 ----------------------------------------------
-- Auteur		: SBR
-- Date			: 05/07/2012
-- Description	: Traitement d'une ligne de fichier EDI pass‚e en paramŠtre
--				  Traitement dynamique par r‚cup‚ration des informations li‚s au Nø de lot d'import pass‚ en paramŠtre
----------------------------------------------
-- SBR 24/09/12 : Nouveau champ EDI_IMPORT_COLONNE.BLN_TRONCATION indique si on accepte des champs dont la taille > taille max par une troncation
----------------------------------------------
CREATE PROCEDURE [dbo].[EDI_TRAITE_LIGNE]
		@ID_LOT_IMPORT  INTEGER,
		@NUM_LIGNE		INTEGER,
		@DATA			VARCHAR(8000)
AS        

SET NOCOUNT ON

DECLARE	@id_table int,
		@cod_table_tampon varchar(50),
		@separateur varchar(5),
		@nb_champs int,
		@num_position int,
		@champ varchar(200),
		@bln_rejet_ligne bit,
		@bln_rejet_champ bit,
		@cod_type_donnee varchar(20),
		@num_taille_max int,
		@cod_colonne varchar(20),
		@lib_colonne varchar(50),
		@cmd1 varchar(2000),
		@cmd2 varchar(2000),
		@quote char(1),
		@bln_tronc bit


select	@id_table = ID_TABLE,
		@cod_table_tampon = COD_TABLE_TAMPON,
		@separateur = CHAR(COD_ASCII_SEPARATEUR)
from	EDI_LOT_IMPORT 
where	ID_LOT_IMPORT = @ID_LOT_IMPORT

select	@nb_champs = MAX(num_position)
from	EDI_IMPORT_COLONNE
where	ID_TABLE = @id_table

select @num_position = 1, @bln_rejet_ligne = 0, @cmd1 = '', @cmd2 = '', @quote = ''''

while @num_position <= @nb_champs
BEGIN
	set @bln_rejet_champ = 0
	
	-- r‚cup‚ration du champ … traiter en fonction de sa position
	select	@champ = dbo.GetDelimData(@DATA, @num_position, @separateur, 'N')
	
	-- r‚cup‚ration des caract‚ristiques de la colonne … alimenter
	select	@cod_type_donnee = cod_type_donnee,
			@num_taille_max = num_taille_max,
			@cod_colonne = cod_colonne,
			@lib_colonne = lib_colonne,
			@bln_tronc = bln_troncation
	from	EDI_IMPORT_COLONNE
	where	ID_TABLE = @id_table
	and		NUM_POSITION = @num_position
	
	-- cont“le de coh‚rence de la valeur
	if @cod_type_donnee = 'CHAR'
	begin
		if @bln_tronc = 0 
			select @bln_rejet_champ = case when LEN(@champ) > @num_taille_max then 1 else 0 end

		set @champ = @quote+left(@champ, @num_taille_max)+@quote -- on entoure le champ texte avec des simples quotes
	end
	
	if @cod_type_donnee = 'INTEGER'
	begin
		if @champ='' set @champ = 'null'
		else
		begin
			if ISNUMERIC(@champ) = 0 set @bln_rejet_champ = 1
			if (LEN(@champ) > @num_taille_max OR dbo.GetNbOccur(@champ, '.')>0 OR dbo.GetNbOccur(@champ, ',')>0) set @bln_rejet_champ = 1
		end
	end
	
	if @cod_type_donnee = 'DATE'
	begin
		if @champ='' set @champ = 'null'
		else
		begin
			if ISDATE(@champ) = 0 set @bln_rejet_champ = 1
			if (LEN(@champ) <> @num_taille_max OR dbo.GetNbOccur(@champ, '/')<>2)  set @bln_rejet_champ = 1
			set @champ = 'convert(datetime,'+@quote+@champ+@quote+',103)'
		end
	end
	
	if @cod_type_donnee = 'FLOAT'
	begin
		if @champ='' set @champ = 'null'
		else
		begin
			if ISNUMERIC(replace(@champ,',','.')) = 0 set @bln_rejet_champ = 1
			if LEN(@champ) > @num_taille_max set @bln_rejet_champ = 1
			set @champ = replace(@champ,',','.')
		end
	end
	

	-- si champ rejet‚ ‚criture d'une ligne dans le fichier de log et rejet de la ligne complŠte
	if 	@bln_rejet_champ = 1 
	begin
		set @bln_rejet_ligne = 1
		
		INSERT INTO EDI_LOG
		(ID_LOT_IMPORT, NUM_LIGNE, LIB_PROBLEME)
		VALUES
		(@ID_LOT_IMPORT, @NUM_LIGNE, @lib_colonne  + ' : [' + ISNULL(dbo.GetDelimData(@DATA, @num_position, @separateur, 'N'), '') + '] ' + 'Format de champ non valide')
	end

	-- composition dynamique de la requˆte insert pour execution ult‚rieure
	select	@cmd1 = @cmd1 + @cod_colonne + ',',
			@cmd2 = @cmd2 + @champ + ','
	
	set @num_position = @num_position + 1
END


-- La ligne peut ˆtre trait‚e, on l'insert dans la table de travail
if @bln_rejet_ligne = 0
begin
	-- construction de la commande insert finale
	select @cmd1 = 'insert into ' + @cod_table_tampon + CHAR(13) +
					'(' + @cmd1 + 'NUM_LIGNE,BLN_REJET,ID_LOT_IMPORT)' + CHAR(13) +
					'values' + CHAR(13) +
					'(' + @cmd2 + cast(@NUM_LIGNE as varchar) + ',0,' + cast(@ID_LOT_IMPORT as varchar) + ')'
	-- trace pour debug
	-- select @cmd1
	exec (@cmd1)
end

GO
         -- =============================================
         -- Author:		Woollams
         -- Create date: 24 janvier 2008
         -- Description:	Lettre de rejet
         -- ---------------------------------------------
         -- DSZ 31/01/2012 13183 REFAIT
         -- =============================================
         -- LDE/OPA 23/05/2014 : #213 En tant qu'utilisateur OPTIFORM, 
         -- lorsque j'‚dite un courrier (PEC, PRO) … destination d'un Adh‚rent ou d'un OF, je veux que, 
         -- l'adresse … afficher dans la zone "correspondance" soit l'adresse TSA propre … ce type de courrier 
         -- si le mode "TSA" s'applique sinon qu'elle soit l'adresse actuelle
         -- =======================================================================================================================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_REJET_ADH_CONTRAT_PRO]
         		@ID_ETABLISSEMENT INT,
         		@ID_BENEFICIAIRE INT,
         		@TYPE_BENEFICIAIRE INT,
         		@ID_ADRESSE INT,
         		@ID_CONTACT INT,
         		@COD_CONTRAT_PRO VARCHAR(10)
         AS
         BEGIN
         
         	/*** Recherche des informations sur l'adherent et l'agence ********************************************/
         	SELECT	ADHERENT.COD_ADHERENT,
         			ADHERENT.LIB_RAISON_SOCIALE
         	INTO	#TEMP_REFERENCE
         
         	FROM	ADHERENT
         			INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         	WHERE	ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT;
         
         
         	/****R‚cup‚ration des infos sur le contrat *********************************/
         	SELECT	ID_CONTRAT_PRO, 
         			COD_CONTRAT_PRO, 
         			LIBL_CONTRAT_PRO, 
         			DAT_DEB_CONTRAT,
         			DAT_FIN_CONTRAT,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU,
         			DAT_RECU_CONTRAT,
         			UTILISATEUR.ID_UTILISATEUR ,
         			UTILISATEUR.LIB_PNM			AS LIB_PRENOM_CHARGE_RELATION,
         			UTILISATEUR.LIB_NOM			AS LIB_NOM_CHARGE_RELATION,
         			UTILISATEUR.EMAIL			AS EMAIL_CHARGE_RELATION,
         			AGENCE.ID_AGENCE,
         			AGENCE.LIB_VILLE  
         						
         	INTO	#TEMP_CONTRAT_PRO
         	FROM	CONTRAT_PRO
         			INNER JOIN SALARIE_PRO ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         			INNER JOIN INDIVIDU ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			LEFT JOIN UTILISATEUR ON CONTRAT_PRO.ID_UTILISATEUR  = UTILISATEUR.ID_UTILISATEUR
         			LEFT JOIN AGENCE ON AGENCE.ID_AGENCE = UTILISATEUR.ID_AGENCE	
         	WHERE	CONTRAT_PRO.COD_CONTRAT_PRO = @COD_CONTRAT_PRO;
         	
         	DECLARE @ID_CPRO INT
         	SELECT @ID_CPRO = ID_CONTRAT_PRO FROM #TEMP_CONTRAT_PRO
         	
         	/****** verifier si un courrier de relance de piŠce a ‚t‚ adress‚ … l'entreprise *****/
         	DECLARE @DAT_EDITION_RELANCE DATETIME
         	SELECT @DAT_EDITION_RELANCE = 
         		DBO.GETMAXDATE(MAX(DAT_RELANCE_ENGAGE_1), 
         						DBO.GETMAXDATE(	MAX(DAT_RELANCE_ENGAGE_2), 
         										MAX(DAT_RELANCE_ENGAGE_3)))
         	FROM ARRIVEE_PIECE_PRO 
         	WHERE (BLN_ACTIF = 0 OR BLN_CONFORME = 0)
         	AND ID_CONTRAT_PRO = @ID_CPRO
         	
         	/*******tableau pieces et motifs*******/
         	SELECT 
         		PIECE_PRO.ID_PIECE_PRO,  
         		PIECE_PRO.LIBL_PIECE_PRO,
         		CASE WHEN ARRIVEE_PIECE_PRO.BLN_ACTIF = 0 THEN 'PiŠce absente' 
         			ELSE MOTIF_NON_CONFORM_PIECE_PRO.LIBL_MOTIF_NON_CONFORM_PIECE_PRO END 
         			AS LIBL_MOTIF_NON_CONFORM_PIECE_PRO,
         		ISNULL(MODULE_PRO.LIBL_MODULE_PRO, '') AS LIBL_MODULE_PRO, 
         		CASE WHEN PIECE_PRO.BLN_MODULE = 1 AND MODULE_PRO.BLN_SUBROGE =1 
         			THEN ETABLISSEMENT_OF.LIB_ENSEIGNE
         			ELSE '' END AS LIB_ENSEIGNE
         	INTO #TEMP_PIECES
         	FROM ARRIVEE_PIECE_PRO
         		LEFT JOIN NR410 ON (ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO)
         		INNER JOIN PIECE_PRO ON (ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO)
         		LEFT JOIN MOTIF_NON_CONFORM_PIECE_PRO ON (MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO = NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO)
         		LEFT JOIN MODULE_PRO ON (MODULE_PRO.ID_MODULE_PRO = ARRIVEE_PIECE_PRO.ID_MODULE_PRO)
         		LEFT JOIN ETABLISSEMENT_OF ON (MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF)
         	WHERE ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO = @ID_CPRO
         	AND (ARRIVEE_PIECE_PRO.BLN_ACTIF=0 OR ARRIVEE_PIECE_PRO.BLN_CONFORME = 0) 
         	AND (PIECE_PRO.BLN_CONTRAT = 1 OR PIECE_PRO.BLN_MODULE =1)  ;
         	
         
         	/*****  Creation du flux XML *********************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_REJET_ADH_CONTRAT_PRO'
         	)
         	/**************************************************************************************************/
         
         	SELECT
         		-- R‚cup‚ration des informations sur le contact
         		dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
         		(
         			SELECT
         					-- Informations de la partie r‚f‚rence
         					ENTETE.COD_ADHERENT,
         					ISNULL(LETTRE.LIB_PRENOM_CHARGE_RELATION, '')	AS LIB_PRENOM_CHARGE_RELATION,
         					ISNULL(LETTRE.LIB_NOM_CHARGE_RELATION, '')		AS LIB_NOM_CHARGE_RELATION,
         					ISNULL(LETTRE.EMAIL_CHARGE_RELATION, '')		AS EMAIL,
         					-- R‚cup‚ration des informations sur l'agence
         					dbo.GetXmlAdrAgenceUtil(LETTRE.ID_UTILISATEUR, (SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE), 1) AS EMETTEUR,
         					LETTRE.NOM_INDIVIDU,
         					LETTRE.PRENOM_INDIVIDU,
         					LETTRE.COD_CONTRAT_PRO,					
         					LETTRE.LIB_VILLE,
         					dbo.GetFullDate(GETDATE()) AS DATE,
         					(
         						SELECT TOP 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
         						FROM CIVILITE
         						FOR XML PATH('POLITESSE_HAUT'), TYPE
         					)
         						
         			FROM	#TEMP_REFERENCE AS ENTETE
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         
         		/******************* Recuperation des informations du corps de la lettre ********************/
         		(
         			SELECT	
         				CASE WHEN @DAT_EDITION_RELANCE IS NOT NULL THEN
         					'AprŠs instruction du dossier et suite au courrier de compl‚tude que nous vous avons adress‚ en date du ' + CONVERT(VARCHAR(10),@DAT_EDITION_RELANCE, 103) +' rest‚ sans r‚ponse de votre part, nous vous retournons le dossier de '+PRENOM_INDIVIDU+' '+ NOM_INDIVIDU+'. En effet, celui-ci ne peut ˆtre recevable en l''‚tat pour le(s) motif(s) suivant(s) : '
         				ELSE
         					'Nous avons bien re‡u en date du '+CONVERT(VARCHAR(10),DAT_RECU_CONTRAT,103)+', le contrat de professionnalisation conclu entre '+PRENOM_INDIVIDU+' '+ NOM_INDIVIDU+' et votre entreprise. AprŠs instruction du dossier, il apparait que celui-ci ne peut ˆtre recevable en l''‚tat pour le(s) motif(s) suivant(s) :'
         				END AS PREMIER_PARAGRAPHE,
         					(
         						SELECT   MOTIF_REJET_PRO.LIBL_MOTIF_REJET_PRO
         
         						FROM	#TEMP_CONTRAT_PRO
         								INNER JOIN MOTIF_REJET_CONTRAT ON #TEMP_CONTRAT_PRO.ID_CONTRAT_PRO = MOTIF_REJET_CONTRAT.ID_CONTRAT_PRO 
         								INNER JOIN MOTIF_REJET_PRO ON MOTIF_REJET_CONTRAT.ID_MOTIF_REJET_PRO = MOTIF_REJET_PRO.ID_MOTIF_REJET_PRO
         						FOR XML RAW('MOTIF_REJET'), ELEMENTS, TYPE, ROOT('MOTIFS')
         					),
         				CONVERT(VARCHAR(10),DATEADD(D,7,GETDATE()),103) AS DATE_POUR_QUAND,
         				(SELECT LIBL_PIECE_PRO,
         					(SELECT										
         						LIBL_MOTIF_NON_CONFORM_PIECE_PRO
         						FROM #TEMP_PIECES AS MOTIFS_PIECES
         						WHERE PIECES.ID_PIECE_PRO = MOTIFS_PIECES.ID_PIECE_PRO
         						FOR XML AUTO,ELEMENTS, TYPE
         					),
         					LIBL_MODULE_PRO,
         					LIB_ENSEIGNE
         					FROM #TEMP_PIECES AS PIECES	
         					GROUP BY ID_PIECE_PRO, LIBL_PIECE_PRO, LIBL_MODULE_PRO, LIB_ENSEIGNE
         					FOR XML AUTO,ELEMENTS, TYPE
         				)
         				
         				FROM	#TEMP_CONTRAT_PRO AS CORPS						
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			(
         				SELECT	TOP 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1) AS POLITESSE_BAS
         				FROM	CIVILITE
         				FOR XML RAW(''), ELEMENTS,TYPE
         			),
         			/******************* Recuperation des informations de la signature********************/
         			(
         				SELECT	SIGNATURE.LIB_PRENOM_CHARGE_RELATION as LIB_PRENOM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CHARGE_RELATION as LIB_NOM_CONSEILLER
         				FROM	#TEMP_CONTRAT_PRO as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         			/******************************************************************************************/
         
         				
         	FROM	#TEMP_CONTRAT_PRO AS LETTRE
         	FOR XML AUTO, ELEMENTS
         END

GO

CREATE PROCEDURE [dbo].[INS_PLAN_FI_US_ENGAGE]  
          @DAT_PLAN_FINANCEMENT_US DATETIME,
          @MNT_PLAN_FINANCEMENT_US DECIMAL(18,2),
          @BLN_ACTIF     TINYINT,
          @BLN_DECOUVERT    TINYINT,
          @COM_PLAN_FINANCEMENT_US VARCHAR(255),
          @ID_UNITE_STAGIAIRE   INT,
          @ID_TYPE_FINANCEMENT  INT,
          @ID_ENVELOPPE    INT,
          @ID_POSTE_COUT_ENGAGE  INT,
          @ID_POSTE_COUT_REGLE  INT,
          @BLN_ATTENTE_FONDS   TINYINT,
          @ID_PLAN_FINANCEMENT_US  INT OUTPUT
         AS
         -- ==========================================================================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- ==========================================================================================  
         -- DSZ 24/01/2014 : 15636: SBR - ne pas generer des PFUS … 0 sans aucune source de financement.
         -- ==========================================================================================
         -- HBO : #675 Suppression du paramŠtre ID_PUBLIC_FAF
         -- ==========================================================================================
         -- OPA 22/04/2015 : #821 En tant que DBA, je souhaite que tous les PFUS cr‚‚s ne possŠdent
         --  plus de cod_pfus
         -- ==========================================================================================
         BEGIN
          IF (@ID_TYPE_FINANCEMENT IS NOT NULL OR @ID_ENVELOPPE IS NOT NULL)
          BEGIN
           INSERT INTO PLAN_FINANCEMENT_US
           (
            DAT_PLAN_FINANCEMENT_US,
            MNT_PLAN_FINANCEMENT_US,
            BLN_ACTIF,
            BLN_DECOUVERT,
            COM_PLAN_FINANCEMENT_US,
            ID_UNITE_STAGIAIRE,
            ID_TYPE_FINANCEMENT,
            ID_ENVELOPPE,
            ID_POSTE_COUT_ENGAGE,
            ID_POSTE_COUT_REGLE,
            BLN_ATTENTE_FONDS
           )
           VALUES
           (
            @DAT_PLAN_FINANCEMENT_US,
            @MNT_PLAN_FINANCEMENT_US,
            @BLN_ACTIF,
            @BLN_DECOUVERT,
            @COM_PLAN_FINANCEMENT_US ,
            @ID_UNITE_STAGIAIRE,
            @ID_TYPE_FINANCEMENT ,
            @ID_ENVELOPPE ,
            @ID_POSTE_COUT_ENGAGE ,
            @ID_POSTE_COUT_REGLE,
            @BLN_ATTENTE_FONDS
           )
         
           SELECT @@IDENTITY AS ID
         
           SET @ID_PLAN_FINANCEMENT_US = @@IDENTITY
          END
         END

GO

 CREATE PROCEDURE [dbo].[UPD_STAGIAIRES_MNT_CHIFFRAGE]
            @ID_UNITE_STAGIAIRE int,
            @MONTANT decimal(18,2),
            @ID_POSTE_COUT_ENGAGE int,
            @ID_TYPE int -- <0 pour type_financement
             -- >0 pour ID Enveloppe
         AS
         -- =============================================
         -- Author  : D.Szeliga
         -- Modif. date : 15/04/2008
         -- Description : Updater le COM_PLAN_FINANCEMENT_US en meme temps que le montant
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- DSZ 28/10/2104 : US618 : la reforme 2014, les comptes dynamiques
         -- =============================================
         -- DSZ 24/11/2104 : US661 : la reforme 2014, suppression ID_PUBLIC FAF
         -- =============================================
         BEGIN
         
          DECLARE @@COMMENT_CONST varchar(20) = 'Saisie … la main'
         
         
          IF (@ID_TYPE < 0)
          BEGIN
         
           IF not exists (SELECT 1
               FROM PLAN_FINANCEMENT_US
               WHERE ID_TYPE_FINANCEMENT = - @ID_TYPE
               AND ID_ENVELOPPE IS NULL
               AND ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
               AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE)
           BEGIN  
           ------------- insert type_financement
             INSERT INTO PLAN_FINANCEMENT_US
           (DAT_PLAN_FINANCEMENT_US, MNT_PLAN_FINANCEMENT_US,
           BLN_ACTIF, ID_UNITE_STAGIAIRE, 
           ID_TYPE_FINANCEMENT,
           ID_ENVELOPPE, ID_POSTE_COUT_ENGAGE, BLN_ATTENTE_FONDS, COM_PLAN_FINANCEMENT_US)
             VALUES
           (GETDATE(), @MONTANT, 
           1, @ID_UNITE_STAGIAIRE,
           - @ID_TYPE, 
           NULL, @ID_POSTE_COUT_ENGAGE, 1, @@COMMENT_CONST)
         
           END
           ELSE
           BEGIN
          ------------- update type_financement 
             UPDATE PLAN_FINANCEMENT_US
             SET 
            MNT_PLAN_FINANCEMENT_US = @MONTANT,
            COM_PLAN_FINANCEMENT_US = @@COMMENT_CONST
             WHERE 
              ID_TYPE_FINANCEMENT = - @ID_TYPE
              AND ID_ENVELOPPE IS NULL
              AND ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
              AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE
           END
           
          END
          ELSE --IF (@ID_TYPE > 0)
          BEGIN
         
            IF not exists(SELECT 1
            FROM PLAN_FINANCEMENT_US
            WHERE ID_TYPE_FINANCEMENT IS NULL 
            AND ID_ENVELOPPE = @ID_TYPE
            AND ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
            AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE)
            BEGIN
            ------------- insert enveloppe
             INSERT INTO PLAN_FINANCEMENT_US
           (DAT_PLAN_FINANCEMENT_US, MNT_PLAN_FINANCEMENT_US,
           BLN_ACTIF, ID_UNITE_STAGIAIRE, ID_TYPE_FINANCEMENT,
           ID_ENVELOPPE, ID_POSTE_COUT_ENGAGE, BLN_ATTENTE_FONDS, COM_PLAN_FINANCEMENT_US)
             VALUES
           (GETDATE(), @MONTANT, 
           1, @ID_UNITE_STAGIAIRE, NULL,
           @ID_TYPE, @ID_POSTE_COUT_ENGAGE, 1, @@COMMENT_CONST)
         
           END
           ELSE
           BEGIN
          ------------- update enveloppe
             UPDATE PLAN_FINANCEMENT_US
             SET 
            MNT_PLAN_FINANCEMENT_US = @MONTANT,
            COM_PLAN_FINANCEMENT_US = @@COMMENT_CONST 
             WHERE 
              ID_TYPE_FINANCEMENT IS NULL 
              AND ID_ENVELOPPE = @ID_TYPE
              AND ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
              AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE
           END  
          END
         END

GO
 --== MODIF ==========================================================
         -- Author		: MB
         -- Modified date: 04/04/2008
         -- comment		: Ajout du parametre @NBR et de la possibilite de compter les occurences ramenees
         --== MODIF ==========================================================
         -- Author		: AMA
         -- Modified date: 14/04/2008
         -- comment		: Changement de taille de CODE_SESSION_PEC dans TEMP_DESTINATAIRES
         --=============================================================
         -- Author		:	AMA
         -- Date			: 20/05/08
         -- Description	: Remplacement du paramŠtre d'entr‚e de la proc‚dure @ID_AGENCE par @ID_CR (id du charg‚ de relation)
         --				  R‚sultat renvoy‚ = les ‚tablissements du CR pass‚ en paramŠtre de la proc‚dure
         -- =============================================
         -- Author		: SBR
         -- Date			: 29/05/08
         -- Description	: Gestion particuliŠre pour les actions collectives: on filtre sur le CM renseign‚ au niveau de l'action
         --=============================================================
         -- Author		: SBR
         -- Date			: 16/07/08
         -- Description	: le filtre des potentiels se fait sur l'utilisateur ayant r‚alis‚ le BAE (et plus le CR de l'‚tablissement)
         -- =============================================
         -- Author		: ASD/TLE
         -- Date			: 22/05/13
         -- Description	: modification jointure + optimisations
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_GRP_ETAB_RELANCE_PIECE_REGL_ADH]
         	@ID_USER	INT,
         	@NBR		INT = NULL OUTPUT
         
         AS
         
         BEGIN
         	
         CREATE TABLE #TEMP_DESTINATAIRES (
         				ID_MODULE_PEC INT,
         				ID_SESSION_PEC INT,
         				COD_SESSION_PEC VARCHAR(17),				
         				ID_ETABLISSEMENT INT,
         				ID_ADHERENT INT,
         				BLN_ACTIF TINYINT,
         				ID_ARRIVEE_PIECE_PEC INT,
         				DAT_RELANCE_REGLE_1 DATETIME,
         				DAT_RELANCE_REGLE_2 DATETIME,
         				DAT_RELANCE_REGLE_3 DATETIME
         			);
         
         SELECT  DISTINCT ACTION_PEC.ID_ACTION_PEC,
         				 MODULE_PEC.ID_MODULE_PEC,
         				 SESSION_PEC.ID_SESSION_PEC,
         				 SESSION_PEC.COD_SESSION_PEC,
         				 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         				 ISNULL(POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE, 0) AS BLN_FACTURE_DIRECTE,
         				 STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         				 ETABLISSEMENT.ID_ETABLISSEMENT,
         				 ADHERENT.ID_ADHERENT 
         
         INTO	#TEMP_SESSIONS
         
         FROM	ACTION_PEC 
         JOIN	MODULE_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         JOIN	SESSION_PEC ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC 
         left JOIN	POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC and POSTE_COUT_REGLE.BLN_ACTIF=1
         JOIN	STAGIAIRE_PEC ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         JOIN	ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         JOIN	ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         WHERE	ACTION_PEC.BLN_ACTIF = 1
         AND		ACTION_PEC.DAT_CLOTURE IS NULL
         AND		MODULE_PEC.BLN_ACTIF = 1
         AND		SESSION_PEC.BLN_ACTIF = 1
         AND		(
         				(MODULE_PEC.BLN_OK_PIECE = 0) 
         			OR 
         				(POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE is null or POSTE_COUT_REGLE.BLN_OK_PIECE = 0)
         		)
         AND		coalesce(ACTION_PEC.ID_UTILISATEUR_BAE, @ID_USER) = @ID_USER
         
         ORDER BY ACTION_PEC.ID_ACTION_PEC, MODULE_PEC.ID_MODULE_PEC, POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         
         	/**** Liste des arriv‚es piŠces li‚es aux postes cout r‚gl‚s ****************************************************************************************************/
         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT,
         				     ADHERENT.ID_ADHERENT,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         	FROM    #TEMP_SESSIONS 
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON		#TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         	AND		ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC
         	JOIN	PIECE_PEC 
         	ON		ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         	JOIN	POSTE_COUT_REGLE 
         	ON		POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC										
         	JOIN	ADHERENT 
         	ON		#TEMP_SESSIONS.ID_ADHERENT = ADHERENT.ID_ADHERENT
         
         	WHERE	(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         	AND		(#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 0)
         	AND		(PIECE_PEC.BLN_ACTIF = 1)
         	AND		((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND		(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_ADH=1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)
         	
         
         	/**** Liste des arrives piŠces lies aux modules **********************************************************************************************************/
         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT,
         				     ADHERENT.ID_ADHERENT,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         	FROM    #TEMP_SESSIONS
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON		#TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         	JOIN	PIECE_PEC 
         	ON		ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC AND (PIECE_PEC.BLN_STAGIAIRE = 0)
         	JOIN	ADHERENT 
         	ON		#TEMP_SESSIONS.ID_ADHERENT = ADHERENT.ID_ADHERENT
         				
         	WHERE	(PIECE_PEC.BLN_MODULE = 1)
         	AND		(PIECE_PEC.BLN_ACTIF = 1)
         	AND		((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND		(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_ADH=1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)
         	
         
         	/**** Liste des arrives pices lies aux sessions **********************************************************************************************************/
         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT,
         				     ADHERENT.ID_ADHERENT,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         	FROM    #TEMP_SESSIONS
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON		#TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         	AND		(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC)
         	JOIN	PIECE_PEC 
         	ON		ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC 
         	JOIN	ADHERENT 
         	ON		#TEMP_SESSIONS.ID_ADHERENT = ADHERENT.ID_ADHERENT
         
         	WHERE	(PIECE_PEC.BLN_SESSION = 1)
         	AND		(PIECE_PEC.BLN_ACTIF = 1)
         	AND		((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND		(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_ADH=1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)
         	
         
         	/**** Liste des arrives piŠces lies aux stagiaires ********************************************************************************************************/
         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT,
         				     #TEMP_SESSIONS.ID_ADHERENT,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         	FROM	#TEMP_SESSIONS 
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON		#TEMP_SESSIONS.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         	AND		(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC)
         	JOIN	PIECE_PEC 
         	ON		ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         	JOIN	STAGIAIRE_PEC 
         	ON		STAGIAIRE_PEC.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         
         	WHERE	(PIECE_PEC.BLN_STAGIAIRE = 1)
         	AND		(PIECE_PEC.BLN_ACTIF = 1)
         	AND		((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND		(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_ADH=1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)
         
         
         	/**** Liste des arrives pices lies aux adherents *******************************************************************************************************/
         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT,
         				     #TEMP_SESSIONS.ID_ADHERENT,
                              ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         	FROM	#TEMP_SESSIONS  
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON		#TEMP_SESSIONS.ID_ADHERENT = ARRIVEE_PIECE_PEC.ID_ADHERENT
         	AND		(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC)
         	JOIN	PIECE_PEC 
         	ON		ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         
         	WHERE	(PIECE_PEC.BLN_ADHERENT = 1)
         	AND		(PIECE_PEC.BLN_ACTIF = 1)
         	AND		((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND		(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_ADH=1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)
         
         
         	SELECT DISTINCT 
         			#TEMP_DESTINATAIRES.ID_ETABLISSEMENT, 
         			#TEMP_DESTINATAIRES.ID_ADHERENT,
         			#TEMP_DESTINATAIRES.COD_SESSION_PEC as _SESSION_PEC
         	INTO	#TMP1
         	FROM	#TEMP_DESTINATAIRES
         	CROSS JOIN 
         			PARAMETRES
         	WHERE	(((#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 IS NULL) 
         	AND		(#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NULL) 
         	AND		(#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL))
         	OR		(
         			(#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 IS NOT NULL)
         			AND (GETDATE()-#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         			AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL)
         			)
         	OR		(
         			(#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NOT NULL)
         			AND (GETDATE()-#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         			AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL))
         			)
         	ORDER BY #TEMP_DESTINATAIRES.ID_ETABLISSEMENT, #TEMP_DESTINATAIRES.COD_SESSION_PEC
         
         	IF @NBR IS NULL
         	BEGIN
         		SELECT  *  
         		FROM	#TMP1
         	END
         	ELSE
         	BEGIN
         		SELECT	@NBR = COUNT(*) 
         		FROM	#TMP1 , NR67bis
         		WHERE	NR67.ID_ADHERENT = #TMP1.ID_ADHERENT
         		AND		NR67.ID_DOCUMENT = 27
         	END
         END
         

GO
 -- =============================================
         -- Author		: XX
         -- Create date	: XX XXXX 2007
         -- Description	: Cr‚ation
         -- =============================================
         -- Author		: SV
         -- Create date	: 29 ao–t 2007
         -- Description	: Modification du type du paramŠtre d'entr‚e en varchar(8000) … la place de varchar(500) pour permettre une liste plus longue (jusqu'… 8000 caractŠres)
         --				  Modification du nom du paramŠtre car ce sont des codes qui sont envoy‚s et non pas des identifiants
         --				  Modification de la requˆte de mise … jour de la date de rejet adh‚rent pour que ce soit les codes modules qui soient utilis‚s comme filtre et non pas les identifiants
         -- =============================================
         --	06/03/09 par SBR - La liste pass‚e en paramŠtre contient les id_module_pec et non les cod_module_pec comme le nom le laisse … penser!
         --					   La mise … jour ‚tait effectu‚e sur le cod_module_pec
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_MODULE_DATE_REJET_LETTRE_ADH]
         	@LISTE__COD_MODULE_PEC varchar(8000)	-- List of ID_MODULE separated with ',' without spaces - i.e.: 1,2,3,4,5,6
         AS
         
         BEGIN
         
         	DECLARE @Item varchar(10);
         	-- Create a temporary table which contains IDs
         	CREATE TABLE #List(Item varchar(10) collate French_CI_AI)
         	
         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@LISTE__COD_MODULE_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item= cast(RTRIM(LTRIM(SUBSTRING(@LISTE__COD_MODULE_PEC,1,CHARINDEX(@Delimiter,@LISTE__COD_MODULE_PEC,0)-1))) as varchar(10)), 
         			@LISTE__COD_MODULE_PEC=RTRIM(LTRIM(SUBSTRING(@LISTE__COD_MODULE_PEC,CHARINDEX(@Delimiter,@LISTE__COD_MODULE_PEC,0)+1,LEN(@LISTE__COD_MODULE_PEC))))
         
         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END
         
         	IF LEN(@LISTE__COD_MODULE_PEC) > 0
         		INSERT INTO #List SELECT cast(@LISTE__COD_MODULE_PEC as varchar(10)) -- Put the last item in
         
         	--Mise … jour des dates de rejet
         	UPDATE
         		MODULE_PEC
         	SET
         		DAT_LETTRE_REJET_ADH = GETDATE()
         	WHERE
         		-- correction bug du 06/03/09 par SBR
         		ID_MODULE_PEC IN (SELECT Item FROM #List)
         END
         
GO
 CREATE PROCEDURE [dbo].[UPD_SOUS_TYPE_COUT_DESENGAGEMENT]
         -- =================================================================================================
         -- DSZ 08/03/10 ANO 12310 
         -- "Le desengagement d'un PCE ne fait pas regresser le PCE en Pb de ventilation.
         -- On peut donc reengager sans avoir reeffectuer le chiffrage."
         -- -> BLN_OK_FINANCEMENT = 0 pour le nouveau pce cr‚e apr‚s desengagement
         -- =================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =================================================================================================
         -- DSZ 24/01/2014 : 15636: SBR - ne pas generer des PFUS … 0 sans aucune source de financement.
         -- =================================================================================================
         -- HBO - OPA - LDE - 20140801 #148C
         -- =================================================================================================
         -- HBO - 20140804 #141
         -- =================================================================================================
         -- OPA 21/11/2014 : #665 PEC2 - UPD_SOUS_TYPE_COUT_DESENGAGEMENT V1 (Suppression de ID_PUBLIC_FAF)
         -- =================================================================================================
          @ID_POSTE_COUT int,
          @ID_ACTION int,
          @BLN_SELECTION int,
          @TIME_STAMP TIMESTAMP,
          @UserId  INT
         AS  
         BEGIN
          DECLARE
           @MNT DECIMAL(18,2),
           @ID_POSTE_COUT_NEGATIVE INT,
           @ID_POSTE_COUT_POSITIVE INT,
           @ID_ENGAGEMENT_AUX INT,
           @RETURN INT
         
          IF (@BLN_SELECTION = 1)
          BEGIN
           SELECT @MNT = MNT_ENGAGE_HT FROM POSTE_COUT_ENGAGE WHERE ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
           
           -- DISENGAGE THE POSTE COST  
           UPDATE
            POSTE_COUT_ENGAGE
           SET
            DAT_DESENGAGEMENT = GETDATE(),
            DAT_MODIF = GETDATE()
           WHERE 
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
            AND TIME_STAMP = @TIME_STAMP
         
           IF @@ROWCOUNT = 0   
           BEGIN  
              IF EXISTS(SELECT * FROM POSTE_COUT_ENGAGE WHERE ID_POSTE_COUT_ENGAGE  = @ID_POSTE_COUT)      
              BEGIN  
              /* Problme de Concurrence d'accs */  
              RAISERROR('Problme de Concurrence d''accs', 16, 1)
              RETURN -1  
              END     
           END
         
           INSERT INTO
            POSTE_COUT_ENGAGE
            (
             COD_POSTE_COUT_ENGAGE,
             MNT_ENGAGE_HT,
             ID_SOUS_TYPE_COUT,
             ID_MODULE_PEC,
             MNT_PREVISIONNEL_HT,
             DAT_DESENGAGEMENT,
             ID_ENGAGEMENT,
             BLN_OK_FINANCEMENT,
             DAT_CREATION
            )
           SELECT
            0, 
            - MNT_ENGAGE_HT,
            ID_SOUS_TYPE_COUT,
            ID_MODULE_PEC,
            - MNT_PREVISIONNEL_HT,
            DAT_DESENGAGEMENT,
            ID_ENGAGEMENT,
            BLN_OK_FINANCEMENT,
            getdate()
           FROM
            POSTE_COUT_ENGAGE
           WHERE
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
         
           UPDATE
            POSTE_COUT_ENGAGE
           SET
            COD_POSTE_COUT_ENGAGE = @@IDENTITY
           WHERE
            ID_POSTE_COUT_ENGAGE = @@IDENTITY
           
           SET @ID_POSTE_COUT_NEGATIVE = @@IDENTITY
         
           -- ENGAGEMENT
           INSERT INTO
            ENGAGEMENT
            (
             COD_ENGAGEMENT,
             DAT_BAE,
             MNT_ENGAGE_HT,
             BLN_ACTIF,
             ID_ACTION_PEC,
             ID_TYPE_ENGAGEMENT
            )
            VALUES
            (
             0,
             GETDATE(),
             -@MNT,
             1,
             @ID_ACTION,
             2
            )
         
           SET @ID_ENGAGEMENT_AUX = @@IDENTITY
         
           UPDATE
            ENGAGEMENT
           SET
            COD_ENGAGEMENT = @ID_ENGAGEMENT_AUX
           WHERE
            ID_ENGAGEMENT = @ID_ENGAGEMENT_AUX
         
           UPDATE
            POSTE_COUT_ENGAGE
           SET
            ID_ENGAGEMENT = @ID_ENGAGEMENT_AUX
           WHERE 
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_NEGATIVE
         
           -- POSTE COUT ENGAGE
           INSERT INTO
            POSTE_COUT_ENGAGE
            (
             COD_POSTE_COUT_ENGAGE,
             MNT_ENGAGE_HT,
             ID_SOUS_TYPE_COUT,
             ID_MODULE_PEC,
             MNT_PREVISIONNEL_HT,
             DAT_DESENGAGEMENT,
             BLN_OK_FINANCEMENT,
             DAT_CREATION
            )
           SELECT
            0,
            MNT_ENGAGE_HT,
            ID_SOUS_TYPE_COUT,
            ID_MODULE_PEC,
            MNT_PREVISIONNEL_HT,
            NULL,
            0,--BLN_OK_FINANCEMENT --DZ 08/03/2010 ANO 12310
            getdate()
           FROM
            POSTE_COUT_ENGAGE
           WHERE
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
         
           UPDATE
            POSTE_COUT_ENGAGE
           SET
            COD_POSTE_COUT_ENGAGE = @@IDENTITY
           WHERE
            ID_POSTE_COUT_ENGAGE = @@IDENTITY
           
           SET @ID_POSTE_COUT_POSITIVE = @@IDENTITY
         
           -- PLAN FINANCEMENT US
           INSERT INTO
            PLAN_FINANCEMENT_US
            (
             DAT_PLAN_FINANCEMENT_US,
             MNT_PLAN_FINANCEMENT_US,
             BLN_ACTIF,
             BLN_DECOUVERT,
             ID_UNITE_STAGIAIRE,
             ID_TYPE_FINANCEMENT,
             ID_ENVELOPPE,
             ID_POSTE_COUT_ENGAGE,
             ID_POSTE_COUT_REGLE,
             BLN_ATTENTE_FONDS
            )
           SELECT
            DAT_PLAN_FINANCEMENT_US,
            - MNT_PLAN_FINANCEMENT_US,
            BLN_ACTIF,
            BLN_DECOUVERT,
            ID_UNITE_STAGIAIRE,
            ID_TYPE_FINANCEMENT,
            ID_ENVELOPPE,
            @ID_POSTE_COUT_NEGATIVE,
            ID_POSTE_COUT_REGLE,
            BLN_ATTENTE_FONDS
           FROM
            PLAN_FINANCEMENT_US
           WHERE
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
            AND
            (
             ID_ENVELOPPE IS NOT NULL
             OR ID_TYPE_FINANCEMENT IS NOT NULL
            ) 
           
           INSERT INTO
            PLAN_FINANCEMENT_US
            (
             DAT_PLAN_FINANCEMENT_US,
             MNT_PLAN_FINANCEMENT_US,
             BLN_ACTIF,
             BLN_DECOUVERT,
             ID_UNITE_STAGIAIRE,
             ID_TYPE_FINANCEMENT,
             ID_ENVELOPPE,
             ID_POSTE_COUT_ENGAGE,
             ID_POSTE_COUT_REGLE,
             BLN_ATTENTE_FONDS
            )
           SELECT
            DAT_PLAN_FINANCEMENT_US,
            MNT_PLAN_FINANCEMENT_US,
            BLN_ACTIF,
            BLN_DECOUVERT,
            ID_UNITE_STAGIAIRE,
            ID_TYPE_FINANCEMENT,
            ID_ENVELOPPE,
            @ID_POSTE_COUT_POSITIVE,
            ID_POSTE_COUT_REGLE,
            BLN_ATTENTE_FONDS
           FROM
            PLAN_FINANCEMENT_US 
           WHERE
            ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT
            AND
            (
             ID_ENVELOPPE IS NOT NULL
             OR ID_TYPE_FINANCEMENT IS NOT NULL
            )
         
           -- #141 : Recablage Desengagement
           DECLARE
            @EventTypeId INT,
            @EventName VARCHAR(50),
            @EventDate DATETIME,
            @EventComment VARCHAR(7600)
           
           SELECT
            @EventTypeId = ID_TYPE_EVENEMENT,
            @EventName = LIBL_TYPE_EVENEMENT
           FROM
            TYPE_EVENEMENT
           WHERE
            COD_TYPE_EVENEMENT = 'DESENG'
         
           SET @EventDate = GETDATE()
           SET @EventComment = 'Origine : D‚sengagement PEC OPTIFORM'
         
           EXEC @RETURN = MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
            @EventName,
            @EventDate,
            @EventTypeId,
            @ID_POSTE_COUT,
            NULL,
            @UserId,
            @EventComment
         
          END
         END

GO

         -- =======================================================================================================================================
         -- Author		: WOOLLAMS
         -- Create date	: 23 janvier 2008
         -- Description	: Lettre de relance d'engagement pour l'adh‚rent
         -- Modif du 28/11/08 par SBRU - adaptation au gabarit C2P
         -- Modif du 20/09/12 par DSZ - 13697 : num tel dynamique
         -- =======================================================================================================================================
         -- LDE/OPA 23/05/2014 : #213 En tant qu'utilisateur OPTIFORM, 
         -- lorsque j'‚dite un courrier (PEC, PRO) … destination d'un Adh‚rent ou d'un OF, je veux que, 
         -- l'adresse … afficher dans la zone "correspondance" soit l'adresse TSA propre … ce type de courrier 
         -- si le mode "TSA" s'applique sinon qu'elle soit l'adresse actuelle
         -- =======================================================================================================================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_RELANCE_ENGAGEMENT_CONTRAT_PRO_ADH]
         	@ID_ETABLISSEMENT	INT,
         	@ID_BENEFICIAIRE	INT,
         	@TYPE_BENEFICIAIRE	INT,
         	@ID_ADRESSE			INT,
         	@ID_CONTACT			INT,
         	@COD_CONTRAT_PRO	VARCHAR(10)
         AS
         BEGIN
         
         	DECLARE @relance INT
         	SET @relance = 1	
         	
         	-- Contact principal par d‚faut mais pas de "."
         	IF @ID_CONTACT IS NULL
         	SELECT @ID_CONTACT = NR31.ID_CONTACT
         	FROM NR31
         		INNER JOIN CONTACT ON CONTACT.ID_CONTACT = NR31.ID_CONTACT
         	WHERE BLN_PRINCIPAL = 1
         		AND BLN_ACTIF = 1
         		AND ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         		AND CONTACT.LIB_NOM_CONTACT <> '.';
         
         	
         	SELECT	ADHERENT.COD_ADHERENT,
         			ETABLISSEMENT.NUM_SIRET,
         			CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         			CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         			CR.ID_UTILISATEUR	as ID_UTIL,
         			CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         			CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         			CR.LIB_VILLE,
         			CR.EMAIL			as EMAIL_CHARGE_RELATION
         	INTO	#TEMP_REFERENCE
         	FROM	ADHERENT
         	JOIN	ETABLISSEMENT	
         	ON		ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	JOIN	ADRESSE
         	ON		ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         	LEFT JOIN
         			UTILISATEUR CR -- charg‚ de relation
         	ON		ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR
         	LEFT JOIN
         			UTILISATEUR CM -- charg‚ de mission
         	ON		ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR
         	WHERE	ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT;
         
         	
         	SELECT	CONTRAT_PRO.ID_CONTRAT_PRO,
         			CONTRAT_PRO.COD_CONTRAT_PRO,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_DEB_CONTRAT, 3) AS DAT_DEBUT,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_FIN_CONTRAT, 3) AS DAT_FIN,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU,
         			INDIVIDU.ID_INDIVIDU,
         			INDIVIDU.ID_NATIONALITE,
         			CONTRAT_PRO.LIB_LIEU_FORMATION,
         			CONTRAT_PRO.ID_SALARIE_PRO
         	INTO	#TMP_CONTRAT_PRO 
         	FROM	CONTRAT_PRO
         	JOIN	SALARIE_PRO 
         	ON		CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         	JOIN	INDIVIDU 
         	ON		SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         	WHERE   CONTRAT_PRO.COD_CONTRAT_PRO = @COD_CONTRAT_PRO;
         	
         	SELECT DISTINCT	PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3
         	INTO	#TMP_PIECES_CONTRAT_PRO
         	FROM	#TMP_CONTRAT_PRO
         	JOIN	ARRIVEE_PIECE_PRO 
         	ON		#TMP_CONTRAT_PRO.ID_CONTRAT_PRO = ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO 
         	JOIN	PIECE_PRO 
         	ON		ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO
         	AND		PIECE_PRO.BLN_CONTRAT = 1 
         	AND		PIECE_PRO.BLN_ACTIF=1 
         	AND		PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1
         	JOIN	SALARIE_PRO 
         	ON		#TMP_CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         	JOIN	INDIVIDU 
         	ON		SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         	WHERE	(
         				(PIECE_PRO.COD_PIECE_PRO  = 'PERMIS' AND INDIVIDU.ID_NATIONALITE = 14) -- U.E.
         				OR
         				(PIECE_PRO.COD_PIECE_PRO <> 'PERMIS')
         			 );
         	
         	SELECT	DISTINCT PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3,
         			MODULE_PRO.COD_MODULE_PRO, 
         			MODULE_PRO.LIBL_MODULE_PRO,
         			MODULE_PRO.BLN_SUBROGE,
         			CONVERT(VARCHAR(8),MODULE_PRO.DAT_DEBUT, 3) AS DAT_DEBUT,
         			dbo.GetFrenchCurrencyFormat(CAST(MODULE_PRO.NB_UNITE_TOTALE as MONEY))  AS NB_UNITE_FORMATION,
                     coalesce(ORGANISME_FORMATION.LIB_RAISON_SOCIALE, '') AS LIB_RAISON_SOCIALE
         	INTO	#TMP_PIECES_MODULE_PRO
         	FROM	#TMP_CONTRAT_PRO
         	JOIN	MODULE_PRO 
         	ON		#TMP_CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         	AND		MODULE_PRO.BLN_SUBROGE = 0 
         	LEFT JOIN
         			ETABLISSEMENT_OF 
         	ON		MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         	LEFT JOIN
         			ORGANISME_FORMATION 
         	ON		ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         	JOIN	ARRIVEE_PIECE_PRO 
         	ON		MODULE_PRO.ID_MODULE_PRO = ARRIVEE_PIECE_PRO.ID_MODULE_PRO 
         	JOIN	PIECE_PRO
         	ON		ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO  
         	WHERE	MODULE_PRO.BLN_OK_PIECE = 0 
         	AND		PIECE_PRO.BLN_MODULE = 1 
         	AND		PIECE_PRO.BLN_CONTRAT = 0 
         	AND		PIECE_PRO.BLN_ACTIF = 1 
         	AND		PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1
         	AND		(ARRIVEE_PIECE_PRO.BLN_ACTIF = 0 OR ARRIVEE_PIECE_PRO.BLN_CONFORME = 0);
         
         		
         	SELECT	@RELANCE =	CASE 
         							WHEN DAT_RELANCE_ENGAGE_2 IS NOT NULL THEN 3
         							WHEN DAT_RELANCE_ENGAGE_1 IS NOT NULL THEN 2
         							ELSE 1
         						END
         	FROM	#TMP_PIECES_CONTRAT_PRO;
         
         	
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_RELANCE_ENGAGEMENT_CONTRAT_PRO_ADH'
         	)
         	
         			
         	SELECT
         			-- R‚cup‚ration des informations sur le contact et le b‚n‚ficiaire
         			dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,
         			(
         				SELECT	              	
         					ISNULL(COD_ADHERENT, '')				AS COD_ADH,
         					ISNULL(LIB_PRENOM_CHARGE_RELATION, '')	AS LIB_PRENOM_CHARGE_RELATION,
         					ISNULL(LIB_NOM_CHARGE_RELATION, '')		AS LIB_NOM_CHARGE_RELATION,
         					ISNULL(EMAIL_CHARGE_RELATION, '')		AS EMAIL,
         
         					-- R‚cup‚ration des informations sur l'‚metteur
         					dbo.GetXmlAdrUtilAvecTel(ENTETE.ID_UTIL, (SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE), 1) AS EMETTEUR,
         
         					(
         					SELECT @relance
         					FOR XML RAW('NUM_RELANCE'), ELEMENTS, TYPE
         					),
         
         					-- r‚f‚rence du contrat pro
         					(
         						SELECT	#TMP_CONTRAT_PRO.COD_CONTRAT_PRO
         						FROM	#TMP_CONTRAT_PRO
         						FOR XML PATH(''), TYPE 
         					),
         					ENTETE.NUM_SIRET AS SIRET,
         					RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         					dbo.GetFullDate(getDate()) AS DATE,				
         					(
         						SELECT	TOP 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         						FROM CIVILITE
         						FOR XML PATH('POLITESSE_HAUT'), TYPE
         					)
         				FROM #TEMP_REFERENCE AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				SELECT	CORPS.COD_CONTRAT_PRO,
         						CORPS.PRENOM_INDIVIDU,
         						CORPS.NOM_INDIVIDU,
         						CORPS.DAT_DEBUT,
         						CORPS.DAT_FIN,
         						CORPS.LIB_LIEU_FORMATION,
         						CASE WHEN @relance = 3 THEN(
         							SELECT 'Sans r‚ponse de votre part sous quinzaine nous cl“turerons ce dossier.'
         							FOR XML PATH('PREVENTION'), TYPE 
         						)END ,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_PIECES_CONTRAT_PRO) > 0) THEN (
         							SELECT 
         								(
         									SELECT	DISTINCT #TMP_PIECES_CONTRAT_PRO.LIBC_PIECE_PRO AS LIB_PIECE_PRO_MANQUANTE
         									FROM	#TMP_PIECES_CONTRAT_PRO
         									WHERE	#TMP_PIECES_CONTRAT_PRO.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT	DISTINCT #TMP_PIECES_CONTRAT_PRO.LIBL_PIECE_PRO AS LIB_PIECE_PRO_NON_CONFORME,
         											MOTIF_NON_CONFORM_PIECE_PRO.LIBL_MOTIF_NON_CONFORM_PIECE_PRO AS LIB_MOTIF_NON_CONFORM_PIECE_PRO
         									FROM    #TMP_PIECES_CONTRAT_PRO
         									JOIN	NR410 
         									ON		#TMP_PIECES_CONTRAT_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         									JOIN	MOTIF_NON_CONFORM_PIECE_PRO 
         									ON		NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE	#TMP_PIECES_CONTRAT_PRO.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECES_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML RAW('TABLEAU_CONTRAT'),ELEMENTS, TYPE
         						)END,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_PIECES_MODULE_PRO) > 0) THEN(
         							SELECT 'Et pour les modules de formation suivants :'
         							FOR XML PATH('SUITE_MODULE'), TYPE 
         						)END ,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_PIECES_MODULE_PRO) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_PIECES_MODULE_PRO.NB_UNITE_FORMATION,
         													#TMP_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													#TMP_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_PIECES_MODULE_PRO.LIBL_MODULE_PRO AS LIB_MODULE_PRO,
         													#TMP_PIECES_MODULE_PRO.LIBL_PIECE_PRO AS LIB_PIECE_PRO_MANQUANTE
         									FROM			#TMP_PIECES_MODULE_PRO
         									WHERE			#TMP_PIECES_MODULE_PRO.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE_MODULE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES_MODULE')
         								),
         								(
         									SELECT DISTINCT	#TMP_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_PIECES_MODULE_PRO.NB_UNITE_FORMATION,
         													#TMP_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													#TMP_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_PIECES_MODULE_PRO.LIBL_MODULE_PRO AS LIB_MODULE_PRO,
         													#TMP_PIECES_MODULE_PRO.LIBL_PIECE_PRO AS LIB_PIECE_PRO_NON_CONFORME,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBL_MOTIF_NON_CONFORM_PIECE_PRO AS LIB_MOTIF_NON_CONFORM_PIECE_PRO
         									FROM    #TMP_PIECES_MODULE_PRO
         									JOIN	NR410 
         									ON		#TMP_PIECES_MODULE_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         									JOIN	MOTIF_NON_CONFORM_PIECE_PRO 
         									ON		NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE	#TMP_PIECES_MODULE_PRO.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME_MODULE'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES_MODULE')
         								)
         							FOR XML RAW('TABLEAU_MODULE'),ELEMENTS, TYPE
         						)END,
         						(
         							SELECT	top 1 dbo.GetContactSalutation(@ID_CONTACT, 0)
         							FROM CIVILITE
         							FOR XML PATH('POLITESSE_BAS'), TYPE
         						)
         				FROM #TMP_CONTRAT_PRO AS CORPS     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TEMP_REFERENCE as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         
         	FROM	#TEMP_REFERENCE as LETTRE
         	FOR XML AUTO, ELEMENTS
         END

GO
         CREATE PROCEDURE MAJ_ANNEE_COURANT                                                                                                                                                                                                                                                 
         
         /*
         SIRIUS
         Objet :  Proc‚dure stock‚e dbo.MAJ_ANNEE_COURANT    Date du script : 05/04/2007 par ED
         Mise a jour de l'annee courante 
          */
         
         
         @NUM_ANNEE 	INTEGER
         AS
         SELECT 1
         FROM PERIODE
         WHERE NUM_ANNEE = @NUM_ANNEE
         AND id_type_periode=1
         IF @@ROWCOUNT > 0
         BEGIN
         	UPDATE PERIODE
         	SET BLN_EN_COURS 	= 0
         	WHERE NUM_ANNEE 	<> @NUM_ANNEE
         	AND ID_TYPE_PERIODE 	=1
         	UPDATE PERIODE
         	SET BLN_EN_COURS 	= 1
         	WHERE NUM_ANNEE 	= @NUM_ANNEE
         	AND ID_TYPE_PERIODE 	=1
         END
         ELSE
         BEGIN
         	PRINT 'ANNEE INEXISTANTE'
         END
         
         
GO
 CREATE PROCEDURE [dbo].[UPD_OPERATION]
          @ID_OPERATION_FINANCIERE INT,
          @LIBL_OPERATION_FINANCIERE VARCHAR(50),  
          @ID_BRANCHE INT,  
          @ID_DISPOSITIF INT,  
          @ID_AGENCE INT,  
          @ID_PERIODE INT,  
          @COM_OPERATION_FINANCIERE VARCHAR(200),
          @DAT_DEBUT datetime,
          @DAT_FIN datetime,
          @ID_UTIL int,
          @BLN_ACTIF int,
          @BLN_DEFAUT int,
          @ID_SCHEMAS_XML INT
         
         AS 
         ---------------------------------------
         -- DSZ #661 21/11/2014 suppresion id_public faf et creation comptes par defaut
         ---------------------------------------
         -- DSZ #946 ajout ID_SCHEMAS_XML
         ----------------------------------
         -- DSZ #1410 08/04/2016 suppression de creation des liaisons avec les comptes id 1 et 2
         ----------------------------------
          
         BEGIN
          IF (@BLN_ACTIF IS NULL)
          BEGIN
           SET @BLN_ACTIF = 0
          END 
          IF (@BLN_DEFAUT IS NULL)
          BEGIN
           SET @BLN_DEFAUT = 0
          END 
         
          IF (@BLN_DEFAUT = 1)
          BEGIN --ancienne operation par defaut devient non-defaut
           UPDATE OPERATION_FINANCIERE SET BLN_DEFAUT = 0 
           WHERE ID_PERIODE = @ID_PERIODE 
           AND coalesce(ID_DISPOSITIF, -1) = coalesce(@ID_DISPOSITIF, -1)
           AND ID_AGENCE = @ID_AGENCE 
           AND coalesce(ID_BRANCHE, -1) = coalesce(@ID_BRANCHE, -1) 
           AND BLN_DEFAUT = 1
          END
         
          UPDATE OPERATION_FINANCIERE SET 
           LIBL_OPERATION_FINANCIERE = @LIBL_OPERATION_FINANCIERE,
           ID_BRANCHE = @ID_BRANCHE,
           ID_DISPOSITIF = @ID_DISPOSITIF,
           ID_AGENCE = @ID_AGENCE,
           ID_PERIODE = @ID_PERIODE,
           DAT_DEBUT = @DAT_DEBUT,
           DAT_FIN = @DAT_FIN,
           DAT_MODIF = GETDATE(),
           COM_MODE_FINANCEMENT = @COM_OPERATION_FINANCIERE,
           ID_UTILISATEUR = @ID_UTIL,
           BLN_ACTIF = @BLN_ACTIF,
           BLN_DEFAUT = @BLN_DEFAUT,
           ID_SCHEMAS_XML = @ID_SCHEMAS_XML
          WHERE ID_OPERATION_FINANCIERE  = @ID_OPERATION_FINANCIERE
         
            
          IF @@ROWCOUNT = 0   
          BEGIN  
             IF EXISTS(SELECT * FROM OPERATION_FINANCIERE WHERE ID_OPERATION_FINANCIERE  = @ID_OPERATION_FINANCIERE)      
             BEGIN  
             /* ProblŠme de Concurrence d'acces */  
             RAISERROR(50001, 16, 2)  
             END  
          END 
         
          END

GO
 /*
         =============================================  
         Author  : MBL
         Create date : 21/11/2013
         Description : Proc‚dure permettant de generer les Regularisation Automatique de FPSPP liee aux versements de collecte 
         
         Le traitement fait appel a la vue VUE_COLLECTE_REGUL_FPSPP permettant de determiner par adherent et annee :
         - le montant PLAN FPSPP enregistr‚ dans OPTIFORM
         - le montant PLAN FPSPP th‚orique
         - et de mesurer les ‚carts entre ces 2 montants
         
         Cette requete permet par ailleurs de proposer 3 cas de regularisations automatiques :
         
         1er Cas de Regularisation :
         -----------------------------
         - FSPP Theorique Insuffisant Alors que le Montant Verse Total > FPSPP Theorique
         La regul VO est valorisee pour l'ecart dans la limite du montant verse VO Hors FPSPP
         
         2eme Cas de Regularisation, complementaire du 1er ET UNIQUEMENT POUR LA PLASTURGIE :
         ---------------------------------------------------------------------------------------
         - FSPP Theorique Insuffisant Alors que le Montant Verse Total > FPSPP Theorique
         Si le montant VO Hors FPSPP, n'a pas suffit pour compenser le FPSPP theorique manquant, on le complete avec du VV, dans la limite du VV Hors FPSPP
         
         3EME CAS DE REGULARISATION 
         ---------------------------
         Le montant enregistre sur le FPSPP est trop important il est transfere sur l'activite PLAN en VO
         
         Parametre : le parametre @ID_GROUPE_TRAITE est optionnel. 
         			S'il est valorise, le traitement n'est declenche que pour le groupe de mˆme ID
         			S'il n'est pas valorise, le traitement est declenche pour tous les groupes
         
         -- CONDITION DE LANCEMENT
         La detection d'ecart est realise sur N=2012, ou N correspond a l'annee  des versements
         La correction d'ecart est declenchee lorsque l'un des 3 cas de regularisations est detecte
         la valeur absolue de l'ecart est superieur a 1
         
         Parametre : le parametre @ID_ADHERENT_TRAITE est optionnel. 
         			S'il est valorise, le traitement n'est declenche que pour l'adherent de mˆme ID
         			S'il n'est pas valorise, le traitement est declenche pour tous les adherents
         
         =============================================  
         */
         CREATE PROCEDURE dbo.BATCH_GENERATION_REGUL_COLLECTE_FPSPP
         	@ID_ADHERENT_TRAITE INT
         AS
         BEGIN
         	IF OBJECT_ID('tempdb..#TMP_REGUL_A_CREER', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_REGUL_A_CREER
         	END
         
         
         	DECLARE 
         		@DAT								DATETIME,	
         		@ID_ADHERENT						INTEGER,
         		@NUM_ANNEE							INTEGER,
         		@ID_PERIODE							INTEGER,
         		@ID_ETABLISSEMENT					INTEGER,
         		@ID_ACTIVITE						INTEGER,
         		@MNT_VERSE_PLAN_FSPP				DECIMAL(15,2), 
         		@MNT_REGUL_VO_FPSPP_INSUFFISANT		DECIMAL(15,2), 
         		@MNT_REGUL_VV_FPSPP_INSUFFISANT		DECIMAL(15,2),  
         		@MNT_REGUL_VO_FPSPP_TROP_IMPORTANT	DECIMAL(15,2),
         		@MNT								DECIMAL(15,2)
         
         
         	SELECT
         		* 
         	INTO
         		#TMP_REGUL_A_CREER	
         	FROM
         		VUE_COLLECTE_REGUL_FPSPP
         	WHERE
         		NUM_ANNEE In (2012)
         		AND ABS(ECART) > 1
         		AND ID_ADHERENT = ISNULL(@ID_ADHERENT_TRAITE, ID_ADHERENT)
         		AND 
         		(
         			ABS(CAST(REGUL_VO_FPSPP_INSUFFISANT AS DECIMAL(15,2)))> 0
         			OR
         			ABS(CAST(REGUL_VV_FPSPP_INSUFFISANT AS DECIMAL(15,2))) > 0
         			OR
         			ABS(CAST(REGUL_VO_FPSPP_TROP_IMPORTANT AS DECIMAL(15,2))) > 0		
         		)
         	ORDER BY
         		NUM_ANNEE,
         		ID_ADHERENT
         
         	DECLARE cu_regul CURSOR FOR
         	SELECT
         		ID_ADHERENT,
         		NUM_ANNEE,
         		ID_ACTIVITE,
         		REGUL_VO_FPSPP_INSUFFISANT,
         		REGUL_VV_FPSPP_INSUFFISANT,
         		REGUL_VO_FPSPP_TROP_IMPORTANT
         	FROM
         		#TMP_REGUL_A_CREER
         
         	OPEN cu_regul
         
         	FETCH cu_regul 
         	INTO	@ID_ADHERENT, @NUM_ANNEE, @ID_ACTIVITE,
         			@MNT_REGUL_VO_FPSPP_INSUFFISANT, @MNT_REGUL_VV_FPSPP_INSUFFISANT, @MNT_REGUL_VO_FPSPP_TROP_IMPORTANT
         
         	WHILE (@@FETCH_STATUS <> -1)
         	BEGIN
         		--SELECT 	*
         		--FROM #TMP_REGUL_A_CREER
         		--WHERE ID_ADHERENT =  @ID_ADHERENT	
         
         		SELECT @ID_PERIODE = ID_PERIODE
         		FROM PERIODE
         		WHERE NUM_ANNEE = @NUM_ANNEE
         		AND ID_TYPE_PERIODE = 1
         
         		-- Recherche etablissemetn de l'adherent ayant verse le plus de FPSPP sur la periode
         		SELECT		TOP 1
         					@ID_ETABLISSEMENT		= ID_ETABLISSEMENT_BENEFICIAIRE, 
         					@MNT_VERSE_PLAN_FSPP	= SUM(ISNULL(DONT_REGLE_FPSPP, 0))					
         		FROM		VERSEMENT
         		INNER JOIN	POSTE_VERSEMENT		ON	VERSEMENT.ID_VERSEMENT				= POSTE_VERSEMENT.ID_VERSEMENT
         		INNER JOIN	TYPE_VERSEMENT		ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT	= TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         		INNER JOIN	POSTE_IMPUTATION	ON	POSTE_VERSEMENT.ID_POSTE_VERSEMENT	= POSTE_IMPUTATION.ID_POSTE_VERSEMENT
         		INNER JOIN ACTIVITE				ON POSTE_IMPUTATION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         		INNER JOIN TYPE_ACTIVITE		ON TYPE_ACTIVITE.ID_TYPE_ACTIVITE				 = ACTIVITE.ID_TYPE_ACTIVITE						
         		LEFT JOIN	BORDEREAU			ON	VERSEMENT.ID_BORDEREAU				= BORDEREAU.ID_BORDEREAU
         		WHERE	VERSEMENT.BLN_ACTIF = 1 
         		AND		POSTE_VERSEMENT.BLN_ACTIF = 1 
         		AND TYPE_ACTIVITE.COD_TYPE_ACTIVITE = 'PLAN'
         		AND VERSEMENT.BLN_IMPAYE= 0
         		AND
         	   (
         		TYPE_VERSEMENT.COD_TYPE_VERSEMENT  IN  ( 'REGUL_O', 'REVERS_O', 'REGUL_V', 'REVERS_V')
         		OR
         		BORDEREAU.ID_LOT_REMISE_BANCAIRE  IS NOT NULL  
         		)
         		AND ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT
         		AND ID_PERIODE = @ID_PERIODE
         		GROUP BY ID_ETABLISSEMENT_BENEFICIAIRE
         		ORDER BY 2 DESC
         		
         		--SELECT ID_ETABLISSEMENT = @ID_ETABLISSEMENT		, DONT_REGLE_FPSPP = @MNT_VERSE_PLAN_FSPP	
         
         		-- Augmentation du FPSPP sur VO
         		IF ABS(@MNT_REGUL_VO_FPSPP_INSUFFISANT) > 0 
         		BEGIN
         		
         			SET @MNT = @MNT_REGUL_VO_FPSPP_INSUFFISANT
         
         			  EXEC CREER_REGULARISATION_PV_PI   
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   5								,		--@ID_TYPE_VERSEMENT = 5 (R‚gularisation Obligatoire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   0										--@regul_FPSSP  
         
         			SET @MNT = -@MNT_REGUL_VO_FPSPP_INSUFFISANT
         
          			 EXEC CREER_REGULARISATION_PV_PI
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   5								,		--@ID_TYPE_VERSEMENT = 5 (R‚gularisation Obligatoire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   @MNT										--@regul_FPSSP  
         		END
         
         
         		-- Augmentation du FPSPP sur VV
         		IF ABS(@MNT_REGUL_VV_FPSPP_INSUFFISANT) > 0 
         		BEGIN
         		
         			SET @MNT = @MNT_REGUL_VV_FPSPP_INSUFFISANT
         
         			  EXEC CREER_REGULARISATION_PV_PI   
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   7								,		--@ID_TYPE_VERSEMENT = 7 (R‚gularisation Volontaire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   0										--@regul_FPSSP  
         
         			SET @MNT = -@MNT_REGUL_VV_FPSPP_INSUFFISANT
         
          			 EXEC CREER_REGULARISATION_PV_PI
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   5								,		--@ID_TYPE_VERSEMENT = 7 (R‚gularisation Volontaire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   @MNT										--@regul_FPSSP  
         		END
         
         		-- Diminution du FPSPP sur VO
         		IF ABS(@MNT_REGUL_VO_FPSPP_TROP_IMPORTANT) > 0 
         		BEGIN
         		
         			SET @MNT = -@MNT_REGUL_VO_FPSPP_TROP_IMPORTANT
         
         			  EXEC CREER_REGULARISATION_PV_PI   
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   5								,		--@ID_TYPE_VERSEMENT = 5 (R‚gularisation Obligatoire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   @MNT										--@regul_FPSSP  
         
         			SET @MNT = @MNT_REGUL_VO_FPSPP_TROP_IMPORTANT
         
          			 EXEC CREER_REGULARISATION_PV_PI
         			   @ID_ADHERENT						,		--@ID_ADHERENT_EMETTEUR 
         			   null								,		--@ID_TIERS_EMETTEUR,    
         			   @ID_ETABLISSEMENT				,		--@ID_ETABLISSEMENT_EMETTEUR 
         			   @MNT								,		--@MNT_VERSEMENT 
         			   5								,		--@ID_TYPE_VERSEMENT = 5 (R‚gularisation Obligatoire)  
         			   @ID_PERIODE						,		--@ID_PERIODE	
         			   @ID_ACTIVITE						,		--@ID_ACTIVITE,  
         			   0										--@regul_FPSSP  
         		END
         
         		FETCH cu_regul 
         		INTO	@ID_ADHERENT, @NUM_ANNEE, @ID_ACTIVITE,
         				@MNT_REGUL_VO_FPSPP_INSUFFISANT, @MNT_REGUL_VV_FPSPP_INSUFFISANT, @MNT_REGUL_VO_FPSPP_TROP_IMPORTANT
         
         
         	END
         
         	CLOSE cu_regul
         	DEALLOCATE cu_regul
         
         
         	IF OBJECT_ID('tempdb..#TMP_REGUL_A_CREER', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_REGUL_A_CREER
         	END
         
         END		
GO

         
         -- =============================================
         -- Author		: XX
         -- Create date	: XX XXXX 2007
         -- Description	:	Cr‚ation
         -- ---------------------------------------------
         -- Author		: SV
         -- Modif. date	: 10 octobre 2007
         -- Description	: Ajout d'un filtre pour ne pas prendre en compte le poste de co–t r‚gl‚ courant (cas de la modification)
         -- =============================================
         
         CREATE  PROCEDURE [dbo].[LEC_DET_VALID_NUM_FACTURE]
         	@ID_PCR_COURANT INT,		-- Identifiant du poste de cout r‚gl‚ courant
         	@NUM_FACTURE VARCHAR(50),	-- Num‚ro de la facture … tester
         	@ID_MODULE INT,				-- Identifiant du module courant
         	@ID_ADHERENT INT,			-- Identifiant de l'adh‚rent associ‚ … la facture	(null si c'est un O.F.)
         	@ID_OF INT					-- Identifiant de l'O.F. associ‚ … la facture		(null si c'est un adh‚rent)
         AS
         BEGIN
         	DECLARE @COUNT INT
         	DECLARE @EXIST INT
         	DECLARE @ID_POSTE_COUT_REGLE INT
         	DECLARE @DAT_VALID DATETIME
         
         	IF @ID_ADHERENT IS NULL
         		BEGIN
         			-- Recherche du nombre de facture existantes avec le mˆme num‚ro
         			SELECT
         				@COUNT = COUNT(*)
         			FROM
         				POSTE_COUT_REGLE
         					INNER JOIN MODULE_PEC		ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         													AND POSTE_COUT_REGLE.NUM_FACTURE = @NUM_FACTURE
         					INNER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         													AND ETABLISSEMENT_OF.ID_OF = @ID_OF
         			WHERE
         				POSTE_COUT_REGLE.NUM_FACTURE IS NOT NULL
         				and
         				(
         					@ID_PCR_COURANT is null
         					or POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE <> @ID_PCR_COURANT
         				)
         			
         			IF @COUNT > 0
         				BEGIN
         					-- Recherche d'une date de rŠglement pour une facture ayant ce num‚ro
         					SELECT 
         						@DAT_VALID = REGLEMENT.DAT_VALID_REGLEMENT
         					FROM
         						REGLEMENT
         							INNER JOIN POSTE_COUT_REGLE	ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         							INNER JOIN MODULE_PEC		ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         															AND POSTE_COUT_REGLE.NUM_FACTURE = @NUM_FACTURE
         							INNER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         															AND ETABLISSEMENT_OF.ID_OF = @ID_OF
         					WHERE
         						POSTE_COUT_REGLE.NUM_FACTURE IS NOT NULL
         						and
         						(
         							@ID_PCR_COURANT is null
         							or POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE <> @ID_PCR_COURANT
         						)
         				END
         		END
         	ELSE
         		BEGIN
         			-- Recherche du nombre de facture existantes avec le mˆme num‚ro
         			SELECT
         				@COUNT = COUNT(*)
         			FROM
         				POSTE_COUT_REGLE
         					INNER JOIN MODULE_PEC		ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         													AND POSTE_COUT_REGLE.NUM_FACTURE = @NUM_FACTURE
         					INNER JOIN ETABLISSEMENT	ON ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT
         													AND ETABLISSEMENT.ID_ADHERENT = @ID_ADHERENT
         			WHERE
         				POSTE_COUT_REGLE.NUM_FACTURE IS NOT NULL
         				and
         				(
         					@ID_PCR_COURANT is null
         					or POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE <> @ID_PCR_COURANT
         				)
         			
         			IF @COUNT > 0
         				BEGIN
         					-- Recherche d'une date de rŠglement pour une facture ayant ce num‚ro
         					SELECT 
         						@DAT_VALID = REGLEMENT.DAT_VALID_REGLEMENT
         					FROM
         						REGLEMENT
         							INNER JOIN POSTE_COUT_REGLE	ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         							INNER JOIN MODULE_PEC		ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         															AND POSTE_COUT_REGLE.NUM_FACTURE = @NUM_FACTURE
         							INNER JOIN ETABLISSEMENT	ON ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT
         															AND ETABLISSEMENT.ID_ADHERENT = @ID_ADHERENT
         					WHERE
         						POSTE_COUT_REGLE.NUM_FACTURE IS NOT NULL
         						and
         						(
         							@ID_PCR_COURANT is null
         							or POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE <> @ID_PCR_COURANT
         						)
         				END
         		END
         	
         	-- D‚finition des valeurs … retouner
         	IF @COUNT > 0
         		BEGIN
         			SET @EXIST = 1
         		END
         	ELSE
         		BEGIN
         			SET @EXIST = 0
         			SET @DAT_VALID = NULL
         		END
         	
         	-- Valeurs … retourner
         	SELECT
         		@EXIST AS EXIST,
         		@DAT_VALID AS DAT_VALID_REGLEMENT
         END
         
GO
         
         -- =============================================
         -- Author:		MBE
         -- Create date: 02/06/2008
         -- Description:	Compteur pour COD_FACTURE. Returns COD_FACTURE
         -- =============================================
         CREATE PROCEDURE [dbo].[FACTURE_COMPTEUR]
         	@FACTURE_ANNEE int
         AS
         BEGIN
         	-- get the existing counter
         	DECLARE	@@COMPTEUR int
         	DECLARE @@COD_CPT varchar(13)
         
         	SET @@COD_CPT = 'FACTURE '+convert(varchar(4), @FACTURE_ANNEE)
         
         	SELECT @@COMPTEUR = NUM_CPT 
         	FROM COMPTEUR 
         	WHERE COD_CPT = @@COD_CPT
         
         	IF @@COMPTEUR is null --if no counter found for this year let's create it
         		BEGIN
         			SET @@COMPTEUR = 1
         			insert into COMPTEUR (COD_CPT, NUM_CPT, BLN_BLOQUE)
         			values (@@COD_CPT, 1, 0)
         		END
         	else
         		BEGIN
         			SET @@COMPTEUR = @@COMPTEUR + 1
         			update COMPTEUR set NUM_CPT = @@COMPTEUR
         			where COD_CPT = @@COD_CPT
         		END
         RETURN  @@COMPTEUR
         END

GO
         -- =============================================
         -- Author		: kw
         -- Create date	: 21 novembre 2007
         -- Description	: proc‚dure de mise … jour des r‚glement et des virements internes pro
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_REGLEMENT_GENERATION_VIREMENT_INTERNE_PRO]
         AS
         BEGIN
         
         	SELECT DISTINCT 
         		ID_REGLEMENT_PRO 
         	INTO #ID_REGLEMENT_PRO
         	FROM [VIEW_VIREMENT_INTERNE_PRO_DATA]
         
         	-- ON REMPLI NR439 AVEC LES VIREMENT_INTERNE_COLLECTE PRO AYANT ID_ACTIVITE NOT NULL ET EGALE A 3
         	INSERT INTO 
         		NR439(ID_VIREMENT_INTERNE_PRO,ID_REGLEMENT_PRO)
         	
         	SELECT DISTINCT 
         		VIREMENT_INTERNE_PRO.ID_VIREMENT_INTERNE_PRO, #ID_REGLEMENT_PRO.ID_REGLEMENT_PRO
         	FROM 
         		VIREMENT_INTERNE_PRO
         		INNER JOIN VIEW_VIREMENT_INTERNE_PRO_DATA ON VIEW_VIREMENT_INTERNE_PRO_DATA.ID_ACTIVITE = VIREMENT_INTERNE_PRO.ID_ACTIVITE
         		INNER JOIN #ID_REGLEMENT_PRO ON #ID_REGLEMENT_PRO.ID_REGLEMENT_PRO = VIEW_VIREMENT_INTERNE_PRO_DATA.ID_REGLEMENT_PRO
         	WHERE NOT EXISTS (select 1 from NR439 where NR439.ID_VIREMENT_INTERNE_PRO = VIREMENT_INTERNE_PRO.ID_VIREMENT_INTERNE_PRO)
         	
         END
         
         

GO

 -- ============================================================  
         -- AUTHOR : SAFI  
         -- DATE  : 19/01/2010  
         -- Ano  : 12176 evol 399  
         -- NOTE  : DAT_ENCAISSEMENT, ADDED A NEW CONTROL FOR THIS COLOUMN  
         ---------------------------------------------------------------  
         -- DSZ 04/05/2010 ANO 12346  
         -- annulation mise en conformit‚ avec la SFD :  
         -- rendre le reversement inactif : VERSEMENT.BLN_ACTIF = 0   
         -- et POSTE_VERSEMENT.BLN_ACTIF = 0 avec POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT.  
         -- Fonctionnalit‚ limit‚ aux reversements le 27/05/10 ano 12322 - DSZ  
         -- ============================================================  
         -- DSZ 12391 04/06/2010   
         -- Remplacer condition sur ID_TYPE_VERSEMENT par BLN_VERSEMENT_INITIAL   
         -- =============================================  
         -- EOU 14060 23/01/2013   
         -- =============================================  
         -- TLE 14994 18/04/2013 : prise en compte des reversements dans la mise … jour de la date synchro ssis  
         -- =============================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT  
         -- =============================================  
         -- MBL 12/11/2013 : Lorsqu'un versement est rendu inactif (@BLN_ACTIF = 0), le lien avec son bordereau est supprime (ID_BORDEREAU=NULL) et la date de validation du reglement est RAZ
         --                  afin de s'assurer qu'aucun traitement lie au bordereau ou a la remise en banque n'est effectue
         -- =============================================
         -- LDE 03/12/2013 #16367 : Versement - Dat_Virement : Points 1 et 3
         -- =============================================
         -- ASD 18/12/2013 ajout gestion impay‚s
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_VERSEMENT]
          @ID_VERSEMENT INTEGER,  
          @ID_ADHERENT_EMETTEUR INTEGER,  
          @ID_TIERS_EMETTEUR INTEGER,  
          @ID_MODE_VERSEMENT INTEGER,    
          @COD_VERSEMENT INTEGER,   
          @DAT_CREATION datetime,  
          @LIB_BANQUE varchar(50),  
          @MNT_VERSEMENT decimal(18,2),  
          @BLN_PB_IMPUTATION TINYINT,  
          @BLN_ACTIF TINYINT,  
          @COM_VERSEMENT VARCHAR(255),  
          @ID_UTILISATEUR INTEGER,  
          @TIME_STAMP timestamp,  
          @ID_BORDEREAU INTEGER,  
          @NUM_CHEQUE varchar(10),  
          @DAT_ENCAISSEMENT datetime,  
          @DAT_IMPUTATION datetime,  
          @DAT_MODIF datetime,  
          @DAT_SAISIE datetime,  
          @DAT_MAJ_COMPTES datetime,  
          @DAT_COMPTA_COMPTES_ADH datetime,  
          @DAT_ANNUL_COMPTES_ADH datetime,  
          @DAT_PASSAGE_COMPTA datetime,  
          @INDICATEUR_INSTANCE INTEGER,  
          @ID_STATUT_VERSEMENT INTEGER,  
          @BLN_IMPAYE TINYINT,  
          @DAT_SAISIE_IMPAYE datetime,  
          @BLN_ENCAISSEMENT_DIFFERE TINYINT,  
          @BLN_DIFFERE_PRIS_EN_COMPTE TINYINT = null,  
          @DAT_VALID_VERSEMENT datetime = null,  
          @ID_BANQUE INTEGER,  
          @MODE_SAISIE_VERSEMENT varchar(15),  
          @ID_ETABLISSEMENT_EMETTEUR int,
          @DAT_VIREMENT datetime			-- LDE 03/12/2013 #16367
         AS    
           
           
           
         --   
         select @LIB_BANQUE =LIBC_BANQUE  from BANQUE WHERE ID_BANQUE = @ID_BANQUE  
         --SAFI AJOUTER 19/01/2010  
         --CONTROL for @DAT_ENCAISSEMENT  
          IF( ISNULL(@BLN_ENCAISSEMENT_DIFFERE,0) = 0)  
          BEGIN  
          SET @DAT_ENCAISSEMENT = NULL  
          END  
         -- END SAFI AJOUTER 19/01/2010  
           
          UPDATE VERSEMENT  
          SET    
            ID_ADHERENT_EMETTEUR=@ID_ADHERENT_EMETTEUR ,  
            ID_TIERS_EMETTEUR=@ID_TIERS_EMETTEUR ,  
            ID_MODE_VERSEMENT=@ID_MODE_VERSEMENT ,    
            COD_VERSEMENT=@COD_VERSEMENT ,   
            DAT_CREATION=@DAT_CREATION ,  
            LIB_BANQUE=@LIB_BANQUE ,  
            MNT_VERSEMENT=@MNT_VERSEMENT ,  
            BLN_PB_IMPUTATION=@BLN_PB_IMPUTATION ,  
            BLN_ACTIF=@BLN_ACTIF ,  
            COM_VERSEMENT=@COM_VERSEMENT ,  
            ID_UTILISATEUR=@ID_UTILISATEUR ,  
         
         -- MBL 12/11/2013 : Lorsqu'un versement est rendu inactif (@BLN_ACTIF = 0), le lien avec son bordereau est supprime (ID_BORDEREAU=NULL) et la date de validation du reglement est RAZ
            --ID_BORDEREAU = @ID_BORDEREAU,  
            --DAT_VALID_VERSEMENT = @DAT_VALID_VERSEMENT,  
            ID_BORDEREAU = CASE WHEN @BLN_ACTIF=0 THEN NULL ELSE @ID_BORDEREAU END,  
            DAT_VALID_VERSEMENT = CASE WHEN @BLN_ACTIF=0 THEN NULL ELSE @DAT_VALID_VERSEMENT END,  
         
            NUM_CHEQUE = @NUM_CHEQUE ,  
            DAT_ENCAISSEMENT=@DAT_ENCAISSEMENT ,  
            DAT_IMPUTATION=@DAT_IMPUTATION ,  
            DAT_MODIF = getdate(),  
            DAT_SAISIE=@DAT_SAISIE ,  
            DAT_MAJ_COMPTES=@DAT_MAJ_COMPTES ,  
            DAT_COMPTA_COMPTES_ADH=@DAT_COMPTA_COMPTES_ADH ,  
            DAT_ANNUL_COMPTES_ADH = @DAT_ANNUL_COMPTES_ADH ,  
            DAT_PASSAGE_COMPTA=@DAT_PASSAGE_COMPTA ,  
            INDICATEUR_INSTANCE= @INDICATEUR_INSTANCE ,  
            ID_STATUT_VERSEMENT = @ID_STATUT_VERSEMENT ,  
            BLN_IMPAYE=@BLN_IMPAYE ,  
            DAT_SAISIE_IMPAYE= @DAT_SAISIE_IMPAYE ,  
            BLN_ENCAISSEMENT_DIFFERE =@BLN_ENCAISSEMENT_DIFFERE,  
            BLN_DIFFERE_PRIS_EN_COMPTE  = @BLN_DIFFERE_PRIS_EN_COMPTE,  
            ID_BANQUE = @ID_BANQUE,  
            MODE_SAISIE_VERSEMENT = @MODE_SAISIE_VERSEMENT,  
            ID_ETABLISSEMENT_EMETTEUR = @ID_ETABLISSEMENT_EMETTEUR,
            DAT_VIREMENT = @DAT_VIREMENT	-- LDE 03/12/2013 #16367
              
           
          FROM VERSEMENT  
          WHERE  
           ID_VERSEMENT  = @ID_VERSEMENT    
           AND TIME_STAMP = @TIME_STAMP    
           
          IF @@ROWCOUNT = 0     
           BEGIN    
              IF EXISTS(SELECT * FROM VERSEMENT WHERE ID_VERSEMENT  = @ID_VERSEMENT)        
              BEGIN    
                     
                 RAISERROR(50001, 16, 1)    
              END    
              ELSE    
              BEGIN    
                     
                 RAISERROR(50002, 16, 1)    
              END    
           END         
           
           
         --modif DSZ 04/06/10 12391  
         select ID_POSTE_VERSEMENT  
         into #tmp_poste_vers_to_update  
         from POSTE_VERSEMENT  
          inner join TYPE_VERSEMENT ON POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT  
         where   
          POSTE_VERSEMENT.ID_VERSEMENT = @ID_VERSEMENT  
          AND POSTE_VERSEMENT.BLN_ACTIF <> @BLN_ACTIF  
          AND TYPE_VERSEMENT.BLN_VERSEMENT = 0 --reversements  
           
         update POSTE_VERSEMENT  
         set BLN_ACTIF = @BLN_ACTIF  
         where POSTE_VERSEMENT.ID_POSTE_VERSEMENT in  
          (select ID_POSTE_VERSEMENT from #tmp_poste_vers_to_update)  
           
           
           
         -- On ne met … jour la date de synchro seulement si un versement a ‚t‚ valid‚ ; prend en compte ici uniquement les impay‚s, reversements et les r‚guls  
         IF EXISTS 
         	(
         		SELECT v.id_versement   
         			   FROM   
         				versement v INNER JOIN poste_versement pv ON pv.id_versement = v.id_versement   
         				INNER JOIN type_versement tv ON tv.id_type_versement = pv.id_type_versement   
         			   WHERE  
         					(tv.bln_versement_initial = 0      
         					AND (tv.bln_versement = 1 OR v.dat_valid_versement IS NOT NULL)  
         					AND v.id_versement = @ID_VERSEMENT  
         					AND v.id_bordereau IS NULL  
         					AND @ID_BORDEREAU IS NOT NULL
         					)
         					 OR v.BLN_IMPAYE=1
             )  
         BEGIN  
          UPDATE VERSEMENT SET   
           SYNC_BLN_SYNCHRO_SSIS = 1,  
           SYNC_DAT_SYNCHRO_SSIS = getdate()  
          WHERE  
           ID_VERSEMENT = @ID_VERSEMENT  
         END  
           

GO

 -- =============================================
         -- Author			: KW
         -- Create date		: XX XX 2007
         -- Description		: Cr‚ation
         -- =============================================
         -- Author			: SV
         -- Modified date	: 21 ao–t 2007
         -- Description		: Ajout d'une association entre le poste de co–t regl‚ et l'adh‚rent relanc‚
         --					  Ajout d'une association entre l'arrivee de la piŠce et l'adh‚rent relanc‚ (ou null si la piŠce concerne tout le monde)
         --					  Ajout d'un filtre de maniŠre … ne pas relancer les piŠces module et session pour chaque facture
         --					  Suppression des piŠces purement stagiaire car elles sont g‚r‚es par les piŠces module
         -- =============================================
         -- Author			: SV
         -- Modified date	: 27 ao–t 2007
         -- Description		: Gestion de la phrase "(par l'organisme de formation XXX)" au niveau du flux X.M.L. pour les cas de formation interne
         -- =============================================
         -- Author			: SV
         -- Modified date	: 31 octobre 2007
         -- Description		: Suppression de la clause sur le le champ #TEMP_SESSION.NUM_FACTURE
         -- =============================================
         -- Author			: AMA
         -- Modified date	: 29 mai 2008
         -- Description		: @COD_SESSION_PEC varchar(12) => varchar(17)
         -- =============================================
         -- Author			: SBRU
         -- Date				: 30/05/2008
         -- Description		: La partie Emetteur est renseign‚e … partir de la fonction GetXmlAdrUtil (au lieu de GetXmlAgenceContact)
         --					  Gestion du cas particulier des actions collectives
         -- =============================================
         -- Le 05/03/09 par SBRU - Adaptation gabarit suite au groupe de travail sur les ‚ditions
         -- =============================================
         -- DSZ 20/09/2012 : 13697 : num tel dynamique
         -- =============================================
         -- DSZ 18/02/2013 : 14832 : suppression signature
         -- =============================================
         -- LDE 08/04/2013 14955: DNE - Processus de relance rŠglement (4) - Modele d'‚dition lettre_pec_relance_reglement adh
         -- =============================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_RELANCE_PIECE_REGLEMENT_ADH]
         		@ID_ETABLISSEMENT int,
         		@ID_BENEFICIAIRE int,
         		@TYPE_BENEFICIAIRE int,
         		@ID_ADRESSE int,
         		@ID_CONTACT int,
         		@COD_SESSION_PEC varchar(17),
         		@ID_UTILISATEUR int
         AS
         BEGIN
         
         	-- Contact principal par d‚faut mais pas de "."
         	IF @ID_CONTACT IS NULL
         	SELECT @ID_CONTACT = NR31.ID_CONTACT
         	FROM NR31
         		INNER JOIN CONTACT ON CONTACT.ID_CONTACT = NR31.ID_CONTACT
         	WHERE BLN_PRINCIPAL = 1
         		AND BLN_ACTIF = 1
         		AND ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         		AND CONTACT.LIB_NOM_CONTACT <> '.';
         		
         		-- Si action individuelle: CR de l'‚tablissement et CM de l'‚tablissement
         		-- Si action collective: CR = CM = responsable des actions collectives renseign‚ dans le champ CM au niveau de l'action
         		select	distinct
         				t4.ID_ETABLISSEMENT,
         				t6.ID_ADHERENT,
         				t6.COD_ADHERENT,
         				t6.LIB_RAISON_SOCIALE,
         				t7.ID_UTILISATEUR	as ID_UTIL,
         				t7.LIB_PNM			as LIB_PRENOM_UTILISATEUR,
         				t7.LIB_NOM			as LIB_NOM_UTILISATEUR,
         				t7.EMAIL,
         				t7.LIB_VILLE,
         				t1.COD_SESSION_PEC
         
         		into #TEMP_REFERENCE
         
         		from	session_pec t1
         		join	module_pec t2
         		on		t1.id_module_pec = t2.id_module_pec
         		join	NR140 t3
         		on		t2.id_action_pec = t3.id_action_pec
         		join	etablissement t4
         		on		t3.id_etablissement = t4.id_etablissement
         		join	action_pec t5
         		on		t3.id_action_pec = t5.id_action_pec
         		join	adherent t6
         		on		t4.id_adherent = t6.id_adherent
         		left join UTILISATEUR AS t7 ON t7.ID_UTILISATEUR = @ID_UTILISATEUR
         		left join
         				utilisateur t8 -- charg‚ de mission ou responsable des actions collectives
         		on		case when (t5.cible_action = 1 or t5.bln_reprise_adhoc = 1)
         					 then t4.id_chargee_mission
         					 else t5.id_chargee_mission
         				end = t8.id_utilisateur
         
         		where	t1.cod_session_pec = @COD_SESSION_PEC
         
         	
         	
         		SELECT  DISTINCT MODULE_PEC.ID_MODULE_PEC,
         						 MODULE_PEC.COD_MODULE_PEC, 
         						 MODULE_PEC.LIBL_MODULE_PEC, 
         						 MODULE_PEC.NUM_INTERNE,
         						 SESSION_PEC.ID_SESSION_PEC,
         						 SESSION_PEC.COD_SESSION_PEC,
         						 SESSION_PEC.DAT_DEBUT,
         						 SESSION_PEC.DAT_FIN,
         						 SESSION_PEC.NUM_DUREE_JOUR,
         						 SESSION_PEC.NUM_DUREE_HEURE,
         						 ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         		INTO	#TEMP
         		FROM	MODULE_PEC
         		JOIN	SESSION_PEC ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC
         		LEFT JOIN ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         		LEFT JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF 
         		WHERE	SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC;
         				
         
         		SELECT  DISTINCT MODULE_PEC.ID_MODULE_PEC,
         						 MODULE_PEC.LIBL_MODULE_PEC, 
         						 SESSION_PEC.ID_SESSION_PEC,
         						 SESSION_PEC.COD_SESSION_PEC,
         						 SESSION_PEC.DAT_DEBUT,
         						 SESSION_PEC.DAT_FIN,
         						 SESSION_PEC.NUM_DUREE_JOUR,
         						 SESSION_PEC.NUM_DUREE_HEURE,
         						 ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         						 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         						 POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE,
         						 POSTE_COUT_REGLE.NUM_FACTURE,
         						 STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         						 ETABLISSEMENT.ID_ETABLISSEMENT,
         						 ADHERENT.ID_ADHERENT 
         
         		INTO	#TEMP_SESSION
         
         		FROM	MODULE_PEC
         				INNER JOIN SESSION_PEC ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC
         				LEFT JOIN ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         				LEFT JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF 
         				INNER JOIN STAGIAIRE_PEC ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         				INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         				INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         				INNER JOIN POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         												and
         												(
         													POSTE_COUT_REGLE.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
         													or POSTE_COUT_REGLE.ID_ETABLISSEMENT is null
         												)
         
         		WHERE		(MODULE_PEC.BLN_ACTIF = 1)
         				AND (SESSION_PEC.BLN_ACTIF = 1)
         				AND (SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC)
         				AND (POSTE_COUT_REGLE.BLN_ACTIF = 1)
         				AND ((MODULE_PEC.BLN_OK_PIECE = 0) OR (POSTE_COUT_REGLE.BLN_OK_PIECE = 0))
         				AND (ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
         	
         		
         		SELECT  DISTINCT #TEMP_SESSION.NUM_FACTURE,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		INTO	#TEMP_PIECES
         		FROM    #TEMP_SESSION 
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSION.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC)
         												and
         												(
         													ARRIVEE_PIECE_PEC.ID_ADHERENT = #TEMP_SESSION.ID_ADHERENT
         													or ARRIVEE_PIECE_PEC.ID_ADHERENT is null
         												)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC										
         		WHERE		(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         				AND (#TEMP_SESSION.BLN_FACTURE_DIRECTE = 0)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         		UNION
         
         		
         		SELECT  DISTINCT #TEMP_SESSION.NUM_FACTURE,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		FROM    #TEMP_SESSION
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSION.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC  
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC)
         												and
         												(
         													ARRIVEE_PIECE_PEC.ID_ADHERENT = #TEMP_SESSION.ID_ADHERENT
         													or ARRIVEE_PIECE_PEC.ID_ADHERENT is null
         												)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC AND (PIECE_PEC.BLN_STAGIAIRE = 0)
         		WHERE		(PIECE_PEC.BLN_MODULE = 1)
         				AND (#TEMP_SESSION.BLN_FACTURE_DIRECTE = 0)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         				--AND #TEMP_SESSION.NUM_FACTURE IS NULL	-- On ne relance pas ces piŠces pour les factures
         
         		UNION
         		
         		
         		SELECT  DISTINCT #TEMP_SESSION.NUM_FACTURE,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		FROM    #TEMP_SESSION 
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSION.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC)
         												and
         												(
         													ARRIVEE_PIECE_PEC.ID_ADHERENT = #TEMP_SESSION.ID_ADHERENT
         													or ARRIVEE_PIECE_PEC.ID_ADHERENT is null
         												)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC										
         		WHERE		(PIECE_PEC.BLN_SESSION = 1)
         				AND (#TEMP_SESSION.BLN_FACTURE_DIRECTE = 0)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         			--	AND #TEMP_SESSION.NUM_FACTURE IS NULL	-- On ne relance pas ces piŠces pour les factures
         
         
         	-- LDE 08/04/2013 14955
         	-- Reprise GetXmlBenefiaireContact car modifications n‚cessaires dans ce bloc pour cette ‚dition
         	DECLARE @LibelleFonction varchar(50)
         	DECLARE @RaisonSociale varchar(64)
         	
         	SELECT	@RaisonSociale	= coalesce(dbo.IS_EMPTY(ETABLISSEMENT.LIB_ENSEIGNE), ADHERENT.LIB_RAISON_SOCIALE)
         		FROM	ETABLISSEMENT
         		JOIN	ADHERENT
         		ON		ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         		WHERE	ETABLISSEMENT.ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         
         	SELECT	@LibelleFonction = FONCTION.LIBL_FONCTION
         		FROM	NR31
         		LEFT JOIN
         				FONCTION
         		ON		FONCTION.ID_FONCTION = NR31.ID_FONCTION
         		WHERE	NR31.ID_CONTACT = @ID_CONTACT
         		AND		NR31.ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         	-- /LDE 08/04/2013 14955
         	
         		
         		SELECT  DISTINCT INDIVIDU.NOM_INDIVIDU,
         						 INDIVIDU.PRENOM_INDIVIDU, 
         						 #TEMP_SESSION.NUM_FACTURE,					 
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		INTO	#TEMP_PIECES_INDIVIDUS
         		FROM	#TEMP_SESSION
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSION.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSION.ID_MODULE_PEC)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         				INNER JOIN INDIVIDU ON INDIVIDU.ID_INDIVIDU =STAGIAIRE_PEC.ID_INDIVIDU
         
         		WHERE		(PIECE_PEC.BLN_STAGIAIRE = 1)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         		ORDER BY	INDIVIDU.NOM_INDIVIDU,INDIVIDU.PRENOM_INDIVIDU;
         	
         
         			DECLARE @relance int
         
         			
         
         			IF EXISTS  ((SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_3 IS NOT NULL) UNION
         						(SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES_INDIVIDUS WHERE DAT_RELANCE_REGLE_3 IS NOT NULL))
         				BEGIN
         					set @relance = 4
         				END
         			ELSE
         				BEGIN
         					IF EXISTS ((SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_2 IS NOT NULL) UNION
         							   (SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES_INDIVIDUS WHERE DAT_RELANCE_REGLE_2 IS NOT NULL))
         						BEGIN
         							set @relance = 3
         						END
         					ELSE
         					BEGIN
         						IF EXISTS ((SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_1 IS NOT NULL) UNION 
         								   (SELECT ID_ARRIVEE_PIECE_PEC from #TEMP_PIECES_INDIVIDUS WHERE DAT_RELANCE_REGLE_1 IS NOT NULL))
         							BEGIN
         								set @relance = 2
         							END
         						ELSE
         							BEGIN
         								set @relance = 1
         							END
         					END
         			END;
         
         	
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_PEC_RELANCE_PIECE_REGLEMENT_ADH'
         	)
         	
         
         	SELECT
         		(
         		SELECT
         				@RaisonSociale as LIB_RAISON_SOCIALE,
         				(
         					SELECT
         						ISNULL(CONTACT_CIVILITE.LIBL_CIVILITE, '')
         					FROM
         						CIVILITE as CONTACT_CIVILITE
         					WHERE
         						CONTACT.ID_CIVILITE = CONTACT_CIVILITE.ID_CIVILITE
         					FOR XML AUTO, ELEMENTS, TYPE
         				),
         				isnull(CONTACT.LIB_NOM_CONTACT, '') as LIB_NOM_CONTACT,
         				case CONTACT.LIB_PNM_CONTACT 
         					when '.' then '' else isnull(CONTACT.LIB_PNM_CONTACT, '') end 
         				as LIB_PNM_CONTACT,
         				ADRESSE.LIB_ADR,
         				ISNULL(ADRESSE.LIB_COMP_VOIE, '') as LIB_COMP_VOIE,
         				ADRESSE.LIB_CP_CEDEX ,
         				ADRESSE.LIB_VIL_CEDEX
         			FROM
         					ADRESSE
         			left outer join	
         					CONTACT 
         			on		CONTACT.ID_CONTACT = @ID_CONTACT
         			and		CONTACT.lib_nom_contact <> '.'
         			and		CONTACT.lib_nom_contact not like 'contact%'
         			WHERE
         					ADRESSE.ID_ADRESSE = @ID_ADRESSE
         			FOR XML AUTO, ELEMENTS, TYPE
         			) as BENEFICIAIRE,
         	(
         
         		
         		
         		
         		SELECT	              	
         			
         			
         				ENTETE.COD_ADHERENT,
         				ENTETE.LIB_PRENOM_UTILISATEUR,
         				ENTETE.LIB_NOM_UTILISATEUR,
         				ENTETE.EMAIL,
         				-- R‚cup‚ration des informations sur l'‚metteur
         				(SELECT 
         					PARAMETRES.FAF_NAME		as NOM,
         					UTILISATEUR.LIB_ADR1		as ADRESSE1,
         					isnull(UTILISATEUR.LIB_ADR2, '') as ADRESSE2,					
         					UTILISATEUR.COD_POSTAL		as CP,
         					UTILISATEUR.LIB_VILLE		as VILLE,
         					SUBSTRING(NUM_TEL, 1,2) +'.' 
         					+ SUBSTRING(NUM_TEL, 3,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 5,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 7,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 9,2)	as TEL
         				FROM
         					UTILISATEUR
         					CROSS JOIN PARAMETRES 
         				WHERE
         					UTILISATEUR.ID_UTILISATEUR = ENTETE.ID_UTIL
         			FOR XML PATH('EMETTEUR'), TYPE) as EMETTEUR,
         				rtrim(case when patindex('%CEDEX%', ENTETE.LIB_VILLE) <> 0 then left(ENTETE.LIB_VILLE, patindex('%CEDEX%', ENTETE.LIB_VILLE)-1) else ENTETE.LIB_VILLE end) as LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         				dbo.GetFullDate(getDate()) as DATE,
         				ENTETE.COD_SESSION_PEC as NUM_REFERENCE,
         				@relance as NUM_RELANCE,
         				(
         					SELECT top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         					FROM CIVILITE
         					FOR XML PATH('POLITESSE_HAUT'), TYPE
         				)
         		FROM #TEMP_REFERENCE AS ENTETE     
         		FOR XML AUTO, ELEMENTS, TYPE
         	),
         
         	(
         		
         		
         		
         		SELECT
         			(
         				-- Informations sur le module-----------------------------------
         				SELECT	MODULE.LIBL_MODULE_PEC,
         						COALESCE(dbo.GetFrenchCurrencyFormat(CAST(MODULE.NUM_DUREE_HEURE as MONEY)), ' ') as DUREE,
         						CONVERT(varchar(10),MODULE.DAT_DEBUT, 103) AS DAT_DEBUT, --DATE DEBUT SESSION
         						CONVERT(varchar(10),MODULE.DAT_FIN, 103) AS DAT_FIN, --DATE FIN FESSION
         						MODULE.LIB_RAISON_SOCIALE AS RAISON_SOCIALE_OF
         				FROM #TEMP AS MODULE
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			(
         				SELECT	TOP 1 INDIVIDU.PRENOM_INDIVIDU + ' ' + INDIVIDU.NOM_INDIVIDU
         				FROM	INDIVIDU 
         				JOIN	STAGIAIRE_PEC ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				JOIN	SESSION_PEC ON STAGIAIRE_PEC.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         				JOIN	ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         				JOIN	ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         				WHERE	SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC
         				ORDER BY INDIVIDU.NOM_INDIVIDU,INDIVIDU.PRENOM_INDIVIDU
         				FOR XML RAW('STAGIAIRE'), ELEMENTS, TYPE
         			),
         			 (SELECT
         				(SELECT	LIB_EDT_DEB_MOTIF_NON_CONFORM_PIECE AS LIB_DEBUT,
         					LIB_EDT_FIN_MOTIF_NON_CONFORM_PIECE AS LIB_FIN
         						FROM    #TEMP_PIECES
         						JOIN	NR210 ON #TEMP_PIECES.ID_ARRIVEE_PIECE_PEC = NR210.ID_ARRIVEE_PIECE_PEC
         						JOIN	MOTIF_NON_CONFORM_PIECE ON NR210.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE AND MOTIF_NON_CONFORM_PIECE.BLN_ADH = 1
         						FOR XML RAW('PIECE'),ELEMENTS, TYPE)
         				FOR XML RAW('PIECES_NON_CONFORMES'),ELEMENTS, TYPE)
         			,
         			(
         				SELECT	top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         				FROM CIVILITE
         				FOR XML PATH('POLITESSE_BAS'), TYPE
         			)
         
         		FROM #TEMP_REFERENCE AS CORPS     
         		FOR XML AUTO, ELEMENTS, TYPE
         	)
         
         	FROM	#TEMP_REFERENCE as LETTRE
         	FOR XML AUTO, ELEMENTS
         END

GO
         create PROCEDURE [dbo].[EDI_TRANSCO_INS_TABLE_CONCERNEE]
         /* 
           Ajout d'une nouvelle table pour gestion de transcodification EDI 
         */  
         @COD_TABLE_FAF		VARCHAR(255),
         @ID_TABLE_FAF_DEFAUT	INTEGER
         AS
         
         BEGIN
         SET ROWCOUNT 0
         SET NOCOUNT ON
         
         	INSERT INTO EDI_TRANSCO_TABLE_CONCERNEE 
         	(
         	COD_TABLE_FAF		,
         	ID_TABLE_FAF_DEFAUT	
         	)
         	VALUES
         	(
         	@COD_TABLE_FAF		,
         	@ID_TABLE_FAF_DEFAUT	
         	)
         
         END  
         
GO

 -- =============================================
         -- Author	: KW
         -- Date		: XX XX 2007
         -- Comment	: Cr‚ation
         -- =============================================
         -- Author	: SV
         -- Date		: 21 ao–t 2007
         -- Comment	: Ajout d'une association entre le poste de co–t regl‚ et son adh‚rent
         --			  Ajout d'un filtre de maniŠre … ne pas relancer les piŠces module et session pour chaque facture
         --			  Suppression des piŠces purement stagiaire car elles sont g‚r‚es par les piŠces module
         -- =============================================
         -- Author	: AMA
         -- Date		: 15 Mai 2008
         -- Comment	: Changement de taille pour COD_SESSION_PEC (passe de 12 … 17 caractŠres)
         -- =============================================
         -- Author	: SBRU
         -- Date		: 27/05/2008
         -- Comment	: La partie Emetteur est renseign‚e … partir de la fonction GetXmlAdrChargeRelation (au lieu de GetXmlAgenceContact)
         -- =============================================
         -- Le 05/03/09 par SBRU - Adaptation gabarit suite au groupe de travail sur les ‚ditions
         -- =============================================
         -- DSZ 20/09/2012 : 13697 : num tel dynamique
         -- =============================================
         -- LDE 08/04/2013 14987: DNE - Processus de relance rŠglement (3) - Modele d'‚dition lettre_pec_relance_reglement OF
         -- =============================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_RELANCE_PIECE_REGLEMENT_OF]
         	@ID_ETABLISSEMENT int,
         	@ID_BENEFICIAIRE int,
         	@TYPE_BENEFICIAIRE int,
         	@ID_ADRESSE int,
         	@ID_CONTACT int,
         	@COD_SESSION_PEC varchar(17),
         	@ID_UTILISATEUR int
         AS
         
         BEGIN
         
         	-- Contact principal par d‚faut mais pas de "."
         	IF @ID_CONTACT IS NULL
         	SELECT @ID_CONTACT = NR31.ID_CONTACT
         	FROM NR31
         		INNER JOIN CONTACT ON CONTACT.ID_CONTACT = NR31.ID_CONTACT
         	WHERE BLN_PRINCIPAL = 1
         		AND BLN_ACTIF = 1
         		AND ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         		AND CONTACT.LIB_NOM_CONTACT <> '.';
         
         		
         		-- Si action individuelle: CR de l'‚tablissement et CM de l'‚tablissement
         		-- Si action collective: CR = CM = responsable des actions collectives renseign‚ dans le champ CM au niveau de l'action
         		select	distinct
         				organisme_formation.cod_of,
         				module_pec.cod_module_pec,
         				module_pec.num_interne,
         				session_pec.id_session_pec,
         				session_pec.cod_session_pec,
         				ADHERENT.COD_ADHERENT,
         				CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         				CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         				CR.ID_UTILISATEUR	as ID_UTIL,
         				CR.LIB_PNM			as LIB_PRENOM_UTILISATEUR,
         				CR.LIB_NOM			as LIB_NOM_UTILISATEUR,
         				CR.EMAIL			as EMAIL_UTILISATEUR,
         				CR.LIB_VILLE,
         				etablissement.num_siret as SIRET,
         				ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         				ETABLISSEMENT_OF.LIB_ENSEIGNE AS ENSEIGNE_ETAB
         		into	#TEMP_REFERENCE
         		from	organisme_formation
         		join	etablissement_of
         		on		organisme_formation.id_of = etablissement_of.id_of
         		join	module_pec
         		on		module_pec.id_etablissement_of = etablissement_of.id_etablissement_of
         		join	session_pec
         		on		session_pec.id_module_pec = module_pec.id_module_pec
         		join	NR140
         		on		module_pec.id_action_pec = NR140.id_action_pec
         		join	etablissement
         		on		NR140.id_etablissement = etablissement.id_etablissement
         		join	action_pec
         		on		NR140.id_action_pec = action_pec.id_action_pec
         		join	adherent
         		on		etablissement.id_adherent = adherent.id_adherent
         		left join UTILISATEUR AS CR ON CR.ID_UTILISATEUR = @ID_UTILISATEUR
         		left join
         				utilisateur CM -- charg‚ de mission ou responsable des actions collectives
         		on		case when (action_pec.cible_action = 1 or action_pec.bln_reprise_adhoc = 1)
         					 then etablissement.id_chargee_mission
         					 else action_pec.id_chargee_mission
         				end = CM.id_utilisateur
         
         		where	session_pec.cod_session_pec = @COD_SESSION_PEC
         
         
         	
         	SELECT	MODULE_PEC.ID_MODULE_PEC,
         			--MODULE_PEC.COD_MODULE_PEC, 
         			MODULE_PEC.LIBL_MODULE_PEC, 
         			--MODULE_PEC.DAT_DEBUT,
         			--MODULE_PEC.DAT_FIN,
         			--MODULE_PEC.NUM_DUREE_HEURE,
         			SESSION_PEC.ID_SESSION_PEC,
         			SESSION_PEC.COD_SESSION_PEC,
         			SESSION_PEC.DAT_DEBUT,
         			SESSION_PEC.DAT_FIN,
         			SESSION_PEC.NUM_DUREE_JOUR,
         			SESSION_PEC.NUM_DUREE_HEURE
         	INTO	#TEMP_SESSION
         	FROM	MODULE_PEC
         	JOIN	SESSION_PEC 
         	ON		MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC
         	WHERE   SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC;
         
         
         	SELECT  DISTINCT    MODULE_PEC.ID_MODULE_PEC,
         						-- MODULE_PEC.COD_MODULE_PEC, 
         						 MODULE_PEC.LIBL_MODULE_PEC, 
         						-- MODULE_PEC.DAT_DEBUT,
         						 --MODULE_PEC.DAT_FIN,
         						 --MODULE_PEC.NUM_DUREE_HEURE,
         						 SESSION_PEC.ID_SESSION_PEC,
         						 SESSION_PEC.COD_SESSION_PEC,
         						 SESSION_PEC.DAT_DEBUT,
         						 SESSION_PEC.DAT_FIN,
         						 SESSION_PEC.NUM_DUREE_JOUR,
         						 SESSION_PEC.NUM_DUREE_HEURE,
         						 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         						 POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE,
         						 POSTE_COUT_REGLE.NUM_FACTURE,
         						 STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         						 ADHERENT.ID_ADHERENT,
         						 ADHERENT.COD_ADHERENT
         
         		INTO	#TEMP_LISTE
         		FROM	MODULE_PEC
         		JOIN	SESSION_PEC 
         		ON		MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC				
         		JOIN	STAGIAIRE_PEC 
         		ON		SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         		JOIN	ETABLISSEMENT 
         		ON		STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         		JOIN	ADHERENT 
         		ON		ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         		JOIN	POSTE_COUT_REGLE 
         		ON		MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		AND		(
         				POSTE_COUT_REGLE.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
         				OR POSTE_COUT_REGLE.ID_ETABLISSEMENT is null
         				)
         		JOIN	ETABLISSEMENT_OF 
         		ON		MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         
         		WHERE		(MODULE_PEC.BLN_ACTIF = 1)
         				AND (SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC)
         				AND (POSTE_COUT_REGLE.BLN_ACTIF = 1)
         				AND ((MODULE_PEC.BLN_OK_PIECE = 0) OR (POSTE_COUT_REGLE.BLN_OK_PIECE = 0))
         				AND (ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT)
         	
         		-- Poste co–t regl‚
         		SELECT  DISTINCT #TEMP_LISTE.NUM_FACTURE,
         						 #TEMP_LISTE.COD_ADHERENT as COD_ADHERENT,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		INTO	#TEMP_PIECES
         		FROM    #TEMP_LISTE 
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_LISTE.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_LISTE.ID_MODULE_PEC)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_LISTE.ID_MODULE_PEC										
         				
         		WHERE		(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         				AND (#TEMP_LISTE.BLN_FACTURE_DIRECTE = 1)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         				AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         		UNION
         		-- Session
         		SELECT  DISTINCT null,--#TEMP_LISTE.NUM_FACTURE,
         						 #TEMP_LISTE.COD_ADHERENT as COD_ADHERENT,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		FROM    #TEMP_LISTE 
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_LISTE.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_LISTE.ID_MODULE_PEC)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_LISTE.ID_MODULE_PEC										
         				
         		WHERE		(PIECE_PEC.BLN_SESSION = 1)
         				AND (#TEMP_LISTE.BLN_FACTURE_DIRECTE = 1)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         				AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         		UNION
         		-- Module
         		SELECT  DISTINCT null,--#TEMP_LISTE.NUM_FACTURE,
         						 #TEMP_LISTE.COD_ADHERENT as COD_ADHERENT,
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         
         		FROM    #TEMP_LISTE
         				INNER JOIN ARRIVEE_PIECE_PEC	ON #TEMP_LISTE.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC 
         				INNER JOIN PIECE_PEC			ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         													AND (PIECE_PEC.BLN_STAGIAIRE = 0)
         													--AND (PIECE_PEC.BLN_ADHERENT = 0)
         				
         		WHERE		(PIECE_PEC.BLN_MODULE = 1)
         				AND (#TEMP_LISTE.BLN_FACTURE_DIRECTE = 1)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         				AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	
         		
         		SELECT  DISTINCT INDIVIDU.NOM_INDIVIDU,
         						 INDIVIDU.PRENOM_INDIVIDU, 
         						 #TEMP_LISTE.NUM_FACTURE,
         						 #TEMP_LISTE.COD_ADHERENT,						 
         						 PIECE_PEC.LIBL_PIECE_PEC,
         						 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         						 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         						 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3
         		INTO	#TEMP_PIECES_INDIVIDUS
         		FROM	#TEMP_LISTE
         				INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_LISTE.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         												AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_LISTE.ID_MODULE_PEC)
         				INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         				INNER JOIN STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC
         				INNER JOIN INDIVIDU ON INDIVIDU.ID_INDIVIDU =STAGIAIRE_PEC.ID_INDIVIDU
         
         		WHERE		(PIECE_PEC.BLN_STAGIAIRE = 1)
         				AND (PIECE_PEC.BLN_ACTIF = 1)
         				AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         				AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         		ORDER BY	INDIVIDU.NOM_INDIVIDU,INDIVIDU.PRENOM_INDIVIDU;
         
         	
         	
         
         			DECLARE @relance int
         
         			IF (EXISTS (SELECT * from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_3 IS NOT NULL))
         				BEGIN
         					set @relance = 4
         				END
         			ELSE
         				BEGIN
         					IF (EXISTS (SELECT * from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_2 IS NOT NULL))
         						BEGIN
         							set @relance = 3
         						END
         					ELSE
         					BEGIN
         						IF (EXISTS (SELECT * from #TEMP_PIECES WHERE DAT_RELANCE_REGLE_1 IS NOT NULL))
         							BEGIN
         								set @relance = 2
         							END
         						ELSE
         							BEGIN
         								set @relance = 1
         							END
         					END
         			END;
         			
         	-- LDE 08/04/2013 14987
         	-- Reprise GetXmlBenefiaireContact car modifications n‚cessaires dans ce bloc pour cette ‚dition
         	DECLARE @LibelleFonction varchar(50)
         	DECLARE @RaisonSociale varchar(64)
         	
         	SELECT	@RaisonSociale = ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         		FROM	ETABLISSEMENT_OF
         		JOIN	ORGANISME_FORMATION
         		ON		ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         		WHERE	ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_BENEFICIAIRE
         		
         	SELECT	@LibelleFonction = FONCTION.LIBL_FONCTION
         		FROM	NR34
         		LEFT JOIN
         				FONCTION
         		ON		FONCTION.ID_FONCTION = NR34.ID_FONCTION
         		WHERE	NR34.ID_CONTACT = @ID_CONTACT
         		AND		NR34.ID_ETABLISSEMENT_OF = @ID_BENEFICIAIRE
         	-- /LDE 08/04/2013 14987
         	
         	select 1 as col into #ONE_LIGNE;
         
         		
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_PEC_RELANCE_PIECE_REGLEMENT_OF'
         	)
         	
         			
         	SELECT
         		-- R‚cup‚ration des informations sur le contact et le b‚n‚ficiaire
         		(
         		SELECT
         				@RaisonSociale as LIB_RAISON_SOCIALE,
         				(
         					SELECT
         						ISNULL(CONTACT_CIVILITE.LIBL_CIVILITE, '')
         					FROM
         						CIVILITE as CONTACT_CIVILITE
         					WHERE
         						CONTACT.ID_CIVILITE = CONTACT_CIVILITE.ID_CIVILITE
         					FOR XML AUTO, ELEMENTS, TYPE
         				),
         				isnull(CONTACT.LIB_NOM_CONTACT, '') as LIB_NOM_CONTACT,
         				case CONTACT.LIB_PNM_CONTACT 
         					when '.' then '' else isnull(CONTACT.LIB_PNM_CONTACT, '') end 
         				as LIB_PNM_CONTACT,
         				ADRESSE.LIB_ADR,
         				ISNULL(ADRESSE.LIB_COMP_VOIE, '') as LIB_COMP_VOIE,
         				ADRESSE.LIB_CP_CEDEX ,
         				ADRESSE.LIB_VIL_CEDEX
         			FROM
         					ADRESSE
         			left outer join	
         					CONTACT 
         			on		CONTACT.ID_CONTACT = @ID_CONTACT
         			and		CONTACT.lib_nom_contact <> '.'
         			and		CONTACT.lib_nom_contact not like 'contact%'
         			WHERE
         					ADRESSE.ID_ADRESSE = @ID_ADRESSE
         			FOR XML AUTO, ELEMENTS, TYPE
         			) as BENEFICIAIRE,
         
         		
         		
         		
         		(
         			SELECT	              	
         
         						isnull(COD_OF, '')					as COD_OF,
         						isnull(LIB_PRENOM_UTILISATEUR, '')	as LIB_PRENOM_UTILISATEUR,
         						isnull(LIB_NOM_UTILISATEUR, '')		as LIB_NOM_UTILISATEUR,
         						isnull(EMAIL_UTILISATEUR, '')		as EMAIL,
         
         				-- R‚cup‚ration des informations sur l'‚metteur
         				(SELECT 
         					PARAMETRES.FAF_NAME		as NOM,
         					UTILISATEUR.LIB_ADR1		as ADRESSE1,
         					isnull(UTILISATEUR.LIB_ADR2, '') as ADRESSE2,					
         					UTILISATEUR.COD_POSTAL		as CP,
         					UTILISATEUR.LIB_VILLE		as VILLE,
         					SUBSTRING(NUM_TEL, 1,2) +'.' 
         					+ SUBSTRING(NUM_TEL, 3,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 5,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 7,2)+'.' +
         					+ SUBSTRING(NUM_TEL, 9,2)	as TEL
         				FROM
         					UTILISATEUR
         					CROSS JOIN PARAMETRES 
         				WHERE
         					UTILISATEUR.ID_UTILISATEUR = ENTETE.ID_UTIL
         			FOR XML PATH('EMETTEUR'), TYPE) as EMETTEUR,
         
         							rtrim(case when patindex('%CEDEX%', LIB_VILLE) <> 0 then left(LIB_VILLE, patindex('%CEDEX%', LIB_VILLE)-1) else LIB_VILLE end) as LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         							dbo.GetFullDate(getDate()) as DATE,
         							COD_SESSION_PEC AS NUM_REFERENCE,
         							ENSEIGNE_ETAB,
         							@relance as NUM_RELANCE,
         							(
         								SELECT top 1
         									dbo.GetContactSalutation(@ID_CONTACT, 1)
         								FROM CIVILITE
         								FOR XML PATH('POLITESSE_HAUT'), TYPE
         							)
         			FROM #TEMP_REFERENCE AS ENTETE     
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         		(
         			
         			
         			
         			SELECT	CORPS.LIBL_MODULE_PEC,
         					Cast((CORPS.NUM_DUREE_HEURE) as decimal(10,2))	AS DUREE,
         					CONVERT(varchar(10),CORPS.DAT_DEBUT, 103)		AS DAT_DEBUT,
         					CONVERT(varchar(10),CORPS.DAT_FIN, 103)			AS DAT_FIN,
         					(
         						SELECT	TOP 1 INDIVIDU.PRENOM_INDIVIDU + ' ' + INDIVIDU.NOM_INDIVIDU
         						FROM	INDIVIDU 
         						JOIN	STAGIAIRE_PEC ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         						JOIN	SESSION_PEC ON STAGIAIRE_PEC.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         						JOIN	ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         						JOIN	ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         						WHERE	SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC
         						ORDER BY INDIVIDU.NOM_INDIVIDU,INDIVIDU.PRENOM_INDIVIDU
         						FOR XML RAW('STAGIAIRE'), ELEMENTS, TYPE
         					),
         				(SELECT (SELECT	LIB_EDT_DEB_MOTIF_NON_CONFORM_PIECE AS LIB_DEBUT,
         					LIB_EDT_FIN_MOTIF_NON_CONFORM_PIECE AS LIB_FIN
         						FROM    #TEMP_PIECES
         						JOIN	NR210 ON #TEMP_PIECES.ID_ARRIVEE_PIECE_PEC = NR210.ID_ARRIVEE_PIECE_PEC
         						JOIN	MOTIF_NON_CONFORM_PIECE ON NR210.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE AND MOTIF_NON_CONFORM_PIECE.BLN_OF = 1
         						FOR XML RAW('PIECE'),ELEMENTS, TYPE)
         				FOR XML RAW('PIECES_NON_CONFORMES'),ELEMENTS, TYPE),
         					(
         					SELECT	top 1
         							dbo.GetContactSalutation(@ID_CONTACT, 1)
         					FROM CIVILITE
         					FOR XML PATH('POLITESSE_BAS'), TYPE
         					)
         
         			FROM #TEMP_SESSION AS CORPS     
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         
         		(
         			
         			
         			
         			SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         					SIGNATURE.LIB_NOM_CONSEILLER
         			FROM
         					#TEMP_REFERENCE as SIGNATURE
         			FOR XML AUTO, ELEMENTS, TYPE
         		)
         		
         
         	FROM	#TEMP_SESSION as LETTRE
         	FOR XML AUTO, ELEMENTS
         END

