         create PROCEDURE [dbo].[EDI_TRANSCO_INS_COD_EXTERNE]
         /* Insertion d'un code externe du rfrentiel FAF pour :
         	- un adhrent ou un groupe
         	- une table
         	- un code externe adherent	
         */
         (
         @ID_ADHERENT 		INTEGER		,
         @ID_GROUPE 		INTEGER		,
         @COD_TABLE_FAF		VARCHAR(255)	,
         @COD_EXTERNE_ADHERENT	VARCHAR(255)	,
         @ID_FAF			INTEGER		
         )
         AS
         BEGIN
         
         	INSERT INTO EDI_TRANSCO_TABLE_ADHERENT
         	(	ID_ADHERENT 		,
         		ID_GROUPE 		,
         		COD_TABLE_FAF		,
         		COD_EXTERNE_ADHERENT	,
         		ID_TABLE_FAF		
         	)
         	VALUES
         	(	@ID_ADHERENT 		,
         		@ID_GROUPE 		,
         		@COD_TABLE_FAF		,
         		@COD_EXTERNE_ADHERENT	,
         		@ID_FAF		
         	)
         END
         

