CREATE PROCEDURE [dbo].[UPD_ACTION_PRISES]  
          @ID_ACTION INT,  
          @LIBL_ACTION VARCHAR(250),  
          @ID_THEME int,  
          @ID_NIVEAU int,
          @ID_SANCTION int,
          @DAT_DEBUT DATETIME,  
          @DAT_FIN DATETIME,  
          @DUREE_JOUR decimal(18,2),
          @DUREE_HEURS decimal(18,2),
          @ID_UTILISATEUR INT,
          @ID_OPERATION INT,
          @CIBLE_ACTION INT,
          @BLN_ACTIF INT,
          @ID_AGENCE INT,
          @CYCLE_COURT INT,
          @COM_ACTION VARCHAR(255),
          @ID_FORMACODE INT,
          @TIME_STAMP TIMESTAMP,
          @DAT_RECU datetime,
          @ID_DECISION_ACTION_PEC int,
          @AXE varchar(30),
          @DOMAINE varchar(30),
          @ID_CHARGEE_MISSION INT
         AS
         -- =======================================================================================================================================
         -- Author:  Dorota Szeliga
         -- Modif. date: 11/03/2008
         -- Description: C2P: Ajout @DAT_RECU, @ID_DECISION_ACTION_PEC,@AXE, @DOMAINE 
         --      Libl_action passe a 100 caracteres
         -- =======================================================================================================================================
         -- Author:  Dorota Szeliga
         -- Modif. date: 12/03/2008
         -- Description: C2P: Si Motif Refus (Decision) assigne, on met BLN_ACCORD a 0 (Refus)
         -- =======================================================================================================================================
         -- Author:  AMA
         -- Modif. date: 17/10/2008
         -- Description: correction de l'affectation de BLN_ACCORD
         -- =======================================================================================================================================
         -- Author:  AMA
         -- Modif. date: 07/10/2008
         -- Description: Suppression de la fin de la proc‚dure stock‚e car elle est inutile
         -- SLQSERVER d‚clechant un type d'exception plus pertient 
         -- =======================================================================================================================================
         -- Author: ASD & SAF pour r‚cup modif MB du 12/02/2008 pour C2P
         -- Modif. date: 18/03/2009
         -- Description: - Modification pour empecher de supprimer les mouvements budgetaires associes aux reglements
         -- =======================================================================================================================================
         -- Author: DSZ
         -- Modif. date: 19/05/2009
         -- Description: Mantis 11946. Faut remettre operation financiere a null si on passe 0
         -- =======================================================================================================================================
         -- Author: DSZ
         -- Modif. date: 19/05/2009
         -- Description: Mantis 11414. Recreer le plan financement si l'operation financiere a ete change
         -- =======================================================================================================================================
         -- Author: SAFI
         -- Modif. date: 31/12/2009
         -- Description: Evol 372,Mantis 12063
         -- L'inactivation d'un module ou d'une action doit au mˆme titre que la cl“ture 
         -- g‚n‚rer un mouvement budg‚taire d'annulation du pr‚visionnel 
         -- =======================================================================================================================================
         -- Author: DSZ
         -- Modif. date: 19/03/2010
         -- Description: 12307: ne pas toucher a BLN_OK_FINANCEMENT des modules engag‚s
         -- =======================================================================================================================================
         -- SAFI AJOUTER 11/10/2010 : 0012474 
         -- Description: Inactivation de Action, inactive all the modules in it
         -- =======================================================================================================================================
         -- Author: DSZ
         -- Modif. date: 06/01/2011
         -- Description: 12258: SFD _PEC 2.33 du 23/12/2010
          --D‚clenchement de l'annulation de mouvements P
          --- Pour tous les stagiaires de l'action :
          -- Cible de l'action (action indiv., AIC, AC)
          -- Op‚ration financiŠre
          -- L'antenne de l'action
          --- Pour les stagiaires de l'adh‚rent ou l'‚tablissement ayant ‚t‚ remplac‚
          -- L'adh‚rent ou l'‚tablissement
          --on trouve tous les mouvements budg‚taires type P associ‚s et on cr‚e les mouvements type P (cod type 19) avec le mˆme montant et signe n‚gatif.
         -- =======================================================================================================================================
         -- DSZ 05/04/2011 12736
         -- renommage procedure ACTION_CREER_MVTS_INVERSES => ACTION_CREER_MVTS_P_INVERSES
         -- =======================================================================================================================================
         -- DSZ 09/12/2011 13040
         --  proc GET_OPTION_PLAN10_POUR_UNITE_STAG EST devenue function table GET_OPTION_PLAN_POUR_UNITE_STAG
         -- =======================================================================================================================================
         -- DSZ 21/03/2013 correction d'appel … ACTION_ENGAGED
         -- =======================================================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================
         -- DSZ 04/11/2013 : 16330:  BLN_VISIBLE_PANIERS ‚gal … @BLN_ACTIF
         -- =======================================================================================================================================
         -- LDE 04/08/2014 148E: Suppression Annulation (INS_MVT_BUDGETAIRE_INACTIVE_ACTION_PEC)
         -- =======================================================================================================================================
         -- HBO - 20140804 #147
         -- =======================================================================================================================================
         -- HBO - 20140806 #149
         -- =======================================================================================================================================
         -- HBO - 20140903 #481
         -- =======================================================================================================================================
         -- DSZ - 205/04/22 #827 suppression d'appel … GET_OPTION_PLAN_POUR_UNITE_STAG
         -- =======================================================================================================================================
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250)
         -- =======================================================================================================================================
         BEGIN
          -- Variable declaration
         
          DECLARE
           @OLD_ID_OPERATION INT,
           @OLD_ID_AGENCE INT,
           @OLD_CIBLE_ACTION INT,
           @RECREATE_PLAN_FINANCEMENT TINYINT,
           @BLN_ACTIF_STATUS_BEFORE_UPDATE INT
         
          SET @RECREATE_PLAN_FINANCEMENT = 0
         
          SELECT
           @BLN_ACTIF_STATUS_BEFORE_UPDATE = BLN_ACTIF
          FROM
           ACTION_PEC
          WHERE
           ID_ACTION_PEC = @ID_ACTION
         
          -- Initialitation variables
         
          IF(@CYCLE_COURT IS NULL)
          BEGIN
           SET @CYCLE_COURT = 0
          END
         
          IF(@ID_OPERATION = 0)
          BEGIN
           SET @ID_OPERATION = NULL
          END
         
          -- Load old values
          SELECT 
           @OLD_ID_OPERATION = ID_OPERATION_FINANCIERE,
           @OLD_ID_AGENCE  = ID_AGENCE,
           @OLD_CIBLE_ACTION = CIBLE_ACTION
          FROM 
           ACTION_PEC
          WHERE
           ID_ACTION_PEC = @ID_ACTION
         
          -- Management Changed Operation FINANCEUR OR BLN_CYCLE_COURT
          DECLARE @ENGAGED INT
          -- @ENGAGED > 0 NOT MODIFIABLE
          -- @ENGAGED = 0 MODIFIABLE
         
          EXEC @ENGAGED = ACTION_ENGAGED
           @ID_ACTION,
           @ID_MODULE = NULL
         
          UPDATE
           POSTE_COUT_ENGAGE
          SET
           BLN_OK_FINANCEMENT = 0
          WHERE
           ID_MODULE_PEC IN 
           (
            SELECT
             ID_MODULE_PEC
            FROM
             MODULE_PEC
            WHERE
             ID_ACTION_PEC = @ID_ACTION
           )
           AND DAT_DESENGAGEMENT IS NULL
           AND ID_ENGAGEMENT IS NULL 
         
          IF(@ENGAGED = 0)
          BEGIN
           IF (@OLD_ID_OPERATION <> @ID_OPERATION
            OR @OLD_ID_AGENCE  <> @ID_AGENCE
            OR @OLD_CIBLE_ACTION <> @CIBLE_ACTION)
           BEGIN
            --flag pour recreer plan financement, voir a la fin
            SET @RECREATE_PLAN_FINANCEMENT = 1
           END
          END --@ENGAGED = 0
         
          -- BLN_ACCORD
          DECLARE @BLN_ACCORD TINYINT
          SET @BLN_ACCORD = NULL
          IF (@ID_DECISION_ACTION_PEC IS NULL OR @ID_DECISION_ACTION_PEC = 1)
          BEGIN
           SET @BLN_ACCORD = 1
          END
          ELSE
          BEGIN
           SET @BLN_ACCORD = 0
          END
         
          -- Update table Action_PEC
          UPDATE ACTION_PEC SET
           LIBL_ACTION_PEC = @LIBL_ACTION,
           ID_THEME = @ID_THEME,  
           ID_NIVEAU = @ID_NIVEAU,  
           ID_SANCTION = @ID_SANCTION,  
           ID_OPERATION_FINANCIERE = @ID_OPERATION,  
           ID_AGENCE = @ID_AGENCE,  
           DAT_DEB_ACTION_PEC = @DAT_DEBUT, 
           DAT_FIN_ACTION_PEC = @DAT_FIN,
           BLN_ACTIF = @BLN_ACTIF,
           DAT_MODIF = GETDATE(),
           NUM_DUREE_JOUR = @DUREE_JOUR,
           NUM_DUREE_HEURE = @DUREE_HEURS,
           CIBLE_ACTION = @CIBLE_ACTION,
           ID_UTILISATEUR = @ID_UTILISATEUR,
           BLN_CYCLE_COURT = @CYCLE_COURT,
           COM_ACTION_PEC = @COM_ACTION,
           ID_FORMACODE = @ID_FORMACODE,
           DAT_RECU = @DAT_RECU,
           ID_DECISION_ACTION_PEC = @ID_DECISION_ACTION_PEC,
           AXE = @AXE,
           DOMAINE = @DOMAINE,
           BLN_ACCORD = @BLN_ACCORD,
           ID_CHARGEE_MISSION = @ID_CHARGEE_MISSION,
           BLN_VISIBLE_PANIERS = @BLN_ACTIF --16330
          FROM 
           ACTION_PEC
          WHERE 
           ID_ACTION_PEC  = @ID_ACTION 
         
          IF(@BLN_ACTIF = 0)
          BEGIN
           EXEC dbo.DEL_EXPORT_D3R
            @ID_ACTION,
            'PEC'
          END
         
          IF (@RECREATE_PLAN_FINANCEMENT = 1)
          BEGIN
           DECLARE @id_us int
           DECLARE @id_dispo int 
           DECLARE @id_periode int 
           DECLARE @id_module int 
           DECLARE @id_pce int 
           DECLARE @BLN_PLAN bit
         
         
           DECLARE US_cursor CURSOR FOR
           SELECT UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE, 
             UNITE_STAGIAIRE.ID_DISPOSITIF,
             MODULE_PEC.ID_PERIODE,
             MODULE_PEC.ID_MODULE_PEC,
             ID_POSTE_COUT_ENGAGE,
             STAGIAIRE_PEC.ID_ETABLISSEMENT
           FROM UNITE_STAGIAIRE 
            inner join STAGIAIRE_PEC on UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
            inner join MODULE_PEC on MODULE_PEC.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC
            inner join POSTE_COUT_ENGAGE on POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           WHERE
            MODULE_PEC.ID_ACTION_PEC = @ID_ACTION 
            and STAGIAIRE_PEC.ID_SESSION_PEC is NULL
            and (isnull(UNITE_STAGIAIRE.MNT_ENGAGE_HT,0) >0 or
               isnull(UNITE_STAGIAIRE.NB_HEURE_ENGAGE,0) >0)
         
           OPEN US_cursor
           FETCH NEXT FROM US_cursor INTO @id_us, @id_dispo, @id_periode, @id_module, @id_pce
           WHILE @@FETCH_STATUS = 0
           BEGIN
            set @BLN_PLAN = 1
            if @ID_PERIODE < 19
             SELECT  @BLN_PLAN =  
                case 
              when (STAGIAIRE_PEC.ID_ACTIVITE = 2) then 0 
              when STAGIAIRE_PEC.ID_ACTIVITE  is null then 
               case when (R19.ID_ACTIVITE = 2) then 0 else 1 end
              else 1 end 
              from UNITE_STAGIAIRE
               inner join STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC 
               inner join ETABLISSEMENT on (STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT)
               left join R19 ON (R19.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT 
                 and R19.ID_PERIODE = @ID_PERIODE
                 and R19.ID_ACTIVITE in ( select id_activite from GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN')) --14822)
                 ) 
             where UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = @id_us
         
            exec dbo.INS_PLAN_FINANCEMENT_US 
              @ID_UNITE_STAGIAIRE=@id_us,
              @ID_POSTE_COUT_ENGAGE=@id_pce, 
              @ID_DISPOSITIF=@id_dispo,
              @ID_MODULE=@id_module,
              @BLN_PLUS10=@BLN_PLAN,
              @HOURS_ALL=NULL,
              @HOURS_STAGIAIRE=NULL,
              @MNT_POSTE_COUT_ENGAGE=NULL,
              @HOURS_US=NULL,
              @BLN_MODIFICATION=0
         
            FETCH NEXT FROM US_cursor INTO @id_us, @id_dispo, @id_periode, @id_module, @id_pce
            
           END
           CLOSE US_cursor
           DEALLOCATE US_cursor
          END --@RECREATE_PLAN_FINANCEMENT
         
          IF(@BLN_ACTIF = 0 AND @BLN_ACTIF_STATUS_BEFORE_UPDATE = 1)
          BEGIN
           UPDATE
            MODULE_PEC
           SET
            BLN_ACTIF = 0
           WHERE
            ID_ACTION_PEC = @ID_ACTION
         
           -- #141 : Recablage Desengagement
           DECLARE
            @EventTypeId INT,
            @EventName VARCHAR(50),
            @EventDate DATETIME,
            @EventComment VARCHAR(7600)
           
           SELECT
            @EventTypeId = ID_TYPE_EVENEMENT,
            @EventName = LIBL_TYPE_EVENEMENT
           FROM
            TYPE_EVENEMENT
           WHERE
            COD_TYPE_EVENEMENT = 'ANNULATI'
         
           SET @EventComment = 'Origine : Annulation Action PEC OPTIFORM'
         
           DECLARE @ID_POSTE_COUT_ENGAGE INT
           DECLARE CURSOR_INCURRED_POST_COST CURSOR FOR
            SELECT
             PCE.ID_POSTE_COUT_ENGAGE
            FROM
             ACTION_PEC AP
             INNER JOIN MODULE_PEC MP
              ON MP.ID_ACTION_PEC = AP.ID_ACTION_PEC
             LEFT JOIN POSTE_COUT_ENGAGE PCE
              ON PCE.ID_MODULE_PEC = MP.ID_MODULE_PEC
            WHERE
             AP.ID_ACTION_PEC = @ID_ACTION
             AND PCE.ID_POSTE_COUT_ENGAGE IS NOT NULL
             AND PCE.DAT_DESENGAGEMENT IS NULL
            ORDER BY
             AP.ID_ACTION_PEC,
             MP.ID_MODULE_PEC,
             PCE.ID_SOUS_TYPE_COUT,
             PCE.ID_POSTE_COUT_ENGAGE
           
           OPEN CURSOR_INCURRED_POST_COST
           FETCH NEXT FROM CURSOR_INCURRED_POST_COST INTO
            @ID_POSTE_COUT_ENGAGE
         
           WHILE (@@Fetch_Status <> -1)
           BEGIN
            SET @EventDate = GETDATE()
            
            EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
             @EventName,
             @EventDate,
             @EventTypeId,
             @ID_POSTE_COUT_ENGAGE,
             NULL,
             @ID_UTILISATEUR,
             @EventComment
           
            FETCH NEXT FROM CURSOR_INCURRED_POST_COST INTO
             @ID_POSTE_COUT_ENGAGE
           END
         
           CLOSE CURSOR_INCURRED_POST_COST
           DEALLOCATE CURSOR_INCURRED_POST_COST
          END
         END

GO
 CREATE PROCEDURE [dbo].[GET_ACTIVITE_PAR_ADHERENTPERIODE]
         -- =============================================  
         -- Author:  SFEIR  
         -- Create date: 29/10/2014  
         -- Description: S‚lection des ACTVITE disponibles pour un ADHERENT et une PERIODE donn‚s.
         -- Remarques: Utilis‚e pour r‚cup‚rer les activit‚s possibles et effectivement utilis‚es
         --    par un adh‚rent et pour une p‚riode.
         -- =============================================
         -- HBO : #672 : Suppression de BLN_ACTIF = 1
         -- =============================================   
          @ID_PERIODE ID,
          @ID_ADHERENT ID
         AS
         BEGIN
          SET NOCOUNT ON;
          
          DECLARE @ACTIVITE TABLE (
           [ID_ACTIVITE] [dbo].[ID] NOT NULL PRIMARY KEY,
           [COD_ACTIVITE] [varchar](8) NULL,
           [LIBL_ACTIVITE] [varchar](60) NULL,
           [BLN_ACTIF] [tinyint] NOT NULL,
           [NUM_ORDRE] [int] NULL,
           [ID_TYPE_ACTIVITE] [int] NULL,
           [BLN_ACTIVITE_IN_PARAM] [bit] NOT NULL,
           [BLN_ACTIVITE_IN_R19] [bit] NOT NULL,
           [BLN_OBLIGATOIRE] [bit] NOT NULL
          )
         
          -- Insert des activit‚s param‚tr‚s dans le systŠme
          INSERT INTO
           @ACTIVITE
          SELECT
           ACTIVITE.ID_ACTIVITE,
           ACTIVITE.COD_ACTIVITE,
           ACTIVITE.LIBL_ACTIVITE,
           ACTIVITE.BLN_ACTIF,
           ACTIVITE.NUM_ORDRE,
           ACTIVITE.ID_TYPE_ACTIVITE,
           BLN_ACTIVITE_IN_PARAM = 1,
           BLN_ACTIVITE_IN_R19 = 0,
           PARAM_ACTIVITE_BRANCHE.BLN_OBLIGATOIRE
          FROM
           ADHERENT
           INNER JOIN R20
            ON R20.ID_ADHERENT = ADHERENT.ID_ADHERENT
             AND R20.ID_PERIODE = @ID_PERIODE
           INNER JOIN TYPE_ASSUJETISSEMENT
            ON TYPE_ASSUJETISSEMENT.ID_TYPE_ASSUJETISSEMENT = R20.ID_TYPE_ASSUJETISSEMENT
           INNER JOIN PARAM_ACTIVITE_BRANCHE
            ON PARAM_ACTIVITE_BRANCHE.ID_BRANCHE = ADHERENT.ID_BRANCHE
             AND PARAM_ACTIVITE_BRANCHE.ID_PERIODE = @ID_PERIODE
             AND PARAM_ACTIVITE_BRANCHE.ID_CHAMP_APPLICATION = TYPE_ASSUJETISSEMENT.ID_CHAMP_APPLICATION
             AND PARAM_ACTIVITE_BRANCHE.BLN_ACTIF = 1
           INNER JOIN ACTIVITE
            ON ACTIVITE.ID_ACTIVITE = PARAM_ACTIVITE_BRANCHE.ID_ACTIVITE
          WHERE
           ADHERENT.ID_ADHERENT = @ID_ADHERENT
         
          DECLARE @ACTIVITE_FROM_R19 TABLE (
           [ID_ACTIVITE] [dbo].[ID] NOT NULL PRIMARY KEY,
           [COD_ACTIVITE] [varchar](8) NULL,
           [LIBL_ACTIVITE] [varchar](60) NULL,
           [BLN_ACTIF] [tinyint] NOT NULL,
           [NUM_ORDRE] [int] NULL,
           [ID_TYPE_ACTIVITE] [int] NULL,
           [BLN_ACTIVITE_IN_PARAM] [bit] NOT NULL,
           [BLN_ACTIVITE_IN_R19] [bit] NOT NULL,
           [BLN_OBLIGATOIRE] [bit] NOT NULL
          )
         
          -- Insert des activit‚s actuellement utilis‚es dans le systŠme
          INSERT INTO
           @ACTIVITE_FROM_R19
          SELECT
           ACTIVITE.ID_ACTIVITE,
           ACTIVITE.COD_ACTIVITE,
           ACTIVITE.LIBL_ACTIVITE,
           ACTIVITE.BLN_ACTIF,
           ACTIVITE.NUM_ORDRE,
           ACTIVITE.ID_TYPE_ACTIVITE,
           BLN_ACTIVITE_IN_PARAM = 0,
           BLN_ACTIVITE_IN_R19 = 1,
           0
          FROM
           ACTIVITE
           INNER JOIN R19
            ON R19.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
             AND R19.ID_ADHERENT = @ID_ADHERENT
             AND R19.ID_PERIODE = @ID_PERIODE
         
          -- assignation du bool‚en R19 pour les activit‚s pr‚sentes dans les deux tables
          UPDATE
           @ACTIVITE
          SET
           BLN_ACTIVITE_IN_R19 = 1
          WHERE
           ID_ACTIVITE IN (SELECT ID_ACTIVITE FROM @ACTIVITE_FROM_R19)
         
          -- ajout des activit‚s pr‚sentes uniquement dans R19
          INSERT INTO
           @ACTIVITE
          SELECT
           *
          FROM
           @ACTIVITE_FROM_R19
          WHERE
           ID_ACTIVITE NOT IN (SELECT ID_ACTIVITE FROM @ACTIVITE)
         
          -- retour de la table de r‚sultat
          SELECT
           *
          FROM
           @ACTIVITE
          ORDER BY
           NUM_ORDRE
          RETURN
         END

