         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         ---------------------------------------------- 
         
         CREATE PROCEDURE [dbo].[LEC_GRP_LISTE_CRITERES]
         	@ID_SESSION int,
         	@ID_AGENCE int,
         	@ID_ADHERENT int,
         	@ID_OF int,
         	@ID_SOUS_TYPE_COUT int,
         	@MNT_TTC decimal(18,2),
         	@BLN_INFERIEUR bit,
         	@NOUVEAUX_OF bit
         
         AS
         BEGIN
         
         	IF @BLN_INFERIEUR IS NULL
         		SET @BLN_INFERIEUR = 0
         
         	SELECT
         		@ID_SESSION											AS ID_SESSION,
         		@ID_AGENCE											AS ID_AGENCE,
         		AGENCE.LIBL_AGENCE,
         		@ID_ADHERENT										AS ID_ADHERENT,
         		ISNULL(ADHERENT.LIB_RAISON_SOCIALE,'')				AS ADHERENT_RAISON_SOCIALE,
         		@ID_OF												AS ID_OF,
         		ISNULL(ORGANISME_FORMATION.LIB_RAISON_SOCIALE,'')	AS OF_RAISON_SOCIALE,
         		@ID_SOUS_TYPE_COUT									AS ID_SOUS_TYPE_COUT,
         		ISNULL(SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT, '')		AS LIBL_SOUS_TYPE_COUT,
         		CASE 
         			WHEN @BLN_INFERIEUR = 0 THEN 
         				'>= ' + @MNT_TTC
         			WHEN @BLN_INFERIEUR = 1 THEN
         				'< ' + @MNT_TTC
         		END													AS MONTANT,
         		@MNT_TTC											AS MNT_TTC,
         		@BLN_INFERIEUR										AS BLN_INFERIEUR,
         		@NOUVEAUX_OF										AS NOUVEAUX_OF,
         		COUNT(POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE)			AS NOMBRE_DOSSIERS
         		
         	FROM POSTE_COUT_REGLE
         	LEFT JOIN SESSION ON SESSION.ID_SESSION = POSTE_COUT_REGLE.ID_SESSION
         	LEFT JOIN AGENCE ON AGENCE.ID_AGENCE = SESSION.ID_AGENCE
         	LEFT JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	LEFT JOIN NR140 ON NR140.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	LEFT JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         	LEFT JOIN ADHERENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	LEFT JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         	LEFT JOIN ORGANISME_FORMATION ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         	LEFT JOIN SOUS_TYPE_COUT ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
         	LEFT JOIN (
         		SELECT PCR.ID_SESSION, COUNT(PCR.ID_POSTE_COUT_REGLE) AS COUNTER
         		FROM POSTE_COUT_REGLE PCR
         		INNER JOIN REGLEMENT ON REGLEMENT.ID_REGLEMENT = PCR.ID_REGLEMENT
         			AND REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
         		GROUP BY PCR.ID_SESSION
         		HAVING PCR.ID_SESSION IS NOT NULL
         	) AS PCR_NEW ON PCR_NEW.ID_SESSION = SESSION.ID_SESSION
         		
         
         	WHERE
         		-- The filter is applied to all sessions
         		--(SESSION.ID_SESSION = @ID_SESSION) AND
         		(AGENCE.ID_AGENCE = @ID_AGENCE OR @ID_AGENCE IS NULL) AND
         		(ADHERENT.ID_ADHERENT = @ID_ADHERENT OR @ID_ADHERENT IS NULL) AND
         		(
         			(@NOUVEAUX_OF IS NULL AND 
         				(ORGANISME_FORMATION.ID_OF = @ID_OF OR @ID_OF IS NULL)
         			) 
         			OR
         			(@NOUVEAUX_OF IS NOT NULL AND 
         				(ORGANISME_FORMATION.DAT_CREATION > DATEADD(MM, -3, GETDATE())) OR
         				(PCR_NEW.COUNTER < 10)
         			)
         		)AND
         		(SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT OR @ID_SOUS_TYPE_COUT IS NULL) AND
         		(
         			(@BLN_INFERIEUR = 0 AND POSTE_COUT_REGLE.MNT_REGLE_TTC >= @MNT_TTC) OR
         			(@BLN_INFERIEUR = 1 AND POSTE_COUT_REGLE.MNT_REGLE_TTC < @MNT_TTC)
         		)
         
         	GROUP BY
         		AGENCE.ID_AGENCE,
         		ADHERENT.ID_ADHERENT,
         		ORGANISME_FORMATION.ID_OF,
         		SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
         		AGENCE.LIBL_AGENCE,
         		ADHERENT.LIB_RAISON_SOCIALE,
         		ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         		SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT
         
         END

GO
 -- =============================================
         -- Author		: XXX
         -- Create date	: XX XXX XXX
         -- comment		: # lecture groupe pour la recherche en liste des actions pec
         -- ---------------------------------------------
         -- Author		: KS
         -- Modified date: 05 octobre 2007
         -- comment		: SESSION_PEC.BLN_ACTIF = 1 AND MODULE_PEC.BLN_ACTIF = 1
         -- =============================================
         -- Author		: APA
         -- Create date	: 26/01/2012
         -- Description	: Defi Lot 1 - 13139 - Ajout du filtre par Id Utilisateur				
         -- =============================================
         -- Author		: HBO
         -- Create date	: 06/06/2013
         -- Description	: 15235: SBR - anulation virement compens‚ impossible				
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_GRP_ANNULATION_VIREMENT]
         	@NUM_VIREMENT		varchar(10),
         	@COD_MODULE_PEC		varchar(10),
         	@ID_SESSION			varchar(10),
         	@COD_SESSION_PEC	varchar(12),
         	@ID_UTILISATEUR		int = NULL
         AS
         BEGIN
         
         	IF (@COD_MODULE_PEC = '')
         		SET @COD_MODULE_PEC = NULL
         
         	IF (@NUM_VIREMENT = '')
         		SET @NUM_VIREMENT = NULL
         
         	IF (@ID_SESSION = '')
         		SET @ID_SESSION = NULL
         
         	SELECT DISTINCT
         		MODULE_PEC.ID_MODULE_PEC,
         		REGLEMENT.ID_REGLEMENT					AS ID_REGLEMENT,
         		POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE	AS ID_POSTE_COUT_REGLE,
         		0										AS ANNULATION,
         		REGLEMENT.NUM_VIREMENT					AS NUM_VIREMENT,
         		REGLEMENT.COD_REGLEMENT 				AS COD_REGLEMENT,
         		MODULE_PEC.COD_MODULE_PEC 				AS COD_MODULE_PEC,
         		MODULE_PEC.LIBL_MODULE_PEC 				AS LIBL_MODULE_PEC,
         		AGENCE.LIBC_AGENCE						AS LIBC_AGENCE,
         		SESSION_PEC.DAT_DEBUT					AS DAT_DEBUT,
         		SESSION_PEC.DAT_FIN						AS DAT_FIN,
         		SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT		AS LIBL_SOUS_TYPE_COUT,
         		POSTE_COUT_REGLE.MNT_REGLE_HT			AS NT_REGLE_HT,
         		POSTE_COUT_REGLE.MNT_REGLE_TVA			AS MNT_REGLE_TVA,
         		POSTE_COUT_REGLE.MNT_REGLE_TTC			AS MNT_REGLE_TTC,
         		SESSION_PEC.ID_SESSION_PEC,
         		SESSION_PEC.COD_SESSION_PEC,
         		CASE 
         			WHEN [TRANSACTION].ID_TIERS_BENEF			IS NOT NULL
         				THEN TIERS.LIB_NOM		
         			WHEN [TRANSACTION].ID_ETABLISSEMENT_BENEF	IS NOT NULL
         				THEN ADHERENT.LIB_SIGLE_ADHERENT
         			WHEN [TRANSACTION].ID_ETABLISSEMENT_OF_BENEF IS NOT NULL
         				THEN ORGANISME_FORMATION.LIB_SIGLE_OF
         		END										AS DESTINATAIRE,
         		SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT,
         		EDITION.ID_EDITION,
         		EDITION.FICHIER_EDITION
         	FROM 
         
         		POSTE_COUT_REGLE
         		INNER JOIN MODULE_PEC	ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		INNER JOIN SESSION_PEC	ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC
         								AND POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 
         		INNER JOIN REGLEMENT	ON (REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT) 
         					AND (REGLEMENT.DAT_VALID_REGLEMENT IS NULL) 
         					AND (REGLEMENT.DAT_EDITION IS NOT NULL OR REGLEMENT.MNT_REGLE_HT=0)
         		LEFT JOIN REGLEMENT_EDITION	ON REGLEMENT.ID_REGLEMENT		= REGLEMENT_EDITION.ID_REGLEMENT 
         		LEFT JOIN EDITION				ON REGLEMENT_EDITION.ID_EDITION = EDITION.ID_EDITION
         		LEFT JOIN AGENCE				ON AGENCE.ID_AGENCE				= REGLEMENT.ID_AGENCE
         		INNER JOIN SOUS_TYPE_COUT		ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
         		INNER JOIN [TRANSACTION]		ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         		LEFT JOIN TIERS					ON TIERS.ID_TIERS				= [TRANSACTION].ID_TIERS_BENEF
         		LEFT JOIN ETABLISSEMENT			ON ETABLISSEMENT.ID_ETABLISSEMENT	= [TRANSACTION].ID_ETABLISSEMENT_BENEF
         		LEFT JOIN ADHERENT				ON ADHERENT.ID_ADHERENT				= ETABLISSEMENT.ID_ADHERENT
         		LEFT JOIN ETABLISSEMENT_OF		ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = [TRANSACTION].ID_ETABLISSEMENT_OF_BENEF
         		LEFT JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF			= ETABLISSEMENT_OF.ID_OF
         	
         	WHERE
         			(@COD_MODULE_PEC IS NULL OR RTRIM(@COD_MODULE_PEC)	= '' OR MODULE_PEC.COD_MODULE_PEC	= @COD_MODULE_PEC) 
         		AND	(@NUM_VIREMENT	 IS NULL OR RTRIM(@NUM_VIREMENT)	= '' OR REGLEMENT.NUM_VIREMENT		= @NUM_VIREMENT) 
         		AND (@ID_SESSION	 IS NULL OR RTRIM(@ID_SESSION)		= '' OR POSTE_COUT_REGLE.ID_SESSION = @ID_SESSION)
         		AND (POSTE_COUT_REGLE.BLN_ACTIF = 1)
         		AND ((@COD_SESSION_PEC IS NULL) OR (SESSION_PEC.COD_SESSION_PEC = @COD_SESSION_PEC))
         		AND SESSION_PEC.BLN_ACTIF	= 1
         		AND MODULE_PEC.BLN_ACTIF	= 1
         		AND (REGLEMENT.ID_UTILISATEUR = @ID_UTILISATEUR OR @ID_UTILISATEUR IS NULL)
         		AND (REGLEMENT_EDITION.ID_EDITION is not null OR REGLEMENT.MNT_REGLE_HT=0)
         	
         	ORDER BY 
         		REGLEMENT.NUM_VIREMENT, 
         		SESSION_PEC.COD_SESSION_PEC, 
         		SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT
         	OPTION(RECOMPILE)
         END
         

GO
 CREATE PROCEDURE [dbo].[LEC_GRP_ACTION_PRISES]
         -- =============================================
         -- Author  : XXX
         -- Create date : XX XXX XXX
         -- comment  : # lecture groupe pour la recherche en liste des actions pec
         -- ---------------------------------------------
         -- Author  : Say
         -- Modified date: 30 juillet 2007
         -- comment  : # alt‚ration de la proc‚dure pour d‚but d'optimisation
         --      # ajout du montant "MNT chiffr‚ "
         -- ---------------------------------------------
         -- Author  : Say
         -- Modified date: 06 ao–t 2007
         -- comment  : # montant "MNT chiffr‚ " devient "MNT reste … engager"
         -- ---------------------------------------------
         -- Author  : Say
         -- Modified date: 08 ao–t 2007
         -- comment  : # montant "MNT reste … engager" redevient "MNT chiffr‚ "
         -- ---------------------------------------------
         -- Author  : Say
         -- Modified date: 16 ao–t 2007
         -- comment  : # restructuration de la proc‚dure car les calculs de montants n'‚taient pas toujours prises en compte
         -- ---------------------------------------------
         -- Author  : Say
         -- Modified date: 20 ao–t 2007
         -- comment  : # table temporaire pour calculer en distinct le MNT_REGLE_HT
         -- ---------------------------------------------
         -- Author  : SVA
         -- Modified date: 04 octobre 2007
         -- comment  : Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚
         -- ---------------------------------------------
         -- Author  : SVA
         -- Modified date: 05 octobre 2007
         -- comment  : Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚ calcul‚ pour la colonne r‚gl‚ (r‚el)
         -- comment  : La date de B.A.E. … prendre en compte est la plus petite des engagements dont la type engagement est 1
         -- ---------------------------------------------
         -- Author  : MBL
         -- Modified date: 16 octobre 2007
         -- comment  : Modification du calcul de la date BAE
         -- ---------------------------------------------
         -- Author  : MBL
         -- Modified date: 19 octobre 2007
         -- comment  : Modification du calcul du montant engag‚
         -- ---------------------------------------------
         -- Author  : DSZE
         -- Modified date: 10 mars 2008
         -- comment  : C2P: Ajout @ID_OF, @ID_STAGE, @BLN_ACCORD, @ANNEE
         -- ---------------------------------------------
         -- Author  : DSZE
         -- Modified date: 12 mars 2008
         -- comment  : C2P: Ajout CODE_ACTION a la lecture des donnees
         -- ---------------------------------------------
         -- 24/04/08 Dorota 
         -- Remplacement calcul MNT_CHIFFRE pour prendre en compte PLAN_FINANCEMENT_US
         -- ---------------------------------------------
         -- 19/09/08 SAFI
         -- FILTRER LES ELEMENTS POSTE_COUT_ENGAGE QUI MATCHENT AVEC MODULE_PEC.ID_MODULE_PEC
         -- ---------------------------------------------
         -- Author  : AMA
         -- Modified date: 04 d‚cembre 2008
         -- comment  : Suppression de la clause DISTINCT dans la sous requˆte de de calcul des
         --      couts r‚gl‚s (les op‚ration d'encaissement/d‚caissement).
         -- ---------------------------------------------
         -- Author  : SAFI
         -- Modified date: 16-01-2009
         -- comment  : Adding two coloumns Nb Heur Engagees, Nb Heur Realisse
         --      And Corriecting the description of the coloumn Cible Action.
         -- ---------------------------------------------
         -- Author  : AMA
         -- Modified date: 19 janvier 2009
         -- comment  : Correction d'un problŠme de jointure sur NR140
         -- + ajout m‚canisme de g‚n‚ration DROP/CREATE
         -- ---------------------------------------------
         -- Author  : AMA
         -- Modified date: 21 janvier 2009
         -- comment  : Correction d'un problŠme de jointure (MANTIS 0011453)
         --  au moment du calcul du montant regl‚. Les r‚sultats
         -- dans SQL SERVER MANAGER sont obtenu avec SET ROWCOUNT(0)
         -- alors qu'OPTIFORM impose SET ROWCOUNT(300) dans ses connections.
         -- R‚sultat: les r‚sultats obtenues dans SQLSERVER peuvent diff‚rer
         --    de ceux obtenus dans OPTIFORM
         -- ---------------------------------------------
         -- Author  : SAFI
         -- Modified date: 23 FEV 2009
         -- comment  : Add one condition for counting 'nb_heur_stagiaire'
         --      with  POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         -- ---------------------------------------------
         -- Author  : AMA
         -- Modified date: 12 mars 2009
         -- comment  : MANTIS 0011845
         --      La correction pr‚c‚dente entrainait une r‚gression
         --      Il n'y a pas de lien unique entre STAGIAIRE, MODULE et POSTE_COUT_ENGAGE
         --      de ce fait certaines lignes ‚taient ramen‚es en doublon dans le calcul
         --      du nombre d'heure engag‚es
         -- ---------------------------------------------
         -- Author  : DSZ
         -- Modified date: 15/05/09
         -- comment  : Mantis 11980. Erreur dans le calcul du MNT_REEL, jointure avec etablissement 
         -- fait redoubler les lignes et ne sert a rien
         -- ---------------------------------------------
         -- Author  : SAFI
         -- Modified date: 17/02/10
         -- comment  : Mantis 12309. 
         -- Do not count on inactive modules and non imput modules 
         -- for the calcule of 'Mnt Demande' and 'Mnt Chiffere'
         -- ---------------------------------------------
         -- Author  : ASD DSZ
         -- Modified date: 13/10/3010
         -- comment  : 12423 Perf.  + indexes associ‚s
         -- ---------------------------------------------
         -- Author  : DSZ
         -- Modified date: 12/11/2010
         -- comment  : 12547 PERF. recherche sur stagiaire
         -- ---------------------------------------------
         -- Author  : RVI
         -- Modified date: 2012-04-18
         -- comment  : 13370 : Ajout colonne NUM_ARCHIVE
         -- =======================================================================================================================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================  
         -- DSZ/GRU #554 13/10/2014
         -- =======================================================================================================================================  
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250), et LIBELLE_ACTION
         -- =======================================================================================================================================  
          @COD_ACTION      Int,
          @LIBL_ACTION     VarChar(250),
          @ID_THEME      Int,
          @ID_NIVEAU      Int,
          @ID_SANCTION     Int,
          @ID_ADHERENT     Int,
          @ID_ETABLISSEMENT    Int,
          @ID_OPERATION     Int,
          @DATE_DEBUT_ENTRE_LE   DateTime,
          @DATE_DEBUT_ET_LE    DateTime,
          @DATE_FIN_ENTRE_LE    DateTime,
          @DATE_FIN_ET_LE     DateTime,
          @BLN_ACTION_INDIVIDUELLE  Int,
          @BLN_ACTION_INTERET_COLLECTIVE Int,
          @BLN_ACTION_COLLECTIVE   Int,
          @BLN_INACTIVE      Int,
          @BLN_CLOTUREE     Int,
          @ID_INDIVIDU     Int,
          @ID_OF       Int,
          @ID_STAGE      Int,
          @BLN_ACCORD      TinyInt,
          @ANNEE       Int
         AS
         BEGIN
          SET NOCOUNT ON
         
         /*
         ** Tests sur les input parameters
         */
          SET @BLN_ACTION_INDIVIDUELLE =
           ISNULL(@BLN_ACTION_INDIVIDUELLE,0);
          SET @BLN_ACTION_INTERET_COLLECTIVE =
           ISNULL(@BLN_ACTION_INTERET_COLLECTIVE,0);
          SET @BLN_ACTION_COLLECTIVE =
           ISNULL(@BLN_ACTION_COLLECTIVE,0);
          SET @BLN_INACTIVE =
           ISNULL(@BLN_INACTIVE,0);
          SET @BLN_CLOTUREE =
           ISNULL(@BLN_CLOTUREE,0);
         
         /*
         ** D‚clarations des variables internes
         */
          DECLARE @NUM_DUREE_JOUR_ACTION_MAX AS Int;
          DECLARE @NUM_DUREE_HEURE_ACTION_MAX AS Int;
          CREATE TABLE #TRI(
           ID_ACTION Int, 
           NUM_ACTION Int, 
           ANNEE_ACTION Int, 
           LIBELLE_ACTION VarChar(250),
           DAT_DEB_ACTION_PEC DateTime,
           DAT_FIN_ACTION_PEC DateTime,
           BLN_ACTIF TinyInt,
           DAT_CLOTURE DateTime,
           NUM_DUREE_JOUR_ACTION_MAX Decimal(18,2),
           NUM_DUREE_HUERE_ACTION_MAX Decimal(18,2),
           CIBLE_ACTION Int,
           ID_THEME Int,
           ID_OPERATION_FINANCIERE Int,
           NUM_ARCHIVE VarChar(17) NULL
          );
          DECLARE @RECHERCHE_VIA_COD_ACTION AS Bit = 0;
          DECLARE @RECHERCHE_VIA_ANNEE AS Bit = 0;
          DECLARE @RECHERCHE_VIA_INDIVIDU AS Bit = 0;
         
         /*
         ** Instanciations des variables internes
         */
          SELECT TOP(1)
           @NUM_DUREE_JOUR_ACTION_MAX = NUM_DUREE_JOUR_ACTION_MAX,
           @NUM_DUREE_HEURE_ACTION_MAX = NUM_DUREE_HEURE_ACTION_MAX
          FROM [dbo].[PARAMETRES];
         
          IF (@LIBL_ACTION     is null and
           @ID_THEME      is null and
           @ID_NIVEAU      is null and
           @ID_SANCTION     is null and
           @ID_ADHERENT     is null and
           @ID_ETABLISSEMENT    is null and
           @ID_OPERATION     is null and
           @DATE_DEBUT_ENTRE_LE   is null and
           @DATE_DEBUT_ET_LE    is null and
           @DATE_FIN_ENTRE_LE    is null and
           @DATE_FIN_ET_LE     is null and
           @BLN_ACTION_INDIVIDUELLE  =0 and
           @BLN_ACTION_INTERET_COLLECTIVE =0 and
           @BLN_ACTION_COLLECTIVE   =0 and
           @BLN_INACTIVE      =0 and
           @BLN_CLOTUREE     =0 and
           @ID_OF       is null and
           @ID_STAGE      is null and
           @BLN_ACCORD      is null )
           begin 
            if  (@ID_INDIVIDU is not null)
             SET @RECHERCHE_VIA_INDIVIDU = 1
            else if (@COD_ACTION  is not null and
             @ANNEE    is null)
             SET @RECHERCHE_VIA_COD_ACTION = 1
            ELSE
             SET @RECHERCHE_VIA_ANNEE = 1
           end
           --sinon le cas le plus g‚neral avec tous les param‚tres
          
         
         /*
         ** Table #TRI
         */
          IF (@RECHERCHE_VIA_COD_ACTION = 1) BEGIN
           INSERT INTO #TRI
            SELECT TOP 301
             ACTION_PEC.ID_ACTION_PEC   AS ID_ACTION,
             ACTION_PEC.COD_ACTION_PEC   AS NUM_ACTION, 
             ACTION_PEC.ANNEE_ACTION_PEC   AS ANNEE_ACTION, 
             ACTION_PEC.LIBL_ACTION_PEC   AS LIBELLE_ACTION,
             ACTION_PEC.DAT_DEB_ACTION_PEC,
             ACTION_PEC.DAT_FIN_ACTION_PEC,
             ACTION_PEC.BLN_ACTIF,
             ACTION_PEC.DAT_CLOTURE,
             @NUM_DUREE_JOUR_ACTION_MAX   AS NUM_DUREE_JOUR_ACTION_MAX,
             @NUM_DUREE_HEURE_ACTION_MAX   AS NUM_DUREE_HUERE_ACTION_MAX,
             ACTION_PEC.CIBLE_ACTION,
             ACTION_PEC.ID_THEME,
             ACTION_PEC.ID_OPERATION_FINANCIERE,
             ACTION_PEC.NUM_ARCHIVE
            FROM
             ACTION_PEC
            WHERE
             (ACTION_PEC.COD_ACTION_PEC = @COD_ACTION) AND
             (ACTION_PEC.BLN_ACTIF = 1) AND
             (ACTION_PEC.DAT_CLOTURE IS NULL);
          END ELSE IF(@RECHERCHE_VIA_ANNEE = 1) BEGIN
           INSERT INTO #TRI
            SELECT TOP 301
             ACTION_PEC.ID_ACTION_PEC   AS ID_ACTION,
             ACTION_PEC.COD_ACTION_PEC   AS NUM_ACTION, 
             ACTION_PEC.ANNEE_ACTION_PEC   AS ANNEE_ACTION, 
             ACTION_PEC.LIBL_ACTION_PEC   AS LIBELLE_ACTION,
             ACTION_PEC.DAT_DEB_ACTION_PEC,
             ACTION_PEC.DAT_FIN_ACTION_PEC,
             ACTION_PEC.BLN_ACTIF,
             ACTION_PEC.DAT_CLOTURE,
             @NUM_DUREE_JOUR_ACTION_MAX   AS NUM_DUREE_JOUR_ACTION_MAX,
             @NUM_DUREE_HEURE_ACTION_MAX   AS NUM_DUREE_HUERE_ACTION_MAX,
             ACTION_PEC.CIBLE_ACTION,
             ACTION_PEC.ID_THEME,
             ACTION_PEC.ID_OPERATION_FINANCIERE,
             ACTION_PEC.NUM_ARCHIVE
            FROM
             ACTION_PEC
            WHERE
             (@COD_ACTION IS NULL OR ACTION_PEC.COD_ACTION_PEC = @COD_ACTION) AND
             (@ANNEE IS NULL OR ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE) AND
             (ACTION_PEC.BLN_ACTIF = 1) AND
             (ACTION_PEC.DAT_CLOTURE IS NULL) 
            ORDER BY ID_ACTION DESC
            OPTION(RECOMPILE);
          END ELSE IF (@RECHERCHE_VIA_INDIVIDU = 1) BEGIN
           INSERT INTO #TRI
            SELECT distinct top 301
             ACTION_PEC.ID_ACTION_PEC   AS ID_ACTION,
             ACTION_PEC.COD_ACTION_PEC   AS NUM_ACTION, 
             ACTION_PEC.ANNEE_ACTION_PEC   AS ANNEE_ACTION, 
             ACTION_PEC.LIBL_ACTION_PEC   AS LIBELLE_ACTION,
             ACTION_PEC.DAT_DEB_ACTION_PEC,
             ACTION_PEC.DAT_FIN_ACTION_PEC,
             ACTION_PEC.BLN_ACTIF,
             ACTION_PEC.DAT_CLOTURE,
             @NUM_DUREE_JOUR_ACTION_MAX   AS NUM_DUREE_JOUR_ACTION_MAX,
             @NUM_DUREE_HEURE_ACTION_MAX   AS NUM_DUREE_HUERE_ACTION_MAX,
             ACTION_PEC.CIBLE_ACTION,
             ACTION_PEC.ID_THEME,
             ACTION_PEC.ID_OPERATION_FINANCIERE,
             ACTION_PEC.NUM_ARCHIVE
            FROM
             STAGIAIRE_PEC
             INNER JOIN MODULE_PEC ON STAGIAIRE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
             INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
            WHERE
             (STAGIAIRE_PEC.ID_INDIVIDU  = @ID_INDIVIDU) AND
             (@BLN_ACTION_INDIVIDUELLE  = 0 OR ACTION_PEC.CIBLE_ACTION = 1) AND
             (@BLN_ACTION_INTERET_COLLECTIVE = 0 OR ACTION_PEC.CIBLE_ACTION = 2) AND
             (@BLN_ACTION_COLLECTIVE   = 0 OR ACTION_PEC.CIBLE_ACTION = 3) AND
             (@BLN_INACTIVE     = 1 OR ACTION_PEC.BLN_ACTIF  = 1) AND
             (@BLN_CLOTUREE     = 1 OR ACTION_PEC.DAT_CLOTURE IS NULL)
            ORDER BY ID_ACTION DESC; 
          END ELSE BEGIN
           INSERT INTO #TRI
            SELECT distinct top 301 
             ACTION_PEC.ID_ACTION_PEC   AS ID_ACTION,
             ACTION_PEC.COD_ACTION_PEC   AS NUM_ACTION, 
             ACTION_PEC.ANNEE_ACTION_PEC   AS ANNEE_ACTION, 
             ACTION_PEC.LIBL_ACTION_PEC   AS LIBELLE_ACTION,
             ACTION_PEC.DAT_DEB_ACTION_PEC,
             ACTION_PEC.DAT_FIN_ACTION_PEC,
             ACTION_PEC.BLN_ACTIF,
             ACTION_PEC.DAT_CLOTURE,
             @NUM_DUREE_JOUR_ACTION_MAX   AS NUM_DUREE_JOUR_ACTION_MAX,
             @NUM_DUREE_HEURE_ACTION_MAX   AS NUM_DUREE_HUERE_ACTION_MAX,
             ACTION_PEC.CIBLE_ACTION,
             ACTION_PEC.ID_THEME,
             ACTION_PEC.ID_OPERATION_FINANCIERE,
             ACTION_PEC.NUM_ARCHIVE
            FROM
             ACTION_PEC
             LEFT JOIN NR140     ON NR140.ID_ACTION_PEC    = ACTION_PEC.ID_ACTION_PEC
             LEFT JOIN ETABLISSEMENT   ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
             LEFT JOIN MODULE_PEC   ON MODULE_PEC.ID_ACTION_PEC   = ACTION_PEC.ID_ACTION_PEC
             LEFT JOIN ETABLISSEMENT_OF   ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
             LEFT JOIN ORGANISME_FORMATION  ON ORGANISME_FORMATION.ID_OF  = ETABLISSEMENT_OF.ID_OF
             LEFT JOIN STAGIAIRE_PEC   ON STAGIAIRE_PEC.ID_MODULE_PEC  = MODULE_PEC.ID_MODULE_PEC AND STAGIAIRE_PEC.ID_INDIVIDU = @ID_INDIVIDU
            WHERE
             (@COD_ACTION     IS NULL OR ACTION_PEC.COD_ACTION_PEC   = @COD_ACTION) AND
             (@LIBL_ACTION     IS NULL OR ACTION_PEC.LIBL_ACTION_PEC   LIKE @LIBL_ACTION) AND
             (@ID_THEME      IS NULL OR ACTION_PEC.ID_THEME     = @ID_THEME) AND
             (@ID_NIVEAU      IS NULL OR ACTION_PEC.ID_NIVEAU     = @ID_NIVEAU) AND
             (@ID_SANCTION     IS NULL OR ACTION_PEC.ID_SANCTION    = @ID_SANCTION) AND
             (@ID_ADHERENT     IS NULL OR ETABLISSEMENT.ID_ADHERENT   = @ID_ADHERENT) AND
             (@ID_OPERATION     IS NULL OR ACTION_PEC.ID_OPERATION_FINANCIERE = @ID_OPERATION) AND
             (@ID_ETABLISSEMENT    IS NULL OR ETABLISSEMENT.ID_ETABLISSEMENT  = @ID_ETABLISSEMENT) AND
             (@DATE_DEBUT_ENTRE_LE   IS NULL OR ACTION_PEC.DAT_DEB_ACTION_PEC  >= @DATE_DEBUT_ENTRE_LE) AND
             (@DATE_DEBUT_ET_LE    IS NULL OR ACTION_PEC.DAT_DEB_ACTION_PEC  <= @DATE_DEBUT_ET_LE) AND
             (@DATE_FIN_ENTRE_LE    IS NULL OR ACTION_PEC.DAT_FIN_ACTION_PEC  >= @DATE_FIN_ENTRE_LE) AND
             (@DATE_FIN_ET_LE    IS NULL OR ACTION_PEC.DAT_FIN_ACTION_PEC  <= @DATE_FIN_ET_LE) AND
             (@ID_INDIVIDU     IS NULL OR STAGIAIRE_PEC.ID_INDIVIDU   = @ID_INDIVIDU) AND
             (@BLN_ACTION_INDIVIDUELLE  = 0  OR ACTION_PEC.CIBLE_ACTION    = 1) AND
             (@BLN_ACTION_INTERET_COLLECTIVE = 0  OR ACTION_PEC.CIBLE_ACTION    = 2) AND
             (@BLN_ACTION_COLLECTIVE   = 0  OR ACTION_PEC.CIBLE_ACTION    = 3) AND
             (@BLN_INACTIVE     = 1  OR ACTION_PEC.BLN_ACTIF     = 1) AND
             (@BLN_CLOTUREE     = 1  OR ACTION_PEC.DAT_CLOTURE    IS NULL) AND
             (@ID_OF       IS NULL OR ORGANISME_FORMATION.ID_OF   = @ID_OF) AND
             (@ID_STAGE      IS NULL OR MODULE_PEC.ID_STAGE     = @ID_STAGE ) AND
             (@BLN_ACCORD     IS NULL OR ACTION_PEC.BLN_ACCORD    = @BLN_ACCORD) AND
             (@ANNEE       IS NULL OR ACTION_PEC.ANNEE_ACTION_PEC   = @ANNEE)
            ORDER BY ID_ACTION DESC  
            OPTION(RECOMPILE);
          END
         
         /*
         ** Table #TEMPLISTREEL
         */
          SELECT
           #TRI.ID_ACTION,
           SUM(CAST(POSTE_COUT_REGLE.MNT_REGLE_HT AS Decimal(18,2))) AS MNT_REEL
          INTO
           #TEMPLISTREEL
          FROM
           #TRI
           INNER JOIN MODULE_PEC ON MODULE_PEC.ID_ACTION_PEC = #TRI.ID_ACTION
           INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           INNER JOIN REGLEMENT ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT AND REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
          GROUP BY
           #TRI.ID_ACTION;
         
         /*
         ** Table #TEMPLISTENGAGE
         */
          SELECT 
           ACTION_PEC.ID_ACTION_PEC,
           case when (action_pec.bln_cycle_court = 0) then
             SUM(cast(POSTE_COUT_ENGAGE.MNT_ENGAGE_HT as decimal(18,2)))
            else
             (select MNT_REEL from #TEMPLISTREEL where #TEMPLISTREEL.ID_ACTION = ACTION_PEC.ID_ACTION_PEC)
           end AS MNT_ENGAGE,
          MIN(ENGAGEMENT.DAT_BAE) as DAT_BAE
          INTO #TEMPLISTENGAGE
          FROM POSTE_COUT_ENGAGE
           INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
           INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC
           INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
           INNER JOIN #TRI  ON #TRI.ID_ACTION   = ACTION_PEC.ID_ACTION_PEC
          WHERE
           DAT_DESENGAGEMENT is NULL  AND 
           ID_TYPE_ENGAGEMENT is not null AND 
           ID_TYPE_ENGAGEMENT <> 2
          GROUP BY 
           ACTION_PEC.ID_ACTION_PEC, 
           ACTION_PEC.BLN_CYCLE_COURT
         
         /*
         ** Table #TEMPLISTENGAGE2
         */
          SELECT 
           MODULE_PEC.ID_ACTION_PEC, 
           SUM(CAST(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT AS Decimal(18,2))) AS MNT_PREV  
          INTO
           #TEMPLISTENGAGE2
          FROM
           #TRI
           INNER JOIN MODULE_PEC ON #TRI.ID_ACTION = MODULE_PEC.ID_ACTION_PEC
                 AND MODULE_PEC.BLN_ACTIF = 1 
                 AND MODULE_PEC.BLN_IMPUTABLE = 1
           INNER JOIN POSTE_COUT_ENGAGE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC       
          GROUP BY
           MODULE_PEC.ID_ACTION_PEC;
         
         /*
         ** Table #TEMPLISTENGAGE3
         */
          SELECT
           MODULE_PEC.ID_ACTION_PEC,
           SUM(CAST(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US AS Decimal(18,2))) AS MNT_CHIFFRE
          INTO
           #TEMPLISTENGAGE3
          FROM
           #TRI
           INNER JOIN MODULE_PEC   ON #TRI.ID_ACTION       = MODULE_PEC.ID_ACTION_PEC
           INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC   = MODULE_PEC.ID_MODULE_PEC 
                    AND MODULE_PEC.BLN_ACTIF = 1 
                    AND MODULE_PEC.BLN_IMPUTABLE = 1
           INNER JOIN PLAN_FINANCEMENT_US  ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE 
                    AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
          GROUP BY
           MODULE_PEC.ID_ACTION_PEC;
         
         /*
         ** Calcul du r‚sultat
         */
          SELECT TOP(301)
           #TRI.ID_ACTION, 
           #TRI.NUM_ACTION, 
           #TRI.LIBELLE_ACTION,
           THEME.LIBL_THEME            AS THEME_GLOBAL,
           CASE 
            WHEN #TRI.CIBLE_ACTION = 1 THEN
             'AI' 
            WHEN #TRI.CIBLE_ACTION = 2 THEN
             'AIC'
            ELSE
             'AC'
           END                AS CIBLE_ACTION,
           #TRI.DAT_DEB_ACTION_PEC,
           #TRI.DAT_FIN_ACTION_PEC,
           OPERATION_FINANCIERE.LIBL_OPERATION_FINANCIERE     AS OPERATION_FINANCIERE,
           #TRI.BLN_ACTIF,
           #TEMPLISTENGAGE.DAT_BAE,
           #TRI.DAT_CLOTURE,
           #TRI.NUM_DUREE_JOUR_ACTION_MAX,
           #TRI.NUM_DUREE_HUERE_ACTION_MAX,
           CASE
            WHEN #TRI.DAT_CLOTURE IS NULL THEN
             0
            ELSE
             1
           END                AS CLOTURE,
           dbo.GetActionPECCode(#TRI.NUM_ACTION,#TRI.ANNEE_ACTION)   AS CODE_ACTION,
           ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0)       AS MNT_ENGAGE,
           ISNULL(#TEMPLISTREEL.MNT_REEL,0)        AS MNT_REEL,
           ISNULL(#TEMPLISTENGAGE2.MNT_PREV,0)        AS MNT_PREV,
           ISNULL(CAST(#TEMPLISTENGAGE3.MNT_CHIFFRE AS Decimal(18,2)),0) AS MNT_CHIFFRE,
           COALESCE(myViewE.CALC_HEURE_ENGAGEES,0)       AS NB_HEUR_ENGAGEE,
           COALESCE(myviewR.nb_h_realisees,0)        AS NB_HEUR_REALISEE,
           #TRI.NUM_ARCHIVE
          FROM  #TRI
           INNER JOIN THEME    ON THEME.ID_THEME = #TRI.ID_THEME
           LEFT JOIN OPERATION_FINANCIERE ON OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = #TRI.ID_OPERATION_FINANCIERE
           LEFT JOIN #TEMPLISTENGAGE  ON #TEMPLISTENGAGE.ID_ACTION_PEC    = #TRI.ID_ACTION
           LEFT JOIN #TEMPLISTENGAGE2  ON #TEMPLISTENGAGE2.ID_ACTION_PEC    = #TRI.ID_ACTION
           LEFT JOIN #TEMPLISTENGAGE3  ON #TEMPLISTENGAGE3.ID_ACTION_PEC    = #TRI.ID_ACTION
           LEFT JOIN #TEMPLISTREEL   ON #TEMPLISTREEL.ID_ACTION      = #TRI.ID_ACTION
           LEFT JOIN dbo.VIEW_Nb_h_realisees_sur_IdAction myviewR
                   ON myviewR.ID_ACTION_PEC      = #TRI.ID_ACTION
           LEFT JOIN dbo.VIEW_Nb_heure_engagees_sur_IdAction myviewE
                   ON myviewE.ID_ACTION_PEC      = #TRI.ID_ACTION
          ORDER BY #TRI.NUM_ACTION;
         END

GO
 CREATE PROCEDURE [dbo].[INS_ACTION_PRISES]
          @LIBL_ACTION varchar(250),
          @ID_THEME int,
          @ID_NIVEAU int,
          @ID_SANCTION int,
          @ID_OPERATION int,
          @DATE_DEBUT datetime,
          @DATE_FIN datetime,
          @CIBLE_ACTION int,
          @BLN_INACTIVE int,
          @ID_UTILISATEUR int,
          @NUM_DUREE_JOUR decimal(18,2),
          @NUM_DUREE_HEURE decimal(18,2),
          @ID_AGENCE int,
          @CICLE_COURT int,
          @COM_ACTION varchar(255),
          @ID_ACTION_PEC int output,
          @ID_FORMACODE INT,
          @DAT_RECU datetime,
          @ID_DECISION_ACTION_PEC int,
          @AXE varchar(30),
          @DOMAINE varchar(30), 
          @ID_UTILISATEUR_CREATEUR int,
          @CODE_ACTION varchar(11) output,
          @ID_CHARGEE_MISSION INT,
          @NUM_ACTION INT = NULL, -- LDE 03/10/2013 15904
          @MILLESIME INT = NULL -- LDE 03/10/2013 15904
         AS
         -- =======================================================================================================================================
         -- Author:  Dorota Szeliga
         -- Modif. date: 11/03/2008
         -- Description: C2P: Ajout @DAT_RECU, @ID_DECISION_ACTION_PEC,@AXE, @DOMAINE 
         --    changement @@COD_ACTION_PEC
         -- =======================================================================================================================================
         -- Author:  Dorota Szeliga
         -- Modif. date: 12/03/2008
         -- Description: C2P: Si Motif Refus (Decision) assigne, on met BLN_ACCORD a 0 (Refus)
         -- =======================================================================================================================================
         -- Author: GLEG
         -- Modif. date: 11/04/2008
         -- Description: Ajout @ID_UTILISATEUR_CREATEUR
         -- =======================================================================================================================================
         -- Author: AMA
         -- Modif. date: 11/04/2008
         -- Description: Correction affectation valeur sur BLN_ACCORD
         -- =======================================================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================
         -- LDE 06/06/2013 15273: Ouverture Optiform par arguments de l'‚cran ActionPec en cr‚ation
         -- =======================================================================================================================================
         -- HBO - 310713 - M15570: Paniers : Ouverture d'Optiform en cr‚ation d'action : ajout du paramŠtre Adh‚rent
         -- =======================================================================================================================================
         -- LDE 03/10/2013 15904: PIC - validation d une action impossible suite lancement optiform via D3R
         -- =======================================================================================================================================
         -- DSZ 06/12/2013 16527 gestion @ID_THEME … null
         -- =======================================================================================================================================
         -- ARI + HBO : #907 : Ajout du dossier PEC dans la table EXPORT_D3R
         -- =======================================================================================================================================
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250)
         -- =======================================================================================================================================
         BEGIN
          IF (@CICLE_COURT IS NULL)
          BEGIN
           SET @CICLE_COURT = 0
          END 
         
          IF (@ID_AGENCE = -1)
          BEGIN
           set @ID_AGENCE = null
          END
          
          IF (@ID_THEME is null)
          BEGIN
           select @ID_THEME = ID_THEME from THEME where COD_THEME = 'ND' 
          END
         
          declare @@ANNEE_ACTION_PEC int
          set @@ANNEE_ACTION_PEC = datepart(yyyy, getdate())
         
          --create COD_ACTION_PEC
          declare @@COD_ACTION_PEC int
         
          -- LDE 06/06/2013 15273
          if (@CODE_ACTION IS NULL)
          BEGIN
           EXEC @@COD_ACTION_PEC = ACTION_COMPTEUR 
             @ACTION_ANNEE = @@ANNEE_ACTION_PEC
          END
          ELSE
          BEGIN
           DECLARE @separatorIndex INT
           SET @separatorIndex = CHARINDEX('/', @CODE_ACTION)
           IF @separatorIndex = 0
           BEGIN
            SET @@COD_ACTION_PEC = CONVERT(INT, @CODE_ACTION)
           END
           ELSE
           -- LDE 03/10/2013 15904
           BEGIN
            -- Mode d'utilisation des paramŠtres
            IF (@NUM_ACTION IS NOT NULL AND @MILLESIME IS NOT NULL)
            BEGIN
             SET @@COD_ACTION_PEC = @NUM_ACTION
             SET @@ANNEE_ACTION_PEC = @MILLESIME
            END
            -- Mode d'utilisation du code action … splitter
            ELSE
            BEGIN
             SET @@COD_ACTION_PEC = CONVERT(INT, SUBSTRING (@CODE_ACTION, 0, @separatorIndex - 1))
             SET @@ANNEE_ACTION_PEC = CONVERT(INT, SUBSTRING (@CODE_ACTION, @separatorIndex + 1, LEN (@CODE_ACTION) -1))
            END
           END
           -- /LDE 03/10/2013 15904
          END
           
          PRINT(CONVERT(VARCHAR(6),@@COD_ACTION_PEC))
          -- /LDE 06/06/2013 15273
         
          -- BLN_ACCORD
          declare @BLN_ACCORD tinyint
          SET @BLN_ACCORD = null
          --AMA 17/10/2008 pas coh‚rent du tout car @ID_DECISION_ACTION_PEC = 1 quand 
          --le motif refus est … 'autoris‚'
          --if @ID_DECISION_ACTION_PEC is not null OR @ID_DECISION_ACTION_PEC = 1
          -- SET @BLN_ACCORD = 0
          if @ID_DECISION_ACTION_PEC is null OR @ID_DECISION_ACTION_PEC = 1
           SET @BLN_ACCORD = 1
          else
           SET @BLN_ACCORD = 0
         
          BEGIN
           INSERT INTO ACTION_PEC
           (
            COD_ACTION_PEC,  
            LIBL_ACTION_PEC,  
            ID_THEME,
            ID_NIVEAU,
            ID_SANCTION,
            ID_OPERATION_FINANCIERE,
            DAT_DEB_ACTION_PEC,
            DAT_FIN_ACTION_PEC,
            CIBLE_ACTION,
            BLN_ACTIF,
            DAT_CREATION,
            DAT_MODIF,
            ID_UTILISATEUR,
            NUM_DUREE_JOUR,
            NUM_DUREE_HEURE,
            ID_AGENCE,
            BLN_CYCLE_COURT,
            COM_ACTION_PEC,
            ID_FORMACODE,
            ANNEE_ACTION_PEC,
            DAT_RECU,
            ID_DECISION_ACTION_PEC,
            AXE,
            DOMAINE,
            BLN_ACCORD,
            ID_UTILISATEUR_CREATEUR,
            ID_CHARGEE_MISSION
           )
           VALUES  
           (
            @@COD_ACTION_PEC,
            @LIBL_ACTION,
            @ID_THEME,
            @ID_NIVEAU,
            @ID_SANCTION,
            @ID_OPERATION,
            @DATE_DEBUT,
            @DATE_FIN,
            @CIBLE_ACTION,
            @BLN_INACTIVE,
            GETDATE(),
            GETDATE(),
            @ID_UTILISATEUR,
            @NUM_DUREE_JOUR,
            @NUM_DUREE_HEURE,
            @ID_AGENCE,
            @CICLE_COURT,
            @COM_ACTION,
            @ID_FORMACODE,
            @@ANNEE_ACTION_PEC,
            @DAT_RECU,
            @ID_DECISION_ACTION_PEC ,
            @AXE,
            @DOMAINE,
            @BLN_ACCORD,
            @ID_UTILISATEUR_CREATEUR,
            @ID_CHARGEE_MISSION
           )  
         
           SELECT @ID_ACTION_PEC = @@IDENTITY
           SET @CODE_ACTION = dbo.GetActionPECCode( @@COD_ACTION_PEC,@@ANNEE_ACTION_PEC)
         
           EXEC dbo.INS_EXPORT_D3R
            @ID_ACTION_PEC,
            'PEC'
          END
          RETURN @ID_ACTION_PEC
         END
GO

         
         create PROCEDURE [dbo].[EDI_TRANSCO_UPD_TABLE_CONCERNEE]
         /* 
           Mise  jour de l'identifiant par defaut associe  une table concerne par la transcodification EDI 
         */  
         @COD_TABLE_FAF		VARCHAR(255),
         @ID_TABLE_FAF_DEFAUT	INTEGER
         AS
         
         BEGIN
         
         SET ROWCOUNT 0
         SET NOCOUNT ON
         
         	UPDATE EDI_TRANSCO_TABLE_CONCERNEE 
         	SET  ID_TABLE_FAF_DEFAUT = @ID_TABLE_FAF_DEFAUT 
         	WHERE COD_TABLE_FAF = @COD_TABLE_FAF
         
         	IF @@ROWCOUNT = 0 
         	BEGIN
         	      /* L'enregistrement a ete detruit */
         	      RAISERROR(50002, 1, 2)
         	END   
         END  
         
         
GO
CREATE PROCEDURE [dbo].[LEC_GRP_MODULE_PEC]
         -- =======================================================================================================================================
         -- Author:  xxx
         -- Create date: xx xxx 2007
         -- Description: lecture des MODULES PEC
         -- =======================================================================================================================================
         -- Author:  SAY
         -- Modif. date: 04 juillet 2007
         -- Description: ajout d'engag‚
         -- =======================================================================================================================================
         -- Author:  SAY
         -- Modif. date: 30 juillet 2007
         -- Description: ajout du montant chiffr‚ et
         --    optimisation
         -- =======================================================================================================================================
         -- Author  : Say
         -- Modified date: 06 ao–t 2007
         -- comment  : # montant "MNT chiffr‚ " devient "MNT reste … engager"
         -- =======================================================================================================================================
         -- Author  : Say
         -- Modified date: 08 ao–t 2007
         -- comment  : # montant "MNT reste … engager" redevient "MNT chiffr‚ "
         -- =======================================================================================================================================
         -- Author  : Say
         -- Modified date: 16 ao–t 2007
         -- comment  : # restructuration de la proc‚dure car les calculs de montants n'‚taient pas toujours prises en compte
         -- =======================================================================================================================================
         -- Author  : Say
         -- Modified date: 20 ao–t 2007
         -- comment  : # table temporaire pour calculer en distinct le MNT_REGLE_HT
         -- =======================================================================================================================================
         -- Author  : SVA
         -- Modified date: 04 octobre 2007
         -- comment  : Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚
         -- =======================================================================================================================================
         -- Author  : SVA
         -- Modified date: 05 octobre 2007
         -- comment  : Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚ calcul‚ pour la colonne r‚gl‚ (r‚el)
         -- =======================================================================================================================================
         -- Author  : MBL
         -- Modified date: 16 octobre 2007
         -- comment  : Correction des conditions portant sur les actions actives et imputables
         --     Suppression du code inutile (alimentation table #TABLE_OF et #TABLE_ADH_ETAB)
         -- =======================================================================================================================================
         -- Author  : MBL
         -- Modified date: 19 octobre 2007
         -- comment  : Modification du calcul du montant engag‚
         -- =======================================================================================================================================
         -- Author  : SV
         -- Modified date: 29 octobre 2007
         -- comment  : Modification de la valeur renvoy‚e pour la la raison sociale de l'adh‚rent
         -- =======================================================================================================================================
         -- 24/04/08 Dorota 
         -- Remplacement calcul MNT_CHIFFRE pour prendre en compte PLAN_FINANCEMENT_US
         -- =======================================================================================================================================
         -- 30/06/08 RMA 
         -- Parameter @ANNEE_ACTION added
         -- =======================================================================================================================================
         -- 18/07/08 DSZE Mantis 9419 --corrige 23/07/2008 pour prendre en compte ID_ENGAGEMENT
         -- IS_ENGAGE etait calcule pour l'action et non pas pour le module, a tort
         -- =======================================================================================================================================
         -- 24/04/08 SAFI
         -- AJOUTER UN COLOUMN DANS LA SELECT MODULE_PEC.BLN_IMPUTABLE
         -- =======================================================================================================================================
         -- 16/09/08 SAFI
         -- FILTRER LES ELEMENTS POSTE_COUT_ENGAGE QUI MATCHENT AVEC #TRI_ (#TRI_ c'est la table de selection)
         -- =======================================================================================================================================
         -- 22/09/08 AMA
         -- Modification du calcul du MNT_REEL: l'utilisation de la clause distincte sur les postes
         -- de cout induit que les op‚rations de versement d'encaissement pris en compte apr‚s des d‚caissements
         -- ne sont pas pris en compte par l'appli
         -- exemple: MODULE|POSTE_COUT
         -- =======================================================================================================================================
         --   100   | 500
         --          100   |-500
         --          100   | 500 =>Element filtr‚ par la clause DISTINCT
         --      =>SOMME FAUSE (0 au lieu de 500)
         -- =======================================================================================================================================
         -- 15/10/08 AMA
         -- Prise en compte des modules inactifs (MANTIS 0010836)
         -- =======================================================================================================================================
         -- 15/10/08 AMA
         -- Annulation de la correction pr‚c‚dente
         -- =======================================================================================================================================
         -- 24/10/08 ASD
         -- Correction sur critŠre NUM_FACTURE (longueur … 50 du varchar)
         -- =======================================================================================================================================
         -- 29/12/08 AMA
         -- Correction d'un problŠme sur le calcul du nombre d'heures engag‚es (MANTIS 0011299)
         -- Ajout du nouveau systŠme de livraison (if exits .. DROP... create)
         -- =======================================================================================================================================
         -- 07/01/09 ASD
         -- valeur de la colonne "engagement possible" : on ne verifiait pas que les postes de cout 
         -- qui n'avaient jamais encore ‚t‚ engag‚s avaient recu l'approbation du chiffrage
         -- =======================================================================================================================================
         -- 08/01/09 ASD
         -- correction r‚gression sur montant engag‚ apparue sur PCE non encore engag‚s (Mantis 11367)
         -- =======================================================================================================================================
         -- 14/01/09 ASD
         -- correction s‚lection des modules n'ayant jamais ‚t‚ engag‚s (Mantis 11367)
         -- Cette correction doit ˆtre ‚valu‚e avec la plus grande prudence.
         -- =======================================================================================================================================
         -- 14/01/09 AMA
         -- Correction s‚lection des modules ayant ‚t‚ engag‚s (MANTIS 11367)
         -- Cette correction doit ˆtre ‚valu‚e avec la plus grande prudence.
         -- =======================================================================================================================================
         -- 29/01/09 AMA
         -- Les deux corrections pr‚c‚dentes (MANTIS 11367) ont entrain‚
         -- une regression (MANTIS 0011473) car le critŠre d'engagement/d‚sengagement
         -- ‚tait mal pris en compte (pour les actions courtes et les bases de reprise)
         -- =======================================================================================================================================
         -- 29/01/05 ASD
         -- Correction de constraint dans la colonne BLN_OK_FINANCEMENT
         -- =======================================================================================================================================
         -- 24/02/09 SAFI
         -- CORRECTION DE COLOUMN COD_ADHERENT FOR DISPLAY AIC/AC or COD_ADHERENT
         -- =======================================================================================================================================
         -- 14/04/2009 SAFI
         -- CHANGER LES CALCUL POUR NB HEUR ENGAGE 
         -- STAGIAIRE_PEC.ID_SESSION_PEC IS NOT NULL 
         -- =======================================================================================================================================
         -- 14/05/2009 ASD SAF
         -- revision de la correction AMA du 29/12 pour NB_H_ENGAGEES 
         -- STAGIAIRE_PEC.ID_SESSION_PEC IS NULL AND ACTION IS ENGAGED
         -- =======================================================================================================================================
         -- 18/05/2009 SAFI
         -- Correction dans la calcul de mnt regle!
         -- =======================================================================================================================================
         -- 04/06/2009 DSZ
         -- changement float->decimal dans la requete finale Mantis 12060
         -- =======================================================================================================================================
         -- 12/06/2009 DSZ
         -- Mantis 12077 mauvais calcul de "chiffrage inacheve". faut prendre min au lieu de sum
         -- =======================================================================================================================================
         -- 26/06/2009 ASD
         -- Correction calcul de MNT_DEMANDE (MNT_PREVISIONNEL) : ne pas prendre en compte les anciens postes de cout
         -- am‚lioration CAST en decimal (18,2)
         -- =======================================================================================================================================
         -- 08/12/2009 SAFI ano id 12251
         -- Correction calcul de MNT_CHIFFRE, Filtre sur PCE non d‚sengag‚ 
         -- Correction trasmis par SBR
         -- =======================================================================================================================================
         -- SAFI AJOUTER ano 12345 05/05/2010 ajout colonne ACTION_PEC_CLOTURE
         -- =======================================================================================================================================
         -- Author  : ASD DSZ
         -- Modified date: 13/10/2010
         -- comment  : 12423 Perf.  + indexes associ‚s
         -- =======================================================================================================================================
         -- Author  : DSZ ASD
         -- Modified date: 25/10/2010
         -- comment  : correction ano rapporte par mail 25/10/2010 ID_MODULE_PEC -> ID_MODULE
         --      + correction premier select #tri : manque clauses sur bln_actif et imputable
         -- =======================================================================================================================================
         -- Author  : DSZ
         -- Modified date: 15/11/2010 - 18/11/2010
         -- comment  : 12544 perf
         -- =======================================================================================================================================
         -- Author  : DSZ
         -- Modified date: 30/09/2011
         -- comment  : 12570 Ne pas prendre en compte les US refus‚s pour calculer le mnt chiffr‚
         -- =======================================================================================================================================
         -- Author  : DSZ
         -- Modified date: 10/11/2011
         -- comment  : 12940 Ne pas prendre en compte les PCE … 0 pour determiner si ok financement
         -- =======================================================================================================================================
         -- Author  : DSZ
         -- Modified date: 17/02/2012
         -- comment  : 13261 Ajout de BLN_MODULE_CLOTURE
         -- Modification de methode de calcul de IS_ENGAGE : reprise de la logique de ACTION_ENGAGED
         -- =======================================================================================================================================
         -- Author  : DSZ
         -- Modified date: 14/05/2012
         -- comment  : 13462 reprise de 12940  : on ne prend pas en compte les PCE … 0 pour ok financement,
         -- mais on les prend en compte pour is_engage. sinon on ne peut pas desengager le module engag‚ mais … 0.
         -- =======================================================================================================================================
         -- DSZ 15/06/2012 13601 RAISON_SOCIALE_OF varchar(50) -> varchar(64)
         -- =======================================================================================================================================
         -- ASD/DSZ 30/07/2102 13766 la correction 13462 ne pas valable pour les modules pas engag‚s
         -- =======================================================================================================================================
         -- OPA #219 En tant qu'utilisateur habilit‚ Optiform, lorsque je consulte la liste des dossiers PEC engageables, je veux que seuls les 
         -- modules ayant des piŠces Bloquant l'engagement absentes ou non conformes soient r‚pertori‚s en "PiŠce manquante"
         -- =======================================================================================================================================
         -- Author  : MB
         -- Modif. date  : 13/08/2015
         -- Description  : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
         --                Correction adapation faite sur US # 219 mal g‚r‚e
         --                Un module dont une (ou +sieurs) piŠce active est absente doit positionner le module en PiŠce manquante et bloquer son engagement 
         --                ce qui n'est plus le cas … ce jour
         -- =======================================================================================================================================
         -- Author  : MBL 
         -- Modif. date : 21/10/2015
         -- Description  : Refonte complŠte de la PS suite … pr‚conisation DBA
         -- =======================================================================================================================================
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250)
         -- =======================================================================================================================================  
          @COD_ACTION     INT,
          @ANNEE_ACTION    INT,
          @LIBL_ACTION_PEC   VARCHAR(250),
          @ID_ETABLISSEMENT_OF  INT,
          @ID_THEME     INT,
          @ID_STAGE     INT,
          @ID_FORMACODE    INT,
          @ID_INDIVIDU    INT,
          @ID_ADHERENT    INT,
          @ID_ETABLISSEMENT   INT,
          @NUM_ANNEE      INT,
          @DEPARTMENT     INT,
          @DATE_DEBUT_ENTRE_LE  DATETIME, 
          @DATE_DEBUT_ET_LE    DATETIME, 
          @DATE_FIN_ENTRE_LE    DATETIME, 
          @DATE_FIN_ET_LE    DATETIME, 
          @BLN_NON_IMPUTABLES   INT,
          @BLN_INACTIVES    INT,
          @NUM_FACTURE     VARCHAR(50),
          @MONTANT_FACTUE    DECIMAL(18,2),
          @ID_CODE_OF     INT,
          @NUM_INTERNE     VARCHAR(50)
         
         
         AS
         BEGIN
         
         
          CREATE TABLE #TMP01
          (
           ID_MODULE     INT,
           ID_ACTION_PEC    INT,
           NUM_MODULE     VARCHAR(14),
           LIBELLE_MODULE    VARCHAR(250),
           DATE_DEBUT     DATETIME,
           DATE_FIN     DATETIME,
           RAISON_SOCIALE_OF   VARCHAR(64),
           COD_ADHERENT    VARCHAR(10), 
           ADHERENT_RAISON_SOCIALE  VARCHAR(50),
           BLN_CYCLE_COURT    TINYINT,   
           BLN_ACTIF     TINYINT,
           BLN_IMPUTABLE    TINYINT,
           BLN_OK_PIECE    TINYINT,
           BLN_OK_ENGAGEMENT   TINYINT default 1,
           LIB_BLN_DELEGATION_PAIEMENT VARCHAR(1),
           ACTION_PEC_CLOTURE   TINYINT,
           BLN_MODULE_CLOTURE   TINYINT,
           MNT_CHIFFRE     DECIMAL(18,2) default 0.0,
           MNT_PREVISIONNEL   float default 0,
           MNT_ENGAGE     float default 0,
           MNT_REEL     float default 0,
           IS_ENGAGE     INTEGER default 0,
           NB_STAGIAIRES    INTEGER default 0,
           NB_H_ENGAGEES    FLOAT default 0,
           NB_H_REALISEES    FLOAT default 0,
           ENGAGEMENT_POSSIBLE   VARCHAR(18) NULL,
           
           -- ELEMENT AJOUTES
           CIBLE_ACTION    INT,
           BLN_OK_FINANCEMENT   INT
           
          )
         
          DECLARE @NB_STAGIAIRES INT
          DECLARE @NB_H_ENGAGEES INT
          DECLARE @NB_H_REALISEES INT
         
          DECLARE @SQLQuery AS NVARCHAR(4000)
          DECLARE @ParameterDefinition AS NVARCHAR(2500) 
         
          IF (@BLN_NON_IMPUTABLES IS NULL)
          BEGIN
           SET @BLN_NON_IMPUTABLES = 0
          END 
         
          IF (@BLN_INACTIVES IS NULL)
          BEGIN
           SET @BLN_INACTIVES = 0
          END
         
         
          SET @SQLQuery = ''
         
          SET @SQLQuery += ' INSERT INTO #TMP01'
          SET @SQLQuery += ' (ID_MODULE,'
          SET @SQLQuery += ' ID_ACTION_PEC,'
          SET @SQLQuery += ' NUM_MODULE,'
          SET @SQLQuery += ' LIBELLE_MODULE,'
          SET @SQLQuery += ' DATE_DEBUT,'
          SET @SQLQuery += ' DATE_FIN,'
          SET @SQLQuery += ' RAISON_SOCIALE_OF,'
          SET @SQLQuery += ' BLN_CYCLE_COURT,'  
          SET @SQLQuery += ' BLN_ACTIF,'
          SET @SQLQuery += ' BLN_IMPUTABLE,'
          SET @SQLQuery += ' BLN_OK_PIECE,'
          SET @SQLQuery += ' LIB_BLN_DELEGATION_PAIEMENT,'
          SET @SQLQuery += ' ACTION_PEC_CLOTURE,'
          SET @SQLQuery += ' BLN_MODULE_CLOTURE,'
          SET @SQLQuery += '  CIBLE_ACTION'
          SET @SQLQuery += ' )'
          SET @SQLQuery += ' SELECT  TOP 301'
          SET @SQLQuery += ' ID_MODULE =MODULE_PEC.ID_MODULE_PEC,'
          SET @SQLQuery += ' ACTION_PEC.ID_ACTION_PEC,'
          SET @SQLQuery += ' NUM_MODULE = MODULE_PEC.COD_MODULE_PEC,'
          SET @SQLQuery += ' LIBELLE_MODULE = MODULE_PEC.LIBL_MODULE_PEC,'
          SET @SQLQuery += ' DATE_DEBUT = MODULE_PEC.DAT_DEBUT,'
          SET @SQLQuery += ' DATE_FIN = MODULE_PEC.DAT_FIN,'
          SET @SQLQuery += ' RAISON_SOCIALE_OF = ORGANISME_FORMATION.LIB_RAISON_SOCIALE,'
          SET @SQLQuery += ' ACTION_PEC.BLN_CYCLE_COURT,          ' 
          SET @SQLQuery += ' MODULE_PEC.BLN_ACTIF,           '   
          SET @SQLQuery += ' MODULE_PEC.BLN_IMPUTABLE,          '
          SET @SQLQuery += ' MODULE_PEC.BLN_OK_PIECE,          '
          SET @SQLQuery += ' LIB_BLN_DELEGATION_PAIEMENT = CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN  '
          SET @SQLQuery +=                      '''X'''
          SET @SQLQuery +=                     ' ELSE '
          SET @SQLQuery +=                      ''''''
          SET @SQLQuery +=                     'END,'
          SET @SQLQuery += ' ACTION_PEC_CLOTURE = (CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END),'
          SET @SQLQuery += ' BLN_MODULE_CLOTURE = (CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END),'
          SET @SQLQuery += ' CIBLE_ACTION = ACTION_PEC.CIBLE_ACTION'
          SET @SQLQuery += ' FROM  MODULE_PEC'
          SET @SQLQuery += ' INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC'
          SET @SQLQuery += ' INNER JOIN PERIODE ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE        '
          SET @SQLQuery += ' LEFT JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF '
          SET @SQLQuery += ' LEFT JOIN ORGANISME_FORMATION ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF      '
          SET @SQLQuery += ' LEFT JOIN ADRESSE ON ADRESSE.ID_ADRESSE = ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE '
          
          SET @SQLQuery += ' WHERE MODULE_PEC.BLN_IMPUTABLE >= (CASE @BLN_NON_IMPUTABLES WHEN 0 THEN 1 ELSE 0 END) '
          
          SET @SQLQuery += ' AND  ACTION_PEC.BLN_ACTIF >= (CASE @BLN_INACTIVES WHEN 0 THEN 1 ELSE 0 END)'
         
          IF @COD_ACTION  IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND ACTION_PEC.COD_ACTION_PEC = @COD_ACTION '
          END
          
          IF @ANNEE_ACTION  IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION'
          END
          IF @LIBL_ACTION_PEC  IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND ACTION_PEC.LIBL_ACTION_PEC LIKE  RTRIM(@LIBL_ACTION_PEC)'
          END
          
          IF  @ID_CODE_OF IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND ORGANISME_FORMATION.ID_OF = @ID_CODE_OF'
          END  
         
          IF  @ID_THEME IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_THEME = @ID_THEME'
          END  
         
          IF  @ID_STAGE IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_STAGE = @ID_STAGE'
          END  
         
          IF  @ID_FORMACODE IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_FORMACODE = @ID_FORMACODE'
          END  
         
          IF  @NUM_ANNEE IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND PERIODE.NUM_ANNEE = @NUM_ANNEE'
          END  
         
          IF  @DEPARTMENT IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND LEFT(ADRESSE.LIB_CP_CEDEX, 2) = RIGHT(''0''+CAST(@DEPARTMENT AS VARCHAR), 2)'
          END  
         
          IF @DATE_DEBUT_ENTRE_LE IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND MODULE_PEC.DAT_DEBUT >= @DATE_DEBUT_ENTRE_LE'
          END
         
          IF @DATE_DEBUT_ET_LE IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND MODULE_PEC.DAT_DEBUT <= @DATE_DEBUT_ET_LE'
          END
         
          IF @DATE_FIN_ENTRE_LE IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND MODULE_PEC.DAT_FIN >= @DATE_FIN_ENTRE_LE'
          END
         
          IF @DATE_FIN_ET_LE IS NOT NULL
          BEGIN
           SET @SQLQuery += ' AND MODULE_PEC.DAT_FIN <= @DATE_FIN_ET_LE'
          END
         
          IF  @NUM_INTERNE IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.NUM_INTERNE = @NUM_INTERNE'
          END  
         
          IF  @ID_ETABLISSEMENT_OF IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF'
          END  
         
          IF  @ID_ADHERENT IS NOT NULL OR @ID_ETABLISSEMENT IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND ACTION_PEC.ID_ACTION_PEC IN '
           SET @SQLQuery +=        ' ('
           SET @SQLQuery +=        ' SELECT ID_ACTION_PEC '
           SET @SQLQuery +=         ' FROM NR140 '
           SET @SQLQuery +=         ' INNER JOIN ETABLISSEMENT ON NR140 .ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT '
           IF  @ID_ADHERENT IS NOT NULL
           BEGIN
            SET @SQLQuery +=        ' WHERE ETABLISSEMENT .ID_ADHERENT = @ID_ADHERENT'
           END
           IF  @ID_ETABLISSEMENT IS NOT NULL
           BEGIN
            SET @SQLQuery +=        ' AND ETABLISSEMENT .ID_ETABLISSEMENT = @ID_ETABLISSEMENT'
           END
           SET @SQLQuery +=        ' )'
          END  
         
         
          IF  @ID_INDIVIDU IS NOT NULL
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_MODULE_PEC IN '
           SET @SQLQuery +=     ' ('
           SET @SQLQuery +=     ' SELECT ID_MODULE_PEC'
           SET @SQLQuery +=      ' FROM STAGIAIRE_PEC '
           SET @SQLQuery +=      ' WHERE ID_INDIVIDU = @ID_INDIVIDU'
           SET @SQLQuery +=     ' )'
          END  
         
          IF  @NUM_FACTURE IS NOT NULL OR @MONTANT_FACTUE IS NOT NULL 
          BEGIN 
           SET @SQLQuery += ' AND MODULE_PEC.ID_MODULE_PEC IN '
           SET @SQLQuery +=        ' ('
           SET @SQLQuery +=        ' SELECT ID_MODULE_PEC '
           SET @SQLQuery +=         ' FROM POSTE_COUT_REGLE '
           SET @SQLQuery +=         ' WHERE 1 = 1'
           IF  @NUM_FACTURE IS NOT NULL
           BEGIN
            SET @SQLQuery +=        ' AND POSTE_COUT_REGLE .NUM_FACTURE = @NUM_FACTURE'
           END
           IF  @MONTANT_FACTUE IS NOT NULL
           BEGIN
            SET @SQLQuery +=        ' AND POSTE_COUT_REGLE.MNT_REGLE_TTC = @MONTANT_FACTUE '
            SET @SQLQuery +=        ' AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1'
           END
           SET @SQLQuery +=        ' )'
          END  
         
          SET @SQLQuery += ' ORDER BY MODULE_PEC.ID_MODULE_PEC'
         
         --SELECT @SQLQuery
         
          SET @ParameterDefinition = '@COD_ACTION INT,@ANNEE_ACTION INT,@LIBL_ACTION_PEC VARCHAR(250), @ID_ETABLISSEMENT_OF INT, @ID_THEME int, @ID_STAGE int, @ID_FORMACODE int, @ID_INDIVIDU INT, @ID_ADHERENT INT, @ID_ETABLISSEMENT INT, @NUM_ANNEE int, @DEPARTMENT int , @DATE_DEBUT_ENTRE_LE DATETIME, @DATE_DEBUT_ET_LE DATETIME, @DATE_FIN_ENTRE_LE DATETIME, @DATE_FIN_ET_LE DATETIME, @BLN_NON_IMPUTABLES INT, @BLN_INACTIVES INT, @NUM_FACTURE VARCHAR(50), @MONTANT_FACTUE DECIMAL(18,2), @ID_CODE_OF INT, @NUM_INTERNE VARCHAR(50)'
         
         
          EXECUTE sp_executesql @SQLQuery, @ParameterDefinition, @COD_ACTION, @ANNEE_ACTION, @LIBL_ACTION_PEC, @ID_ETABLISSEMENT_OF, @ID_THEME, 
          @ID_STAGE , @ID_FORMACODE, @ID_INDIVIDU, @ID_ADHERENT, @ID_ETABLISSEMENT, @NUM_ANNEE, @DEPARTMENT, 
          @DATE_DEBUT_ENTRE_LE, @DATE_DEBUT_ET_LE, @DATE_FIN_ENTRE_LE, @DATE_FIN_ET_LE, @BLN_NON_IMPUTABLES, @BLN_INACTIVES, 
          @NUM_FACTURE, @MONTANT_FACTUE, @ID_CODE_OF, @NUM_INTERNE
         
         
          UPDATE #TMP01
          SET COD_ADHERENT = ADH_ACTION.COD_ADHERENT, ADHERENT_RAISON_SOCIALE = ADH_ACTION.ADHERENT_RAISON_SOCIALE
          FROM #TMP01 T
          INNER JOIN
           (SELECT ID_ACTION_PEC, COD_ADHERENT  = MAX(COD_ADHERENT), ADHERENT_RAISON_SOCIALE = MAX(LIB_RAISON_SOCIALE)
           FROM NR140
           INNER JOIN ETABLISSEMENT ON NR140.ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT 
           INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT= ETABLISSEMENT .ID_ADHERENT
           GROUP BY ID_ACTION_PEC
           ) 
           ADH_ACTION ON T.ID_ACTION_PEC = ADH_ACTION.ID_ACTION_PEC
          WHERE T.CIBLE_ACTION = 1
         
          UPDATE #TMP01 
          SET  COD_ADHERENT = 'AIC', ADHERENT_RAISON_SOCIALE ='AIC'
          FROM #TMP01 T
          WHERE T.CIBLE_ACTION = 2
         
          UPDATE #TMP01 
          SET  COD_ADHERENT = 'AC', ADHERENT_RAISON_SOCIALE ='AC'
          FROM #TMP01 T
          WHERE T.CIBLE_ACTION = 3
         
         
          -- Recherche si des pieces bloquant l'engagement sont absentes ou non conformes
          UPDATE #TMP01
          SET BLN_OK_ENGAGEMENT = KO_PIECE_ENGAGEMENT.BLN_OK_ENGAGEMENT
          FROM #TMP01 T
          INNER JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
              0 AS BLN_OK_ENGAGEMENT
              FROM ARRIVEE_PIECE_PEC 
              INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
              INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC   
              AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
              AND
              (
               ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
               OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
              )
              AND PIECE_PEC.BLN_ACTIF = 1
              GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC
             ) 
          KO_PIECE_ENGAGEMENT ON KO_PIECE_ENGAGEMENT.ID_MODULE_PEC = T.ID_MODULE
          
           
          -- Calcul des montants r‚gl‚s
          UPDATE #TMP01
          SET MNT_REEL = ISNULL(REGLE.MNT_REGLE_HT, 0)
          FROM #TMP01 T
          INNER JOIN
           (
            SELECT ID_MODULE_PEC,
              MNT_REGLE_HT = SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) 
            FROM POSTE_COUT_REGLE   
            INNER JOIN REGLEMENT   ON REGLEMENT.ID_REGLEMENT   = POSTE_COUT_REGLE.ID_REGLEMENT 
                    AND (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL)
            GROUP BY ID_MODULE_PEC
           )
          REGLE ON REGLE.ID_MODULE_PEC = T.ID_MODULE
         
         
         
          -- Calcul des montants demandes (previsionnels)
          UPDATE #TMP01
          SET MNT_PREVISIONNEL = ISNULL(DEMANDE.MNT_PREVISIONNEL_HT, 0),
           BLN_OK_FINANCEMENT = ISNULL(DEMANDE.BLN_OK_FINANCEMENT, 0)
          FROM #TMP01 T
          INNER JOIN
           (
            SELECT 
             ID_MODULE_PEC, 
             MNT_PREVISIONNEL_HT = SUM(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT) ,
             BLN_OK_FINANCEMENT  = MIN(POSTE_COUT_ENGAGE.BLN_OK_FINANCEMENT) 
            FROM POSTE_COUT_ENGAGE
            WHERE POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
            GROUP BY POSTE_COUT_ENGAGE.ID_MODULE_PEC
           )
          DEMANDE ON DEMANDE.ID_MODULE_PEC =  T.ID_MODULE
         
         
          -- Calcul des montants chiffr‚s
          UPDATE #TMP01
          SET MNT_CHIFFRE = ISNULL(CHIFFRE.MNT_CHIFFRE, 0),
           MNT_ENGAGE = ISNULL(CHIFFRE.MNT_ENGAGE, 0) ,
           IS_ENGAGE = ISNULL(CHIFFRE.IS_ENGAGE, 0)   
          FROM #TMP01 T
          INNER JOIN
           (
            SELECT 
             ID_MODULE_PEC, 
             MNT_CHIFFRE = SUM(ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US, 0)) ,
             MNT_ENGAGE =  SUM(CASE WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL THEN 0 ELSE ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US, 0) END) ,
             IS_ENGAGE =  MAX(CASE WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL THEN 0 ELSE 1 END) 
            FROM POSTE_COUT_ENGAGE
            INNER JOIN PLAN_FINANCEMENT_US ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US .ID_POSTE_COUT_ENGAGE
                    AND PLAN_FINANCEMENT_US .ID_POSTE_COUT_REGLE IS NULL
            WHERE POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
            GROUP BY POSTE_COUT_ENGAGE.ID_MODULE_PEC
           )
          CHIFFRE ON CHIFFRE.ID_MODULE_PEC = T.ID_MODULE
         
         
          -- Calcul du NB de stagiaire et du NB d'heures engag‚es
          UPDATE #TMP01
          SET NB_STAGIAIRES= ISNULL(NB_STAGIAIRES_ENG.NB_STAGIAIRE, 0), 
           NB_H_ENGAGEES= ISNULL(NB_STAGIAIRES_ENG.NB_HEURE_ENGAGE, 0) 
          FROM #TMP01 T
          INNER JOIN
           (
            SELECT ID_MODULE_PEC,
              NB_STAGIAIRE= COUNT(STAGIAIRE_PEC.ID_STAGIAIRE_PEC) ,
              NB_HEURE_ENGAGE = SUM(STAGIAIRE_PEC.NB_HEURE_ENGAGE)
              
            FROM STAGIAIRE_PEC
            WHERE ID_SESSION_PEC IS NULL
            GROUP BY ID_MODULE_PEC
           )
          NB_STAGIAIRES_ENG ON NB_STAGIAIRES_ENG.ID_MODULE_PEC = T.ID_MODULE
          UPDATE #TMP01
          SET NB_H_ENGAGEES = NB_H_ENGAGEES * IS_ENGAGE
          
         
          -- Calcul du NB d'heures r‚alis‚es (Session actives du module)
          UPDATE #TMP01
          SET NB_H_REALISEES= ISNULL(NB_STAGIAIRES_REGLE.NB_HEURE_REGLE, 0)
          FROM #TMP01 T
          INNER JOIN
           (
            SELECT STAGIAIRE_PEC.ID_MODULE_PEC,
              NB_HEURE_REGLE = SUM(UNITE_STAGIAIRE.NB_HEURE_REGLE)
            FROM STAGIAIRE_PEC
            INNER JOIN SESSION_PEC  ON SESSION_PEC.ID_SESSION_PEC  = STAGIAIRE_PEC.ID_SESSION_PEC
            INNER JOIN UNITE_STAGIAIRE ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
            WHERE SESSION_PEC.BLN_ACTIF = 1
            GROUP BY STAGIAIRE_PEC.ID_MODULE_PEC
            
           )
          NB_STAGIAIRES_REGLE ON NB_STAGIAIRES_REGLE.ID_MODULE_PEC = T.ID_MODULE
         
         
          -- Valorisation de la colonne [Engagement Possible]
          UPDATE #TMP01
          SET ENGAGEMENT_POSSIBLE = 'PiŠce Manquante'
          WHERE BLN_OK_ENGAGEMENT = 0
          AND  BLN_ACTIF = 1 
          AND  BLN_IMPUTABLE = 1
          
          UPDATE #TMP01
          SET  ENGAGEMENT_POSSIBLE = 'Chiffrage inachev‚' 
          WHERE ENGAGEMENT_POSSIBLE IS NULL
          AND  BLN_OK_FINANCEMENT = 0
          AND  BLN_ACTIF = 1 
          AND  BLN_IMPUTABLE = 1
         
          UPDATE #TMP01
          SET  ENGAGEMENT_POSSIBLE = 'Possible' 
          WHERE ENGAGEMENT_POSSIBLE IS NULL
          AND  BLN_ACTIF = 1 
          AND  BLN_IMPUTABLE = 1
         
          UPDATE #TMP01
          SET  ENGAGEMENT_POSSIBLE = '' 
          WHERE ENGAGEMENT_POSSIBLE IS NULL
         
         
          UPDATE #TMP01
          SET 
           MNT_CHIFFRE     = ROUND(MNT_CHIFFRE   , 2),
           MNT_PREVISIONNEL   = ROUND(MNT_PREVISIONNEL , 2),
           MNT_ENGAGE     = ROUND(MNT_ENGAGE   , 2)
          
          SELECT 
           ID_MODULE     ,
           ID_ACTION_PEC    ,
           NUM_MODULE     ,
           LIBELLE_MODULE    ,
           DATE_DEBUT     ,
           DATE_FIN     ,
           RAISON_SOCIALE_OF   ,
           COD_ADHERENT    , 
           ADHERENT_RAISON_SOCIALE  ,
           BLN_CYCLE_COURT    ,   
           BLN_ACTIF     ,
           BLN_IMPUTABLE    ,
           BLN_OK_PIECE    ,
           BLN_OK_ENGAGEMENT   ,
           LIB_BLN_DELEGATION_PAIEMENT ,
           ACTION_PEC_CLOTURE   ,
           BLN_MODULE_CLOTURE   ,
           MNT_CHIFFRE     ,
           MNT_PREVISIONNEL   ,
           MNT_ENGAGE     ,
           MNT_REEL     ,
           IS_ENGAGE     ,
           NB_STAGIAIRES    ,
           NB_H_ENGAGEES    ,
           NB_H_REALISEES    ,
           ENGAGEMENT_POSSIBLE   
          FROM #TMP01
         
         /*
         Code Supprime Suite A Refonte
         -----------------------------
         -- MBL du 21/10/2015
         -- Description  : Refonte complŠte de la PS suite … pr‚conisation DBA
         
         CREATE TABLE #TRI_ (
           ID_MODULE INT,
           ID_ACTION_PEC INT,
           NUM_MODULE  VARCHAR(14),
           LIBELLE_MODULE VARCHAR(250),
           DATE_DEBUT DATETIME,
           DATE_FIN DATETIME,
           RAISON_SOCIALE_OF VARCHAR(64),
           COD_ADHERENT VARCHAR(10), 
           ADHERENT_RAISON_SOCIALE VARCHAR(50),
           BLN_CYCLE_COURT TINYINT,   
           BLN_ACTIF TINYINT,
           BLN_IMPUTABLE TINYINT,
           BLN_OK_PIECE TINYINT,
           BLN_OK_ENGAGEMENT TINYINT,
           LIB_BLN_DELEGATION_PAIEMENT VARCHAR(1),
           ACTION_PEC_CLOTURE TINYINT,
           BLN_MODULE_CLOTURE TINYINT
         )
         
         IF( @COD_ACTION     IS NOT NULL AND 
          @LIBL_ACTION_PEC   IS NULL AND 
          @ID_ETABLISSEMENT_OF  IS NULL AND 
          @ID_THEME     IS NULL AND 
          @ID_STAGE     IS NULL AND 
          @ID_FORMACODE    IS NULL AND 
          @ID_INDIVIDU    IS NULL AND
          @ID_ADHERENT    IS NULL AND 
          @ID_ETABLISSEMENT   IS NULL AND 
          @DEPARTMENT     IS NULL AND 
          @DATE_DEBUT_ENTRE_LE  IS NULL AND  
          @DATE_DEBUT_ET_LE    IS NULL AND  
          @DATE_FIN_ENTRE_LE    IS NULL AND  
          @DATE_FIN_ET_LE    IS NULL AND  
          @NUM_FACTURE     IS NULL AND 
          @MONTANT_FACTUE    IS NULL AND 
          @ID_CODE_OF     IS NULL AND 
          @NUM_INTERNE     IS NULL 
         )
         BEGIN
         
         
         
          -- Lecture des donnees ---------------------------------------------------------------------------------------------------------------
          INSERT INTO #TRI_
          SELECT DISTINCT TOP 301 
           MODULE_PEC.ID_MODULE_PEC AS ID_MODULE,
           ACTION_PEC.ID_ACTION_PEC,
           MODULE_PEC.COD_MODULE_PEC   AS NUM_MODULE,
           MODULE_PEC.LIBL_MODULE_PEC   AS LIBELLE_MODULE,
           --MODULE_PEC.ID_REGLE_CHIFFRAGE       AS ID_REGLE_CHIFFRAGE,
           MODULE_PEC.DAT_DEBUT    AS DATE_DEBUT,
           MODULE_PEC.DAT_FIN     AS DATE_FIN,
           ORGANISME_FORMATION.LIB_RAISON_SOCIALE   AS RAISON_SOCIALE_OF,
           CASE 
            WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN  CAST(ADHERENT.COD_ADHERENT AS VARCHAR(10))
            WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
            ELSE 'AC'
           END         AS COD_ADHERENT, 
           CASE 
            WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN ADHERENT.LIB_RAISON_SOCIALE 
            WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
            ELSE 'AC'
           END         AS ADHERENT_RAISON_SOCIALE,
           ACTION_PEC.BLN_CYCLE_COURT,  
           MODULE_PEC.BLN_ACTIF,
           MODULE_PEC.BLN_IMPUTABLE,
           MODULE_PEC.BLN_OK_PIECE,
           COALESCE(PIECEMODULEPEC.BLN_OK_ENGAGEMENT, 1) AS BLN_OK_ENGAGEMENT,
           CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN  'X'  ELSE '' END   
           AS  LIB_BLN_DELEGATION_PAIEMENT,
           (CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS ACTION_PEC_CLOTURE,
           (CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS BLN_MODULE_CLOTURE
           
          FROM  MODULE_PEC
           INNER JOIN ACTION_PEC   ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
           LEFT JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
               0 AS BLN_OK_ENGAGEMENT
              FROM ARRIVEE_PIECE_PEC 
              INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
              INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC   
              AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
              AND
              (
               ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
               OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
              )
              -- Modif MB . du 13/08/2015 : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
              --WHERE ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
              AND PIECE_PEC.BLN_ACTIF = 1
              GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC) PIECEMODULEPEC ON PIECEMODULEPEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           LEFT JOIN ETABLISSEMENT_OF  ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
           LEFT JOIN ORGANISME_FORMATION ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
           INNER JOIN NR140    ON NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
           inner join ETABLISSEMENT  ON NR140.ID_ETABLISSEMENT IS NOT NULL AND NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           LEFT JOIN ADHERENT    ON ETABLISSEMENT.ID_ADHERENT IS NOT NULL AND ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
           INNER JOIN PERIODE    ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
          WHERE
            ((@COD_ACTION IS NULL) OR (ACTION_PEC.COD_ACTION_PEC = @COD_ACTION))  
           AND ((@ANNEE_ACTION IS NULL) OR (ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION))    
           AND ((@NUM_ANNEE IS NULL) OR (PERIODE.NUM_ANNEE IS NOT NULL AND PERIODE.NUM_ANNEE= @NUM_ANNEE))
           AND (MODULE_PEC.BLN_IMPUTABLE >= CASE @BLN_NON_IMPUTABLES WHEN 0 THEN 1 ELSE 0 END)
           AND (ACTION_PEC.BLN_ACTIF >= CASE @BLN_INACTIVES WHEN 0 THEN 1 ELSE 0 END)
          ORDER BY MODULE_PEC.ID_MODULE_PEC
          OPTION(RECOMPILE)
         END
         ELSE
         BEGIN
          INSERT INTO #TRI_
          SELECT DISTINCT TOP 301 
           MODULE_PEC.ID_MODULE_PEC    AS ID_MODULE,
           ACTION_PEC.ID_ACTION_PEC,
           MODULE_PEC.COD_MODULE_PEC    AS NUM_MODULE,
           MODULE_PEC.LIBL_MODULE_PEC    AS LIBELLE_MODULE,
           --MODULE_PEC.ID_REGLE_CHIFFRAGE   As ID_REGLE_CHIFFRAGE,
           MODULE_PEC.DAT_DEBUT     AS DATE_DEBUT,
           MODULE_PEC.DAT_FIN      AS DATE_FIN,
           ORGANISME_FORMATION.LIB_RAISON_SOCIALE AS RAISON_SOCIALE_OF,
           CASE 
            WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN  cast(ADHERENT.COD_ADHERENT as varchar(10))  
            WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
            ELSE 'AC'
           END          AS COD_ADHERENT, 
           CASE 
            WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN ADHERENT.LIB_RAISON_SOCIALE 
            WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
            ELSE 'AC'
           END          AS ADHERENT_RAISON_SOCIALE,
           ACTION_PEC.BLN_CYCLE_COURT,  
           MODULE_PEC.BLN_ACTIF,
           MODULE_PEC.BLN_IMPUTABLE,
           MODULE_PEC.BLN_OK_PIECE,
           COALESCE(PIECEMODULEPEC.BLN_OK_ENGAGEMENT, 1) AS BLN_OK_ENGAGEMENT,
           CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN
            'X' 
           ELSE
            ''
           END   
           AS  LIB_BLN_DELEGATION_PAIEMENT,
           (CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS ACTION_PEC_CLOTURE,
           (CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS BLN_MODULE_CLOTURE
           
          FROM  MODULE_PEC
           INNER JOIN ACTION_PEC   ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
           LEFT JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
               0 AS BLN_OK_ENGAGEMENT
              FROM ARRIVEE_PIECE_PEC 
              INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
              INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC   
              AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
              AND
              (
               ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
               OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
              )
              -- Modif MB . du 13/08/2015 : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
              --WHERE ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
              AND PIECE_PEC.BLN_ACTIF = 1
              GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC) PIECEMODULEPEC ON PIECEMODULEPEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           LEFT JOIN ETABLISSEMENT_OF  ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
           LEFT JOIN ADRESSE    ON ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE IS NOT NULL AND ADRESSE.ID_ADRESSE = ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE
           LEFT JOIN ORGANISME_FORMATION ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
           INNER JOIN NR140    ON NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
           INNER JOIN ETABLISSEMENT  ON NR140.ID_ETABLISSEMENT IS NOT NULL AND NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           LEFT JOIN ADHERENT    ON ETABLISSEMENT.ID_ADHERENT IS NOT NULL AND ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
           INNER JOIN PERIODE    ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
           LEFT JOIN POSTE_COUT_REGLE  ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           LEFT JOIN STAGIAIRE_PEC   ON STAGIAIRE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
          WHERE
            ((@COD_ACTION   IS NULL) OR (ACTION_PEC.COD_ACTION_PEC IS NOT NULL AND ACTION_PEC.COD_ACTION_PEC = @COD_ACTION))  
           AND ((@ANNEE_ACTION   IS NULL) OR (ACTION_PEC.ANNEE_ACTION_PEC IS NOT NULL AND ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION))    
           AND ((@LIBL_ACTION_PEC  IS NULL) OR (ACTION_PEC.LIBL_ACTION_PEC IS NOT NULL AND ACTION_PEC.LIBL_ACTION_PEC LIKE  RTRIM(@LIBL_ACTION_PEC)))  
           AND  ((@ID_CODE_OF   IS NULL) OR (ORGANISME_FORMATION.ID_OF = @ID_CODE_OF))
              AND ((@ID_THEME    IS NULL) OR (MODULE_PEC.ID_THEME = @ID_THEME))
           AND  ((@ID_STAGE   IS NULL) OR (MODULE_PEC.ID_STAGE IS NOT NULL AND MODULE_PEC.ID_STAGE = @ID_STAGE))
           AND  ((@ID_FORMACODE  IS NULL) OR (MODULE_PEC.ID_FORMACODE = @ID_FORMACODE))
           AND  ((@DATE_DEBUT_ENTRE_LE IS NULL) OR (MODULE_PEC.DAT_DEBUT >= @DATE_DEBUT_ENTRE_LE))
           AND  ((@DATE_DEBUT_ET_LE IS NULL) OR (MODULE_PEC.DAT_DEBUT IS NOT NULL AND MODULE_PEC.DAT_DEBUT <= @DATE_DEBUT_ET_LE))
           AND  ((@DATE_FIN_ENTRE_LE IS NULL) OR (MODULE_PEC.DAT_FIN >= @DATE_FIN_ENTRE_LE))
           AND  ((@DATE_FIN_ET_LE  IS NULL) OR (MODULE_PEC.DAT_FIN <= @DATE_FIN_ET_LE))
           AND  ((@NUM_INTERNE   IS NULL) OR (MODULE_PEC.NUM_INTERNE IS NOT NULL AND MODULE_PEC.NUM_INTERNE = RTRIM(@NUM_INTERNE))) 
              AND ((@ID_ETABLISSEMENT_OF IS NULL) OR (MODULE_PEC.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF))  
           AND  ((@DEPARTMENT   IS NULL) OR (ADRESSE.LIB_CP_CEDEX IS NOT NULL AND 
                  SUBSTRING(ADRESSE.LIB_CP_CEDEX,0,3) = (CASE WHEN @DEPARTMENT < 10 THEN '0' ELSE '' END) + CONVERT(VARCHAR(3),@DEPARTMENT)))
           AND  ((@ID_INDIVIDU   IS NULL) OR (STAGIAIRE_PEC.ID_INDIVIDU = @ID_INDIVIDU AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL))
           AND  ((@ID_ADHERENT   IS NULL) OR (ADHERENT.ID_ADHERENT =  @ID_ADHERENT))
           AND  ((@ID_ETABLISSEMENT IS NULL) OR (NR140.ID_ETABLISSEMENT = @ID_ETABLISSEMENT))
           AND  ((@NUM_ANNEE   IS NULL) OR (PERIODE.NUM_ANNEE= @NUM_ANNEE))
           AND  (MODULE_PEC.BLN_IMPUTABLE >= CASE @BLN_NON_IMPUTABLES WHEN 0 THEN 1 ELSE 0 END)
           AND  (ACTION_PEC.BLN_ACTIF >= CASE @BLN_INACTIVES WHEN 0 THEN 1 ELSE 0 END)
           AND  ((@MONTANT_FACTUE  IS NULL) OR (POSTE_COUT_REGLE.MNT_REGLE_TTC = @MONTANT_FACTUE AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1))
           AND  ((@NUM_FACTURE   IS NULL) OR (POSTE_COUT_REGLE.NUM_FACTURE like CAST(RTRIM(@NUM_FACTURE) AS VARCHAR(50))))
          ORDER BY MODULE_PEC.ID_MODULE_PEC
          OPTION(RECOMPILE)
         END
         
         
          --AMA 22/09/2008 Pour ‚viter d'utiliser la requˆte avec le DISTINCT, 
          -- on r‚cupŠre d'abord la liste des modules concern‚s par les versements
         SELECT
           #TRI_.ID_MODULE,
           SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MNT_REEL
          INTO #TEMPLISTMODULE
          FROM 
           #TRI_ 
           INNER JOIN POSTE_COUT_REGLE  ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TRI_.ID_MODULE
           INNER JOIN REGLEMENT   ON REGLEMENT.ID_REGLEMENT   = POSTE_COUT_REGLE.ID_REGLEMENT 
                   AND (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL)
          GROUP BY #TRI_.ID_MODULE
         
          -- 1- pour les postes de cout engag‚s et non (d‚sengag‚s ou de d‚sengagement)
           SELECT 
            #TRI_.ID_MODULE, 
            ISNULL(MIN(CASE POSTE_COUT_ENGAGE.MNT_ENGAGE_HT WHEN 0 THEN 1 ELSE BLN_OK_FINANCEMENT END),0) AS MIN_BLN_OK_FINANCEMENT, 
            CASE WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
              ISNULL(SUM(ISNULL(POSTE_COUT_ENGAGE.MNT_ENGAGE_HT,  0)),0)
             ELSE
              (SELECT MNT_REEL FROM #TEMPLISTMODULE WHERE #TEMPLISTMODULE.ID_MODULE = #TRI_.ID_MODULE)
            END AS MNT_ENGAGE,
            COUNT(POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE) AS ENGAGE_CNT
           INTO #TEMPLISTENGAGE_1EREETAPE
           FROM POSTE_COUT_ENGAGE
            INNER JOIN #TRI_  ON #TRI_.ID_MODULE   = POSTE_COUT_ENGAGE.ID_MODULE_PEC
            INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = #TRI_.ID_ACTION_PEC
            INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
                AND ENGAGEMENT.DAT_BAE IS NOT NULL
           WHERE
            DAT_DESENGAGEMENT IS NULL  AND 
            ID_TYPE_ENGAGEMENT IS NOT NULL AND 
            ID_TYPE_ENGAGEMENT <> 2
            
           GROUP BY #TRI_.ID_MODULE, action_pec.bln_cycle_court
          UNION
          -- 2- pour les modules n'ayant pas encore ‚t‚ engag‚s
          SELECT 
           #TRI_.ID_MODULE, 
           ISNULL(MIN(BLN_OK_FINANCEMENT),0) AS MIN_BLN_OK_FINANCEMENT, 
           CASE WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
             0
            ELSE
             (SELECT MNT_REEL FROM #TEMPLISTMODULE WHERE #TEMPLISTMODULE.ID_MODULE = #TRI_.ID_MODULE)
           END AS MNT_ENGAGE,
           0 AS ENGAGE_CNT
          FROM POSTE_COUT_ENGAGE
           INNER JOIN #TRI_  ON #TRI_.ID_MODULE   = POSTE_COUT_ENGAGE.ID_MODULE_PEC
           INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = #TRI_.ID_ACTION_PEC 
           LEFT JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
                  AND ENGAGEMENT.DAT_BAE IS NULL
          WHERE
           POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL
          GROUP BY #TRI_.ID_MODULE, ACTION_PEC.BLN_CYCLE_COURT
         
          SELECT 
            ID_MODULE,
            ISNULL(MIN(MIN_BLN_OK_FINANCEMENT),0) AS MIN_BLN_OK_FINANCEMENT,
            ISNULL(SUM(MNT_ENGAGE),0)AS MNT_ENGAGE,
            ISNULL(SUM(ENGAGE_CNT),0) AS IS_ENGAGE
          INTO  #TEMPLISTENGAGE
          FROM  #TEMPLISTENGAGE_1EREETAPE
          GROUP BY ID_MODULE
         
          SELECT 
           #TRI_.ID_MODULE, 
           SUM(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT) AS MNT_PREVISIONNEL
          INTO #TEMPLISTENGAGE2
          FROM POSTE_COUT_ENGAGE
           INNER JOIN #TRI_  ON #TRI_.ID_MODULE = POSTE_COUT_ENGAGE.ID_MODULE_PEC
          WHERE   POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
          GROUP BY #TRI_.ID_MODULE
         
          SELECT 
           #TRI_.ID_MODULE,
           ISNULL(SUM(ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0)),0) AS MNT_CHIFFRE
          INTO #TEMPLISTENGAGE3
          FROM #TRI_
          INNER JOIN POSTE_COUT_ENGAGE ON #TRI_.ID_MODULE=POSTE_COUT_ENGAGE.ID_MODULE_PEC
          INNER JOIN  PLAN_FINANCEMENT_US ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
                   AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
          -- AJOUT DSZ 30/09/2011 12570
          INNER JOIN UNITE_STAGIAIRE ON (PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
                  AND UNITE_STAGIAIRE.BLN_REFUS = 0)
          -- << --
          GROUP BY #TRI_.ID_MODULE
         
         
          SELECT  ISNULL(SUM(NB_HOURS), 0) AS NB_H_E, ID_MODULE
          INTO #TEMP_NB_H_E
          FROM         (SELECT DISTINCT 
          dbo.STAGIAIRE_PEC.ID_STAGIAIRE_PEC, dbo.STAGIAIRE_PEC.NB_HEURE_ENGAGE AS NB_HOURS, 
          #TRI_.ID_MODULE
          FROM          dbo.STAGIAIRE_PEC
          inner join #TRI_ ON STAGIAIRE_PEC.ID_MODULE_PEC = #TRI_.ID_MODULE
           INNER JOIN dbo.MODULE_PEC ON dbo.MODULE_PEC.ID_MODULE_PEC = dbo.STAGIAIRE_PEC.ID_MODULE_PEC
           INNER JOIN dbo.POSTE_COUT_ENGAGE ON dbo.POSTE_COUT_ENGAGE.ID_MODULE_PEC = dbo.MODULE_PEC.ID_MODULE_PEC
         
          WHERE      (dbo.STAGIAIRE_PEC.ID_SESSION_PEC IS NULL) AND (dbo.MODULE_PEC.BLN_ACTIF = 1) AND (dbo.MODULE_PEC.BLN_IMPUTABLE = 1) 
          AND (dbo.POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL) AND (dbo.POSTE_COUT_ENGAGE.ID_ENGAGEMENT > 0) AND 
          (dbo.POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL)) AS derivedtbl_1
          GROUP BY ID_MODULE
         
          SELECT     SUM(dbo.UNITE_STAGIAIRE.NB_HEURE_REGLE) AS NB_H_R, #TRI_.ID_MODULE
          INTO #TEMP_NB_H_R
          FROM  #TRI_ 
          inner join dbo.STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_MODULE_PEC = #TRI_.ID_MODULE
          INNER JOIN dbo.UNITE_STAGIAIRE       ON dbo.STAGIAIRE_PEC.ID_STAGIAIRE_PEC = dbo.UNITE_STAGIAIRE.ID_STAGIAIRE_PEC
          WHERE     (dbo.STAGIAIRE_PEC.ID_SESSION_PEC IS NOT NULL)
          GROUP BY #TRI_.ID_MODULE
         
          -- Lecture final ------------------------------------------------------------------------------------------------------------------
          SELECT 
           #TRI_.*,
           CAST(ISNULL(#TEMPLISTENGAGE3.MNT_CHIFFRE,0) AS DECIMAL(18,2)) AS MNT_CHIFFRE, 
           ISNULL(#TEMPLISTENGAGE2.MNT_PREVISIONNEL, 0) AS MNT_PREVISIONNEL,
           ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,   0) AS MNT_ENGAGE,
           ISNULL(#TEMPLISTMODULE.MNT_REEL,    0) AS MNT_REEL,
           CASE WHEN #TEMPLISTENGAGE.IS_ENGAGE > 0 THEN 1 ELSE 0 END
                 AS IS_ENGAGE,
         -- 1. NB_STAGIAIRE
           ISNULL((SELECT COUNT(STAGIAIRE_PEC.ID_STAGIAIRE_PEC)
           FROM STAGIAIRE_PEC WHERE 
           STAGIAIRE_PEC.ID_MODULE_PEC =  #TRI_.ID_MODULE AND
           STAGIAIRE_PEC.ID_SESSION_PEC IS NULL),0) AS NB_STAGIAIRES,
         --2. NB_H_ENGAGEES
          ISNULL(#TEMP_NB_H_E.NB_H_E,0) AS NB_H_ENGAGEES,
         --3. NB_H_REALISEES
            ISNULL(#TEMP_NB_H_R.NB_H_R,0) AS NB_H_REALISEES,
         --4.ENGAGEMENT POSSIBLE
           CASE WHEN (#TRI_.BLN_ACTIF = 1 AND #TRI_.BLN_IMPUTABLE = 1) THEN
            CASE WHEN(#TRI_.BLN_OK_ENGAGEMENT = 0 ) THEN
             'PiŠce Manquante'
            ELSE
             CASE WHEN (#TEMPLISTENGAGE.MIN_BLN_OK_FINANCEMENT = 0) THEN
              'Chiffrage inachev‚' 
             ELSE
              'Possible'
             END
            END
           ELSE
            '' -- Return Empty
           END AS ENGAGEMENT_POSSIBLE
          FROM  #TRI_
           LEFT JOIN #TEMPLISTENGAGE ON #TEMPLISTENGAGE.ID_MODULE = #TRI_.ID_MODULE
           LEFT JOIN #TEMPLISTENGAGE2 ON #TEMPLISTENGAGE2.ID_MODULE = #TRI_.ID_MODULE
           LEFT JOIN #TEMPLISTENGAGE3 ON #TEMPLISTENGAGE3.ID_MODULE = #TRI_.ID_MODULE
           LEFT JOIN #TEMPLISTMODULE ON #TEMPLISTMODULE.ID_MODULE = #TRI_.ID_MODULE
           LEFT JOIN #TEMP_NB_H_R 
                  ON #TEMP_NB_H_R.ID_MODULE = #TRI_.ID_MODULE
           LEFT JOIN #TEMP_NB_H_E 
                  ON #TEMP_NB_H_E.ID_MODULE = #TRI_.ID_MODULE
         
         
         */
         END
GO
 CREATE PROCEDURE [dbo].[INS_VIREMENT_INTERNE_PEC]
         -- =============================================
         -- Author  : XXX
         -- Create date : XX XXX 2007
         -- Description : proc‚dure d'insertion des virements interne pec
         -- =============================================
         -- Author  : KS
         -- Modified on : 03 oct 2007
         -- Description : ajout de la gestion des subventions
         -- ---------------------------------------------
         -- Modified on : 12 nov 2007
         -- Description : modification de la protection sur le calcul du montant MNT_VIREMENT_INTERNE_PEC >> nouvelle regle sur le calcul de la somme
         -- ---------------------------------------------
         -- Modified on : 03 dec 2007
         -- Description : utilisation des montants TVA sur le plan de financement US
         -- ---------------------------------------------
         -- Author  : ASD
         -- Create date : 23/02/2009
         -- Description : Correction d'un critŠre x=y lorsque x et y sont ‚gaux … NULL
         -- ---------------------------------------------
         -- Author  : ASD
         -- Create date : 12/03/2009
         -- Description : Ajout de la diff‚renciation des subventions
         -- =============================================  
         -- Author:  MBL
         -- Modif. date: 19/10/2009
         -- Description: Homog‚n‚isation du calcul des montants HT, TVA et TTC sur la chaine de traitement
         -- =============================================  
         -- Author:  ASD SAF
         -- Modif. date: 14/10/2010
         -- Description: 12131 : Reglements de 0? qui s'annulent sur le montant global mais pas sur sa r‚partition / enveloppe-dispositif
         -- =============================================
         -- HBO - 141113 - M16371: Lot 1 - Modification structure de donn‚es / proc‚dures stock‚es
         -- =============================================
         -- HBO - #653 - G‚n‚ration et Editions des Ordres de virements Internes
         -- =============================================
         AS
         BEGIN
          DECLARE
           @LAST_ID int
          SELECT TOP 1
           @LAST_ID = ID_VIREMENT_INTERNE_PEC
          FROM
           VIREMENT_INTERNE_PEC
          ORDER BY
           ID_VIREMENT_INTERNE_PEC DESC 
         
          SELECT
           NULL   as DAT_EDIT_VIREMENT_INTERNE_PEC,
           GETDATE()  as DAT_COMPTA_VIREMENT_INTERNE_PEC,
           COALESCE(dbo.GetVirementReglementSplit(ID_ACTIVITE, ID_SUBVENTION),
           (SUM(CAST(MNT_PLAN_FINANCEMENT_US AS DECIMAL(18,2))
           + CAST(MNT_PLAN_FINANCEMENT_US_TVA AS DECIMAL(18,2))))) as MNT_VIREMENT_INTERNE_PEC, 
           ID_ACTIVITE,  
           NUM_IBAN, 
           ID_SUBVENTION
          INTO
           #TEMP_VIREMENT_INTERNE_PEC
          FROM
           VIEW_VIREMENT_INTERNE_PEC_DATA
          WHERE
           ID_ACTIVITE IS NOT NULL OR ID_SUBVENTION IS NOT NULL
          GROUP BY
           ID_ACTIVITE, NUM_IBAN, ID_SUBVENTION
         
          INSERT INTO dbo.VIREMENT_INTERNE_PEC
          (
           DAT_EDIT_VIREMENT_INTERNE_PEC, 
           DAT_COMPTA_VIREMENT_INTERNE_PEC, 
           MNT_VIREMENT_INTERNE_PEC, 
           ID_ACTIVITE, 
           NUM_IBAN, 
           ID_SUBVENTION
          )
          SELECT
           DAT_EDIT_VIREMENT_INTERNE_PEC,
           DAT_COMPTA_VIREMENT_INTERNE_PEC,
           CAST(MNT_VIREMENT_INTERNE_PEC AS DECIMAL(18,2)), 
           ID_ACTIVITE,  
           NUM_IBAN, 
           ID_SUBVENTION
          FROM
           #TEMP_VIREMENT_INTERNE_PEC
          WHERE
           MNT_VIREMENT_INTERNE_PEC <> 0
         
          --R‚cup‚ration de la liste des plans financements concern‚s
          SELECT DISTINCT
           ID_PLAN_FINANCEMENT_US,ID_ACTIVITE, ID_SUBVENTION
          INTO
           #TEMP_PLAN_FINANCEMENT_US
          FROM
           VIEW_VIREMENT_INTERNE_PEC_DATA
          WHERE
           ID_ACTIVITE IS NOT NULL
           OR ID_SUBVENTION IS NOT NULL
         
          --Liste des virements internes ins‚r‚s
          SELECT
           ID_VIREMENT_INTERNE_PEC,ID_ACTIVITE,
           ID_SUBVENTION
          INTO
           #TEMP_VIREMENT_PEC
          FROM
           VIREMENT_INTERNE_PEC
          WHERE
           VIREMENT_INTERNE_PEC.ID_VIREMENT_INTERNE_PEC > @LAST_ID
         
          --Mise … jour des plan financements avec les id_virement_interne_pec concern‚es
          UPDATE
           PLAN_FINANCEMENT_US
          SET
           PLAN_FINANCEMENT_US.ID_VIREMENT_INTERNE_PEC = #TEMP_VIREMENT_PEC.ID_VIREMENT_INTERNE_PEC
          FROM
           #TEMP_VIREMENT_PEC
           INNER JOIN #TEMP_PLAN_FINANCEMENT_US 
            ON
            (
             #TEMP_PLAN_FINANCEMENT_US.ID_ACTIVITE  = #TEMP_VIREMENT_PEC.ID_ACTIVITE -- id_activite valoris‚e uniquement
             --ASD : ajout de la ligne ci-dessous (id_activite is null => on est en subventions)
             or
             (
              #TEMP_PLAN_FINANCEMENT_US.ID_ACTIVITE is NULL
              and #TEMP_VIREMENT_PEC.ID_ACTIVITE is NULL
             )-- id activite NULL des deux c“t‚s
            )
            and
            (
             --ASD 20090313 nouvel ajout pour diff‚rencier les subventions
             #TEMP_PLAN_FINANCEMENT_US.ID_SUBVENTION  = #TEMP_VIREMENT_PEC.ID_SUBVENTION
             or
             (
              #TEMP_PLAN_FINANCEMENT_US.ID_SUBVENTION is null
              and #TEMP_VIREMENT_PEC.ID_SUBVENTION is null
             )
            )
          WHERE
           #TEMP_PLAN_FINANCEMENT_US.ID_PLAN_FINANCEMENT_US = PLAN_FINANCEMENT_US.ID_PLAN_FINANCEMENT_US
         END
GO
 -- =============================================================
         -- Author		: GiO
         -- Create date	: 12 Mars 2008
         -- Description	: Lettre de relance de REGLEMENT pour l'adh‚rent
         -- =============================================================
         CREATE PROCEDURE [dbo].[EDT_LETTRE_RELANCE_REGLEMENT_CONTRAT_PRO_ADH]
         	@ID_ETABLISSEMENT	INT,
         	@ID_BENEFICIAIRE	INT,
         	@TYPE_BENEFICIAIRE	INT,
         	@ID_ADRESSE			INT,
         	@ID_CONTACT			INT,
         	@COD_CONTRAT_PRO	VARCHAR(10)
         AS
         BEGIN
         
         	DECLARE @relance INT
         	SET @relance = 1
         
         	/**** R‚cup‚ration des infos pour la partie r‚f‚rence ****/
         	SELECT DISTINCT	ADHERENT.COD_ADHERENT,
         			AGENCE.ID_AGENCE,
         			AGENCE.COD_POSTAL,
         			AGENCE.LIB_VILLE,
         			AGENCE.LIB_NOM_CONSEILLER,
         			AGENCE.LIB_PNM_CONSEILLER
         	INTO	#TEMP_REGLEMENT_REFERENCE
         	FROM	ADHERENT
         			INNER JOIN AGENCE			ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         			INNER JOIN ETABLISSEMENT	ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	WHERE	(ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT);
         
         
         	/**** R‚cup‚ration des infos sur le contrat pro ****/
         	SELECT DISTINCT	CONTRAT_PRO.ID_CONTRAT_PRO,
         			CONTRAT_PRO.COD_CONTRAT_PRO,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_DEB_CONTRAT, 3) AS DAT_DEBUT,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_FIN_CONTRAT, 3) AS DAT_FIN,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU,
         			CONTRAT_PRO.LIB_LIEU_FORMATION
         	INTO	#TMP_REGLEMENT_CONTRAT_PRO 
         	FROM	CONTRAT_PRO
         			INNER JOIN SALARIE_PRO ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         			INNER JOIN INDIVIDU ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         	WHERE   CONTRAT_PRO.COD_CONTRAT_PRO = @COD_CONTRAT_PRO;
         
         
         	/*** Recuperation de la liste des pieces contrats li‚es … ce contrat **********/
         	SELECT DISTINCT	PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3
         	INTO	#TMP_REGLEMENT_PIECES_CONTRAT_PRO
         	FROM	#TMP_REGLEMENT_CONTRAT_PRO
         			INNER JOIN ARRIVEE_PIECE_PRO ON #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO = ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO 
         			INNER JOIN PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO AND (ARRIVEE_PIECE_PRO.BLN_ACTIF!=1 OR ARRIVEE_PIECE_PRO.BLN_CONFORME!=1)
         					AND PIECE_PRO.BLN_CONTRAT = 1 AND PIECE_PRO.BLN_ACTIF=1 AND (PIECE_PRO.BLN_BLOQUANT_REGLEMENT = 1 or PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1 );
         
         
         	/*** Recuperation de la liste des pieces modules li‚es … ce contrat  **********/
         	SELECT	DISTINCT PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         			MODULE_PRO.COD_MODULE_PRO, 
         			MODULE_PRO.LIBL_MODULE_PRO,
         			MODULE_PRO.BLN_SUBROGE,
         			MODULE_PRO.BLN_ACTIF AS MODULE_ACTIF,
         			CONVERT(VARCHAR(8),MODULE_PRO.DAT_DEBUT, 3) AS DAT_DEBUT,
         			dbo.GetFrenchCurrencyFormat(CAST(MODULE_PRO.NB_UNITE_TOTALE as MONEY))  AS NB_UNITE_TOTALE,
                     ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         	INTO	#TMP_REGLEMENT_PIECES_MODULE_PRO
         	FROM	#TMP_REGLEMENT_CONTRAT_PRO
         			INNER JOIN MODULE_PRO ON #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         									AND MODULE_PRO.BLN_SUBROGE = 0 AND MODULE_PRO.BLN_OK_PIECE = 0 
         			INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         			INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			INNER JOIN ARRIVEE_PIECE_PRO ON MODULE_PRO.ID_MODULE_PRO = ARRIVEE_PIECE_PRO.ID_MODULE_PRO 
         			INNER JOIN PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO AND (ARRIVEE_PIECE_PRO.BLN_ACTIF!=1 OR ARRIVEE_PIECE_PRO.BLN_CONFORME!=1)
         				AND ARRIVEE_PIECE_PRO.ID_PIECE_PRO <> 10 AND MODULE_PRO.BLN_ACTIF=1 AND PIECE_PRO.BLN_MODULE = 1 AND PIECE_PRO.BLN_CONTRAT = 0 AND PIECE_PRO.BLN_ACTIF=1 AND  (PIECE_PRO.BLN_BLOQUANT_REGLEMENT = 1 or PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1 );
         				
         
         	/*** Recuperation de la liste des pieces session li‚es … ce contrat  **********/
         	SELECT  distinct   PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         			MODULE_PRO.COD_MODULE_PRO, 
         			MODULE_PRO.LIBL_MODULE_PRO,
         			MODULE_PRO.BLN_SUBROGE,
         			MODULE_PRO.BLN_ACTIF AS MODULE_PRO_ACTIF,
         			CONVERT(VARCHAR(8),SESSION_PRO.DAT_DEBUT, 3) AS DAT_DEBUT,
         			SESSION_PRO.COD_SESSION_PRO,
         			SESSION_PRO.NUM_FACTURE,
         			SESSION_PRO.BLN_ACTIF as SESSION_ACTIF,
         			dbo.GetFrenchCurrencyFormat(CAST(SESSION_PRO.NB_UNITE_TOTALE as MONEY))  AS NB_UNITE_TOTALE,
                     ORGANISME_FORMATION.LIB_RAISON_SOCIALE,ORGANISME_FORMATION.COD_OF
         	INTO	#TMP_REGLEMENT_PIECES_SESSION
         FROM         ARRIVEE_PIECE_PRO 
         Inner join #TMP_REGLEMENT_CONTRAT_PRO on #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO= ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO 
         INNER JOIN
                               SESSION_PRO ON ARRIVEE_PIECE_PRO.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO
         inner join module_pro on module_pro.id_module_pro=ARRIVEE_PIECE_PRO.id_module_pro
         INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         			INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			INNER JOIN PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO AND (ARRIVEE_PIECE_PRO.BLN_ACTIF!=1 OR ARRIVEE_PIECE_PRO.BLN_CONFORME!=1)
         and module_pro.bln_subroge=0
         WHERE     (ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO = #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO) AND (ARRIVEE_PIECE_PRO.ID_SESSION_PRO IS NOT NULL) AND 
                              ( (ARRIVEE_PIECE_PRO.BLN_ACTIF <> 1) OR   (ARRIVEE_PIECE_PRO.BLN_CONFORME <> 1))
                            				AND SESSION_PRO.BLN_ACTIF=1 AND MODULE_PRO.BLN_ACTIF=1	AND PIECE_PRO.BLN_SESSION = 1 AND PIECE_PRO.BLN_CONTRAT = 0 AND PIECE_PRO.BLN_MODULE = 0 AND PIECE_PRO.BLN_ACTIF=1 AND  (PIECE_PRO.BLN_BLOQUANT_REGLEMENT = 1 or PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1 ) and SESSION_PRO.BLN_OK_PIECE = 0 ;  
                             
         
         		
         		IF ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_CONTRAT_PRO WHERE DAT_RELANCE_REGLE_2 IS NOT NULL)  > 0) OR ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO WHERE DAT_RELANCE_REGLE_2 IS NOT NULL)  > 0  OR ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION WHERE DAT_RELANCE_REGLE_2 IS NOT NULL)  > 0))
         			BEGIN
         				SET @relance = 3
         			END
         		ELSE
         			BEGIN
         				IF ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_CONTRAT_PRO WHERE DAT_RELANCE_REGLE_1 IS NOT NULL)  > 0) OR ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO WHERE DAT_RELANCE_REGLE_1 IS NOT NULL)  > 0 OR ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION WHERE DAT_RELANCE_REGLE_1 IS NOT NULL)  > 0))
         					BEGIN
         						SET @relance = 2
         					END
         			END;
         
         	/*****  Creation du flux XML *****************************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_RELANCE_REGLEMENT_CONTRAT_PRO_ADH'
         	)
         	/**********************************************************************************************************/
         			
         	SELECT
         			(
         				SELECT @relance
         				FOR XML RAW('NUM_RELANCE'), ELEMENTS, TYPE
         			),
         			( 
         				SELECT  case when @relance=1 then ' Šre' else ' Šme' end
         				FOR XML RAW('niŠme'), ELEMENTS, TYPE
         			),
         			(
         				/**********************************************************************************************/
         				/*****************	ENTETE DE LA LETTRE *******************************************************/
         				/**********************************************************************************************/
         				SELECT	              	
         					-- R‚cup‚ration des informations sur l'agence
         					dbo.GetXmlAgenceContact(ENTETE.ID_AGENCE) as EMETTEUR,
         					
         					-- R‚cup‚ration des informations sur le contact
         					dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,
         
         					/******************* Recuperation des informations DE l'entete ****************************/
         					(
         						SELECT	REFERENCE.COD_ADHERENT,
         								REFERENCE.LIB_VILLE,
         								dbo.GetFullDate(getDate()) as DATE,								
         								(
         									SELECT	#TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO
         									FROM	#TMP_REGLEMENT_CONTRAT_PRO
         									FOR XML PATH('CONTRAT_PRO'), TYPE 
         								),
         								(
         									SELECT	top 1
         											dbo.GetContactSalutation(@ID_CONTACT, 1)
         									FROM CIVILITE
         									FOR XML PATH('POLITESSE_HAUT'), TYPE
         								)
         
         						FROM #TEMP_REGLEMENT_REFERENCE AS REFERENCE     
         						FOR XML AUTO, ELEMENTS, TYPE
         					)
         				FROM #TEMP_REGLEMENT_REFERENCE AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				/**********************************************************************************************/
         				/*****************	CORPS DE LA LETTRE ********************************************************/
         				/**********************************************************************************************/
         				SELECT	CORPS.ID_CONTRAT_PRO,
         						CORPS.COD_CONTRAT_PRO,
         						CORPS.PRENOM_INDIVIDU,
         						CORPS.NOM_INDIVIDU,
         						CORPS.DAT_DEBUT,
         						CORPS.DAT_FIN,
         						CORPS.LIB_LIEU_FORMATION,
         						CASE WHEN @relance = 3 THEN(
         							SELECT 'Sans r‚ponse de votre part sous quinzaine nous cl“turerons ce dossier.'
         							FOR XML PATH('PREVENTION'), TYPE 
         						)END ,
         				/************************************************************************************************/
         				/*****************	PIECES CONTRAT *************************************************************/
         				/**********************************************************************************************/
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_CONTRAT_PRO) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_CONTRAT_PRO.LIBC_PIECE_PRO
         									FROM			#TMP_REGLEMENT_PIECES_CONTRAT_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_CONTRAT_PRO.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_CONTRAT_PRO.LIBC_PIECE_PRO,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBC_MOTIF_NON_CONFORM_PIECE_PRO
         									FROM    #TMP_REGLEMENT_PIECES_CONTRAT_PRO
         											INNER JOIN NR410 ON #TMP_REGLEMENT_PIECES_CONTRAT_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         											INNER JOIN MOTIF_NON_CONFORM_PIECE_PRO ON NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_CONTRAT_PRO.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML PATH('TABLEAU_CONTRAT'),ELEMENTS, TYPE
         						)END,
         
         				/************************************************************************************************/
         				/*****************	PIECES MODULES *************************************************************/
         				/**********************************************************************************************/
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO) > 0 and (SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_CONTRAT_PRO) > 0) THEN(
         							SELECT 'Et pour les modules de formation suivants :'
         							FOR XML PATH('SUITE_MODULE'), TYPE 
         						)END ,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBL_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBC_PIECE_PRO
         									FROM			#TMP_REGLEMENT_PIECES_MODULE_PRO
         									WHERE			#TMP_REGLEMENT_PIECES_MODULE_PRO.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBL_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBC_PIECE_PRO,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBC_MOTIF_NON_CONFORM_PIECE_PRO
         									FROM    #TMP_REGLEMENT_PIECES_MODULE_PRO
         											INNER JOIN NR410 ON #TMP_REGLEMENT_PIECES_MODULE_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         											INNER JOIN MOTIF_NON_CONFORM_PIECE_PRO ON NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_MODULE_PRO.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML PATH('TABLEAU_MODULE'),ELEMENTS, TYPE
         						)END,
         				/************************************************************************************************/
         				/*****************	PIECES SESSION *************************************************************/
         				/**********************************************************************************************/
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION) > 0 and ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO) > 0 or (SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_CONTRAT_PRO) > 0)) THEN(
         							SELECT 'Et pour les sessions  suivantes :'
         							FOR XML PATH('SUITE_SESSION'), TYPE 
         						)END ,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_SESSION.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_SESSION.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_SESSION.COD_SESSION_PRO,
         													#TMP_REGLEMENT_PIECES_SESSION.LIB_RAISON_SOCIALE,
         													 Case when #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE <>'' or #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE is not  null
         													then #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE else '' end as NUM_FACTURE,
         													#TMP_REGLEMENT_PIECES_SESSION.LIBL_PIECE_PRO													
         													
         									FROM			#TMP_REGLEMENT_PIECES_SESSION
         									WHERE			#TMP_REGLEMENT_PIECES_SESSION.BLN_ACTIF = 0  --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_SESSION.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_SESSION.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_SESSION.COD_SESSION_PRO,
         													#TMP_REGLEMENT_PIECES_SESSION.LIB_RAISON_SOCIALE,
         													 Case when #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE <>'' or #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE is not  null
         													then #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE else '' end as NUM_FACTURE,
         													#TMP_REGLEMENT_PIECES_SESSION.LIBL_PIECE_PRO,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBC_MOTIF_NON_CONFORM_PIECE_PRO
         
         									FROM    #TMP_REGLEMENT_PIECES_SESSION
         											INNER JOIN NR410 ON #TMP_REGLEMENT_PIECES_SESSION.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         											INNER JOIN MOTIF_NON_CONFORM_PIECE_PRO ON NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_SESSION.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML RAW('TABLEAU_SESSION'),ELEMENTS, TYPE
         						)END,
         						(
         							SELECT	top 1 dbo.GetContactSalutation(@ID_CONTACT, 0)
         							FROM CIVILITE
         							FOR XML PATH('POLITESSE_BAS'), TYPE
         						)
         				FROM #TMP_REGLEMENT_CONTRAT_PRO AS CORPS     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				/**********************************************************************************************/
         				/*****************	SIGNATURE DE LA LETTRE ****************************************************/
         				/**********************************************************************************************/
         				SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TEMP_REGLEMENT_REFERENCE as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         			/**************************************************************************************************/
         
         	FROM	#TEMP_REGLEMENT_REFERENCE as LETTRE
         	FOR XML AUTO, ELEMENTS
         END
GO

         
         -- =============================================
         -- Author:		xxx
         -- Create date: xx xxx 2007
         -- Description:	lecture des motifs non conforme
         -- ---------------------------------------------
         -- Author:		SAY
         -- Modif. date: 20 juin 2007
         -- Description:	ajout pr la prise en charge de la session, ou de la session prec.
         -- ---------------------------------------------
         -- Author:		SAY
         -- Modif. date: 04 juillet 2007
         -- Description:	correction sur la prise en charge des sessions
         -- ---------------------------------------------
         -- Author:		SAY
         -- Modif. date: 06 sept 2007
         -- Description:	correction sur la creation de la premiere session
         -- ---------------------------------------------
         -- Author:		AMA
         -- Modif. date: 27 novembre 2008
         -- Description:	Optimisation: plus besoin d'appeler LEC_GRP_MOTIF_NON_CONFORM_PIECE_PRO
         --				dans la couche service
         -- ---------------------------------------------
         -- Author:		DSZ
         -- Modif. date: 15/05/09
         -- Description:	On passe plutot id_session = 0 et non pas null ce qui pose des problemes
         -- pendant la creation de session. Voir Mantis 12004
         -- ---------------------------------------------
         -- Author:		ASD-DSZ
         -- Modif. date: 13/01/2011
         -- Description:	Optimisation de l'obtention de @ID_PREV_SESSION (max des sessions existantes) et inclusion dans le else.
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_MOTIF_NON_COFORM_PIECE]
         	@ID_MODULE			int,
         	@ID_ACTION			int,
         	@ID_MODE_SESSION	int,
         	@ID_SESSION			int
         AS  
         BEGIN
         	IF @ID_MODULE IS NOT NULL
         		BEGIN
         			DECLARE @ID_PREV_SESSION	int
         			IF (@ID_MODE_SESSION is null)
         				SET @ID_PREV_SESSION = null
         			else
         /*			DECLARE @COUNT				int
         			DECLARE @COD_MOD			varchar(12)
         
         			SET @COUNT = 0
         
         			SELECT @COUNT	= count(*)			from SESSION_PEC	where ID_MODULE_PEC = @ID_MODULE
         			SELECT @COD_MOD = COD_MODULE_PEC	from MODULE_PEC		where ID_MODULE_PEC = @ID_MODULE
         
         			SELECT @ID_PREV_SESSION = ID_SESSION_PEC from SESSION_PEC	
         					where	COD_SESSION_PEC = (@COD_MOD+(case when @COUNT < 9 then '0'+cast(@COUNT as varchar(1)) else cast(@COUNT as varchar(2)) end))
         	*/			SELECT @ID_PREV_SESSION = max(ID_SESSION_PEC) from SESSION_PEC where	ID_MODULE_PEC = @ID_MODULE
         			--end
         
         			IF ((@ID_SESSION is null OR @ID_SESSION = 0)  AND @ID_MODE_SESSION is not null AND @ID_PREV_SESSION is null)
         				BEGIN
         					SELECT
         						0														AS SELECTION,							
         						-1														AS ID_ARRIVEE_PIECE_PEC,
         						MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE		AS ID,
         						MOTIF_NON_CONFORM_PIECE.COD_MOTIF_NON_CONFORM_PIECE		AS COD,
         						MOTIF_NON_CONFORM_PIECE.LIBL_MOTIF_NON_CONFORM_PIECE	AS LIBELLE,
         						PIECE_PEC.ID_PIECE_PEC,
         						-1														AS ID_ADHERENT
         					FROM
         						PIECE_PEC
         						inner join MOTIF_PIECE				on	MOTIF_PIECE.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         						inner join MOTIF_NON_CONFORM_PIECE	on	MOTIF_PIECE.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE
         					WHERE 
         						MOTIF_NON_CONFORM_PIECE.BLN_ACTIF		= 1				AND
         						PIECE_PEC.BLN_SESSION					= 1
         				END
         			ELSE
         				BEGIN
         					SELECT
         						--0 AS SELECTION,
         						-- COUNT(*) utilis‚ pour IF EXISTS
         						(SELECT COUNT(*) FROM NR210
							WHERE ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
							AND ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE)	AS SELECTION,
         						ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         						MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE		AS ID,
         						MOTIF_NON_CONFORM_PIECE.COD_MOTIF_NON_CONFORM_PIECE		AS COD,
         						MOTIF_NON_CONFORM_PIECE.LIBL_MOTIF_NON_CONFORM_PIECE	AS LIBELLE,
         						ARRIVEE_PIECE_PEC.ID_PIECE_PEC,
         						ISNULL(ARRIVEE_PIECE_PEC.ID_ADHERENT, -1)				AS ID_ADHERENT,
         						ARRIVEE_PIECE_PEC.ID_MODULE_PEC							AS ID_MODULE,
         						ARRIVEE_PIECE_PEC.ID_SESSION_PEC						AS ID_SESSION
         					FROM
         						ARRIVEE_PIECE_PEC
         						inner join MOTIF_PIECE				on	MOTIF_PIECE.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         						inner join MOTIF_NON_CONFORM_PIECE	on	MOTIF_PIECE.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE
         --						MOTIF_NON_CONFORM_PIECE
         					WHERE 
         						ARRIVEE_PIECE_PEC.ID_MODULE_PEC			= @ID_MODULE	AND
         						MOTIF_NON_CONFORM_PIECE.BLN_ACTIF		= 1				AND
         						ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC		IS NULL			AND
         						ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE	IS NULL			AND 
         						(
         							(@ID_SESSION	is not null AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC = @ID_SESSION	AND 
         															ARRIVEE_PIECE_PEC.ID_SESSION_PEC is not null) 
         							OR
         							(@ID_SESSION	is null		AND @ID_PREV_SESSION	is not null					AND 
         															ARRIVEE_PIECE_PEC.ID_SESSION_PEC = @ID_PREV_SESSION AND 
         															ARRIVEE_PIECE_PEC.ID_SESSION_PEC is not null) 
         							OR
         							(@ID_SESSION	is null		AND @ID_PREV_SESSION	is null						AND 
         							 ARRIVEE_PIECE_PEC.ID_SESSION_PEC is null) 
         						)
         				END
         		END
         	ELSE
         		BEGIN
         			DECLARE @CIBLE_ACTION INT
         			DECLARE @BLN_EXTERNE INT
         			DECLARE @ID_PIECE_PEC INT
         			DECLARE @BLN_ADHERENT INT
         			DECLARE @LIBL_PIECE_PEC varchar(50)
         
         			-- Temporal table for loading the adherents attached to action
         
         			CREATE TABLE #TEMPLIST
         			(
         				ID_ADHERENT int,
         				LIBL_ADHERENT varchar(50)
         			)
         			
         			-- Temporal table for loading the pieces for each adherent attached to action
         
         			CREATE TABLE #TEMPLIST2
         			(
         				ID_PIECE_PEC int,
         				LIBL_PIECE_PEC varchar(50),
         				ID_ADHERENT int,
         				LIBL_ADHERENT varchar(50),
         				BLN_ADHERENT tinyint
         			)
         
         			INSERT INTO #TEMPLIST (ID_ADHERENT, LIBL_ADHERENT)
         			SELECT DISTINCT ADHERENT.ID_ADHERENT, ADHERENT.LIB_RAISON_SOCIALE
         			FROM NR140 
         			INNER JOIN ETABLISSEMENT	ON ETABLISSEMENT.ID_ETABLISSEMENT	= NR140.ID_ETABLISSEMENT
         			INNER JOIN ADHERENT			ON ADHERENT.ID_ADHERENT				= ETABLISSEMENT.ID_ADHERENT
         			WHERE NR140.ID_ACTION_PEC = @ID_ACTION
         
         			SELECT @CIBLE_ACTION = CIBLE_ACTION FROM ACTION_PEC WHERE ID_ACTION_PEC = @ID_ACTION
         
         			SELECT @BLN_EXTERNE = BLN_EXTERNE	FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE
         
         			DECLARE CURSORPIECES 
         			CURSOR FOR 
         			SELECT ID_PIECE_PEC, BLN_ADHERENT, LIBL_PIECE_PEC 
         			FROM PIECE_PEC
         			WHERE
         				(PIECE_PEC.BLN_MODULE = 1 OR PIECE_PEC.BLN_ADHERENT = 1) AND
         				PIECE_PEC.BLN_POSTE_COUT_REGLE		= 0 AND 
         				PIECE_PEC.BLN_STAGIAIRE				= 0 AND
         				PIECE_PEC.BLN_ACTIF					= 1
         
         			OPEN CURSORPIECES
         			FETCH NEXT FROM CURSORPIECES INTO
         			@ID_PIECE_PEC, @BLN_ADHERENT, @LIBL_PIECE_PEC
         						
         			WHILE (@@Fetch_Status <> -1)
         			begin 
         				IF (@@Fetch_Status <> -2) 
         				BEGIN
         					IF @BLN_ADHERENT = 1
         					BEGIN
         						INSERT INTO #TEMPLIST2(ID_PIECE_PEC, LIBL_PIECE_PEC,ID_ADHERENT, LIBL_ADHERENT, BLN_ADHERENT)
         						SELECT @ID_PIECE_PEC, @LIBL_PIECE_PEC, ID_ADHERENT, LIBL_ADHERENT, 1
         						FROM #TEMPLIST
         					END
         					ELSE
         					BEGIN
         						INSERT INTO #TEMPLIST2(ID_PIECE_PEC, LIBL_PIECE_PEC, ID_ADHERENT, LIBL_ADHERENT, BLN_ADHERENT)
         						VALUES (@ID_PIECE_PEC, @LIBL_PIECE_PEC,NULL,NULL,0)
         					END
         				END
         				
         				FETCH NEXT FROM CURSORPIECES INTO
         				@ID_PIECE_PEC, @BLN_ADHERENT, @LIBL_PIECE_PEC
         			END
         
         			CLOSE CURSORPIECES
         			DEALLOCATE CURSORPIECES
         
         		   SELECT --0 AS SELECTION,
         					(SELECT COUNT(*) FROM NR210
							WHERE ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
							AND ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE)	AS SELECTION,
         					ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         					MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE as ID,
         					MOTIF_NON_CONFORM_PIECE.COD_MOTIF_NON_CONFORM_PIECE as COD,
         					MOTIF_NON_CONFORM_PIECE.LIBL_MOTIF_NON_CONFORM_PIECE as LIBELLE,
         					#TEMPLIST2.ID_PIECE_PEC, 
         					CASE WHEN (#TEMPLIST2.ID_ADHERENT IS NULL) THEN -1 ELSE #TEMPLIST2.ID_ADHERENT END AS ID_ADHERENT
         			FROM
         				#TEMPLIST2
         					inner join MOTIF_PIECE				on MOTIF_PIECE.ID_PIECE_PEC = #TEMPLIST2.ID_PIECE_PEC
         					inner join MOTIF_NON_CONFORM_PIECE	on MOTIF_PIECE.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE
         				LEFT JOIN ARRIVEE_PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = #TEMPLIST2.ID_PIECE_PEC 
         					AND ARRIVEE_PIECE_PEC.ID_MODULE_PEC = @ID_MODULE 
         					AND (ARRIVEE_PIECE_PEC.ID_ADHERENT = #TEMPLIST2.ID_ADHERENT OR 
         						(ARRIVEE_PIECE_PEC.ID_ADHERENT IS NULL AND #TEMPLIST2.ID_ADHERENT IS NULL))
         					AND ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
         		END
         END
         
GO

         
         create PROCEDURE [dbo].[EDI_TRANSCO_LEC_DET_TABLE_CONCERNEE] 
         /* 
           Lecture d'une table concernee par la transcodification dans le cadre de l'EDI 
           et de la valeur par defaut pour la transcodification
         */  
         @ID_TABLE		VARCHAR(255)
         AS
         
         BEGIN
         SET ROWCOUNT 0
         SET NOCOUNT ON
         
         DECLARE @COD_TABLE_FAF		VARCHAR(255),
         	@COD_FAF 		CHAR(5),
         	@LIBC_FAF 		VARCHAR(20),
         	@ID_TABLE_FAF_DEFAUT	INTEGER,
         	@LIB			VARCHAR(2000)
         	CREATE TABLE #TMP02
         	(
         		ID_FAF 	INTEGER		NULL,
         		COD_FAF 	CHAR(5)		NULL,
         		LIBC_FAF 	VARCHAR(20)	NULL
         	)
         
         	SELECT @COD_TABLE_FAF = name
         	FROM	sysobjects
         	WHERE	type = 'U'
         	AND	id = @ID_TABLE
         	IF @@ROWCOUNT > 0
         	BEGIN		
         		SELECT 	@ID_TABLE_FAF_DEFAUT = ID_TABLE_FAF_DEFAUT	
         		FROM EDI_TRANSCO_TABLE_CONCERNEE 
         		WHERE COD_TABLE_FAF = @COD_TABLE_FAF
         
         		IF @@ROWCOUNT > 0
         		BEGIN		
         			IF @ID_TABLE_FAF_DEFAUT IS NOT NULL
         			BEGIN
         				SET @LIB = 'INSERT INTO #TMP02 '
         				SET @LIB = @LIB + 'SELECT ID_' + @COD_TABLE_FAF + ' ID , COD_' + @COD_TABLE_FAF + ' COD , LIBC_' + @COD_TABLE_FAF + ' LIBC  FROM ' + @COD_TABLE_FAF
         				SET @LIB = @LIB + ' WHERE ID_' + @COD_TABLE_FAF + ' = ' + CONVERT(VARCHAR, @ID_TABLE_FAF_DEFAUT)
         				EXECUTE (@LIB)
         			END
         			ELSE
         			BEGIN
         				INSERT INTO #TMP02 VALUES (NULL, NULL, NULL)
         			END
         	
         		END
         	END
         	SELECT @COD_TABLE_FAF COD_TABLE_FAF, ID_FAF, COD_FAF, LIBC_FAF 
         	FROM #TMP02
         
         END
         
GO
 CREATE PROCEDURE [dbo].[INS_MODULE_PEC]  
          @LIBL_MODULE_PEC varchar(250),
          @ID_ACTION int,
          @ID_ETABLISSEMENT_OF int,
          @ID_THEME int,
          @ID_STAGE int,
          @ID_FORMACODE int,
          @BLN_ACTIF int,
          @BLN_IMPUTABLE int,
          @BLN_EXTERNE int,
          @ID_UTIL int,
          @NUM_INTERNE varchar(50),
          @DAT_DEBUT datetime,
          @DAT_FIN datetime,
          @DUREE_JOURS decimal(18,2),
          @DUREE_HEURE decimal(18,2),
          @MNT_CONVENTION decimal(18,2),
          @ID_PERIODE int,
          @COM_MODULE_PEC varchar(255),
          @ID_DEPARTEMENT int,
          @BLN_INTRA int,
          @AXE_MODULE varchar(30),
          @DOMAINE_MODULE varchar(30),
          @ID_MODALITE_FORMATION int,
          @BLN_DELEGATION_PAIEMENT int,
          @ID_UTILISATEUR_CREATEUR int,
          @ID_DISPOSITIF_PAR_DEFAUT int,
          @ID_MODULE_PEC int output,
          @ID_CRITERE_CHIFFRAGE int,
          @BLN_CATALOGUE tinyint,
          @ID_MODALITE_ENSEIGNEMENT int = null,
          @CODE_CPF varchar(10) = null
          
         AS  
         -- =======================================================================================================================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================  
         -- DSZ US#1003 16/07/2015 : Ajout ID_MODALITE_ENSEIGNEMENT et CODE_CPF 
         -- =======================================================================================================================================  
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250)
         -- ======================================================================================================================================= 
         BEGIN
         
          DECLARE @COD_MODULE VARCHAR(17)
          DECLARE @COUNT INT
          DECLARE @TEXT VARCHAR(2)
          DECLARE @COD_ACTION int
          DECLARE @ANNEE_ACTION_PEC VARCHAR(4)
         
          SELECT
           @COUNT = COUNT(*)
          FROM MODULE_PEC
          WHERE ID_ACTION_PEC = @ID_ACTION
         
          SET @TEXT = coalesce(RIGHT('0'+CAST(@COUNT+1 AS VARCHAR(2)),2), '01')
         
          SELECT @COD_ACTION = COD_ACTION_PEC,
              @ANNEE_ACTION_PEC = CAST(ACTION_PEC.ANNEE_ACTION_PEC AS varchar(4))
          FROM ACTION_PEC
          WHERE ID_ACTION_PEC = @ID_ACTION
         
          SET @COD_MODULE = right('000000' 
                + CONVERT(VARCHAR(8), @COD_ACTION)+ ' ' 
                + CONVERT(VARCHAR(2), @TEXT),9) + '/' 
                + @ANNEE_ACTION_PEC
         
          
          INSERT INTO MODULE_PEC
           (COD_MODULE_PEC,LIBL_MODULE_PEC, ID_ACTION_PEC, ID_ETABLISSEMENT_OF, 
           ID_THEME, ID_STAGE, ID_FORMACODE, BLN_ACTIF, BLN_IMPUTABLE, BLN_EXTERNE, 
           ID_UTILISATEUR, NUM_INTERNE, DAT_DEBUT, DAT_FIN, NUM_DUREE_JOUR, 
           NUM_DUREE_HEURE, MNT_CONVENTION, ID_PERIODE, DAT_CREATION, DAT_MODIF, 
           COM_MODULE_PEC, ID_DEPARTEMENT, BLN_INTRA, AXE_MODULE, DOMAINE_MODULE, 
           ID_MODALITE_FORMATION, BLN_DELEGATION_PAIEMENT,ID_UTILISATEUR_CREATEUR,
           ID_DISPOSITIF_PAR_DEFAUT,ID_CRITERE_CHIFFRAGE,BLN_CATALOGUE, ID_MODALITE_ENSEIGNEMENT, CODE_CPF)
          VALUES 
           (@COD_MODULE,@LIBL_MODULE_PEC, @ID_ACTION, @ID_ETABLISSEMENT_OF, 
           @ID_THEME, @ID_STAGE, @ID_FORMACODE, @BLN_ACTIF, @BLN_IMPUTABLE, @BLN_EXTERNE, 
           @ID_UTIL, @NUM_INTERNE, @DAT_DEBUT, @DAT_FIN, @DUREE_JOURS, 
           @DUREE_HEURE, @MNT_CONVENTION, @ID_PERIODE, GETDATE(), GETDATE(),
           @COM_MODULE_PEC, @ID_DEPARTEMENT,@BLN_INTRA,@AXE_MODULE,@DOMAINE_MODULE,
           @ID_MODALITE_FORMATION, @BLN_DELEGATION_PAIEMENT,@ID_UTILISATEUR_CREATEUR,
           @ID_DISPOSITIF_PAR_DEFAUT,@ID_CRITERE_CHIFFRAGE, @BLN_CATALOGUE, @ID_MODALITE_ENSEIGNEMENT, @CODE_CPF)
         
          --select @@IDENTITY as ID 
          SET @ID_MODULE_PEC = @@IDENTITY
          
         
         
         END
GO

         -- =============================================
         -- Author:		GiO ACAR
         -- Create date: 07/06/2013
         -- Description:	Compteur pour COD_dossier. Returns COD_dossier
         -- en entr‚e type = PEC ou PRO
         -- MANTIS		: B15254 [Paniers] R‚alisation des PS Paniers
         -- =============================================
         -- DSZ 06/12/2013 16536 retourner un code_dossier … 6 chiffres plus le mill‚sime
         -- =============================================
         CREATE PROCEDURE [dbo].[RESERVER_COD_DOSSIER] 
         	@TYPE varchar(3),
         	@RESULT_COD_DOSSIER varchar(12) output
         AS
         BEGIN
         	-- get the existing counter
         DECLARE @COD_CPT varchar(12)
         DECLARE	@COMPTEURint int
         DECLARE @DOSSIER_ANNEE int 
         DECLARE @INCREMENT int
         set @DOSSIER_ANNEE= datepart(year,getdate())
         
         	IF @TYPE = 'PEC'
         	BEGIN
         		EXEC  @compteurint= ACTION_COMPTEUR  @DOSSIER_ANNEE	
         		SET @RESULT_COD_DOSSIER = dbo.GetPECCodePadded(@COMPTEURint,@DOSSIER_ANNEE)
         
         	END
         	ELSE IF @TYPE = 'PRO'
         	BEGIN	
         		SET @COMPTEURint = IDENT_CURRENT('CONTRAT_PRO') + 1
         		SET @INCREMENT = @COMPTEURint
         		DBCC CHECKIDENT ('CONTRAT_PRO', RESEED, @INCREMENT)
         		SET @RESULT_COD_DOSSIER = dbo.GetContratProCode (@COMPTEURint, @DOSSIER_ANNEE)
         	END
         
         END
         
         
GO
 CREATE PROCEDURE [dbo].[UPD_REGLEMENT_GENERATION_VIREMENT_INTERNE_PEC]
         -- =============================================
         -- Author  : XXX
         -- Create date : XX XXX 2007
         -- Description : proc‚dure de mise … jour des r‚glement et des virements internes pec
         -- =============================================
         -- Author  : KS
         -- Modified on : 09 oct 2007
         -- Description : MaJ des filtrages et des Updates
         -- =============================================
         -- DSZ 20/03/2013 MAJ la nouvelle colonne  REGLEMENT.BLN_IN_VIR_INT_PEC
         -- =============================================
         AS
         BEGIN
          SELECT DISTINCT 
           ID_REGLEMENT 
          INTO
           #ID_REGLEMENT
          FROM 
           [VIEW_VIREMENT_INTERNE_PEC_DATA]
         
          -- ON REMPLI NR139 AVEC LES VIREMENT_INTERNE_COLLECTE AYANT ID_ACTIVITENOT NULL
          INSERT INTO NR139
          (
           ID_VIREMENT_INTERNE_PEC,
           ID_REGLEMENT
          )
          SELECT DISTINCT 
           VIREMENT_INTERNE_PEC.ID_VIREMENT_INTERNE_PEC,
           #ID_REGLEMENT.ID_REGLEMENT
          FROM 
           VIREMENT_INTERNE_PEC
           INNER JOIN VIEW_VIREMENT_INTERNE_PEC_DATA
            ON VIEW_VIREMENT_INTERNE_PEC_DATA.ID_ACTIVITE = VIREMENT_INTERNE_PEC.ID_ACTIVITE
           INNER JOIN #ID_REGLEMENT
            ON #ID_REGLEMENT.ID_REGLEMENT = VIEW_VIREMENT_INTERNE_PEC_DATA.ID_REGLEMENT
          WHERE
           NOT EXISTS (SELECT 1 FROM NR139 WHERE NR139.ID_VIREMENT_INTERNE_PEC = VIREMENT_INTERNE_PEC.ID_VIREMENT_INTERNE_PEC)
         
          -- ON REMPLI NR139 AVEC LES VIREMENT_INTERNE_COLLECTE AYANT ID_SUBVENTION  NOT NULL
          INSERT INTO NR139
          (
           ID_VIREMENT_INTERNE_PEC,
           ID_REGLEMENT
          )
          SELECT DISTINCT 
           VIREMENT_INTERNE_PEC.ID_VIREMENT_INTERNE_PEC,
           #ID_REGLEMENT.ID_REGLEMENT
          FROM 
           VIREMENT_INTERNE_PEC
           INNER JOIN VIEW_VIREMENT_INTERNE_PEC_DATA
            ON VIEW_VIREMENT_INTERNE_PEC_DATA.ID_SUBVENTION = VIREMENT_INTERNE_PEC.ID_SUBVENTION
           INNER JOIN #ID_REGLEMENT
            ON #ID_REGLEMENT.ID_REGLEMENT = VIEW_VIREMENT_INTERNE_PEC_DATA.ID_REGLEMENT
          WHERE
           NOT EXISTS (SELECT 1 FROM NR139 WHERE NR139.ID_VIREMENT_INTERNE_PEC = VIREMENT_INTERNE_PEC.ID_VIREMENT_INTERNE_PEC)
          
          UPDATE
           REGLEMENT
          SET
           BLN_IN_VIR_INT_PEC = 1
          FROM
           REGLEMENT 
           INNER JOIN #ID_REGLEMENT
            ON #ID_REGLEMENT.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         END
GO
CREATE PROCEDURE [dbo].[UPD_ARRIVEE_PIECE] 
          @ID_MODULE    int,
          @ID_STAGIAIRE   int,
          @ID_PIECE    int,
          @BLN_CONFORME   int,
          @BLN_ACTIF    int,
          @ID_ARRIVEE_PIECE_PEC int output,
          @ID_SESSION    int,
          @ID_ADHERENT   int ,
          @ID_DISPOSITIF   int,
          @ID_POSTE_COUT_REGLE    int,
          @NUM_FILE    smallint,
          @ID_UTILISATEUR   int,
          @NOM_FICHIER   varchar(100),
          @NUM_LOT    varchar(17) = NULL
         AS
         -- =============================================
         -- Author:  DSZ
         -- Create date: 17/12/2010
         -- Description: Procedure generale pour toutes les pieces du module, adherent, stagiaire
         -- EVOL PIECES 12550
         -- COD_ARRIVEE_PIECE_PEC servira a differencier les pieces : 
         -- 1 module, 2 adherent, 3 stagiaire, 4 session = A FAIRE
         -- =============================================
         -- Author:  ASD-SAF
         -- Create date: 23/12/2010
         -- Description: 12550Remplacement du calcul @ID_DISPOSITIF, par paramŠtre
         -- =============================================
         -- Author:  SAF
         -- Create date: 31/12/2010
         -- Description: 12550 Ajouter une condition pour Session
         -- =============================================
         -- Author:  SAF
         -- Create date: 07/02/2011
         -- Description: 12559 delete if the piece exists and conform and present
         -- =============================================
         -- Author:  ASD
         -- Create date: 11/02/2011
         -- Description: 12559 r‚organiser le code pour lisibilit‚
         -- =============================================
         -- DSZ 03/10/2012 14046
         -- gerer les nulls possibles dans la partie SELECT @ID_ARRIVEE_PIECE_PEC
         -- =============================================
         -- DSZ 06/06/2013 15281
         -- Ajout et gestion de  NUM_FILE
         -- =============================================
         -- LDE 13/06/2013 15281
         -- =============================================
         -- DSZ 26/06/2013 15338 ajout id_utilisateur
         -- =============================================
         -- DSZ 23/07/2013 15600 modif appel … la UPD_PIECES_STAGIAIRE
         -- =============================================
         -- DSZ 07/11/2013 16337 gestion nom_fichier
         -- =============================================
         -- WKH 26/11/2013 : 16468 ajout NUM_LOT
         -- =============================================
         -- DSZ 03/12/2013 : 16499 ajout nom_fichier et @NUM_LOT … UPD_PIECES_STAGIAIRE
         -- =============================================
         -- DSZ 16/04/2014 - #218 ne pas modifier la facture d‚j… attach‚e au module (dont id_pcr is null)
         -- =============================================
         -- DSZ 19/05/2014 - #331 enregistrer num_fichier mˆme si nom_file = 0
         -- =============================================
         -- LDE 27/05/2014 #354
         -- =============================================
         BEGIN
         
          SET @BLN_CONFORME = isnull(@BLN_CONFORME,0)
          SET @BLN_ACTIF = isnull(@BLN_ACTIF,0)
          SET @NUM_FILE = isnull(@NUM_FILE, 0)
         
          IF @ID_ADHERENT <= 0
          BEGIN
           SET @ID_ADHERENT = NULL
          END
          
          IF @ID_ARRIVEE_PIECE_PEC <= 0
          BEGIN
           SET @ID_ARRIVEE_PIECE_PEC = NULL
          END
         
          IF @ID_SESSION <= 0
          BEGIN
           SET @ID_SESSION = NULL
          END
          
          IF @ID_DISPOSITIF <= 0
          BEGIN
           SET @ID_DISPOSITIF = NULL
          END
         
          IF (@ID_POSTE_COUT_REGLE <= 0)
          BEGIN
           SET @ID_POSTE_COUT_REGLE = NULL
          END
         
          IF (@ID_STAGIAIRE IS NOT NULL)
          BEGIN
           EXEC UPD_PIECES_STAGIAIRE   
               @ID_MODULE,
              @ID_STAGIAIRE,
              @ID_PIECE,
              @BLN_CONFORME,
              @BLN_ACTIF,
              @ID_ARRIVEE_PIECE_PEC,
              @ID_SESSION,
                    @ID_DISPOSITIF,
              @ID_ADHERENT,
              @NUM_FILE,
              @NOM_FICHIER,
              @NUM_LOT
          END
          ELSE
          BEGIN
           IF ((@ID_SESSION is not null)
            AND (@ID_ARRIVEE_PIECE_PEC IS NULL)
            AND (@BLN_CONFORME = 0 OR @BLN_ACTIF = 0 or @NUM_FILE > 0))
           BEGIN
            SELECT
             @ID_ARRIVEE_PIECE_PEC = ID_ARRIVEE_PIECE_PEC -- arrivee piece de session/dr ?
            FROM
             ARRIVEE_PIECE_PEC 
            WHERE
             ID_PIECE_PEC    = @ID_PIECE
             AND isnull(ID_MODULE_PEC,0)  = isnull(@ID_MODULE,0)
             AND isnull(ID_ADHERENT,0)  = isnull(@ID_ADHERENT, 0)
             AND isnull(ID_SESSION_PEC,0) = isnull(@ID_SESSION, 0)
             AND isnull(ID_POSTE_COUT_REGLE ,0) = isnull(@ID_POSTE_COUT_REGLE, 0)
            -- les parametres @ sont NULL en cas de cr‚ation
            -- une partie des parametres est renseign‚e en mode modification ou bien l'ARRIVEE_PIECE_PEC n'existe pas
           END
            
           IF (@ID_ARRIVEE_PIECE_PEC IS NULL OR @ID_UTILISATEUR = (SELECT TOP 1 ID_UTILISATEUR FROM UTILISATEUR WHERE COD_UTIL = 'ADMIN_D3R'))
           and (@BLN_CONFORME = 0 OR @BLN_ACTIF = 0 or @NUM_FILE > 0) 
           BEGIN     
            INSERT INTO ARRIVEE_PIECE_PEC 
            (
             COD_ARRIVEE_PIECE_PEC, 
             DAT_ARRIVEE_PIECE_PEC,
             BLN_ACTIF,
             BLN_CONFORME,
             ID_MODULE_PEC,
             ID_PIECE_PEC,
             ID_STAGIAIRE_PEC, 
             ID_ADHERENT,
             ID_SESSION_PEC,
             ID_DISPOSITIF,
             ID_POSTE_COUT_REGLE,
             NUM_FILE,
             ID_UTILISATEUR,
             NOM_FICHIER,
             NUM_LOT
            )
            VALUES 
            (
             case when @ID_ADHERENT IS NOT NULL then 3 else 1 end,
             GETDATE(),
             @BLN_ACTIF,
             @BLN_CONFORME,
             @ID_MODULE,
             @ID_PIECE,
             @ID_STAGIAIRE, 
             @ID_ADHERENT,
             @ID_SESSION,
             @ID_DISPOSITIF,
             @ID_POSTE_COUT_REGLE,
             @NUM_FILE,
             @ID_UTILISATEUR,
             @NOM_FICHIER,
             @NUM_LOT
            )
         
            SET
             @ID_ARRIVEE_PIECE_PEC = @@IDENTITY
            
            UPDATE
             ARRIVEE_PIECE_PEC
            SET
             COD_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
            WHERE
             ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
           END
           ELSE IF ( @ID_ARRIVEE_PIECE_PEC IS NOT NULL)
           BEGIN
            IF (@BLN_CONFORME = 1 AND @BLN_ACTIF = 1 AND @NUM_FILE = 0) --on la supprime si exists/present et confom
            BEGIN      
             DELETE FROM NR210
             WHERE
              ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
             
             DELETE FROM ARRIVEE_PIECE_PEC
             WHERE
              ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC 
            END
            ELSE
            BEGIN    
             DECLARE @UserId INT
             SELECT
              @UserId = ID_UTILISATEUR
             FROM
              UTILISATEUR
             WHERE
              COD_util = 'admin'
         
             UPDATE ARRIVEE_PIECE_PEC
             SET 
              BLN_ACTIF   = @BLN_ACTIF,
              BLN_CONFORME  = @BLN_CONFORME,
              NUM_FILE   = @NUM_FILE,
              NOM_FICHIER   = @NOM_FICHIER,
              ID_UTILISATEUR  = @UserId
             WHERE
              ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
            END
           END
          END
         END
GO
 CREATE PROCEDURE [dbo].[UPD_MODULE_PEC]  
         -- =======================================================================================================================================
         -- 13/07/2012 EOU 13689
         -- Impact BLN_EXTERNE dans le chiffrage des formateurs internes dans le  PEC
         -- =======================================================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================
         -- LDE 04/08/2014 148E: Suppression Annulation (INS_MVT_BUDGETAIRE_INACTIVE_ACTION_PEC)
         -- =======================================================================================================================================
         -- OPA - 20140801 #148F
         -- =======================================================================================================================================
         -- OPA - 20140805 #146
         -- =======================================================================================================================================
         -- DSZ - 2014/09/04 #484
         -- Toute modification d?un module PEC devra d?sormais entra?ner la d?sapprobation (POSTE_COUT_ENGAGE.BLN_OK_FINANCEMENT = 0) 
         -- de tous les postes de co?t d?engagement non encore engag?s (et non d?sengag?s) associ?s au module modifi?.
         -- =======================================================================================================================================
         -- HBO - #578 - On ne supprime pas les PFUS
         -- =======================================================================================================================================
         -- DSZ #1003 16/07/2015 : Ajout ID_MODALITE_ENSEIGNEMENT et CODE_CPF; nettoyage
         -- =======================================================================================================================================
         -- DSZ #1290 11/03/2016 : Mettre ? jour le statut CDC
         -- =======================================================================================================================================
         -- GOK/OPA - 12/04/2016 #1152 Modification de la taille du parametre  @LIBL_ACTION de VARCHAR(100) … VARCHAR(250)
         -- ======================================================================================================================================= 
          @ID_MODULE_PEC int,
          @LIBL_MODULE_PEC varchar(250),
          @ID_ACTION int,
          @ID_ETABLISSEMENT_OF int,
          @ID_THEME int,
          @ID_STAGE int,
          @ID_FORMACODE int,
          @BLN_ACTIF int,
          @BLN_IMPUTABLE int,
          @BLN_EXTERNE int,
          @ID_UTIL int,
          @NUM_INTERNE varchar(50),
          @DAT_DEBUT datetime,
          @DAT_FIN datetime,
          @DUREE_JOURS decimal(18,2),
          @DUREE_HEURE decimal(18,2),
          @MNT_CONVENTION decimal(18,2),
          @ID_PERIODE int,
          @COM_MODULE_PEC varchar(255),
          @ID_DEPARTEMENT int,
          @TIME_STAMP TIMESTAMP,
          @BLN_INTRA int,
          @AXE_MODULE varchar(30),
          @DOMAINE_MODULE varchar(30),
          @ID_MODALITE_FORMATION int,
          @BLN_DELEGATION_PAIEMENT int,
          @ID_DISPOSITIF_PAR_DEFAUT int,
          @ID_CRITERE_CHIFFRAGE    int,
          @BLN_CATALOGUE tinyint,
          @ID_MODALITE_ENSEIGNEMENT int = null,
          @CODE_CPF varchar(10) = null
         AS  
         BEGIN
          DECLARE
           @BLN_ACTIF_STATUS_BEFORE_UPDATE INT,
           @BLN_IMPUTABLE_STATUS_BEFORE_UPDATE INT
           
          SELECT  
           @BLN_ACTIF_STATUS_BEFORE_UPDATE  = BLN_ACTIF ,
           @BLN_IMPUTABLE_STATUS_BEFORE_UPDATE = BLN_IMPUTABLE
          FROM
           MODULE_PEC 
          WHERE
           ID_MODULE_PEC = @ID_MODULE_PEC 
         
         
          UPDATE
          MODULE_PEC
          SET 
          LIBL_MODULE_PEC    = @LIBL_MODULE_PEC,
          ID_ACTION_PEC    = @ID_ACTION,
          ID_ETABLISSEMENT_OF   = @ID_ETABLISSEMENT_OF,
          ID_THEME     = @ID_THEME,
          ID_STAGE     = @ID_STAGE,
          ID_FORMACODE    = @ID_FORMACODE,
          BLN_ACTIF     = @BLN_ACTIF,
          BLN_IMPUTABLE    = @BLN_IMPUTABLE,
          BLN_EXTERNE     = @BLN_EXTERNE,
          ID_UTILISATEUR    = @ID_UTIL,
          NUM_INTERNE     = @NUM_INTERNE,
          DAT_DEBUT     = @DAT_DEBUT,
          DAT_FIN      = @DAT_FIN,
          NUM_DUREE_JOUR    = @DUREE_JOURS,
          NUM_DUREE_HEURE    = @DUREE_HEURE,
          MNT_CONVENTION    = @MNT_CONVENTION,
          ID_PERIODE     = @ID_PERIODE,
          DAT_MODIF     = GETDATE(),
          COM_MODULE_PEC    = @COM_MODULE_PEC,
          ID_DEPARTEMENT    = @ID_DEPARTEMENT,
          BLN_INTRA     = @BLN_INTRA,
          AXE_MODULE     = @AXE_MODULE,
          DOMAINE_MODULE    = @DOMAINE_MODULE,
          ID_MODALITE_FORMATION  = @ID_MODALITE_FORMATION, 
          BLN_DELEGATION_PAIEMENT  = @BLN_DELEGATION_PAIEMENT,
          ID_DISPOSITIF_PAR_DEFAUT = @ID_DISPOSITIF_PAR_DEFAUT,
          ID_CRITERE_CHIFFRAGE  = @ID_CRITERE_CHIFFRAGE,
          BLN_CATALOGUE    = @BLN_CATALOGUE,
          ID_MODALITE_ENSEIGNEMENT = @ID_MODALITE_ENSEIGNEMENT,
          CODE_CPF     = @CODE_CPF 
          WHERE 
          ID_MODULE_PEC = @ID_MODULE_PEC
          AND TIME_STAMP = @TIME_STAMP
         
          IF (@@ROWCOUNT = 0)
          BEGIN
           IF EXISTS(SELECT 1 FROM MODULE_PEC WHERE ID_MODULE_PEC  = @ID_MODULE_PEC)
           BEGIN
            RAISERROR(50001, 16, 1)
           END
           ELSE
           BEGIN
            RAISERROR(50002, 16, 1)
           END
          END
         
          UPDATE
           ACTION_PEC
          SET
           ID_UTILISATEUR = @ID_UTIL,DAT_MODIF = getdate()
          WHERE
           ID_ACTION_PEC = @ID_ACTION 
         
         
         ----- desactivation du module : traitement des mvt budgetaires pour chaque PCE
          IF (@BLN_ACTIF = 0 AND @BLN_ACTIF_STATUS_BEFORE_UPDATE = 1) OR
          (@BLN_IMPUTABLE = 0 AND @BLN_IMPUTABLE_STATUS_BEFORE_UPDATE = 1) 
          BEGIN
          DECLARE
             @EventTypeId INT,
             @EventName VARCHAR(50),
             @EventDate DATETIME,
             @EventComment VARCHAR(7600)
           
            SELECT
              @EventTypeId = ID_TYPE_EVENEMENT,
              @EventName = LIBL_TYPE_EVENEMENT
            FROM
            TYPE_EVENEMENT
            WHERE
            COD_TYPE_EVENEMENT = 'ANNULATI'
         
            SET @EventComment = 'Origine : Annulation/Non Imputabilit? Module PEC OPTIFORM'
         
            DECLARE @ID_POSTE_COUT_ENGAGE INT
            DECLARE CURSOR_INCURRED_POST_COST CURSOR FOR
             SELECT
           PCE.ID_POSTE_COUT_ENGAGE
             FROM
           MODULE_PEC MP 
           LEFT JOIN POSTE_COUT_ENGAGE PCE
            ON PCE.ID_MODULE_PEC = MP.ID_MODULE_PEC
             WHERE
           MP.ID_MODULE_PEC = @ID_MODULE_PEC
           AND PCE.ID_POSTE_COUT_ENGAGE IS NOT NULL
           AND PCE.DAT_DESENGAGEMENT IS NULL
             ORDER BY
           PCE.ID_SOUS_TYPE_COUT,
           PCE.ID_POSTE_COUT_ENGAGE
            
            OPEN CURSOR_INCURRED_POST_COST
            FETCH NEXT FROM CURSOR_INCURRED_POST_COST INTO
             @ID_POSTE_COUT_ENGAGE
         
            WHILE (@@Fetch_Status <> -1)
            BEGIN
             SET @EventDate = GETDATE()
             
             EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
           @EventName,
           @EventDate,
           @EventTypeId,
           @ID_POSTE_COUT_ENGAGE,
           NULL,
           @ID_UTIL,
           @EventComment
            
             FETCH NEXT FROM CURSOR_INCURRED_POST_COST INTO @ID_POSTE_COUT_ENGAGE
            END
         
            CLOSE CURSOR_INCURRED_POST_COST
            DEALLOCATE CURSOR_INCURRED_POST_COST
          END
         
         
         --apr?s la modification du module desapprouver tous les PCE non engag?s
          UPDATE
           POSTE_COUT_ENGAGE 
          SET
           BLN_OK_FINANCEMENT = 0,
           DAT_MODIF = GETDATE()
          WHERE
           ID_MODULE_PEC = @ID_MODULE_PEC
           AND DAT_DESENGAGEMENT IS NULL
           AND ID_ENGAGEMENT IS NULL
           
           -- mettre ? jour tous les statuts CDC de l'action du module
           UPDATE DEMANDE_CDC 
           set STATUT_DEMANDE = null
           FROM DEMANDE_CDC
          inner join STAGIAIRE_PEC_CDC on STAGIAIRE_PEC_CDC.ID_STAGIAIRE_PEC_CDC = DEMANDE_CDC.ID_STAGIAIRE_PEC_CDC
          inner join STAGIAIRE_PEC on STAGIAIRE_PEC.ID_STAGIAIRE_PEC = STAGIAIRE_PEC_CDC.ID_STAGIAIRE_PEC
          inner join MODULE_PEC on MODULE_PEC.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC
         
           where MODULE_PEC.ID_ACTION_PEC = @ID_ACTION
           and  STATUT_DEMANDE <> 'EnAttenteEnvoi'
         END
GO
 CREATE PROCEDURE [dbo].[MVT_BUDGETAIRE_REGENERATION_ACTION_PEC]  
          @ID_ACTION_PEC  INT
         AS
         BEGIN
         
         IF OBJECT_ID('tempdb..#TMP_EVENEMENT', 'U') IS NOT NULL 
         BEGIN
          drop table #TMP_EVENEMENT
         END
         
         PRINT @ID_ACTION_PEC
         
         SELECT  EVENEMENT.ID_EVENEMENT
         INTO  #TMP_EVENEMENT
         FROM  EVENEMENT
         INNER JOIN POSTE_COUT_ENGAGE ON EVENEMENT .ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE .ID_POSTE_COUT_ENGAGE
         WHERE  POSTE_COUT_ENGAGE .ID_MODULE_PEC IN 
                     ( SELECT ID_MODULE_PEC 
                      FROM MODULE_PEC 
                      WHERE ID_ACTION_PEC = @ID_ACTION_PEC 
                     )
         -- Exclusion des Postes de cout engages lies a des engagements issus de la reprise
         AND
         (
           NOT POSTE_COUT_ENGAGE . ID_POSTE_COUT_ENGAGE IN
                     ( SELECT  ID_POSTE_COUT_ENGAGE 
                      FROM  POSTE_COUT_ENGAGE
                      INNER JOIN MODULE_PEC ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
                      INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC   = MODULE_PEC.ID_ACTION_PEC
                      WHERE  ACTION_PEC.BLN_REPRISE_NESSIE = 1
                      AND   ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC -- SBR le 11/06/13
                      AND   ID_ENGAGEMENT < 478535 
                     )
           OR EVENEMENT.ID_TYPE_EVENEMENT = 8
         )
         
         INSERT INTO #TMP_EVENEMENT
         SELECT EVENEMENT.ID_EVENEMENT 
         FROM EVENEMENT
         INNER JOIN POSTE_COUT_REGLE ON EVENEMENT .ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE .ID_POSTE_COUT_REGLE
         WHERE POSTE_COUT_REGLE .ID_MODULE_PEC IN 
                   ( SELECT ID_MODULE_PEC 
                    FROM MODULE_PEC 
                    WHERE ID_ACTION_PEC = @ID_ACTION_PEC 
                   )
         -- Exclusion des Postes de cout regles lies a des reglements issus de la reprise
         AND NOT POSTE_COUT_REGLE .ID_POSTE_COUT_REGLE IN
                    ( SELECT  ID_POSTE_COUT_REGLE  
                     FROM  POSTE_COUT_REGLE  
                     INNER JOIN MODULE_PEC ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
                     INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC   = MODULE_PEC.ID_ACTION_PEC
                     WHERE  ACTION_PEC.BLN_REPRISE_NESSIE = 1
                     AND   ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC -- SBR le 11/06/13
                     AND   (ID_REGLEMENT < 379553 OR ID_REGLEMENT = 389213)
                    )
         
         
         /* SELECTION DES EVENEMENTS DE CLOTURE ET D'ANNULATION 
          -- POUR LES ACTIONS NON ISSUS DE LA REPRISE NESSIE ON LES PREND TOUS
          -- POUR LES ACTIONS ISSUS DE LA REPRISE NESSIE ON NE PRENDE EN COMPTE QUE CEUX REALISES POST_REPRISE  >= 2013
          */
         IF (SELECT BLN_REPRISE_NESSIE FROM ACTION_PEC WHERE ID_ACTION_PEC = @ID_ACTION_PEC ) = 1
         BEGIN
          INSERT INTO #TMP_EVENEMENT
          SELECT ID_EVENEMENT 
          FROM  EVENEMENT 
          INNER JOIN TYPE_EVENEMENT  ON EVENEMENT .ID_TYPE_EVENEMENT = TYPE_EVENEMENT .ID_TYPE_EVENEMENT 
          INNER JOIN POSTE_COUT_ENGAGE ON EVENEMENT .ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE .ID_POSTE_COUT_ENGAGE
          INNER JOIN MODULE_PEC   ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE .ID_MODULE_PEC 
          WHERE (COD_TYPE_EVENEMENT = 'CLOTACT' OR COD_TYPE_EVENEMENT  = 'CLOMOPEC' OR COD_TYPE_EVENEMENT  = 'ANNULATI')
          AND YEAR(DAT_EVENEMENT)   >= 2013
          AND MODULE_PEC.ID_ACTION_PEC = @ID_ACTION_PEC
         
          INSERT INTO #TMP_EVENEMENT
          SELECT MVT_BUDGETAIRE.ID_EVENEMENT 
          FROM  EVENEMENT 
          INNER JOIN TYPE_EVENEMENT  ON EVENEMENT .ID_TYPE_EVENEMENT = TYPE_EVENEMENT .ID_TYPE_EVENEMENT 
          INNER JOIN MVT_BUDGETAIRE  ON EVENEMENT .ID_EVENEMENT= MVT_BUDGETAIRE.ID_EVENEMENT
          INNER JOIN MODULE_PEC   ON MODULE_PEC.ID_MODULE_PEC = MVT_BUDGETAIRE.ID_MODULE_PEC 
          WHERE (COD_TYPE_EVENEMENT = 'CLOTACT' OR COD_TYPE_EVENEMENT  = 'CLOMOPEC' OR COD_TYPE_EVENEMENT  = 'ANNULATI')
          AND MODULE_PEC.ID_ACTION_PEC = @ID_ACTION_PEC
          AND YEAR(DAT_EVENEMENT)   >= 2013
         END
         ELSE
         BEGIN
          INSERT INTO #TMP_EVENEMENT
          SELECT MVT_BUDGETAIRE.ID_EVENEMENT 
          FROM  EVENEMENT 
          INNER JOIN TYPE_EVENEMENT  ON EVENEMENT .ID_TYPE_EVENEMENT = TYPE_EVENEMENT .ID_TYPE_EVENEMENT 
          INNER JOIN MVT_BUDGETAIRE  ON EVENEMENT .ID_EVENEMENT= MVT_BUDGETAIRE.ID_EVENEMENT
          INNER JOIN MODULE_PEC   ON MODULE_PEC.ID_MODULE_PEC = MVT_BUDGETAIRE.ID_MODULE_PEC 
          WHERE (COD_TYPE_EVENEMENT = 'CLOTACT' OR COD_TYPE_EVENEMENT  = 'CLOMOPEC' OR COD_TYPE_EVENEMENT  = 'ANNULATI')
          AND MODULE_PEC.ID_ACTION_PEC = @ID_ACTION_PEC
          
         END
         
         DELETE FROM MVT_BUDGETAIRE WHERE ID_EVENEMENT IN
         (
         SELECT ID_EVENEMENT FROM #TMP_EVENEMENT
         )
         
         DELETE FROM EVENEMENT WHERE ID_EVENEMENT IN
         (
         SELECT ID_EVENEMENT FROM #TMP_EVENEMENT
         )
         
         DELETE FROM COMMENTAIRES 
         WHERE TYPE_OBJET = 16 AND
         ID_OBJET IN
         (
         SELECT ID_EVENEMENT FROM #TMP_EVENEMENT
         )
         
         DECLARE @ID_POSTE_COUT_ENGAGE int,
           @ID_POSTE_COUT_REGLE int,
           @ID_SOUS_TYPE_COUT  int, 
           @DAT_CREATION_PCE  datetime,
           @ID_TYPE_ENGAGEMENT  int,
           @DAT_BAE    datetime,
           @DAT_DESENGAGEMENT  datetime,
           @ID_EVENEMENT   int,
           @MNT_ENGAGE_HT   decimal(15,2), 
           @MNT_FINANCE_HT   decimal(15,2), 
           @COD_TYPE_EVENEMENT  varchar(8),
           @ID_MODULE_PEC   int,
           @BLN_MODULE_ACTIF  tinyint, 
           @BLN_MODULE_IMPUTABLE tinyint, 
           @DAT_EVENEMENT   datetime, 
           @DAT_CLOTURE_MODULE  datetime, 
           @DAT_CLOTURE_ACTION  datetime,
           @DAT_MODIF_MODULE  datetime, 
           @DAT_MODIF_ACTION  datetime,
           @ID_TYPE_EVENEMENT  int,
           @LIBL_TYPE_EVENEMENT varchar(50),
           @DAT_VALID_REGLEMENT datetime,
           @MNT_REGLE_HT   decimal(15,2),
           @ID_UTILISATEUR   int,
           @COM_EVENEMENT   varchar(7600)
         
         
         SET @ID_UTILISATEUR   = 82
         SET @COM_EVENEMENT   = 'Reg‚n‚ration Evenement et Mvt Budg‚taires par la PS MVT_BUDGETAIRE_REGENERATION_ACTION_PEC'
         
         /* 
         **********************************************************************************
         -- Generation des evenements lies au chiffrage, a l'engagement et au desengagement
         ********************************************************************************** 
         */
         DECLARE cu_pce CURSOR FOR
         SELECT POSTE_COUT_ENGAGE.ID_MODULE_PEC, POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE, ID_SOUS_TYPE_COUT, DAT_CREATION_PCE = POSTE_COUT_ENGAGE.DAT_CREATION, 
         ENGAGEMENT.ID_TYPE_ENGAGEMENT, ENGAGEMENT.DAT_BAE,  POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT,
         POSTE_COUT_ENGAGE .MNT_ENGAGE_HT, MNT_FINANCE.MNT_FINANCE
         FROM POSTE_COUT_ENGAGE 
         LEFT JOIN ENGAGEMENT ON POSTE_COUT_ENGAGE .ID_ENGAGEMENT = ENGAGEMENT .ID_ENGAGEMENT 
         INNER JOIN MODULE_PEC ON MODULE_PEC .ID_MODULE_PEC = POSTE_COUT_ENGAGE .ID_MODULE_PEC
         INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         LEFT JOIN ( SELECT ID_POSTE_COUT_ENGAGE, MNT_FINANCE = SUM(MNT_PLAN_FINANCEMENT_US)
             FROM PLAN_FINANCEMENT_US
             WHERE ID_POSTE_COUT_REGLE IS NULL
             GROUP BY ID_POSTE_COUT_ENGAGE
            ) MNT_FINANCE ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = MNT_FINANCE .ID_POSTE_COUT_ENGAGE 
         WHERE MODULE_PEC.ID_ACTION_PEC= @ID_ACTION_PEC
         -- Exclusion des Postes de cout engages lies a des engagements issus de la reprise
         AND  NOT POSTE_COUT_ENGAGE . ID_POSTE_COUT_ENGAGE IN
                     ( SELECT  ID_POSTE_COUT_ENGAGE 
                      FROM  POSTE_COUT_ENGAGE
                      INNER JOIN MODULE_PEC ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
                      INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC   = MODULE_PEC.ID_ACTION_PEC
                      WHERE ACTION_PEC.BLN_REPRISE_NESSIE = 1
                      AND  ID_ENGAGEMENT < 478535 
                     )
         
         ORDER BY POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT, POSTE_COUT_ENGAGE .ID_POSTE_COUT_ENGAGE
         
         SET @ID_POSTE_COUT_REGLE =NULL
         OPEN cu_pce
         
         FETCH cu_pce INTO
           @ID_MODULE_PEC   ,
           @ID_POSTE_COUT_ENGAGE , 
           @ID_SOUS_TYPE_COUT  ,
           @DAT_CREATION_PCE  ,
           @ID_TYPE_ENGAGEMENT  ,
           @DAT_BAE    ,
           @DAT_DESENGAGEMENT  ,
           @MNT_ENGAGE_HT   , 
           @MNT_FINANCE_HT   
         
         
         WHILE @@fetch_status <> -1
         BEGIN
          --SELECT
          -- ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE  , 
          -- ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT  ,
          -- DAT_CREATION_PCE  = @DAT_CREATION_PCE   ,
          -- ID_TYPE_ENGAGEMENT  = @ID_TYPE_ENGAGEMENT  ,
          -- DAT_BAE     = @DAT_BAE     ,
          -- DAT_DESENGAGEMENT  = @DAT_DESENGAGEMENT  ,
          -- MNT_ENGAGE_HT   = @MNT_ENGAGE_HT   , 
          -- MNT_FINANCE_HT   = @MNT_FINANCE_HT   
         
         
          --IF @MNT_ENGAGE_HT != @MNT_FINANCE_HT
          --BEGIN
          -- -- Cas de desynchronisation PCE / PFUS
          -- -- Regeneration Impossible
          --SELECT
          -- 'Cas de desynchronisation PCE / PFUS  -- Regeneration Impossible',
           
          -- ID_MODULE_PEC   = @ID_MODULE_PEC   ,
          -- ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE  , 
          -- ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT  ,
          -- DAT_CREATION_PCE  = @DAT_CREATION_PCE   ,
          -- ID_TYPE_ENGAGEMENT  = @ID_TYPE_ENGAGEMENT  ,
          -- DAT_BAE     = @DAT_BAE     ,
          -- DAT_DESENGAGEMENT  = @DAT_DESENGAGEMENT  ,
          -- MNT_ENGAGE_HT   = @MNT_ENGAGE_HT   , 
          -- MNT_FINANCE_HT   = @MNT_FINANCE_HT   
          --END
          --ELSE
          BEGIN
           IF @ID_TYPE_ENGAGEMENT IS NULL  -- Pas d'engagement
            OR
            @ID_TYPE_ENGAGEMENT = 1 -- Engagement initial
            OR 
            @ID_TYPE_ENGAGEMENT = 3 -- Engagement compl.
           BEGIN  
            -- Generation de l'evenement lie au chiffrage du PCE 
            -- ***************************************************
            -- Dans OPTIFORM, il doit etre declenche lors de l'approbation d'un chiffrage d'un PCE (Bouton Approuver de l'ecran de Chiffrage)
            -- A chaque chiffrage d'un PCE, un nouvel evenement est cree pour le PCE approuve (qui est le dernier genere pour le sous type de cout associe - sans BAE et non desengage)
            -- ********************************************************************************************************************
            SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
            FROM TYPE_EVENEMENT
            WHERE COD_TYPE_EVENEMENT = 'CHIF_PEC'
            
            SET @ID_POSTE_COUT_REGLE = NULL
            SET @DAT_EVENEMENT = @DAT_CREATION_PCE
            EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
            @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
            
            IF @DAT_BAE IS NOT NULL
            BEGIN 
             -- Generation de l'evenement lie a l'engagement
               -- ***************************************************
             -- Dans OPTIFORM, il doit etre declenche lors du BAE
             -- Un evenement est cree pour tous les PCE associes a l'action engage -- ceux lie a l'engagement cree (table ENGAGEMENT)
             -- ********************************************************************************************************************
             SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
             FROM TYPE_EVENEMENT
             WHERE COD_TYPE_EVENEMENT = 'ENGAGMT'
             
             SET @ID_POSTE_COUT_REGLE = NULL
             SET @DAT_EVENEMENT = @DAT_BAE
             EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
             @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
             
            END
           END
           
           IF @ID_TYPE_ENGAGEMENT = 2 -- Desengagement
           BEGIN  
            -- Generation de l'evenement lie au desengagement d'un PCE
            -- ***************************************************
            -- Dans OPTIFORM, il doit etre declenche lors du desengagement d'un PCE
            -- Un evenement est cree pour tous le PCE desengage
            -- ********************************************************************************************************************
            SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
            FROM TYPE_EVENEMENT
            WHERE COD_TYPE_EVENEMENT = 'DESENG'
               
            SET @DAT_EVENEMENT = @DAT_DESENGAGEMENT
            EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
            @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
         
           END
          END
          
          FETCH cu_pce INTO
           @ID_MODULE_PEC   ,
           @ID_POSTE_COUT_ENGAGE , 
           @ID_SOUS_TYPE_COUT  ,
           @DAT_CREATION_PCE  ,
           @ID_TYPE_ENGAGEMENT  ,
           @DAT_BAE    ,
           @DAT_DESENGAGEMENT  ,
           @MNT_ENGAGE_HT   , 
           @MNT_FINANCE_HT   
          
         END
         CLOSE cu_pce
         DEALLOCATE cu_pce
         
         /* 
         **********************************************************************************
         -- Generation des evenements lies au reglement
         ********************************************************************************** 
         */
         DECLARE cu_pcr CURSOR FOR
         SELECT POSTE_COUT_REGLE.ID_MODULE_PEC, POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE, POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT, REGLEMENT.DAT_VALID_REGLEMENT,
         POSTE_COUT_REGLE.MNT_REGLE_HT, MNT_FINANCE.MNT_FINANCE
         FROM POSTE_COUT_REGLE
         INNER JOIN REGLEMENT ON POSTE_COUT_REGLE .ID_REGLEMENT = REGLEMENT .ID_REGLEMENT 
         INNER JOIN MODULE_PEC ON MODULE_PEC .ID_MODULE_PEC = POSTE_COUT_REGLE .ID_MODULE_PEC
         INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         LEFT JOIN ( SELECT ID_POSTE_COUT_REGLE, MNT_FINANCE = SUM(MNT_PLAN_FINANCEMENT_US)
             FROM PLAN_FINANCEMENT_US
             GROUP BY ID_POSTE_COUT_REGLE
            ) MNT_FINANCE ON POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = MNT_FINANCE .ID_POSTE_COUT_REGLE
         WHERE MODULE_PEC.ID_ACTION_PEC = @ID_ACTION_PEC
         AND REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
         -- Exclusion des Postes de cout regles lies a des reglements issus de la reprise
         AND NOT POSTE_COUT_REGLE .ID_POSTE_COUT_REGLE IN
                    ( SELECT ID_POSTE_COUT_REGLE  
                     FROM POSTE_COUT_REGLE  
                     INNER JOIN MODULE_PEC ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
                     INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC   = MODULE_PEC.ID_ACTION_PEC
                     WHERE ACTION_PEC.BLN_REPRISE_NESSIE = 1
                     AND (ID_REGLEMENT < 379553 OR ID_REGLEMENT = 389213)
                    )
         
         ORDER BY POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT, POSTE_COUT_REGLE .ID_POSTE_COUT_REGLE
         
         SET @ID_POSTE_COUT_ENGAGE=NULL
         
         OPEN cu_pcr
         
         FETCH cu_pcr INTO
           @ID_MODULE_PEC   ,
           @ID_POSTE_COUT_REGLE , 
           @ID_SOUS_TYPE_COUT  ,
           @DAT_VALID_REGLEMENT ,
           @MNT_REGLE_HT   , 
           @MNT_FINANCE_HT   
         
         WHILE @@fetch_status <> -1
         BEGIN
         
          IF @MNT_REGLE_HT != @MNT_FINANCE_HT
          BEGIN
           -- Cas de desynchronisation PCE / PFUS
           -- Regeneration Impossible
          SELECT
           'Cas de desynchronisation PCR / PFUS  -- Regeneration Impossible',
           
           ID_MODULE_PEC   = @ID_MODULE_PEC  ,
           ID_POSTE_COUT_REGLE  = @ID_POSTE_COUT_REGLE , 
           ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT ,
           DAT_VALID_REGLEMENT  = @DAT_VALID_REGLEMENT ,
           MNT_REGLE_HT   = @MNT_REGLE_HT   , 
           MNT_FINANCE_HT   = @MNT_FINANCE_HT   
          END
          ELSE
          BEGIN
           SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
           FROM TYPE_EVENEMENT
           WHERE COD_TYPE_EVENEMENT = 'REGLEMT'
         
           SET @DAT_EVENEMENT  = ISNULL( @DAT_VALID_REGLEMENT, @DAT_MODIF_ACTION)
           
           EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
           @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
          END
          
          FETCH cu_pcr INTO
           @ID_MODULE_PEC   ,
           @ID_POSTE_COUT_REGLE , 
           @ID_SOUS_TYPE_COUT  ,
           @DAT_VALID_REGLEMENT ,
           @MNT_REGLE_HT   , 
           @MNT_FINANCE_HT   
         
         END
         CLOSE cu_pcr
         DEALLOCATE cu_pcr
         
         /* 
         **********************************************************************************
         -- Generation des evenements lies aux annulations et aux clotures
         ********************************************************************************** 
         */
         DECLARE cu_etat_module CURSOR FOR
         SELECT MODULE_PEC.ID_MODULE_PEC, DER_PCE.ID_POSTE_COUT_ENGAGE, MODULE_PEC.BLN_ACTIF, MODULE_PEC.BLN_IMPUTABLE, MODULE_PEC.DAT_CLOTURE, ACTION_PEC.DAT_CLOTURE, MODULE_PEC.DAT_MODIF, ACTION_PEC.DAT_MODIF
         FROM MODULE_PEC
         INNER JOIN ACTION_PEC ON ACTION_PEC .ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC 
         INNER JOIN (SELECT ID_MODULE_PEC, ID_SOUS_TYPE_COUT, ID_POSTE_COUT_ENGAGE = MAX(ID_POSTE_COUT_ENGAGE)
            FROM POSTE_COUT_ENGAGE
            GROUP BY ID_MODULE_PEC, ID_SOUS_TYPE_COUT) 
            DER_PCE ON DER_PCE .ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC   
            
         WHERE ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC
           AND
           (  
            (
             ACTION_PEC.BLN_REPRISE_NESSIE = 0 AND (MODULE_PEC.BLN_ACTIF = 0 OR MODULE_PEC.BLN_IMPUTABLE = 0)
            )
            OR 
            (
             ACTION_PEC.BLN_REPRISE_NESSIE = 1 AND (YEAR(MODULE_PEC.DAT_MODIF) >= 2013 OR YEAR(ACTION_PEC.DAT_MODIF) >= 2013)
            )
            OR 
            (
             ACTION_PEC.BLN_REPRISE_NESSIE = 0 AND (MODULE_PEC.DAT_CLOTURE IS NOT NULL OR ACTION_PEC.DAT_CLOTURE IS NOT NULL)
            )
            OR 
            (
             ACTION_PEC.BLN_REPRISE_NESSIE = 1 AND (YEAR(MODULE_PEC.DAT_CLOTURE) >= 2013 OR YEAR(ACTION_PEC.DAT_CLOTURE) >= 2013)
            )
           )
         
         OPEN cu_etat_module
         
         FETCH cu_etat_module INTO
          @ID_MODULE_PEC,
          @ID_POSTE_COUT_ENGAGE,
          @BLN_MODULE_ACTIF , 
          @BLN_MODULE_IMPUTABLE , 
          @DAT_CLOTURE_MODULE , 
          @DAT_CLOTURE_ACTION ,
          @DAT_MODIF_MODULE ,
          @DAT_MODIF_ACTION 
         
         WHILE (@@FETCH_STATUS <> -1)
         BEGIN
         
          IF (@DAT_CLOTURE_MODULE IS NOT NULL OR  @DAT_CLOTURE_ACTION  IS NOT NULL)
          BEGIN 
           -- ***************************************************
           -- Generation de l'evenement lie a la cloture d'un module
           -- ***************************************************
           -- Dans OPTIFORM, il doit etre declenche lors de la cloture d'un module ou d'une action
           -- Un evenement est genere pour chaque sous type de cout associe a l'action au module
           -- ******************************************************************************************************************** 
           SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
           FROM TYPE_EVENEMENT
           WHERE COD_TYPE_EVENEMENT = 'CLOMOPEC'
           
           
           
           SET @ID_POSTE_COUT_REGLE =NULL
           SET @DAT_EVENEMENT  = ISNULL( @DAT_CLOTURE_MODULE, @DAT_CLOTURE_ACTION)
           EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
           @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
           
          END
          ELSE IF  (@BLN_MODULE_ACTIF = 0 OR @BLN_MODULE_IMPUTABLE = 0)
          BEGIN 
           -- ***************************************************
           -- Generation de l'evenement lie a l'annulation d'un module
           -- ***************************************************
           -- Dans OPTIFORM, il doit etre declenche lors de l'annulation d'un module ou d'une action
           -- Un evenement est genere pour chaque sous type de cout associe a l'action au module
           -- ********************************************************************************************************************  
           IF @DAT_MODIF_ACTION > @DAT_MODIF_MODULE 
           BEGIN
            SET @DAT_MODIF_MODULE = @DAT_MODIF_ACTION 
           END
           
           SELECT @ID_TYPE_EVENEMENT = ID_TYPE_EVENEMENT, @LIBL_TYPE_EVENEMENT = LIBL_TYPE_EVENEMENT
           FROM TYPE_EVENEMENT
           WHERE COD_TYPE_EVENEMENT = 'ANNULATI'
           
           SET @ID_POSTE_COUT_REGLE =NULL
           SET @DAT_EVENEMENT  = ISNULL( @DAT_MODIF_MODULE, @DAT_MODIF_ACTION)
           EXEC MVT_BUDGETAIRE_PEC_INS_EVENEMENT_PEC
           @LIBL_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_TYPE_EVENEMENT, @ID_POSTE_COUT_ENGAGE, @ID_POSTE_COUT_REGLE, @ID_UTILISATEUR, @COM_EVENEMENT, @ID_EVENEMENT out
           
          END
         
          FETCH cu_etat_module INTO
           @ID_MODULE_PEC,
           @ID_POSTE_COUT_ENGAGE,
           @BLN_MODULE_ACTIF , 
           @BLN_MODULE_IMPUTABLE , 
           @DAT_CLOTURE_MODULE , 
           @DAT_CLOTURE_ACTION ,
           @DAT_MODIF_MODULE ,
           @DAT_MODIF_ACTION 
         
          
         END
         
         CLOSE cu_etat_module
         DEALLOCATE cu_etat_module
         END
GO
 CREATE PROCEDURE [dbo].[INS_ARRIVEE_PIECE]
          @TYPE_PIECE  VARCHAR(10),
          @ID_FACTURE  INT,
          @ID_DOSSIER  INT,
          @TYPE_DOSSIER VARCHAR(3),
          @NOM_FICHIER VARCHAR(100),
          @RESULT_SUCCESS INT OUTPUT,
          @NUM_LOT  VARCHAR(17) = NULL 
         AS
         -- =======================================================================================================================================
         -- AUTHOR:  GIO ACAR
         -- CREATE DATE: 10 JUIN 2013
         -- DESCRIPTION: INSERTION D'UNE ARRIVEE PIECE
         -- MANTIS  : B15254 [Paniers] R‚alisation des PS Paniers
         -- =======================================================================================================================================
         -- DSZ 26/06/2013 15338 ajout id_utilisateur
         -- =======================================================================================================================================
         -- DSZ 12/11/2013 16337 ajout NOM_FICHIER
         -- =======================================================================================================================================
         -- WKH 26/11/2013 : 16468 ajout NUM_LOT
         -- =======================================================================================================================================
         -- ASD 02/12/2013 : 16499 suppression r‚pertoire de la piŠce si fourni dans @NOM_FICHIER
         --       + gestion NUM_FILE (revue DSZ)
         -- =======================================================================================================================================
         -- ASD 05/12/2013 : 15738 correction passage paramŠtre tjrs nul … UPD_ARRIVEE_PIECE
         -- =======================================================================================================================================
         -- HBO - 20140327 - #237 - Facture Conforme par D3R
         -- =======================================================================================================================================
         -- LDE 31/03/2014 - ajout r‚entrance
         -- =======================================================================================================================================
         -- DSZ 17/04/2014 - PEC : uniquement une cr‚ation par D3R, pas d'update (vu ASD+BBL)
         -- modification du curseur pour que le contenu ne soit pas modifi‚ par une insertion en cours de vie du curseur
         -- =======================================================================================================================================
         -- OPA 15/05/2014 - #324 - En tant qu'utilisateur systŠme Optiform, lorsque D3R me demande d'enregistrer une facture pour un dossier PRO, 
         -- je l'enregistre pr‚sente et conforme, car ces v‚rifications de conformit‚ sont faites par D3R.
         -- =======================================================================================================================================
         BEGIN
          DECLARE
           @ID_UTILISATEUR INT
          
          SELECT
           @ID_UTILISATEUR = ID_UTILISATEUR
          FROM
           UTILISATEUR
          WHERE
           COD_UTIL = 'ADMIN_D3R'
         
          --16499 SUPPRESSION RPERTOIRE DE LA PIÔCE SI FOURNI DANS @NOM_FICHIER
          IF CHARINDEX('\', REVERSE(@NOM_FICHIER))>0  
          BEGIN
           SET @NOM_FICHIER = RIGHT(@NOM_FICHIER, CHARINDEX('\', REVERSE(@NOM_FICHIER))-1)
          END
           
          DECLARE
           @NUM_FILE    INT = 1,
           @NUM_FILE_A_PASSER  INT = 0,
           @NUM_FILE_ARR_EXISTANT INT = 0,
           @NOW     DATETIME = GETDATE(),
           @BLN_CONFORME   INT = 0
         
          IF(@TYPE_PIECE='FACT' OR @TYPE_PIECE='FACTADH' OR @TYPE_PIECE='FACTOF') --#324
          BEGIN
           SET @BLN_CONFORME = 1 --#237
          END
         
          IF @TYPE_DOSSIER='PRO'
          BEGIN
           DECLARE
            @ID_PIECE_PRO INT
           
           SELECT
            @ID_PIECE_PRO=ID_PIECE_PRO
           FROM
            PIECE_PRO
           WHERE
            COD_PIECE_PRO=@TYPE_PIECE
           
           IF (NOT EXISTS (SELECT 1
               FROM
                FACTURE
               WHERE
                ID_FACTURE = @ID_FACTURE
                AND @TYPE_PIECE='FACT'
               ) --PIÔCE FACTURE UNIQUEMENT
            OR
            NOT EXISTS (SELECT 1
               FROM
                ARRIVEE_PIECE_PRO 
                INNER JOIN CONTRAT_PRO
                 ON CONTRAT_PRO.ID_CONTRAT_PRO = ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO
               WHERE
                ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO = @ID_DOSSIER
                AND CONTRAT_PRO.BLN_ACTIF = 1
                AND ARRIVEE_PIECE_PRO.ID_PIECE_PRO = @ID_PIECE_PRO
               )
            )
            BEGIN
             EXEC INS_ARRIVEE_PIECE_PRO
              @NOW,
              1,
              @BLN_CONFORME,
              NULL,
              @ID_PIECE_PRO,
              @ID_DOSSIER,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              1,
              @ID_UTILISATEUR,
              @NOM_FICHIER,
              @NUM_LOT  
            END
            ELSE
            BEGIN
             DECLARE
              @COD_ARRIVEE_PIECE_PRO INT,
              @ID_ARRIVEE_PIECE_PRO INT
         
             SELECT
              @ID_ARRIVEE_PIECE_PRO = ID_ARRIVEE_PIECE_PRO,
              @COD_ARRIVEE_PIECE_PRO = COD_ARRIVEE_PIECE_PRO,
              @NUM_FILE_ARR_EXISTANT = NUM_FILE  --ASD 16499
             FROM
              ARRIVEE_PIECE_PRO
             WHERE
              ID_CONTRAT_PRO = @ID_DOSSIER
              AND ID_PIECE_PRO = @ID_PIECE_PRO
             
             SET @NUM_FILE_A_PASSER = @NUM_FILE_ARR_EXISTANT + @NUM_FILE --ASD 16499
             
             EXEC UPD_ARRIVEE_PIECE_PRO
              @ID_ARRIVEE_PIECE_PRO,
              @COD_ARRIVEE_PIECE_PRO,
              GETDATE,
              1,
              @BLN_CONFORME,
              NULL,
              TIMESTAMP,
              @ID_PIECE_PRO,
              @ID_DOSSIER,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              NULL,
              @NUM_FILE_A_PASSER,
              @ID_UTILISATEUR,
              @NOM_FICHIER,
              @NUM_LOT
            END
          END
          ELSE IF  @TYPE_DOSSIER='PEC' 
          BEGIN
           
           DECLARE
            @ID_PIECE_PEC INT
           
           SELECT
            @ID_PIECE_PEC = ID_PIECE_PEC
           FROM
            PIECE_PEC
           WHERE
            COD_PIECE_PEC = @TYPE_PIECE
           
           DECLARE
            @ID_MODULE INT,
            @ID_STAGIAIRE_EXISTANT INT = NULL,
            @ID_ADHERENT_EXISTANT INT = NULL,
            @ID_ARRIVEE_PIECE_PEC_EXISTANT INT = NULL
         
         
           DECLARE CURSORMODULE CURSOR FOR 
            SELECT
             modules.ID_MODULE_PEC,
             ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
             NUM_FILE, 
             ID_STAGIAIRE_PEC,
             ID_ADHERENT 
            FROM
             (SELECT
             MODULE_PEC.ID_MODULE_PEC,
             min(ID_ARRIVEE_PIECE_PEC) as id_app
             FROM
              MODULE_PEC
              LEFT JOIN ARRIVEE_PIECE_PEC
               ON ARRIVEE_PIECE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
                AND ARRIVEE_PIECE_PEC.ID_PIECE_PEC = @ID_PIECE_PEC
             WHERE
              MODULE_PEC.ID_ACTION_PEC = @ID_DOSSIER
              AND MODULE_PEC.BLN_ACTIF = 1
             GROUP BY MODULE_PEC.ID_MODULE_PEC ) modules
             LEFT JOIN ARRIVEE_PIECE_PEC
              ON ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC = modules.id_app
         
           OPEN CURSORMODULE
           FETCH NEXT FROM CURSORMODULE 
            INTO @ID_MODULE, @ID_ARRIVEE_PIECE_PEC_EXISTANT, @NUM_FILE_ARR_EXISTANT, @ID_STAGIAIRE_EXISTANT, @ID_ADHERENT_EXISTANT
           WHILE @@FETCH_STATUS = 0
           BEGIN
            IF(@TYPE_PIECE='FACT')
             SET @NUM_FILE_A_PASSER = 1
            ELSE
             SET @NUM_FILE_A_PASSER = COALESCE(@NUM_FILE_ARR_EXISTANT + @NUM_FILE, @NUM_FILE)
         
            --LA PS FAIT INSERTION OU UPDATE SELON BESOIN
            EXEC UPD_ARRIVEE_PIECE 
             @ID_MODULE,
             NULL,
             @ID_PIECE_PEC,
             @BLN_CONFORME,
             1,
             @ID_ARRIVEE_PIECE_PEC_EXISTANT,
             0,
             @ID_ADHERENT_EXISTANT,
             0,
             0,
             @NUM_FILE_A_PASSER,
             @ID_UTILISATEUR,
             @NOM_FICHIER,
             @NUM_LOT
            
            FETCH NEXT FROM CURSORMODULE
             INTO @ID_MODULE,  @ID_ARRIVEE_PIECE_PEC_EXISTANT, @NUM_FILE_ARR_EXISTANT, @ID_STAGIAIRE_EXISTANT, @ID_ADHERENT_EXISTANT
           END
           
           CLOSE CURSORMODULE -- CLOSE THE CURSOR
           DEALLOCATE CURSORMODULE -- DEALLOCATE THE CURSOR
         
          END
         
          SET @RESULT_SUCCESS = 0
         END
GO

         
         create PROCEDURE [dbo].[EDI_TRANSCO_LEC_GRP_TABLE_CONCERNEE]
         /* 
           Lecture des tables concernees par la transcodification dans le cadre de l'EDI 
         */  
         AS
         BEGIN
         
         SET ROWCOUNT 0
         SET NOCOUNT ON
         
         DECLARE @COD_FAF 		CHAR(5),
         	@LIBC_FAF 		VARCHAR(20),
         	@id			INTEGER,
         	@name	 		VARCHAR(255),
         	@ID_TABLE_FAF_DEFAUT	VARCHAR(255),
         	@LIB			VARCHAR(2000)
         
         SELECT name , id, ID_TABLE_FAF_DEFAUT ID_FAF,  @COD_FAF COD_FAF, @LIBC_FAF LIBC_FAF
         INTO #TMP01
         from sysobjects, EDI_TRANSCO_TABLE_CONCERNEE 
         where type = 'U'
         and sysobjects.name = EDI_TRANSCO_TABLE_CONCERNEE.COD_TABLE_FAF COLLATE Latin1_General_BIN
         
         DECLARE cur SCROLL CURSOR FOR
         SELECT id, name, ID_FAF
         FROM	#TMP01
         
         CREATE TABLE #TMP02
         (
         	ID_TABLE	INTEGER		NULL,
         	ID_FAF 		INTEGER		NULL,
         	COD_FAF 	CHAR(5)		NULL,
         	LIBC_FAF 	VARCHAR(20)	NULL
         )
         OPEN cur
         FETCH cur INTO @id, @name, @ID_TABLE_FAF_DEFAUT
         WHILE (@@fetch_status <> -1)
         BEGIN
         	IF @ID_TABLE_FAF_DEFAUT IS NOT NULL
         	BEGIN
         		DELETE FROM #TMP02
         		
         		SET @LIB = 'INSERT INTO #TMP02 '
         		SET @LIB = @LIB + 'SELECT ' + CONVERT(VARCHAR, @id) + ', ID_' + @name + ' ID , COD_' + @name + ' COD , LIBC_' + @name + ' LIBC  FROM ' + @name
         		SET @LIB = @LIB + ' WHERE ID_' + @name + ' = ' + CONVERT(VARCHAR, @ID_TABLE_FAF_DEFAUT)
         		EXECUTE (@LIB)
         
         
         		UPDATE 	#TMP01 
         		SET 	#TMP01.COD_FAF = #TMP02.COD_FAF,
         			#TMP01.LIBC_FAF = #TMP02.LIBC_FAF
         		FROM	#TMP02 
         		WHERE	#TMP01.ID_FAF = #TMP02.ID_FAF
         		AND	#TMP01.id = #TMP02.ID_TABLE
         
         	
         	END	
         	FETCH cur INTO @id, @name,@ID_TABLE_FAF_DEFAUT
         END
         
         SELECT * FROM #TMP01
         ORDER BY name
         
         CLOSE cur
         DEALLOCATE cur
         
         
         END
         
GO

         
         -- =============================================
         -- Author:		SV
         -- Create date: 17 ao–t 2007
         -- Description:	Ajout de la contrainte d'existance d'un etablissement sur le poste co–t r‚gl‚ dans le cas d'une facture indirecte
         --				Ajout de la v‚rification de l'‚tat actif du poste de co–t regl‚
         --					--> David : Dans le cas d'une facture indirecte sans ‚tablissement, il est impossible de g‚n‚rer de rŠglement car il n'y a pas d'IBAN associ‚
         -- =============================================
         -- Author:		KS
         -- Modif. date: 09 oct. 2007
         -- Description:	Ajout du compte sur le nombre de r‚glement afin de prendre en compte le cas d'une validation directe sans ‚diter les 
         --				impressions non ‚dit‚s.
         -- =============================================
         -- Author:		ASDI
         -- Modif. date: 28 oct. 2008
         -- Description:	Retirer le blocage sur la validation des virements lorsqu'il y a un avoir qui traŒne.
         -- =============================================
         -- Author		: APA
         -- Create date	: 26/01/2012
         -- Description	: Defi Lot 1 - 13139 - Ajout du filtre par Id Utilisateur				
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_GRP_POSTE_COUT_REGLE_HORS_REGLEMENT]
         	@ID_UTILISATEUR AS INT = NULL
         AS
         BEGIN
         	DECLARE @NB_POSTE_COUT_REGLE	AS INT
         	DECLARE @NB_REGLEMENT			AS INT
         
         	SET @NB_POSTE_COUT_REGLE =
         	(
         		SELECT
         			COUNT(ID_POSTE_COUT_REGLE) as NB_POSTE_COUT_REGLE
         		FROM
         			POSTE_COUT_REGLE 
         				INNER JOIN SESSION ON SESSION.ID_SESSION = POSTE_COUT_REGLE.ID_SESSION
         		WHERE
         			SESSION.DAT_PAIEMENT is NULL 
         			AND SESSION.DAT_RECEPTION is not NULL
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			AND POSTE_COUT_REGLE.DAT_BAP is not NULL 
         			AND (POSTE_COUT_REGLE.ID_REGLEMENT is NULL AND POSTE_COUT_REGLE.ID_TYPE_FACTURE<>2)
         			AND
         			(
         				POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         				OR POSTE_COUT_REGLE.ID_ETABLISSEMENT is not null
         			)
         			AND (SESSION.ID_UTILISATEUR_REGLEMENT = @ID_UTILISATEUR OR @ID_UTILISATEUR IS NULL)
         	)
         	SELECT
         		@NB_REGLEMENT = COUNT(ID_REGLEMENT)
         	FROM
         		REGLEMENT
         	WHERE
         		BLN_ACTIF = 1 
         		AND BLN_EN_COURS = 1 
         		AND DAT_EDITION is null
         		AND (ID_UTILISATEUR = @ID_UTILISATEUR OR @ID_UTILISATEUR IS NULL)
         
         
         	SET @NB_POSTE_COUT_REGLE = @NB_POSTE_COUT_REGLE + @NB_REGLEMENT
         
         	SELECT 'Return Value' = COALESCE(@NB_POSTE_COUT_REGLE,0)
         END
         
         
         
GO
 -- =============================================================
         -- Author		: GiO
         -- Create date	: 12 Mars 2008
         -- Description	: Lettre de relance de Reglement pour l'OF
         -- =============================================================
         CREATE PROCEDURE [dbo].[EDT_LETTRE_RELANCE_REGLEMENT_CONTRAT_PRO_OF]
         	@ID_ETABLISSEMENT	INT,
         	@ID_BENEFICIAIRE	INT,
         	@TYPE_BENEFICIAIRE	INT,
         	@ID_ADRESSE			INT,
         	@ID_CONTACT			INT,
         	@COD_CONTRAT_PRO	VARCHAR(10)
         AS
         BEGIN
         
         	DECLARE @relance INT
         	SET @relance = 1
         
         	/**** R‚cup‚ration des infos sur le contrat pro ****/
         	SELECT	ADHERENT.COD_ADHERENT,
         			CONTRAT_PRO.ID_CONTRAT_PRO,
         			CONTRAT_PRO.COD_CONTRAT_PRO,
         			CONTRAT_PRO.LIB_LIEU_FORMATION,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_DEB_CONTRAT, 3) AS DAT_DEBUT,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_FIN_CONTRAT, 3) AS DAT_FIN,
         			AGENCE.ID_AGENCE,
         			AGENCE.COD_POSTAL,
         			AGENCE.LIB_VILLE,
         			AGENCE.LIB_NOM_CONSEILLER,
         			AGENCE.LIB_PNM_CONSEILLER,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU
         	INTO	#TMP_REGLEMENT_CONTRAT_PRO 
         	FROM	CONTRAT_PRO
         			INNER JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         			INNER JOIN SALARIE_PRO ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         			INNER JOIN INDIVIDU ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			INNER JOIN AGENCE ON CONTRAT_PRO.ID_AGENCE = AGENCE.ID_AGENCE
         	WHERE   CONTRAT_PRO.COD_CONTRAT_PRO = @COD_CONTRAT_PRO;
         
         	/**** R‚cup‚ration du COD_OF ****/
         	
         	
         			SELECT ORGANISME_FORMATION.COD_OF as COD_OF
         				into #OF
         			FROM
         				ETABLISSEMENT_OF
         				INNER JOIN		ORGANISME_FORMATION		ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			WHERE 
         				ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_BENEFICIAIRE;
         
         	/*** Recuperation de la liste des pieces modules li‚es … ce contrat  **********/
         	SELECT	DISTINCT PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         			MODULE_PRO.COD_MODULE_PRO, 
         			MODULE_PRO.LIBL_MODULE_PRO,
         			MODULE_PRO.BLN_SUBROGE,
         			MODULE_PRO.BLN_ACTIF AS MODULE_ACTIF,
         			CONVERT(VARCHAR(8),MODULE_PRO.DAT_DEBUT, 3) AS DAT_DEBUT,
         			dbo.GetFrenchCurrencyFormat(CAST(MODULE_PRO.NB_UNITE_TOTALE as MONEY))  AS NB_UNITE_TOTALE,
                     ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         	INTO	#TMP_REGLEMENT_PIECES_MODULE_PRO
         	FROM	#TMP_REGLEMENT_CONTRAT_PRO
         			INNER JOIN MODULE_PRO ON #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         									AND MODULE_PRO.BLN_SUBROGE = 1  AND MODULE_PRO.BLN_OK_PIECE = 0 
         			INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         			INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			INNER JOIN ARRIVEE_PIECE_PRO ON MODULE_PRO.ID_MODULE_PRO = ARRIVEE_PIECE_PRO.ID_MODULE_PRO 
         			INNER JOIN PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO
         			AND (ARRIVEE_PIECE_PRO.BLN_ACTIF!=1 OR ARRIVEE_PIECE_PRO.BLN_CONFORME!=1)	AND MODULE_PRO.BLN_ACTIF=1 AND PIECE_PRO.BLN_MODULE = 1 AND PIECE_PRO.BLN_CONTRAT = 0 AND PIECE_PRO.BLN_ACTIF=1 AND  (PIECE_PRO.BLN_BLOQUANT_REGLEMENT = 1 or PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1 );
         
         
         
         	/*** Recuperation de la liste des pieces session li‚es … ce contrat  **********/
         	SELECT     PIECE_PRO.ID_PIECE_PRO, 
         			PIECE_PRO.LIBC_PIECE_PRO, 
         			PIECE_PRO.LIBL_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO, 
         			ARRIVEE_PIECE_PRO.BLN_ACTIF,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         			ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         			MODULE_PRO.COD_MODULE_PRO, 
         			MODULE_PRO.LIBL_MODULE_PRO,
         			MODULE_PRO.BLN_SUBROGE,
         			MODULE_PRO.BLN_ACTIF AS MODULE_PRO_ACTIF,
         			CONVERT(VARCHAR(8),SESSION_PRO.DAT_DEBUT, 3) AS DAT_DEBUT,
         			SESSION_PRO.COD_SESSION_PRO,
         			SESSION_PRO.NUM_FACTURE,
         			SESSION_PRO.BLN_ACTIF as SESSION_ACTIF,
         			dbo.GetFrenchCurrencyFormat(CAST(SESSION_PRO.NB_UNITE_TOTALE as MONEY))  AS NB_UNITE_TOTALE,
                     ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         	INTO	#TMP_REGLEMENT_PIECES_SESSION
         FROM         ARRIVEE_PIECE_PRO 
         Inner join #TMP_REGLEMENT_CONTRAT_PRO on #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO= ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO 
         INNER JOIN
                               SESSION_PRO ON ARRIVEE_PIECE_PRO.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO
         inner join module_pro on module_pro.id_module_pro=ARRIVEE_PIECE_PRO.id_module_pro
         INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         			INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			INNER JOIN PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO AND (ARRIVEE_PIECE_PRO.BLN_ACTIF!=1 OR ARRIVEE_PIECE_PRO.BLN_CONFORME!=1)
         and module_pro.bln_subroge=1
         WHERE     (ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO = #TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO) AND (ARRIVEE_PIECE_PRO.ID_SESSION_PRO IS NOT NULL) AND 
                              ( (ARRIVEE_PIECE_PRO.BLN_ACTIF <> 1) OR   (ARRIVEE_PIECE_PRO.BLN_CONFORME <> 1))
                            				AND SESSION_PRO.BLN_ACTIF=1 AND MODULE_PRO.BLN_ACTIF=1	AND PIECE_PRO.BLN_SESSION = 1 AND PIECE_PRO.BLN_CONTRAT = 0 AND PIECE_PRO.BLN_MODULE = 0 AND PIECE_PRO.BLN_ACTIF=1 AND  (PIECE_PRO.BLN_BLOQUANT_REGLEMENT = 1 or PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT = 1 ) and SESSION_PRO.BLN_OK_PIECE = 0 and ORGANISME_FORMATION.ID_OF=@ID_BENEFICIAIRE;   
                             
         
         
         		IF  ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO WHERE DAT_RELANCE_REGLE_2 IS NOT NULL)  > 0 or (SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION WHERE DAT_RELANCE_REGLE_2 IS NOT NULL)  > 0) 
         			BEGIN
         				SET @relance = 3
         			END
         		ELSE
         			BEGIN
         				IF ((SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO WHERE DAT_RELANCE_REGLE_1 IS NOT NULL)  > 0 or (SELECT COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION WHERE DAT_RELANCE_REGLE_1 IS NOT NULL)  > 0)
         					BEGIN
         						SET @relance = 2
         					END
         			END;
         
         	/*****  Creation du flux XML *****************************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_RELANCE_REGLEMENT_CONTRAT_PRO_OF'
         	)
         	/**********************************************************************************************************/
         			
         	SELECT
         			(
         				SELECT @relance
         				FOR XML RAW('NUM_RELANCE'), ELEMENTS, TYPE
         			),
         			(
         				SELECT  case when @relance=1 then 'Šre' else 'Šme'  end
         				FOR XML RAW('niŠme'), ELEMENTS, TYPE
         			),
         			(
         				/**********************************************************************************************/
         				/*****************	ENTETE DE LA LETTRE *******************************************************/
         				/**********************************************************************************************/
         				SELECT	              	
         					-- R‚cup‚ration des informations sur l'agence
         					dbo.GetXmlAgenceContact(ENTETE.ID_AGENCE) as EMETTEUR,
         					
         					-- R‚cup‚ration des informations sur le contact
         					dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,
         
         					/******************* Recuperation des informations DE l'entete ****************************/
         					(
         						SELECT	REFERENCE.COD_ADHERENT,
         								REFERENCE.LIB_VILLE,
         								dbo.GetFullDate(getDate()) as DATE,
         								(
         									SELECT	TOP 1 COD_OF
         									FROM #OF
         									FOR XML PATH(''), TYPE
         								),						
         								(
         									SELECT	#TMP_REGLEMENT_CONTRAT_PRO.ID_CONTRAT_PRO
         									FROM	#TMP_REGLEMENT_CONTRAT_PRO
         									FOR XML PATH(''), TYPE 
         								),
         								(
         									SELECT	top 1
         											dbo.GetContactSalutationOF(@ID_CONTACT, 1)
         									FROM CIVILITE
         									FOR XML PATH('POLITESSE_HAUT'), TYPE
         								)
         
         						FROM #TMP_REGLEMENT_CONTRAT_PRO AS REFERENCE     
         						FOR XML AUTO, ELEMENTS, TYPE
         					)
         				FROM #TMP_REGLEMENT_CONTRAT_PRO AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				/**********************************************************************************************/
         				/*****************	CORPS DE LA LETTRE ********************************************************/
         				/**********************************************************************************************/
         				SELECT	CORPS.ID_CONTRAT_PRO,
         						CORPS.PRENOM_INDIVIDU,
         						CORPS.NOM_INDIVIDU,
         						CORPS.DAT_DEBUT,
         						CORPS.DAT_FIN,
         						CORPS.LIB_LIEU_FORMATION,
         						CASE WHEN @relance = 3 THEN(
         							SELECT 'Sans r‚ponse de votre part sous quinzaine nous cl“turerons ce dossier.'
         							FOR XML PATH('PREVENTION'), TYPE 
         						)END ,
         				/************************************************************************************************/
         				/*****************	PIECES MODULES *************************************************************/
         				/**********************************************************************************************/
         							CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO ) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													--#TMP_REGLEMENT_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBL_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBC_PIECE_PRO
         									FROM		#TMP_REGLEMENT_PIECES_MODULE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_MODULE_PRO.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_MODULE_PRO.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.COD_MODULE_PRO, 
         													--#TMP_REGLEMENT_PIECES_MODULE_PRO.LIB_RAISON_SOCIALE,
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBL_MODULE_PRO, 
         													#TMP_REGLEMENT_PIECES_MODULE_PRO.LIBC_PIECE_PRO,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBC_MOTIF_NON_CONFORM_PIECE_PRO
         									FROM    #TMP_REGLEMENT_PIECES_MODULE_PRO
         											INNER JOIN NR410 ON #TMP_REGLEMENT_PIECES_MODULE_PRO.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         											INNER JOIN MOTIF_NON_CONFORM_PIECE_PRO ON NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_MODULE_PRO.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML RAW('TABLEAU_MODULE'),ELEMENTS, TYPE
         						)END,
         				/************************************************************************************************/
         				/*****************	PIECES SESSION *************************************************************/
         				/**********************************************************************************************/
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION) > 0 and (SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_MODULE_PRO) > 0) THEN(
         							SELECT 'Et pour les sessions  suivantes :'
         							FOR XML PATH('SUITE_SESSION'), TYPE 
         						)END ,
         						CASE WHEN ((SELECT  COUNT(*) FROM #TMP_REGLEMENT_PIECES_SESSION) > 0) THEN (
         							SELECT 
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_SESSION.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_SESSION.NB_UNITE_TOTALE,
         												#TMP_REGLEMENT_PIECES_SESSION.COD_SESSION_PRO,
         													#TMP_REGLEMENT_PIECES_SESSION.LIB_RAISON_SOCIALE,
         													 Case when #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE <>'' or #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE is not  null
         													then #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE else '' end as NUM_FACTURE,
         													#TMP_REGLEMENT_PIECES_SESSION.LIBL_PIECE_PRO													
         													
         									FROM			#TMP_REGLEMENT_PIECES_SESSION
         									WHERE			#TMP_REGLEMENT_PIECES_SESSION.BLN_ACTIF = 0 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_MANQUANTE'), ELEMENTS, TYPE, ROOT('PIECES_MANQUANTES')
         								),
         								(
         									SELECT DISTINCT	#TMP_REGLEMENT_PIECES_SESSION.DAT_DEBUT,
         													#TMP_REGLEMENT_PIECES_SESSION.NB_UNITE_TOTALE,
         													#TMP_REGLEMENT_PIECES_SESSION.COD_SESSION_PRO,
         													#TMP_REGLEMENT_PIECES_SESSION.LIB_RAISON_SOCIALE,
         													 Case when #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE <>'' or #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE is not  null
         													then #TMP_REGLEMENT_PIECES_SESSION.NUM_FACTURE else '' end as NUM_FACTURE,
         													#TMP_REGLEMENT_PIECES_SESSION.LIBL_PIECE_PRO,
         													MOTIF_NON_CONFORM_PIECE_PRO.LIBC_MOTIF_NON_CONFORM_PIECE_PRO
         
         									FROM    #TMP_REGLEMENT_PIECES_SESSION
         											INNER JOIN NR410 ON #TMP_REGLEMENT_PIECES_SESSION.ID_ARRIVEE_PIECE_PRO = NR410.ID_ARRIVEE_PIECE_PRO
         											INNER JOIN MOTIF_NON_CONFORM_PIECE_PRO ON NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = MOTIF_NON_CONFORM_PIECE_PRO.ID_MOTIF_NON_CONFORM_PIECE_PRO
         									WHERE		#TMP_REGLEMENT_PIECES_SESSION.BLN_ACTIF = 1 --CELUI DE ARRIVEE_PIECE_PRO
         									FOR XML RAW('PIECE_NON_CONFORME'), ELEMENTS, TYPE, ROOT('PIECES_NON_CONFORMES')
         								)
         							FOR XML RAW('TABLEAU_SESSION'),ELEMENTS, TYPE
         						)END,
         						(
         							SELECT	top 1 dbo.GetContactSalutationOF(@ID_CONTACT, 0)
         							FROM CIVILITE
         							FOR XML PATH('POLITESSE_BAS'), TYPE
         						)
         				FROM #TMP_REGLEMENT_CONTRAT_PRO AS CORPS     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				/**********************************************************************************************/
         				/*****************	SIGNATURE DE LA LETTRE ****************************************************/
         				/**********************************************************************************************/
         				SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TMP_REGLEMENT_CONTRAT_PRO as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         			/**************************************************************************************************/
         
         	FROM	#TMP_REGLEMENT_CONTRAT_PRO as LETTRE
         	FOR XML AUTO, ELEMENTS
         END
GO

         -- =============================================
         -- Author	: XX
         -- Date		: XX XXXX 2007
         -- Comment	: Cr‚ation
         -- =============================================
         -- Author	: SV
         -- Date		: 28 ao–t 2007
         -- Comment	: Suppression de la v‚rification sur la date d'edition de la lettre de remboursement de salaire du module
         --					--> Fait lors de la g‚n‚ration de la liste des potentiels
         --				  Mise en place d'une jointure externe sur l'organisme de formation
         --					--> Cas de la formation interne
         --				  Modification du flux X.M.L.
         --					--> Simplification du tag <TITRE_TABLEAU_STAGE>
         --						* Avant : <TITRE_TABLEAU_STAGE><ADHERENT><COD_ADHERENT/><SESSION_PEC><COD_SESSION_PEC/></SESSION_PEC></ADHERENT></TITRE_TABLEAU_STAGE>
         --						* AprŠs : <TITRE_TABLEAU_STAGE><COD_ADHERENT/><COD_SESSION_PEC/></TITRE_TABLEAU_STAGE>
         --					--> Suppression du tag <STG_COD_SESSION_PEC> du tag <TABLEAU_STAGE>
         --					-->Ajout du sexe du stagiaire dans le tag <TABLEAU_STAGE>
         --						* balise <STG_SEXE> avec la valeur M ou F
         --				  Ajout d'un filtre sur la session pec des stagiaires pec pour ‚viter les d‚duplications lorsqu'un module contient plusieurs session
         --				  Simplification de la requˆte qui g‚nŠre le flux X.M.L.
         --					--> Aucun besoin de r‚p‚ter les requˆtes sur les jointures g‚r‚es par la requˆte principale
         -- =============================================
         -- Author	: SV
         -- Date		: 30 ao–t 2007
         -- Comment	: Modification de la valeur retourn‚e dans la balise <STG_SEXE> de <TABLEAU_STAGE>
         --					--> La valeur 'M' est remplac‚e par 'H'
         -- =============================================
         -- Author	: SV
         -- Date		: 30 ao–t 2007
         -- Comment	: Ajout des valeurs suivantes dans les informations des stagiaires du tag <TABLEAU_STAGE>
         --					-->* Ajout de la date de naissance dans le tag <STG_DATE_NAISSANCE>
         --					-->* Ajout du C.S.P. dans le tag <STG_CSP>
         --					-->* Ajout du type de contrat dans le tag <STG_TYPE_CONTRAT>
         --					-->* Ajout de la dur‚e du travail dans le tag <STG_DUREE_TRAVAIL>
         -- =============================================
         -- Author	: SV
         -- Date		: 12 octobre 2007
         -- Comment	: Mise en place d'une comparaison avec unlike sur le code de la session
         --					Utilisation de l'ensemble des ‚tablissement d'un adh‚rent et non plus uniquement son ‚tablissement principal
         -- =============================================
         -- Author	: SV
         -- Date		: 13 octobre 2007
         -- Comment	: Modification de taille du paramŠtre du code session de 10 … 50 caractŠres
         -- =============================================
         -- Author	: SV
         -- Date		: 15 octobre 2007
         -- Comment	: Utilisation l'identifiant de l'adh‚rent d'un ‚tablissement pour le joindre au stagiaire plut“t que de ne se bas‚ que sur l'‚tablissement pass‚ en paramŠtre qui est l'‚tablissement principal de l'adh‚rent
         -- =============================================
         -- Author	: SBR
         -- Date		: 28/05/2008
         -- Comment	: La partie Emetteur est renseign‚e … partir de la fonction GetXmlAdrChargeRelation (au lieu de GetXmlAgenceContact)
         -- =============================================
         -- Author	: AMA
         -- Date		: 18/07/2008
         -- Comment	: Adaptation … la matrice C2P
         -- =============================================
         -- 26/12/08 par SBR - correction anomalie filtre sur ‚tablissement OF principal
         -- =============================================
         -- 06/03/09 par SBR - adaptation gabarit suite groupe de travail sur les ‚ditions
         -- =============================================
         -- 30/01/12 par SBR - Filtre sur l'‚tablissement et non plus sur l'adh‚rent.
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_REMBOURSEMENT_SALAIRE]
         (
         	@ID_ETABLISSEMENT		int,
         	@ID_BENEFICIAIRE		int,
         	@TYPE_BENEFICIAIRE		int,
         	@ID_ADRESSE				int,
         	@ID_CONTACT				int,
         	@_COD_MODULE_PEC		varchar(50),
         	@_ID_ADHERENT			int
         )
         AS
         --AJout
         	DECLARE @SalaireHoraireBrut		decimal(18,2)
         	DECLARE @NbHeureSurTT			decimal(18,2)
         	DECLARE @TotalSalaireEtCharge	decimal(18,2)
         	DECLARE @NbHeureHorsTT			decimal(18,2)
         	DECLARE @SalaireHoraireCharge	decimal(18,2)
         	DECLARE @DemiSalaireHoraireNet	decimal(18,2)
         	DECLARE @TotalAllocationFormation decimal(18,2)
         
         
         	-- Contact principal par d‚faut mais pas de "."
         	IF @ID_CONTACT IS NULL
         	SELECT @ID_CONTACT = NR31.ID_CONTACT
         	FROM NR31
         		INNER JOIN CONTACT ON CONTACT.ID_CONTACT = NR31.ID_CONTACT
         	WHERE BLN_PRINCIPAL = 1
         		AND BLN_ACTIF = 1
         		AND ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         		AND CONTACT.LIB_NOM_CONTACT <> '.';
         
         -- Pr‚paration
         	-- Modification de la session pec pour indiquer que la lettre de remboursement de salaire est ‚dit‚e
         	UPDATE
         		SESSION_PEC
         	SET
         		DAT_LETTRE_REMBOURSEMENT_SALAIRE = convert(datetime, '31/12/9999', 103)
         	WHERE 
         		ID_MODULE_PEC IN (SELECT ID_MODULE_PEC FROM MODULE_PEC where COD_MODULE_PEC = @_COD_MODULE_PEC);
         
         
         -- XML Generation
         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_REMBOURSEMENT_SALAIRE'
         	)
         
         	SELECT
         
         			dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,
         
         			-- ENTETE
         			(
         				SELECT
         					ADHERENT.COD_ADHERENT				as COD_ADHERENT,
         					CR.LIB_PNM							as LIB_PRENOM_CHARGE_RELATION,
         					CR.LIB_NOM							as LIB_NOM_CHARGE_RELATION,
         					CR.EMAIL,
         					-- Recuperation ‚metteur
         					dbo.GetXmlAdrChargeRelation(ETABLISSEMENT.ID_ETABLISSEMENT)	as EMETTEUR,
         					rtrim(case when patindex('%CEDEX%', CR.LIB_VILLE) <> 0 then left(CR.LIB_VILLE, patindex('%CEDEX%', CR.LIB_VILLE)-1) else CR.LIB_VILLE end) as LIB_VILLE,
         					dbo.GetFullDate(getdate())			as DATE,
         
         					(SELECT top 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
         					 FROM	CIVILITE
         					 FOR XML PATH('POLITESSE_HAUT'), TYPE
         					),
         
         					(SELECT top 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
         					 FROM	CIVILITE
         					 FOR XML PATH('POLITESSE_BAS'), TYPE
         					)
         				FOR XML RAW('ENTETE'), ELEMENTS, TYPE
         			),
         
         			-- R‚cup‚ration du pr‚nom et du nom … mettre en signature
         			(
         				SELECT
         					CM.LIB_PNM		as LIB_PNM_CONSEILLER,
         					CM.LIB_NOM		as LIB_NOM_CONSEILLER
         				FOR XML RAW('SIGNATURE'), ELEMENTS, TYPE
         			),
         						
         			-- Tableau
         			--Zone de titre
         			(
         				SELECT
         					ADHERENT.COD_ADHERENT as COD_ADHERENT_TABLEAU,
         					SESSION_PEC.COD_SESSION_PEC	as COD_SESSION_PEC_TABLEAU,					
         					CM.LIB_PNM + ' ' + CM.LIB_NOM as SUIVI_PAR,
         					dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE_TABLEAU,
         					dbo.GetXmlAdrChargeRelation(ETABLISSEMENT.ID_ETABLISSEMENT)as EMETTEUR_TABLEAU
         					--ADHERENT.COD_ADHERENT		as COD_ADHERENT,
         					--SESSION_PEC.COD_SESSION_PEC	as COD_SESSION_PEC
         				FOR XML RAW(''), ELEMENTS, TYPE, ROOT('TITRE_TABLEAU_STAGE')
         			),	
         			--Zone de date
         			(
         				SELECT
         					MODULE_PEC.LIBL_MODULE_PEC	as LIBELLE_SESSION,
         					CAST(MODULE_PEC.NUM_DUREE_HEURE AS decimal(10,1)) as NB_HEURE_MODULE,
         					dbo.GetShortDate(SESSION_PEC.DAT_DEBUT) as DAT_DEBUT_MODULE,
         					dbo.GetShortDate(MODULE_PEC.DAT_FIN) as DAT_FIN_MODULE,
         					dbo.GetShortDate(SESSION_PEC.DAT_DEBUT) as DAT_DEBUT_SESSION,
         					dbo.GetShortDate(SESSION_PEC.DAT_FIN) as DAT_FIN_SESSION,					
         					CAST(SESSION_PEC.NUM_DUREE_HEURE AS decimal(10,1)) as DUREE_HEURE_SESSION
         					
         				FOR XML RAW(''), ELEMENTS, TYPE, ROOT('DATES_TABLEAU_STAGE')
         			),
         			(
         				
         				SELECT 										
         					dbo.GetXmlRemunerationAndAllocation(INDIVIDU.NOM_INDIVIDU, INDIVIDU.PRENOM_INDIVIDU, STAGIAIRE_PEC.ID_STAGIAIRE_PEC)
         					
         				FROM
         					STAGIAIRE_PEC
         				JOIN 
         					ETABLISSEMENT
         				ON	ETABLISSEMENT.ID_ETABLISSEMENT = STAGIAIRE_PEC.ID_ETABLISSEMENT
         				AND ETABLISSEMENT.ID_ADHERENT = @_ID_ADHERENT
         				JOIN 
         					INDIVIDU
         				ON	INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				WHERE 
         					STAGIAIRE_PEC.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         					--AND STAGIAIRE_PEC.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         				FOR XML RAW('TABLEAU_STAGE'), ELEMENTS, TYPE
         			),
         			(
         				select dbo.GetXmlRemunerationAndAllocationCumul(SESSION_PEC.ID_SESSION_PEC)				
         				FOR XML RAW(''), ELEMENTS, TYPE, ROOT('PIED_TABLEAU_STAGE')
         			)
         	FROM
         		ADHERENT
         	join 
         		etablissement
         	on	etablissement.id_adherent = adherent.id_adherent
         	JOIN 
         		NR140
         	ON	NR140.ID_ETABLISSEMENT = etablissement.id_etablissement
         	JOIN 
         		ACTION_PEC
         	ON	NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC	
         	JOIN 
         		MODULE_PEC
         	ON	MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         	LEFT JOIN 
         		ETABLISSEMENT_OF
         	ON	MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	JOIN 
         		SESSION_PEC
         	ON	SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         	JOIN 
         		ADRESSE
         	ON	ADHERENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         	left join
         			utilisateur CR -- charg‚ de relation ou responsable des actions collectives
         	on		case when (ACTION_PEC.cible_action = 1 or ACTION_PEC.bln_reprise_adhoc = 1)
         				 then ETABLISSEMENT.id_chargee_relation
         				 else ACTION_PEC.id_chargee_mission 
         			end = CR.id_utilisateur
         	left join
         			utilisateur CM -- charg‚ de mission ou responsable des actions collectives
         	on		case when (ACTION_PEC.cible_action = 1 or ACTION_PEC.bln_reprise_adhoc = 1)
         				 then ETABLISSEMENT.id_chargee_mission
         				 else ACTION_PEC.id_chargee_mission
         			end = CM.id_utilisateur
         	WHERE	--SESSION_PEC.COD_SESSION_PEC like '%' + @_COD_SESSION_PEC
         	SESSION_PEC.ID_MODULE_PEC IN (SELECT ID_MODULE_PEC FROM MODULE_PEC where COD_MODULE_PEC = @_COD_MODULE_PEC)  
         	AND		coalesce(SESSION_PEC.DAT_LETTRE_REMBOURSEMENT_SALAIRE, convert(datetime, '31/12/9999', 103)) = convert(datetime, '31/12/9999', 103)
         
         	AND		NR140.ID_ETABLISSEMENT = @ID_ETABLISSEMENT -- SBR le 30/01/12
         	FOR XML RAW('LETTRE'), ELEMENTS
GO
 CREATE PROCEDURE [dbo].[UPD_PIECES_STAGIAIRE]
          @ID_MODULE    INT,
          @ID_STAGIAIRE   INT,
          @ID_PIECE    INT,
          @BLN_CONFORME   INT,
          @BLN_ACTIF    INT,
          @ID_ARRIVEE_PIECE_PEC INT OUTPUT,
          @ID_SESSION    INT,
          @ID_DISPOSITIF   INT,
          @ID_ADHERENT   INT,
          @NUM_FILE    SMALLINT,
          @NOM_FICHIER   VARCHAR(100),
          @NUM_LOT    VARCHAR(17) 
         AS 
         -- =============================================
         -- Author:  xxx
         -- Create date: xx xxx 2007
         -- Description: update/insert des piÇùces stagiaires pour un module ou une session
         -- ---------------------------------------------
         -- Author:  SAY
         -- Modif. date: 20 juin 2007
         -- Description: ajout pr la prise en charge de la session
         -- ---------------------------------------------
         -- Author  : SAY
         -- Modified date: 29 aout 2007
         -- comment  : # correction sur le comptage des UNITE_STAGIAIRE afin de diff‚rencier le cas session / le cas module 
         -- =============================================
         -- Author:  ASD-SAF
         -- Create date: 23/12/2010
         -- Description: 12550Remplacement du calcul @ID_DISPOSITIF, par paramŠtre
         -- =============================================
         -- Author:  SAF
         -- Create date: 30/12/2010
         -- Description: 12550 SET @ID_ARRIVEE_PIECE_PEC = NULL IF < 0
         -- =============================================
         -- Author:  SAF
         -- Create date: 07/04/2011
         -- Description: 12559 SAVE ONLY THE PIECES NO CONFORM AND NO PRESENT
         -- Ajouter un parametre pour id_adherent
         -- =============================================
         -- Author:  SAF
         -- Create date: 20/04/2011 
         -- Description: 12710 : Ajout de suprission des pieces conform et present 
         -- Si le dispositif concern‚ pas de heur engag‚
         -- =============================================
         -- DSZ 03/10/2012 14046
         -- gerer les nulls possibles dans la partie SELECT @ID_ARRIVEE_PIECE_PEC
         -- =============================================
         -- ASD 15/10/2012 14046
         -- erreur de copy paste
         -- =============================================
         -- DSZ 03/12/2013 16499 ajout @NOM_FICHIER et @NUM_LOT
         -- ============================================= 
         BEGIN
          IF (@ID_ARRIVEE_PIECE_PEC <= 0)
          BEGIN
           SET @ID_ARRIVEE_PIECE_PEC = NULL
          END
         
          IF (@ID_SESSION <= 0)
          BEGIN
           SET @ID_SESSION = NULL
          END
         
         
          IF (@ID_DISPOSITIF <= 0)
          BEGIN
           SET @ID_DISPOSITIF = NULL
          END
         
          IF (@ID_ADHERENT <= 0)
          BEGIN
           SET @ID_ADHERENT = NULL
          END
         
          DECLARE @UserId INT
          SELECT
           @UserId = ID_UTILISATEUR
          FROM
           UTILISATEUR
          WHERE
           COD_util = 'ADMIN_WEB'
          
          IF exists (SELECT 1 FROM UNITE_STAGIAIRE
             WHERE
              ID_STAGIAIRE_PEC = @ID_STAGIAIRE
              AND
              (
               ID_DISPOSITIF = @ID_DISPOSITIF
               OR @ID_DISPOSITIF IS NULL
              )
              AND
              (
               (
                NB_HEURE_REGLE > 0
                AND @ID_SESSION is not null
               )
               OR
               (
                NB_HEURE_ENGAGE > 0
                AND
                (
                 @ID_SESSION is null
                 OR @ID_SESSION = 0
                )
               )
              )
            )
          BEGIN -- Save only if it there is a unite stagiare for that dispositif 
             -- or if the piece doesn't depend on dispositifs
           IF (@BLN_CONFORME IS NULL)
           BEGIN
            SET @BLN_CONFORME = 0
           END
         
           IF (@BLN_ACTIF IS NULL)
           BEGIN
            SET @BLN_ACTIF = 0
           END
         
           DECLARE @NUMREG INT = 0
           
           IF @ID_ARRIVEE_PIECE_PEC IS NULL
           BEGIN
            SELECT
             @ID_ARRIVEE_PIECE_PEC = ID_ARRIVEE_PIECE_PEC 
            FROM
             ARRIVEE_PIECE_PEC 
            WHERE
             ID_PIECE_PEC  = @ID_PIECE
             AND isnull(ID_MODULE_PEC,0)  = isnull(@ID_MODULE,0)
             AND isnull(ID_STAGIAIRE_PEC,0) = isnull(@ID_STAGIAIRE, 0)
             AND isnull(ID_ADHERENT,0)  = isnull(@ID_ADHERENT, 0)
           END
         
           IF((@BLN_CONFORME = 0 OR @BLN_ACTIF = 0 or @NUM_FILE>0)) -- Insert only when no conform or no present) 
           BEGIN
            IF (@ID_ARRIVEE_PIECE_PEC IS NULL)
            BEGIN
             INSERT INTO ARRIVEE_PIECE_PEC 
             (
              COD_ARRIVEE_PIECE_PEC,
              DAT_ARRIVEE_PIECE_PEC,
              BLN_ACTIF,
              BLN_CONFORME,
              ID_MODULE_PEC,
              ID_PIECE_PEC,
              ID_STAGIAIRE_PEC, 
              ID_DISPOSITIF,
              ID_SESSION_PEC,
              ID_ADHERENT,
              NUM_FILE,
              NOM_FICHIER,
              NUM_LOT,
              ID_UTILISATEUR
             )
             VALUES 
             (
              0,
              GETDATE(),
              @BLN_ACTIF,
              @BLN_CONFORME,
              @ID_MODULE,
              @ID_PIECE,
              @ID_STAGIAIRE,
              @ID_DISPOSITIF,
              @ID_SESSION,
              @ID_ADHERENT,
              @NUM_FILE,
              @NOM_FICHIER,
              @NUM_LOT,
              @UserId
             ) 
               
             UPDATE
              ARRIVEE_PIECE_PEC
             SET
              COD_ARRIVEE_PIECE_PEC = @@IDENTITY
             WHERE
              ID_ARRIVEE_PIECE_PEC = @@IDENTITY
         
             SET @ID_ARRIVEE_PIECE_PEC = @@IDENTITY
            END
            ELSE
            BEGIN
             UPDATE
              ARRIVEE_PIECE_PEC 
             SET
              BLN_ACTIF  = @BLN_ACTIF,
              BLN_CONFORME = @BLN_CONFORME,
              NUM_FILE  = @NUM_FILE,
              NUM_LOT   = @NUM_LOT,
              NOM_FICHIER  = @NOM_FICHIER,
              ID_UTILISATEUR = @UserId
             WHERE
              ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
            END
           END
           ELSE
           BEGIN
            IF(@ID_ARRIVEE_PIECE_PEC IS NOT NULL)
            BEGIN
             DELETE FROM NR210
             WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
         
             DELETE FROM ARRIVEE_PIECE_PEC
             WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC 
            END
           END
           -- UPDATE MODULE_PEC BLN_OK_PIECE
           IF (@ID_SESSION IS NULL)-- OR @ID_SESSION = 0) SAFI 03/12/2010
           BEGIN
            SELECT
             @NUMREG = COUNT(*)
            FROM
             ARRIVEE_PIECE_PEC
             INNER JOIN PIECE_PEC
              ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
               AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
               AND (ARRIVEE_PIECE_PEC.BLN_ACTIF = 0 OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0)
            WHERE
             ARRIVEE_PIECE_PEC.ID_MODULE_PEC = @ID_MODULE
             AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC is null
         
            IF (@NUMREG = 0)
            BEGIN
             UPDATE
              MODULE_PEC
             SET
              BLN_OK_PIECE = 1
             WHERE
              ID_MODULE_PEC = @ID_MODULE
            END
            ELSE
            BEGIN
             UPDATE
              MODULE_PEC
             SET
              BLN_OK_PIECE = 0
             WHERE
              ID_MODULE_PEC = @ID_MODULE
            END
           END
          END
          ELSE
          BEGIN
           IF(@ID_ARRIVEE_PIECE_PEC IS NOT NULL AND @BLN_CONFORME = 1 AND @BLN_ACTIF = 1)   
           BEGIN
            DELETE FROM NR210
            WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
         
            DELETE FROM ARRIVEE_PIECE_PEC
            WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC 
           END
          END
         END
GO

         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_DOSSIERS_FACTURABLES]
         /*
         -- =======================================================================================================================================
         -- Author:		DSZ
         -- Create date: 20/08/2010
         -- Description:	Lettre PEC dossiers facturables evol 12421
         -- C2P_SFD_PEC_EDITION_DOSSIERS_FACTURABLES_1.2.doc du 28/07/2010
         -- Plus les modifs de MHBM du 19/08/2010
         -- =======================================================================================================================================
         -- SAFI : 12421 : 27/08/2010
         -- Description : Put 0 incase of null using ISNULL
         -- =======================================================================================================================================
         -- SAFI : 12421 : 31/08/2010
         -- Description : Add the Headings and details of 
         -- Pave 5,6 et 7 also in XML
         -- =======================================================================================================================================
         -- DSZ 13/09/10 12481
         -- ajout order By aux paves 5 et 6
         -- nb_heures passe en decimal
         -- =======================================================================================================================================
         -- DSZ 14/09/2010 12481
         -- nnb heure passe en vrai decimal (18,2) 
         -- format dates sans siecle
         -- cosmetique!
         -- =======================================================================================================================================
         -- DSZ 20/09/2010 retours tests recette sur v1.0.15.10
         -- 12499 : changement titre pave 6
         -- 12495 : modules sans types : ajout gestion @MONTANT_D a la creation de #liste_typee
         -- =======================================================================================================================================
         -- ASD 20/09/2010 retours tests recette sur v1.0.15.10
         -- 12496 : correc calcul nb h
         -- 12500 : ordre de tri d'affichage
         -- =======================================================================================================================================
         -- DSZ 21/09/2010 12501 :  	 La fonction du destinataire supprim‚
         -- ajout ID_CONTACT aux parametres
         -- modif gestion @MONTANT_D uniquement pour les dossiers type D
         -- ajout gestion parametre MNT_MIN pour tous les dossiers
         -- =======================================================================================================================================
         -- DSZ 22/09/2010 : 12501 EVOL de MHBM si pas de contact dans la transaction, on prend le contact principal
         -- =============================================
         -- SAFI 24/09/2010 : 12505 Merge all the 3 coloumns of PAVE_1 by one coloumn 
         -- =======================================================================================================================================
         -- ASD 30/09/2010 12495 : exclusion compl‚mentaire des modules > mnt_min
         -- lorsque < montant_D avec date fin module - duree_C > aujourd'hui
         -- + limitation des piŠces manquantes aux modules r‚ellement affich‚s (lien avec 12495)
         -- + ‚limination des doublons de piŠces manquantes
         -- =======================================================================================================================================
         -- DSZ 01/10/2010 : 12511 ajout raison de NC Mantis 
         -- =======================================================================================================================================
         -- DSZ 08/10/2010 : 12513 ajout info sur pieces manquantes stagiaire
         -- =======================================================================================================================================
         -- ASD 14/01/2011 : 12610 enlever d'autres sous types de couts pour les dossiers subrog‚s : 
         --					remplacer @STC_CP par un tableau/une liste de STC_EXCLUS
         -- =======================================================================================================================================
         -- ASD 20/03/2012 : 13335 : m‚nage de vieux commentaires et ajout de commentaires d‚crivant l'algo
         -- 					plus correction d'une jointure sur PCR et MODULE au lieu de PCR et SESSION 
         --					plus suppression d'une jointure inutile
         -- =======================================================================================================================================
         -- DSZ 26/03/2012 : 13335 : correction de condition de date avec @PARAM_DUREE_C ;
         -- =======================================================================================================================================
         -- SLAH 01/06/2012 : 13531 : BBL-Modification libelle OPCA 
         -- =======================================================================================================================================
         -- DSZ 20/09/2012 : 13697 : num tel dynamique
         -- =======================================================================================================================================
         -- DSZ 01/03/2013 : 14979 : ajout ANNULATION_CREANCES
         -- =======================================================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================
         -- LDE/OPA 23/05/2014 : #213 En tant qu'utilisateur OPTIFORM, 
         -- lorsque j'‚dite un courrier (PEC, PRO) … destination d'un Adh‚rent ou d'un OF, je veux que, 
         -- l'adresse … afficher dans la zone "correspondance" soit l'adresse TSA propre … ce type de courrier 
         -- si le mode "TSA" s'applique sinon qu'elle soit l'adresse actuelle
         -- =======================================================================================================================================
         -- Author:		MBL
         -- Modif. date: 21/10/2015
         -- Description:	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         -- =======================================================================================================================================
         */
         	@ID_BENEFICIAIRE INT,
         	@TYPE_BENEFICIAIRE INT,
         	@ID_ADRESSE INT,
         	@ID_CONTACT INT
         WITH RECOMPILE
         AS
         BEGIN
         	
         	DECLARE @ROW_COUNT_PAVE_6 INT
         	DECLARE @ROW_COUNT_PAVE_7 INT
         	DECLARE @ROW_COUNT_PAVE_5 INT
         	DECLARE @FAF_NAME VARCHAR(100)
         	SELECT @FAF_NAME = FAF_NAME FROM PARAMETRES	
         
         	-- Rajout MBL du 21/10/2015 :	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         	DECLARE @NUM_ANNEE_EN_COURS int
         	SELECT @NUM_ANNEE_EN_COURS  = NUM_ANNEE
         	FROM PERIODE
         	WHERE ID_TYPE_PERIODE = 1
         	AND BLN_EN_COURS = 1
         	
         	/**** R‚cup‚ration des infos pour la partie r‚f‚rence ****/
         	SELECT	ADHERENT.COD_ADHERENT,
         			ETABLISSEMENT.NUM_SIRET,			
         			CM.LIB_NOM			AS LIB_NOM_CONSEILLER,
         			CM.LIB_PNM			AS LIB_PNM_CONSEILLER,
         			CR.ID_UTILISATEUR	AS ID_UTIL,
         			CR.LIB_PNM			AS LIB_PRENOM_CHARGE_RELATION,
         			CR.LIB_NOM			AS LIB_NOM_CHARGE_RELATION,
         			CR.LIB_VILLE,
         			CR.EMAIL			AS EMAIL_CHARGE_RELATION,
         			CR.NUM_TEL          AS TEL_CHARGE_RELATION,
         			ADHERENT.LIB_RAISON_SOCIALE,
         			ADRESSE.LIB_VIL_CEDEX AS VILLE
         	INTO	#TEMP_REFERENCE
         	FROM	ADHERENT
         	JOIN	ETABLISSEMENT	
         	ON		ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	JOIN	ADRESSE
         	ON		ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         	LEFT JOIN
         			UTILISATEUR CR -- charg‚ de relation
         	on		ETABLISSEMENT.id_chargee_relation = CR.id_utilisateur
         	LEFT JOIN
         			UTILISATEUR CM -- charg‚ de mission
         	on		ETABLISSEMENT.id_chargee_mission = CM.id_utilisateur
         	WHERE	ETABLISSEMENT.ID_ETABLISSEMENT = @ID_BENEFICIAIRE;
         
         
         	DECLARE @ID_REF_UTIL int
         	SELECT @ID_REF_UTIL = ID_UTIL FROM #TEMP_REFERENCE;
         
         	DECLARE @ID_TYPE_TVA int
         	SELECT @ID_TYPE_TVA = ETABLISSEMENT.ID_TYPE_TVA   FROM  ETABLISSEMENT 
         	WHERE	ETABLISSEMENT.ID_ETABLISSEMENT = @ID_BENEFICIAIRE;
         	
         	DECLARE @ID_DOCUMENT int	
         	SELECT @ID_DOCUMENT = ID_DOCUMENT
         	FROM [DOCUMENT]
         	WHERE COD_DOCUMENT = 'LET_PEC_DOSFACT'
         
         
         	-----------R‚cup‚ration des params dans PARAM_EDITION_PEC
         	DECLARE @PARAM_DUREE_A INT
         	DECLARE @PARAM_DUREE_B INT
         	DECLARE @PARAM_DUREE_C INT
         	DECLARE @PARAM_MNT_D DECIMAL(18,2)
         	DECLARE @PARAM_MNT_MIN DECIMAL (18,2)
         	DECLARE @ANNUL_CREANCES VARCHAR(7)
         	DECLARE @CHAINE AS VARCHAR(50)
         	DECLARE @SEP AS VARCHAR (2)
         	SET @SEP = ','
         	
         	SELECT 
         			@PARAM_DUREE_A	= DUREE_A,
         			@PARAM_DUREE_B	= DUREE_B,
         			@PARAM_DUREE_C	= DUREE_C,
         			@PARAM_MNT_D	= MONTANT_D,
         			@PARAM_MNT_MIN	= MNT_MIN,
         			@CHAINE			= STC_EXCLUS, --des sous types de co–ts … exclure dans PARAM_EDITION_PEC
         			@ANNUL_CREANCES = CAST(ROUND(ANNULATION_CREANCES/30,0) AS VARCHAR(2))+' mois'
         	FROM dbo.PARAM_EDITION_PEC
         	WHERE ID_DOCUMENT = @ID_DOCUMENT
         	
         	SELECT CAST(DATA AS INTEGER) AS DATA INTO #LIST_STC_A_EXCLURE FROM F_SPLIT( @CHAINE, @SEP)
         
         
         	IF @ID_CONTACT IS NULL
         		SELECT @ID_CONTACT = ID_CONTACT FROM dbo.NR31 
         		WHERE NR31.ID_ETABLISSEMENT = @ID_BENEFICIAIRE
         		AND NR31.BLN_ACTIF = 1 AND NR31.BLN_PRINCIPAL = 1
         
         	/****  R‚cup‚ration des infos pour la partie adh‚rent ****/
         	SELECT DISTINCT	ADHERENT.COD_ADHERENT,
         			AGENCE.ID_AGENCE,
         			AGENCE.COD_POSTAL,
         			AGENCE.LIB_VILLE,
         			AGENCE.LIB_NOM_CONSEILLER,
         			AGENCE.LIB_PNM_CONSEILLER
         	INTO	#TEMP_ADHERENT
         	FROM	ADHERENT
         			INNER JOIN AGENCE			ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         			INNER JOIN ETABLISSEMENT	ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	WHERE	(ETABLISSEMENT.ID_ETABLISSEMENT = @ID_BENEFICIAIRE);
         
         
         	/**** END R‚cup‚ration des infos pour la partie r‚f‚rence ****/
         
         	/************ TABLEAUX page 2************/
         
         	-----------Liste des modules qui peuvent ˆtre concern‚s (sans v‚rifier ici s'ils sont engag‚s)
         
         	SELECT 
         		MODULE_PEC.ID_MODULE_PEC AS ID_MODULE_PEC, 
         		MODULE_PEC.DAT_FIN AS DAT_FIN, 
         		STAGIAIRE_PEC.ID_STAGIAIRE_PEC, 
         		STAGIAIRE_PEC.ID_INDIVIDU, 
         		STAGIAIRE_PEC.ID_ETABLISSEMENT 
         	INTO #LISTMODULE_ETAB_STAGIAIRE 
         	FROM MODULE_PEC 
         	INNER JOIN ACTION_PEC 
         		ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC 
         		AND ACTION_PEC.BLN_ACTIF=1 
         		AND ACTION_PEC.DAT_CLOTURE IS NULL 
         	INNER JOIN STAGIAIRE_PEC 
         		ON STAGIAIRE_PEC.ID_MODULE_PEC=MODULE_PEC.ID_MODULE_PEC 
         		AND STAGIAIRE_PEC.ID_ETABLISSEMENT = @ID_BENEFICIAIRE 
         		AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL 
         
         	-- Rajout MBL du 21/10/2015 :	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         	INNER JOIN PERIODE				ON	PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         									AND	PERIODE.NUM_ANNEE >= @NUM_ANNEE_EN_COURS - 2
         
         	WHERE
         		MODULE_PEC.BLN_ACTIF = 1 
         		AND MODULE_PEC.BLN_IMPUTABLE = 1 
         
         	----------- D‚doublonner les r‚sultats en r‚cup‚rant uniquement le 1er stagiaire de l'‚tablissement concern‚ 
         	----------- de chaque module au module
         	SELECT 
         		MAX(ID_STAGIAIRE_PEC) AS MAX_ID_STAGIAIRE_PEC, 
         		COUNT(ID_STAGIAIRE_PEC) AS NB_STAGIAIRES,
         		CAST (NULL AS VARCHAR(52)) AS NOM_STAGIARE,
         		ID_MODULE_PEC 
         	INTO #PREMIER_STAGIAIRE_PAR_MODULE_PEC 
         	FROM #LISTMODULE_ETAB_STAGIAIRE 
         	GROUP BY ID_MODULE_PEC
         
         	-----------Ajouter le nom pr‚nom du stagiaire d‚fini dans le bloc pr‚c‚dent
         	UPDATE #PREMIER_STAGIAIRE_PAR_MODULE_PEC
         		SET NOM_STAGIARE = NOM_INDIVIDU +' '+LEFT(PRENOM_INDIVIDU, 1) 
         	FROM #PREMIER_STAGIAIRE_PAR_MODULE_PEC
         	INNER JOIN STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = #PREMIER_STAGIAIRE_PAR_MODULE_PEC.MAX_ID_STAGIAIRE_PEC
         	INNER JOIN INDIVIDU ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         
          
         	-----------R‚cup‚ration des ID des types de co–ts
         	DECLARE @TC_CP INT 
         	DECLARE @TC_REM INT 
         	DECLARE @TC_FA INT 
         	DECLARE @ID_ADH INT
         
         	SELECT @TC_CP = ID_TYPE_COUT FROM TYPE_COUT WHERE COD_TYPE_COUT='CP' 
         	SELECT @TC_REM = ID_TYPE_COUT FROM TYPE_COUT WHERE COD_TYPE_COUT='REM' 
         	SELECT @TC_FA = ID_TYPE_COUT FROM TYPE_COUT WHERE COD_TYPE_COUT='FA' 
         	SELECT @ID_ADH = ID_ADHERENT FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT=@ID_BENEFICIAIRE
         
         
         	----------- R‚cup‚ration des PCE engag‚s non d‚sengag‚s 
         	----------- avec sum(montants PFUS) pour chaque module s‚lectionn‚
         	SELECT
         		#LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC, 
         		POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT AS STC, 
         		SOUS_TYPE_COUT.ID_TYPE_COUT AS TC, 
         		SUM(PFUS.MNT_PLAN_FINANCEMENT_US) AS MNT_PFUS,
         		#LISTMODULE_ETAB_STAGIAIRE.DAT_FIN, 
         		#LISTMODULE_ETAB_STAGIAIRE.ID_ETABLISSEMENT 
         	INTO #LIST_MODULES 
         	FROM #LISTMODULE_ETAB_STAGIAIRE 
         	INNER JOIN POSTE_COUT_ENGAGE 
         		ON #LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC 
         		AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL 
         		AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT > 0 
         		AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         	INNER JOIN UNITE_STAGIAIRE 
         		ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = #LISTMODULE_ETAB_STAGIAIRE.ID_STAGIAIRE_PEC 
         	INNER JOIN PLAN_FINANCEMENT_US AS PFUS 
         		ON PFUS.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
         		AND PFUS.ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE 
         		AND PFUS.BLN_ACTIF=1 
         	INNER JOIN SOUS_TYPE_COUT 
         		ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT 
         	GROUP BY 
         		#LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC, 
         		#LISTMODULE_ETAB_STAGIAIRE.DAT_FIN, 
         		#LISTMODULE_ETAB_STAGIAIRE.ID_ETABLISSEMENT, 
         		SOUS_TYPE_COUT.ID_TYPE_COUT, 
         		POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT 
         
         
         -------- R‚cup‚ration des sum(montants de PFUS de PCE) par TC sauf STC exclus
         	SELECT 
         		#LIST_MODULES.ID_MODULE_PEC, 
         		NB_STAGIAIRES, 
         		MAX(DAT_FIN) AS DAT_FIN, 
         		SUM(CASE WHEN (#LIST_STC_A_EXCLURE.DATA IS  NULL  )
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_ENGAGE_SAUF_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_MODULES.TC = @TC_CP AND #LIST_STC_A_EXCLURE.DATA IS NULL
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_ENGAGE_TC_CP_SAUF_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_MODULES.TC = @TC_CP AND #LIST_STC_A_EXCLURE.DATA IS NOT NULL  
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_ENGAGE_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_MODULES.TC = @TC_REM 
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_ENGAGE_TC_REM, 
         		SUM(CASE WHEN #LIST_MODULES.TC = @TC_FA 
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_ENGAGE_TC_FA 
         	INTO #SUM_LIST_MODULES 
         	FROM #LIST_MODULES
         		INNER JOIN #PREMIER_STAGIAIRE_PAR_MODULE_PEC ON  #LIST_MODULES.ID_MODULE_PEC=#PREMIER_STAGIAIRE_PAR_MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN #LIST_STC_A_EXCLURE ON #LIST_STC_A_EXCLURE.DATA=#LIST_MODULES.STC
         	GROUP BY #LIST_MODULES.ID_MODULE_PEC, #PREMIER_STAGIAIRE_PAR_MODULE_PEC.NB_STAGIAIRES 
         
         
         -------- R‚cup‚ration des sum(PFUS) par TC des couples sessions-stagiaire 
         -------- pour chaque couple module-stagiaire identifi‚ pr‚c‚demment
         -------- A‹e ? Sum (PCR.MNT_REGLE_HT) = MNT_REEL
         	SELECT 
         		#LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC AS ID_MODULE_PEC, 
         		SESSION_PEC.ID_SESSION_PEC, 
         		MAX(COALESCE(SESSION_PEC.DAT_FIN, '01/01/1900')) AS DAT_FIN_SESSION, 
         --		ISNULL(SUM(POSTE_COUT_REGLE.MNT_REGLE_HT),0) AS MNT_REEL, 
         		POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT AS STC, 
         		SOUS_TYPE_COUT.ID_TYPE_COUT AS TC, 
         		SUM(PFUS.MNT_PLAN_FINANCEMENT_US) AS MNT_PFUS
         
         	INTO #LIST_SESSIONS 
         	FROM #LISTMODULE_ETAB_STAGIAIRE 
         		INNER JOIN SESSION_PEC 
         			ON SESSION_PEC.ID_MODULE_PEC=#LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC 
         			AND SESSION_PEC.BLN_ACTIF=1 
         		INNER JOIN STAGIAIRE_PEC 
         			ON STAGIAIRE_PEC.ID_SESSION_PEC=SESSION_PEC.ID_SESSION_PEC 
         			AND STAGIAIRE_PEC.ID_ETABLISSEMENT = #LISTMODULE_ETAB_STAGIAIRE.ID_ETABLISSEMENT 
         			AND STAGIAIRE_PEC.ID_INDIVIDU = #LISTMODULE_ETAB_STAGIAIRE.ID_INDIVIDU 
         		INNER JOIN UNITE_STAGIAIRE 
         			ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC 
         		-- 20120320 INNER au lieu de LEFT vu la jointure sur PFUS
         		INNER JOIN POSTE_COUT_REGLE 
         			ON -- 20120320 mauvaise clause remplac‚e par SESSION 
         			-- POSTE_COUT_REGLE.ID_MODULE_PEC = #LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC 
         			POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 
         			AND POSTE_COUT_REGLE.BLN_ACTIF=1 
         		INNER JOIN PLAN_FINANCEMENT_US AS PFUS 
         			ON PFUS.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
         			AND PFUS.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE 
         			AND PFUS.BLN_ACTIF=1 
         		INNER JOIN SOUS_TYPE_COUT 
         			ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT 
         	GROUP BY 
         		#LISTMODULE_ETAB_STAGIAIRE.ID_MODULE_PEC, 
         		POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT, 
         		SOUS_TYPE_COUT.ID_TYPE_COUT, 
         		SESSION_PEC.ID_SESSION_PEC
         	
         -------- Consolidation des sum(PFUS de PCR) par TC des couples sessions-stagiaire sauf STC exclus
         	SELECT
         		MAX (DAT_FIN_SESSION) AS DAT_FIN_SESSION, 
         		#LIST_SESSIONS.ID_SESSION_PEC, 
         		ID_MODULE_PEC, 
         		SUM(CASE WHEN (#LIST_STC_A_EXCLURE.DATA IS NULL  )
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_REGLE_SAUF_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_SESSIONS.TC = @TC_CP AND #LIST_STC_A_EXCLURE.DATA IS NULL
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_REGLE_TC_CP_SAUF_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_SESSIONS.TC = @TC_CP AND #LIST_STC_A_EXCLURE.DATA IS NOT NULL  
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_REGLE_STC_EXCLUS, 
         		SUM(CASE WHEN #LIST_SESSIONS.TC = @TC_REM 
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_REGLE_TC_REM, 
         		SUM(CASE WHEN #LIST_SESSIONS.TC = @TC_FA 
         			THEN MNT_PFUS ELSE 0 END
         			) AS MNT_REGLE_TC_FA 
         	INTO #SUM_LIST_SESSIONS_INTERMEDIAIRE 
         	FROM #LIST_SESSIONS 
         	LEFT JOIN #LIST_STC_A_EXCLURE ON #LIST_STC_A_EXCLURE.DATA=#LIST_SESSIONS.STC
         	GROUP BY 
         		#LIST_SESSIONS.ID_MODULE_PEC, 
         		#LIST_SESSIONS.ID_SESSION_PEC 
         
         
         -------- Consolidation des sum(PFUS de PCR) par TC tous couples sessions-stagiaire confondus sauf STC exclus
         -------- par module
         	SELECT 
         		MAX(DAT_FIN_SESSION) AS DAT_FIN_SESSION, 
         		ID_MODULE_PEC, 
         		SUM(MNT_REGLE_SAUF_STC_EXCLUS) AS MNT_REGLE_SAUF_STC_EXCLUS, 
         		SUM(MNT_REGLE_TC_CP_SAUF_STC_EXCLUS) AS MNT_REGLE_TC_CP_SAUF_STC_EXCLUS, 
         		SUM(MNT_REGLE_STC_EXCLUS) AS MNT_REGLE_STC_EXCLUS, 
         		SUM(MNT_REGLE_TC_REM) AS MNT_REGLE_TC_REM, 
         		SUM(MNT_REGLE_TC_FA) AS MNT_REGLE_TC_FA 
         	INTO #SUM_LIST_SESSIONS 
         	FROM #SUM_LIST_SESSIONS_INTERMEDIAIRE 
         	GROUP BY #SUM_LIST_SESSIONS_INTERMEDIAIRE.ID_MODULE_PEC 
         
         
         
         -----------------------------------------------------------
         --************************ PIECES *************************
         -----------------------------------------------------------
         	CREATE TABLE #LIST_PIECES_DOUBLONS_POSSIBLES (
         	ID_MODULE_PEC INT,
         	ID_SESSION_PEC INT,
         	COD_SESSION_PEC VARCHAR(17),
         	BLN_ACTIF TINYINT,
         	ID_ARRIVEE_PIECE_PEC INT,
         	DAT_RELANCE_REGLE_1 DATETIME,
         	DAT_RELANCE_REGLE_2 DATETIME,
         	DAT_RELANCE_REGLE_3 DATETIME,
         	NOM_PRENOM_STAGIARE varchar(50)
         );
         
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	/**** Liste des arriv‚es piŠces li‚es aux postes cout r‚gl‚s *************/
         	SELECT #SUM_LIST_SESSIONS.ID_MODULE_PEC,
         		 SESSION_PEC.ID_SESSION_PEC,
         		 SESSION_PEC.COD_SESSION_PEC,
         		 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		 NULL AS NOM_PRENOM_STAGIARE
         	FROM #SUM_LIST_SESSIONS 
         	INNER JOIN SESSION_PEC 
         	ON SESSION_PEC.ID_MODULE_PEC=#SUM_LIST_SESSIONS.ID_MODULE_PEC 
         	AND SESSION_PEC.BLN_ACTIF=1 
         	JOIN	POSTE_COUT_REGLE 
         	ON	POSTE_COUT_REGLE.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON	POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         	AND	ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC
         	JOIN	PIECE_PEC 
         	ON	ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         	INNER JOIN MODULE_PEC 
         	ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC 
         
         	WHERE	(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         	AND	(MODULE_PEC.BLN_DELEGATION_PAIEMENT = 0)
         	AND	(PIECE_PEC.BLN_ACTIF = 1)
         	AND	((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND	((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         			AND ( EXISTS (SELECT 1 FROM NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         
         
         	/**** Liste des arriv‚es piŠces li‚es aux modules *************************/
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	SELECT #SUM_LIST_MODULES.ID_MODULE_PEC,
         		 NULL,
         		 NULL,
         		 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		 NULL AS NOM_PRENOM_STAGIARE
         
         	FROM    #SUM_LIST_MODULES
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON	#SUM_LIST_MODULES.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         	JOIN	PIECE_PEC 
         	ON	ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC AND (PIECE_PEC.BLN_STAGIAIRE = 0)
         	INNER JOIN MODULE_PEC 
         	ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC 
         
         	WHERE	(PIECE_PEC.BLN_MODULE = 1)
         	AND	(MODULE_PEC.BLN_DELEGATION_PAIEMENT = 0)
         	AND	(PIECE_PEC.BLN_ACTIF = 1)
         	AND	((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND	((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         	AND ( EXISTS (SELECT 1 FROM NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         
         
         	/**** Liste des arriv‚es piŠces li‚es aux sessions ************************/
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	SELECT #SUM_LIST_SESSIONS.ID_MODULE_PEC,
         		 SESSION_PEC.ID_SESSION_PEC,
         		 SESSION_PEC.COD_SESSION_PEC,
         		 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		 NULL AS NOM_PRENOM_STAGIARE
         
         	FROM    #SUM_LIST_SESSIONS
         	INNER JOIN SESSION_PEC 
         	ON SESSION_PEC.ID_MODULE_PEC=#SUM_LIST_SESSIONS.ID_MODULE_PEC 
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON	SESSION_PEC.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         	AND	(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC)
         	JOIN	PIECE_PEC 
         	ON	ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC 
         	INNER JOIN MODULE_PEC 
         	ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC 
         
         	WHERE	(PIECE_PEC.BLN_SESSION = 1)
         	AND	(MODULE_PEC.BLN_DELEGATION_PAIEMENT = 0)
         	AND	(PIECE_PEC.BLN_ACTIF = 1)
         	AND	((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND	((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         	AND	(EXISTS (SELECT 1 FROM NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         
         
         	/**** Liste des arriv‚es piŠces li‚es aux stagiaires modules **************/
         	---requ‚te refait DSZ 08/10/2010 en vue de 12513 : la requˆte pr‚cedente ne donne pas de r‚sultats, … tort
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	SELECT DISTINCT
         		#SUM_LIST_MODULES.ID_MODULE_PEC,
         		NULL,
         		NULL,
         		ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC, 
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		LEFT(NOM_INDIVIDU+ ' '+ PRENOM_INDIVIDU, 50) AS NOM_PRENOM_STAGIARE
         	FROM #SUM_LIST_MODULES
         		INNER JOIN STAGIAIRE_PEC 
         			ON	STAGIAIRE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC 
         				AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL
         		INNER JOIN ARRIVEE_PIECE_PEC	ON	STAGIAIRE_PEC.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC	AND
         										ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE IS NULL
         		INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC	= PIECE_PEC.ID_PIECE_PEC
         		INNER JOIN INDIVIDU ON (STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU)
         		
         	WHERE 
         		PIECE_PEC.BLN_STAGIAIRE = 1 AND 
         		ARRIVEE_PIECE_PEC.ID_SESSION_PEC IS NULL AND
         		(
         			ISNULL(ARRIVEE_PIECE_PEC.BLN_ACTIF,0) = 0
         			OR	
         			ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         		) 
         
         	/**** Liste des arriv‚es piŠces li‚es aux stagiaires sessions ************/
         	---requ‚te refait DSZ 08/10/2010 en vue de 12513 : la requˆte pr‚cedente ne donne pas de r‚sultats, … tort
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	SELECT DISTINCT
         		#SUM_LIST_MODULES.ID_MODULE_PEC,
         		ARRIVEE_PIECE_PEC.ID_SESSION_PEC,
         		SESSION_PEC.COD_SESSION_PEC,
         		ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC, 
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		LEFT(NOM_INDIVIDU+ ' '+ PRENOM_INDIVIDU, 50) AS NOM_PRENOM_STAGIARE
         	FROM #SUM_LIST_MODULES
         		INNER JOIN SESSION_PEC ON (SESSION_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC )
         		INNER JOIN STAGIAIRE_PEC 
         			ON	STAGIAIRE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC 
         				AND STAGIAIRE_PEC.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         		INNER JOIN ARRIVEE_PIECE_PEC	ON	STAGIAIRE_PEC.ID_STAGIAIRE_PEC = ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC	AND
         											ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE IS NULL
         		INNER JOIN 	PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC	= PIECE_PEC.ID_PIECE_PEC
         		JOIN INDIVIDU ON (STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU)
         	
         	WHERE 
         		PIECE_PEC.BLN_STAGIAIRE = 1 AND 
         		ARRIVEE_PIECE_PEC.ID_SESSION_PEC IS NOT NULL AND
         		(
         			ISNULL(ARRIVEE_PIECE_PEC.BLN_ACTIF,0) = 0
         			OR	
         			ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         		) 
         
         	/**** Liste des arriv‚es piŠces li‚es aux adherents *********************/
         	INSERT INTO #LIST_PIECES_DOUBLONS_POSSIBLES
         	SELECT #SUM_LIST_MODULES.ID_MODULE_PEC,
         		 NULL,
         		 NULL,
         		 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         		 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         		 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3,
         		 NULL AS NOM_PRENOM_STAGIARE
         
         	FROM	#SUM_LIST_MODULES  
         	JOIN	ARRIVEE_PIECE_PEC 
         	ON	ARRIVEE_PIECE_PEC.ID_ADHERENT = @ID_ADH
         	AND	(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC)
         	JOIN	PIECE_PEC 
         	ON	ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         
         	INNER JOIN MODULE_PEC 
         	ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC 
         
         	WHERE	(PIECE_PEC.BLN_ADHERENT = 1)
         	AND	(PIECE_PEC.BLN_ACTIF = 1)
         	AND	(MODULE_PEC.BLN_DELEGATION_PAIEMENT = 0)
         	AND	((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         	AND	((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         	AND ( EXISTS (SELECT 1 FROM NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         
         	SELECT DISTINCT #LIST_PIECES_DOUBLONS_POSSIBLES.*,
         	CAST (NULL AS VARCHAR(50)) AS MOTIF_NC,
         	0 AS COUNT_NC
         	INTO #LIST_PIECES
         	FROM #LIST_PIECES_DOUBLONS_POSSIBLES 
         
         	UPDATE #LIST_PIECES
         	SET MOTIF_NC = 
         		(SELECT MIN(MOTIF_NON_CONFORM_PIECE.LIBL_MOTIF_NON_CONFORM_PIECE)
         			FROM MOTIF_NON_CONFORM_PIECE
         			LEFT JOIN NR210 ON (NR210.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE)
         			WHERE NR210.ID_ARRIVEE_PIECE_PEC = #LIST_PIECES.ID_ARRIVEE_PIECE_PEC),
         	COUNT_NC = 
         		(SELECT COUNT(NR210.ID_MOTIF_NON_CONFORM_PIECE)
         		FROM NR210
         		WHERE NR210.ID_ARRIVEE_PIECE_PEC = #LIST_PIECES.ID_ARRIVEE_PIECE_PEC)
         	FROM #LIST_PIECES
         	WHERE #LIST_PIECES.BLN_ACTIF=1
         
         	-- **************************** TOUT **************************************
         	-- **************************** TOUT **************************************
         	SELECT 
         		MODULE_PEC.ID_MODULE_PEC AS ID_MODULE_PEC, 
         		CASE WHEN (#LIST_PIECES.ID_MODULE_PEC IS NOT NULL) 
         		THEN MODULE_PEC.COD_MODULE_PEC + ' *'
         		ELSE
         		MODULE_PEC.COD_MODULE_PEC
         		END
         		AS NUM_MODULE, 
         		CASE WHEN MODULE_PEC.ID_ETABLISSEMENT_OF IS NOT NULL THEN 
         		ORGANISME_FORMATION.LIB_RAISON_SOCIALE 
         		ELSE 
         		'Formation interne' 
         		END AS LIBL_OF, 
         		MODULE_PEC.LIBL_MODULE_PEC AS LIBL_MODULE_PEC, 
         		CONVERT(CHAR(10),MODULE_PEC.DAT_DEBUT,3) AS DATE_DEBUT_STRING, 
         		CONVERT(CHAR(10),MODULE_PEC.DAT_FIN,3) AS DATE_FIN_STRING, 
         		MODULE_PEC.DAT_DEBUT AS DATE_DEBUT_DATE, 
         		MODULE_PEC.DAT_FIN AS DATE_FIN_DATE, 
         		CASE WHEN #SUM_LIST_SESSIONS.DAT_FIN_SESSION IS NULL THEN 
         		'' 
         		ELSE 
         		CONVERT(CHAR(10),#SUM_LIST_SESSIONS.DAT_FIN_SESSION,3) 
         		END AS DAT_FIN_SESSION_STRING, 
         		MODULE_PEC.BLN_DELEGATION_PAIEMENT AS BLN_DELEGATION_PAIEMENT, 
         		#SUM_LIST_MODULES.NB_STAGIAIRES AS NB_STAGIAIRES, 
         		#SUM_LIST_MODULES.DAT_FIN AS DAT_FIN, 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_SAUF_STC_EXCLUS + #SUM_LIST_MODULES.MNT_ENGAGE_STC_EXCLUS  ,2)AS MNT_ENGAGE, 
         		ROUND(COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_SAUF_STC_EXCLUS,0) + COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_STC_EXCLUS,0) ,2) AS MNT_REGLE, 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_SAUF_STC_EXCLUS + #SUM_LIST_MODULES.MNT_ENGAGE_STC_EXCLUS
         			- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_SAUF_STC_EXCLUS,0)- + COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_STC_EXCLUS,0)
         		 ,2)
         		AS A_FACTURER, --A_FACTURER 
         		CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT=0) THEN 
         			ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_SAUF_STC_EXCLUS 
         			+ #SUM_LIST_MODULES.MNT_ENGAGE_STC_EXCLUS 
         			- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_SAUF_STC_EXCLUS,0) 
         			- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_STC_EXCLUS,0)  ,2)
         			ELSE 
         			ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_SAUF_STC_EXCLUS 
         			- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_SAUF_STC_EXCLUS,0)  ,2)
         		END AS A_FACTURER_ENTREPRISE, --A_FACTURER_ENTREPRISE 
         		CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT=0) THEN 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_TC_CP_SAUF_STC_EXCLUS 
         		+ #SUM_LIST_MODULES.MNT_ENGAGE_STC_EXCLUS 
         		- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_TC_CP_SAUF_STC_EXCLUS,0) 
         		- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_STC_EXCLUS,0)  ,2)
         		ELSE 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_TC_CP_SAUF_STC_EXCLUS 
         		- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_TC_CP_SAUF_STC_EXCLUS,0)  ,2)
         		END AS A_FACTURER_ENTREPRISE_TC_CP, --A_FACTURER_ENTREPRISE_TC_CP 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_TC_REM 
         		- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_TC_REM,0)  ,2)
         		AS A_FACTURER_ENTREPRISE_TC_REM, --A_FACTURER_ENTREPRISE_TC_REM 
         		ROUND(#SUM_LIST_MODULES.MNT_ENGAGE_TC_FA 
         		- COALESCE(#SUM_LIST_SESSIONS.MNT_REGLE_TC_FA,0) ,2)
         		AS A_FACTURER_ENTREPRISE_TC_FA --A_FACTURER_ENTREPRISE_TC_FA 
         		,
         		(SELECT 
         			ISNULL(SUM(NB_HOURS),0) 
         			FROM 
         			(SELECT DISTINCT(STAGIAIRE_PEC.ID_STAGIAIRE_PEC), 
         				STAGIAIRE_PEC.NB_HEURE_ENGAGE AS NB_HOURS
         				FROM STAGIAIRE_PEC		
         				LEFT JOIN MODULE_PEC		ON	MODULE_PEC.ID_MODULE_PEC		= STAGIAIRE_PEC.ID_MODULE_PEC									 
         				LEFT JOIN POSTE_COUT_ENGAGE ON	POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC														
         				WHERE 
         					MODULE_PEC.ID_MODULE_PEC			= #SUM_LIST_MODULES.ID_MODULE_PEC				AND			
         					STAGIAIRE_PEC.ID_SESSION_PEC		IS NULL							AND
         					MODULE_PEC.BLN_ACTIF				= 1								AND
         					MODULE_PEC.BLN_IMPUTABLE			= 1								AND
         					POSTE_COUT_ENGAGE.ID_ENGAGEMENT		IS NOT NULL						AND 
         					POSTE_COUT_ENGAGE.ID_ENGAGEMENT		> 0								AND
         					POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         			) AS CALC_HEURE_ENGAGEES
         		) AS NB_HEURE_ENGAGE,
         
         		-- Nb Heur Realisees
         		(SELECT 
         			ISNULL(SUM( STAGIAIRE_PEC.NB_HEURE_REGLE),0) 
         			FROM 
         				STAGIAIRE_PEC
         				LEFT JOIN MODULE_PEC		ON	MODULE_PEC.ID_MODULE_PEC			= STAGIAIRE_PEC.ID_MODULE_PEC									 		
         				LEFT JOIN SESSION_PEC		ON	SESSION_PEC.ID_SESSION_PEC			= STAGIAIRE_PEC.ID_SESSION_PEC
         				WHERE 
         				MODULE_PEC.ID_MODULE_PEC			= #SUM_LIST_MODULES.ID_MODULE_PEC				AND			
         				MODULE_PEC.BLN_IMPUTABLE			= 1								AND
         				MODULE_PEC.BLN_ACTIF				= 1								AND
         				SESSION_PEC.BLN_ACTIF				= 1								
         		)	AS NB_HEURE_REEL 	
         			
         		INTO #LISTE_COMPLETE 
         		FROM #SUM_LIST_MODULES 
         		INNER JOIN MODULE_PEC 
         		ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_MODULES.ID_MODULE_PEC 
         		LEFT JOIN ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF=ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         		LEFT JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF=ORGANISME_FORMATION.ID_OF 
         		LEFT JOIN #SUM_LIST_SESSIONS 
         		ON MODULE_PEC.ID_MODULE_PEC = #SUM_LIST_SESSIONS.ID_MODULE_PEC 
         		LEFT JOIN #LIST_PIECES 
         		ON MODULE_PEC.ID_MODULE_PEC = #LIST_PIECES.ID_MODULE_PEC
         
         		SELECT 
         			ID_MODULE_PEC, 
         			CASE WHEN DATEDIFF(D,DAT_FIN, GETDATE())>@PARAM_DUREE_A THEN 
         			'A' 
         			WHEN DATEDIFF(D,DAT_FIN, GETDATE())>@PARAM_DUREE_B THEN -- param 30j 
         			'B' 
         			WHEN  DAT_FIN < GETDATE() + @PARAM_DUREE_C  THEN --DSZ 26/03/2012
         			--when abs (datediff(d,DAT_FIN, getdate()))<=@PARAM_DUREE_C then -- param +-30j 
         			'C' 
         			WHEN ROUND(A_FACTURER_ENTREPRISE,2)  > @PARAM_MNT_D THEN --param 150 
         			'D' 
         			ELSE 
         			'' 
         			END AS TYPE_DOSSIER 
         		INTO #TYPE_DOSSIER 
         		FROM #LISTE_COMPLETE 		
         
         		SELECT DISTINCT
         			#TYPE_DOSSIER.TYPE_DOSSIER, 
         			#LISTE_COMPLETE.* 
         		INTO #LISTE_TYPEE 
         		FROM #LISTE_COMPLETE 
         		INNER JOIN #TYPE_DOSSIER 
         			ON #LISTE_COMPLETE.ID_MODULE_PEC = #TYPE_DOSSIER.ID_MODULE_PEC 
         		WHERE 
         			--modif DSZ 21/09/2010 sur la condition > @PARAM_MNT_D uniquement pour type D
         			-- ajout @PARAM_MNT_MIN
         			--modif DSZ 20/09/2010 12495
         			ROUND(A_FACTURER_ENTREPRISE,2) > @PARAM_MNT_MIN
         			AND #TYPE_DOSSIER.TYPE_DOSSIER <> ''
         		ORDER BY NUM_MODULE 
         
         		SELECT 
         			#LISTE_TYPEE.NUM_MODULE,
         			PIECE_PEC.LIBL_PIECE_PEC,
         			CASE WHEN #LIST_PIECES.BLN_ACTIF=1 
         				THEN CAST(#LIST_PIECES.COUNT_NC AS VARCHAR(2))+ ' NC dont '+ #LIST_PIECES.motif_NC
         				ELSE 'M' END 
         			AS M_NC,
         			CASE 
         				WHEN PIECE_PEC.BLN_STAGIAIRE = 1 AND #LIST_PIECES.COD_SESSION_PEC IS NOT NULL THEN 
         					'Stagiaire '+ #LIST_PIECES.NOM_PRENOM_STAGIARE + ' ('+#LIST_PIECES.COD_SESSION_PEC+')'
         				WHEN PIECE_PEC.BLN_STAGIAIRE = 1 THEN 
         					'Stagiaire '+ #LIST_PIECES.NOM_PRENOM_STAGIARE
         				WHEN PIECE_PEC.BLN_SESSION = 1 THEN 'Session '+ #LIST_PIECES.COD_SESSION_PEC
         				WHEN PIECE_PEC.BLN_POSTE_COUT_REGLE = 1 THEN 'Demande de rŠglement'
         				WHEN PIECE_PEC.BLN_MODULE = 1 then 'Module' 
         				ELSE ''
         			END AS TYPE_PIECE
         		INTO #LIST_PIECES_TABLEAU
         		FROM #LIST_PIECES
         		JOIN ARRIVEE_PIECE_PEC
         		ON ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC = #LIST_PIECES.ID_ARRIVEE_PIECE_PEC
         		JOIN PIECE_PEC
         		ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         		INNER JOIN #LISTE_TYPEE 
         			ON #LIST_PIECES.ID_MODULE_PEC = #LISTE_TYPEE.ID_MODULE_PEC 
         
         
         		/**********************************************************************************************/
         		/*****************	SIGNATURE DE LA LETTRE ANNEX ****************************************************/
         		/**********************************************************************************************/
         		DECLARE @LIB_PRENOM_CHARGE_RELATION_SIGNE VARCHAR(100)
         		DECLARE @LIB_NOM_CHARGE_RELATION_SIGNE VARCHAR(100) 
         
         		SELECT	@LIB_NOM_CHARGE_RELATION_SIGNE = ISNULL(LIB_NOM_CHARGE_RELATION, ''),
         				@LIB_PRENOM_CHARGE_RELATION_SIGNE = ISNULL(LIB_PRENOM_CHARGE_RELATION, '')
         		FROM	#TEMP_REFERENCE AS SIGNATURE;
         
         
         		/*********Total Montant Facturable***********/
         		DECLARE @MNT_TOTAL_FACT DECIMAL(18,2)
         		DECLARE @MNT_TOTAL_RESTANT_DU DECIMAL(18,2)
         
         		SELECT 
         			@MNT_TOTAL_FACT = ROUND(SUM(A_FACTURER_ENTREPRISE),2),
         			@MNT_TOTAL_RESTANT_DU = ROUND(SUM(A_FACTURER),2) 
         		FROM #LISTE_TYPEE 
         		WHERE TYPE_DOSSIER <> ''
         					
         					
         		---- Safi Ajouter 31/08/2010 ---->	
         		------------ PAVE 5 BEGIN ---------------------------------------------------
         		SELECT		@ROW_COUNT_PAVE_5 = COUNT(*)
         		FROM		#LISTE_TYPEE
         		INNER JOIN  #PREMIER_STAGIAIRE_PAR_MODULE_PEC PS  ON (PS.ID_MODULE_PEC = #LISTE_TYPEE.ID_MODULE_PEC)
         		WHERE		BLN_DELEGATION_PAIEMENT = 0		
         		------------ PAVE 5 END   ---------------------------------------------------
         		------------ PAVE 6 BEGIN ---------------------------------------------------
         		SELECT		@ROW_COUNT_PAVE_6 = COUNT(*)
         		FROM		#LISTE_TYPEE
         		INNER JOIN	#PREMIER_STAGIAIRE_PAR_MODULE_PEC PS  ON (PS.ID_MODULE_PEC = #LISTE_TYPEE.ID_MODULE_PEC)
         		WHERE		BLN_DELEGATION_PAIEMENT = 1
         	
         		SELECT
         			'Vos r‚f‚rences dossiers '+@FAF_NAME+'(1)'+CHAR(13) + CHAR(10)+'A rappeler imp‚rativement sur la facture' AS NUM_MODULE_PAVE_6_ENTETE,
         			'Type de dossier (2)'																AS TYPE_DOSSIER_PAVE_6_ENTETE,
         			'Organisme de Formation / Intitul‚ de la formation'									AS LIB_OF_ET_MOD_PEC_PAVE_6_ENTETE,
         			'Nb de stagiaires Dont Nom du 1er salari‚'											AS NB_STAG_AVEC_NOM_PAVE_6_ENTETE,  
         			'Date de d‚but formation / date de fin de formation'								AS DT_DEBUT_FORM_PAVE_6_ENTETE,
         			'Date derniŠre journ‚e attest‚e '													AS DAT_DER_JOUR_ATT_PAVE_6_ENTETE,
         			'Montant engag‚'																	AS MNT_ENGAGE_PAVE_6_ENTETE,		
         			'Nombre Heures attest‚es / Nombre heures pr‚vues'									AS NB_H_REEL_ET_ENG_PAVE_6_ENTETE,		
         			'A facturer entreprise'																AS A_FACT_ENTR_PAVE_6_ENTETE,
         			'Votre r‚ponse (3) :'																AS VOTRE_REP_PAVE_6_ENTETE,
         			'Dont A facturer Co–ts p‚dagogiques'												AS A_FACT_ENTR_TC_CP_PAVE_6_ENTETE,
         			'Dont A facturer Salaires stagiaires formateur Allocation formation'				AS A_FACT_ENTR_TC_REM_PAVE_6_ENTETE,
         			'Dont A facturer Frais annexes'														AS A_FACT_ENTR_TC_FA_PAVE_6_ENTETE
         		INTO #PAVE_6_ENTETE
         		------------ PAVE 6 END   ---------------------------------------------------
         		------------ PAVE 7 BEGIN ---------------------------------------------------
         		SELECT	@ROW_COUNT_PAVE_7 = COUNT(*) FROM #LIST_PIECES_TABLEAU 
         
         		SELECT	'Vos r‚f‚rences dossiers '+@FAF_NAME			AS NUM_MODULE_PAVE_7_ENTETE,	
         				'Liste des piŠces manquantes / NC'				AS LIBL_PIECE_PEC_PAVE_7_ENTETE,
         				'Manquante / Non conforme'						AS M_NC_PAVE_7_ENTETE,
         				'Type de piŠce (Code session)'					AS TYPE_PIECE_PAVE_7_ENTETE
         		INTO	#PAVE_7_ENTETE	
         		------------ PAVE 7 BEGIN END -----------------------------------------------
         		--<--- Safi Ajouter 31/08/2010 -----
         			
         		DECLARE @PAVE_1 VARCHAR(MAX)
         		
         		SELECT @PAVE_1 = 
         			'Dossiers … facturer … '+@FAF_NAME+' de ' +
         			LTRIM(RTRIM(PAVE_1_TITRE.LIB_RAISON_SOCIALE)) + ' … ' +			
         			(CASE WHEN PATINDEX('%CEDEX%', PAVE_1_TITRE.VILLE) <> 0 THEN 
         				 LEFT(PAVE_1_TITRE.VILLE, PATINDEX('%CEDEX%', PAVE_1_TITRE.VILLE)-1) 
         			ELSE LTRIM(RTRIM(PAVE_1_TITRE.VILLE)) 
         			END) 								
         			+ ' - SIRET No ' + LTRIM(RTRIM(PAVE_1_TITRE.NUM_SIRET))
         			FROM  #TEMP_REFERENCE AS PAVE_1_TITRE;
         
         			/*****  Creation du flux XML *****************************************************************************/
         			WITH XMLNAMESPACES (
         					DEFAULT 'EDT_LETTRE_PEC_DOSSIERS_FACTURABLES'
         				)
         
         			SELECT
         			/**********************************************************************************************/
         			/*****************	ENTETE DE LA LETTRE *******************************************************/
         			/**********************************************************************************************/
         			(
         				SELECT	    
         
         				-- R‚cup‚ration des informations sur le contact et le b‚n‚ficiaire
         				-- utilisation fonction SansFonction Mantis 12501 21/09/2010 DSZ
         				( SELECT dbo.GetXmlBenefContactSansFonction(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) 
         				  FOR XML RAW('BENEFICIAIRE_LETTRE'), ELEMENTS, TYPE),
         	  	
         				/******************* Recuperation des informations de l'entete ****************************/
         				ISNULL(COD_ADHERENT, '')				AS COD_ADH,					
         				ISNULL(LIB_PRENOM_CHARGE_RELATION, '')	AS LIB_PRENOM_CHARGE_RELATION,					
         				ISNULL(LIB_NOM_CHARGE_RELATION, '')		AS LIB_NOM_CHARGE_RELATION,
         				ISNULL(EMAIL_CHARGE_RELATION, '')		AS EMAIL,
         				ISNULL(TEL_CHARGE_RELATION,'')			AS TEL_CR,
         
         				-- R‚cup‚ration des informations sur l'‚metteur
         				(SELECT dbo.GetXmlAdrUtilAvecTel(ENTETE.ID_UTIL, (SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE), 1) FOR XML RAW('EMETTEUR_LETTRE'), ELEMENTS, TYPE),
         				RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         				dbo.GetFullDate(GETDATE()) AS DATE,				
         				(
         					SELECT TOP 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
         					FROM CIVILITE
         					FOR XML PATH('POLITESSE_HAUT'), TYPE
         				)
         				FROM #TEMP_REFERENCE AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         	
         			/***************** fin entete, corps ****************/		
         			(	SELECT dbo.getFrenchCurrencyFormat(ISNULL(@MNT_TOTAL_FACT,0))
         				FOR XML RAW('TOTAL_MNT_FACTURABLE'), ELEMENTS, TYPE
         			),
         
         			(
         				SELECT @ANNUL_CREANCES
         				FOR XML RAW('ANNULATION_CREANCES'), ELEMENTS, TYPE
         			),
         		
         			(
         				SELECT ISNULL(LIB_PRENOM_CHARGE_RELATION, '') + ' '+  ISNULL(LIB_NOM_CHARGE_RELATION, '')
         				AS SIGN_CR
         				FROM  #TEMP_REFERENCE AS SIGN
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			/*******page deux entete (le pave 1 le titre)********/
         			(	SELECT @PAVE_1 AS LIB_PAVE1
         				FROM  #TEMP_REFERENCE AS PAVE_1_TITRE 
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			/****** page deux tableau 1 ****/
         
         			(
         				SELECT 
         					dbo.getFrenchCurrencyFormat(ISNULL(@MNT_TOTAL_RESTANT_DU,0)) AS MNT_TOT_RESTANT_DU,
         					dbo.getFrenchCurrencyFormat(ISNULL(@MNT_TOTAL_FACT,0)) AS MNT_TOT_FACTURABLE	
         				FOR XML RAW('PAVE_2_TOTAUX'), ELEMENTS, TYPE
         			),
         
         			( 
         				SELECT 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER,0)) AS DECIMAL(18,2)),0.00)) AS A_FACTURER, 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER_ENTREPRISE,0)) AS DECIMAL(18,2)),0.00)) AS  A_FACTURER_ENTREPRISE
         					FROM #LISTE_TYPEE AS PAVE_2_LIGNE_A
         					WHERE  TYPE_DOSSIER ='A'
         				FOR XML AUTO, ELEMENTS, TYPE				
         			),
         
         			( 
         				SELECT 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER,0)) AS DECIMAL(18,2)),0.00)) AS A_FACTURER, 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER_ENTREPRISE,0)) AS DECIMAL(18,2)),0.00)) AS  A_FACTURER_ENTREPRISE
         					FROM #LISTE_TYPEE AS PAVE_2_LIGNE_B
         					WHERE  TYPE_DOSSIER ='B'
         				FOR XML AUTO, ELEMENTS, TYPE				
         			),
         
         			( 
         				SELECT 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER,0)) AS DECIMAL(18,2)),0.00)) AS A_FACTURER, 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER_ENTREPRISE,0)) AS DECIMAL(18,2)),0.00)) AS  A_FACTURER_ENTREPRISE
         					FROM #LISTE_TYPEE AS PAVE_2_LIGNE_C
         					WHERE  TYPE_DOSSIER ='C'
         				FOR XML AUTO, ELEMENTS, TYPE				
         			),
         
         			( 
         				SELECT 
         					@PARAM_MNT_D AS PARAM_MNT_D,
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER,0)) AS DECIMAL(18,2)),0.00)) AS A_FACTURER, 
         					dbo.getFrenchCurrencyFormat(ISNULL(CAST(SUM(ISNULL(A_FACTURER_ENTREPRISE,0)) AS DECIMAL(18,2)),0.00)) AS  A_FACTURER_ENTREPRISE
         					FROM #LISTE_TYPEE AS PAVE_2_LIGNE_D
         					WHERE  TYPE_DOSSIER ='D'
         				FOR XML AUTO, ELEMENTS, TYPE				
         			),
         
         			(
         				SELECT
         					ISNULL(PAVE_3.COD_ADHERENT, '')				AS COD_ADH,					
         					ISNULL(PAVE_3.LIB_PRENOM_CHARGE_RELATION, '')	AS LIB_PRENOM_CR,					
         					ISNULL(PAVE_3.LIB_NOM_CHARGE_RELATION, '')		AS LIB_NOM_CR
         				FROM #TEMP_REFERENCE AS PAVE_3     
         				FOR XML AUTO, ELEMENTS, TYPE	
         			),
         		
         			---- Safi Ajouter 31/08/2010 ---->  
         			-- PAVE 5 BEGIN
         			(
         				SELECT 'FORMATIONS SANS DELEGATION DE PAIEMENT : DEPENSES A NOUS FACTURER AVEC JUSTIFICATIFS ET ATTESTATIONS DE PRESENCE'	AS PAVE_5_TITRE, 
         					(
         					SELECT										
         						NUM_MODULE_PAVE_6_ENTETE													AS NUM_MODULE_PAVE_5_ENTETE,
         						TYPE_DOSSIER_PAVE_6_ENTETE													AS TYPE_DOSSIER_PAVE_5_ENTETE,
         						LIB_OF_ET_MOD_PEC_PAVE_6_ENTETE												AS LIB_OF_ET_MOD_PEC_PAVE_5_ENTETE,
         						NB_STAG_AVEC_NOM_PAVE_6_ENTETE												AS NB_STAG_AVEC_NOM_PAVE_5_ENTETE,  
         						DT_DEBUT_FORM_PAVE_6_ENTETE 												AS DT_DEBUT_FORM_PAVE_5_ENTETE,
         						DAT_DER_JOUR_ATT_PAVE_6_ENTETE 												AS DAT_DER_JOUR_ATT_PAVE_5_ENTETE,
         						MNT_ENGAGE_PAVE_6_ENTETE 													AS MNT_ENGAGE_PAVE_5_ENTETE,		
         						NB_H_REEL_ET_ENG_PAVE_6_ENTETE 												AS NB_H_REEL_ET_ENG_PAVE_5_ENTETE,		
         						A_FACT_ENTR_PAVE_6_ENTETE 													AS A_FACT_ENTR_PAVE_5_ENTETE,
         						A_FACT_ENTR_TC_CP_PAVE_6_ENTETE 											AS A_FACT_ENTR_TC_CP_PAVE_5_ENTETE,
         						A_FACT_ENTR_TC_REM_PAVE_6_ENTETE 											AS A_FACT_ENTR_TC_REM_PAVE_5_ENTETE,
         						A_FACT_ENTR_TC_FA_PAVE_6_ENTETE 											AS A_FACT_ENTR_TC_FA_PAVE_5_ENTETE,
         						VOTRE_REP_PAVE_6_ENTETE 													AS VOTRE_REP_PAVE_5_ENTETE
         					FROM #PAVE_6_ENTETE AS  PAVE_5_ENTETE  ---- Used the #PAVE_6_ENTETE as it is 99% same.
         					WHERE @ROW_COUNT_PAVE_5 > 0
         					FOR XML AUTO,ELEMENTS, TYPE
         					),
         					(SELECT 
         						NUM_MODULE,
         						TYPE_DOSSIER,
         						LIBL_OF,
         						LIBL_MODULE_PEC, 
         						#LISTE_TYPEE.NB_STAGIAIRES, 
         						ps.NOM_STAGIARE,
         						DATE_DEBUT_STRING,
         						DATE_FIN_STRING,
         						DAT_FIN_SESSION_STRING,
         						dbo.getFrenchCurrencyFormat(ISNULL(MNT_ENGAGE,0)) AS MNT_ENGAGE,
         						dbo.FloatToVarcharSansZeros(NB_HEURE_REEL) AS NB_HEURE_REEL,
         						dbo.FloatToVarcharSansZeros(NB_HEURE_ENGAGE) AS NB_HEURE_ENGAGE,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE,0)) AS A_FACT_ENTR,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_CP,0)) AS A_FACT_ENTR_TC_CP,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_REM,0)) AS A_FACT_ENTR_TC_REM,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_FA,0)) AS A_FACT_ENTR_TC_FA
              				FROM #LISTE_TYPEE
         					INNER JOIN  #premier_stagiaire_par_module_pec ps  on (ps.id_module_pec = #LISTE_TYPEE.id_module_pec)
         					WHERE BLN_DELEGATION_PAIEMENT = 0		
         					ORDER BY TYPE_DOSSIER, 
         					--ASD 20100920 DAT_FIN_SESSION_STRING
         					DATE_FIN_DATE
         					FOR XML RAW('PAVE_5_DETAIL'),ELEMENTS, TYPE
         					)
         				FROM #PAVE_6_ENTETE AS PAVE_5
         				WHERE @ROW_COUNT_PAVE_5 > 0
         				FOR XML AUTO,ELEMENTS, TYPE			
         			),
         	-- PAVE 5 END
         	-- PAVE 6 BEGIN
         			(
         				SELECT 'FORMATIONS AVEC DELEGATION DE PAIEMENT : DEPENSES RESTANT A NOUS FACTURER'	AS PAVE_6_TITRE, 
         					(
         					SELECT										
         						NUM_MODULE_PAVE_6_ENTETE,
         						TYPE_DOSSIER_PAVE_6_ENTETE,
         						LIB_OF_ET_MOD_PEC_PAVE_6_ENTETE,
         						NB_STAG_AVEC_NOM_PAVE_6_ENTETE,  
         						DT_DEBUT_FORM_PAVE_6_ENTETE,
         						DAT_DER_JOUR_ATT_PAVE_6_ENTETE,
         						MNT_ENGAGE_PAVE_6_ENTETE,		
         						NB_H_REEL_ET_ENG_PAVE_6_ENTETE,		
         						A_FACT_ENTR_PAVE_6_ENTETE,
         						A_FACT_ENTR_TC_CP_PAVE_6_ENTETE,
         						A_FACT_ENTR_TC_REM_PAVE_6_ENTETE,
         						A_FACT_ENTR_TC_FA_PAVE_6_ENTETE,
         						VOTRE_REP_PAVE_6_ENTETE
         					FROM #PAVE_6_ENTETE AS  PAVE_6_ENTETE
         					WHERE @ROW_COUNT_PAVE_6 > 0
         					FOR XML AUTO,ELEMENTS, TYPE
         					),
         					(
         					 SELECT 
         						NUM_MODULE,
         						TYPE_DOSSIER,
         						LIBL_OF,
         						LIBL_MODULE_PEC, 
         						#LISTE_TYPEE.NB_STAGIAIRES, 
         						ps.NOM_STAGIARE,
         						DATE_DEBUT_STRING,
         						DATE_FIN_STRING,
         						DAT_FIN_SESSION_STRING,
         						dbo.getFrenchCurrencyFormat(ISNULL(MNT_ENGAGE,0)) AS MNT_ENGAGE,
         						dbo.FloatToVarcharSansZeros(NB_HEURE_REEL ) AS NB_HEURE_REEL,
         						dbo.FloatToVarcharSansZeros(NB_HEURE_ENGAGE ) as NB_HEURE_ENGAGE,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE,0)) AS A_FACT_ENTR,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_CP,0)) AS A_FACT_ENTR_TC_CP,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_REM,0)) AS A_FACT_ENTR_TC_REM,
         						dbo.getFrenchCurrencyFormat(ISNULL(A_FACTURER_ENTREPRISE_TC_FA,0)) AS A_FACT_ENTR_TC_FA
              				FROM #LISTE_TYPEE
         					INNER JOIN #premier_stagiaire_par_module_pec ps  ON (ps.id_module_pec = #LISTE_TYPEE.id_module_pec)
         					WHERE BLN_DELEGATION_PAIEMENT = 1
         					ORDER BY TYPE_DOSSIER, 
         					--ASD 20100920 DAT_FIN_SESSION_STRING
         					DATE_FIN_DATE
         					FOR XML RAW('PAVE_6_DETAIL'),ELEMENTS, TYPE
         					)
         				FROM #PAVE_6_ENTETE AS PAVE_6
         				WHERE @ROW_COUNT_PAVE_6 > 0
         				FOR XML AUTO,ELEMENTS, TYPE			
         			),
         	-- PAVE 6 END
         	-- PAVE 7 BEGIN
         			(
         				SELECT 'LISTE DES PIECES MANQUANTES OU NON CONFORMES'	AS PAVE_7_TITRE, 
         					(
         					SELECT										
         						NUM_MODULE_PAVE_7_ENTETE,	
         						LIBL_PIECE_PEC_PAVE_7_ENTETE,					
         						M_NC_PAVE_7_ENTETE,
         						TYPE_PIECE_PAVE_7_ENTETE
         					FROM #PAVE_7_ENTETE AS  PAVE_7_ENTETE
         					WHERE @ROW_COUNT_PAVE_7 > 0
         					FOR XML AUTO,ELEMENTS, TYPE
         					),
         					(SELECT NUM_MODULE,
         					(SELECT										
         						LIBL_PIECE_PEC,
         						M_NC,
         						TYPE_PIECE
         						FROM #LIST_PIECES_TABLEAU AS PAVE_7_DETAIL_PIECES
         						WHERE PAVE_7_DETAIL_PIECES.NUM_MODULE = PAVE_7_DETAIL.NUM_MODULE
         						FOR XML AUTO,ELEMENTS, TYPE
         					)
         				FROM #LIST_PIECES_TABLEAU AS PAVE_7_DETAIL	
         				GROUP BY NUM_MODULE
         				FOR XML AUTO,ELEMENTS, TYPE)
         				FROM #PAVE_7_ENTETE	AS PAVE_7
         				WHERE @ROW_COUNT_PAVE_7 > 0
         				FOR XML AUTO,ELEMENTS, TYPE			
         			)										
         	-- PAVE 7 END
         		--<--- Safi Ajouter 31/08/2010 ----- 
         		
         -- ne marche pas tant que pied de la page
         --		,
         --		(select 
         --				PAVE_8.LIB_RAISON_SOCIALE, 
         --				case when LEN(PAVE_8.NUM_SIRET)=14 then right(PAVE_8.NUM_SIRET,5)
         --				else '' end as NIC
         --			from  #TEMP_REFERENCE as PAVE_8
         --			FOR XML AUTO, ELEMENTS, TYPE
         --		)
         
         		FROM #TEMP_REFERENCE AS LETTRE
         		FOR XML AUTO, ELEMENTS	
         END
         
GO

         create PROCEDURE [dbo].[EDI_TRANSCO_LEC_GRP_COD_EXTERNE]
         /* Lecture des transcodifications de code externes associees a un adherent pour un referentiel donne */
         (
         @ID_ADHERENT 		INTEGER		,
         @ID_GROUPE 		INTEGER		,
         @COD_TABLE_FAF		VARCHAR(255)	
         )
         AS
         BEGIN
         
         	SET ROWCOUNT 0
         	SET NOCOUNT ON
         	
         	DECLARE @COD_FAF 		VARCHAR(8),
         		@LIBC_FAF 		VARCHAR(20),
         		@COD_EXTERNE_ADHERENT	VARCHAR(255),
         		@ID_TABLE_FAF		INTEGER,
         		@LIB			VARCHAR(2000)
         	SELECT 	COD_EXTERNE_ADHERENT	,
         		ID_TABLE_FAF	
         	INTO #TMP01
         	FROM EDI_TRANSCO_TABLE_ADHERENT
         	WHERE	(
         			ID_GROUPE 	= @ID_GROUPE 
         		OR 	ID_ADHERENT 	= @ID_ADHERENT
         		)
         	AND	@COD_TABLE_FAF 		= COD_TABLE_FAF 
         
         
         	DECLARE cur SCROLL CURSOR FOR
         	SELECT COD_EXTERNE_ADHERENT, ID_TABLE_FAF
         	FROM	#TMP01
         	
         	CREATE TABLE #TMP02
         	(
         		COD_EXTERNE_ADHERENT	VARCHAR(255)	NULL,
         		ID_FAF 			INTEGER		NULL,
         		COD_FAF 		VARCHAR(8)		NULL,
         		LIBC_FAF 		VARCHAR(20)	NULL
         	)
         	OPEN cur
         	FETCH cur INTO @COD_EXTERNE_ADHERENT, @ID_TABLE_FAF
         	WHILE (@@fetch_status <> -1)
         	BEGIN	
         
         		SET @LIB = 'INSERT INTO #TMP02 '
         		SET @LIB = @LIB + 'SELECT ' + CHAR(39) + @COD_EXTERNE_ADHERENT + CHAR(39) + ', ID_' + @COD_TABLE_FAF + ' ID , COD_' + @COD_TABLE_FAF + ' COD , LIBC_' + @COD_TABLE_FAF + ' LIBC  FROM ' + @COD_TABLE_FAF
         		SET @LIB = @LIB + ' WHERE ID_' + @COD_TABLE_FAF + ' = ' + CONVERT(VARCHAR, @ID_TABLE_FAF)
         		EXECUTE (@LIB)
         		
         
         		FETCH cur INTO @COD_EXTERNE_ADHERENT, @ID_TABLE_FAF
         	END
         	
         	CLOSE cur
         	DEALLOCATE cur
         	
         	SELECT #TMP01.COD_EXTERNE_ADHERENT	,
         	       #TMP02.ID_FAF			,
         	       #TMP02.COD_FAF			,
         	       #TMP02.LIBC_FAF				
         	FROM #TMP01, #TMP02
         	WHERE	#TMP01.COD_EXTERNE_ADHERENT= #TMP02.COD_EXTERNE_ADHERENT  COLLATE Latin1_General_BIN
         	ORDER BY #TMP01.COD_EXTERNE_ADHERENT	
         	
         END
         
         
GO

         -- =============================================
         -- Author			: DSZ
         -- Creation date	: 03/05/2012
         -- Description		: bas‚ sur lec_grp_trasaction. 
         -- Transaction pour sous-type donn‚ et pour les ‚tablissements et ‚tabs OF pass‚s en parametre
         -- … am‚liorer encore plus si on n'a plus besoin de @TransactionFinder (toutes les transactions passent … strict)
         -- si transaction existe mais sans contact, on laisse le contact vide.
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_TRANSACTION_ETABLISSEMENT]
         	@ID_TYPE_TRANSACTION			int,			-- Type de la transaction
         	@ID_SOUS_TYPE_TRANSACTION		int,			-- Sous type de la transaction
         	@ID_ACTIVITE					int,			-- Activit‚ de la transaction
         	@BLN_ACTIF						tinyint = 1,	-- Etat de la transaction
         	@TransactionFinder				tinyint = 1,		-- 1 : Normal | 2 : Strict | 3 : NormalButStrict
         	@LIST_ETABS						varchar(2000),
         	@LIST_ETABS_OF					varchar(2000)
         	
         AS
         begin
         	declare @ST_REGLEMENT int
         	declare @ST_REGELEMNT_COPIE int
         
         	select @ST_REGLEMENT=id_sous_type_transaction from sous_type_transaction where cod_sous_type_transaction='REGLEMT'
         	select @ST_REGELEMNT_COPIE=id_sous_type_transaction from sous_type_transaction where cod_sous_type_transaction='CPY_REGL'
         	
         	select * into #etabs from F_SPLIT(@LIST_ETABS, ',')
         	select * into #etabs_of from F_SPLIT(@LIST_ETABS_OF, ',')
         	
         		--S‚lection des transactions "g‚n‚riques"
         	select 
         		[TRANSACTION].ID_ADRESSE,
         		[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF,
         		[TRANSACTION].ID_TIERS_BENEF,
         		[TRANSACTION].ID_ETABLISSEMENT_BENEF,
         		[TRANSACTION].ID_CONTACT,
         		[TRANSACTION].ID_ETABLISSEMENT_OF_DEST,
         		[TRANSACTION].ID_ETABLISSEMENT_DEST,
         		[TRANSACTION].ID_TRANSACTION,
         		[TRANSACTION].ID_TYPE_TRANSACTION,
         		[TRANSACTION].ID_SOUS_TYPE_TRANSACTION,
         		[TRANSACTION].ID_ACTIVITE,
         		[TRANSACTION].BLN_ACTIF,
         		[TRANSACTION].NUM_IBAN,
         		[TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL,
         		[TRANSACTION].BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE,
         		[TRANSACTION].ID_MODE_ENVOI_DOC,
         			(case when ID_TYPE_TRANSACTION is null then 0 else 1 end +
         			case when ID_SOUS_TYPE_TRANSACTION is null then 0 else 1 end +
         			case when ID_ACTIVITE is null then 0 else 1 end)
         		 as NIVEAU_PRECISION --ajout DSZ 15/07/2010 12448 
         	into
         		#TMP_NORMAL
         	from
         		[TRANSACTION]
         	where
         		((@ID_TYPE_TRANSACTION is null) or (([TRANSACTION].ID_TYPE_TRANSACTION = @ID_TYPE_TRANSACTION) or ([TRANSACTION].ID_TYPE_TRANSACTION is null)))
         		and	((@ID_SOUS_TYPE_TRANSACTION is null) or (([TRANSACTION].ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION) or ([TRANSACTION].ID_SOUS_TYPE_TRANSACTION is null)))
         		and	((@ID_ACTIVITE is null) or (([TRANSACTION].ID_ACTIVITE = @ID_ACTIVITE) or ([TRANSACTION].ID_ACTIVITE is null)))
         		and	[TRANSACTION].BLN_ACTIF >= @BLN_ACTIF
         		and
         		(
         			[TRANSACTION].ID_SOUS_TYPE_TRANSACTION is null
         			or 
         			[TRANSACTION].ID_SOUS_TYPE_TRANSACTION not in (@ST_REGLEMENT, @ST_REGELEMNT_COPIE)
         		)
         		and 
         		(
         			[TRANSACTION].ID_ETABLISSEMENT_OF_DEST in (select data from #etabs_of)
         			or
         			[TRANSACTION].ID_ETABLISSEMENT_DEST in (select data from #etabs)
         		)
         	
         
         		CREATE TABLE #TRAN_FINAL (
         		[ID_ADRESSE] int NULL,
         		[ID_ETABLISSEMENT_OF_BENEF] int NULL,
         		[ID_TIERS_BENEF] int NULL,
         		[ID_ETABLISSEMENT_BENEF] int NULL,
         		[ID_CONTACT] int NULL,
         		[ID_ETABLISSEMENT_OF_DEST] int NULL,
         		[ID_ETABLISSEMENT_DEST] int NULL,
         		[ID_TRANSACTION] [int] NULL,
         		[ID_TYPE_TRANSACTION] int NULL,
         		[ID_SOUS_TYPE_TRANSACTION] int NULL,
         		[ID_ACTIVITE] int NULL,
         		[BLN_ACTIF] tinyint NULL,
         		[NUM_IBAN] varchar(34) NULL,
         		[BLN_TRANSACTION_REGLEMENT_PRINCIPAL] tinyint NULL,
         		[BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE] tinyint NULL,
         		[ID_MODE_ENVOI_DOC] int NULL,
         		[NIVEAU_PRECISION] tinyint null)
         		
         	if (@TransactionFinder <> 1)
         		begin
         			-- S‚lection des transaction r‚pondant strictement au filtre
         			select 
         				[TRANSACTION].ID_ADRESSE,
         				[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF,
         				[TRANSACTION].ID_TIERS_BENEF,
         				[TRANSACTION].ID_ETABLISSEMENT_BENEF,
         				[TRANSACTION].ID_CONTACT,
         				[TRANSACTION].ID_ETABLISSEMENT_OF_DEST,
         				[TRANSACTION].ID_ETABLISSEMENT_DEST,
         				[TRANSACTION].ID_TRANSACTION,
         				[TRANSACTION].ID_TYPE_TRANSACTION,
         				[TRANSACTION].ID_SOUS_TYPE_TRANSACTION,
         				[TRANSACTION].ID_ACTIVITE,
         				[TRANSACTION].BLN_ACTIF,
         				[TRANSACTION].NUM_IBAN,
         				[TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL,
         				[TRANSACTION].BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE,
         				[TRANSACTION].ID_MODE_ENVOI_DOC,
         					(case when ID_TYPE_TRANSACTION is null then 0 else 1 end +
         					case when ID_SOUS_TYPE_TRANSACTION is null then 0 else 1 end +
         					case when ID_ACTIVITE is null then 0 else 1 end)
         				as NIVEAU_PRECISION  --ajout DSZ 15/07/2010 12448 
         			into
         				#TMP_STRICT
         			from
         				[TRANSACTION]
         				left join NR31 on (NR31.ID_ETABLISSEMENT = [TRANSACTION].ID_ETABLISSEMENT_DEST)
         				left join NR34 on (NR34.ID_ETABLISSEMENT_OF = [TRANSACTION].ID_ETABLISSEMENT_OF_DEST)
         			where
         				((@ID_TYPE_TRANSACTION is null) or (([TRANSACTION].ID_TYPE_TRANSACTION = @ID_TYPE_TRANSACTION)))
         				and	((@ID_SOUS_TYPE_TRANSACTION is null) or ([TRANSACTION].ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION))
         				and	((@ID_ACTIVITE is null) or ([TRANSACTION].ID_ACTIVITE = @ID_ACTIVITE))
         				and	[TRANSACTION].BLN_ACTIF >= @BLN_ACTIF
         				and
         				(
         					[TRANSACTION].ID_SOUS_TYPE_TRANSACTION is null
         					or [TRANSACTION].ID_SOUS_TYPE_TRANSACTION not in (@ST_REGLEMENT, @ST_REGELEMNT_COPIE)
         				)
         				and 
         				(
         					[TRANSACTION].ID_ETABLISSEMENT_OF_DEST in (select data from #etabs_of)
         					or
         					[TRANSACTION].ID_ETABLISSEMENT_DEST in (select data from #etabs)
         				)
         			
         			
         			if (@TransactionFinder <> 2)
         				begin
         					-- Transactions "NormalButStrict"
         					insert into #TRAN_FINAL 
         					select * from #TMP_NORMAL
         					except
         					select * from #TMP_STRICT
         				end
         			else
         				begin
         					-- Transactions "Strict"
         					insert into #TRAN_FINAL select *  from #TMP_STRICT
         				end
         		end
         	else
         		begin
         			-- Transactions "Normal"
         			insert into #TRAN_FINAL select * from #TMP_NORMAL
         		end
         		
         	-- gestion des contacts		
         
         	select 
         		#TRAN_FINAL.ID_ADRESSE,
         		#TRAN_FINAL.ID_ETABLISSEMENT_OF_BENEF,
         		#TRAN_FINAL.ID_TIERS_BENEF,
         		#TRAN_FINAL.ID_ETABLISSEMENT_BENEF,
         		#TRAN_FINAL.ID_CONTACT,
         		#TRAN_FINAL.ID_ETABLISSEMENT_OF_DEST,
         		#TRAN_FINAL.ID_ETABLISSEMENT_DEST,
         		#TRAN_FINAL.ID_TRANSACTION,
         		#TRAN_FINAL.ID_TYPE_TRANSACTION,
         		#TRAN_FINAL.ID_SOUS_TYPE_TRANSACTION,
         		#TRAN_FINAL.ID_ACTIVITE,
         		#TRAN_FINAL.BLN_ACTIF,
         		#TRAN_FINAL.NUM_IBAN,
         		#TRAN_FINAL.BLN_TRANSACTION_REGLEMENT_PRINCIPAL,
         		#TRAN_FINAL.BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE,
         		#TRAN_FINAL.ID_MODE_ENVOI_DOC, 
         			(case when ID_TYPE_TRANSACTION is null then 0 else 1 end +
         			case when ID_SOUS_TYPE_TRANSACTION is null then 0 else 1 end +
         			case when ID_ACTIVITE is null then 0 else 1 end)
         		 as NIVEAU_PRECISION 
         	from
         		#TRAN_FINAL
         	union --les contacts pour les etabs qui n'ont pas de transaction
         	select 
         		
         		NR31.ID_ADRESSE ,
         		null as ID_ETABLISSEMENT_OF_BENEF,
         		null as ID_TIERS_BENEF,
         		NR31.ID_ETABLISSEMENT as ID_ETABLISSEMENT_BENEF,
         		NR31.ID_CONTACT,
         		null as ID_ETABLISSEMENT_OF_DEST,
         		NR31.ID_ETABLISSEMENT as ID_ETABLISSEMENT_DEST,
         		null as ID_TRANSACTION,
         		null as ID_TYPE_TRANSACTION,
         		null as ID_SOUS_TYPE_TRANSACTION,
         		null as ID_ACTIVITE,
         		null as BLN_ACTIF,
         		null as NUM_IBAN,
         		null as BLN_TRANSACTION_REGLEMENT_PRINCIPAL,
         		1	 as BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE,
         		1 as ID_MODE_ENVOI_DOC,
         		0 as  NIVEAU_PRECISION 
         	from
         		#etabs
         			inner join NR31 on NR31.ID_ETABLISSEMENT = #etabs.data
         	where 
         			NR31.ID_ETABLISSEMENT not in  (select coalesce(ID_ETABLISSEMENT_DEST,0) from #TRAN_FINAL) and --coalesce trŠs important ici, car ne marche pas si tran_final n'est pas vide mais id_etab_dest est null
         			NR31.BLN_PRINCIPAL =1 and  
         			NR31.BLN_ACTIF = 1
         			
         	union		--les contact pour les etabs OF qui n'ont pas de transaction
         	select 
         		
         		NR34.ID_ADRESSE,
         		NR34.ID_ETABLISSEMENT_OF  as ID_ETABLISSEMENT_OF_BENEF,
         		null as ID_TIERS_BENEF,
         		null as ID_ETABLISSEMENT_BENEF,
         		NR34.ID_CONTACT,
         		NR34.ID_ETABLISSEMENT_OF  as ID_ETABLISSEMENT_OF_DEST,
         		null as ID_ETABLISSEMENT_DEST,
         		null as ID_TRANSACTION,
         		null as ID_TYPE_TRANSACTION,
         		null as ID_SOUS_TYPE_TRANSACTION,
         		null as ID_ACTIVITE,
         		null as BLN_ACTIF,
         		null as NUM_IBAN,
         		null as BLN_TRANSACTION_REGLEMENT_PRINCIPAL,
         		1	 as BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE,
         		1 as ID_MODE_ENVOI_DOC,
         		0 as  NIVEAU_PRECISION 
         	from
         		#etabs_of
         			inner join NR34 on NR34.ID_ETABLISSEMENT_OF = #etabs_of.data
         	where 
         			NR34.ID_ETABLISSEMENT_OF not in  (select coalesce(ID_ETABLISSEMENT_OF_DEST,0) from #TRAN_FINAL) and 
         			NR34.BLN_PRINCIPAL =1 and  
         			NR34.BLN_ACTIF = 1
         	
         
         end
GO
CREATE PROCEDURE [dbo].[INS_MODULE_PRO]  
          @ID_MODULE_PRO    int OUTPUT, 
          @COD_MODULE_PRO    varchar(10),
          @BLN_ACTIF     tinyint = 1, 
          @BLN_SUBROGE    tinyint = 0,
          @ID_UTILISATEUR    int, 
          @DAT_DEBUT     datetime, 
          @DAT_FIN     datetime, 
          @NB_UNITE_FORMATION   decimal(18,2), 
          @NB_UNITE_EVALUATION  decimal(18,2), 
          @NB_UNITE_ACCOMPAGNEMENT decimal(18,2), 
          @TAUX_HORAIRE_MODULE  decimal(18,2), 
          @TAUX_HORAIRE_DEMANDE_OF decimal(18,2), 
          @TAUX_HORAIRE_RETENU_OF  decimal(18,2), 
          @TAUX_HORAIRE_RETENU_ADH decimal(18,2), 
          @MNT_MODULE_HT    decimal(18,2), 
          @MNT_DEMANDE_ADH   decimal(18,2),
          @BLN_PRINCIPAL    tinyint = 0, 
          @ID_CONTRAT_PRO    int, 
          @ID_ETABLISSEMENT_OF  int, 
          @ID_THEME     int, 
          @ID_TYPE_FORMATION   int, 
          @ID_ENGAGEMENT_PRO   int, 
          @BLN_OK_PIECE    tinyint, 
          @ID_FORMACODE    int, 
          @LIBL_MODULE_PRO   varchar(250), 
          @NB_UNITE_TOTALE   decimal(18,2)  = 0, 
          @COM_MODULE_PRO    varchar(255),
          @ID_STAGE     int,
          @BLN_EXTERNE    tinyint,
          @MNT_CONVENTION    decimal(18,2),
          @NB_UNITE_TOTAL_FORMATION decimal(18,2),
          @TAUX_PLAFOND_OF   decimal(18,2)
         
         AS  
          BEGIN
           SET QUOTED_IDENTIFIER ON
         
           DECLARE @COUNT    INT
           DECLARE @ID_PERIODE   INT
         
           IF(@COD_MODULE_PRO IS NULL)
           BEGIN
            SET @COUNT = 0
            SET @COD_MODULE_PRO = ''
         
            SELECT @COUNT    = COUNT(ID_MODULE_PRO) +1     FROM MODULE_PRO  WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO
            SELECT @COD_MODULE_PRO  = RIGHT(COD_CONTRAT_PRO, 8) FROM CONTRAT_PRO WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO
            SELECT @COD_MODULE_PRO = @COD_MODULE_PRO+(CASE WHEN @COUNT <= 9 THEN '0'+CAST(@COUNT AS VARCHAR(1)) ELSE CAST(@COUNT AS VARCHAR(2)) END)
           END
         
           SELECT  @ID_PERIODE = PERIODE.ID_PERIODE FROM PERIODE WHERE DATEPART(YEAR, GETDATE()) = PERIODE.NUM_ANNEE AND ID_TYPE_PERIODE = 1
         
           IF @ID_STAGE = -1
            SET @ID_STAGE = null
         
           INSERT INTO MODULE_PRO
           (
            COD_MODULE_PRO, 
            BLN_SUBROGE, 
            DAT_DEBUT,  DAT_FIN, 
            NB_UNITE_FORMATION, NB_UNITE_EVALUATION, 
            NB_UNITE_ACCOMPAGNEMENT, 
            TAUX_HORAIRE_MODULE, TAUX_HORAIRE_DEMANDE_OF, 
            TAUX_HORAIRE_RETENU_OF, TAUX_HORAIRE_RETENU_ADH, 
            MNT_MODULE_HT, 
            MNT_DEMANDE_ADH,
            BLN_PRINCIPAL,  BLN_ACTIF, 
            DAT_MODIF,   DAT_CREATION, 
            ID_UTILISATEUR,  ID_CONTRAT_PRO, 
            ID_ETABLISSEMENT_OF,ID_THEME, 
            ID_TYPE_FORMATION, ID_ENGAGEMENT_PRO, 
            BLN_OK_PIECE, 
            ID_FORMACODE, 
            LIBL_MODULE_PRO, NB_UNITE_TOTALE, 
            COM_MODULE_PRO, ID_PERIODE,
            ID_STAGE,
            BLN_EXTERNE, MNT_CONVENTION, NB_UNITE_TOTAL_FORMATION,TAUX_PLAFOND_OF
           )
           VALUES 
           (
            @COD_MODULE_PRO,
            @BLN_SUBROGE, 
            @DAT_DEBUT,  @DAT_FIN, 
            @NB_UNITE_FORMATION, @NB_UNITE_EVALUATION, 
            @NB_UNITE_ACCOMPAGNEMENT, 
            @TAUX_HORAIRE_MODULE, @TAUX_HORAIRE_DEMANDE_OF, 
            @TAUX_HORAIRE_RETENU_OF, @TAUX_HORAIRE_RETENU_ADH, 
            @MNT_MODULE_HT, @MNT_DEMANDE_ADH,
            @BLN_PRINCIPAL,  @BLN_ACTIF, 
            getdate(),   getdate(), 
            @ID_UTILISATEUR,  @ID_CONTRAT_PRO, 
            case when (@ID_ETABLISSEMENT_OF = 0) then null ELSE @ID_ETABLISSEMENT_OF end,
            case when (@ID_THEME = 0)    then null ELSE @ID_THEME end, 
            @ID_TYPE_FORMATION,  @ID_ENGAGEMENT_PRO, 
            @BLN_OK_PIECE, 
            @ID_FORMACODE, 
            @LIBL_MODULE_PRO, @NB_UNITE_TOTALE, 
            @COM_MODULE_PRO,@ID_PERIODE,@ID_STAGE, @BLN_EXTERNE, @MNT_CONVENTION, @NB_UNITE_TOTAL_FORMATION,@TAUX_PLAFOND_OF
            
           )
           SET @ID_MODULE_PRO = @@IDENTITY
           RETURN @@IDENTITY
          END
GO
CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_ENGAGEMENT_OF]
          @ID_ETABLISSEMENT  int, --Attention ici ID_ETABLISSEMENT est l'id etablissement de l'O.F
          @ID_BENEFICIAIRE  int, -- et Beneficiare ‚galement = ‚tablissement OF
          @ID_ADRESSE    int,
          @ID_CONTACT    int,
          @COD_MODULE_PEC   varchar(14),
          @MODE     int -- 1 DifPortable, 2 CSP, 3 POE, 4 Autre
         AS
         
         -- =============================================
         -- Author  : XXX
         -- Date   : XX XXXX 2007
         -- Description : Cr‚ation
         -- =============================================
         -- Author  : SBR
         -- Date   : 21/05/08
         -- Description : La partie Emetteur est renseign‚e … partir de la fonction GetXmlAdrUtil (au lieu de GetXmlAgenceContact)
         -- =============================================
         -- Author  : SBR
         -- Date   : 09/06/08
         -- Description : Suppression jointure sur @ID_ETABLISSEMENT
         -- (@ID_ETABLISSEMENT est en fait ID_ETABLISSEMENT_OF)
         --==============================================
         -- Author  : AMA
         -- Date   : 08/09/08
         -- Description : R‚‚criture de la proc‚dure sur la base d'une nouvelle matrice d'‚dition
         --==========================================================================================================================================
         -- le 29/12/08 par SBR - correction mauvaise gestion des actions collectives.
         --==========================================================================================================================================
         -- le 25/02/09 par SBR - suppression filtre sur MODULE_PEC.DAT_LETTRE_PEC_ENGAGEMENT_OF suite … correction nouvelle ‚dition aprŠs d‚sengagement
         --==========================================================================================================================================
         -- le 26/02/09 par SBR - Adaptation format suite au groupe de travail sur les ‚ditions
         --==========================================================================================================================================
         -- le 02/12/09 par SBR - Nouvelle rŠgle de gestion pour le calcul de la date limite de fourniture des documents: si date fin module >= date du jour alors date limite = date fin module + 15 jours sinon date limite = date du jour + 15 jours
         --==========================================================================================================================================
         -- le 28/02/11 par SBR - Ajout nveau STC subrog‚ "Repas factur‚s/OF"
         --==========================================================================================================================================
         -- Le 18/09/12 par DSZ - 13697 Ajout num tel de l'emetteur
         -- =========================================================================================================================================
         -- Le 08/11/12 par LDE - 14239: SUPPRESSION DES SALARIES SUR LES ACCORDS DE PRISE EN CHARGE
         -- =========================================================================================================================================
         -- Le 18/02/13 par DSZ - 14832 : suppression Signature
         -- =========================================================================================================================================
         -- Le 23/05/13 par OPA et LDE - 14671 : DNE - [Demandeur d'emploi] - (2) -: Mise … jour et Compl‚ment … l'‚dition accord pec OF : Conventions CSP
         -- =========================================================================================================================================
         -- Le 12/07/13 par DSZ - 15508 : remplacer ETABLISSEMENT par la concatenation des adherents et codes; ajout PERIODE_MODULE1
         -- =========================================================================================================================================
         -- Le 23/07/13 par DSZ - 15602 : message d'erreur division par 0: le premier stagiare doit ˆtre celui que … heures engag‚s > 0
           -- 15617 prendre cod postal et ville d'adresse si pas d'hexaposte
         -- =========================================================================================================================================
         -- Le 24/07/13 par HBO - 15624: DNE - Courrier accord OF - Manque Nø et BIS et Nom de voieAdresse destinataire
         -- =========================================================================================================================================
         -- Le 24/07/13 par DSZ - 15628: sous-type de co–t : "Co–t p‚dagoqique"  remplac‚ par TYPE DE COUT : "Cout P‚dagogique"
         -- =========================================================================================================================================
         -- Le 26/07/13 par TLE - 15628: sous-type de co–t : "Co–t p‚dagoqique"  remplac‚ par TYPE DE COUT : "Cout P‚dagogique" => somme des sous types de cout
         -- =========================================================================================================================================
         -- Le 14/08/13 par OPA - 15658: IBO - Correction … apporter sur courrier OF CSP et POE
         -- =========================================================================================================================================
         -- Le 16/01/14 par OPA - 15637: DNE - Courrier accord OF - demande d'ajout d'une phrase … l'‚dition : "Courrier accord OF autre"
         -- =========================================================================================================================================
         -- LDE 23/05/2014 #213
         -- =========================================================================================================================================
         -- DSZ 02/06/2014 #361
         -- =========================================================================================================================================
         -- DSZ 13/06/2014 #73
         -- =========================================================================================================================================
         -- DSZ 13/06/2014 #369
         -- =========================================================================================================================================
         -- DSZ 12/05/2015 #328 g‚rer le cas o— le b‚n‚ficiaire est un ‚tablissement OF diff‚rent de l'‚tablissement OF destinataire
         -- =========================================================================================================================================
         
         
         
         BEGIN
         
          -- Recherche de l'identifiant du module pec … partir de son code
          DECLARE @ID_MODULE_PEC INT
          SELECT @ID_MODULE_PEC = ID_MODULE_PEC FROM MODULE_PEC WHERE COD_MODULE_PEC = @COD_MODULE_PEC;
          
           -- Contact principal par d‚faut mais pas de "."
          IF @ID_CONTACT IS NULL
           SELECT @ID_CONTACT = NR34.ID_CONTACT
           FROM NR34 
           INNER JOIN CONTACT ON CONTACT.ID_CONTACT = NR34.ID_CONTACT
           WHERE BLN_PRINCIPAL = 1
           AND BLN_ACTIF = 1
           AND ID_ETABLISSEMENT_OF = @ID_BENEFICIAIRE
           AND CONTACT.LIB_NOM_CONTACT <> '.';
           
           
         --============================B‚n‚ficiaire===============================
          
          SELECT 
           OFO.LIB_RAISON_SOCIALE,
           COALESCE(CAST(a.NUM_VOIE AS VARCHAR(5)) + ' '+tv.LIBL_TYPE_VOIE + ' ' + a.LIB_NOM_VOIE,a.LIB_ADR) AS LIB_ADR,
           CIVILITE.LIBC_CIVILITE,  
           CONTACT.LIB_PNM_CONTACT, 
           CONTACT.LIB_NOM_CONTACT ,
           A.LIB_COMP_VOIE,
           A.LIB_MENTION_PARTICULIERE,
           coalesce(H.COD_POSTAL, A.LIB_CP_CEDEX)   AS LIB_CP_CEDEX,
           coalesce(H.LIB_ACHEMINEMENT, A.LIB_VIL_CEDEX) AS LIB_VIL_CEDEX,
           OFO.LIB_RAISON_SOCIALE AS NOM_OF,
           EOF.NUM_SIRET AS SIRET,
           EOF.LIB_NUM_DECLARATION AS NUM_ACTIVITE  
          INTO #TMP_BENEFICIAIRE
          FROM ETABLISSEMENT_OF EOF 
          INNER JOIN ORGANISME_FORMATION OFO ON OFO.ID_OF = EOF.ID_OF
          INNER JOIN ADRESSE A ON A.ID_ADRESSE = EOF.ID_ADRESSE_PRINCIPALE
          INNER JOIN TYPE_VOIE TV ON TV.ID_TYPE_VOIE = A.ID_TYPE_VOIE
          LEFT JOIN HEXAPOSTE H ON H.ID_HEXAPOSTE = A.ID_HEXAPOSTE
          LEFT JOIN CONTACT on CONTACT.ID_CONTACT = @ID_CONTACT
          LEFT JOIN CIVILITE on CONTACT.ID_CIVILITE = CIVILITE.ID_CIVILITE  
          WHERE EOF.ID_ETABLISSEMENT_OF = @ID_BENEFICIAIRE
         
         --=======================================================================
         
         --==========================Entˆte=======================================
         
         
         
          -- Si action individuelle: CR de l'‚tablissement et CM de l'‚tablissement
          -- Si action collective: CR = CM = responsable des actions collectives renseign‚ dans le champ CM au niveau de l'action
          SELECT DISTINCT -- disctinct n‚cessaire pour la gestion correcte des acions collectives
            CR.ID_UTILISATEUR AS ID_UTIL,
            CR.LIB_PNM   AS LIB_PRENOM_CHARGE_RELATION,
            UPPER(CR.LIB_NOM) AS LIB_NOM_CHARGE_RELATION,
            CR.LIB_VILLE,
            CR.EMAIL   AS EMAIL_CHARGE_RELATION,
            ORGANISME_FORMATION.COD_OF
          INTO #TMP_ENTETE
          FROM ADHERENT 
          INNER JOIN ETABLISSEMENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
          INNER JOIN NR140 ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
          INNER JOIN ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
          INNER JOIN MODULE_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC AND MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
          LEFT  JOIN  ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
          LEFT  JOIN  ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
          LEFT  JOIN  UTILISATEUR CR -- charg‚ de relation ou responsable des actions collectives
          ON CASE WHEN (ACTION_PEC.CIBLE_ACTION = 1 OR ACTION_PEC.BLN_REPRISE_ADHOC = 1)
             THEN ETABLISSEMENT.ID_CHARGEE_RELATION
             ELSE ACTION_PEC.ID_CHARGEE_MISSION 
           END = CR.ID_UTILISATEUR
          LEFT JOIN  UTILISATEUR CM -- charg‚ de mission ou responsable des actions collectives
          ON CASE WHEN (ACTION_PEC.CIBLE_ACTION = 1 OR ACTION_PEC.BLN_REPRISE_ADHOC = 1)
            THEN ETABLISSEMENT.ID_CHARGEE_MISSION
            ELSE ACTION_PEC.ID_CHARGEE_MISSION
           END = CM.ID_UTILISATEUR;
         
         --=======================================================================
         
         --==========================Corps========================================
         
         --attention, le suivant marche si pas beaucoup des valeurs, ce qui est … priori le cas. test‚ pour 10 adherents ok, mais si jamais pose des soucis,
         --il faut opter pour un curseur. au pire ‡a retournera juste une seul valeur
          declare @ADHERENTS varchar(500);
          with adh as
          (
           select distinct
            cast(cod_adherent as varchar(6)) +' '+ lib_raison_sociale as nom
           from STAGIAIRE_PEC 
           inner join ETABLISSEMENT   on ETABLISSEMENT.ID_ETABLISSEMENT   = STAGIAIRE_PEC.ID_ETABLISSEMENT  
           inner join ADHERENT on ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT  
           where ID_MODULE_PEC = @ID_MODULE_PEC 
          )
         
          SELECT @ADHERENTS =  COALESCE(@ADHERENTS + ', ', '') + nom 
          FROM adh
         
          SELECT 
            M.LIBL_MODULE_PEC AS NOM,
            CONVERT(VARCHAR(10), m.DAT_DEBUT, 3) AS DATE_DEBUT,
            CONVERT(VARCHAR(10), m.DAT_FIN, 3) AS DATE_FIN,
            coalesce(H.COD_POSTAL, A.LIB_CP_CEDEX)   AS CP_ETAB_OF,
            coalesce(H.LIB_ACHEMINEMENT, A.LIB_VIL_CEDEX) AS VILLE_ETAB_OF,
            'du ' + CONVERT(VARCHAR(8), m.DAT_DEBUT, 3) + ' au ' + CONVERT(VARCHAR(8), m.DAT_FIN, 3) + ' ' + CONVERT(VARCHAR(15), m.NUM_DUREE_HEURE) + ' h' AS DATE_DUREE,
            DBO.GETFRENCHCURRENCYFORMAT(CAST(COALESCE(ms.COUT,0) AS MONEY)) + ' ? HT' AS COUT,
            CASE
             WHEN COALESCE(mr.COUT_REPOF,0) >0
              THEN '+ '+ DBO.GETFRENCHCURRENCYFORMAT(CAST(COALESCE(mr.COUT_REPOF,0) AS MONEY))+ '? (repas)'
             ELSE  ''
            END AS COUT_REPOF,
            COALESCE(ms.MNT_PREVISIONNEL_HT,0) AS MNT_PREVISIONNEL_HT,
            CAST(M.NUM_DUREE_HEURE AS DECIMAL(8,2)) DUREE,
            P.NUM_ANNEE AS PERIODE_MODULE,
            (P.NUM_ANNEE+1) AS PERIODE_SUIVANTE
          INTO #TMP_FORMATION
          FROM MODULE_PEC AS M
          INNER JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = M.ID_ETABLISSEMENT_OF
          INNER JOIN
          (SELECT m.ID_MODULE_PEC, SUM (pce.MNT_PREVISIONNEL_HT) as MNT_PREVISIONNEL_HT, SUM (pce.MNT_ENGAGE_HT) as COUT
          FROM
           MODULE_PEC m 
           INNER JOIN POSTE_COUT_ENGAGE pce ON m.ID_MODULE_PEC = pce.ID_MODULE_PEC
           INNER JOIN SOUS_TYPE_COUT stc ON pce.ID_SOUS_TYPE_COUT = stc.ID_SOUS_TYPE_COUT
           INNER JOIN TYPE_COUT tc ON tc.ID_TYPE_COUT = stc.ID_TYPE_COUT AND tc.COD_TYPE_COUT = 'CP'
          GROUP BY
           m.ID_MODULE_PEC 
          ) AS ms ON m.ID_MODULE_PEC = ms.ID_MODULE_PEC
          LEFT JOIN
          (SELECT m.ID_MODULE_PEC, SUM (pce.MNT_PREVISIONNEL_HT) as MNT_PREVISIONNEL_HT, SUM (pce.MNT_ENGAGE_HT) as COUT_REPOF
          FROM
           MODULE_PEC m 
           INNER JOIN POSTE_COUT_ENGAGE pce ON m.ID_MODULE_PEC = pce.ID_MODULE_PEC
           INNER JOIN SOUS_TYPE_COUT stc ON pce.ID_SOUS_TYPE_COUT = stc.ID_SOUS_TYPE_COUT AND stc.COD_SOUS_TYPE_COUT = 'REPOF'
          GROUP BY
           m.ID_MODULE_PEC 
          ) AS mr ON m.ID_MODULE_PEC = mr.ID_MODULE_PEC 
          INNER JOIN ADRESSE A ON A.ID_ADRESSE = ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE
          INNER JOIN TYPE_VOIE TV ON TV.ID_TYPE_VOIE = A.ID_TYPE_VOIE
          LEFT  JOIN HEXAPOSTE H ON H.ID_HEXAPOSTE = A.ID_HEXAPOSTE
          INNER JOIN PERIODE P ON P.ID_PERIODE = M.ID_PERIODE
          WHERE M.ID_MODULE_PEC = @ID_MODULE_PEC
         
          
          SELECT T2.NOM_INDIVIDU  AS NOM_STAGIAIRE,
            T2.PRENOM_INDIVIDU AS PRENOM_STAGIAIRE
          INTO #TMP_STAGIAIRE
          FROM STAGIAIRE_PEC T1 
          INNER JOIN INDIVIDU T2 ON T1.ID_INDIVIDU = T2.ID_INDIVIDU
          WHERE T1.ID_MODULE_PEC = @ID_MODULE_PEC 
          -- SESSION NON RALISE
          AND  T1.ID_SESSION_PEC IS NULL
          AND  T1.NB_HEURE_ENGAGE > 0;    -- LDE 08/11/2012 #14239 
          
          -- Recherche le nom de l'organisme de formation
          DECLARE @NOM_OF VARCHAR(64)
          SELECT @NOM_OF = LIB_RAISON_SOCIALE FROM #TMP_BENEFICIAIRE;
          
         --=======================================================================
         
         --==========================Convention===================================
         
          SELECT TOP 1
          ST.ID_STAGIAIRE_PEC,
          CASE WHEN I.BLN_MASCULIN = 1
           THEN 'Monsieur'
           ELSE 'Madame'
          END AS CIVILITE,
          I.PRENOM_INDIVIDU AS PRENOM,
          I.NOM_INDIVIDU AS NOM,
          CAST(a.NUM_VOIE AS VARCHAR(5)) + ' ' + tv.LIBL_TYPE_VOIE + ' ' + a.LIB_NOM_VOIE AS ADRESSE1,
          A.LIB_COMP_VOIE AS ADRESSE2,
          H.COD_POSTAL AS CP,
          H.LIB_ACHEMINEMENT AS VILLE
          INTO #TMP_PREMIER_STAGIAIRE    
          FROM STAGIAIRE_PEC ST  
          INNER JOIN SALARIE SA ON SA.ID_INDIVIDU = ST.ID_INDIVIDU AND SA.ID_ETABLISSEMENT = ST.ID_ETABLISSEMENT
          INNER JOIN INDIVIDU I ON I.ID_INDIVIDU = ST.ID_INDIVIDU
          LEFT JOIN ADRESSE A ON A.ID_ADRESSE = SA.ID_ADRESSE
          LEFT JOIN TYPE_VOIE TV ON TV.ID_TYPE_VOIE = A.ID_TYPE_VOIE
          LEFT JOIN HEXAPOSTE H ON H.ID_HEXAPOSTE = A.ID_HEXAPOSTE 
          WHERE ST.ID_MODULE_PEC = @ID_MODULE_PEC
          and ST.NB_HEURE_ENGAGE > 0
         
          
          
          DECLARE @SS_TYPE_COUT INT
          DECLARE @NB_HEURES INT
          
          SELECT 
           @SS_TYPE_COUT = (POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT / STAGIAIRE_PEC.NB_HEURE_ENGAGE),
           @NB_HEURES = STAGIAIRE_PEC.NB_HEURE_ENGAGE
          FROM STAGIAIRE_PEC
          INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
          WHERE STAGIAIRE_PEC.ID_STAGIAIRE_PEC = (SELECT ID_STAGIAIRE_PEC FROM #TMP_PREMIER_STAGIAIRE)
          
          --une table qui contient deux lignes pour repeter la convention 2 fois
          DECLARE @tmp_deux_lignes TABLE (Id int) 
          insert into @tmp_deux_lignes values (1)
          insert into @tmp_deux_lignes values (2)
         
         
         -- Recherche le nom complet du 1er stagiaire
          DECLARE @NOM_COMPLET_STAGIAIRE VARCHAR(64)
          SELECT @NOM_COMPLET_STAGIAIRE = (CIVILITE + ' ' + NOM + ' ' + PRENOM ) FROM #TMP_PREMIER_STAGIAIRE;
         
         
         
         --=======================================================================
         --**********************    XML
         --======================================================================= 
          WITH XMLNAMESPACES (
           DEFAULT 'LETTRE_PEC_ENGAGEMENT_OF'
          )
         
          SELECT
           -- R‚cup‚ration des informations sur le contact et le b‚n‚ficiaire
           (SELECT
             LIB_RAISON_SOCIALE AS RAISON_SOCIALE,
             LIBC_CIVILITE,  
             LIB_PNM_CONTACT, 
             LIB_NOM_CONTACT ,
             LIB_ADR,
             LIB_COMP_VOIE,
             LIB_MENTION_PARTICULIERE,
             LIB_CP_CEDEX,
             LIB_VIL_CEDEX
            FROM #TMP_BENEFICIAIRE AS ADRESSE      
            FOR XML AUTO, ELEMENTS, TYPE
           ) AS BENEFICIAIRE,  
           (SELECT     
             ISNULL(COD_OF, '')      AS COD_OF,
             ISNULL(LIB_PRENOM_CHARGE_RELATION, '') AS LIB_PRENOM_CHARGE_RELATION,
             ISNULL(LIB_NOM_CHARGE_RELATION, '')  AS LIB_NOM_CHARGE_RELATION,
             ISNULL(EMAIL_CHARGE_RELATION, '')  AS EMAIL,
             -- R‚cup‚ration des informations sur l'‚metteur
             DBO.GETXMLADRUTILAVECTEL(ENTETE.ID_UTIL, dbo.DossierEstTSA(@COD_MODULE_PEC, 1), 0) AS EMETTEUR, -- LDE 23/05/2014 #213
             RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, -- RETRAITEMENT DE LA VILLE AU CAS Oë DE LA FORME COMMUNE CEDEX 999
             DBO.GETFULLDATE(GETDATE()) AS DATE,  
             @COD_MODULE_PEC AS COD_MODULE_PEC,
             (
              SELECT TOP 1
               DBO.GETCONTACTSALUTATION(@ID_CONTACT, 1)
              FROM CIVILITE
              FOR XML PATH('POLITESSE_HAUT'), TYPE
             )
            FROM #TMP_ENTETE AS ENTETE     
            FOR XML AUTO, ELEMENTS, TYPE
           ),
           (SELECT
             (SELECT
               NOM,
               @ADHERENTS as ETABLISSEMENT,
               DATE_DUREE,
               COUT,
               COUT_REPOF
              FROM #TMP_FORMATION AS FORMATION
              FOR XML AUTO, ELEMENTS, TYPE
             ),
             (SELECT NOM_STAGIAIRE,
                PRENOM_STAGIAIRE
              FROM #TMP_STAGIAIRE AS STAGIAIRE
              FOR XML AUTO, ELEMENTS, TYPE
             ),
             -- modif du 02/12/09 par SBR
             (CASE 
              WHEN MODULE_PEC.DAT_FIN >= GETDATE() THEN DBO.GETFULLDATE(MODULE_PEC.DAT_FIN + 15)
              ELSE DBO.GETFULLDATE(GETDATE() + 15)
              END
             ) AS DATE_FIN_PLUS_QUINZE,
             (CASE WHEN @MODE <> 4
              THEN @NOM_OF
              ELSE NULL
             END) AS NOM_OF, 
             (CASE WHEN @MODE <> 4
              THEN @NOM_OF
              ELSE NULL
             END) AS NOM_OF,
             (CASE WHEN @MODE = 1
              THEN @NOM_OF
              ELSE NULL
             END) AS NOM_OF,   
             (CASE WHEN @MODE = 1 --Dif portable
              THEN @NOM_COMPLET_STAGIAIRE 
              ELSE NULL
             END) AS NOM_COMPLET_STAGIAIRE,
             (SELECT TOP 1
               DBO.GETCONTACTSALUTATION(@ID_CONTACT, 1)
              FROM CIVILITE
              FOR XML PATH('POLITESSE_BAS'), TYPE
             )
             FOR XML RAW('CORPS'), ELEMENTS, TYPE
           ),
           CASE WHEN @MODE = 2 --CSP
              THEN (SELECT 
               (SELECT 
                 LIB_RAISON_SOCIALE AS NOM,
                 (SELECT 
                   LIB_ADR AS ADRESSE1,
                   LIB_COMP_VOIE AS ADRESSE2,
                   LIB_CP_CEDEX AS CP,
                   LIB_VIL_CEDEX AS VILLE
                  FROM #TMP_BENEFICIAIRE AS ADRESSE
                  FOR XML AUTO, ELEMENTS, TYPE
                 ),
                 SIRET,
                 NUM_ACTIVITE
                FROM #TMP_BENEFICIAIRE AS [OF] 
                FOR XML AUTO, ELEMENTS, TYPE
               ),
               (SELECT
                PERIODE_MODULE as PERIODE_MODULE1,
                NOM,
                (SELECT 
                 CIVILITE,
                 PRENOM,
                 NOM,
                 ADRESSE1,
                 ADRESSE2,
                 CP,
                 VILLE
                FROM #TMP_PREMIER_STAGIAIRE AS STAGIAIRE
                FOR XML AUTO, ELEMENTS, TYPE       
                ),
                NOM AS NOM_FORMATION,
                DUREE,
                DATE_DEBUT,
                DATE_FIN,
                CP_ETAB_OF,
                VILLE_ETAB_OF,
                DBO.GETFRENCHCURRENCYFORMAT(CAST(COALESCE(MNT_PREVISIONNEL_HT,0) AS MONEY)) + ' ? HT' AS MNT_DEMANDE,
                @NB_HEURES AS NB_HEURES,
                COUT AS MNT_ENGAGE,
                @SS_TYPE_COUT AS SOUS_TYPE_COUT,
                PERIODE_MODULE,
                PERIODE_SUIVANTE
                FROM #TMP_FORMATION AS FORMATION
                FOR XML AUTO, ELEMENTS, TYPE
               ),
               DBO.GETFULLDATE(GETDATE()) AS DATE_EDITION
              from @tmp_deux_lignes 
              FOR XML RAW('CONVENTION'), ELEMENTS, TYPE) 
              ELSE NULL
           END
          FROM ACTION_PEC 
          INNER JOIN MODULE_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC 
          WHERE MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
          FOR XML RAW('LETTRE'), ELEMENTS, TYPE
         
         END
GO

         -- =============================================
         -- Author:		MBL
         -- Create date: xx xxx 2007
         -- Description:	Cr‚ation
         -- ---------------------------------------------
         -- Author:		SV
         -- Modif. date: 18 septembre 2007
         -- Description:	Initialisation des dates de d‚but et de fin aux dates de la p‚riode de l'enveloppe si les dates sont nulles
         -- ---------------------------------------------
         -- Author:		SAFI
         -- Modif. date: 18/10/2011
         -- Description:	changement de la taille de la colonne sur table temp
         -- LIBL_MVT_BUDGETAIRE varchar(50) … (60)
         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_MVT_ENVELOPPE_PER]
         /* Reconstitution des mouvements d'une enveloppe entre 2 dates */
         (@ID_ENVELOPPE integer,
         @DAT_DEBUT	datetime,
         @DAT_FIN	datetime)
         AS
         
         BEGIN
         	SET NOCOUNT ON
         
         	/* D‚finition automatique des dates de d‚but et de fin si elles ne sont pas fournies */
         	select
         		@DAT_DEBUT = case when (@DAT_DEBUT is null)
         			then PERIODE.DAT_DEB_PERIODE
         			else @DAT_DEBUT
         		end,
         		@DAT_FIN = case when (@DAT_FIN is null)
         			then PERIODE.DAT_FIN_PERIODE
         			else @DAT_FIN
         		end
         	from
         		PERIODE
         			inner join ENVELOPPE on ENVELOPPE.ID_PERIODE = PERIODE.ID_PERIODE
         									and ENVELOPPE.ID_ENVELOPPE = @ID_ENVELOPPE
         	
         	DECLARE
         	@ID_ADHERENT		integer,
         	@LIB_RAISON_SOCIALE varchar(50),
         	@LIBL_ENVELOPPE varchar(50),
         	@ID			integer, 
         	@MNT_MVT	decimal(18,2),
         	@MNT_SOLDE	decimal(18,2),
         	@BLN_OK		tinyint,
         	@MNT_SOLDE_SAV decimal(18,2),
         	@P_E_R varchar(1),
         	@P_E_R_SAV varchar(1)
         
         	DECLARE @NIV_DEBUG tinyint
         	SELECT @NIV_DEBUG = 0
         
         
         	IF @NIV_DEBUG >= 1
         	BEGIN
         		SELECT DAT_DEBUT = @DAT_DEBUT	
         		SELECT DAT_FIN = @DAT_FIN	
         	END
         
         	SELECT @DAT_DEBUT	= @DAT_DEBUT		+ 1
         	SELECT @DAT_FIN		= @DAT_FIN			+ 1
         
         
         	SET @BLN_OK = 0
         
         
         	SELECT @LIB_RAISON_SOCIALE = NULL
         
         	SELECT @LIBL_ENVELOPPE = LIBL_ENVELOPPE
         	FROM ENVELOPPE
         	WHERE ID_ENVELOPPE = @ID_ENVELOPPE
         
         	SET @BLN_OK = 1
         
         	IF @BLN_OK = 1
         	BEGIN
         
         		IF @NIV_DEBUG >= 1
         		BEGIN
         			PRINT '-- Liste des mouvements pour l''enveloppe'
         			SELECT MVT.DAT_MVT_BUDGETAIRE, NUM_ANNEE, ID_ADHERENT, MNT_MVT_SIRIUS = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 1 ELSE -1 END), LIBL_MVT_BUDGETAIRE, LIBC_TYPE_MOUVEMENT, P_E_R, SENS
         			FROM MVT_BUDGETAIRE MVT, EVENEMENT, ENVELOPPE, TYPE_ENVELOPPE, TYPE_MOUVEMENT, PARAMETRAGE_BUDGETAIRE, PERIODE
         			WHERE MVT.ID_EVENEMENT = EVENEMENT.ID_EVENEMENT
         			AND MVT.ID_ENVELOPPE= ENVELOPPE.ID_ENVELOPPE
         			AND ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         			AND MVT.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         			AND ENVELOPPE.ID_PERIODE = PERIODE.ID_PERIODE
         			AND ENVELOPPE.ID_ENVELOPPE = @ID_ENVELOPPE 
         		--	AND P_E_R = 'R'
         			ORDER BY NUM_ANNEE, DAT_MVT_BUDGETAIRE, P_E_R
         		END
         
         		IF @NIV_DEBUG >= 1
         		BEGIN 
         			PRINT '-- Liste des differentes periode par type (engage, previsionnel, reel)'
         		END
         
         		SELECT DISTINCT ENVELOPPE.ID_ENVELOPPE, 
         						PERIODE.ID_PERIODE, 
         						PERIODE.NUM_ANNEE, 
         						CAST(0 AS decimal(18,2)) MNT_INITIAL_P,
         						CAST(0 AS decimal(18,2)) MNT_FINAL_P,
         						CAST(0 AS decimal(18,2)) MNT_INITIAL_E,
         						CAST(0 AS decimal(18,2)) MNT_FINAL_E,
         						CAST(0 AS decimal(18,2)) MNT_INITIAL_R,
         						CAST(0 AS decimal(18,2)) MNT_FINAL_R
         		INTO #TMP_CPT_INIT
         		FROM ENVELOPPE, MVT_BUDGETAIRE, PERIODE
         		WHERE ENVELOPPE.ID_ENVELOPPE = @ID_ENVELOPPE
         		AND ENVELOPPE.ID_ENVELOPPE = MVT_BUDGETAIRE.ID_ENVELOPPE
         		AND ENVELOPPE.ID_PERIODE = PERIODE.ID_PERIODE
         		AND DAT_MVT_BUDGETAIRE >= @DAT_DEBUT
         		AND DAT_MVT_BUDGETAIRE <= @DAT_FIN
         
         		IF @NIV_DEBUG >= 1
         		BEGIN
         			SELECT * FROM #TMP_CPT_INIT
         		END
         
         
         		-- Calcul des montants initiaux sur les differentes enveloppes (somme des mouvements avant la date de prise en compte)
         		UPDATE #TMP_CPT_INIT 
         		SET MNT_INITIAL_P = TMP_INIT.MNT_INITIAL_P
         		FROM
         			( SELECT TMP01.ID_ENVELOPPE, SUM(MNT_MVT_BUDGETAIRE) MNT_INITIAL_P
         			FROM #TMP_CPT_INIT TMP01, ENVELOPPE, MVT_BUDGETAIRE
         			WHERE 
         				TMP01.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         			AND ENVELOPPE.ID_ENVELOPPE = MVT_BUDGETAIRE.ID_ENVELOPPE
         			AND DAT_MVT_BUDGETAIRE <= @DAT_DEBUT
         			AND P_E_R = 'P'
         			GROUP BY TMP01.ID_ENVELOPPE) TMP_INIT
         		WHERE #TMP_CPT_INIT.ID_ENVELOPPE= TMP_INIT.ID_ENVELOPPE
         
         		UPDATE #TMP_CPT_INIT 
         		SET MNT_INITIAL_E = TMP_INIT.MNT_INITIAL_E
         		FROM
         			( SELECT TMP01.ID_ENVELOPPE, SUM(MNT_MVT_BUDGETAIRE) MNT_INITIAL_E
         			FROM #TMP_CPT_INIT TMP01, ENVELOPPE, MVT_BUDGETAIRE
         			WHERE	
         				TMP01.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         			AND ENVELOPPE.ID_ENVELOPPE = MVT_BUDGETAIRE.ID_ENVELOPPE 
         			AND DAT_MVT_BUDGETAIRE <= @DAT_DEBUT
         			AND P_E_R = 'E'
         			GROUP BY TMP01.ID_ENVELOPPE) TMP_INIT
         		WHERE #TMP_CPT_INIT.ID_ENVELOPPE = TMP_INIT.ID_ENVELOPPE
         
         		UPDATE #TMP_CPT_INIT 
         		SET MNT_INITIAL_R = TMP_INIT.MNT_INITIAL_R
         		FROM
         			( SELECT TMP01.ID_ENVELOPPE, SUM(MNT_MVT_BUDGETAIRE) MNT_INITIAL_R
         			FROM #TMP_CPT_INIT TMP01, ENVELOPPE, MVT_BUDGETAIRE
         			WHERE
         				TMP01.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         			AND ENVELOPPE.ID_ENVELOPPE= MVT_BUDGETAIRE.ID_ENVELOPPE
         			AND DAT_MVT_BUDGETAIRE <= @DAT_DEBUT
         			AND P_E_R = 'R'
         			GROUP BY TMP01.ID_ENVELOPPE) TMP_INIT
         		WHERE #TMP_CPT_INIT.ID_ENVELOPPE= TMP_INIT.ID_ENVELOPPE
         
         UPDATE #TMP_CPT_INIT SET MNT_INITIAL_E = MNT_INITIAL_E + MNT_INITIAL_R
         UPDATE #TMP_CPT_INIT SET MNT_INITIAL_P = MNT_INITIAL_P + MNT_INITIAL_E
         
         
         		CREATE TABLE #TMP_MVT
         		(ID integer not null identity,
         		ID_ENVELOPPE integer,
         		ID_ADHERENT integer,
         		LIBL_RAISON_SOCIALE varchar(50),
         		DAT_MVT_BUDGETAIRE datetime, 
         		NUM_ANNEE integer,
         		MNT_MVT decimal(18,2), 
         		MNT_DEBIT decimal(18,2),
         		MNT_CREDIT decimal(18,2),
         		LIBL_MVT_BUDGETAIRE varchar(60),
         		LIBL_PERIODE varchar(50),
         		P_E_R	varchar(1)
         		)
         
         
         		/* Recuperation des mouvements entre les 2 tables dans une table temporaire */
         		INSERT INTO #TMP_MVT
         		(	ID_ENVELOPPE, 	
         			ID_ADHERENT, 
         			LIBL_RAISON_SOCIALE,
         			DAT_MVT_BUDGETAIRE, 
         			NUM_ANNEE , 
         			MNT_MVT , 
         			MNT_DEBIT ,
         			MNT_CREDIT ,
         			LIBL_MVT_BUDGETAIRE, 
         			LIBL_PERIODE, 	
         			P_E_R)
         		SELECT 
         			MVT.ID_ENVELOPPE, 
         			MVT.ID_ADHERENT, 
         			NULL,
         			MVT.DAT_MVT_BUDGETAIRE, 
         			PERIODE.NUM_ANNEE, 
         			MNT_MVT_SIRIUS = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 1 ELSE -1 END), 
         			MNT_DEBIT = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 1 ELSE 0 END),
         			MNT_CREDIT = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 0 ELSE 1 END),
         			LIBL_MVT_BUDGETAIRE = ISNULL(LIBL_MVT_BUDGETAIRE, ''),
         			LIBL_PERIODE = 'Ann‚e ' + CAST(NUM_ANNEE AS VARCHAR), 
         			P_E_R
         		FROM MVT_BUDGETAIRE MVT, EVENEMENT, ENVELOPPE, TYPE_ENVELOPPE, TYPE_MOUVEMENT, PARAMETRAGE_BUDGETAIRE, PERIODE
         		WHERE MVT.ID_EVENEMENT = EVENEMENT.ID_EVENEMENT
         		AND MVT.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         		AND ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		AND MVT.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
         		AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
         		AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		AND ENVELOPPE.ID_PERIODE = PERIODE.ID_PERIODE
         		AND DAT_MVT_BUDGETAIRE >= @DAT_DEBUT
         		AND DAT_MVT_BUDGETAIRE <= @DAT_FIN
         		ORDER BY NUM_ANNEE, DAT_MVT_BUDGETAIRE, P_E_R
         
         
         /* Recalcul des soldes finaux */
         	UPDATE #TMP_CPT_INIT
         	SET MNT_FINAL_R = MNT_INITIAL_R + SOLDE_MVT.SOLDE
         	FROM
         	(SELECT	#TMP_MVT.ID_ENVELOPPE, ISNULL(SUM ((CASE P_E_R WHEN 'R' THEN 1 ELSE 0 END)* (MNT_CREDIT - MNT_DEBIT) ),0)  SOLDE
         	FROM #TMP_MVT 
         	GROUP BY #TMP_MVT.ID_ENVELOPPE
         	) SOLDE_MVT
         	WHERE SOLDE_MVT.ID_ENVELOPPE = #TMP_CPT_INIT.ID_ENVELOPPE
         
         
         
         	UPDATE #TMP_CPT_INIT
         	SET MNT_FINAL_E = MNT_INITIAL_E + SOLDE_MVT.SOLDE
         	FROM
         	(SELECT	#TMP_MVT.ID_ENVELOPPE, ISNULL(SUM ((CASE P_E_R WHEN 'P' THEN 0 ELSE 1 END)* (MNT_CREDIT - MNT_DEBIT) ),0)  SOLDE
         	FROM #TMP_MVT 
         	GROUP BY #TMP_MVT.ID_ENVELOPPE
         	) SOLDE_MVT
         	WHERE SOLDE_MVT.ID_ENVELOPPE = #TMP_CPT_INIT.ID_ENVELOPPE
         
         	UPDATE #TMP_CPT_INIT
         	SET MNT_FINAL_P = MNT_INITIAL_P + SOLDE_MVT.SOLDE
         	FROM
         	(SELECT	#TMP_MVT.ID_ENVELOPPE, ISNULL(SUM ((MNT_CREDIT - MNT_DEBIT) ),0)  SOLDE
         	FROM #TMP_MVT 
         	GROUP BY #TMP_MVT.ID_ENVELOPPE
         	) SOLDE_MVT
         	WHERE SOLDE_MVT.ID_ENVELOPPE = #TMP_CPT_INIT.ID_ENVELOPPE
         
         
         /* Fin Recalcul des soldes finaux */
         
         
         	SELECT ID_ADHERENT = #TMP_MVT.ID_ADHERENT, 
         			LIB_RAISON_SOCIALE = ADHERENT.LIB_RAISON_SOCIALE, 
         			LIBL_PERIODE = #TMP_MVT.LIBL_PERIODE, 
         			MNT_INITIAL_P = #TMP_CPT_INIT.MNT_INITIAL_P, 
         			MNT_INITIAL_E = #TMP_CPT_INIT.MNT_INITIAL_E, 
         			MNT_INITIAL_R = #TMP_CPT_INIT.MNT_INITIAL_R, 
         			DAT_MVT_BUDGETAIRE = #TMP_MVT.DAT_MVT_BUDGETAIRE, 
         			LIBL_MVT_BUDGETAIRE = #TMP_MVT.LIBL_MVT_BUDGETAIRE, 
         			P_E_R,
         			MNT_DEBIT, 
         			MNT_CREDIT, 
         			MNT_FINAL_P, 
         			MNT_FINAL_E, 
         			MNT_FINAL_R, 
         			ID_ENVELOPPE = #TMP_MVT.ID_ENVELOPPE,
         			LIBL_ENVELOPPE = @LIBL_ENVELOPPE
         	FROM #TMP_MVT
         		INNER JOIN #TMP_CPT_INIT ON #TMP_MVT .ID_ENVELOPPE = #TMP_CPT_INIT.ID_ENVELOPPE 
         		LEFT OUTER JOIN ADHERENT ON #TMP_MVT .ID_ADHERENT = ADHERENT.ID_ADHERENT
         	ORDER BY #TMP_MVT .ID_ENVELOPPE, #TMP_MVT.LIBL_PERIODE, DAT_MVT_BUDGETAIRE, #TMP_MVT.ID_ADHERENT
         	END
         
         END
         
GO

         
         create PROCEDURE [dbo].[EDI_TRANSCO_CTL_EXISTE_ID_DEFAUT] 
         /* 
           Controle que l'identifiant par defaut associee  une table concernee par la transcodification dans le cadre de l'EDI 
           correspond  un identifiant prsent dans cette table.
         */  
         @ID_TABLE		VARCHAR(255),
         @ID_FAF			INTEGER
         AS
         
         BEGIN
         SET ROWCOUNT 0
         SET NOCOUNT ON
         
         DECLARE @COD_TABLE_FAF		VARCHAR(255),
         	@COD_FAF 		VARCHAR(8),
         	@LIBC_FAF 		VARCHAR(20),
         	@ID_TABLE_FAF_DEFAUT	INTEGER,
         	@LIB			VARCHAR(2000)
         	CREATE TABLE #TMP02
         	(
         		ID_FAF 	INTEGER		NULL,
         		COD_FAF 	VARCHAR(8)	NULL,
         		LIBC_FAF 	VARCHAR(20)	NULL
         	)
         
         	SELECT @COD_TABLE_FAF = name
         	FROM	sysobjects
         	WHERE	type = 'U'
         	AND	id = @ID_TABLE
         	
         
         	IF @@ROWCOUNT > 0
         	BEGIN		
         		SET @LIB = 'INSERT INTO #TMP02 '
         		SET @LIB = @LIB + 'SELECT ID_' + @COD_TABLE_FAF + ' ID , COD_' + @COD_TABLE_FAF + ' COD , LIBC_' + @COD_TABLE_FAF + ' LIBC  '
         		SET @LIB = @LIB + ' FROM ' + @COD_TABLE_FAF
         		SET @LIB = @LIB + ' WHERE ID_' + @COD_TABLE_FAF + ' = ' + CONVERT(VARCHAR, @ID_FAF)
         		EXECUTE (@LIB)
         
         		SELECT @COD_TABLE_FAF COD_TABLE_FAF, ID_FAF, COD_FAF, LIBC_FAF 
         		FROM #TMP02
         	
         	END
         
         END
         
GO
 CREATE PROCEDURE [BATCH_MVT_BUDGETAIRES]  
         -- =============================================      
         -- Author:  Say      
         -- Create date: 13 mars 2007      
         -- Description: Proc‚dure pour le batch comptable sur les mouvements budg‚taire      
         -- =============================================      
         -- DSZ 11/05/2012 : 13427 ajout transfert FMS      
         -- =============================================      
         -- DSZ 09/07/2012 : 13341 3 bis : ajout BATCH_DOTATIONS_FAIBLE_MS      
         -- =============================================      
         -- MBL 06/12/2013 : Desactivation lancement des PS de generation des transferts de collecte initialement crees    
         --      : Lancement des PS de generation des nouveaux transferts de collecte    
         -- =============================================      
         -- MBL 12/12/2014 : Refonte complŠte des mouvements budgetaires de collecte    
         -- =============================================      
         -- MBL 12/01/2015 : Reactivation lancement des PS de generation des transferts FMS    
         -- =============================================      
         -- MBL 20/03/2015 : Lancement de generation des nouvelles dotations    
         -- =============================================      
         -- MBL 30/06/2015 : Lancement des transferts de solde engagement Compte Historique <-> Compte Volontaire   
         -- =============================================      
         -- MBL 16/07/2015 : Rajout des transferts correspondant aux types d'evenement suivants :  
            -- R‚gularisation Frais Gestion VV  
            -- Compensation Frais Gestion VO  
            -- Compensation Frais Gestion VV  
         -- =============================================      
         -- MBL 16/10/2015 : Lancement des transferts de solde engagement Compte Historique <-> Compte Volontaire   
         --     tous les vendredis (auparavant tous les mois)  
         -- =============================================      
         -- MBL 22/09/2015 : Rajout des transferts correspondant au type d'evenement Dotations Exceptionnelle PME 2015
         -- =============================================      
         -- MBL 13/11/2015 : Rajout des transferts correspondant au type d'evenement Dotations de Bonification Tranche Sup‚rieure
         -- =============================================      
         -- MBL 19/11/2015 : Rajout des transferts correspondant au type d'evenement Dotations Suppl‚mentaire Dotations Suppl‚mentaires DEFI GESTION PME 2015
         -- =============================================      
         -- MBL 13/01/2016 : Lancement des transferts de solde engagement Compte Historique <-> Compte Volontaire   
         --     tous les vendredis jusqu'a fin janvier 2016
         -- =============================================      
         -- MBL 11/03/2016 : Param‚trage 2016
         -- =============================================      
         -- MBL 11/03/2016 : Param‚trage 2016
         	-- Inclusion des transferts de Prescriptions :
         	-- 18) Batch des tranferts de prescription du compte Plan Obligatoire 2015
         	-- 19) Batch des tranferts de prescription du compte Selection DEFI 2015
         -- =============================================      
         
         AS    
         BEGIN      
             
         	DECLARE @DAT_J datetime    
         	SELECT @DAT_J = GETDATE()    
         
         
         	-- 1) Generation des mouvements budgetaires li‚s aux versements de collecte    
         	EXEC BATCH_GENERATION_MVT_BUDGETAIRE_COLLECTE    
         
         
         
         	-- 3) Generation pour les adh‚rents -10 des Dotations sur Compte S‚lection Defi (OK 2015)   
         	EXEC BATCH_TRANSFERT_DOTATION_ALIM_CPT_MOINS10 'DOTDSM10', NULL    
         
         	-- 4) Generation pour les adh‚rents -10 des Dotations sur Compte Plan Obligatoire (OK 2015)      
         	EXEC BATCH_TRANSFERT_DOTATION_ALIM_CPT_MOINS10 'DOTVOM10', NULL    
         
         	-- 5) Generation pour les adh‚rents -10 des Dotations sur Compte Plan Obligatoire (OK 2015)   
         	EXEC [BATCH_TRANSFERT_DOTATION_ALIM_CPT_DEFI_SELECTION_10_300] 'DOTDS_M3', NULL    
         
         	-- 6) Generation pour Options PERFORMANCE des Dotations d'Abondement sur Compte Plan Obligatoire    (OK 2015)   
         	EXEC [BATCH_TRANSFERT_DOTATION_ABONDEMENT_VO_OPTION_PERFORMANCE] 'DOTABOVO', NULL    
         
         
         
         	-- 7) Generation Transferts pour R‚gularisation Frais Gestion VV	(OK 2015)   
         	--EXEC [BATCH_TRANSFERT_REGUL_FRAIS_GESTION_VV] 2016, NULL  
         
         	-- 8) Generation Transferts pour  Compensation Frais Gestion VV		(OK 2015)   
         	--EXEC [BATCH_TRANSFERT_COMPENSATION_FRAIS_GESTION_VV] 2016, NULL  
         	IF DAY(@DAT_J)  = 11 AND MONTH(@DAT_J) =3 AND YEAR(@DAT_J) = 2016  
         	BEGIN    
         		EXEC [BATCH_TRANSFERT_COMPENSATION_FRAIS_GESTION_VV] 2015, NULL  
         	END
         
         	-- 9) Generation Transferts pour Compensation Frais Gestion VO		(OK 2015)  
         	--EXEC [BATCH_TRANSFERT_COMPENSATION_FRAIS_GESTION_VO_PLAN] 2015, NULL  
         
         
         	-- 10) Generation des Tranferts des soldes cr‚diteurs du compte historique vers le compte volontaire    
         	-- lanc‚ tous les vendredis (5 eme jour de la semaine)  jusqu'a fin janvier 2016
         	--IF MONTH(@DAT_J) != MONTH(@DAT_J+1)  AND YEAR(@DAT_J) = 2015  
         	IF DAY(@DAT_J)  = 11 AND MONTH(@DAT_J) =3 AND YEAR(@DAT_J) = 2016  
         	BEGIN    
         		EXEC BATCH_GENERATION_TRANSFERT_COMPTE_HISTORIQUE_CREDITEUR NULL  
         	END    
         	 
         	-- 11) Generation des Transferts des comptes volontaires avec solde d'engagement cr‚diteur vers les comptes historiques avec solde d'engagement d‚biteur    
         	-- lanc‚ tous les vendredis (5 eme jour de la semaine)  jusqu'a fin janvier 2016
         	--IF MONTH(@DAT_J) != MONTH(@DAT_J+1)  AND YEAR(@DAT_J) = 2015  
         	IF DAY(@DAT_J)  = 11 AND MONTH(@DAT_J) =3 AND YEAR(@DAT_J) = 2016  
         	BEGIN    
         		EXEC BATCH_GENERATION_TRANSFERT_COMPTE_HISTORIQUE_DEBITEUR NULL    
         	END    
         
         	-- 15) Generation pour les adh‚rents 10-49 des Dotations Exceptionnelle PME 2015
         	--EXEC [BATCH_TRANSFERT_DOTATION_EXCEPTIONNELLE_PME_2015] NULL
         
         	-- 16) Generation des Dotations de Bonification Tranche Sup‚rieure
         	-- EXEC [BATCH_TRANSFERT_BONIFICATION_TRANCHE_SUPERIEURE] 2015, NULL
         
         	-- 17) Generation pour les adh‚rents 10-49 des Dotations Suppl‚mentaires DEFI GESTION PME 2015
         	-- EXEC [BATCH_TRANSFERT_DOTATION_SUPPLEMENTAIRE_DEFI_GESTION_PME_2015] NULL
         
         
         	-- 18) Batch des tranferts de prescription du compte Plan Obligatoire 2015
         	EXEC [BATCH_TRANSFERT_PRESCRIPTION_COMPTE_PLAN_OBLIGATOIRE] 2015, NULL
         
         	-- 19) Batch des tranferts de prescription du compte Selection DEFI 2015
         	EXEC BATCH_TRANSFERT_PRESCRIPTION_SELECTION_DEFI 2015, NULL
         
         
         
         
         
         
         	-- 20) Generation des Mouvements budgetaires lies aux transfert de collecte    
         	EXEC BATCH_GENERATION_MVT_BUDGETAIRE_TRANSFERT NULL  
         
         END    
         
GO
 CREATE PROCEDURE [dbo].[UPD_CONTRAT_PRO]
          @ID_CONTRAT_PRO     INT,
          @LIBL_CONTRAT_PRO    VARCHAR(250),
          @DAT_DEB_CONTRAT    DATETIME,
          @DAT_FIN_CONTRAT    DATETIME,
          @DAT_DEB_FORMATION    DATETIME,
          @DAT_FIN_FORMATION    DATETIME,
          @DAT_SIGNATURE_CONTRAT   DATETIME,
          @BLN_ACTIF      TINYINT,
          @COM_CONTRAT_PRO    VARCHAR(255),
          @NUM_NB_SALARIE_ETABLISSEMENT INT,
          @NUM_DUREE_CONTRAT    DECIMAL(18,2),
          @NUM_DUREE_FORMATION   DECIMAL(18,2),
          @NUM_DUREE_PERIODE_ESSAI  DECIMAL(18,2),
          @NUM_DUREE_MENSUELLE_TRAVAIL DECIMAL(18,4),
          @NUM_DUREE_HEBDO_TRAVAIL_HEURES  TINYINT,
          @NUM_DUREE_HEBDO_TRAVAIL_MINUTES TINYINT,
          @LIB_QUALIF_TUTEUR    VARCHAR(120),
          @LIBL_QUALIFICATION_VISEE  VARCHAR(255),
          @DAT_EXAMEN      DATETIME,
          @COEF_CLASSIFICATION   VARCHAR(4),
          @LIB_EMPLOI_OCCUPE    VARCHAR(120),
          @LIB_CAISSE_RETRAITE   VARCHAR(120),
          @LIB_ORGANISME_PREVOYANCE  VARCHAR(120),
          @MNT_SALAIRE_BRUT_MENSUEL  DECIMAL(18,2),
          @BLN_CONFORME_ACCORD   TINYINT,
          @BLN_PARTICIPATION_FINANCIERE TINYINT,
          @BLN_EXONERATION_CHARGES  TINYINT,
          @NUM_ENREGISTREMENT_DDTE  VARCHAR(20),
          @DAT_DEPOT_DDTE     DATETIME,
          @DAT_ENREGISTREMENT_DDTE  DATETIME,
          @DAT_CLOTURE     DATETIME,
          @BLN_ORIGINE_SFEIR    TINYINT,
          @ID_UTILISATEUR     INT,
          @ID_CLASSIFICATION    INT,
          @ID_AGENCE      INT,
          @ID_TIERS_DDTE     INT,
          @ID_FORMACODE     INT,
          @ID_PUBLIC_SPECIFIQUE   INT,
          @ID_THEME      INT,
          @ID_NIVEAU      INT,
          @ID_SANCTION     INT,
          @ID_TYPE_ISSUE_PRO    INT,
          @ID_TYPOLOGIE_CONTRAT   INT,
          @ID_SALARIE_PRO     INT,
          @ID_TUTEUR      INT,
          @ID_TYPE_CONTRAT    INT,
          @ID_SPECIALITE     INT,
          @ID_ETABLISSEMENT    INT,
          @ID_ETAT_CONTRAT_PRO   INT,
          @ID_MOTIF_CLOTURE_PRO   INT,
          @ID_TYPE_CONTRAT_PRO   INT,
          @DAT_BAE_INITIALE    DATETIME,
          @LIB_LIEU_FORMATION    VARCHAR(80),
          @ID_IDCC      INT,
          @ID_TYPE_CONTRAT_FAF   INT,
          @NUM_DERNIER_AVENANT   INT,
          @BLN_OK_PIECE     TINYINT,
          @DAT_LETTRE_REFUS    DATETIME,
          @DAT_LETTRE_REJET    DATETIME,
          @TIME_STAMP      TIMESTAMP,
          @BLN_DIPLOME_OBTENU    TINYINT,
          @DAT_RECU_CONTRAT    DATETIME,
          @ID_CLASSIFICATION_VISEE  INT,
          @ID_ACTION_PEC     INT,
          @ID_CSP_TUTEUR     INT,
          @ID_AGENCE_CLOTURE    INT,
          @BLN_ATTESTATION_FORMATION  TINYINT,
          @BLN_TUTEUR_FORME    TINYINT,
          @LIB_LIEU_SIGNATURE    VARCHAR(255),
          @ID_CONTACT_ETABLISSEMENT  INT
         AS
         -- =============================================
         -- Author  : KSA
         -- Create date : 11 janv. 2008
         -- Description : Cr‚ation de la proc‚dure d'update contrat
         -- ---------------------------------------------
         -- Modif. date : 04 f‚v. 2008
         -- Description : Modification du NUM DDTE suite … la modification de Kwame Woollams
         -- =============================================
         -- Modif. date : 04 mars. 2008
         -- Gestion de l'ajout de BLN_DIPLOME_OBTENU
         ------------------------------------------------
         -- Modif. date : 06 mars. 2008
         -- 0006978: NUM_DUREE_PERIODE_ESSAI dans CONTRAT_PRO devrait accepter les d‚cimales 
         ------------------------------------------------
         -- Modif. date : 15 janv. 2009
         -- FI251: ajout cl‚ externe ID_ACTION_PEC 
         -- =============================================
         -- Modif. date : 02 mars. 2010
         -- EVOL 12301 : Ajout de la colonne ID_CSP_TUTEUR
         -- =============================================
         -- DSZ 12/12/12 14030
         -- ajout parametre @ID_AGENCE_CLOTURE et son traitement pour obtenir NUM_ARCHVE
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- HBO 02/07/2013 : 15376 : CPRO / onglet Employeur : nouvelle case … cocher Attestation formation
         -- =============================================
         -- HBO 04/07/2013 : 15382: CPRO / onglet Salari‚ & Tuteur : Tuteur form‚ : nouvelle case … cocher
         -- =============================================
         -- HBO 05/07/2013 : 15384: CPRO / onglet Le contrat : A (lieu de signature)
         -- =============================================
         -- TLE 08/07/2013 : 15381 : CPRO / onglet Salari‚ & Tuteur : Emploi
         -- =============================================
         -- HBO : 220713 : M15573: CPRO / onglet Employeur : ‚cart par rapport aux SFD : Contact et e-mail de l'employeur dans le CPRO
         -- =======================================================================================================================================
         -- HBO : 130813 : M15604: NLE - CPro - Onglet contrat - Dur‚e hebdo travail (suite mantis 0015162: D‚tail CPRO / Contrat / Dur‚es)
         -- =======================================================================================================================================
         -- TLE 09/10/2013 : Passage de la taille de LIB_QUALIF_TUTEUR … 35 (avant passage 2.9.60)
         -- =============================================
         -- TLE 23/10/2013 : Passage de la taille de LIB_QUALIF_TUTEUR … 120
         -- =============================================
         -- DSZ 04/11/2013 : 16330:  BLN_VISIBLE_PANIERS ‚gal … @BLN_ACTIF
         --==============================================
         -- HBO - 311213 - #16653: NLE - PROD - calcul SMIC
         -- =============================================
         -- GOK,DSZ 13/04/2016 : US 1152 :  Modification de la taille du parametre champ @LIBL_CONTRAT_PRO de varchar(50) … varchar(250) 
         -- =============================================
         
         
         BEGIN
          DECLARE
           @NUM_ARCHIVE VARCHAR(17) = NULL
          
          IF (@DAT_CLOTURE IS NOT NULL AND @ID_AGENCE_CLOTURE IS NOT NULL)
          BEGIN
           DECLARE
            @COMPTEUR INT = 0
           
           EXEC @COMPTEUR = dbo.GET_COMPTEUR_SUIVANT 'NUM_ARCHIVE'
           
           SELECT
            @NUM_ARCHIVE = CONVERT(VARCHAR(8), @COMPTEUR) + '/' + COD_AGENCE 
           FROM
            AGENCE
           WHERE
            ID_AGENCE = @ID_AGENCE_CLOTURE
          END
          
          UPDATE
           CONTRAT_PRO
          SET
           LIBL_CONTRAT_PRO    = @LIBL_CONTRAT_PRO,
           LIB_QUALIF_TUTEUR    = @LIB_QUALIF_TUTEUR,
           LIBL_QUALIFICATION_VISEE  = @LIBL_QUALIFICATION_VISEE,
           LIB_EMPLOI_OCCUPE    = @LIB_EMPLOI_OCCUPE,
           LIB_CAISSE_RETRAITE    = @LIB_CAISSE_RETRAITE,
           LIB_ORGANISME_PREVOYANCE  = @LIB_ORGANISME_PREVOYANCE,
           COM_CONTRAT_PRO     = @COM_CONTRAT_PRO,
           DAT_MODIF      = GETDATE(),
           DAT_DEB_CONTRAT     = @DAT_DEB_CONTRAT,
           DAT_FIN_CONTRAT     = @DAT_FIN_CONTRAT,
           DAT_DEB_FORMATION    = @DAT_DEB_FORMATION,
           DAT_FIN_FORMATION    = @DAT_FIN_FORMATION,
           DAT_SIGNATURE_CONTRAT   = @DAT_SIGNATURE_CONTRAT,
           DAT_EXAMEN      = @DAT_EXAMEN,
           DAT_DEPOT_DDTE     = @DAT_DEPOT_DDTE,
           DAT_ENREGISTREMENT_DDTE   = @DAT_ENREGISTREMENT_DDTE,
           DAT_CLOTURE      = @DAT_CLOTURE,
           DAT_LETTRE_REFUS    = @DAT_LETTRE_REFUS,
           DAT_LETTRE_REJET    = @DAT_LETTRE_REJET,
           BLN_ACTIF      = @BLN_ACTIF,
           BLN_CONFORME_ACCORD    = @BLN_CONFORME_ACCORD,
           BLN_PARTICIPATION_FINANCIERE = @BLN_PARTICIPATION_FINANCIERE,
           BLN_EXONERATION_CHARGES   = @BLN_EXONERATION_CHARGES,
           BLN_ORIGINE_SFEIR    = @BLN_ORIGINE_SFEIR,
           BLN_OK_PIECE     = @BLN_OK_PIECE,
           NUM_NB_SALARIE_ETABLISSEMENT = @NUM_NB_SALARIE_ETABLISSEMENT,
           NUM_DUREE_CONTRAT    = @NUM_DUREE_CONTRAT,
           NUM_DUREE_FORMATION    = @NUM_DUREE_FORMATION,
           NUM_DUREE_PERIODE_ESSAI   = @NUM_DUREE_PERIODE_ESSAI,
           NUM_DUREE_MENSUELLE_TRAVAIL  = @NUM_DUREE_MENSUELLE_TRAVAIL,
           NUM_DUREE_HEBDO_TRAVAIL_HEURES = @NUM_DUREE_HEBDO_TRAVAIL_HEURES,
           NUM_DUREE_HEBDO_TRAVAIL_MINUTES = @NUM_DUREE_HEBDO_TRAVAIL_MINUTES,
           NUM_ENREGISTREMENT_DDTE   = @NUM_ENREGISTREMENT_DDTE,
           NUM_DERNIER_AVENANT    = @NUM_DERNIER_AVENANT,
           COEF_CLASSIFICATION    = @COEF_CLASSIFICATION,
           MNT_SALAIRE_BRUT_MENSUEL  = @MNT_SALAIRE_BRUT_MENSUEL,
           ID_UTILISATEUR     = @ID_UTILISATEUR,
           ID_CLASSIFICATION    = @ID_CLASSIFICATION,
           ID_AGENCE      = @ID_AGENCE,
           ID_TIERS_DDTE     = @ID_TIERS_DDTE,
           ID_FORMACODE     = @ID_FORMACODE,
           ID_PUBLIC_SPECIFIQUE   = @ID_PUBLIC_SPECIFIQUE,
           ID_THEME      = @ID_THEME,
           ID_NIVEAU      = @ID_NIVEAU,
           ID_SANCTION      = @ID_SANCTION,
           ID_TYPE_ISSUE_PRO    = @ID_TYPE_ISSUE_PRO,
           ID_TYPOLOGIE_CONTRAT   = @ID_TYPOLOGIE_CONTRAT,
           ID_SALARIE_PRO     = @ID_SALARIE_PRO,
           ID_TUTEUR      = @ID_TUTEUR,
           ID_TYPE_CONTRAT     = @ID_TYPE_CONTRAT,
           ID_SPECIALITE     = @ID_SPECIALITE,
           ID_ETABLISSEMENT    = @ID_ETABLISSEMENT,
           ID_ETAT_CONTRAT_PRO    = @ID_ETAT_CONTRAT_PRO,
           ID_MOTIF_CLOTURE_PRO   = @ID_MOTIF_CLOTURE_PRO,
           ID_TYPE_CONTRAT_PRO    = @ID_TYPE_CONTRAT_PRO,
           DAT_BAE_INITIALE    = @DAT_BAE_INITIALE,
           LIB_LIEU_FORMATION    = @LIB_LIEU_FORMATION,
           ID_IDCC       = @ID_IDCC,
           ID_TYPE_CONTRAT_FAF    = @ID_TYPE_CONTRAT_FAF,
           BLN_DIPLOME_OBTENU    = @BLN_DIPLOME_OBTENU,
           DAT_RECU_CONTRAT    = @DAT_RECU_CONTRAT,
           ID_CLASSIFICATION_VISEE   = @ID_CLASSIFICATION_VISEE,
           ID_ACTION_PEC     = @ID_ACTION_PEC,
           ID_CSP_TUTEUR     = @ID_CSP_TUTEUR,
           NUM_ARCHIVE      = @NUM_ARCHIVE,
           ID_AGENCE_CLOTURE    = @ID_AGENCE_CLOTURE,
           BLN_ATTESTATION_FORMATION  = @BLN_ATTESTATION_FORMATION,
           BLN_TUTEUR_FORME    = @BLN_TUTEUR_FORME,
           LIB_LIEU_SIGNATURE    = @LIB_LIEU_SIGNATURE,
           ID_CONTACT_ETABLISSEMENT  = @ID_CONTACT_ETABLISSEMENT,
           BLN_VISIBLE_PANIERS    = @BLN_ACTIF 
          WHERE
           ID_CONTRAT_PRO     = @ID_CONTRAT_PRO
           AND TIME_STAMP     = @TIME_STAMP
         
          IF((@DAT_CLOTURE IS NOT NULL) OR (@BLN_ACTIF = 0))
          BEGIN
           EXEC dbo.DEL_EXPORT_D3R
            @ID_CONTRAT_PRO,
            'PRO'
          END
         END
GO
CREATE PROCEDURE [dbo].[EDT_ORDRES_VIREMENT_RECAP_AMOUNTS]
          @StartDate DATETIME,
          @EndDate DATETIME,
          @Reedit  INT,
          @UserID  INT
         -- =============================================
         -- HBO - #652 - Amounts for activities and subvention
         -- =============================================
         AS
         BEGIN
          DECLARE
           @ActivitiesAndAmounts TABLE
           (
            Code  VARCHAR(8),
            Amount  DECIMAL(18,2),
            DateDebut DATETIME,
            DateFin  DATETIME,
            Reedition INT,
            UserID  INT,
            OrderNumber INT
           )
          
          ;with ActivitiesAndAmounts as
             (
           SELECT DISTINCT
            LIBC_ACTIVITE AS Code,
            sum(dbo.GetMontantReglementSplit(R.ID_REGLEMENT,A.ID_ACTIVITE, null, 1)) AS Amount,
            @StartDate AS DATE_DEBUT,
            @EndDate AS DATE_FIN,
            @Reedit  AS REEDITION,
            @UserID  AS ID_UTILISATEUR,
            NUM_ORDRE AS OrderNumber
           FROM
            REGLEMENT R
            CROSS APPLY ACTIVITE A
           WHERE
            R.BLN_ACTIF = 1
            AND 
            (
             (
              @Reedit = 1
              AND R.DAT_VALID_REGLEMENT IS NOT NULL
              AND (@StartDate IS NULL OR DATEDIFF(DAY,R.DAT_VALID_REGLEMENT,@StartDate) <= 0)
              AND (@EndDate  IS NULL OR DATEDIFF(DAY,R.DAT_VALID_REGLEMENT,@EndDate ) >= 0)
             )
             OR
             (
              @Reedit <> 1
              AND R.BLN_EN_COURS = 1
              AND (@UserID is null or R.ID_UTILISATEUR = @UserID)
             )
            )
           GROUP BY
            NUM_ORDRE,
            LIBC_ACTIVITE
             )
             INSERT INTO
           @ActivitiesAndAmounts
             SELECT
           *
             FROM
           ActivitiesAndAmounts
             WHERE
           Amount <> 0 
          ORDER BY
           OrderNumber
            
          ;with SubventionAndAmount as
             (
           SELECT DISTINCT
            'SUBV' AS Code,
            sum(dbo.GetMontantReglementSplit(R.ID_REGLEMENT,null, null, 1)) AS Amount,
            @StartDate AS DATE_DEBUT,
            @EndDate AS DATE_FIN,
            @Reedit  AS REEDITION,
            @UserID  AS ID_UTILISATEUR,
            99   AS OrderNumber
           FROM
            REGLEMENT R
           WHERE
            R.BLN_ACTIF = 1
            AND 
            (
             (
              @Reedit = 1
              AND R.DAT_VALID_REGLEMENT IS NOT NULL
              AND (@StartDate IS NULL OR DATEDIFF(DAY,R.DAT_VALID_REGLEMENT,@StartDate) <= 0)
              AND (@EndDate  IS NULL OR DATEDIFF(DAY,R.DAT_VALID_REGLEMENT,@EndDate ) >= 0)
             )
             OR
             (
              @Reedit <>1
              AND R.BLN_EN_COURS = 1
              AND (@UserID is null or R.ID_UTILISATEUR = @UserID)
             )
            )
             )
             INSERT INTO
           @ActivitiesAndAmounts
          SELECT
           *
             FROM
           SubventionAndAmount
             WHERE
           Amount <> 0
          
          SELECT
           *
          FROM
           @ActivitiesAndAmounts
         
         END
GO
 CREATE PROCEDURE [dbo].[INS_NIVEAU_HABILITATION]
          @COD_NIVEAU_HABILITATION VARCHAR(8), 
          @LIBC_NIVEAU_HABILITATION VARCHAR(20), 
          @LIBL_NIVEAU_HABILITATION VARCHAR(50), 
          @BLN_PRIO TINYINT, 
          @BLN_ACTIF TINYINT, 
          @NUM_ORDRE INTEGER,
          @ID_UTILISATEUR INTEGER,
          @COM_NIVEAU_HABILITATION VARCHAR(255) 
         AS
         BEGIN
          INSERT INTO [NIVEAU_HABILITATION]
          (
           [COD_NIVEAU_HABILITATION],
           [LIBC_NIVEAU_HABILITATION],
           [LIBL_NIVEAU_HABILITATION],
           [BLN_PRIO],
           [BLN_ACTIF],
           [COM_NIVEAU_HABILITATION],
           [DAT_MODIF],
           [DAT_CREATION],
           [NUM_ORDRE],
           [ID_UTILISATEUR]
          )
          VALUES
          (
           @COD_NIVEAU_HABILITATION,
           @LIBC_NIVEAU_HABILITATION,
           @LIBL_NIVEAU_HABILITATION,
           @BLN_PRIO,
           @BLN_ACTIF,
           @COM_NIVEAU_HABILITATION,
           GETDATE(),
           GETDATE(),
           @NUM_ORDRE,
           @ID_UTILISATEUR
          )
         
          SELECT @@IDENTITY AS ID
         END
GO

         
         CREATE PROCEDURE [dbo].[UPD_VIREMENT]  
         	@ID_VIREMENT INT,  
         	@ID_UTILISATEUR INT,
         	@ID_ENVELOPPE_SOURCE INT,
         	@ID_ENVELOPPE_DESTINATION INT,
         	@COM_VIREMENT_ENVELOPPE VARCHAR(255),
         	@TIME_STAMP TIMESTAMP
         AS  
         
         UPDATE VIREMENT_ENVELOPPE SET
         	ID_ENVELOPPE_SOURCE = @ID_ENVELOPPE_SOURCE,
         	ID_ENVELOPPE_DESTINATION = @ID_ENVELOPPE_DESTINATION,
         	ID_UTILISATEUR = @ID_UTILISATEUR,
         	COM_VIREMENT_ENVELOPPE = @COM_VIREMENT_ENVELOPPE
         FROM VIREMENT_ENVELOPPE
         WHERE ID_VIREMENT_ENVELOPPE = @ID_VIREMENT AND
         	TIME_STAMP = @TIME_STAMP
         
         	
           
         IF @@ROWCOUNT = 0   
         BEGIN  
            IF EXISTS(SELECT * FROM VIREMENT_ENVELOPPE WHERE ID_VIREMENT_ENVELOPPE  = @ID_VIREMENT)      
            BEGIN  
               /* Problme de Concurrence d'accs */  
               RAISERROR('Problme de Concurrende d''accs', 16, 1) 
               RETURN -1 
            END 
            ELSE  
            BEGIN  
               /* L'enregistrement a t dtruit */  
               RAISERROR(50002, 16, 1)  
            END      
         END 
         
GO

         
         -- =============================================
         -- Author:		kwame woollams
         -- Create date: 18 septembre 2007
         -- Description:	recupere le pourcentage des virements 
         -- annul‚es par rapport aux virements … valider
         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_PRC_VIR_SELECTIONNEES_ANNULEES]
         AS
         BEGIN
         	DECLARE @PRC AS DECIMAL(18,2)
         
         	DECLARE @NUMERATEUR AS DECIMAL(18,2)
         	DECLARE @DENOMINATEUR AS DECIMAL(18,2)
         	SET @NUMERATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT.ID_REGLEMENT)
         		FROM	REGLEMENT
         		WHERE	REGLEMENT.BLN_EN_COURS = 1 AND
         				REGLEMENT.BLN_CRITERE = 1 AND
         				REGLEMENT.BLN_ACTIF = 0
         	)
         
         	SET @DENOMINATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT.ID_REGLEMENT)
         		FROM	REGLEMENT
         		WHERE	REGLEMENT.BLN_EN_COURS = 1 AND
         				REGLEMENT.BLN_CRITERE = 1
         	)
         
         	 
         		IF @DENOMINATEUR = 0
         			SET @PRC = 0
         
         		IF @DENOMINATEUR != 0 
         			SET @PRC = @NUMERATEUR/@DENOMINATEUR
         	
         
         	SELECT 'Return Value' = COALESCE(ROUND(@PRC,2),0)
         END
         
         
         
         
GO
CREATE PROCEDURE [dbo].[INS_CONTRAT_PRO]
          @ID_CONTRAT_PRO     INT OUTPUT,
          @COD_CONTRAT_PRO    VARCHAR(10) OUTPUT,
          @LIBL_CONTRAT_PRO    VARCHAR(250),
          @DAT_DEB_CONTRAT    DATETIME,
          @DAT_FIN_CONTRAT    DATETIME,
          @DAT_DEB_FORMATION    DATETIME,
          @DAT_FIN_FORMATION    DATETIME,
