          @LIB_ORGANISME_PREVOYANCE  VARCHAR(120),
          @MNT_SALAIRE_BRUT_MENSUEL  DECIMAL(18,2),
          @BLN_CONFORME_ACCORD   TINYINT,
          @BLN_PARTICIPATION_FINANCIERE TINYINT,
          @BLN_EXONERATION_CHARGES  TINYINT,
          @NUM_ENREGISTREMENT_DDTE  VARCHAR(20),
          @DAT_DEPOT_DDTE     DATETIME,
          @DAT_ENREGISTREMENT_DDTE  DATETIME,
          @DAT_CLOTURE     DATETIME,
          @BLN_ORIGINE_SFEIR    TINYINT,
          @ID_UTILISATEUR     INT,
          @ID_CLASSIFICATION    INT,
          @ID_AGENCE      INT,
          @ID_TIERS_DDTE     INT,
          @ID_FORMACODE     INT,
          @ID_PUBLIC_SPECIFIQUE   INT,
          @ID_THEME      INT,
          @ID_NIVEAU      INT,
          @ID_SANCTION     INT,
          @ID_TYPE_ISSUE_PRO    INT,
          @ID_TYPOLOGIE_CONTRAT   INT,
          @ID_SALARIE_PRO     INT,
          @ID_TUTEUR      INT,
          @ID_TYPE_CONTRAT    INT,
          @ID_SPECIALITE     INT,
          @ID_ETABLISSEMENT    INT,
          @ID_ETAT_CONTRAT_PRO   INT,
          @ID_MOTIF_CLOTURE_PRO   INT,
          @ID_TYPE_CONTRAT_PRO   INT,
          @DAT_BAE_INITIALE    DATETIME,
          @LIB_LIEU_FORMATION    VARCHAR(80),
          @ID_IDCC      INT,
          @ID_TYPE_CONTRAT_FAF   INT,
          @NUM_DERNIER_AVENANT   INT,
          @BLN_OK_PIECE     TINYINT,
          @DAT_LETTRE_REFUS    DATETIME,
          @DAT_LETTRE_REJET    DATETIME,
          @BLN_DIPLOME_OBTENU    TINYINT,
          @DAT_RECU_CONTRAT    DATETIME,
          @ID_UTILISATEUR_CREATEUR  INT,
          @ID_CLASSIFICATION_VISEE  INT,
          @ID_ACTION_PEC     INT,
          @ID_CSP_TUTEUR     INT,
          @BLN_ATTESTATION_FORMATION  TINYINT,
          @BLN_TUTEUR_FORME    TINYINT,
          @LIB_LIEU_SIGNATURE    VARCHAR(255),
          @ID_CONTACT_ETABLISSEMENT  INT
         AS
         -- =============================================
         -- Author  : KSA
         -- Create date : 11 janv. 2008
         -- Description : Cr‚ation de la proc‚dure d'insertion contrat
         -- ---------------------------------------------
         -- Modif. date : 29 janv. 2008
         -- Description : Code contrat sur 8
         -- ---------------------------------------------
         -- Modif. date : 04 f‚v. 2008
         -- Description : Modification du NUM DDTE suite … la modification de Kwame Woollams
         ------------------------------------------------
         -- Modif. date : 04 mars. 2008
         -- Gestion de l'ajout de BLN_DIPLOME_OBTENU
         ------------------------------------------------
         -- Modif. date : 06 mars. 2008
         -- 0006978: NUM_DUREE_PERIODE_ESSAI dans CONTRAT_PRO devrait accepter les d‚cimales 
         ------------------------------------------------
         -- Modif. date : 15 janv. 2009
         -- FI251: ajout cl‚ externe ID_ACTION_PEC 
         -- =============================================
         -- Modif. date : 02 mars. 2010
         -- EVOL 12301 : Ajout de la colonne ID_CSP_TUTEUR
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- LDE 06/06/2013 15288: Ouverture Optiform par arguments de l'‚cran Contrat Pro en cr‚ation
         -- Le @COD_CONTRAT_PRO peut ˆtre fourni en entr‚ et doit dans ce cas ˆtre utilis‚.
         -- =============================================
         -- HBO 02/07/2013 : 15376 : CPRO / onglet Employeur : nouvelle case … cocher Attestation formation
         -- =============================================
         -- HBO 04/07/2013 : 15382: CPRO / onglet Salari‚ & Tuteur : Tuteur form‚ : nouvelle case … cocher
         -- =============================================
         -- HBO 05/07/2013 : 15384: CPRO / onglet Le contrat : A (lieu de signature)
         -- =============================================
         -- TLE 08/07/2013 : 15381: CPRO / onglet Salari‚ & Tuteur : Emploi -> champs LIB_QUALIF_TUTEUR … 120
         -- =============================================
         -- HBO : 220713 : M15573: CPRO / onglet Employeur : ‚cart par rapport aux SFD : Contact et e-mail de l'employeur dans le CPRO
         -- =============================================
         -- HBO : 130813 : M15604: NLE - CPro - Onglet contrat - Dur‚e hebdo travail (suite mantis 0015162: D‚tail CPRO / Contrat / Dur‚es)
         -- =============================================
         -- TLE 09/10/2013 : Passage de la taille de LIB_QUALIF_TUTEUR … 35 (avant passage 2.9.60)
         -- =============================================
         -- TLE 23/10/2013 : Passage de la taille de LIB_QUALIF_TUTEUR … 120
         -- =============================================
         -- HBO - 311213 - #16653: NLE - PROD - calcul SMIC
         -- ================================================================
         -- ARI + HBO : #907 : Ajout du dossier PRO dans la table EXPORT_D3R
         -- =============================================
         -- GOK,DSZ 13/04/2016 : US 1152 :  Modification de la taille du parametre champ @LIBL_CONTRAT_PRO de varchar(50) … varchar(250) 
         -- =============================================
         
         BEGIN
          INSERT INTO CONTRAT_PRO
          (
           COD_CONTRAT_PRO,   LIBL_CONTRAT_PRO,   DAT_DEB_CONTRAT,     DAT_FIN_CONTRAT,
           DAT_DEB_FORMATION,   DAT_FIN_FORMATION,   DAT_SIGNATURE_CONTRAT,    BLN_ACTIF,
           DAT_MODIF,     DAT_CREATION,    COM_CONTRAT_PRO,     NUM_NB_SALARIE_ETABLISSEMENT,
           NUM_DUREE_CONTRAT,   NUM_DUREE_FORMATION,  NUM_DUREE_PERIODE_ESSAI,   NUM_DUREE_MENSUELLE_TRAVAIL,
           NUM_DUREE_HEBDO_TRAVAIL_HEURES, NUM_DUREE_HEBDO_TRAVAIL_MINUTES,
           LIB_QUALIF_TUTEUR,   LIBL_QUALIFICATION_VISEE,   DAT_EXAMEN, 
           COEF_CLASSIFICATION,  LIB_EMPLOI_OCCUPE,   LIB_CAISSE_RETRAITE,    LIB_ORGANISME_PREVOYANCE,
           MNT_SALAIRE_BRUT_MENSUEL, BLN_CONFORME_ACCORD,  BLN_PARTICIPATION_FINANCIERE,  BLN_EXONERATION_CHARGES,
           NUM_ENREGISTREMENT_DDTE, DAT_DEPOT_DDTE,    DAT_ENREGISTREMENT_DDTE,   DAT_CLOTURE, 
           BLN_ORIGINE_SFEIR,   ID_UTILISATEUR,    ID_CLASSIFICATION,     ID_AGENCE,
           ID_TIERS_DDTE,    ID_FORMACODE,    ID_PUBLIC_SPECIFIQUE,    ID_THEME,
           ID_NIVEAU,     ID_SANCTION,    ID_TYPE_ISSUE_PRO,     ID_TYPOLOGIE_CONTRAT, 
           ID_SALARIE_PRO,    ID_TUTEUR,     ID_TYPE_CONTRAT,     ID_SPECIALITE,
           ID_ETABLISSEMENT,   ID_ETAT_CONTRAT_PRO,  ID_MOTIF_CLOTURE_PRO,    ID_TYPE_CONTRAT_PRO, 
           DAT_BAE_INITIALE,   LIB_LIEU_FORMATION,   ID_IDCC,       ID_TYPE_CONTRAT_FAF, 
           NUM_DERNIER_AVENANT,  BLN_OK_PIECE,    DAT_LETTRE_REFUS,     DAT_LETTRE_REJET,
           BLN_DIPLOME_OBTENU,   DAT_RECU_CONTRAT,   ID_UTILISATEUR_CREATEUR,   ID_CLASSIFICATION_VISEE,
           ID_ACTION_PEC,    ID_CSP_TUTEUR,    BLN_ATTESTATION_FORMATION,   BLN_TUTEUR_FORME,
           LIB_LIEU_SIGNATURE,   ID_CONTACT_ETABLISSEMENT
          )
          VALUES 
          (
           '',       @LIBL_CONTRAT_PRO,   @DAT_DEB_CONTRAT,     @DAT_FIN_CONTRAT,
           @DAT_DEB_FORMATION,   @DAT_FIN_FORMATION,   @DAT_SIGNATURE_CONTRAT,    @BLN_ACTIF,
           GETDATE(),     GETDATE(),     @COM_CONTRAT_PRO,     @NUM_NB_SALARIE_ETABLISSEMENT, 
           @NUM_DUREE_CONTRAT,   @NUM_DUREE_FORMATION,  @NUM_DUREE_PERIODE_ESSAI,   @NUM_DUREE_MENSUELLE_TRAVAIL,
           @NUM_DUREE_HEBDO_TRAVAIL_HEURES, @NUM_DUREE_HEBDO_TRAVAIL_MINUTES, 
           @LIB_QUALIF_TUTEUR,   @LIBL_QUALIFICATION_VISEE,   @DAT_EXAMEN, 
           @COEF_CLASSIFICATION,  @LIB_EMPLOI_OCCUPE,   @LIB_CAISSE_RETRAITE,    @LIB_ORGANISME_PREVOYANCE,
           @MNT_SALAIRE_BRUT_MENSUEL,  @BLN_CONFORME_ACCORD,  @BLN_PARTICIPATION_FINANCIERE,  @BLN_EXONERATION_CHARGES,
           @NUM_ENREGISTREMENT_DDTE, @DAT_DEPOT_DDTE,   @DAT_ENREGISTREMENT_DDTE,   @DAT_CLOTURE,
           @BLN_ORIGINE_SFEIR,   @ID_UTILISATEUR,   @ID_CLASSIFICATION,     @ID_AGENCE,
           @ID_TIERS_DDTE,    @ID_FORMACODE,    @ID_PUBLIC_SPECIFIQUE,    @ID_THEME,
           @ID_NIVEAU,     @ID_SANCTION,    @ID_TYPE_ISSUE_PRO,     @ID_TYPOLOGIE_CONTRAT, 
           @ID_SALARIE_PRO,   @ID_TUTEUR,     @ID_TYPE_CONTRAT,     @ID_SPECIALITE,
           @ID_ETABLISSEMENT,   @ID_ETAT_CONTRAT_PRO,  @ID_MOTIF_CLOTURE_PRO,    @ID_TYPE_CONTRAT_PRO, 
           @DAT_BAE_INITIALE,   @LIB_LIEU_FORMATION,  @ID_IDCC,       @ID_TYPE_CONTRAT_FAF, 
           @NUM_DERNIER_AVENANT,  @BLN_OK_PIECE,    @DAT_LETTRE_REFUS,     @DAT_LETTRE_REJET,
           0,       @DAT_RECU_CONTRAT,   @ID_UTILISATEUR_CREATEUR,   @ID_CLASSIFICATION_VISEE,
           @ID_ACTION_PEC,    @ID_CSP_TUTEUR,    @BLN_ATTESTATION_FORMATION,   @BLN_TUTEUR_FORME,
           @LIB_LIEU_SIGNATURE,  @ID_CONTACT_ETABLISSEMENT
          )
         
          SELECT @ID_CONTRAT_PRO  = @@IDENTITY
           
          IF (@COD_CONTRAT_PRO IS NOT NULL) -- LDE 06/06/2013 15288
           SET @COD_CONTRAT_PRO = RIGHT('000000000' + CONVERT(VARCHAR(8),@COD_CONTRAT_PRO), 8)
          ELSE
           SET @COD_CONTRAT_PRO = RIGHT('000000000' + CONVERT(VARCHAR(8),@ID_CONTRAT_PRO), 8)
           
          SELECT @COD_CONTRAT_PRO
         
          UPDATE
           CONTRAT_PRO
          SET
           COD_CONTRAT_PRO = @COD_CONTRAT_PRO
          WHERE
           ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         
          EXEC dbo.INS_EXPORT_D3R
           @ID_CONTRAT_PRO,
           'PRO'
         
          RETURN @@IDENTITY
         END
GO

         
         
         -- =============================================
         -- Author:		Say
         -- Create date: 30 mars 2007
         -- Description:	Proc‚dure pour le batch d'‚criture comptable
         -- Modified date : 12 avril 2007
         -- Description: Desactivation du d‚caissement … la demande de M. Blanco
         -- Modified date : 08 novembre 2007
         -- Description: Activation du decaissement … la demande de M. Blanco
         --				suppression des lignes … montant nul
         -- Modified date : 14 janvier 2008
         -- Description: Changement du sens (Debt / Credit) des ecritures negatives.
         -- Modified date : 11 sept 2008
         -- Description: ajout restitution
         -- =============================================
         CREATE PROCEDURE [dbo].[BATCH__RESULTAT_COMPTA]
         AS
         BEGIN
         	exec dbo.BATCH__RESULT_COMPTA_REMISE
         	exec dbo.BATCH__RESULT_COMPTA_IMPAYE
         	exec dbo.BATCH__RESULT_COMPTA_REVERSEMENT
         	exec dbo.BATCH__RESULT_COMPTA_REGULARISATION
         	exec dbo.BATCH__RESULT_COMPTA_REMISE_BANC_DECAISSEMENT
         	--exec dbo.BATCH__RESULT_COMPTA_RESTITUTION
         	
         	DELETE FROM ECRITURE_COMPTABLE WHERE MNT = 0
         
         	UPDATE ECRITURE_COMPTABLE
         	SET MNT = -MNT, SENS = CASE SENS WHEN 'D' THEN 'C' ELSE 'D' END
         	WHERE MNT <= 0
         
         END
         
         
GO
 CREATE PROCEDURE [dbo].[INS_COMPTE]
          @LIBL_COMPTE VARCHAR(50)
            ,@BLN_ACTIF  TINYINT
            -- ,@ID_ADHERENT INT
            ,@ID_GROUPE  INT
            ,@ID_PERIODE  INT
            ,@ID_TYPE_COMPTE INT
            ,@ID_ACTIVITE INT
            ,@ID_TYPE_FINANCEMENT INT 
         AS
         
         -- ==========================================================================================
         -- Author:  SAFI
         -- Create date: 2009/09/02
         -- Description: New control to stop insert existing rows. 
         -- ==========================================================================================
         -- Author:  SAFI : 12549 : 12548
         -- Create date: 2010/11/15 
         -- Description: Renseigner le libell‚ du compte avec le libell‚ du groupe
         --    et ajouter date de creation
         --    supprission de la colonne id_adherent 
         --    dans la table de COMPTE
         -- ==========================================================================================
         -- ASD/OPA 09/12/2014 : #654 Suppression de l'utilisation de l'ID_PUBLIC_FAF
         -- ========================================================================================== 
         BEGIN
          DECLARE @ID_COMPTE INT 
          SET @ID_COMPTE = 0
         
          SELECT 
            @ID_COMPTE = ID_COMPTE
          FROM COMPTE
          WHERE   
              --ID_ADHERENT   = @ID_ADHERENT   AND
              ID_GROUPE   = @ID_GROUPE   AND
              ID_PERIODE   = @ID_PERIODE   AND
              ID_TYPE_COMPTE  = @ID_TYPE_COMPTE  AND
              ID_ACTIVITE   = @ID_ACTIVITE   AND
              ID_TYPE_FINANCEMENT = @ID_TYPE_FINANCEMENT
         
          IF (@ID_COMPTE = 0 )
          BEGIN
           
           --- SAFI 15/11/2010 ----> 
           SELECT  @LIBL_COMPTE = LIB_GROUPE FROM GROUPE WHERE ID_GROUPE = @ID_GROUPE
           --- SAFI 15/11/2010 <---- 
         
         
           INSERT INTO COMPTE
            (
             [LIBL_COMPTE]
               ,[BLN_ACTIF]
               --,[ID_ADHERENT]
               ,[ID_GROUPE]
               ,[ID_PERIODE]
               ,[ID_TYPE_COMPTE]
               ,[ID_ACTIVITE]
               ,[ID_TYPE_FINANCEMENT]
               ,[DAT_CREATION]  
            )
            VALUES
            (
             @LIBL_COMPTE
               ,@BLN_ACTIF
               --,@ID_ADHERENT
               ,@ID_GROUPE
               ,@ID_PERIODE
               ,@ID_TYPE_COMPTE
               ,@ID_ACTIVITE
               ,@ID_TYPE_FINANCEMENT
               ,GETDATE()
            )
         
           RETURN @@IDENTITY
          END
          ELSE
           BEGIN
            RETURN @ID_COMPTE
           END
         END
GO

