         -- Author  : MBL  
         -- Modified date: 05/01/2015
         -- OBJET : Blocage du BAE si D‚synchro entre Activit‚ Historis‚e du Stagiaire et Activit‚ du dispositif PLAN
         -- =======================================================================================================================================
         -- Author  : MBL  
         -- Modified date: 16/06/2015
         -- OBJET : Le Blocage du BAE si D‚synchro entre Activit‚ Historis‚e du Stagiaire et Activit‚ du dispositif PLAN 
         --         n'est effectue que sur les modules actifs
         -- =======================================================================================================================================
         -- Author  : MB
         -- Modif. date  : 13/08/2015
         -- Description  : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
         --                Correction adaptation faite sur US # 219 mal g‚r‚e
         --                Un module dont une (ou +sieurs) piŠce active est absente doit positionner le module en PiŠce manquante et bloquer son engagement 
         --                ce qui n'est plus le cas … ce jour
         -- =======================================================================================================================================
         -- DSZ 20/01/2016 #1123
         -- Ajout statut "Absence lien CPF"
         -- =======================================================================================================================================
         -- OPA 02/03/2016 #1012
         -- En tant que gestionnaire Engagement, depuis l'‚cran de validation des BAE, je veux engager des actions CPF et non CPF.
         -- =======================================================================================================================================
         -- MOU/OPA 03/03/2016 #1056
         -- En tant que gestionnaire Engagement CPF, sur l'‚cran BAE, je veux savoir que la validation d'un dossier CDC est en erreur
         -- =======================================================================================================================================
         -- DSZ 07/03/2016 #1079 ajout @ID_ACTION
         -- =======================================================================================================================================
         -- OPA 01/04/2016 #1123 1123 En tant que gestionnaire Engagement CPF, sur l'‚cran BAE, je ne peux pas engager une action d'un module avec 
         -- au moins une heure sur le dispositif CPF, s'il n'est pas li‚ … un dossier CDC
         -- =======================================================================================================================================
         -- MOU 11/04/2016 #1079 Utilisation de la nouvelle table DEMANDE_CDC pour le calcul du Statut
         -- =======================================================================================================================================
         -- BKE 28/04/2016 #1433 Int‚gration de scripts MBL (voir en dessous)
         -- Author  : MBL
         -- Modif. date  : 21/04/2016
         -- Description  : Blocage du BAE si un des modules … engager n'a jamais ete engage et que la date de cloture comptable de son millesime est d‚pass‚e 
         -- =======================================================================================================================================
         BEGIN  
           
          SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED  
          
          DECLARE @ID_PERIODE_ECHUE  INT  
          -- Declaration variable locale du paramŠtre  
          DECLARE @LOC_ID_UTILISATEUR INT  
          SET  @LOC_ID_UTILISATEUR = @ID_UTILISATEUR --Utiliser cette variable locale comme entr‚e dans les requˆtes  
           
          -- Recherche de la derniere periode de collecte (periode echue)  
          SELECT TOP 1 @ID_PERIODE_ECHUE = ID_PERIODE   
          FROM PERIODE   
          WHERE ID_TYPE_PERIODE = 1  
          AND  GETDATE() >= DAT_COLLECTE_LIMITE_RELIQUAT  
          ORDER BY NUM_ANNEE DESC  
           
          
          DECLARE @AttenteBAE TABLE
         (
           ID_ACTION_PEC int, 
           MNT_A_ENGAGER_HT decimal(18,2),
           CIBLE_ACTION tinyint,  
           ID_ADHERENT int,  
           ADHERENT VARCHAR(255),  
           BLN_OK_FINANCEMENT  tinyint,  
           BLN_OK_PIECE tinyint,
           BLN_OK_ENGAGEMENT tinyint,  
           ENGAGEMENT_POSSIBLE VARCHAR(50),  
           BLN_ETABLISSEMENT_OF tinyint,
           BLN_OF tinyint
         )
         
          -- Recuperation des actions en attente de BAE dans la table @AttenteBAE  
          insert into @AttenteBAE
          (
          ID_ACTION_PEC , 
           MNT_A_ENGAGER_HT,
           CIBLE_ACTION ,  
           BLN_OK_FINANCEMENT  ,  
           BLN_OK_PIECE ,
           BLN_OK_ENGAGEMENT ,  
           BLN_ETABLISSEMENT_OF ,
           BLN_OF 
          )
          SELECT  
          MODULE_PEC.ID_ACTION_PEC,  
          MNT_A_ENGAGER_HT = ISNULL(SUM(ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0)),0) ,  
          CIBLE_ACTION = MIN(ACTION_PEC.CIBLE_ACTION),  
          BLN_OK_FINANCEMENT  = MIN(BLN_OK_FINANCEMENT),  
          BLN_OK_PIECE = MIN(MODULE_PEC.BLN_OK_PIECE),
           -- OPA 07/04/2014
          BLN_OK_ENGAGEMENT = MIN(COALESCE(PIECEMODULEPEC.BLN_OK_ENGAGEMENT, 1)),  
           -- BBL 06/06/2011
          BLN_ETABLISSEMENT_OF = MIN(ISNULL( ETABLISSEMENT_OF.BLN_ACTIF , 1)),
          BLN_OF = MIN(ISNULL( ORGANISME_FORMATION.BLN_ACTIF , 1))   
           FROM MODULE_PEC 
          INNER JOIN ACTION_PEC   ON ACTION_PEC.ID_ACTION_PEC    = MODULE_PEC.ID_ACTION_PEC   
           INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC   = MODULE_PEC.ID_MODULE_PEC
           -- MBL Modif du  24/09/2014 : Blocage du BAE si des PCE non approuves et sans PFUS sont associes a l'action
           -- INNER JOIN PLAN_FINANCEMENT_US ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE  
           LEFT JOIN PLAN_FINANCEMENT_US ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE  
           -- OPA 07/04/2014
           LEFT JOIN 
           (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
           0 AS BLN_OK_ENGAGEMENT
             FROM ARRIVEE_PIECE_PEC 
             INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
             INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC   
             AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
             AND
             (
           ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
           OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
             )
           -- Modif MB . du 13/08/2015 : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
           --WHERE ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
           AND PIECE_PEC.BLN_ACTIF = 1   
             GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC) PIECEMODULEPEC ON PIECEMODULEPEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
          -- BBL 06/06/2011  
          LEFT JOIN ETABLISSEMENT_OF  ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF AND MODULE_PEC.BLN_EXTERNE = 1  
          LEFT JOIN ORGANISME_FORMATION   ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF  
          WHERE 
          (@ID_ACTION is not null OR ACTION_PEC.ID_UTILISATEUR   = @LOC_ID_UTILISATEUR) -- derniŠre modification a ‚t‚ r‚alis‚e par l'utilisateur pass‚ en paramŠtre @LOC_ID_UTILISATEUR   
          AND (@ID_ACTION is null or ACTION_PEC.ID_ACTION_PEC = @ID_ACTION)
          AND  ACTION_PEC.BLN_ACTIF = 1     -- Actions actives  
          AND  ACTION_PEC.DAT_CLOTURE IS NULL    -- Actions non cloturees  
          AND  ACTION_PEC.BLN_CYCLE_COURT = 0     -- Actions en cycle court  
          AND  MODULE_PEC.BLN_IMPUTABLE = 1     -- Modules imputables  
          AND  MODULE_PEC.BLN_ACTIF = 1     -- Modules actifs  
          AND  POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL    -- Postes de cout non engages  
          AND  POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL    -- Postes de cout non desengages  
          
          -- MBL Modif du 21/08/2014 : Prise en compte des PCE avec Monatnt demand‚ … 0
          -- AND COALESCE (POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT,0) <> 0   
          AND COALESCE (POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT,0) >= 0   
          AND  MODULE_PEC.DAT_CLOTURE IS NULL       --suite … l'evol cloture du module DSZ 24/05/2012  
          GROUP BY MODULE_PEC.ID_ACTION_PEC 
           
          -- Recherche du code et du libelle des adherents pour les actions individuelles  
          UPDATE @AttenteBAE  
          SET  ID_ADHERENT = ETABLISSEMENT .ID_ADHERENT,  
               ADHERENT = CAST(ADHERENT.COD_ADHERENT AS VARCHAR(10)) + ' ' + ADHERENT.LIB_RAISON_SOCIALE  
          FROM  @AttenteBAE A
          INNER JOIN NR140   ON A.ID_ACTION_PEC = NR140.ID_ACTION_PEC 
          INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140 .ID_ETABLISSEMENT   
          INNER JOIN ADHERENT  ON ETABLISSEMENT.ID_ADHERENT   = ADHERENT .ID_ADHERENT  
          WHERE A.CIBLE_ACTION = 1  
              
           
          -- Calcul du montant collect‚ surl'activite PROF et la periode de collecte echue par les adherents  
          -- pour les actions individuelles  
          SELECT  SUM(POSTE_IMPUTATION.MNT_HT)    AS COLLECTE_VERSEE,    
            POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE AS ID_ADHERENT_BENEFICIAIRE  
          INTO #COLLECTE_PCR  
          FROM  POSTE_IMPUTATION  
          INNER JOIN POSTE_VERSEMENT  ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT  = POSTE_VERSEMENT.ID_POSTE_VERSEMENT  
          INNER JOIN VERSEMENT   ON POSTE_VERSEMENT.ID_VERSEMENT    = VERSEMENT.ID_VERSEMENT  
          INNER JOIN @AttenteBAE A on POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE = A.ID_ADHERENT 
          INNER JOIN ACTIVITE on POSTE_IMPUTATION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE 
          WHERE ACTIVITE.COD_ACTIVITE = 'PRO'
          AND  POSTE_VERSEMENT.ID_PERIODE = @ID_PERIODE_ECHUE  
          AND  POSTE_VERSEMENT.BLN_ACTIF = 1  
          AND  VERSEMENT.BLN_ACTIF = 1  
          AND  VERSEMENT.BLN_IMPAYE = 0  
           GROUP BY POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE 
           
            -- Calcul du montant deja engage sur les differentes actions  
          SELECT ID_ACTION_PEC  = MODULE_PEC.ID_ACTION_PEC ,  
           MNT_DEJA_ENGAGE_HT = ISNULL(SUM(PCE.MNT_ENGAGE_HT), 0)  
          INTO #TMP_MNT_DEJA_ENGAGE  
          FROM POSTE_COUT_ENGAGE PCE  
          INNER JOIN MODULE_PEC ON MODULE_PEC .ID_MODULE_PEC = PCE.ID_MODULE_PEC  
          INNER JOIN @AttenteBAE  A ON MODULE_PEC.ID_ACTION_PEC = A.ID_ACTION_PEC  
          WHERE  PCE.ID_ENGAGEMENT IS NOT NULL   
          AND  PCE.DAT_DESENGAGEMENT IS NULL  
          GROUP BY MODULE_PEC. ID_ACTION_PEC  
           
         -- Determination des actions avec Chiffrage inacheve (faire avant le reste)  
         UPDATE @AttenteBAE  
         SET  ENGAGEMENT_POSSIBLE = 'Chiffrage inachev‚'  
         WHERE ENGAGEMENT_POSSIBLE IS NULL  
         AND  BLN_OK_FINANCEMENT = 0  
           
         -- BBL 06/06/2011  
         -- Determination des actions avec organisme de formation inactif portant sur un type de co–t … engager CP  
         UPDATE A 
         SET  ENGAGEMENT_POSSIBLE = 'Etab. OF Inactif'  
         FROM @AttenteBAE A
         WHERE ENGAGEMENT_POSSIBLE IS NULL   
         AND  (BLN_ETABLISSEMENT_OF = 0 OR BLN_OF = 0)  
         AND  EXISTS (  
             SELECT 1  
             FROM POSTE_COUT_ENGAGE T1  
             JOIN MODULE_PEC T2  
             ON  T1.ID_MODULE_PEC = T2.ID_MODULE_PEC  
             JOIN SOUS_TYPE_COUT T3  
             ON  T1.ID_SOUS_TYPE_COUT = T3.ID_SOUS_TYPE_COUT  
             JOIN TYPE_COUT T4  
             ON  T4.ID_TYPE_COUT = T3.ID_TYPE_COUT  
             WHERE T2.ID_ACTION_PEC = A.ID_ACTION_PEC  
             AND  T1.ID_ENGAGEMENT IS NULL  
             AND  T1.DAT_DESENGAGEMENT IS NULL  
             AND  T4.COD_TYPE_COUT = 'CP'  
             )  
                   
         --#1123 lien CPF #1012 En attente CDC
         UPDATE A  
         SET  ENGAGEMENT_POSSIBLE = 'Absence lien CPF'
         FROM @AttenteBAE A
         -- pour l'un de ses modules, un stagiaire possŠde au moins 1 heure (non refus‚e) sur le dispositif CPF
         INNER JOIN MODULE_PEC mp on A.ID_ACTION_PEC =  mp.ID_ACTION_PEC 
         INNER JOIN STAGIAIRE_PEC sp on mp.ID_MODULE_PEC = sp.ID_MODULE_PEC 
         INNER JOIN UNITE_STAGIAIRE us on us.ID_STAGIAIRE_PEC = sp.ID_STAGIAIRE_PEC 
         AND us.NB_HEURE_ENGAGE >= 1 --au moins 1 heure
         AND us.BLN_REFUS = 0 --(non refus‚e)
         INNER JOIN DISPOSITIF d on  us.ID_DISPOSITIF = d.ID_DISPOSITIF  
         AND COD_DISPOSITIF = 'CPF' --sur le dispositif CPF
         LEFT JOIN STAGIAIRE_PEC_CDC spc on spc.ID_STAGIAIRE_PEC = sp.ID_STAGIAIRE_PEC 
         WHERE ENGAGEMENT_POSSIBLE IS NULL
         AND spc.NUM_DOSSIER_CDC IS NULL
         AND sp.ID_SESSION_PEC IS NULL
         
         --#1123 lien CPF #1012 En attente CDC
         UPDATE @AttenteBAE 
         SET  ENGAGEMENT_POSSIBLE = (
          CASE WHEN dc.STATUT_DEMANDE = 'EnAttenteEnvoi' -- un dossier CDC est en attente d'envoi cdc
           THEN 'En attente CDC'
          WHEN dc.STATUT_DEMANDE = 'ValidationKO' -- un dossier CDC est erreur (le retour de la CDC est ValidationKO)
           THEN 'Erreur engagement CDC'
          END)
         FROM @AttenteBAE A
         -- pour l'un de ses modules, un stagiaire possŠde au moins 1 heure (non refus‚e) sur le dispositif CPF
         INNER JOIN MODULE_PEC mp on A.ID_ACTION_PEC =  mp.ID_ACTION_PEC 
         INNER JOIN STAGIAIRE_PEC sp on mp.ID_MODULE_PEC = sp.ID_MODULE_PEC 
         INNER JOIN UNITE_STAGIAIRE us on us.ID_STAGIAIRE_PEC = sp.ID_STAGIAIRE_PEC 
         LEFT JOIN STAGIAIRE_PEC_CDC spc on spc.ID_STAGIAIRE_PEC = sp.ID_STAGIAIRE_PEC
         LEFT JOIN DEMANDE_CDC dc on dc.ID_STAGIAIRE_PEC_CDC = spc.ID_STAGIAIRE_PEC_CDC  
         WHERE ENGAGEMENT_POSSIBLE IS NULL
         
         /* MBL Ajout du 21/04/2016 : 
         Blocage du BAE si un des modules … engager n'a jamais ete engage et que la date de cloture comptable de son millesime est d‚pass‚e 
         */
         UPDATE @AttenteBAE  
         SET  ENGAGEMENT_POSSIBLE = 'Mill‚sime cl“tur‚'  
         --FROM MODULE_PEC 
         FROM @AttenteBAE A
         INNER JOIN MODULE_PEC mp ON A.ID_ACTION_PEC = mp.ID_ACTION_PEC
         INNER JOIN PERIODE p ON mp.ID_PERIODE  = p.ID_PERIODE
         LEFT JOIN 
         ( SELECT  ID_MODULE_PEC, 
             DAT_BAE_INIT_MODULE = MIN(DAT_BAE) 
          FROM  ENGAGEMENT 
          INNER JOIN POSTE_COUT_ENGAGE ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
          WHERE  DAT_BAE IS NOT NULL
          GROUP BY ID_MODULE_PEC
         )
         ENG_INIT_MODULE ON ENG_INIT_MODULE.ID_MODULE_PEC = mp.ID_MODULE_PEC 
         WHERE A.ENGAGEMENT_POSSIBLE IS NULL  
         AND  DAT_BAE_INIT_MODULE IS NULL       -- Module Jamais engage
         AND   p.DAT_CLOTURE_COMPTABLE_PERIODE <= GETDATE() -- Date de cloture comptable du millesime du module d‚pass‚e 
         /* Fin MB Ajout du 21/04/2016 */
           
         /* MBL Ajout du 05/01/2015 : 
         Blocage du BAE si D‚synchro entre Activit‚ Historis‚e du Stagiaire et Activit‚ du dispositif PLAN
         */
         UPDATE A  
         SET  ENGAGEMENT_POSSIBLE = 'D‚synchro Activit‚ Historis‚e Stagiaire'  
         from MODULE_PEC 
         INNER JOIN @AttenteBAE A ON MODULE_PEC.ID_ACTION_PEC= A.ID_ACTION_PEC
         INNER JOIN STAGIAIRE_PEC ON MODULE_PEC.ID_MODULE_PEC = STAGIAIRE_PEC .ID_MODULE_PEC 
         INNER JOIN UNITE_STAGIAIRE ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC .ID_STAGIAIRE_PEC 
         INNER JOIN DISPOSITIF ON DISPOSITIF.ID_DISPOSITIF = UNITE_STAGIAIRE.ID_DISPOSITIF
         where DISPOSITIF .BLN_PLAN = 1
         AND DISPOSITIF .ID_ACTIVITE != STAGIAIRE_PEC.ID_ACTIVITE
         AND A.ENGAGEMENT_POSSIBLE IS NULL  
         -- MBL Ajout du 16/06/2015 : 
         AND MODULE_PEC.BLN_ACTIF = 1
         /* Fin MB Ajout du 05/01/2015*/
             
          -- Recherche s'il existe un pb de desynchronisation des plans de financement  
          -- et s'il existe un financement interdit par l'operation financiere  
          -- et s'il existe un financement theoriquement interdit  (fena)  
            
          SELECT (SELECT FROM_FONCTION FROM F_C2P_AUDIT_FINANCEMENTDESYNCHRONISE_LIGHT_BYACTION(T.ID_ACTION_PEC)) AS FD,  
             (SELECT FROM_FONCTION FROM F_C2P_AUDIT_FINANCEMENTNONAUTORISEPAROPERATIONFINANCIERE_LIGHT_BYACTION(T.ID_ACTION_PEC)) AS FNAPOF,  
             (SELECT FROM_FONCTION FROM F_C2P_AUDIT_FINANCEMENTENGAGEMENTNONAUTORISE_LIGHT_BYACTION(T.ID_ACTION_PEC)) AS FENA,  
             ID_ACTION_PEC  
           INTO #TEMPLIST2  
           FROM @AttenteBAE T  
            WHERE  T.ENGAGEMENT_POSSIBLE IS NULL  
              
          UPDATE T  
          SET  T.ENGAGEMENT_POSSIBLE =   
            CASE WHEN FENA IS NOT NULL AND FENA='fena'  
             THEN  
             'Financement Interdit'  
             ELSE 'ProblŠme Financement'       
            END  
           FROM #TEMPLIST2 T2  
          INNER JOIN @AttenteBAE T  
          ON  T.ID_ACTION_PEC = T2.ID_ACTION_PEC  
          WHERE (FD IS NOT NULL AND LEN(FD)>0)  
             OR (FENA IS NOT NULL AND LEN(FENA)>0)  
             OR (FNAPOF IS NOT NULL AND LEN(FNAPOF)>0)  
         
         
         -- UPDATE T  
         -- SET  T.ENGAGEMENT_POSSIBLE = 'ProblŠme Financement'  
         -- FROM (select * from F_C2P_AUDIT_FinancementNonAutoriseParOperationFinanciere_light()) F  
         -- INNER JOIN #TEMPLIST T  
         -- ON  T.ID_ACTION_PEC = F.ID_ACTION_PEC  
         -- AND  T.ENGAGEMENT_POSSIBLE IS NULL  
         --   
         -- UPDATE T  
         -- SET  T.ENGAGEMENT_POSSIBLE = 'Financement Interdit'  
         -- FROM (select * from F_C2P_AUDIT_FinancementEngagementNonAutorise_light()) F  
         -- INNER JOIN #TEMPLIST T  
         -- ON  T.ID_ACTION_PEC = F.ID_ACTION_PEC  
         -- AND  T.ENGAGEMENT_POSSIBLE IS NULL    
           
          -- Determination des actions avec pieces manquantes (si BLN_OK_ENGAGEMENT = 0) ou Chiffrage Possible  
          UPDATE @AttenteBAE  
          SET ENGAGEMENT_POSSIBLE =   
            CASE WHEN (BLN_OK_ENGAGEMENT = 0) THEN   
             'PiŠce Manquante'  
             ELSE  
             'Possible'  
             END   
          WHERE ENGAGEMENT_POSSIBLE IS NULL  
          --AND  BLN_OK_PIECE = 0  
           
           
          SELECT  
           ACTION_PEC.ID_ACTION_PEC,  
           ACTIVE_BAE = 0,  
           ACTION_PEC.COD_ACTION_PEC,  
           ACTION_PEC.ANNEE_ACTION_PEC,  
           CODE_ACTION_PEC = DBO.GETACTIONPECCODE(ACTION_PEC.COD_ACTION_PEC,ACTION_PEC.ANNEE_ACTION_PEC),  
           ACTION_PEC.LIBL_ACTION_PEC,  
           ADHERENT = CASE   
            WHEN ACTION_PEC.CIBLE_ACTION = 1   
             THEN A.ADHERENT  
            WHEN ACTION_PEC.CIBLE_ACTION = 2   
             THEN ' AIC'  
            ELSE ' AC'  
           END,  
           ACTION_PEC.DAT_DEB_ACTION_PEC,  
           ACTION_PEC.DAT_FIN_ACTION_PEC,  
           MNT_ENGAGE   = ISNULL(A.MNT_A_ENGAGER_HT ,0),  
           MNT_DEJA_ENGAGE  = ISNULL(#TMP_MNT_DEJA_ENGAGE.MNT_DEJA_ENGAGE_HT,0) ,  
           ENGAGEMENT_POSIBLE = A.ENGAGEMENT_POSSIBLE,  
           COLLECTE_VERSEE  = ROUND(ISNULL(#COLLECTE_PCR.COLLECTE_VERSEE,0),2)  
          FROM  @AttenteBAE A 
          INNER JOIN ACTION_PEC    ON ACTION_PEC .ID_ACTION_PEC = A.ID_ACTION_PEC   
          LEFT JOIN #COLLECTE_PCR   ON A.ID_ADHERENT  = #COLLECTE_PCR.ID_ADHERENT_BENEFICIAIRE  
          LEFT JOIN #TMP_MNT_DEJA_ENGAGE ON A.ID_ACTION_PEC  = #TMP_MNT_DEJA_ENGAGE.ID_ACTION_PEC  
          ORDER BY A.ID_ACTION_PEC DESC
         END
GO
 CREATE PROCEDURE [dbo].[UPD_PIECES_REGLEMENT]
          @ID_PIECE int,
          @BLN_ACTIF int,
          @BLN_CONFORME int,
          @ID_POSTE_COUT_REGLE int,
          @ID_MODULE_PEC int,
          @ID_ARRIVEE_PIECE_PEC int output,
             @BLN_OK_PIECE_RAZ bit
         AS
         -- =============================================
         -- Author:  XX
         -- Create date: XX XX 2007
         -- Description: Cr‚ation
         -- =============================================
         -- Author:  SV
         -- Create date: 17 ao–t 2007
         -- Description: Suppression de la partie concernant la gestion de l'‚tat des piŠces
         --     ==> Rel‚gu‚ … une autre proc‚dure
         -- =============================================
         -- Author:  SAFI
         -- Create date: 28/12/2010
         -- Description: Settint the DAT_ARRIVEE_PIECE_PEC to null if the BLN_ACTIF = 0
         -- =============================================
         -- Author:  SAFI
         -- Create date: 08/02/2011 : 12559
         -- Description: Save only the pieces which 
         -- are non conform or no present
         -- =============================================
         -- Author:  APA
         -- Description: Nettoyage function
         --    utilisation pour la DR
         -- ===============================================
         -- DSZ 14/06/2012 13600 ajout cod_arrivee_piece_pec dans l'insert
         -- ===============================================
         BEGIN
         
          IF (@BLN_ACTIF IS NULL)
          BEGIN
           SET @BLN_ACTIF = 0
          END
         
          IF (@BLN_CONFORME IS NULL)
          BEGIN
           SET @BLN_CONFORME = 0
          END
         
          DECLARE @NUMREG INT
          
          SET @NUMREG = 0
          
          SELECT
           @NUMREG = COUNT(*)
          FROM
           ARRIVEE_PIECE_PEC
          WHERE
           ID_PIECE_PEC = @ID_PIECE
           AND ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
          
          DECLARE @UserId INT
          SELECT
           @UserId = ID_UTILISATEUR
          FROM
           UTILISATEUR
          WHERE
           COD_util = 'admin'
         
          IF (@NUMREG > 0)
          BEGIN  
           IF (@BLN_ACTIF = 0 OR @BLN_CONFORME = 0)
           BEGIN
            UPDATE
             ARRIVEE_PIECE_PEC 
            SET
             BLN_ACTIF = @BLN_ACTIF,
             BLN_CONFORME = @BLN_CONFORME,
             ID_UTILISATEUR = @UserId
            WHERE
             ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
             AND ID_PIECE_PEC = @ID_PIECE
           END
           ELSE 
           BEGIN   
            DECLARE @ID INT
         
            SELECT
             @ID = ID_ARRIVEE_PIECE_PEC
            FROM
             ARRIVEE_PIECE_PEC
            WHERE
             ID_PIECE_PEC = @ID_PIECE
             AND ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
             AND ID_MODULE_PEC = @ID_MODULE_PEC
         
            DELETE FROM NR210
            WHERE ID_ARRIVEE_PIECE_PEC = @ID
            
            DELETE FROM ARRIVEE_PIECE_PEC
            WHERE ID_ARRIVEE_PIECE_PEC = @ID
           END 
          END
          ELSE
          BEGIN  
           IF (@BLN_ACTIF = 0 OR @BLN_CONFORME = 0)
           BEGIN
            INSERT INTO ARRIVEE_PIECE_PEC
            (
             BLN_ACTIF,
             BLN_CONFORME,
             ID_POSTE_COUT_REGLE,
             ID_PIECE_PEC,
             DAT_ARRIVEE_PIECE_PEC,
             ID_MODULE_PEC,
             COD_ARRIVEE_PIECE_PEC,
             ID_UTILISATEUR
            )
            VALUES
            (
             @BLN_ACTIF,
             @BLN_CONFORME,
             @ID_POSTE_COUT_REGLE,
             @ID_PIECE,
             GETDATE(),
             @ID_MODULE_PEC,
             0,
             @UserId
            )
            
            UPDATE
             ARRIVEE_PIECE_PEC
            SET
             COD_ARRIVEE_PIECE_PEC = SCOPE_IDENTITY()
            WHERE
             ID_ARRIVEE_PIECE_PEC = SCOPE_IDENTITY()
           END
           ELSE 
           BEGIN
            DELETE FROM NR210
            WHERE ID_ARRIVEE_PIECE_PEC = @ID
            
            DELETE FROM ARRIVEE_PIECE_PEC
            WHERE ID_ARRIVEE_PIECE_PEC = @ID
           END 
          END
         END
GO
 -- =============================================
         -- Author:		SAFI/DCL
         -- Create date: 05-03-2009
         -- Description:	suppression des Etablissement li‚ a une action et les arrivee piece
         -- =============================================
         -- Author:		SAFI
         -- Create date: 06-06-2009
         -- Description:	suppression de toutes lignes en 
         -- ARRIVEE_PIECE_PEC si l'adherent supprimer completement.
         -- =============================================
         -- Author:		RVI
         -- Create date: 2012-04-24
         -- Description:	Modification de l'ordre d'ex‚cution : v‚rification et
         -- suppression des piŠces AVANT la suppresion de la liaison
         -- sinon on fait comment pour les retrouver ?!
         -- =============================================
         	CREATE PROCEDURE [dbo].[DEL_ETABLISSEMENT_ACTION]
         	@ID_ACTION INT,  
         	@ID_ETABLISSEMENT INT
         
         AS
         BEGIN	
         	SET NOCOUNT ON;    
         
         	DECLARE @ID_ADHERENT  INT	
         	DECLARE @ADHERENT_COUNT INT
         
         -- Get the Adherent of the Etablisssement deleted from NR140
         	SELECT @ID_ADHERENT = ID_ADHERENT FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         
         -- Verify if the same Adherent Exists in NR140 for other Etablissements of the same Action PEC.
         -- If the count is not zero, that means we have lins exist for the same adherent, else no more lines for the same adherent.
         	SET @ADHERENT_COUNT = 0
         	SELECT @ADHERENT_COUNT  = COUNT(*)
         	FROM NR140
         	INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         	INNER JOIN ADHERENT		ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	WHERE NR140.ID_ACTION_PEC = @ID_ACTION AND
         	ADHERENT.ID_ADHERENT = (SELECT ID_ADHERENT FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
         
         
         
         IF @ADHERENT_COUNT <= 0
         	BEGIN
         		
         		
         		SELECT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC	
         		INTO #TEMP_LIST
         		FROM NR210
         		INNER JOIN	ACTION_PEC			ON	ACTION_PEC.ID_ACTION_PEC				=	@ID_ACTION
         		INNER JOIN	MODULE_PEC			ON	MODULE_PEC.ID_ACTION_PEC				=   @ID_ACTION
         		INNER JOIN	ETABLISSEMENT		ON	ETABLISSEMENT.ID_ETABLISSEMENT			=	@ID_ETABLISSEMENT     
         		INNER JOIN	ADHERENT			ON	ADHERENT.ID_ADHERENT	 				=	ETABLISSEMENT.ID_ADHERENT
         		INNER JOIN	ARRIVEE_PIECE_PEC	ON	ARRIVEE_PIECE_PEC.ID_ADHERENT			=	ADHERENT.ID_ADHERENT										
         		INNER JOIN	PIECE_PEC			ON	PIECE_PEC.ID_PIECE_PEC					=	ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         		WHERE								ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC	=	NR210.ID_ARRIVEE_PIECE_PEC
         								
         
         		DELETE FROM NR210				WHERE ID_ARRIVEE_PIECE_PEC IN (SELECT ID_ARRIVEE_PIECE_PEC FROM  #TEMP_LIST)
         		DELETE FROM ARRIVEE_PIECE_PEC	WHERE ID_ARRIVEE_PIECE_PEC IN (SELECT ID_ARRIVEE_PIECE_PEC FROM  #TEMP_LIST)
         		
         
         		SET @ADHERENT_COUNT = 0
         		SELECT @ADHERENT_COUNT  = COUNT(*)
         		FROM NR140
         		INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         		INNER JOIN ADHERENT		ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE NR140.ID_ACTION_PEC = @ID_ACTION AND
         		ADHERENT.ID_ADHERENT = (SELECT ID_ADHERENT FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
         
         		
         		IF @ADHERENT_COUNT <= 0
         		BEGIN 		
         			DELETE ARRIVEE_PIECE_PEC FROM 
         			MODULE_PEC 
         			WHERE
         			ARRIVEE_PIECE_PEC.ID_ADHERENT = @ID_ADHERENT	AND
         			MODULE_PEC.ID_MODULE_PEC IN (SELECT ID_MODULE_PEC FROM MODULE_PEC WHERE ID_ACTION_PEC = @ID_ACTION)		
         		END
         
         	END
         
         		UPDATE MODULE_PEC
         		SET BLN_OK_PIECE = case WHEN EXISTS (SELECT ID_MODULE_PEC FROM ARRIVEE_PIECE_PEC APP
         											WHERE APP.ID_MODULE_PEC = MP.ID_MODULE_PEC) THEN 0 ELSE 1 END
         		FROM MODULE_PEC MP
         		WHERE ID_ACTION_PEC = @ID_ACTION
         
         
         -- DELETE * FROM NR140 (Etablissement of the Action)
         	DELETE FROM NR140 
         	WHERE 
         	ID_ACTION_PEC = @ID_ACTION AND 
         	ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         
         END
         
GO

         
         -- =============================================
         -- Author:		DSZ
         -- Create date: 22/06/2012
         -- Description:	13625
         -- =============================================
         CREATE PROCEDURE UPD_OFFRE_SERVICE_DOCUMENT 
         	@ID_OFFRE_SERVICE int,
         	@COD_DOCUMENT1 varchar(15),
         	@COD_DOCUMENT2 varchar(15),
         	@COD_DOCUMENT3 varchar(15),
         	@ID_UTILISATEUR int
         AS
         BEGIN
         	SET NOCOUNT ON;
         	delete from OFFRE_SERVICE_DOCUMENT
         	where ID_OFFRE_SERVICE = @ID_OFFRE_SERVICE
         	
         	insert into OFFRE_SERVICE_DOCUMENT (ID_OFFRE_SERVICE, ID_DOCUMENT, ID_UTILISATEUR, DAT_CREATION)
         	select
         		@ID_OFFRE_SERVICE,
         		ID_DOCUMENT,
         		@ID_UTILISATEUR,
         		GETDATE()
         	from DOCUMENT 
         	where 
         		(DOCUMENT.COD_DOCUMENT = @COD_DOCUMENT1)
         		OR
         		(DOCUMENT.COD_DOCUMENT = @COD_DOCUMENT2)
         		OR
         		(DOCUMENT.COD_DOCUMENT = @COD_DOCUMENT3)
         	
         END
         
GO
 -- =============================================
         -- Author		: XXX
         -- Create date	: XX XXX XXX
         -- Comment		:
         -- ---------------------------------------------
         -- Author		: SV
         -- Modified date: 29 ao–t 2007
         -- Comment		: Ajout de la modification de la date de modification d'une action cl“tur‚e
         -- ---------------------------------------------
         -- Author		: SV
         -- Modified date: 09 octobre 2007
         -- Comment		: Ajout de l'appel de la proc‚dure charg‚e de cr‚er les ‚vˆnements et les mouvements budg‚taires ad‚quats
         -- =============================================
         -- Author		: SAFI
         -- Modified date: 12/08/2011
         -- Ano ID		: 12797
         -- comment		: Ajouter un parameter ID_UTILISATEUR 
         -- =============================================
         -- Author		: RVI
         -- Modified date: 17/04/2012
         -- Ano ID		: 13370
         -- comment		: Ajouter Num‚ro d'archivage et agence
         -- =============================================
         -- HBO - 20140415 #116
         -- =============================================
         -- HBO - 20140731 #148A
         -- =============================================
         -- LDE 05/08/2014 #145 En tant qu'utilisateur OPTIFORM, je cl“ture l'Action PEC courante afin de g‚n‚rer les ‚vŠnements et mouvements budg‚taires associ‚s
         -- Recƒblage des mouvements budgetaire de cl“ture d'action
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_ACTION_CLOTURE]
         	@ID_ACTION_PEC			INT,
         	@ID_MOTIF_CLOTURE_PEC	INT,
         	@ID_UTILISATEUR			INT,
         	@ID_AGENCE_CLOTURE		INT = NULL,
         	@NUM_ARCHIVE			VARCHAR(17) OUT
         AS
         BEGIN
         	BEGIN TRY
         		DECLARE
         			@COMPTEUR INT,
         			@COD_AGENCE VARCHAR(8)
         
         		IF(@ID_AGENCE_CLOTURE IS NULL)
         		BEGIN
         			SELECT
         				@ID_AGENCE_CLOTURE = ID_AGENCE
         			FROM
         				UTILISATEUR
         			WHERE
         				ID_UTILISATEUR = @ID_UTILISATEUR
         		END
         	
         		IF (@ID_MOTIF_CLOTURE_PEC <> 0)
         		BEGIN
         			BEGIN TRANSACTION
         		
         			EXEC @COMPTEUR = [dbo].[GET_COMPTEUR_SUIVANT] 'NUM_ARCHIVE'
         		
         			SELECT @COD_AGENCE = COD_AGENCE FROM AGENCE WHERE ID_AGENCE = @ID_AGENCE_CLOTURE
         	
         			SELECT @NUM_ARCHIVE = CONVERT(VARCHAR(8), @COMPTEUR) + '/' + @cod_agence
         	
         			UPDATE
         				ACTION_PEC
         			SET
         				ID_MOTIF_CLOTURE_PEC = @ID_MOTIF_CLOTURE_PEC,
         				DAT_CLOTURE = GetDate(),
         				DAT_MODIF = GetDate(),
         				ID_UTILISATEUR = @ID_UTILISATEUR,
         				ID_AGENCE_CLOTURE = @ID_AGENCE_CLOTURE,
         				NUM_ARCHIVE = @NUM_ARCHIVE
         			WHERE
         				ID_ACTION_PEC = @ID_ACTION_PEC
         
         			--	D‚branchement Mvts Budg‚taires pour cl“ture action PEC
         			-- LDE 05/08/2014 #145
         			EXEC INS_MVT_BUDGETAIRE_CLOTURE_ACTION_PEC @ID_ACTION_PEC, @ID_UTILISATEUR;
         
         			COMMIT
         		END
         	END TRY
         	BEGIN CATCH
         		IF @@TRANCOUNT > 0
         			ROLLBACK
         		
         		SET @NUM_ARCHIVE = NULL
         				
         		DECLARE
         			@ErrMsg nvarchar(4000),
         			@ErrSeverity int
         
         		SELECT
         			@ErrMsg = ERROR_MESSAGE(),
         			@ErrSeverity = ERROR_SEVERITY()
         
         		RAISERROR(@ErrMsg, @ErrSeverity, 1)
         	END CATCH
         END
GO

         
         -- =============================================
         -- Author:		SAFI
         -- Create date: 03-06-2009
         -- Description:	SYNC NB HEUR ENGAGE DE STAGIAIRE DE L'ACTION
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_STAGIAIRE_SOLDE_NEGATIF]
         	-- Add the parameters for the stored procedure here
         	@ID_ACTION_PEC INT,
         	@ID_MODULE_PEC INT,
         	@NB_HEUR_ENGAGE_N DECIMAL(18,2),	
         	@NOM_PRENOM_STAGIAIRE_FOUND varchar(110) OUTPUT
         	--@ID_SESSION_FOUND INT	OUTPUT
         	
         AS
         BEGIN
         DECLARE @ID_STAGIAIRE INT 
         DECLARE @ID_INDIVIDU INT
         DECLARE @ID_SESSION_PEC INT
         DECLARE @ID_STAGIAIRE_FOUND INT 
         --DECLARE @ID_STAGIAIRE_FOUND INT
         --DECLARE @ID_SESSION_FOUND INT
         
         
         --SET @ID_ACTION_PEC = 142711
         --SELECT @ID_MODULE_PEC = ID_MODULE_PEC 
         --FROM MODULE_PEC WHERE 
         --ID_ACTION_PEC = @ID_ACTION_PEC
         
         --DROP TABLE #TMP_STAGIAIRE_POSSIBLE
         
         -- SET @NB_HEUR_ENGAGE_N = 20.00
         
         --SELECT ID_STAGIAIRE_PEC,ID_INDIVIDU,ID_SESSION_PEC INTO  #TMP_STAGIAIRE_POSSIBLE FROM STAGIAIRE_PEC WHERE ID_SESSION_PEC IN(
         --SELECT ID_SESSION_PEC FROM SESSION_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC AND BLN_ACTIF=1)
         
         SELECT STAGIAIRE_PEC.ID_STAGIAIRE_PEC,STAGIAIRE_PEC.ID_INDIVIDU,SESSION_PEC.ID_SESSION_PEC
         INTO  #TMP_STAGIAIRE_POSSIBLE 
         FROM STAGIAIRE_PEC
         LEFT JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC 
         LEFT JOIN SESSION_PEC ON SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC 
         WHERE
         STAGIAIRE_PEC.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         
         
         
         	DECLARE CUR_STG_SES_POSSIBLE CURSOR FOR 
         	SELECT ID_STAGIAIRE_PEC,ID_INDIVIDU,ID_SESSION_PEC
         	FROM #TMP_STAGIAIRE_POSSIBLE 
         	OPEN CUR_STG_SES_POSSIBLE
         	FETCH CUR_STG_SES_POSSIBLE INTO @ID_STAGIAIRE, @ID_INDIVIDU	,@ID_SESSION_PEC	
         
         	WHILE @@Fetch_Status = 0
         	BEGIN
         			
         			IF(		
         			(SELECT 
         -- New H Engaged en Module
         			@NB_HEUR_ENGAGE_N - 
         -- H Engaged on other Sessions
         			ISNULL((
         			SELECT	SUM(UNITE_STAGIAIRE.NB_HEURE_REGLE)
         			FROM UNITE_STAGIAIRE 
         			LEFT JOIN	STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC  
         			LEFT JOIN	INDIVIDU ON STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			WHERE		
         						UNITE_STAGIAIRE.BLN_REFUS <> 1								AND				
         						INDIVIDU.ID_INDIVIDU = @ID_INDIVIDU							AND
         						STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC				AND 						
         						(STAGIAIRE_PEC.ID_SESSION_PEC <> @ID_SESSION_PEC)						
         			GROUP BY	STAGIAIRE_PEC.ID_INDIVIDU,  STAGIAIRE_PEC.ID_MODULE_PEC,STAGIAIRE_PEC.ID_STAGIAIRE_PEC			
         			),0)) -
         -- H Engaged in current Session 
         			ISNULL((
         			SELECT	SUM(UNITE_STAGIAIRE.NB_HEURE_REGLE)
         			FROM UNITE_STAGIAIRE 
         			LEFT JOIN	STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC  
         			LEFT JOIN	INDIVIDU ON STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			WHERE		
         						UNITE_STAGIAIRE.BLN_REFUS <> 1								AND				
         						INDIVIDU.ID_INDIVIDU = @ID_INDIVIDU							AND
         						STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC				AND 						
         						(STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)						
         			GROUP BY	STAGIAIRE_PEC.ID_INDIVIDU,  STAGIAIRE_PEC.ID_MODULE_PEC,STAGIAIRE_PEC.ID_STAGIAIRE_PEC			
         			),0) < 0) 
         			BEGIN
         				SET @ID_STAGIAIRE_FOUND = @ID_STAGIAIRE				
         				BREAK
         			END
         
         	FETCH CUR_STG_SES_POSSIBLE INTO @ID_STAGIAIRE, @ID_INDIVIDU,@ID_SESSION_PEC		
         	END
         
         DEALLOCATE CUR_STG_SES_POSSIBLE
         
         SELECT @NOM_PRENOM_STAGIAIRE_FOUND = INDIVIDU.NOM_INDIVIDU + ' ' + PRENOM_INDIVIDU 
         FROM INDIVIDU 
         INNER JOIN STAGIAIRE_PEC on STAGIAIRE_PEC.id_individu=individu.id_individu
         AND stagiaire_pec.id_stagiaire_pec = @ID_STAGIAIRE_FOUND
         
         --			ISNULL((
         --			SELECT	SUM(UNITE_STAGIAIRE.NB_HEURE_ENGAGE)
         --			FROM UNITE_STAGIAIRE 
         --			LEFT JOIN	STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC  
         --			LEFT JOIN	INDIVIDU ON STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         --			WHERE		
         --						UNITE_STAGIAIRE.BLN_REFUS <> 1								AND				
         --						INDIVIDU.ID_INDIVIDU = @ID_INDIVIDU							AND
         --						STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC				AND 
         --						STAGIAIRE_PEC.ID_SESSION_PEC IS NULL --(@ID_SESSION IS NULL OR STAGIAIRE_PEC.ID_SESSION_PEC <> @ID_SESSION)
         --			GROUP BY	STAGIAIRE_PEC.ID_INDIVIDU,  STAGIAIRE_PEC.ID_MODULE_PEC,STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         --			),0) AS NB_HEURE_ENGAGE_ACTUAL,
         
         END
         
GO
