         -- SAFI : Rename LIB_COMPTE_BANQUE for Transit and Activite
         -- 18/01/2011 : 12622 
         -- =============================================
         -- DSZ 03/12/12 : 14425 : renommage agence IDF en NE
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- HBO - 141113 - M16371: Lot 1 - Modification structure de donn‚es / proc‚dures stock‚es
         -- =============================================
         CREATE PROCEDURE LEC_GRP_ORDRE_VIREMENT_REGULARISATION_NEGATIVES
         	@TYPE_ETAT		int,		--Etat = 1 (jamais edit‚)
         	@DATE_DEBUT		datetime,
         	@DATE_FIN		datetime
         with recompile
         AS
         	BEGIN
         		CREATE TABLE #TEMP
         		(
         			ID_VIREMENT_INTERNE_COLLECTE INTEGER,
         			ID_VIREMENT_INTERNE_COLLECTE_IMPAYE INTEGER,
         			ID_ACTIVITE INTEGER,
         			DAT_EDIT_VIREMENT_INTERNE_COLLECTE Datetime,
         			DAT_COMPTA_VIREMENT_INTERNE_COLLECTE Datetime,
         			MNT_VIREMENT_INTERNE_COLLECTE decimal(18,2)
         		)
         
         		IF (@TYPE_ETAT = 1)
         			BEGIN
         				--GESTION DES REGULARISATIONS
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION	ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT		ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT			on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         					--ajout DSZ 04/06/2010
         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       
         					--modif DSZ 04/06/2010
         					-- ((POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 5 OR POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 6)
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 --regul et revers
         					-->-- fin modif DSZ
         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE <= 0 )
         
         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select ID_VIREMENT_INTERNE_COLLECTE from #TEMP)
         				
         				UPDATE #TEMP
         				SET DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         
         				--Gestion des impay‚s
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE*(-1) as MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         				WHERE
         					VERSEMENT.ID_STATUT_VERSEMENT = 7
         					and POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS not NULL
         					and VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0
         
         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select
         																					ID_VIREMENT_INTERNE_COLLECTE_IMPAYE
         																				from
         																					#TEMP
         																				WHERE
         																					ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS NOT NULL)
         			END
         		ELSE
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         					--ajout DSZ 04/06/2010
         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE      
         					 --modif DSZ 04/06/2010
         					-- ((POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 5 OR POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 6)
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 --regul et revers
         					-->-- fin modif DSZ
         					AND (@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)
         					AND	(@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0
         
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         				WHERE
         					VERSEMENT.ID_STATUT_VERSEMENT = 7
         					and POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS not NULL
         					AND (@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)
         					AND	(@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0
         			END
         			
         			SELECT
         				#TEMP.ID_VIREMENT_INTERNE_COLLECTE,
         				CASE WHEN #TEMP.MNT_VIREMENT_INTERNE_COLLECTE < 0 
         					THEN #TEMP.MNT_VIREMENT_INTERNE_COLLECTE * (-1) 
         					ELSE #TEMP.MNT_VIREMENT_INTERNE_COLLECTE 
         				END AS MNT_VIREMENT_INTERNE_COLLECTE,
         				#TEMP.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         				TRANSIT.NUM_IBAN_TRANSIT,
         				TRANSIT.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_TRANSIT,
         				ACTIVITE.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_ACTIVITE,
         				ACTIVITE.NUM_IBAN_ACTIVITE,
         				ACTIVITE.LIB_BANQUE,
         				PARAMETRES.NOM_PNM_SECRETAIRE_GENERAL,
         				PARAMETRES.NOM_PNM_DAF,
         				PARAMETRES.NOM_PNM_DIRECTEUR,
         				PARAMETRES.PIED_PAGE_C2P,			
         				(SELECT RTRIM(
         						CASE 
         							WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) 
         							ELSE LIB_VILLE 
         						END) 
         				FROM AGENCE 
         				WHERE COD_AGENCE = 'NE') AGENCE_LIB_VILLE,
         				PARAMETRES.BANQUE_VIREMENT		
         			FROM
         				#TEMP
         				INNER JOIN ACTIVITE ON  #TEMP.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         				CROSS JOIN PARAMETRES
         				CROSS JOIN TRANSIT
         			WHERE
         				#TEMP.MNT_VIREMENT_INTERNE_COLLECTE <> 0
         			order by
         				ACTIVITE.ID_ACTIVITE,
         				#TEMP.ID_VIREMENT_INTERNE_COLLECTE
         	END
GO

         -- ====================================================================
         -- Author		: GiO
         -- Create date	: 26 Mai 2008
         -- comment		: Update ID_REGLEMENT_PRO a null pour recr‚er un  nouveau reglement apres annulation d'un 
         ----------------------------------------------------------------------
         -- Author		: DCL
         -- Create date	: 23 juin 2009
         -- comment		: ajout param reglement _pro pour distinguer reglement ADH et OF
         --				(si autoriser! ie, dat_valid_reglement is null)
         ----------------------------------------------------------------------
         -- Author		: SAF - ASD
         -- Create date		: 31/01/2001
         -- comment		: gestion du NULL pour l'affectation des variables @ID_REGLEMENT_PRO_OF et @ID_REGLEMENT_PRO_ADH
         --				  where xxx = NULL ne fonctionne jamais : remplac‚ par "is null".
         -- ===================================================================
         CREATE PROCEDURE [dbo].[UPD_ID_REGLEMENT_PRO_DANS_SESSION_PRO]
         	@ID_SESSION_PRO INT,
         	@ID_REGLEMENT_PRO INT
         AS
         BEGIN
         
         --		UPDATE SESSION_PRO 
         --		set ID_REGLEMENT_PRO_ADH=null,
         --			ID_REGLEMENT_PRO_OF=null  
         --		where ID_SESSION_PRO=@ID_SESSION_PRO
         
         
         declare @ID_REGLEMENT_PRO_of int
         declare @ID_REGLEMENT_PRO_adh int
         declare @dat_valid_reglement_OF as datetime
         set @dat_valid_reglement_OF = null
         declare @dat_valid_reglement_ADH as datetime
         set @dat_valid_reglement_ADH = null
         
         select @ID_REGLEMENT_PRO_OF=id_reglement_pro_of, @ID_REGLEMENT_PRO_adh=id_reglement_pro_adh from session_pro 
         where (id_reglement_pro_of = @ID_REGLEMENT_PRO or id_reglement_pro_adh=@ID_REGLEMENT_PRO)
         and id_session_pro=@id_session_pro
         
         select @dat_valid_reglement_OF=dat_valid_reglement from reglement_pro where id_reglement_pro = @ID_REGLEMENT_PRO_OF
         select @dat_valid_reglement_ADH=dat_valid_reglement from reglement_pro where id_reglement_pro = @ID_REGLEMENT_PRO_ADH
         
         	IF @dat_valid_reglement_OF is null and @dat_valid_reglement_adh is null
         	BEGIN
         		if (@ID_REGLEMENT_PRO_adh is not null) 
         			UPDATE SESSION_PRO 
         			set ID_REGLEMENT_PRO_ADH=null  
         			where ID_SESSION_PRO=@ID_SESSION_PRO
         				and id_reglement_pro_adh= @ID_REGLEMENT_PRO_adh
         		
         		if (@ID_REGLEMENT_PRO_of is not null) 
         			UPDATE SESSION_PRO 
         			set ID_REGLEMENT_PRO_OF=null
         			where ID_SESSION_PRO=@ID_SESSION_PRO
         			and id_reglement_pro_of= @ID_REGLEMENT_PRO_of
         	END
         
         
         END
         
GO

         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_RELANCE_INSTRUCTION]
         	@ID_ETABLISSEMENT int,
         	@ID_ACTION_PEC int
         AS
         
         BEGIN
         		-- Recherche des informations sur l'adherent et l'agence
         		SELECT
         				ADHERENT.ID_ADRESSE_PRINCIPALE,
         				ADHERENT.ID_ETABLISSEMENT_PRINCIPAL,
         				ADHERENT.ID_ADHERENT,
         				ADHERENT.COD_ADHERENT,
         				ADHERENT.LIB_RAISON_SOCIALE,
         				
         				AGENCE.ID_AGENCE,
         				AGENCE.LIBL_AGENCE,
         				AGENCE.LIB_NOM_CONSEILLER,
         				AGENCE.LIB_PNM_CONSEILLER,
         				AGENCE.LIB_ADR1,
         				AGENCE.LIB_VILLE,
         				AGENCE.COD_POSTAL,
         				AGENCE.NUM_TEL,
         				AGENCE.NUM_FAX,
         				AGENCE.EMAIL
         		INTO
         				#TMP_GENERAL
         		FROM
         				ADHERENT
         				INNER JOIN AGENCE ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         				INNER JOIN ETABLISSEMENT ON ADHERENT.ID_ETABLISSEMENT_PRINCIPAL = ETABLISSEMENT.ID_ETABLISSEMENT AND 
         						  ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         				ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT;
         
         		--R‚cup‚ration de la liste des modules
         		SELECT  ACTION_PEC.COD_ACTION_PEC,
         				
         				MODULE_PEC.ID_MODULE_PEC,
         				MODULE_PEC.COD_MODULE_PEC, 
         				MODULE_PEC.LIBL_MODULE_PEC, 
         				MODULE_PEC.DAT_DEBUT, 
         				MODULE_PEC.DAT_FIN,
          
                         ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         		INTO
         				#TMP_MODULE
         		FROM         
         				ORGANISME_FORMATION 
         				INNER JOIN ETABLISSEMENT_OF ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF 
         				INNER JOIN MODULE_PEC ON ETABLISSEMENT_OF.ID_OF = MODULE_PEC.ID_ETABLISSEMENT_OF 
         				INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         
         		WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC;
         
         
         	--R‚cup‚ration les infos d'action PEC
         		SELECT  
         				ACTION_PEC.COD_ACTION_PEC
         
         		INTO
         				#TMP_ACTION_PEC
         		FROM      
         				ACTION_PEC 
         
         		WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC;
         
         
         
         
         
         	/*****  Creation du flux XML *********************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_PEC_RELANCE_INSTRUCTION'
         	)
         	/**************************************************************************************************/
         
         	SELECT
         			/***************** Recuperation des informations sur l'agence *****************************/
         			(
         				SELECT
         					AGENCE.LIBL_AGENCE	as AGENCE_NOM,
         					AGENCE.LIB_ADR1		as AGENCE_ADRESSE,
         					AGENCE.COD_POSTAL	as AGENCE_CP,
         					AGENCE.LIB_VILLE	as AGENCE_VILLE,
         					AGENCE.NUM_FAX		as AGENCE_FAX,
         					AGENCE.EMAIL		as AGENCE_EMAIL
         				FROM
         					#TMP_GENERAL as AGENCE
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			/******************************************************************************************/
         
         			/******************* Recuperation des informations sur le destinataire ********************/
         			(
         				SELECT
         						LETTRE.LIB_RAISON_SOCIALE,
         						DESTINATAIRE.LIB_ADR,
         						DESTINATAIRE.LIB_CP_CEDEX,
         						DESTINATAIRE.LIB_VIL_CEDEX
         				FROM
         						ADRESSE as DESTINATAIRE
         				WHERE
         						LETTRE.ID_ADRESSE_PRINCIPALE = DESTINATAIRE.ID_ADRESSE
         				FOR XML AUTO, ELEMENTS, TYPE
         
         			),
         			/******************************************************************************************/
         
         			/******************* Recuperation des informations DE l'entete ****************************/
         			(
         				SELECT
         						LETTRE.COD_ADHERENT as COD_ADHERENT,
         						LETTRE.LIB_VILLE as LIB_VILLE	
         				FROM
         						#TMP_GENERAL AS ENTETE
         				FOR XML AUTO, ELEMENTS, TYPE
         
         			),
         			/******************************************************************************************/
         
         			/******************* Recuperation des informations du corps de la lettre ****************************/
         			(
         				SELECT
         					CORPS.COD_ACTION_PEC as COD_ACTION_PEC,
         					
         					(
         						SELECT
         							MODULE.ID_MODULE_PEC, 
         							MODULE.COD_MODULE_PEC, 
         							MODULE.LIBL_MODULE_PEC,
         							CASE WHEN (DATEDIFF(DAY,MODULE.DAT_FIN,getDate())>= 0) THEN 'r‚alis‚ par' 
         																					ELSE '… r‚alis‚ par '
         							END as REALISATION,
         							MODULE.LIB_RAISON_SOCIALE,
         							MODULE.DAT_DEBUT, 
         							MODULE.DAT_FIN,
         
         							(
         								SELECT     PIECE.COD_PIECE_PEC as NOM_PIECE
         
         								FROM		 
         											PIECE_PEC AS PIECE INNER JOIN ARRIVEE_PIECE_PEC ON PIECE.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         								WHERE		(PIECE.BLN_BLOQUANT_ENGAGEMENT = 1)
         										AND ((BLN_ADHERENT = 1) OR (BLN_MODULE = 1) OR (BLN_STAGIAIRE = 1))
         										AND (ARRIVEE_PIECE_PEC.BLN_ACTIF = 0 ) 
         										AND (ARRIVEE_PIECE_PEC.DAT_ARRIVEE_PIECE_PEC IS NULL)
         										AND (ARRIVEE_PIECE_PEC.ID_ADHERENT = LETTRE.ID_ADHERENT)
         										AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = MODULE.ID_MODULE_PEC)
         								FOR XML AUTO, ELEMENTS, TYPE,ROOT('PIECES_MANQUANTES')
         							),
         							(
         								SELECT      PIECE_PEC.ID_PIECE_PEC as ID_PIECE_PEC,
         									        PIECE_PEC.COD_PIECE_PEC as COD_PIECE_PEC, 
         											MOTIF_NON_CONFORMITE.LIBL_MOTIF_NON_CONFORM_PIECE AS MOTIF
         								FROM		 
         											PIECE_PEC 
         											INNER JOIN ARRIVEE_PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         											INNER JOIN NR210 ON NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         											INNER JOIN MOTIF_NON_CONFORM_PIECE AS MOTIF_NON_CONFORMITE ON NR210.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORMITE.ID_MOTIF_NON_CONFORM_PIECE
         
         								WHERE		(PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1)
         										AND ((BLN_ADHERENT = 1) OR (BLN_MODULE = 1) OR (BLN_STAGIAIRE = 1))
         										AND (ARRIVEE_PIECE_PEC.BLN_ACTIF = 1 ) 
         										AND (ARRIVEE_PIECE_PEC.DAT_ARRIVEE_PIECE_PEC IS NOT NULL)
         										AND (ARRIVEE_PIECE_PEC.ID_ADHERENT = LETTRE.ID_ADHERENT)
         										AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = MODULE.ID_MODULE_PEC)
         								FOR XML AUTO, ELEMENTS, TYPE,ROOT('PIECES_NON_CONFORMES')
         							)
         						FROM
         								#TMP_MODULE AS MODULE
         						FOR XML AUTO, ELEMENTS, TYPE
         					)
         
         				FROM
         						#TMP_ACTION_PEC AS CORPS
         				FOR XML AUTO, ELEMENTS, TYPE
         
         			),
         			/******************************************************************************************/
         
         			/******************* Recuperation des informations de la signature********************/
         			(
         				SELECT
         						SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TMP_GENERAL as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         			/******************************************************************************************/
         
         				
         	FROM	#TMP_GENERAL as LETTRE
         	FOR XML AUTO, ELEMENTS
         END
         
GO
 -- =============================================
         -- Author:		xxx
         -- Create date: xx xxx 2007
         -- Description:	lecture des donn‚es pour les ordres de virements type r‚gularisation
         -- ---------------------------------------------
         -- Author		: Say
         -- Modified date: 24 sept 2007
         -- comment		: # VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE >= 0 afin de prendre en compte un cas de r‚gul adh => adh pr*
         --					la mˆme p‚riode, mˆme activit‚ donnant un montant … nul. Ceci permet de mettre … jour DAT_EDIT_VIREMENT_INTERNE_COLLECTE
         --					pour la comptabilit‚
         -- =============================================
         -- Author		: SAFI
         -- Modified date: 13-03-2009
         -- comment		: Add one new colonne BANQUE_VIRIEMENT FOR THE ADDRESS 
         -- =============================================
         -- DSZ 12391 04/06/2010 
         -- Remplacer condition sur ID_TYPE_VERSEMENT par BLN_VERSEMENT_INITIAL 
         -- =============================================
         -- Author		: SAFI
         -- Modified date: 17/01/2011
         -- comment		: rename the two coloumns LIB_COMPTE_BANQUE (TRANSIT ET ACTIVITE)
         -- =============================================
         -- DSZ 03/12/12 : 14425 : renommage agence IDF en NE
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- HBO - 141113 - M16371: Lot 1 - Modification structure de donn‚es / proc‚dures stock‚es
         -- =============================================
         CREATE PROCEDURE LEC_GRP_ORDRE_VIREMENT_REGULARISATION_POSITIVES
         	@TYPE_ETAT		int,		--Etat = 1 (jamais edit‚)
         	@DATE_DEBUT		datetime,
         	@DATE_FIN		datetime
         with recompile
         AS
         	BEGIN
         		CREATE TABLE #TEMP
         		(
         			ID_VIREMENT_INTERNE_COLLECTE INTEGER,
         			ID_ACTIVITE INTEGER,
         			DAT_EDIT_VIREMENT_INTERNE_COLLECTE Datetime,
         			DAT_COMPTA_VIREMENT_INTERNE_COLLECTE Datetime,
         			MNT_VIREMENT_INTERNE_COLLECTE decimal(18,2)
         		)
         
         		IF (@TYPE_ETAT = 1)
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         					--ajout DSZ 04/06/2010
         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       
         					--modif DSZ 04/06/2010
         					--(POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 5 OR POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 6 OR VERSEMENT.ID_STATUT_VERSEMENT = 7)
         					(TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 OR VERSEMENT.ID_STATUT_VERSEMENT = 7) --regul et revers or impay‚
         					-->-- fin modif DSZ
         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE >= 0)
         					
         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select ID_VIREMENT_INTERNE_COLLECTE from #TEMP)
         				
         				UPDATE #TEMP
         				SET DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         			END
         		ELSE
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         					--ajout DSZ 04/06/2010
         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       
         					--modif DSZ 04/06/2010
         					--(POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 5 OR POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 6 OR VERSEMENT.ID_STATUT_VERSEMENT = 7)
         					(TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 OR VERSEMENT.ID_STATUT_VERSEMENT = 7) --regul et revers or impay‚
         					-->-- fin modif DSZ
         					AND ((@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)) 
         					AND	((@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)) 
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE > 0 )		
         			END
         
         		SELECT
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE,
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE,
         			#TEMP.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         			TRANSIT.NUM_IBAN_TRANSIT,
         			TRANSIT.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_TRANSIT,
         			ACTIVITE.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_ACTIVITE,
         			ACTIVITE.NUM_IBAN_ACTIVITE,
         			ACTIVITE.LIB_BANQUE,
         			PARAMETRES.NOM_PNM_SECRETAIRE_GENERAL,
         			PARAMETRES.NOM_PNM_DAF,
         			PARAMETRES.NOM_PNM_DIRECTEUR,
         			PARAMETRES.PIED_PAGE_C2P,
         			(SELECT RTRIM(
         				CASE 
         					WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) 
         					ELSE LIB_VILLE 
         				END) 
         			FROM AGENCE 
         			WHERE COD_AGENCE = 'NE') AGENCE_LIB_VILLE,
         			PARAMETRES.BANQUE_VIREMENT		
         		FROM
         			#TEMP 
         			INNER JOIN ACTIVITE ON  #TEMP.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         			CROSS JOIN PARAMETRES 
         			CROSS JOIN TRANSIT
         		WHERE
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE > 0
         		order by
         			ACTIVITE.ID_ACTIVITE,
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE
         	END
GO

         
         -- =============================================
         -- Author:		DSZ
         -- Create date: 23/06/09
         -- Description:	Inserer des donnees dans la table MVT-BUDGETAIRE_PERIODE, 
         -- pour reporting pluri-annuel
         ------------------------------------------------
         -- DSZ 30/07/09
         -- modif apres l'email de MHBM date 30/07 
         -- il faut prendre en compte la session, pas le module
         -- remplace @BLN_USE_SESSION par @ID_SESSION, ajout partie 'C'
         ------------------------------------------------
         -- DSZ 06/08/09
         -- si module n'a pas de session repartir la somme sur les dates du module
         ------------------------------------------------
         -- DSZ 10/08/09
         -- ajout control_sum
         ------------------------------------------------
         -- DSZ 18/09/09
         -- apres le point avec MHBM : limiter la date de derniere session aux sessions regles et actives
         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         CREATE PROCEDURE [dbo].[INS_MVT_BUDG_PERIODE] 
         	@ID_MODULE int,
         	@ID_DISPOSITIF int,
         	@ID_BRANCHE int,
         	@ID_ENVELOPPE int,
         	@ID_COMPTE int,
         	@ID_TYPE_FINANCEMENT int,		
         	@TYPE_ENREGISTREMENT varchar(3),
         	@MNT decimal(18,2),
         	--@BLN_USE_SESSION bit, --s'il faut prendre la date de derniere session. utiliser par exemple pour cloture
         	@ID_SESSION int,
         	@DATE datetime = NULL  --s'il y a juste une date, e.g. reglement
         AS
         BEGIN
         	SET NOCOUNT ON;
         
         
         	DECLARE @dat_debut datetime
         	DECLARE @dat_fin datetime
         	DECLARE @jours_total int
         	DECLARE @id_periode int
         	DECLARE @jours_periode int
         
         
         	--ajout DSZ 31/07/09
         	if @TYPE_ENREGISTREMENT in ('C', 'EN') --cloture ou engagement net. 
         	--on met le mnt sure le periode entre la fin de la derniere session REGLE et la fin du module
         	begin
         		select  @dat_debut = CAST( floor(CAST(max(SESSION_PEC.DAT_FIN) AS FLOAT ))AS DATETIME), --only the date part
         				@dat_fin = CAST( floor(CAST(max(MODULE_PEC.dat_fin) AS FLOAT ))AS DATETIME),
         				@jours_total = datediff(d, @dat_debut, @dat_fin)
         		from MODULE_PEC
         			inner join SESSION_PEC on (SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC)
         		--ajout DSZ 18/09/09
         			inner join POSTE_COUT_REGLE on (POSTE_COUT_REGLE.id_SESSION_PEC = SESSION_PEC.id_SESSION_PEC )
         		where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE
         		and SESSION_PEC.BLN_ACTIF = 1
         		--fin ajout DSZ
         	end	
         	--fin ajout DSZ
         	
         	if @DATE is null and @dat_debut is null -- ajout and DSZ 06/08/09
         	begin
         		if @ID_SESSION is null --que le module
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), --only the date part
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from MODULE_PEC
         			where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE
         		else --on prend les dates de la session
         			select  @dat_debut = CAST( floor(CAST(max(SESSION_PEC.DAT_DEBUT) AS FLOAT ))AS DATETIME), --only the date part
         					@dat_fin = CAST( floor(CAST(max(SESSION_PEC.DAT_FIN) AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from SESSION_PEC
         			where ID_SESSION_PEC = @ID_SESSION
         	end
         
         
         
           -------------------------------------------------------------------------------
           --------------------------------   INSERT   -----------------------------------
         
         	IF (datepart(yy,@dat_debut) = datepart(yy,@dat_fin) --seulement un periode
         		OR @DATE is not null) --une date = un periode
         	BEGIN
         		IF @DATE is null
         			select @DATE = @dat_debut
         		select @id_periode = PERIODE.ID_PERIODE
         		from PERIODE
         		where ID_TYPE_PERIODE = 1 and
         		(@DATE >=DAT_DEB_PERIODE and @DATE <= DAT_FIN_PERIODE)
         		
         		if @id_periode is not null
         			INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PEC, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         			VALUES
         			   (GetDate(), 
         				@MNT,
         				@id_periode,
         				@ID_DISPOSITIF,
         				@ID_BRANCHE,
         				@ID_MODULE,
         				@ID_ENVELOPPE, 
         				@ID_COMPTE, 
         				@ID_TYPE_FINANCEMENT,
         				@TYPE_ENREGISTREMENT	)
         			
         	END
         	ELSE      --plus d'un periode
         	BEGIN
         		declare @mnt_calcule decimal (18,2)
         		declare @control_sum decimal (18,2)
         		set @control_sum = 0
         		DECLARE periode_cursor CURSOR FOR
         			select PERIODE.ID_PERIODE,
         			datediff(d,@dat_debut, DAT_FIN_PERIODE) as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_debut >=DAT_DEB_PERIODE) and (@dat_debut <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, @dat_fin)+1 as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_fin>=DAT_DEB_PERIODE) and (@dat_fin <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, DAT_FIN_PERIODE)+1 as jours 
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			(DAT_DEB_PERIODE>@dat_debut and DAT_FIN_PERIODE <@dat_fin)
         
         		OPEN periode_cursor
         		FETCH NEXT FROM periode_cursor
         		INTO @id_periode, @jours_periode
         		WHILE @@FETCH_STATUS = 0
         		BEGIN
         			if @id_periode is not null
         			begin
         				set @mnt_calcule = round(@MNT*(cast(@jours_periode as decimal(18,2))/ cast(@jours_total as decimal(18,2))), 2)
         				set @control_sum = @control_sum + @mnt_calcule
         				INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PEC, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         				VALUES
         				   (GetDate(), 
         					round(@MNT*(cast(@jours_periode as decimal(18,2))/ cast(@jours_total as decimal(18,2))), 2),
         					@id_periode,
         					@ID_DISPOSITIF,
         					@ID_BRANCHE,
         					@ID_MODULE,
         					@ID_ENVELOPPE, 
         					@ID_COMPTE, 
         					@ID_TYPE_FINANCEMENT,
         					@TYPE_ENREGISTREMENT)
         			end
         			FETCH NEXT FROM periode_cursor
         			INTO @id_periode, @jours_periode
         		END
         		CLOSE periode_cursor
         		DEALLOCATE periode_cursor
         
         		select @control_sum = @MNT - @control_sum
         		if (@control_sum <> 0)
         		begin
         			UPDATE MVT_BUDGETAIRE_PERIODE
         			SET MNT_MVT_BUDG_PERIODE = MNT_MVT_BUDG_PERIODE + @control_sum
         			WHERE ID_MVT_BUDG_PERIODE = @@IDENTITY
         		end
         	END
         END
         
GO
-- =============================================
         -- Author:		DSZ
         -- Create date: 14/02/2013
         -- Description:	14921 : batch de Compensation FPSPP Plan Plasturgie Option A, p‚riode 19 = 2012
         -- sera lanc‚ manuellement de temps en temps
         -- =============================================
         -- 20130226 :	14921 ASD : revue vari‚e suite … tests
         -- =============================================
         -- DSZ 08/04/2013 15095 : La r‚gularisation automatique s'effectuera par ‚tablissement verseur de VV.
         -- RAF : Le montant de r‚gul. ne doit pas exc‚der le montant plan des VV mˆme p‚riode moins la somme des montants conventionnels pour cet ‚tab.
         -- =============================================
         -- MBL 17/12/2013 : Inhibition du code de la procedure stockee
         --					Dans un 1er temps, tout appel a cette PS doit etre supprime dans OPTIFORM
         --					Dans un 2eme temps, cette PS sera supprimee 
         -- =============================================
         CREATE PROCEDURE DBO.BATCH_COMPENSATION_FPSPP_PLASTURGIE
         AS
         BEGIN
         	-- MBL 17/12/2013 : Inhibition du code de la procedure stockee
         	RETURN;
         	--drop table #tmp_etab
         	--option Plast A
         	DECLARE
         		@ID_OPTION_PLASTA INT
         	
         	SELECT
         		@ID_OPTION_PLASTA = ID_OPTION
         	FROM
         		OPTIONS
         	WHERE
         		COD_OPTION = 'PLASTA';
         	--print @id_option_plasta
         	--Lorsque les 3 conditions suivantes sont r‚unies :
         	--* le groupe d l'adh‚rent est en option Plast A
         	--* Acomptes Plan VV 2012 (somme des MNT_HT des poste imputation Plan en VV, r‚gul et reversement compris, 
         	--impay‚s et non remis en banque exclus), en excluant les montants d‚j… d‚volus au FPSPP >0
         	--* FPSPP plan restant d– (=FPSPP plan du - d‚j… vers‚) >0
         	--la liste des candidats en Plast A avec leurs montant Acomptes, D‚j… Verse FPSSPP s'il y a un montant Acompte disponible pour la compensation FPSPP
         	WITH LISTE_ETABS
         		AS (
         		SELECT
         			POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE AS ID_ETAB,
         			sum(POSTE_IMPUTATION.MNT_HT) AS ACOMPTESPLANDONTFPSPP,
         			-- Montant Plan Volontaire dont FPSPP 
         			SUM(isnull(POSTE_IMPUTATION.DONT_REGLE_FPSPP, 0))  AS DEJA_REGLE_FPSPP,
         			-- Montant FPSPP total
         			R20.ID_TYPE_ASSUJETISSEMENT,
         			max(VERSEMENT.ID_VERSEMENT) AS ID_VERSEMENT,
         			--le versement le plus recent
         			MAX(POSTE_IMPUTATION.ID_ACTIVITE ) AS ID_ACTIVITE,
         			POSTE_VERSEMENT.ID_PERIODE
         		FROM
         			VERSEMENT
         			INNER JOIN POSTE_VERSEMENT
         				ON POSTE_VERSEMENT.ID_VERSEMENT=VERSEMENT.ID_VERSEMENT
         			INNER JOIN TYPE_VERSEMENT
         				ON POSTE_VERSEMENT.ID_TYPE_VERSEMENT=TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         			INNER JOIN POSTE_IMPUTATION
         				ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT=POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         				AND POSTE_IMPUTATION.ID_ACTIVITE IN(4, 5) --Plan
         			INNER JOIN R20
         				ON R20.ID_PERIODE=19
         				AND R20.ID_ADHERENT=VERSEMENT.ID_ADHERENT_EMETTEUR
         				AND POSTE_VERSEMENT.ID_PERIODE=R20.ID_PERIODE
         			INNER JOIN ETABLISSEMENT
         				ON POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE=ETABLISSEMENT.ID_ETABLISSEMENT
         				AND ETABLISSEMENT.BLN_ACTIF=1
         			INNER JOIN R20BIS
         				ON R20BIS.ID_GROUPE=ETABLISSEMENT.ID_GROUPE
         				AND R20BIS.ID_PERIODE=R20.ID_PERIODE
         				AND R20BIS.ID_OPTION=@ID_OPTION_PLASTA
         			LEFT JOIN BORDEREAU
         				ON VERSEMENT.ID_BORDEREAU=BORDEREAU.ID_BORDEREAU
         		WHERE
         			VERSEMENT.BLN_IMPAYE = 0 -- impay‚s exclus
         			AND
         			(
         				TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 1
         				AND BORDEREAU.ID_LOT_REMISE_BANCAIRE IS NOT NULL --non remis en banque exclus
         				
         				OR --sauf si c'est une r‚gul ou un reversement, pas de remise bancaire et si c'est un reversement, qu'il soit valid‚
         				(
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0
         					AND
         					(
         						TYPE_VERSEMENT.BLN_VERSEMENT=1
         						OR VERSEMENT.DAT_VALID_VERSEMENT IS NOT NULL
         					)
         				)
         			)
         			AND TYPE_VERSEMENT.GRP_TYPE_VERSEMENT = 'V'	--obligatoires exclus
         		GROUP BY
         			POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,
         			R20.ID_TYPE_ASSUJETISSEMENT,
         			POSTE_VERSEMENT.ID_PERIODE
         		)
         		
         		
         		SELECT
         			ETABLISSEMENT.ID_ADHERENT,
         			LISTE_ETABS.ID_ETAB,
         			LISTE_ETABS.ACOMPTESPLANDONTFPSPP,
         			LISTE_ETABS.DEJA_REGLE_FPSPP ,
         			LISTE_ETABS.ID_ACTIVITE,
         			round(MASSE_SALARIALE_REELLE  *isnull(PARAMETRE_GLOBAL.TAU_GLO_APPEL, 0)/100 *isnull(PARAMETRE_APPEL.PRC_APPELE, 0) /100 *isnull(PARAMETRE_APPEL.
         PRC_FPSPP, 0) /100 , 2) AS DU_FPSPP
         		INTO
         			#TMP_ETAB
         		FROM
         			LISTE_ETABS
         			INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT=LISTE_ETABS.ID_ETAB
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT=ADHERENT.ID_ADHERENT
         			INNER JOIN R21_BIS ON
         								  R21_BIS.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         							  AND R21_BIS.ID_PERIODE=LISTE_ETABS.ID_PERIODE
         			INNER JOIN BRANCHE ON ADHERENT.ID_BRANCHE=BRANCHE.ID_BRANCHE
         			INNER JOIN PARAMETRE_GLOBAL ON
         										   PARAMETRE_GLOBAL.ID_ACTIVITE=LISTE_ETABS.ID_ACTIVITE
         									   AND PARAMETRE_GLOBAL.ID_PERIODE=LISTE_ETABS.ID_PERIODE
         									   AND PARAMETRE_GLOBAL.ID_TYPE_ASSUJETISSEMENT=LISTE_ETABS.ID_TYPE_ASSUJETISSEMENT
         									   AND PARAMETRE_GLOBAL.ID_REGIME=BRANCHE.ID_REGIME
         									   AND PARAMETRE_GLOBAL.BLN_ACTIF=1
         			INNER JOIN PARAMETRE_APPEL ON
         										  PARAMETRE_APPEL.ID_PARAM_GLO=PARAMETRE_GLOBAL.ID_PARAM_GLO
         									  AND PARAMETRE_APPEL.ID_TYPE_VERSEMENT=4
         									  AND --VO
         										  PARAMETRE_APPEL.BLN_ACTIF=1
         		WHERE
         			  ACOMPTESPLANDONTFPSPP - DEJA_REGLE_FPSPP > 0.00001 -- Acompte Plan seul (dont FPSPP moins FPSPP)
         		  AND isnull(MASSE_SALARIALE_REELLE, 0) > 0
         	--select * from #tmp_etab
         	DECLARE
         		@ID_ADH INT,
         		@ID_ETAB INT,
         		@ID_ACTIVITE INT,
         		@ACOMPTEDISPO DECIMAL(18, 2),
         		@RESTANT_DU_FPSPP DECIMAL(18, 2),
         		@REGUL_FPSSP DECIMAL(18, 2)
         
         	DECLARE CURS_ADH CURSOR
         		FOR
         			SELECT
         				ID_ADHERENT,
         				ID_ETAB,
         				ACOMPTESPLANDONTFPSPP - DEJA_REGLE_FPSPP,
         				DU_FPSPP - DEJA_REGLE_FPSPP,
         				ID_ACTIVITE
         			FROM #TMP_ETAB
         			WHERE 	--* FPSPP plan restant d– (=FPSPP plan du - d‚j… vers‚) >0
         			ABS(DU_FPSPP - DEJA_REGLE_FPSPP) > 0.00001  -- pourrait ˆtre dans la clause where au dessus 
         	-- mais d‚port‚ ici pour simplifier la logique (formule de calcul du D– ‚crite une seule fois)
         	OPEN CURS_ADH
         	FETCH NEXT FROM CURS_ADH
         	INTO @ID_ADH, @ID_ETAB, @ACOMPTEDISPO, @RESTANT_DU_FPSPP, @ID_ACTIVITE
         	WHILE @@FETCH_STATUS = 0
         		BEGIN
         			-- r‚gul positive 'O'
         			SET @REGUL_FPSSP = DBO.GETMIN (@ACOMPTEDISPO, @RESTANT_DU_FPSPP)
         			EXEC CREER_REGULARISATION_PV_PI
         			@ID_ADHERENT_EMETTEUR = @ID_ADH,
         			@ID_TIERS_EMETTEUR = NULL,
         			@ID_ETABLISSEMENT_EMETTEUR = @ID_ETAB ,
         			@MNT_VERSEMENT = @REGUL_FPSSP,
         			@ID_TYPE_VERSEMENT = 5,
         			@ID_PERIODE = 19,
         			@ID_ACTIVITE = @ID_ACTIVITE,
         			@DONT_FPSPP = @REGUL_FPSSP
         			-- r‚gul n‚gative 'V'			
         			SET @REGUL_FPSSP = -1 * @REGUL_FPSSP -- IMPORTANT
         			EXEC CREER_REGULARISATION_PV_PI
         			@ID_ADHERENT_EMETTEUR = @ID_ADH,
         			@ID_TIERS_EMETTEUR = NULL,
         			@ID_ETABLISSEMENT_EMETTEUR =  @ID_ETAB,
         			@MNT_VERSEMENT = @REGUL_FPSSP,
         			@ID_TYPE_VERSEMENT = 7,
         			@ID_PERIODE = 19,
         			@ID_ACTIVITE = @ID_ACTIVITE,
         			@DONT_FPSPP = 0
         			FETCH NEXT FROM CURS_ADH INTO @ID_ADH, @ID_ETAB, @ACOMPTEDISPO, @RESTANT_DU_FPSPP, @ID_ACTIVITE
         		END
         	CLOSE CURS_ADH
         	DEALLOCATE CURS_ADH
         END
GO

         -- =============================================
         -- Author:		ASD
         -- Create date: 23/06/09
         -- Description:	Inserer des donnees dans la table MVT-BUDGETAIRE_PERIODE, 
         -- pour reporting pluri-annuel du CPRO
         -- =============================================
         -- DSZ 31/07/09
         -- remplacement @BLN_USE_SESSION par @ID_SESSION
         -- refection calcul periodes (pour corriger)
         -- =============================================
         -- DSZ 05/08/09 
         -- ajout 'ENP' pour repartir sur le periode entre fin de derniere session et fin du module
         -- ajout " @dat_debut is null" pour les cas ou pas de session dans le module
         ------------------------------------------------
         -- DSZ 10/08/09
         -- ajout control_sum
         ------------------------------------------------
         -- DSZ 22/09/09
         -- ajout recherche id_enveloppe
         ------------------------------------------------
         -- DSZ 28/10/09
         -- ajout condition if @mnt_calcule <> 0
         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         
         CREATE PROCEDURE [dbo].[INS_MVT_BUDG_PERIODE_PRO] 
         	@ID_MODULE int,
         	@ID_DISPOSITIF int,
         	@ID_BRANCHE int,
         	@ID_ENVELOPPE int,
         	@ID_COMPTE int,
         	@ID_TYPE_FINANCEMENT int,		
         	@TYPE_ENREGISTREMENT varchar(3),
         	@MNT decimal(18,2),
         	--@BLN_USE_SESSION bit, --s'il faut prendre la date de derniere session. utiliser par exemple pour cloture
         	@ID_SESSION int,
         	@DATE datetime = NULL  --s'il y a juste une date, e.g. reglement
         AS
         BEGIN
         	SET NOCOUNT ON;
         
         
         	DECLARE @dat_debut datetime
         	DECLARE @dat_fin datetime
         	DECLARE @jours_total int
         	DECLARE @id_periode int
         	DECLARE @jours_periode int
         
         	--ajout DSZ 31/07/09
         	if @TYPE_ENREGISTREMENT in ('CP', 'ENP') --cloture --ENP vu avec MHBM le 4/08
         	--on met le mnt sur la periode entre la fin de la derniere session et la fin du module
         	begin
         		select  @dat_debut = CAST( floor(CAST(max(SESSION_PRO.DAT_FIN) AS FLOAT ))AS DATETIME), --only the date part
         				@dat_fin = CAST( floor(CAST(max(MODULE_PRO.dat_fin) AS FLOAT ))AS DATETIME),
         				@jours_total = datediff(d, @dat_debut, @dat_fin)
         		from MODULE_PRO
         			inner join SESSION_PRO on (SESSION_PRO.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO)
         		where MODULE_PRO.ID_MODULE_PRo = @ID_MODULE
         	end	
         	--fin ajout DSZ
         
         	
         	if @DATE is null and @dat_debut is null	--ajout 'and' DSZ 05/08/09
         	begin
         		if @ID_SESSION is null
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), --only the date part
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from MODULE_PRO
         			where MODULE_PRO.ID_MODULE_PRO = @ID_MODULE
         		else
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), --only the date part
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from SESSION_PRO
         			where ID_SESSION_PRO = @ID_SESSION
         	end
         
         --		select  @dat_debut = CAST( floor(CAST(max(SESSION_PRO.DAT_FIN) AS FLOAT ))AS DATETIME), --only the date part
         --				@dat_fin = CAST( floor(CAST(max(MODULE_PRO.dat_fin) AS FLOAT ))AS DATETIME),
         --				@jours_total = datediff(d, @dat_debut, @dat_fin)
         --		from MODULE_PRO
         --			inner join SESSION_PRO on (SESSION_PRO.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO)
         --		where MODULE_PRO.ID_MODULE_PRO = @ID_MODULE
         
         
         
           ---------------------------- ID_ ENVELOPPE ------------------------------------
         if (@ID_ENVELOPPE is null and @ID_COMPTE is null)
         begin
         	declare @id_dispo_module int
         	declare @id_periode_module int
         	declare @ID_AGENCE int
         	select 
         		@id_dispo_module = case when ID_TYPE_FORMATION = 3 then 7 --fonction tutorale = dispositif 7
         								else 5 end, 
         		@id_periode_module = MODULE_PRO.ID_PERIODE,
         		@ID_AGENCE = CONTRAT_PRO.ID_AGENCE
         	from MODULE_PRO 
         		inner join CONTRAT_PRO on (CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO)
         	where ID_MODULE_PRO = @ID_MODULE
         	
         	select @ID_ENVELOPPE = id_enveloppe 
         	from enveloppe 
         	inner join type_enveloppe on (type_enveloppe.id_type_enveloppe = enveloppe.id_type_enveloppe)
         	where type_enveloppe.ID_BRANCHE = @ID_BRANCHE
         	and type_enveloppe.ID_DISPOSITIF = @id_dispo_module
         	and type_enveloppe.ID_AGENCE = @ID_AGENCE
         	and enveloppe.id_periode = @id_periode_module
         end
         
         
           -------------------------------------------------------------------------------
           --------------------------------   INSERT   -----------------------------------
         
         	IF (datepart(yy,@dat_debut) = datepart(yy,@dat_fin) --seulement un periode
         		OR @DATE is not null) --une date = un periode
         	BEGIN
         		IF @DATE is null
         			select @DATE = @dat_debut
         		select @id_periode = PERIODE.ID_PERIODE
         		from PERIODE
         		where ID_TYPE_PERIODE = 1 and
         		(@DATE >=DAT_DEB_PERIODE and @DATE <= DAT_FIN_PERIODE)
         		
         		if (@id_periode is not null and @MNT <> 0)
         			INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PRO, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         			VALUES
         			   (GetDate(), 
         				@MNT,
         				@id_periode,
         				@ID_DISPOSITIF,
         				@ID_BRANCHE,
         				@ID_MODULE,
         				@ID_ENVELOPPE, 
         				@ID_COMPTE, 
         				@ID_TYPE_FINANCEMENT,
         				@TYPE_ENREGISTREMENT	)
         			
         	END
         	ELSE      --plus d'une periode
         	BEGIN
         		declare @mnt_calcule decimal (18,2)
         		declare @control_sum decimal (18,2)
         		set @control_sum = 0
         		DECLARE periode_cursor CURSOR FOR
         			select PERIODE.ID_PERIODE,
         			datediff(d,@dat_debut, DAT_FIN_PERIODE) as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_debut >=DAT_DEB_PERIODE) and (@dat_debut <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, @dat_fin)+1 as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_fin>=DAT_DEB_PERIODE) and (@dat_fin <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, DAT_FIN_PERIODE)+1 as jours 
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			(DAT_DEB_PERIODE>@dat_debut and DAT_FIN_PERIODE <@dat_fin)
         
         		OPEN periode_cursor
         		FETCH NEXT FROM periode_cursor
         		INTO @id_periode, @jours_periode
         		WHILE @@FETCH_STATUS = 0
         		BEGIN
         			if @id_periode is not null
         			begin
         				set @mnt_calcule = round(@MNT*(cast(@jours_periode as float)/ cast(@jours_total as float)), 2)
         				set @control_sum = @control_sum + @mnt_calcule
         				if @mnt_calcule <> 0
         				begin
         					INSERT INTO MVT_BUDGETAIRE_PERIODE
         					   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PRO, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         					VALUES
         					   (GetDate(), 
         						@mnt_calcule,
         						@id_periode,
         						@ID_DISPOSITIF,
         						@ID_BRANCHE,
         						@ID_MODULE,
         						@ID_ENVELOPPE, 
         						@ID_COMPTE, 
         						@ID_TYPE_FINANCEMENT,
         						@TYPE_ENREGISTREMENT)
         				end
         			end
         			FETCH NEXT FROM periode_cursor
         			INTO @id_periode, @jours_periode
         		END
         		CLOSE periode_cursor
         		DEALLOCATE periode_cursor
         		
         		select @control_sum = @MNT - @control_sum
         		if (@control_sum <> 0)
         		begin
         			UPDATE MVT_BUDGETAIRE_PERIODE
         			SET MNT_MVT_BUDG_PERIODE = MNT_MVT_BUDG_PERIODE + @control_sum
         			WHERE ID_MVT_BUDG_PERIODE = @@IDENTITY
         		end
         	END
         END
GO
