         CREATE PROCEDURE [dbo].[INS_MOTIF_REFUS_CONTRAT]
         	@ID_CONTRAT_PRO		as int,
         	@ID_MOTIF_REFUS_PRO as int
         AS  
         	IF NOT EXISTS ( SELECT 1 FROM MOTIF_REFUS_CONTRAT WHERE	ID_CONTRAT_PRO		= @ID_CONTRAT_PRO		AND 
         															ID_MOTIF_REFUS_PRO	= @ID_MOTIF_REFUS_PRO)
         	BEGIN	
         		INSERT INTO MOTIF_REFUS_CONTRAT (ID_CONTRAT_PRO, ID_MOTIF_REFUS_PRO) VALUES (@ID_CONTRAT_PRO, @ID_MOTIF_REFUS_PRO)
         	END
