         CREATE PROCEDURE dbo.INS_FONCTION
         	@COD_FONCTION VARCHAR(8),  
         	@LIBC_FONCTION VARCHAR(20),  
         	@LIBL_FONCTION VARCHAR(120),  
         	@BLN_PRIO TINYINT,  
         	@BLN_ACTIF TINYINT,  
         	@NUM_ORDRE INTEGER,
         	@ID_UTILISATEUR INTEGER,
         	@COM_FONCTION VARCHAR(255)  
         AS  
         BEGIN
         	DECLARE
         		@CPT INTEGER,
         		@COD_TABLE CHAR(25)
         
         	INSERT INTO FONCTION
         	(
         		COD_FONCTION,  
         		LIBC_FONCTION,  
         		LIBL_FONCTION,  
         		BLN_PRIO,  
         		BLN_ACTIF,  
         		DAT_MODIF,  
         		NUM_ORDRE,
         		ID_UTILISATEUR ,
         		COM_FONCTION
         	)
         	VALUES  
         	(
         		@COD_FONCTION,  
         		@LIBC_FONCTION,  
         		@LIBL_FONCTION,  
         		@BLN_PRIO,  
         		@BLN_ACTIF,  
         		GETDATE(),  
         		@NUM_ORDRE,
         		@ID_UTILISATEUR ,
         		@COM_FONCTION
         	)
         	
         	SELECT @@IDENTITY AS ID
         END
GO
