         CREATE PROCEDURE UPD_INS_EFFECTIF_MOYEN_SYNCHRO 
         	@ID_ADHERENT int, 
         	@ANNEE int,
         	@NUM_EFFECTIF_MOYEN decimal (12,2)
         AS
         BEGIN
         	DECLARE @id_periode int
         	SELECT @id_periode = id_periode from PERIODE where COD_PERIODE = @ANNEE and ID_TYPE_PERIODE = 1
         	if exists( SELECT 1 from R21 where ID_ADHERENT = @ID_ADHERENT and ID_PERIODE = @id_periode)
         		UPDATE R21 set NUM_EFFECTIF_MOYEN = @NUM_EFFECTIF_MOYEN
         		where ID_ADHERENT = @ID_ADHERENT and ID_PERIODE = @id_periode
         	ELSE
         		insert into R21 (ID_ADHERENT, ID_PERIODE,NUM_EFFECTIF_MOYEN)
         		values (@ID_ADHERENT, @id_periode, @NUM_EFFECTIF_MOYEN)
         		
         END
