         ----------------------------------------------  
         
         CREATE PROCEDURE [dbo].[LEC_GRP_SUISI_ENVELOPPE]
         	@ID_PERIODE 	int,
         	@ID_ENVELOPPE	int,
         	@LIST_ID_TYPE_ENVELOPPES	varchar(1000)
         	
         AS
         BEGIN
         
         	CREATE TABLE #TEMPLIST
         	(
         		ORDER_ID int
         	)
         
         	DECLARE @ORDERID varchar(10), @POS int
         
         	SET @LIST_ID_TYPE_ENVELOPPES = LTRIM(RTRIM(@LIST_ID_TYPE_ENVELOPPES))+ ','
         	SET @POS = CHARINDEX(',', @LIST_ID_TYPE_ENVELOPPES, 1)
         
         	IF REPLACE(@LIST_ID_TYPE_ENVELOPPES, ',', '') <> ''
         	BEGIN
         		WHILE @POS > 0
         		BEGIN
         			SET @ORDERID = LTRIM(RTRIM(LEFT(@LIST_ID_TYPE_ENVELOPPES, @POS - 1)))
         			IF @ORDERID <> ''
         			BEGIN
         				INSERT INTO #TEMPLIST (ORDER_ID) VALUES (CAST(@ORDERID AS int)) --Use Appropriate conversion
         			END
         			SET @LIST_ID_TYPE_ENVELOPPES = RIGHT(@LIST_ID_TYPE_ENVELOPPES, LEN(@LIST_ID_TYPE_ENVELOPPES) - @POS)
         			SET @POS = CHARINDEX(',', @LIST_ID_TYPE_ENVELOPPES, 1)
         
         		END
         	END	
         
         	------------- CALCULATE TOTAL MNT PREVISIONEL, ENGAGE AND REEL --------------
         
         	DECLARE @TOTAL_PREVISIONEL AS decimal(18,2)
         	DECLARE @TOTAL_ENGAGE AS decimal(18,2)
         	DECLARE @TOTAL_REEL AS decimal(18,2)
         
         	SET @TOTAL_PREVISIONEL = 0
         	SET @TOTAL_ENGAGE = 0
         	SET @TOTAL_REEL = 0
         
         	CREATE TABLE #TEMPLIST2
         	(
         		SENS VARCHAR(1),
         		MNT_PREVISIONEL decimal(18,2),
         		MNT_ENGAGE decimal(18,2),
         		MNT_REEL decimal(18,2)
         	)
         
         	INSERT INTO #TEMPLIST2
         	SELECT
         		PARAMETRAGE_BUDGETAIRE.SENS,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'P' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'E' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'R' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END
         	FROM  
         
         		ENVELOPPE 
         		INNER JOIN TYPE_ENVELOPPE ON TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE 
         		INNER JOIN PERIODE ON PERIODE.ID_PERIODE = ENVELOPPE.ID_PERIODE 
         		INNER JOIN PARAMETRAGE_BUDGETAIRE ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		INNER JOIN MVT_BUDGETAIRE ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
         			AND MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         	
         	WHERE
         			((RTRIM(@ID_PERIODE) IS NULL) OR ( PERIODE.ID_PERIODE = @ID_PERIODE))  
         		AND  ((RTRIM(@ID_ENVELOPPE) IS NULL) OR (ENVELOPPE.ID_ENVELOPPE  = @ID_ENVELOPPE))  			
         		AND  ((RTRIM(@LIST_ID_TYPE_ENVELOPPES) IS NULL) OR (TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  IN (SELECT ORDER_ID FROM #TEMPLIST)))
         
         
         	DECLARE @CURRENT_PREVISIONEL AS decimal(18,2)
         	DECLARE @CURRENT_ENGAGE AS decimal(18,2)
         	DECLARE @CURRENT_REEL AS decimal(18,2)
         	DECLARE @CURRENT_SENS AS VARCHAR
         
         	DECLARE CURSOR_MONTANT CURSOR FOR
         		SELECT 
         			SENS,
         			MNT_PREVISIONEL,
         			MNT_ENGAGE,
         			MNT_REEL
         		FROM 
         			#TEMPLIST2
         	OPEN CURSOR_MONTANT
         
         	FETCH NEXT FROM CURSOR_MONTANT 
         	INTO @CURRENT_SENS, @CURRENT_PREVISIONEL, @CURRENT_ENGAGE, @CURRENT_REEL
         
         	WHILE @@FETCH_STATUS = 0
         	BEGIN
         
         		IF @CURRENT_SENS = 'D'
         			BEGIN
         				SET @TOTAL_PREVISIONEL = @TOTAL_PREVISIONEL - @CURRENT_PREVISIONEL
         				SET @TOTAL_ENGAGE = @TOTAL_ENGAGE - @CURRENT_ENGAGE
         				SET @TOTAL_REEL = @TOTAL_REEL - @CURRENT_REEL
         			END
         		ELSE
         			BEGIN
         				SET @TOTAL_PREVISIONEL = @TOTAL_PREVISIONEL + @CURRENT_PREVISIONEL
         				SET @TOTAL_ENGAGE = @TOTAL_ENGAGE + @CURRENT_ENGAGE
         				SET @TOTAL_REEL = @TOTAL_REEL + @CURRENT_REEL
         			END
         
         	FETCH NEXT FROM CURSOR_MONTANT 
         	INTO @CURRENT_SENS, @CURRENT_PREVISIONEL, @CURRENT_ENGAGE, @CURRENT_REEL
         
         	END
         	CLOSE CURSOR_MONTANT
         	DEALLOCATE CURSOR_MONTANT
         	
         	--------------------------- SELECT RESULT -----------------------
         
         	SELECT
          
         		TYPE_ENVELOPPE.LIBL_TYPE_ENVELOPPE, 
         		ENVELOPPE.LIBL_ENVELOPPE, 
         		PERIODE.NUM_ANNEE, 
         		'' AS MOUVEMENT, 
         		ENVELOPPE.BLN_ACTIF, 
         		MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,
         		MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE,
         		PARAMETRAGE_BUDGETAIRE.SENS, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'P' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_PREVISIONNEL, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'E' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_ENGAGE, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'R' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_REEL,
         		CAST(@TOTAL_PREVISIONEL AS DECIMAL(10,2)) AS TOTAL_PREVISIONEL,
         		CAST(@TOTAL_ENGAGE AS DECIMAL(10,2)) AS TOTAL_ENGAGE,
         		CAST(@TOTAL_REEL AS DECIMAL(10,2)) AS TOTAL_REEL
         		
         	FROM  
         
         		ENVELOPPE 
         		INNER JOIN TYPE_ENVELOPPE ON TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE 
         		INNER JOIN PERIODE ON PERIODE.ID_PERIODE = ENVELOPPE.ID_PERIODE 
         		INNER JOIN PARAMETRAGE_BUDGETAIRE ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		INNER JOIN MVT_BUDGETAIRE ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
         			AND MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
         	
         	WHERE
         			((RTRIM(@ID_PERIODE) IS NULL) OR ( PERIODE.ID_PERIODE = @ID_PERIODE))  
         		AND  ((RTRIM(@ID_ENVELOPPE) IS NULL) OR (ENVELOPPE.ID_ENVELOPPE  = @ID_ENVELOPPE))  			
         		AND  ((RTRIM(@LIST_ID_TYPE_ENVELOPPES) IS NULL) OR (TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  IN (SELECT ORDER_ID FROM #TEMPLIST)))
         
         END
GO
 -- =============================================
         -- Author		: Kwame woollams
         -- Create date	: 20 apr 2007
         -- Description	: Lecture groupe Reglement PRO
         -- =============================================
         -- Author		: KS
         -- Modif. date	: 02nd apr 2008
         -- Description	: ajout de la gestion des des editions virements PEC en complement de @GENERATION_ONLY		is null
         --					qui ne semble pas etre utilise autrement
         -- =============================================
         -- Author		: DCL
         -- Modif. date	: 04th dec 2008
         -- Description	: ajout NUM_IBAN
         -- =============================================
         CREATE PROCEDURE LEC_GRP_REGLEMENT_PRO
         	@GENERATION_ONLY	TINYINT = NULL,
         	@MODE_CRITERE		SMALLINT = NULL
         AS
         BEGIN
         	-- Donnees temporaires pour @MODE_CRITERE is not null ------------------------------------------------------------------------------
         	SELECT
         		ID_ETABLISSEMENT_OF,
         		count(*) AS NB_SESSION_PRO
         	INTO
         		#TMP_SESSION_PRO
         	FROM
         		SESSION_PRO
         		INNER JOIN MODULE_PRO ON MODULE_PRO.ID_MODULE_PRO=SESSION_PRO.ID_MODULE_PRO
         	WHERE
         		MODULE_PRO.ID_ETABLISSEMENT_OF IS NOT NULL
         		AND MODULE_PRO.BLN_ACTIF = 1
         		AND SESSION_PRO.BLN_ACTIF = 1
         		AND @MODE_CRITERE IS NOT NULL
         	GROUP BY
         		ID_ETABLISSEMENT_OF
         
         	SELECT
         		SESSION_PRO.ID_REGLEMENT_PRO_ADH AS ID_REGLEMENT_PRO,
         		CASE
         			WHEN count(*) > 0 THEN 1
         			ELSE 0
         		END AS IBAN_MODIFIE
         	INTO
         		#TMP_SESSION_PRO_VALID_6
         	FROM
         		SESSION_PRO
         		INNER JOIN ETAT_PRO ON SESSION_PRO.ID_ETAT_PRO=ETAT_PRO.ID_ETAT_PRO
         	WHERE
         		SESSION_PRO.ID_ETAT_PRO = 8
         		AND @MODE_CRITERE IS NOT NULL
         		AND ETAT_PRO.COD_ETAT_PRO = 'CHGIBAN'
         	GROUP BY
         		SESSION_PRO.ID_REGLEMENT_PRO_ADH
         
         	UNION ALL
         
         	SELECT
         		SESSION_PRO.ID_REGLEMENT_PRO_OF  AS ID_REGLEMENT_PRO,
         		CASE
         			WHEN	count(*) > 0 THEN 1
         			ELSE 0
         		END AS IBAN_MODIFIE
         	FROM
         		SESSION_PRO
         		INNER JOIN ETAT_PRO ON SESSION_PRO.ID_ETAT_PRO=ETAT_PRO.ID_ETAT_PRO
         	WHERE
         		SESSION_PRO.ID_ETAT_PRO = 8
         		AND @MODE_CRITERE IS NOT NULL
         		AND ETAT_PRO.COD_ETAT_PRO = 'CHGIBAN'
         	GROUP BY
         		SESSION_PRO.ID_REGLEMENT_PRO_OF
         	
         	-- ajout DCL 3/12/2008
         	DECLARE
         		@NB_REGL INT
         	SET @NB_REGL =
         		(
         		SELECT
         			count(RP.ID_REGLEMENT_PRO)
         		FROM
         			REGLEMENT_PRO RP
         			INNER JOIN [TRANSACTION] T ON T.ID_TRANSACTION	= RP.ID_TRANSACTION
         		WHERE
         			(
         				@GENERATION_ONLY = 1
         				AND DAT_GENERATION_SEPA IS NOT NULL
         				OR
         				(
         					@GENERATION_ONLY = 0
         					AND DAT_GENERATION_SEPA IS NULL
         					AND RP.BLN_ACTIF = 1
         					AND DAT_VALID_REGLEMENT IS NOT NULL
         				)
         				OR
         				(
         					@GENERATION_ONLY IS NULL
         				)
         			)
         			AND MNT_REGLE_TTC <> 0
         			AND
         			(
         				@MODE_CRITERE IS  NULL
         				OR
         				(
         					@MODE_CRITERE IS NOT NULL
         					AND RP.BLN_ACTIF		= 1
         					AND RP.BLN_EN_COURS	= 1
         					AND RP.DAT_VALID_REGLEMENT IS NULL
         					AND RP.DAT_EDITION IS NULL
         				)
         			)
         		)
         
         	-- Donnees generales ----------------------------------------------------------------------------------------------------------------
         	SELECT
         		RP.*,
         		-- ajout DCL 3/12/2008
         		T.NUM_IBAN	AS	NUM_IBAN,
         		@NB_REGL	AS	NB_REGL,
         		AGENCE.LIBC_AGENCE,
         		AGENCE.LIBL_AGENCE,
         		coalesce(T.ID_ETABLISSEMENT_BENEF, T.ID_ETABLISSEMENT_OF_BENEF, T.ID_TIERS_BENEF) AS ID_BENEF,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_BENEF		IS NOT NULL	THEN A.LIB_RAISON_SOCIALE
         			WHEN	T.ID_ETABLISSEMENT_OF_BENEF		IS NOT NULL	THEN O.LIB_RAISON_SOCIALE
         			WHEN	T.ID_TIERS_BENEF				IS NOT NULL	THEN TI.LIB_NOM
         			ELSE												'erreur'
         		END	AS                                                                               LIB_BENEF,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_BENEF		IS NOT NULL	THEN 'Adherent'
         			WHEN	T.ID_ETABLISSEMENT_OF_BENEF		IS NOT NULL	THEN 'Etablissement'
         			WHEN	T.ID_TIERS_BENEF				IS NOT NULL	THEN 'Tiers'
         			ELSE																	 'erreur'
         		END AS	LIB_TYPE_BENEFICIAIRE,
         		isnull((
         				SELECT
         					count(*)
         				FROM
         					SESSION_PRO
         				WHERE
         					 SESSION_PRO.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO
         					 OR SESSION_PRO.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO
         				),0) AS	NOMBRE_DOSSIERS,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_DEST		IS NOT NULL	THEN A2.ID_ADHERENT
         			WHEN	T.ID_ETABLISSEMENT_OF_DEST	IS NOT NULL	THEN O2.ID_OF
         			ELSE	NULL
         		END	AS	ID_DEST,
         		coalesce(1*T.ID_ETABLISSEMENT_DEST/T.ID_ETABLISSEMENT_DEST,2*T.ID_ETABLISSEMENT_OF_DEST/T.ID_ETABLISSEMENT_OF_DEST)	AS	ID_TYPE_DEST,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_OF_DEST IS NOT NULL AND (O.DAT_CREATION > dateadd(MM, -3, getdate()) OR NB_SESSION_PRO < 10) THEN 1
         			ELSE 0
         		END	AS	NOUVEAUX_OF,
         		isnull(P6.IBAN_MODIFIE, 0)	AS	IBAN_MODIFIE
         	FROM
         		REGLEMENT_PRO	RP
         		LEFT JOIN AGENCE						ON	AGENCE.ID_AGENCE=RP.ID_AGENCE
         													AND @MODE_CRITERE IS NOT NULL
         		INNER JOIN [TRANSACTION] T				ON	T.ID_TRANSACTION=RP.ID_TRANSACTION
         		INNER JOIN SOUS_TYPE_TRANSACTION		ON	T.ID_SOUS_TYPE_TRANSACTION=SOUS_TYPE_TRANSACTION.ID_SOUS_TYPE_TRANSACTION
         													AND SOUS_TYPE_TRANSACTION.COD_SOUS_TYPE_TRANSACTION='REGLEMT'
         		LEFT JOIN ADHERENT A					ON	A.ID_ETABLISSEMENT_PRINCIPAL=T.ID_ETABLISSEMENT_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ORGANISME_FORMATION O			ON	O.ID_ETABLISSEMENT_OF_PRINCIPAL=T.ID_ETABLISSEMENT_OF_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN TIERS TI						ON	TI.ID_TIERS=T.ID_TIERS_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ADHERENT A2					ON	A2.ID_ETABLISSEMENT_PRINCIPAL=T.ID_ETABLISSEMENT_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ORGANISME_FORMATION O2		ON	O2.ID_ETABLISSEMENT_OF_PRINCIPAL=T.ID_ETABLISSEMENT_OF_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN #TMP_SESSION_PRO P			ON	P.ID_ETABLISSEMENT_OF=T.ID_ETABLISSEMENT_OF_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN #TMP_SESSION_PRO_VALID_6 P6	ON	P6.ID_REGLEMENT_PRO=RP.ID_REGLEMENT_PRO
         													AND @MODE_CRITERE IS NOT NULL
         	WHERE
         	(
         		@GENERATION_ONLY		= 1
         		AND DAT_GENERATION_SEPA					IS NOT NULL
         		OR
         		(
         			@GENERATION_ONLY	= 0
         			AND DAT_GENERATION_SEPA					IS NULL
         			AND RP.BLN_ACTIF = 1
         			AND DAT_VALID_REGLEMENT						IS NOT NULL
         		)
         		OR
         		(
         			@GENERATION_ONLY IS NULL
         		)
         	)
         	AND MNT_REGLE_TTC	<> 0
         	AND
         	(
         		@MODE_CRITERE IS  NULL
         		OR
         		(
         			@MODE_CRITERE IS NOT NULL
         			AND RP.BLN_ACTIF = 1
         			AND RP.BLN_EN_COURS	= 1
         			AND RP.DAT_VALID_REGLEMENT IS NULL
         			AND RP.DAT_EDITION IS NULL
         		)
         	)
         END
GO

         
         CREATE PROCEDURE [dbo].[LEC_GRP_ETAB_DOSSIES_FACTURABLES] 
         /*
         -- =============================================
         -- Author:		DSZ
         -- Create date: 13/08/2010
         -- Description:	Liste des beneficiaires potentiels pour Dossiers Facturables
         -- Bas‚ sur C2P_SFD_PEC_EDITION_DOSSIERS_FACTURABLES_1.2.doc
         -- =============================================
         -- DSZ 10/09/10
         -- traitement de BLN_DELEGATION _PAIEMENT 
         -- (on ne prend pas en compte mnt engage ent sous-type_cout = CP si delegation paiement)
         -- =============================================
         -- DSZ 14/09/10 12482
         -- ne prendre pas en compte actions clotur‚s
         -- prendre que les modules imputables
         -- =============================================
         -- DSZ 21/09/2010 dans le cadre de 12498
         -- ajout critere sur ID_ANTENNE : 
         -- mise en conformit‚ avec la C2P_SFD_PEC_EDITION_DOSSIERS_FACTURABLES_1.3.doc
         -- =============================================
         -- DSZ/ASD 22/09/2010 12507 : refection totale du calcul MNT_ENGAGE MNT_REEL
         -- Sinon les calculs ne prenait pas bien en compte les actions collectives
         -- =============================================
         -- ASD 30/09/2010 12495 : exclusion compl‚mentaire des modules > mnt_min
         -- lorsque < montant_D avec date fin module - duree_C > aujourd'hui
         -- ajout du champ DATE_FIN dans les tables temporaires
         -- =============================================
         -- ASD 20/03/2012 renommage des paramŠtres … l'identique de [EDT_LETTRE_PEC_DOSSIERS_FACTURABLES]
         --                et revue du code 
         --				  et ajout de la gestion des STC exclus. et donc de #FINAL
         -- 					plus correction d'une jointure sur PCR et MODULE au lieu de PCR et SESSION 
         --					plus suppression d'une jointure inutile
         -- =============================================
         -- DSZ 26/03/2012 13335 ajout jointure sur stc au calcul de #FINAl, sinon tous les stc sont melang‚s … tort
         -- suppresion des individus des #tmp_modules … la fin, sinon multiplication des lignes … tort, et falsification des montants
         -- refection de calcul de #FINAL : correction de la condition sur param_duree_D
         -- =============================================
         -- Author:		MBL
         -- Modif. date: 21/10/2015
         -- Description:	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         -- =============================================
         */
         	@ID_CHARGERELATION INT,
         	@ID_ANTENNE INT,
         	@ID_ADHERENT INT,
         	@ID_ETABLISSEMENT INT,
         	@BLN_REPRISE_ADHOC tinyint
         AS
         BEGIN
         	-- choix etablissements
         	create table  #tmp_etab (id_etablissement int)
         	
         	-- Rajout MBL du 21/10/2015 :	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         	DECLARE @NUM_ANNEE_EN_COURS int
         	SELECT @NUM_ANNEE_EN_COURS  = NUM_ANNEE
         	FROM PERIODE
         	WHERE ID_TYPE_PERIODE = 1
         	AND BLN_EN_COURS = 1
         	
         
         	IF (@ID_ETABLISSEMENT is not null)
         		--Si ce critŠre est int‚gralement renseign‚, l'‚tablissement s‚lectionn‚ 
         		--sera le seul destinataire potentiel de cette ‚dition (ETABLISSEMENT.ID_ETABLISSEMENT), 
         	BEGIN
         		insert into #tmp_etab (id_etablissement) values (@ID_ETABLISSEMENT)
         	END
         	ELSE
         	IF @ID_ADHERENT is not null
         	--	Si le critŠre ne comporte que la s‚lection de l'adh‚rent, les destinataires de l'‚dition 
         	-- seront tous les ‚tablissements actifs de l'adh‚rent s‚lectionn‚ (ETABLISSEMENT.ID_ADHERENT), 
         	BEGIN
         		insert into #tmp_etab (id_etablissement)
         		SELECT ID_ETABLISSEMENT 
         		FROM ETABLISSEMENT
         		where ID_ADHERENT = @ID_ADHERENT
         		and BLN_ACTIF = 1
         	END 
         	ELSE 
         	IF @ID_CHARGERELATION is not null
         	BEGIN
         	--	Sinon, les ‚tablissements destinataires potentiels sont tous ceux, actifs, 
         	--	dont le charg‚ de relation est l'AGF choisi au premier critŠre 
         		insert into #tmp_etab (id_etablissement)
         		select ID_ETABLISSEMENT
         		from ETABLISSEMENT
         		where ETABLISSEMENT.ID_CHARGEE_RELATION = @ID_CHARGERELATION
         	END
         	ELSE 
         	IF @ID_ANTENNE is not null
         	BEGIN
         		insert into #tmp_etab (id_etablissement)
         		select ID_ETABLISSEMENT
         		from ETABLISSEMENT
         		inner join UTILISATEUR on (UTILISATEUR.ID_UTILISATEUR = ETABLISSEMENT.ID_CHARGEE_RELATION)
         		where UTILISATEUR.id_agence = @ID_ANTENNE
         	END
         
         --select * from #tmp_etab
         
         	------- modules de ces etablissements, uniquement engag‚s. non repris d' adhoc
         	SELECT  
         		MODULE_PEC.ID_MODULE_PEC,
         		STAGIAIRE_PEC.ID_ETABLISSEMENT,
         		STAGIAIRE_PEC.ID_INDIVIDU,
         		MNT_PLAN_FINANCEMENT_US AS MNT_ENGAGE,
         		MODULE_PEC.DAT_FIN,
         		POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT,
         		MODULE_PEC.BLN_DELEGATION_PAIEMENT
         	into #TEMPLISTENGAGE_1ereEtape	
         		FROM MODULE_PEC
         		INNER JOIN ACTION_PEC			ON (ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC)and
         										ACTION_PEC.BLN_ACTIF = 1 and
         										ACTION_PEC.DAT_CLOTURE IS NULL
         		INNER JOIN STAGIAIRE_PEC		ON (STAGIAIRE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC)
         -- 20120313 ajout ASD pour conformit‚ avec
         										AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL 
         		INNER JOIN #tmp_etab			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = #tmp_etab.id_etablissement
         		inner join UNITE_STAGIAIRE		on (UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC)
         		INNER JOIN POSTE_COUT_ENGAGE	ON (MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC)
         										AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT	is NULL	
         										AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL 
         										AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT > 0 
         		INNER JOIN 	PLAN_FINANCEMENT_US	ON(PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE	 = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE					
         										and PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         										and PLAN_FINANCEMENT_US.BLN_ACTIF = 1)
         		INNER JOIN ENGAGEMENT			ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT 	AND 
         										ID_TYPE_ENGAGEMENT	is not null AND 
         										ENGAGEMENT.ID_TYPE_ENGAGEMENT	<> 2 and
         										ENGAGEMENT.DAT_BAE is not null
         										
         		-- Rajout MBL du 21/10/2015 :	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         		INNER JOIN PERIODE				ON	PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         										AND	PERIODE.NUM_ANNEE >= @NUM_ANNEE_EN_COURS - 2
         
         	where
         		MODULE_PEC.BLN_ACTIF = 1  AND 
         		MODULE_PEC.BLN_IMPUTABLE = 1  and
         		(@BLN_REPRISE_ADHOC = 1 OR isnull(ACTION_PEC.BLN_REPRISE_ADHOC,0) = 0)
         --select * from #TEMPLISTENGAGE_1ereEtape
         
         	------- montant engage du PCE (sum PFUS du PCE)
         	select 	ID_MODULE_PEC,
         			ISNULL(sum(MNT_ENGAGE),0) as MNT_ENGAGE,
         		ID_SOUS_TYPE_COUT
         	into 	#TEMPLISTENGAGE
         	from 	#TEMPLISTENGAGE_1ereEtape
         	group by id_module_pec, id_sous_type_cout
         
         
         	------- information unique module/‚tab/individu/date s‚lectionn‚s
         	select distinct ID_MODULE_PEC,
         		ID_ETABLISSEMENT,
         		ID_INDIVIDU,
         		DAT_FIN, id_sous_type_cout,
         		BLN_DELEGATION_PAIEMENT
         	into #tmp_modules
         	from #TEMPLISTENGAGE_1ereEtape
         	--select * from #TEMPLISTENGAGE_1ereEtape
         	--select * from #TEMPLISTENGAGE
         
         	------- montant reel/r‚alis‚ PFUS pour chaque module-etab-stagiaire
         	Select 
         		#tmp_modules.ID_MODULE_PEC AS ID_MODULE_PEC, 
         		PFUS.MNT_PLAN_FINANCEMENT_US as MNT_REGLE, 
         		#tmp_modules.id_sous_type_cout
         	INTO #TEMPLISTREEL__1ereEtape
         	FROM #tmp_modules 
         		Inner join SESSION_PEC 
         			on SESSION_PEC.ID_MODULE_PEC=#tmp_modules.ID_MODULE_PEC 
         			AND SESSION_PEC.BLN_ACTIF=1 
         		INNER JOIN STAGIAIRE_PEC -- de l'‚tablissement
         			ON STAGIAIRE_PEC.ID_SESSION_PEC=SESSION_PEC.ID_SESSION_PEC 
         			AND STAGIAIRE_PEC.ID_ETABLISSEMENT = #tmp_modules.ID_ETABLISSEMENT 
         			AND STAGIAIRE_PEC.ID_INDIVIDU = #tmp_modules.ID_INDIVIDU 
         		INNER JOIN UNITE_STAGIAIRE 
         			ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC 
         		-- 20120320 INNER au lieu de LEFT( oblig‚ vu jointure sur PFUS)
         		INNER JOIN POSTE_COUT_REGLE 
         			ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 
         			-- OLD 20120320 AND POSTE_COUT_REGLE.ID_MODULE_PEC = #tmp_modules.ID_MODULE_PEC -- moins de d‚multiplication
         			AND POSTE_COUT_REGLE.BLN_ACTIF=1 
         			AND POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT=#tmp_modules.id_sous_type_cout
         		INNER JOIN PLAN_FINANCEMENT_US as PFUS 
         			ON PFUS.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
         			AND PFUS.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE 
         			AND PFUS.BLN_ACTIF=1 
         					--inutile 20120320
         	--	inner join MODULE_PEC ON (MODULE_PEC.ID_MODULE_PEC=#tmp_modules.ID_MODULE_PEC)
         		-- LEFT JOIN REGLEMENT 
         		--	ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT 
         		--	AND (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL) 
         		--	AND REGLEMENT.BLN_ACTIF=1 
         
         	------- sum(montant reel/r‚alis‚ PFUS) pour chaque module-etab-stagiaire
         	select
         		ID_MODULE_PEC,
         		isnull(sum(MNT_REGLE),0) as MNT_REEL,
         		 id_sous_type_cout
         	into #TEMPLISTREEL
         	from #TEMPLISTREEL__1ereEtape
         	GROUP BY 
         		#TEMPLISTREEL__1ereEtape.ID_MODULE_PEC, id_sous_type_cout
         
         
         	-- finalement la liste des etablissements
         	-- Le montant restant … facturer par dossier (par module) est sup‚rieur … un plancher 
         	-- fix‚ par param‚trage (PARAM_EDITION_PEC.MNT_MIN).
         	DECLARE @ID_DOCUMENT int	
         	SELECT @ID_DOCUMENT = ID_DOCUMENT
         	FROM [DOCUMENT]
         	WHERE COD_DOCUMENT = 'LET_PEC_DOSFACT'
         
         
         	-----------R‚cup‚ration des params dans PARAM_EDITION_PEC
         	--ASD 20120313 renommage des paramŠtres … l'identique de [EDT_LETTRE_PEC_DOSSIERS_FACTURABLES]
         	declare @PARAM_DUREE_C int            --ex : @DUREE_C
         	declare @PARAM_MNT_D decimal(18,2)    --ex : @MONTANT_D
         	declare @PARAM_MNT_MIN decimal (18,2) --ex : @MNT_MIN
         	declare @CHAINE as varchar(50)
         	declare @SEP as varchar (2)
         	set @SEP = ','
         	
         	select 
         			@PARAM_DUREE_C	= DUREE_C,
         			@PARAM_MNT_D	= MONTANT_D,
         			@PARAM_MNT_MIN	= MNT_MIN,
         			@CHAINE			= STC_EXCLUS --des sous types de co–ts … exclure dans PARAM_EDITION_PEC
         	from dbo.PARAM_EDITION_PEC
         	where ID_DOCUMENT = @ID_DOCUMENT
         	
         	SELECT cast(data as integer) as data into #LIST_STC_A_EXCLURE from F_SPLIT( @CHAINE, @SEP)
         
         
         
         
         
         	SELECT      
         		#tmp_mods_sans_individus.ID_ETABLISSEMENT
         	into #FINAL
         	from (select distinct ID_MODULE_PEC, ID_ETABLISSEMENT, DAT_FIN, id_sous_type_cout, BLN_DELEGATION_PAIEMENT 
         						from #tmp_modules) #tmp_mods_sans_individus --on se debarasse des individus, sinon lignes multiples … tort
         		LEFT JOIN #TEMPLISTENGAGE	ON (#TEMPLISTENGAGE.ID_MODULE_PEC		= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         	 									#TEMPLISTENGAGE.ID_SOUS_TYPE_COUT	= #tmp_mods_sans_individus.id_sous_type_cout)
         		LEFT JOIN #TEMPLISTREEL		ON (#TEMPLISTREEL.ID_MODULE_PEC			= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         										#TEMPLISTREEL.ID_SOUS_TYPE_COUT		= #tmp_mods_sans_individus.id_sous_type_cout)
         
         		where 
         		(#tmp_mods_sans_individus.BLN_DELEGATION_PAIEMENT=0  
         		or #tmp_mods_sans_individus.ID_SOUS_TYPE_COUT not in (select * from #LIST_STC_A_EXCLURE)
         		)
         		and
         		(ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_MIN)
         		AND 
         		(#tmp_mods_sans_individus.DAT_FIN < getdate() + @PARAM_DUREE_C 
         		OR	
         		  ( ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_D)		)
         
         -- Rajout MBL du 21/10/2015 :	Seuls les modules des p‚riodes N, N-1 et N-2 sont pris en compte 
         -- DEBUG : Liste des modules a prendre en compte dans l'edition
         	--SELECT  DISTINCT  COD_MODULE_PEC, NUM_ANNEE, ID_ETABLISSEMENT, #tmp_mods_sans_individus.DAT_FIN, 
         	--MNT_ENGAGE = ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0),
         	--MNT_REGLE = ISNULL(#TEMPLISTREEL.MNT_REEL,0)
         	--from (select distinct ID_MODULE_PEC, ID_ETABLISSEMENT, DAT_FIN, id_sous_type_cout, BLN_DELEGATION_PAIEMENT 
         	--					from #tmp_modules) #tmp_mods_sans_individus --on se debarasse des individus, sinon lignes multiples … tort
         	--	LEFT JOIN #TEMPLISTENGAGE	ON (#TEMPLISTENGAGE.ID_MODULE_PEC		= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         	-- 									#TEMPLISTENGAGE.ID_SOUS_TYPE_COUT	= #tmp_mods_sans_individus.id_sous_type_cout)
         	--	LEFT JOIN #TEMPLISTREEL		ON (#TEMPLISTREEL.ID_MODULE_PEC			= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         	--									#TEMPLISTREEL.ID_SOUS_TYPE_COUT		= #tmp_mods_sans_individus.id_sous_type_cout)
         
         	--	INNER JOIN MODULE_PEC		ON MODULE_PEC.ID_MODULE_PEC = #tmp_mods_sans_individus.ID_MODULE_PEC
         	--	INNER JOIN PERIODE			ON	PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         	--	where 
         	--	(#tmp_mods_sans_individus.BLN_DELEGATION_PAIEMENT=0  
         	--	or #tmp_mods_sans_individus.ID_SOUS_TYPE_COUT not in (select * from #LIST_STC_A_EXCLURE)
         	--	)
         	--	and
         	--	(ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_MIN)
         	--	AND 
         	--	(#tmp_mods_sans_individus.DAT_FIN < getdate() + @PARAM_DUREE_C 
         	--	OR	
         	--	  ( ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_D)		)
         	--ORDER BY NUM_ANNEE, COD_MODULE_PEC
         
         		
         	
         			
         		---- comparaison des montants au niveau du module et pas de chacun des sous types de cout
         		select distinct ETABLISSEMENT.ID_ETABLISSEMENT,
         		ETABLISSEMENT.ID_BRANCHE, -- SBR le 05/03/13
         		ETABLISSEMENT.ID_ADHERENT,
         		ETABLISSEMENT.ID_AGENCE,
         		ETABLISSEMENT.ID_CHARGEE_RELATION,
         		ETABLISSEMENT.ID_ADRESSE_PRINCIPALE,
         		NR31.ID_CONTACT,
         		COD_ADHERENT,
         		ETABLISSEMENT.ID_ETABLISSEMENT as ID_BENEFICIAIRE
         		from ETABLISSEMENT
         		inner join #FINAL on (#FINAL.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT)
         		inner join adherent on (ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT)
         		left join dbo.NR31 on (ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT
         								and NR31.BLN_ACTIF = 1 and NR31.BLN_PRINCIPAL = 1)
         		order by ETABLISSEMENT.ID_BRANCHE -- SBR le 05/03/13
         		
         	
         END
         
GO
 -- =============================================
         -- Author		: Say
         -- Create date	: 27 nov. 2007
         -- Description	: insertion d'une liaisons contrat pro - motif de rejet
         -- ---------------------------------------------
         -- Author		: XXX
         -- Modified date: XX XXX 2007
         -- comment		: 
         -- =============================================
         CREATE PROCEDURE [dbo].[INS_MOTIF_REJET_CONTRAT]
         	@ID_CONTRAT_PRO		as int,
         	@ID_MOTIF_REJET_PRO as int
         AS  
         	IF NOT EXISTS ( SELECT 1 FROM MOTIF_REJET_CONTRAT WHERE	ID_CONTRAT_PRO		= @ID_CONTRAT_PRO		AND 
         															ID_MOTIF_REJET_PRO	= @ID_MOTIF_REJET_PRO)
         	BEGIN	
         		INSERT INTO MOTIF_REJET_CONTRAT (ID_CONTRAT_PRO, ID_MOTIF_REJET_PRO) VALUES (@ID_CONTRAT_PRO, @ID_MOTIF_REJET_PRO)
         	END
         
GO
-- =============================================
         -- Author		: GiO
         -- Create date	: 18 MArs 2008
         -- Description	: Cr‚ation des lettres pour contrat pro de remboursement de salaires Adh‚rent
         -- =============================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_CONTRAT_PRO_REMB_SAL_ADH]
         @ID_ETABLISSEMENT	INT,
         	@ID_BENEFICIAIRE	INT,
         	@TYPE_BENEFICIAIRE	INT,
         	@ID_ADRESSE			INT,
         	@ID_CONTACT			INT,
         	@_ID_MODULE_PRO INT,
         	@_COD_CONTRAT_PRO	VARCHAR(10)
         
         AS
         BEGIN
         
         	DECLARE @RELANCE INT
         	SET @RELANCE = 0
         	
         
         	/**** R‚cup‚ration des infos pour la partie r‚f‚rence ****/
         	SELECT	ADHERENT.ID_ADHERENT,
         			ADHERENT.ID_TYPE_TVA,
         			ADHERENT.COD_ADHERENT,
         			AGENCE.ID_AGENCE,
         			AGENCE.COD_POSTAL,
         			AGENCE.LIB_VILLE,
         			AGENCE.LIB_NOM_CONSEILLER,
         			AGENCE.LIB_PNM_CONSEILLER,
         			ADHERENT.LIB_RAISON_SOCIALE
         	INTO	#TEMP_REGLEMENT_REFERENCE
         	FROM	ADHERENT
         			INNER JOIN AGENCE			ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         			INNER JOIN ETABLISSEMENT	ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	WHERE	(ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT);
         
         	/**** R‚cup‚ration des infos sur le contrat pro ****/
         	SELECT	CONTRAT_PRO.ID_CONTRAT_PRO,
         			CONTRAT_PRO.COD_CONTRAT_PRO,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_DEB_CONTRAT, 3) AS DAT_DEBUT,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_FIN_CONTRAT, 3) AS DAT_FIN,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU,
         			Case when INDIVIDU.BLN_MASCULIN=1 then 'Monsieur' else 'Madame' end as Title ,
         			CONTRAT_PRO.LIB_LIEU_FORMATION
         	INTO	#TMP_CONTRAT_PRO
         	FROM	CONTRAT_PRO
         			INNER JOIN SALARIE_PRO ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         			INNER JOIN INDIVIDU ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         	WHERE   CONTRAT_PRO.COD_CONTRAT_PRO = @_COD_CONTRAT_PRO;
         
         		/**** R‚cup‚ration des infos sur le le module pro pour les ETABLISSEMENT OF ****/
         		SELECT ORGANISME_FORMATION.LIB_RAISON_SOCIALE, ROUND(MODULE_PRO.TAUX_HORAIRE_MODULE,2) as TAUX_HORAIRE_MODULE , TYPE_FORMATION.LIBL_TYPE_FORMATION
         		INTO #TEMP_MODULE_ORGANISME_OF FROM ORGANISME_FORMATION
         		INNER JOIN ETABLISSEMENT_OF  ON ETABLISSEMENT_OF.ID_OF=ORGANISME_FORMATION.ID_OF
         		INNER join MODULE_PRO on MODULE_PRO.ID_ETABLISSEMENT_OF=ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         		INNER join TYPE_FORMATION on MODULE_PRO.ID_TYPE_FORMATION=TYPE_FORMATION.ID_TYPE_FORMATION
         		where MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO;
         	
         	
         /*********** R‚cuperation du TAU_TVA*********************************************************************/
         SELECT TAU_TVA
         INTO #TVA from R26
         inner join #TEMP_REGLEMENT_REFERENCE on #TEMP_REGLEMENT_REFERENCE.ID_TYPE_TVA = R26.ID_TYPE_TVA
         inner join PERIODE on PERIODE.ID_PERIODE=R26.ID_PERIODE and PERIODE.ID_TYPE_PERIODE=2 and (DATEDIFF(DAY,PERIODE.DAT_DEB_PERIODE,GETDATE()) >0)
         order by PERIODE.DAT_DEB_PERIODE desc
         
         
         /*****  nieme relance *****************************************************************************/
         	IF( (SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE1_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE1_EFF IS NULL)) >0)
         			BEGIN
         				SET @RELANCE = 1
         			END
         		ELSE
         			IF ((SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE2_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE2_EFF IS NULL)) >0)
         					BEGIN
         						SET @RELANCE = 2
         					END
         			
         		ELSE
         			BEGIN
         				IF ((SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE3_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE3_EFF IS NULL)) >0)
         					BEGIN
         						SET @RELANCE = 3
         					END
         			END;
         
         /*****  Creation du flux XML *****************************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_PRO_REMBOURSEMENT_SALAIRES_ADH'
         	)
         	/**********************************************************************************************************/
         			
         	SELECT
         
         			CASE WHEN (@RELANCE > 0) THEN 
         			(
         
         			SELECT
         				(
         					SELECT CASE WHEN @RELANCE=0 THEN null ELSE @RELANCE END
         					FOR XML RAW('NUM_RELANCE'), ELEMENTS, TYPE
         				),
         				( 
         					SELECT  CASE WHEN @RELANCE=0 THEN ''  WHEN @RELANCE=1 THEN 'Šre' ELSE 'Šme' END
         					FOR XML RAW('niŠme'), ELEMENTS, TYPE
         				),
         				( 
         					SELECT  CASE WHEN  @RELANCE=0 THEN '' ELSE ' RELANCE' END
         					FOR XML RAW('RELANCE'), ELEMENTS, TYPE
         				)
         				FOR XML RAW('TOP') ,ELEMENTS,TYPE
         
         			)end,
         
         			(
         				/**********************************************************************************************/
         				/*****************	ENTETE DE LA LETTRE *******************************************************/
         				/**********************************************************************************************/
         				SELECT	              	
         					-- R‚cup‚ration des informations sur l'agence
         					dbo.GetXmlAgenceContact(ENTETE.ID_AGENCE) as EMETTEUR,
         					
         					-- R‚cup‚ration des informations sur le contact
         					dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,
         
         					/******************* Recuperation des informations DE l'entete ****************************/
         					(
         						SELECT	REFERENCE.LIB_VILLE,
         								dbo.GetFullDate(getDate()) as DATE
         
         						FROM #TEMP_REGLEMENT_REFERENCE AS REFERENCE     
         						FOR XML AUTO, ELEMENTS, TYPE
         					)
         				FROM #TEMP_REGLEMENT_REFERENCE AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			(
         				/**********************************************************************************************/
         				/*****************	CORPS DE LA LETTRE ********************************************************/
         				/**********************************************************************************************/
         				SELECT	
         						DEMANDE.COD_ADHERENT,
         						DEMANDE.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE_ADHERENT,
         						(
         							SELECT 
         									CORPS.ID_CONTRAT_PRO,
         									CORPS.DAT_DEBUT,
         									CORPS.DAT_FIN,
         									CORPS.Title,
         									CORPS.PRENOM_INDIVIDU,
         									CORPS.NOM_INDIVIDU
         							FROM #TMP_CONTRAT_PRO  AS CORPS 
         							FOR XML PATH(''), ELEMENTS, TYPE
         						),	
         						(
         				
         						SELECT	
         								ORGANISME.LIB_RAISON_SOCIALE,
         								ORGANISME.LIBL_TYPE_FORMATION
         						FROM #TEMP_MODULE_ORGANISME_OF as ORGANISME
         						FOR XML PATH(''), ELEMENTS, TYPE
         						)
         				FROM  #TEMP_REGLEMENT_REFERENCE AS DEMANDE
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			
         			
         			(
         			select
         												
         			(
         				SELECT	top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         				FROM CIVILITE
         				FOR XML PATH('POLITESSE_HAUT'), TYPE
         			),
         						CAST(CORPS.TAUX_HORAIRE_MODULE AS decimal(10,2)) as TAUX_HORAIRE_MODULE,
         			(
         				SELECT 	top 1 CAST((TAU_TVA * 100) AS decimal(10,2)) as TAU_TVA from #TVA
         					FOR XML PATH(''), ELEMENTS, TYPE
         			),
         
         			(
         				SELECT	top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 0)
         				FROM CIVILITE
         				FOR XML PATH('POLITESSE_BAS'), TYPE
         			)
         				FROM #TEMP_MODULE_ORGANISME_OF as CORPS
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         
         			(
         				/**********************************************************************************************/
         				/*****************	SIGNATURE DE LA LETTRE ****************************************************/
         				/**********************************************************************************************/
         				SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TEMP_REGLEMENT_REFERENCE as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)
         			/**************************************************************************************************/
         
         			
         	FROM	#TEMP_REGLEMENT_REFERENCE as LETTRE
         	FOR XML AUTO, ELEMENTS
         
         END
GO
 CREATE PROCEDURE [dbo].[INS_NR34]
         (
         		@ID_CONTACT INT, 
         		@ID_FONCTION INT,  
         		@NUM_TEL VARCHAR(10), 
         		@NUM_PORT VARCHAR(10), 
         		@NUM_FAX VARCHAR(10), 
         		@BLN_PRINCIPAL TINYINT, 
         		@BLN_ACTIF TINYINT, 
         		@EMAIL_PRO VARCHAR(100), 
         		@ID_ADRESSE INT, 
         		@ID_ETABLISSEMENT_OF INT, 
         		@LIB_TITRE VARCHAR(100), 
         		@EMAIL_PERS VARCHAR(100)
         )
         AS
         BEGIN
         	INSERT INTO [dbo].[NR34] 
         	(
         		[ID_CONTACT], 
         		[ID_FONCTION], 
         		[NUM_TEL], 
         		[NUM_PORT], 
         		[NUM_FAX], 
         		[BLN_PRINCIPAL], 
         		[BLN_ACTIF], 
         		[EMAIL_PRO], 
         		[ID_ADRESSE], 
         		[ID_ETABLISSEMENT_OF], 
         		[LIB_TITRE], 
         		[EMAIL_PERS]
         	) 
         	VALUES 
         	(
         		@ID_CONTACT, 
         		@ID_FONCTION, 
         		@NUM_TEL, 
         		@NUM_PORT, 
         		@NUM_FAX, 
         		@BLN_PRINCIPAL, 
         		@BLN_ACTIF, 
         		@EMAIL_PRO, 
         		@ID_ADRESSE, 
         		@ID_ETABLISSEMENT_OF, 
         		@LIB_TITRE, 
         		@EMAIL_PERS
         	)
         
         	IF (EXISTS (
         				select [TRANSACTION].ID_ADRESSE, [TRANSACTION].ID_CONTACT, [TRANSACTION].ID_ADRESSE
         				from [TRANSACTION]
         				where 
         					[TRANSACTION].ID_ETABLISSEMENT_OF_DEST	=  @ID_ETABLISSEMENT_OF	AND
         					[TRANSACTION].ID_CONTACT				=  @ID_CONTACT			AND
         					[TRANSACTION].ID_ADRESSE				<> @ID_ADRESSE
         				) )
         	BEGIN
         		UPDATE [TRANSACTION] set [TRANSACTION].ID_ADRESSE = @ID_ADRESSE
         		where 
         			[TRANSACTION].ID_ETABLISSEMENT_OF_DEST	=  @ID_ETABLISSEMENT_OF	AND
         			[TRANSACTION].ID_CONTACT				=  @ID_CONTACT
         		print 'transaction ok'
         	END
         END
GO
