         CREATE PROCEDURE EDT_ORDRES_VIREMENT
         	@ID_ETABLISSEMENT		int,
         	@ID_BENEFICIAIRE		int,
         	@TYPE_BENEFICIAIRE		int,
         	@ID_ADRESSE				int,
         	@ID_CONTACT				int,
         	@TYPE_DESTINATAIRE		int,
         	@ID_TRANSACTION			int,
         	@ID_REGLEMENT			int
         AS
         	BEGIN
         		DECLARE
         			@MODE_EDITION tinyint,
         			@COD_ADHERENT_OF AS VARCHAR(8),
         			@ID_OF AS INT,
         			@ID_ADHERENT AS INT,
         			@LIB_RAISON_SOCIALE_ADHERENT AS VARCHAR(50),
         			@LIB_RAISON_SOCIALE_OF AS VARCHAR(64),
         			@ID_UTIL AS INT,
         			@LIB_VILLE AS VARCHAR(50),
         			@ID_ETAB_OF AS INT,
         			@ID_ETAB AS INT,
         			@TOT AS MONEY,
         			-- r‚cup‚ration nø iban & bic
         			@num_iban varchar(34),
         			@bic varchar(11)
         	
         		select
         			@num_iban = num_iban,
         			@bic = BIC  
         		from
         			[transaction]
         		where
         			id_transaction = @ID_TRANSACTION
         
         		SET @MODE_EDITION = 1
         		SET @ID_ETAB = NULL
         		SET @ID_ETAB_OF = NULL
         
         		/* Mise en place des variables en fonction du destinataire */
         		IF (@TYPE_DESTINATAIRE = 1)
         		BEGIN
         			select
         				@ID_ADHERENT					= adherent.id_adherent,
         				@COD_ADHERENT_OF				= adherent.cod_adherent,
         				@LIB_RAISON_SOCIALE_ADHERENT	= adherent.lib_raison_sociale
         			from
         				etablissement
         			join
         				adherent
         			on	etablissement.id_adherent = adherent.id_adherent
         			where
         				etablissement.id_etablissement = @ID_ETABLISSEMENT
         		END
         
         		IF (@TYPE_DESTINATAIRE = 2)
         			BEGIN
         				select
         					@ID_OF							= organisme_formation.id_of,
         					@COD_ADHERENT_OF				= organisme_formation.cod_of,
         					@LIB_RAISON_SOCIALE_OF			= organisme_formation.lib_raison_sociale
         				from
         					etablissement_of
         					join organisme_formation on	etablissement_of.id_of = organisme_formation.id_of
         				where
         					etablissement_of.id_etablissement_of = @ID_ETABLISSEMENT
         			END
         
         		/* Informations sur le module P.E.C. */
         		SELECT DISTINCT
         			MODULE_PEC.LIBL_MODULE_PEC,
         			MODULE_PEC.ID_MODULE_PEC
         		INTO
         			[#ORGANISME_FORMATION]
         		FROM
         			POSTE_COUT_REGLE
         			JOIN REGLEMENT	ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         			JOIN MODULE_PEC	ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1;
         		
         		/* Information sur le plan de financement du stagiaire */
         		SELECT
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US)		AS MNT_REGLE_HT,
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US_TVA)	AS MNT_REGLE_TVA,
         	--		SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US) * POSTE_COUT_REGLE.TAU_TVA AS MNT_REGLE_TVA,
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE, 
         			STAGIAIRE_PEC.ID_ETABLISSEMENT 
         		INTO
         			[#PLAN_FINANCEMENT_US_OF]
         		FROM
         			PLAN_FINANCEMENT_US
         			JOIN UNITE_STAGIAIRE	ON	PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         			JOIN STAGIAIRE_PEC		ON	UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         			JOIN POSTE_COUT_REGLE	ON	PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         			JOIN REGLEMENT			ON	REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         		GROUP BY
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT--,
         		--	POSTE_COUT_REGLE.TAU_TVA
         
         		/* Information sur les modules P.E.C. */
         		SELECT DISTINCT 
         			MODULE_PEC.ID_MODULE_PEC,
         			MODULE_PEC.COD_MODULE_PEC,	
         			MODULE_PEC.LIBL_MODULE_PEC,
         			ADHERENT.ID_ADHERENT,
         			ADHERENT.COD_ADHERENT,
         			ADHERENT.LIB_RAISON_SOCIALE
         		INTO
         			#MODULE_PEC
         		FROM 
         			REGLEMENT
         			JOIN POSTE_COUT_REGLE ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN MODULE_PEC ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN NR140 ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN ETABLISSEMENT ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			JOIN ADHERENT ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         	
         		CREATE TABLE #TMP_GENERAL
         		(
         			LIB_NOM_CONSEILLER varchar(35), 
         			LIB_PNM_CONSEILLER varchar(35), 
         			ID_UTILISATEUR int, 
         			LIB_PRENOM_CHARGE_RELATION varchar(35), 
         			LIB_NOM_CHARGE_RELATION varchar(35), 
         			LIB_VILLE varchar(50), 
         			EMAIL_CHARGE_RELATION varchar(100), 
         			NUM_VIREMENT int
         		)
         
         		/* Information sur l'adresse emetteur */
         		IF (@TYPE_DESTINATAIRE = 1)
         			INSERT INTO #TMP_GENERAL
         			SELECT	DISTINCT
         				CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         				CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         				CR.ID_UTILISATEUR,
         				CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         				CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         				CR.LIB_VILLE,
         				CR.EMAIL			as EMAIL_CHARGE_RELATION,
         				REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         				JOIN POSTE_COUT_REGLE	ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         				JOIN MODULE_PEC			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         				JOIN NR140				ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         				JOIN ETABLISSEMENT		ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT AND	ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT -- 10/11/11 par SBR: gestion du cas des actions co multi ‚tablissements
         				JOIN ADHERENT			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         				JOIN ACTION_PEC			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         				LEFT JOIN utilisateur CR ON	ETABLISSEMENT.id_chargee_relation = CR.id_utilisateur	-- 10/11/11 par SBR: on ne filtre que sur le CR de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         				LEFT JOIN utilisateur CM ON	ETABLISSEMENT.id_chargee_mission = CM.id_utilisateur	-- 10/11/11 par SBR: on ne filtre que sur le CM de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         				AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         				AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         
         		IF (@TYPE_DESTINATAIRE = 2)
         			INSERT INTO #TMP_GENERAL
         			SELECT	TOP 1
         				CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         				CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         				CR.ID_UTILISATEUR,
         				CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         				CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         				CR.LIB_VILLE,
         				CR.EMAIL			as EMAIL_CHARGE_RELATION,
         				REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         				JOIN POSTE_COUT_REGLE ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         				JOIN MODULE_PEC ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         				JOIN NR140 ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         				JOIN ETABLISSEMENT ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         				JOIN ADHERENT ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         				JOIN ACTION_PEC ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         				LEFT JOIN utilisateur CR -- charg‚ de relation
         			ON	ETABLISSEMENT.id_chargee_relation = CR.id_utilisateur	-- 10/11/11 par SBR: on ne filtre que sur le CR de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			LEFT JOIN
         				utilisateur CM -- charg‚ de mission
         			ON	ETABLISSEMENT.id_chargee_mission = CM.id_utilisateur	-- 10/11/11 par SBR: on ne filtre que sur le CM de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         
         
         		CREATE TABLE #POSTE_COUT_REGLE_ADH_OF
         		(
         			ID_POSTE_COUT_REGLE int,
         			LIB_RAISON_SOCIALE varchar(100), 
         			DAT_DEBUT datetime,
         			MNT_REGLE_HT decimal(18,2),
         			LIBC_TYPE_FACTURE varchar(50),
         			NUM_FACTURE varchar(50), 
         			DAT_FIN datetime,
         			MNT_REGLE_TVA decimal(18,2),
         			COD_SESSION_PEC varchar(17),
         			ID_MODULE_PEC int, 
         			ID_OF int, 
         			MNT_REGLE_TTC decimal(18,2),
         			MNT_POSTE_COUT_REGLE_TTC decimal(18,2)
         		)
         
         		/* D‚finition du total en fonction du type de b‚n‚ficiaire */
         		IF (@TYPE_DESTINATAIRE = 2) -- OF
         		BEGIN
         			/* Information du r‚gl‚ de chaque P.C.R. par adh‚rent */
         			insert into #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					ADHERENT.LIB_RAISON_SOCIALE as LIB_RAISON_SOCIALE, 
         					SESSION_PEC.DAT_DEBUT as DAT_DEBUT,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN as DAT_FIN,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					STAGIAIRE_PEC.ID_ETABLISSEMENT AS ID_OF, 
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA   AS MNT_REGLE_TTC,
         					/*POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC*/
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_POSTE_COUT_REGLE_TTC
         				FROM
         					REGLEMENT 
         						INNER JOIN POSTE_COUT_REGLE			ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         						INNER JOIN SESSION_PEC				ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         						INNER JOIN MODULE_PEC				ON SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN STAGIAIRE_PEC			ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         						INNER JOIN ETABLISSEMENT			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         						INNER JOIN ADHERENT					ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         						INNER JOIN #PLAN_FINANCEMENT_US_OF	ON #PLAN_FINANCEMENT_US_OF.ID_POSTE_COUT_REGLE=POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE AND #PLAN_FINANCEMENT_US_OF.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         						INNER JOIN TYPE_FACTURE				ON POSTE_COUT_REGLE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         			   WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END
         
         		IF (@TYPE_DESTINATAIRE = 1) --ADH
         		BEGIN
         			/* Information du r‚gl‚ de chaque P.C.R. par O.F. */
         			insert into #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					convert(varchar,ORGANISME_FORMATION.COD_OF) + ' ' + ORGANISME_FORMATION.LIB_RAISON_SOCIALE as LIB_RAISON_SOCIALE,
         					SESSION_PEC.DAT_DEBUT as DAT_DEBUT,
         					POSTE_COUT_REGLE.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN as DAT_FIN,
         					POSTE_COUT_REGLE.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					null,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC	AS MNT_REGLE_TTC,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC
         				FROM 
         					POSTE_COUT_REGLE
         						INNER JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         						INNER JOIN MODULE_PEC				ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN SESSION_PEC				ON SESSION_PEC.ID_SESSION_PEC = POSTE_COUT_REGLE.ID_SESSION_PEC
         						INNER JOIN NR140 ON MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         						INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         						INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         						LEFT OUTER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         						LEFT OUTER JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         						INNER JOIN TYPE_FACTURE				ON TYPE_FACTURE.ID_TYPE_FACTURE = POSTE_COUT_REGLE.ID_TYPE_FACTURE
         				WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END
         	
         		--SELECT @TOT=SUM(MNT_POSTE_COUT_REGLE_TTC) FROM  #POSTE_COUT_REGLE_ADH_OF;
         		SELECT @TOT=SUM(round(MNT_REGLE_TVA, 2) + MNT_REGLE_HT) FROM  #POSTE_COUT_REGLE_ADH_OF;
         
         		-- XML Generation
         		WITH XMLNAMESPACES (
         			DEFAULT 'ORDRE_VIREMENT'
         		)
         		SELECT
         
         				-- Recuperation des informations sur le contact
         				dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
         
         				(
         					SELECT
         						CASE
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'VOTRE CODE ORGANISME : '
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'VOTRE CODE ADHRENT : '
         						END	AS VOTRE_CODE,
         						CAST(@COD_ADHERENT_OF AS VARCHAR) AS COD_ADHERENT_OF,
         						LIB_PRENOM_CHARGE_RELATION,
         						LIB_NOM_CHARGE_RELATION,
         						EMAIL_CHARGE_RELATION AS EMAIL,
         
         						-- R‚cup‚ration des informations sur l'‚metteur
         						dbo.GetXmlAdrUtilAvecTel(ID_UTILISATEUR, 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         															(SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE)
         														ELSE
         															(SELECT MAX(CAST(dbo.DossierEstTSA(COD_MODULE_PEC, 1) AS INT)) FROM #MODULE_PEC)
         													END
         												), 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 1
         														ELSE 0
         													END
         												)) AS EMETTEUR,
         
         						cast(NUM_VIREMENT as varchar) as NUM_VIREMENT,
         						rtrim(case when patindex('%CEDEX%', LIB_VILLE) <> 0 then left(LIB_VILLE, patindex('%CEDEX%', LIB_VILLE)-1) else LIB_VILLE end) as LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         						dbo.GetFullDate(getdate()) as DATE,
         						dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_HAUT
         					FROM
         						#TMP_GENERAL
         					FOR XML RAW('REFERENCE_LETTRE'), ELEMENTS, TYPE
         				),
         
         				-- Zone titre
         				(
         					SELECT
         						MIN(dbo.GetFullDate(DAT_REGLEMENT)) AS DAT_REGLEMENT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) AS MONEY)) AS MNT_REGLE_TTC,
         						@num_iban AS IBAN,
         						@bic AS BIC,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_HT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) - SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_TVA,
         						CASE 
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'correspondant … (aux) l''action(s) de formation que vous avez r‚alis‚e(s).'			
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'correspondant aux frais de salaires, annexes et divers li‚s aux actions de formation d‚crites ci-dessous.'			
         						END AS CORPS_TEXTE_VARIABLE
         
         					FROM REGLEMENT
         					JOIN POSTE_COUT_REGLE 
         					ON	 POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         					WHERE
         						REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         						AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         						AND REGLEMENT.BLN_ACTIF = 1
         						AND REGLEMENT.BLN_EN_COURS	= 1
         						AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         					FOR XML RAW('TITRE'), ELEMENTS, TYPE
         				),
         
         				'Intitul‚ du module' AS LIB_TITRE_TABLEAU,
         
         				CASE
         					WHEN (@TYPE_DESTINATAIRE = 2) THEN 'Adh‚rent'
         					WHEN (@TYPE_DESTINATAIRE = 1) THEN 'Organisme Formation'
         				END	AS LIB_TITRE_TABLEAU_LIGNE_2,
         
         
         				-- Zone tableau
         				CASE 
         				WHEN (@TYPE_DESTINATAIRE = 2) THEN
         				(
         					SELECT
         						LIBL_MODULE_PEC,
         						(
         							SELECT
         								coalesce(LIB_RAISON_SOCIALE,' ') as LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) as DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) as DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	RUPTURE_OF.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         							AND		MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM 
         						#ORGANISME_FORMATION RUPTURE_OF
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				-- Cas d un document ADH
         				WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         				(
         					SELECT
         						convert(varchar,COD_MODULE_PEC) + ' ' + LIBL_MODULE_PEC as LIBL_MODULE_PEC,
         						(
         							SELECT
         								coalesce(LIB_RAISON_SOCIALE,' ') as LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) as DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) as DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_MOD.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM
         						#MODULE_PEC RUPTURE_MOD
         					WHERE
         						RUPTURE_MOD.ID_ADHERENT = @ID_ADHERENT
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				END,
         
         				(
         				SELECT dbo.GetFrenchCurrencyFormat(CAST(@TOT AS MONEY)) AS MONTANT_TOTAL 
         				FOR XML RAW ('TABLEAU_TOTAL'), ELEMENTS, TYPE
         				),
         
         				(
         				SELECT dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_BAS
         				FOR XML RAW ('POLITESSE_BAS'), ELEMENTS, TYPE
         				)
         
         		FOR XML RAW('REGLEMENT'), ELEMENTS
         	-------------------------------------------------------------------------------------------- END
         	END
GO

         
         
         -- =====================================================================================
         -- Author:	KW	
         -- Create date: 27 novembre 2007
         -- Description:	Verifie si des sessions pro bapees appartenant a une session bap pro
         -- r‚ceptionnee n'ont pas de reglement ou si des reglements en cours n'ont pas ‚t‚ ‚dit‚s
         -- ---------------------------------------------
         -- Author		: RMA 
         -- Modified date: 05/12/2008
         -- comment		: # Evol.1 210 
         --				  [DAT_BAP] => [DAT_BAP_OF - DAT_BAP_ADH]
         --				  [ID_SESSION_BAP_PRO] => [ID_SESSION_BAP_PRO_OF - ID_SESSION_BAP_PRO_ADH]
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_SESSION_PRO_HORS_REGLEMENT]
         AS
         BEGIN
         
         	DECLARE @NB_SESSION_PRO	AS INT
         
         	SET @NB_SESSION_PRO =
         	(
         		SELECT
         				COUNT(ID_SESSION_PRO)
         		FROM
         				SESSION_PRO
         				INNER JOIN SESSION_BAP_PRO ON (
         							(SESSION_PRO.ID_SESSION_BAP_PRO_OF = SESSION_BAP_PRO.ID_SESSION_BAP_PRO AND SESSION_PRO.DAT_BAP_OF IS NOT NULL) 
         							OR (SESSION_PRO.ID_SESSION_BAP_PRO_ADH = SESSION_BAP_PRO.ID_SESSION_BAP_PRO AND SESSION_PRO.DAT_BAP_ADH IS NOT NULL))
         		WHERE	--Evol.1 210 --	 SESSION_PRO.DAT_BAP IS NOT NULL
         					SESSION_PRO.BLN_ACTIF = 1
         				AND	SESSION_PRO.ID_REGLEMENT_PRO_ADH IS NULL
         				AND	SESSION_PRO.ID_REGLEMENT_PRO_OF  IS NULL
         				AND	SESSION_BAP_PRO.DAT_PAIEMENT IS NULL 
         				AND SESSION_BAP_PRO.DAT_RECEPTION IS NOT NULL
         	)
         	
         	SELECT 'Return Value' = COALESCE(@NB_SESSION_PRO,0)
         END
         
GO


         CREATE PROCEDURE [dbo].[INS_HISTO_OF]

         	@ID_OF int,

         	@ID_OF_REPRENEUR int,

         	@ID_TIERS_MANDATAIRE int,

         	@TYPE_DONNEE varchar(50),

         	@DAT_DEBUT datetime,

         	@DAT_FIN datetime,

         	@VAL_ID_DONNEE int

         AS

         

         	DECLARE @VAL_LIB_DONNEE AS VARCHAR(50)

         

         	IF( @TYPE_DONNEE = 'ID_SITUATION_ECONOMIQUE')

         	BEGIN

         	SET @VAL_LIB_DONNEE = (SELECT TOP 1 LIBL_SITUATION_ECONOMIQUE FROM SITUATION_ECONOMIQUE WHERE ID_SITUATION_ECONOMIQUE = @VAL_ID_DONNEE)

         	END

         	insert into HISTO_OF

         		(

         			ID_OF,

         			ID_OF_REPRENEUR,

         			ID_TIERS_MANDATAIRE,

         			DAT_DEBUT,

         			DAT_FIN,

         			TYPE_DONNEE,

         			VAL_LIB_DONNEE,

         			VAL_ID_DONNEE

         		)

         	values

         		(

         			@ID_OF,

         			@ID_OF_REPRENEUR,

         			@ID_TIERS_MANDATAIRE,

         			@DAT_DEBUT,

         			@DAT_FIN,

         			@TYPE_DONNEE,

         			@VAL_LIB_DONNEE,

         			@VAL_ID_DONNEE

         		)

         	

         	RETURN SCOPE_IDENTITY()

         
GO

         -- =======================================================================================================================================
         -- Author		: Kwame Woollams
         -- Create date	: 20 septembre 2007
         -- Description	: Permet de generer le flux pour une copie d'ordre de virement
         -- EDT_ORDRES_VIREMENT_COPIE 28, 63, 1, 126, 48, '74055', '66684'
         -- =======================================================================================================================================
         -- 26/12/08 par SBR - suppression filtre sur ‚tablissement principal
         -- =======================================================================================================================================
         -- 03/12/09 par SBR - adaptation gabarit suite au groupe de travail sur les ‚ditions
         --					- ajout du nø IBAN
         -- =======================================================================================================================================
         -- 10/06/10 par SBR - 2 DR qui ont les mˆmes caract‚ristiques ne sont pas prises en compte car utilisation de la clause DISTINCT.
         --					  Correction par ajout du champ POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE dans la table #POSTE_COUT_REGLE_ADH_OF
         -- =======================================================================================================================================
         -- 10/11/11 par SBR - Correction mauvaise gestion des actions co qui peut conduire … l'‚dition de plusieurs pav‚s d'entˆte dans le courrier
         --					  Impact sur Information de l'adresse emetteur
         -- =======================================================================================================================================
         -- 15/11/11 par SBR - Traitement adresse emetteur split‚ entre ADH et OF
         -- =======================================================================================================================================
         -- 15/06/12 par DSZ - 13601 - @@LIB_RAISON_SOCIALE_OF varchar(50) ->  varchar(64)
         -- =======================================================================================================================================
         -- 19/09/12 par DSZ - 13697 : Rendre dynamique le nø de t‚l‚phone 
         -- =======================================================================================================================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =======================================================================================================================================
         -- TLE 13/07/2013 : 15143 : BBL- Taille du champ IBAN table TRANSACTION (de 27 … 34)
         -- =======================================================================================================================================
         -- HBO - 201113 - M16378: Lot 1 - Editions
         -- =======================================================================================================================================
         -- LDE/OPA 23/05/2014 : #213 En tant qu'utilisateur OPTIFORM, 
         -- lorsque j'‚dite un courrier (PEC, PRO) … destination d'un Adh‚rent ou d'un OF, je veux que, 
         -- l'adresse … afficher dans la zone "correspondance" soit l'adresse TSA propre … ce type de courrier 
         -- si le mode "TSA" s'applique sinon qu'elle soit l'adresse actuelle
         -- =======================================================================================================================================
         
         CREATE PROCEDURE EDT_ORDRES_VIREMENT_COPIE
         	@ID_ETABLISSEMENT		INT,
         	@ID_BENEFICIAIRE		INT,
         	@TYPE_BENEFICIAIRE		INT,
         	@ID_ADRESSE				INT,
         	@ID_CONTACT				INT,
         	@TYPE_DESTINATAIRE		INT,
         	@ID_TRANSACTION			INT,
         	@ID_REGLEMENT			INT
         AS
         	BEGIN
         		DECLARE
         			@MODE_EDITION TINYINT,
         			@COD_ADHERENT_OF AS VARCHAR(8),
         			@ID_OF AS INT,
         			@ID_ADHERENT AS INT,
         			@LIB_RAISON_SOCIALE_ADHERENT AS VARCHAR(50),
         			@LIB_RAISON_SOCIALE_OF AS VARCHAR(64),
         			@ID_UTIL AS INT,
         			@LIB_VILLE AS VARCHAR(50),
         			@ID_ETAB_OF AS INT,
         			@ID_ETAB AS INT,
         			@TOT AS MONEY,
         			-- r‚cup‚ration nø iban & BIC
         			@NUM_IBAN VARCHAR(34),
         			@BIC VARCHAR(11)
         	
         		SELECT
         			@NUM_IBAN = NUM_IBAN,
         			@BIC = BIC
         		FROM
         			[TRANSACTION]
         		WHERE
         			ID_TRANSACTION = @ID_TRANSACTION
         
         		SET @MODE_EDITION = 1
         
         		SET @ID_ETAB = NULL
         		SET @ID_ETAB_OF = NULL
         
         		/* Mise en place des variables en fonction du destinataire */
         		IF (@TYPE_DESTINATAIRE = 1)
         		BEGIN
         			SELECT
         				@ID_ADHERENT					= ADHERENT.ID_ADHERENT,
         				@COD_ADHERENT_OF				= ADHERENT.COD_ADHERENT,
         				@LIB_RAISON_SOCIALE_ADHERENT	= ADHERENT.LIB_RAISON_SOCIALE
         			FROM
         				ETABLISSEMENT
         			JOIN
         				ADHERENT
         			ON	ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         			WHERE
         				ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         		END
         
         		IF (@TYPE_DESTINATAIRE = 2)
         		BEGIN
         			SELECT
         				@ID_OF							= ORGANISME_FORMATION.ID_OF,
         				@COD_ADHERENT_OF				= ORGANISME_FORMATION.COD_OF,
         				@LIB_RAISON_SOCIALE_OF			= ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         			FROM
         				ETABLISSEMENT_OF
         			JOIN 
         				ORGANISME_FORMATION	
         			ON	ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			WHERE
         				ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT
         
         		END
         
         		/* Informations sur le module P.E.C. */
         		SELECT DISTINCT
         			MODULE_PEC.LIBL_MODULE_PEC,
         			MODULE_PEC.ID_MODULE_PEC
         		INTO
         			[#ORGANISME_FORMATION]
         		FROM
         			POSTE_COUT_REGLE
         		JOIN 
         			REGLEMENT
         		ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         		JOIN 
         			MODULE_PEC
         		ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1;
         	
         		/* Information sur le plan de financement du stagiaire */
         		SELECT
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US)		AS MNT_REGLE_HT,
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US_TVA)	AS MNT_REGLE_TVA,
         	--		SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US) * POSTE_COUT_REGLE.TAU_TVA AS MNT_REGLE_TVA,
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE, 
         			STAGIAIRE_PEC.ID_ETABLISSEMENT 
         		INTO
         			[#PLAN_FINANCEMENT_US_OF]
         		FROM
         			PLAN_FINANCEMENT_US
         		JOIN 
         			UNITE_STAGIAIRE	
         		ON	PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         		JOIN 
         			STAGIAIRE_PEC
         		ON	UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         		JOIN 
         			POSTE_COUT_REGLE
         		ON	PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		JOIN 
         			REGLEMENT
         		ON	REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         		GROUP BY
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT--,
         	--		POSTE_COUT_REGLE.TAU_TVA
         
         		/* Information sur les modules P.E.C. */
         		SELECT DISTINCT 
         			MODULE_PEC.ID_MODULE_PEC,
         			MODULE_PEC.COD_MODULE_PEC,	
         			MODULE_PEC.LIBL_MODULE_PEC,
         			ADHERENT.ID_ADHERENT,
         			ADHERENT.COD_ADHERENT,
         			ADHERENT.LIB_RAISON_SOCIALE
         		INTO
         			#MODULE_PEC
         		FROM 
         			REGLEMENT
         		JOIN 
         			POSTE_COUT_REGLE 
         		ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         		JOIN 
         			MODULE_PEC 
         		ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		JOIN 
         			NR140 
         		ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         		JOIN 
         			ETABLISSEMENT 
         		ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         		JOIN 
         			ADHERENT 
         		ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         	
         		CREATE TABLE #TMP_GENERAL
         		(
         			LIB_NOM_CONSEILLER VARCHAR(35), 
         			LIB_PNM_CONSEILLER VARCHAR(35), 
         			ID_UTILISATEUR INT, 
         			LIB_PRENOM_CHARGE_RELATION VARCHAR(35), 
         			LIB_NOM_CHARGE_RELATION VARCHAR(35), 
         			LIB_VILLE VARCHAR(50), 
         			EMAIL_CHARGE_RELATION VARCHAR(100), 
         			NUM_VIREMENT INT
         		)
         
         		/* Information sur l'adresse emetteur */
         		IF (@TYPE_DESTINATAIRE = 1)
         			INSERT INTO #TMP_GENERAL
         			SELECT	DISTINCT
         					CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         					CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         					CR.ID_UTILISATEUR,
         					CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         					CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         					CR.LIB_VILLE,
         					CR.EMAIL			as EMAIL_CHARGE_RELATION,
         					REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         			JOIN 
         				POSTE_COUT_REGLE 
         			ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN 
         				MODULE_PEC 
         			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN 
         				NR140 
         			ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN 
         				ETABLISSEMENT 
         			ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			AND	ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT -- 10/11/11 par SBR: gestion du cas des actions co multi ‚tablissements
         			JOIN 
         				ADHERENT 
         			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         			JOIN
         				ACTION_PEC
         			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         			LEFT JOIN
         				UTILISATEUR CR -- charg‚ de relation
         			ON	ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR	-- 10/11/11 par SBR: on ne filtre que sur le CR de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			LEFT JOIN
         				UTILISATEUR CM -- charg‚ de mission
         			ON	ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR	-- 10/11/11 par SBR: on ne filtre que sur le CM de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         
         		IF (@TYPE_DESTINATAIRE = 2)
         			INSERT INTO #TMP_GENERAL
         			SELECT	TOP 1
         					CM.LIB_NOM			AS LIB_NOM_CONSEILLER,
         					CM.LIB_PNM			AS LIB_PNM_CONSEILLER,
         					CR.ID_UTILISATEUR,
         					CR.LIB_PNM			AS LIB_PRENOM_CHARGE_RELATION,
         					CR.LIB_NOM			AS LIB_NOM_CHARGE_RELATION,
         					CR.LIB_VILLE,
         					CR.EMAIL			AS EMAIL_CHARGE_RELATION,
         					REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         			JOIN 
         				POSTE_COUT_REGLE 
         			ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN 
         				MODULE_PEC 
         			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN 
         				NR140 
         			ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN 
         				ETABLISSEMENT 
         			ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			JOIN 
         				ADHERENT 
         			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         			JOIN
         				ACTION_PEC
         			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         			LEFT JOIN
         				UTILISATEUR CR -- charg‚ de relation
         			ON	ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR	-- 10/11/11 par SBR: on ne filtre que sur le CR de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			LEFT JOIN
         				UTILISATEUR CM -- charg‚ de mission
         			ON	ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR	-- 10/11/11 par SBR: on ne filtre que sur le CM de l'‚tablissement et plus sur le CM de l'action en cas d'action CO
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         
         		CREATE TABLE #POSTE_COUT_REGLE_ADH_OF
         		(
         			ID_POSTE_COUT_REGLE INT,
         			LIB_RAISON_SOCIALE VARCHAR(100), 
         			DAT_DEBUT DATETIME,
         			MNT_REGLE_HT DECIMAL(18,2),
         			LIBC_TYPE_FACTURE VARCHAR(50),
         			NUM_FACTURE VARCHAR(50), 
         			DAT_FIN DATETIME,
         			MNT_REGLE_TVA DECIMAL(18,2),
         			COD_SESSION_PEC VARCHAR(17),
         			ID_MODULE_PEC INT, 
         			ID_OF INT, 
         			MNT_REGLE_TTC DECIMAL(18,2),
         			MNT_POSTE_COUT_REGLE_TTC DECIMAL(18,2)
         		)
         
         		/* D‚finition du total en fonction du type de b‚n‚ficiaire */
         		IF (@TYPE_DESTINATAIRE = 2) -- OF
         		BEGIN
         			/* Information du r‚gl‚ de chaque P.C.R. par adh‚rent */
         			INSERT INTO #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					ADHERENT.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE, 
         					SESSION_PEC.DAT_DEBUT AS DAT_DEBUT,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN AS DAT_FIN,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					STAGIAIRE_PEC.ID_ETABLISSEMENT AS ID_OF, 
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA   AS MNT_REGLE_TTC,
         					/*POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC*/
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_POSTE_COUT_REGLE_TTC
         				FROM
         					REGLEMENT 
         						INNER JOIN POSTE_COUT_REGLE			ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         						INNER JOIN SESSION_PEC				ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         						INNER JOIN MODULE_PEC				ON SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN STAGIAIRE_PEC			ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         						INNER JOIN ETABLISSEMENT			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         						INNER JOIN ADHERENT					ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         						INNER JOIN #PLAN_FINANCEMENT_US_OF	ON #PLAN_FINANCEMENT_US_OF.ID_POSTE_COUT_REGLE=POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE AND #PLAN_FINANCEMENT_US_OF.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         						INNER JOIN TYPE_FACTURE				ON POSTE_COUT_REGLE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         			   WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END
         
         		IF (@TYPE_DESTINATAIRE = 1) --ADH
         		BEGIN
         			/* Information du r‚gl‚ de chaque P.C.R. par O.F. */
         			INSERT INTO #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					CONVERT(VARCHAR,ORGANISME_FORMATION.COD_OF) + ' ' + ORGANISME_FORMATION.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE,
         					SESSION_PEC.DAT_DEBUT AS DAT_DEBUT,
         					POSTE_COUT_REGLE.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN AS DAT_FIN,
         					POSTE_COUT_REGLE.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					NULL,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC	AS MNT_REGLE_TTC,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC
         				FROM 
         					POSTE_COUT_REGLE
         						INNER JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         						INNER JOIN MODULE_PEC				ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN SESSION_PEC				ON SESSION_PEC.ID_SESSION_PEC = POSTE_COUT_REGLE.ID_SESSION_PEC
         						INNER JOIN NR140					ON MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         						INNER JOIN ETABLISSEMENT			ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         						INNER JOIN ADHERENT					ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         						LEFT OUTER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         						LEFT OUTER JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         						INNER JOIN TYPE_FACTURE				ON TYPE_FACTURE.ID_TYPE_FACTURE = POSTE_COUT_REGLE.ID_TYPE_FACTURE
         				WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END
         	
         		--SELECT @TOT=SUM(MNT_POSTE_COUT_REGLE_TTC) FROM  #POSTE_COUT_REGLE_ADH_OF;
         		SELECT @TOT = SUM(ROUND(MNT_REGLE_TVA, 2) + MNT_REGLE_HT) FROM  #POSTE_COUT_REGLE_ADH_OF;
         
         		-- XML Generation
         		WITH XMLNAMESPACES (
         			DEFAULT 'ORDRE_VIREMENT_COPIE'
         		)
         		SELECT
         				-- Recuperation des informations sur le contact
         				dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
         				(
         					SELECT
         						CASE
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'VOTRE CODE ORGANISME : '
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'VOTRE CODE ADHRENT : '
         						END	AS VOTRE_CODE,
         						CAST(@COD_ADHERENT_OF AS VARCHAR) AS COD_ADHERENT_OF,
         						LIB_PRENOM_CHARGE_RELATION,
         						LIB_NOM_CHARGE_RELATION,
         						EMAIL_CHARGE_RELATION AS EMAIL,
         
         						-- R‚cup‚ration des informations sur l'‚metteur
         						dbo.GetXmlAdrUtilAvecTel(ID_UTILISATEUR, 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         															(SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE)
         														ELSE
         															(SELECT MAX(CAST(dbo.DossierEstTSA(COD_MODULE_PEC, 1) AS INT)) FROM #MODULE_PEC)
         													END
         												), 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 1
         														ELSE 0
         													END
         												)) AS EMETTEUR,
         
         						CAST(NUM_VIREMENT AS VARCHAR) AS NUM_VIREMENT,
         						RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         						dbo.GetFullDate(GETDATE()) AS DATE,
         						dbo.GetContactSalutation(@ID_CONTACT, 1) AS POLITESSE_HAUT
         					FROM
         						#TMP_GENERAL
         					FOR XML RAW('REFERENCE_LETTRE'), ELEMENTS, TYPE
         				),
         
         				-- Zone titre
         				(
         					SELECT
         						MIN(dbo.GetFullDate(DAT_REGLEMENT)) AS DAT_REGLEMENT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) AS MONEY)) AS MNT_REGLE_TTC,
         						@num_iban AS IBAN,
         						@BIC AS BIC,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_HT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) - SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_TVA,
         						CASE 
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'correspondant … (aux) l''action(s) de formation que vous avez r‚alis‚e(s).'			
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'correspondant aux frais de salaires, annexes et divers li‚s aux actions de formation d‚crites ci-dessous.'			
         						END AS CORPS_TEXTE_VARIABLE
         					
         					FROM REGLEMENT
         					JOIN POSTE_COUT_REGLE 
         					ON	 POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         					WHERE
         						REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         						AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         						AND REGLEMENT.BLN_ACTIF = 1
         						AND REGLEMENT.BLN_EN_COURS	= 1
         						AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         					FOR XML RAW('TITRE'), ELEMENTS, TYPE
         				),
         
         				'Intitul‚ du module' AS LIB_TITRE_TABLEAU,
         
         				CASE
         					WHEN (@TYPE_DESTINATAIRE = 2) THEN 'Adh‚rent'
         					WHEN (@TYPE_DESTINATAIRE = 1) THEN 'Organisme Formation'
         				END	AS LIB_TITRE_TABLEAU_LIGNE_2,
         
         
         				-- Zone tableau
         				CASE 
         				WHEN (@TYPE_DESTINATAIRE = 2) THEN
         				(
         					SELECT
         						LIBL_MODULE_PEC,
         						(
         							SELECT
         								COALESCE(LIB_RAISON_SOCIALE,' ') AS LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) AS DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) AS DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_OF.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM 
         						#ORGANISME_FORMATION RUPTURE_OF
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				-- Cas d un document ADH
         				WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         				(
         					SELECT
         						CONVERT(VARCHAR,COD_MODULE_PEC) + ' ' + LIBL_MODULE_PEC AS LIBL_MODULE_PEC,
         						(
         							SELECT
         								COALESCE(LIB_RAISON_SOCIALE,' ') AS LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) AS DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) AS DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_MOD.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM
         						#MODULE_PEC RUPTURE_MOD
         					WHERE
         						RUPTURE_MOD.ID_ADHERENT = @ID_ADHERENT
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				END,
         		
         				(
         				SELECT dbo.GetFrenchCurrencyFormat(CAST(@TOT AS MONEY)) AS MONTANT_TOTAL 
         				FOR XML RAW ('TABLEAU_TOTAL'), ELEMENTS, TYPE
         				),
         
         				(
         				SELECT dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_BAS
         				FOR XML RAW ('POLITESSE_BAS'), ELEMENTS, TYPE
         				)
         
         		FOR XML RAW('REGLEMENT'), ELEMENTS
         		--------------------------------------------------------------------------------------------
         	END
GO

         
         CREATE PROCEDURE [dbo].[INS_NR410] 
         	@ID_ARRIVEE_PIECE_PRO			INT,
         	@ID_MOTIF_NON_CONFORM_PIECE_PRO	INT
         AS  
         
         	IF NOT EXISTS ( SELECT 1 
         					FROM NR410 
         					WHERE	 NR410.ID_ARRIVEE_PIECE_PRO = @ID_ARRIVEE_PIECE_PRO  
         						 AND NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = @ID_MOTIF_NON_CONFORM_PIECE_PRO  
         				)
         	BEGIN
         		INSERT INTO NR410
         		  (
         			ID_ARRIVEE_PIECE_PRO,
         			ID_MOTIF_NON_CONFORM_PIECE_PRO
         		  )
         		VALUES
         		(
         		   @ID_ARRIVEE_PIECE_PRO,
         		   @ID_MOTIF_NON_CONFORM_PIECE_PRO
         		)
         	END
GO

         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         ----------------------------------------------  
         
         CREATE PROCEDURE [dbo].[DARES_HISTO_DGEFP]
         	@ID_CONTRAT_PRO			AS INT
         AS
         BEGIN
         
         	
         	
         	
         	DECLARE @NB_UNITE_FORMATION_TOT AS decimal(18,2)
         	DECLARE @NB_UNITE_TOTAL_TOT AS decimal(18,2)
         	DECLARE @NB_ORGANISMES_INTERVENANTS AS INT
         	DECLARE @NUM_SIRET_ORGANISME_PRINCIPAL AS VARCHAR(14)
         	DECLARE @BLN_EXTERNE tinyint
         
         	SELECT	@NB_UNITE_FORMATION_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_FORMATION),0), 
         			@NB_UNITE_TOTAL_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_TOTALE),0) 
         	FROM	CONTRAT_PRO 
         			INNER JOIN MODULE_PRO ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         			INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
         			AND	MODULE_PRO.BLN_ACTIF = 1			
         			AND TYPE_FORMATION.COD_TYPE_FORMATION != 'FTUT'
         
         	SELECT   @NB_ORGANISMES_INTERVENANTS = COUNT(DISTINCT ETABLISSEMENT_OF.ID_OF)
         	FROM	 MODULE_PRO 
         			 INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE		MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_ACTIF = 1
         
         	SET		@NUM_SIRET_ORGANISME_PRINCIPAL = NULL
         	SET		@BLN_EXTERNE = 1
         	SELECT  @NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT_OF.NUM_SIRET,
         			@BLN_EXTERNE					= MODULE_PRO .BLN_EXTERNE 
         	FROM    MODULE_PRO 
         			LEFT JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE	MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_PRINCIPAL = 1
         
         	IF @NUM_SIRET_ORGANISME_PRINCIPAL IS NULL AND @BLN_EXTERNE = 0
         	BEGIN
         		SELECT	@NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT.NUM_SIRET
         		FROM	CONTRAT_PRO
         				INNER JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT 
         		WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         	END
         
         
         	SELECT  TOP 1 CONTRAT_PRO.*,
         			@NB_UNITE_FORMATION_TOT			AS NB_UNITE_FORMATION,
         			@NB_UNITE_TOTAL_TOT				AS NB_UNITE_TOTALE,
         			CLASSIFICATION.COD_CLASSIFICATION, 
         			TYPE_CONTRAT_PRO.COD_TYPE_CONTRAT_PRO,
         			ADHERENT.LIB_RAISON_SOCIALE					AS LIB_RAISON_SOCIALE_ADH,
         			ETABLISSEMENT.NUM_SIRET						AS NUM_SIRET_ADH,
         			ADRESSE.LIB_ADR								AS LIB_ADR1_ADH,
         			ADRESSE.LIB_COMP_VOIE						AS LIB_ADR2_ADH,
         			ADRESSE.LIB_CP_CEDEX						AS LIB_CP_CEDEX_ADH,
         			ADRESSE.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_ADH,
         			ETABLISSEMENT_OF.NUM_SIRET					AS NUM_SIRET_OF,
         			TUTEUR.NOM_INDIVIDU							AS NOM_INDIVIDU_TUTEUR,
         			TUTEUR.PRENOM_INDIVIDU						AS PRENOM_INDIVIDU_TUTEUR,
         			TUTEUR.BLN_MASCULIN							AS BLN_MASCULIN_TUTEUR,
         			SALARIE_PRO.COD_IDE,
         			SALARIE_PRO.ID_TRANCHE_AGE, 
         			SALARIE_PRO.ID_NATIONALITE, 
         			SALARIE_PRO.BLN_TRAVAILLEUR_HANDICAPE,
         			SALARIE_PRO.LIB_DERNIERE_CERTIF_PROF,
         			SALARIE_PRO.LIB_DERNIER_EMPLOI_OCCUPE,
         			SALARIE_PRO.NUM_DUREE_SITUATION,
         
         			ADRESSE_SALARIE_PRO.NUM_TEL								AS NUM_TEL_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_FAX								AS NUM_FAX_SALARIE_PRO,
         			SALARIE_PRO.NUM_MOBILE									AS NUM_MOBILE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_VOIE							AS NUM_VOIE_SALARIE_PRO,
         			COMP_NUM_ADR_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO,
         			TYPE_VOIE_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE_SALARIE_PRO,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE_SALARIE_PRO.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE_SALARIE_PRO.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         																	AS LIB_MENTION_PARTICULIERE_SALARIE_PRO,
         			HEXAPOSTE_SALARIE_PRO.COD_INSEE_COMMUNE					AS COD_INSEE_COMMUNE_SALARIE_PRO,
         			PAYS_SALARIE_PRO.COD_DDTEFP								AS COD_PAYS_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_COMP_VOIE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_ADR								AS LIB_ADR1_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_ADR2_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_CP_CEDEX						AS LIB_CP_CEDEX_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_SALARIE_PRO,
         
         			INDIVIDU.BLN_MASCULIN,
         			INDIVIDU.NOM_INDIVIDU,
         			INDIVIDU.PRENOM_INDIVIDU,
         			INDIVIDU.NOM_JEUNE_FILLE,
         			INDIVIDU.DAT_NAISSANCE,
         			NATIONALITE.COD_DDTEFP						AS COD_DDTEFP_NATIONALITE,
         			ADRESSE.NUM_TEL,
         			ADRESSE.NUM_FAX,
         			SALARIE_PRO.NUM_MOBILE,
         			ADRESSE.NUM_VOIE,
         			COMP_NUM_ADR.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE,
         			TYPE_VOIE.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         			AS LIB_MENTION_PARTICULIERE,
         			HEXAPOSTE.COD_INSEE_COMMUNE,
         			PAYS.COD_DDTEFP							AS COD_PAYS,
         			ADRESSE.LIB_COMP_VOIE,
         			TIERS.NUM_SIRET							AS NUM_SIRET_TIERS,
         			TIERS.COD_TIERS							AS COD_TIERS,
         			IDCC.COD_IDCC, 
         			IDCC.LIBL_IDCC,
         			NIVEAU.COD_DDTEFP						AS COD_DDTEFP_NIVEAU,
         			DIPLOME.COD_DDTEFP						AS COD_DDTEFP_DIPLOME, 
         			SITUATION_SALARIE.COD_DDTEFP			AS COD_DDTEFP_SITUATION_SALARIE,
         			SANCTION.COD_DDTEFP						AS COD_DDTEFP_SANCTION,
         			MOTIF_CLOTURE_PRO.COD_DDTEFP			AS COD_DDTEFP_MOTIF_CLOTURE_PRO,
         			MOTIF_CLOTURE_PRO.BLN_RUPTURE			AS BLN_RUPTURE,
         			TYPE_ISSUE_PRO.COD_TYPE_ISSUE_PRO		AS COD_DDTEFP_TYPE_ISSUE_PRO,
         			TYPE_CONTRAT.COD_DDTEFP					AS COD_DDTEFP_TYPE_CONTRAT,
         			SPECIALITE.COD_DDTEFP					AS COD_DDTEFP_SPECIALITE,
         			@NB_ORGANISMES_INTERVENANTS				AS NB_ORGANISMES_INTERVENANTS,
         			@NUM_SIRET_ORGANISME_PRINCIPAL			AS NUM_SIRET_ORGANISME_PRINCIPAL,
         			TYPOLOGIE_CONTRAT.COD_DDTEFP			AS COD_TYPOLOGIE_CONTRAT,
         			TYPE_MIN_SOCIAL.COD_DDTEFP				AS COD_MIN_SOCIAL
         			
         	INTO	#TEMP_CONTRAT
         	FROM	CONTRAT_PRO
         			LEFT  JOIN ETABLISSEMENT		ON ETABLISSEMENT.ID_ETABLISSEMENT	= CONTRAT_PRO.ID_ETABLISSEMENT
         			INNER JOIN ADRESSE				ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE 
         												AND ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         			LEFT JOIN	HEXAPOSTE			ON HEXAPOSTE.ID_HEXAPOSTE = ADRESSE.ID_HEXAPOSTE
         			LEFT JOIN	PAYS				ON PAYS.ID_PAYS = ADRESSE.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR			ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE				ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE
         
         			LEFT JOIN  ADHERENT				ON ADHERENT.ID_ADHERENT				= ETABLISSEMENT.ID_ADHERENT
         			LEFT JOIN CLASSIFICATION		ON CONTRAT_PRO.ID_CLASSIFICATION	= CLASSIFICATION.ID_CLASSIFICATION
         			LEFT JOIN TYPE_CONTRAT_PRO		ON CONTRAT_PRO.ID_TYPE_CONTRAT_PRO = TYPE_CONTRAT_PRO.ID_TYPE_CONTRAT_PRO
         			LEFT JOIN MODULE_PRO			ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         												AND  MODULE_PRO.BLN_PRINCIPAL = 1
         			LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         			LEFT JOIN INDIVIDU	TUTEUR		ON CONTRAT_PRO.ID_TUTEUR = TUTEUR.ID_INDIVIDU
         			INNER JOIN SALARIE_PRO			ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO
         
         			INNER JOIN ADRESSE		AS ADRESSE_SALARIE_PRO		ON ADRESSE_SALARIE_PRO.ID_ADRESSE = SALARIE_PRO.ID_ADRESSE 
         			LEFT JOIN	HEXAPOSTE	AS HEXAPOSTE_SALARIE_PRO	ON HEXAPOSTE_SALARIE_PRO.ID_HEXAPOSTE = ADRESSE_SALARIE_PRO.ID_HEXAPOSTE
         			LEFT JOIN	PAYS		AS PAYS_SALARIE_PRO 		ON PAYS_SALARIE_PRO.ID_PAYS = ADRESSE_SALARIE_PRO.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR	AS COMP_NUM_ADR_SALARIE_PRO	ON ADRESSE_SALARIE_PRO.ID_COMP_NUM_ADR = COMP_NUM_ADR_SALARIE_PRO.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE		AS TYPE_VOIE_SALARIE_PRO	ON TYPE_VOIE_SALARIE_PRO.ID_TYPE_VOIE = ADRESSE_SALARIE_PRO.ID_TYPE_VOIE
         			
         			INNER JOIN INDIVIDU				ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			LEFT JOIN NATIONALITE			ON INDIVIDU.ID_NATIONALITE = NATIONALITE.ID_NATIONALITE
         			LEFT JOIN TIERS					ON CONTRAT_PRO.ID_TIERS_DDTE = TIERS.ID_TIERS
         			LEFT JOIN IDCC					ON CONTRAT_PRO.ID_IDCC = IDCC.ID_IDCC
         			LEFT JOIN NIVEAU				ON SALARIE_PRO.ID_NIVEAU = NIVEAU.ID_NIVEAU
         			LEFT JOIN DIPLOME				ON SALARIE_PRO.ID_DIPLOME = DIPLOME.ID_DIPLOME 
         			LEFT JOIN SITUATION_SALARIE		ON SALARIE_PRO.ID_SITUATION_SALARIE = SITUATION_SALARIE.ID_SITUATION_SALARIE
         			LEFT JOIN SANCTION				ON CONTRAT_PRO.ID_SANCTION = SANCTION.ID_SANCTION
         			LEFT JOIN MOTIF_CLOTURE_PRO		ON CONTRAT_PRO.ID_MOTIF_CLOTURE_PRO = MOTIF_CLOTURE_PRO.ID_MOTIF_CLOTURE_PRO
         			LEFT JOIN TYPE_ISSUE_PRO		ON CONTRAT_PRO.ID_TYPE_ISSUE_PRO = TYPE_ISSUE_PRO.ID_TYPE_ISSUE_PRO
         			LEFT JOIN TYPE_CONTRAT			ON CONTRAT_PRO.ID_TYPE_CONTRAT = TYPE_CONTRAT.ID_TYPE_CONTRAT
         			--LEFT JOIN SPECIALITE			ON CONTRAT_PRO.ID_SPECIALITE = SPECIALITE.ID_SPECIALITE
         			LEFT JOIN THEME					ON CONTRAT_PRO.ID_THEME = THEME.ID_THEME 
         			LEFT JOIN SPECIALITE			ON THEME.ID_SPECIALITE = SPECIALITE.ID_SPECIALITE
         			
         			LEFT JOIN TYPOLOGIE_CONTRAT		ON TYPOLOGIE_CONTRAT.ID_TYPOLOGIE_CONTRAT = CONTRAT_PRO.ID_TYPOLOGIE_CONTRAT
         			LEFT JOIN TYPE_MIN_SOCIAL		ON TYPE_MIN_SOCIAL.ID_TYPE_MIN_SOCIAL = SALARIE_PRO.ID_TYPE_MIN_SOCIAL
         			
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         	SELECT  UTILISATEUR.LIB_NOM				AS LIB_NOM_UTILISATEUR, 
         			UTILISATEUR.LIB_PNM				AS LIB_PNM_UTILISATEUR,	
         			UTILISATEUR.NUM_TEL				AS NUM_TEL_UTILISATEUR, 
         			UTILISATEUR.EMAIL				AS EMAIL_UTILISATEUR, 
         			AGENCE.NUM_FAX					AS NUM_FAX_AGENCE,
         			AGENCE.NUM_TEL					AS NUM_TEL_AGENCE, 
         			AGENCE.COD_POSTAL				AS COD_POSTAL_AGENCE,
         			AGENCE.LIB_VILLE				AS LIB_VILLE_AGENCE, 
         			AGENCE.LIB_ADR1					AS LIB_ADR1_AGENCE, 
         			HEXAPOSTE.COD_INSEE_COMMUNE		AS COD_INSEE_COMMUNE_AGENCE, 
         			AGENCE.LIB_NOM_CONSEILLER		AS LIB_NOM_CONSEILLER, 
                     AGENCE.LIB_PNM_CONSEILLER		AS LIB_PNM_CONSEILLER
         	INTO	#TEMP_OPERATEUR
         	FROM    CONTRAT_PRO 
         			INNER JOIN UTILISATEUR ON CONTRAT_PRO.ID_UTILISATEUR = UTILISATEUR.ID_UTILISATEUR 
         			INNER JOIN AGENCE ON UTILISATEUR.ID_AGENCE = AGENCE.ID_AGENCE 
         			INNER JOIN HEXAPOSTE ON AGENCE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         
         
         	SELECT	ADHERENT.DAT_CREATION				AS DAT_CREATION_ADHERENT,
         			NAF.COD_NAF							AS COD_NAF, 
         			ADRESSE.NUM_TEL						AS NUM_TEL_ENTREPRENEUR,	
         			ADRESSE.NUM_FAX						AS NUM_FAX_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_ENTREPRENEUR,
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_ENTREPRENEUR,
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_ENTREPRENEUR,
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_ENTREPRENEUR, 
         			ADRESSE.LIB_ADR						AS LIB_ADR_ENTREPRENEUR,  
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_ENTREPRENEUR,
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR
         	INTO	#TEMP_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN NR31 ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT
         								AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 
              -- AND   ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL modif 07/03/2007 ED
         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF 
         			LEFT JOIN  ADRESSE ON ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         									AND ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         			LEFT JOIN TYPE_VOIE ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS ON ADRESSE.ID_PAYS = PAYS.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         			
         
         
         
         	SELECT  CONTACT.LIB_NOM_CONTACT				AS LIB_NOM_CONTACT_ENTREPRENEUR, 
         			CONTACT.LIB_PNM_CONTACT				AS LIB_PNM_CONTACT_ENTREPRENEUR, 
         			CIVILITE.COD_DDTEFP					AS COD_DDTEFP_CIVILITE_CONTACT_ENTREPRENEUR, 
         			NAF.COD_NAF							AS COD_NAF_CONTACT_ENTREPRENEUR,
         			NR31.NUM_TEL						AS NUM_TEL_CONTACT_ENTREPRENEUR, 
         			NR31.NUM_FAX						AS NUM_FAX_CONTACT_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_CONTACT_ENTREPRENEUR, 
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_CONTACT_ENTREPRENEUR, 
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_CONTACT_ENTREPRENEUR, 
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEF_TYPE_VOIE_CONTACT_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_CONTACT_ENTREPRENEUR, 
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_CONTACT_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_CONTACT_ENTREPRENEUR,
         			ADRESSE.LIB_ADR						AS LIB_ADR_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_CONTACT_ENTREPRENEUR
         	INTO	#TEMP_CONTACT_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 
         			--AND ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL modif 07/03/2007 ED
         			LEFT JOIN NR31  ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT 
         						AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADRESSE ON NR31.ID_ADRESSE = ADRESSE.ID_ADRESSE 
         			LEFT JOIN CONTACT ON NR31.ID_CONTACT = CONTACT.ID_CONTACT
         			LEFT JOIN CIVILITE ON CONTACT.ID_CIVILITE = CIVILITE.ID_CIVILITE 
         			LEFT JOIN TYPE_VOIE ON ADRESSE.ID_TYPE_VOIE = TYPE_VOIE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS  ON PAYS.ID_PAYS = ADRESSE.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR 
         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         
         	--SELECT * FROM #TEMP_CONTRAT
         	--SELECT * FROM #TEMP_OPERATEUR
         	--SELECT * FROM #TEMP_ENTREPRENEUR
         	--SELECT * FROM #TEMP_CONTACT_ENTREPRENEUR
         
         
         
         	SELECT	* INTO #TMP_HISTO
         	FROM	#TEMP_CONTRAT
         			FULL OUTER JOIN #TEMP_OPERATEUR	ON 1=1
         			FULL OUTER JOIN #TEMP_ENTREPRENEUR ON 1=1
         			FULL OUTER JOIN #TEMP_CONTACT_ENTREPRENEUR ON 1=1
         
         	INSERT INTO DARES_CONTRAT_DGEFP
         	(
         	ID_CONTRAT_PRO	,
         	NUM_AVENANT	,
         	DAT_CREATION	,
         	DAT_ENVOI_DGEFP	,
         	BLN_EXONERATION_CHARGES	,
         	NUM_ENREGISTREMENT_DDTE	,
         	DAT_DEPOT_DDTE	,
         	DAT_ENREGISTREMENT_DDTE	,
         
         	BLN_INITIAL	,
         	BLN_MODIFICATION	,
         	BLN_AVENANT	,
         	DAT_DEB_CONTRAT	,
         	DAT_FIN_CONTRAT	,
         	NUM_DUREE_HEBDO_TRAVAIL	,
         	NUM_DUREE_PERIODE_ESSAI	,
         	NUM_DUREE_CONTRAT	,
         	NB_UNITE_FORMATION	,
         	COD_CLASSIFICATION	,
         	COEF_CLASSIFICATION	,
         	MNT_SALAIRE_BRUT_MENSUEL	,
         	COD_TYPE_CONTRAT	,
         	DAT_SIGNATURE_CONTRAT	,
         	LIB_RAISON_SOCIALE_ADH	,
         	NUM_SIRET_ADH	,
         	LIB_ADR1_ADH	,
         	LIB_ADR2_ADH	,
         	LIB_CP_CEDEX_ADH	,
         	LIB_VIL_CEDEX_ADH	,
         	NUM_SIRET_OF	,
         	NOM_INDIVIDU_TUTEUR	,
         	PRENOM_INDIVIDU_TUTEUR	,
         	LIB_QUALIF_TUTEUR	,
         	NOM_FICHIER_XML	,
         	STATUT_HISTO	,
         	MOTIF_CONTROL_CONFORMITE	,
         	COMMENTAIRE_COMMANDITAIRE	,
         	ETAT_TRAITEMENT_HISTO	,
         	NUM_DEPOT_DDTE	,
         	LIB_LIEU_FORMATION	,
         	DAT_EXAMEN	,
         	LIBL_QUALIFICATION_VISEE	,
         	NB_ORGANISMES_INTERVENANTS	,
         	NUM_SIRET_ORGANISME_PRINCIPAL	,
         	EMAIL_PRO_ENTREPRENEUR	,
         	COD_NAF	,
         	COD_DDTEFP_COMP_NUM_ADR_ENTREPRENEUR	,
         	NUM_VOIE_ENTREPRENEUR	,
         	LIB_ADR_ENTREPRENEUR	,
         	LIB_COMP_VOIE_ENTREPRENEUR	,
         	LIB_CP_CEDEX_ENTREPRENEUR	,
         	LIB_VIL_CEDEX_ENTREPRENEUR	,
         	LIB_MENTION_PARTICULIERE_ENTREPRENEUR	,
         	COD_INSEE_COMMUNE_ENTREPRENEUR	,
         	COD_PAYS_ENTREPRENEUR	,
         	COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR	,
         	LIB_CAISSE_RETRAITE	,
         	NUM_FAX_ENTREPRENEUR	,
         	NUM_TEL_ENTREPRENEUR	,
         	LIB_ORGANISME_PREVOYANCE	,
         	NUM_NB_SALARIE_ETABLISSEMENT	,
         	DAT_CLOTURE	,
         	BLN_PARTICIPATION_FINANCIERE	,
         	COD_DDTEFP_DIPLOME	,
         	COD_DDTEFP_NIVEAU	,
         	COD_DDTEFP_NATIONALITE	,
         	COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO	,
         	BLN_MASCULIN	,
         	DAT_NAISSANCE	,
         	LIB_ADR1_SALARIE_PRO	,
