           ID_SCHEMAS_XML = 2
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF  ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CSP' -- Periode pro prio  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
           
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- financement enveloppes  
         SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF		ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN TYPE_ENVELOPPE	ON  TYPE_ENVELOPPE.ID_BRANCHE = OPERATION_FINANCIERE.ID_BRANCHE  
         							AND TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          INNER JOIN ENVELOPPE  ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF IN ( 'CSP') 
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE
          AND TYPE_ENVELOPPE.ID_DISPOSITIF IN (SELECT ID_DISPOSITIF FROM DISPOSITIF WHERE DISPOSITIF.COD_DISPOSITIF IN ( 'CSP', 'CPF') )
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          -- PAS DE Financement par fonds individualises (Obligatoire, Volontaire et Conventionnel)  
           
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          (  
          [ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE]  
          )  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON  OPERATION_FINANCIERE  .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          CROSS JOIN SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF IN ( 'CSP') 
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
          AND  not exists  ( select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
           
          --------------------------------------------------------------------------  
          --------------------------------------------------------------------------  
          -- ********************  
          -- * CPF      *  
          -- ********************  
           
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- Financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_BRANCHE = OPERATION_FINANCIERE.ID_BRANCHE  
          AND  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          AND  TYPE_ENVELOPPE.ID_DISPOSITIF = OPERATION_FINANCIERE.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CPF'  
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          UNION  
          -- Financement par fonds individualises (Obligatoire, Volontaire et Conventionnel)  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN TYPE_FINANCEMENT  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND -- Type Financement sur Compte Volontaire et Compte Obligatoire   
          -- + Conventionnel pour la branche PLASTURGIE  
          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)  
          )  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  
            
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          -- Plan financement individualis‚  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NULL  
          ,NR152.ID_TYPE_FINANCEMENT     
          ,1  
          ,ACTIVITE.ID_ACTIVITE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN   SOUS_TYPE_COUT  
          CROSS JOIN   ACTIVITE   
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  ACTIVITE.COD_ACTIVITE in ('-10', '10-49', '50-299', 'VOL')   
          AND  NR152.ID_TYPE_FINANCEMENT IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
         	 (  
         	 -- Pour le Type de financement Volontaire et l'activit‚ Volontaire, tous les Sous Type de couts sont autorises sauf FFRECONV  
         	 NR152.ID_TYPE_FINANCEMENT IN (3)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('VOL')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
         	 )  
         	 OR  
         	 (  
         	 -- Pour le Type de financement Obligatoire +50, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         	 NR152.ID_TYPE_FINANCEMENT IN (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('10-49', '50-299')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT')  
         	 )  
         	 OR  
         	 (  
         	 -- Pour le Type de financement Obligatoire -10, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         	 NR152.ID_TYPE_FINANCEMENT IN (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('-10')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT', 'REM')  
         	 )  
         
          )   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  
          UNION  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON  OPERATION_FINANCIERE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND	(  
         			SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('AF', 'FFRECONV', 'REMFORM')  
         		)   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
         
         
         -- ********************  
          -- * CPF-SUP      *  
          -- ********************  
           
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- Financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_BRANCHE = OPERATION_FINANCIERE.ID_BRANCHE  
          AND  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          AND  TYPE_ENVELOPPE.ID_DISPOSITIF = OPERATION_FINANCIERE.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CPF-SUP'  
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          UNION  
          -- Financement par fonds individualises (Obligatoire, Volontaire et Conventionnel)  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN TYPE_FINANCEMENT  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CPF-SUP'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND -- Type Financement sur Compte Volontaire 
          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)   
          )  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  
            
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          -- Plan financement individualis‚  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NULL  
          ,NR152.ID_TYPE_FINANCEMENT     
          ,1  
          ,ACTIVITE.ID_ACTIVITE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN   SOUS_TYPE_COUT  
          CROSS JOIN   ACTIVITE   
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_TYPE_FINANCEMENT IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'CPF-SUP'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
         		 (  
         		 -- Pour le Type de financement Volontaire et l'activit‚ Volontaire, tous les Sous Type de couts sont autorises sauf FFRECONV  
         		 NR152.ID_TYPE_FINANCEMENT IN (3)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('VOL')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
         		 )  
         		 OR  
         		 (  
         		 -- Pour le Type de financement Obligatoire +50, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         		 NR152.ID_TYPE_FINANCEMENT IN (4)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('10-49', '50-299')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT')  
         		 )  
         		 OR  
         		 (  
         		 -- Pour le Type de financement Obligatoire -10, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         		 NR152.ID_TYPE_FINANCEMENT IN (4)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('-10')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT', 'REM')  
         		 )  
         	 )   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  
          UNION  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON  OPERATION_FINANCIERE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'CPF-SUP'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND	(  
         			SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('AF', 'FFRECONV', 'REMFORM')  
         		)   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
         
         
          -- ********************  
          -- * PP-CPF           *  
          -- ********************  
           
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- Financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_BRANCHE = OPERATION_FINANCIERE.ID_BRANCHE  
          AND  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          AND  TYPE_ENVELOPPE.ID_DISPOSITIF = OPERATION_FINANCIERE.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'PP-CPF'  
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          UNION  
          -- Financement par fonds individualises (Obligatoire, Volontaire et Conventionnel)  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN TYPE_FINANCEMENT  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'PP-CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND -- Type Financement sur Compte Volontaire et Compte Plan Obligatoire
          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)   
          )  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  
            
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          -- Plan financement individualis‚  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NULL  
          ,NR152.ID_TYPE_FINANCEMENT     
          ,1  
          ,ACTIVITE.ID_ACTIVITE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN   SOUS_TYPE_COUT  
          CROSS JOIN   ACTIVITE   
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_TYPE_FINANCEMENT IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'PP-CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
         		 (  
         		 -- Pour le Type de financement Volontaire et l'activit‚ Volontaire, tous les Sous Type de couts sont autorises sauf FFRECONV  
         		 NR152.ID_TYPE_FINANCEMENT IN (3)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('VOL')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
         		 )  
         		 OR  
         		 (  
         		 -- Pour le Type de financement Obligatoire +50, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         		 NR152.ID_TYPE_FINANCEMENT IN (4)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('10-49', '50-299')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT')  
         		 )  
         		 OR  
         		 (  
         		 -- Pour le Type de financement Obligatoire -10, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         		 NR152.ID_TYPE_FINANCEMENT IN (4)  
         		 AND  
         		 ACTIVITE.COD_ACTIVITE in ('-10')   
         		 AND  
         		 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT', 'REM')  
         		 )  
         	 )   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  
          UNION  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON  OPERATION_FINANCIERE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'PP-CPF'  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND	(  
         			SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('AF', 'FFRECONV', 'REMFORM')  
         		)   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
         
         
         
          -- ****************************************  
          -- * OPERATION FINANCIERE POE INDIVIDUELLE*  
          -- ****************************************  
         INSERT INTO OPERATION_FINANCIERE  
          (  
           COD_OPERATION_FINANCIERE,  
           LIBC_OPERATION_FINANCIERE,  
           LIBL_OPERATION_FINANCIERE,  
           DAT_DEBUT,  
           DAT_FIN,  
           DAT_CREATION,  
           BLN_DEFAUT,  
           BLN_ACTIF,  
           DAT_MODIF,  
           ID_PERIODE,  
           ID_AGENCE,  
           ID_BRANCHE,  
           ID_DISPOSITIF,  
           ID_UTILISATEUR,  
           COM_MODE_FINANCEMENT  
          )  
          SELECT  
           COD_OPERATION_FINANCIERE	= 'x',  
           LIBC_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' IND ' + AGENCE.COD_AGENCE,  
           LIBL_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' IND ' + AGENCE.COD_AGENCE,  
           DAT_DEBUT					= '01/01/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_FIN					= '31/12/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_CREATION				= getdate(),  
           BLN_DEFAUT				= 0 ,  
           BLN_ACTIF					= 1,  
           DAT_MODIF					= getdate(),  
           ID_PERIODE				= @ANNEE_ID_PERIODE,  
           ID_AGENCE					= AGENCE.ID_AGENCE,  
           ID_BRANCHE				= BRANCHE.ID_BRANCHE,  
           ID_DISPOSITIF				= DISPOSITIF.ID_DISPOSITIF,  
           82,  
           NULL  
          FROM  
           AGENCE  
           CROSS JOIN BRANCHE  
           CROSS JOIN DISPOSITIF  
          WHERE  
           AGENCE.BLN_ACTIF = 1  -- Agence Actives  
           AND BRANCHE.BLN_ACTIF = 1  
           AND DISPOSITIF.BLN_ACTIF = 1  
           AND not exists  
            (  
             SELECT  
              1  
             FROM  
              OPERATION_FINANCIERE  
             WHERE  
              ID_PERIODE = @ANNEE_ID_PERIODE  
              AND ID_AGENCE = AGENCE.ID_AGENCE  
              AND ID_BRANCHE = BRANCHE.ID_BRANCHE  
              AND ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
              AND LIBC_OPERATION_FINANCIERE LIKE '%' + DISPOSITIF.COD_DISPOSITIF + ' CO %'
            )  
           AND DISPOSITIF.COD_DISPOSITIF IN  
           (  
            'POE'
           )  
            
         INSERT INTO OPERATION_FINANCIERE  
          (  
           COD_OPERATION_FINANCIERE,  
           LIBC_OPERATION_FINANCIERE,  
           LIBL_OPERATION_FINANCIERE,  
           DAT_DEBUT,  
           DAT_FIN,  
           DAT_CREATION,  
           BLN_DEFAUT,  
           BLN_ACTIF,  
           DAT_MODIF,  
           ID_PERIODE,  
           ID_AGENCE,  
           ID_BRANCHE,  
           ID_DISPOSITIF,  
           ID_UTILISATEUR,  
           COM_MODE_FINANCEMENT  
          )  
          SELECT  
           COD_OPERATION_FINANCIERE	= 'x',  
           LIBC_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' CO ' + AGENCE.COD_AGENCE,  
           LIBL_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' CO ' + AGENCE.COD_AGENCE,  
           DAT_DEBUT					= '01/01/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_FIN					= '31/12/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_CREATION				= getdate(),  
           BLN_DEFAUT				= 0 ,  
           BLN_ACTIF					= 1,  
           DAT_MODIF					= getdate(),  
           ID_PERIODE				= @ANNEE_ID_PERIODE,  
           ID_AGENCE					= AGENCE.ID_AGENCE,  
           ID_BRANCHE				= BRANCHE.ID_BRANCHE,  
           ID_DISPOSITIF				= DISPOSITIF.ID_DISPOSITIF,  
           82,  
           NULL  
          FROM  
           AGENCE  
           CROSS JOIN BRANCHE  
           CROSS JOIN DISPOSITIF  
          WHERE  
           AGENCE.BLN_ACTIF = 1  -- Agence Actives  
           AND BRANCHE.BLN_ACTIF = 1  
           AND DISPOSITIF.BLN_ACTIF = 1  
           AND not exists  
            (  
             SELECT  
              1  
             FROM  
              OPERATION_FINANCIERE  
             WHERE  
              ID_PERIODE = @ANNEE_ID_PERIODE  
              AND ID_AGENCE = AGENCE.ID_AGENCE  
              AND ID_BRANCHE = BRANCHE.ID_BRANCHE  
              AND ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
              AND LIBC_OPERATION_FINANCIERE LIKE '%'+DISPOSITIF.COD_DISPOSITIF + ' CO %'
            )  
           AND DISPOSITIF.COD_DISPOSITIF IN  
           (  
            'POE'
           )    
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- Financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          INNER JOIN DISPOSITIF ON TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF IN ('POE')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND OPERATION_FINANCIERE.ID_BRANCHE = TYPE_ENVELOPPE.ID_BRANCHE
          AND OPERATION_FINANCIERE.ID_DISPOSITIF = TYPE_ENVELOPPE.ID_DISPOSITIF
           AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          
           
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          INNER JOIN DISPOSITIF ON  TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE DISPOSITIF.COD_DISPOSITIF IN ('POE')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
            
         
         
           
          --------------------------------------------------------------------------  
          --------------------------------------------------------------------------  
          -- *************************************  
          -- * OPERATION FINANCIERE MULTI BRANCHE - MULTI DISPOSITIF *  
          -- *************************************  
           
          INSERT INTO [dbo].[OPERATION_FINANCIERE]  
          ([COD_OPERATION_FINANCIERE]  
          ,[LIBC_OPERATION_FINANCIERE]  
          ,[LIBL_OPERATION_FINANCIERE]  
          ,[DAT_DEBUT]  
          ,[DAT_FIN]  
          ,[DAT_CREATION]  
          ,[BLN_DEFAUT]  
          ,[BLN_ACTIF]  
          ,[DAT_MODIF]  
          ,[ID_PERIODE]  
          ,[ID_AGENCE]  
          ,[ID_BRANCHE]  
          ,[ID_DISPOSITIF]  
          ,[ID_UTILISATEUR]  
          ,[COM_MODE_FINANCEMENT])  
          SELECT  
          'x'  
          ,'MULTI BR-DISPO' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + LEFT(AGENCE.COD_AGENCE  , 2)
          ,'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + AGENCE.COD_AGENCE  
          ,'01/01/' + @ANNEE_TEXTE + ' 00:00:00'  
          ,'31/12/' + @ANNEE_TEXTE + ' 00:00:00'  
          ,getdate()  
          ,0  
          ,1  
          ,getdate()  
          ,@ANNEE_ID_PERIODE  
          ,AGENCE.ID_AGENCE  
          ,ID_BRANCHE=NULL  
          ,ID_DISPOSITIF=NULL  
          ,82  
          ,NULL  
          FROM AGENCE  
          WHERE AGENCE.BLN_ACTIF = 1  
          AND  not exists (select 1   
          from [OPERATION_FINANCIERE]   
          where [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + AGENCE.COD_AGENCE  
          )  
           
          -- FINANCEMENT  
          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  
          -- Financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          INNER JOIN DISPOSITIF ON TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND DISPOSITIF.COD_DISPOSITIF IN ('PPPRIO', 'FORMTUT', 'FONCTUT', 'CPF')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          UNION  
          -- Financement par fonds individualises (Obligatoire, Volontaire et Conventionnel)  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          CROSS JOIN TYPE_FINANCEMENT  
          WHERE [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND -- Type Financement sur Compte Volontaire et Compte Obligatoire
          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)  
          )  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  
           
          -- PLAN FINANCEMENT  
          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          -- Plan financement individualis‚  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NULL  
          ,NR152.ID_TYPE_FINANCEMENT     
          ,1  
          ,ACTIVITE.ID_ACTIVITE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE   CROSS JOIN   SOUS_TYPE_COUT  
          CROSS JOIN   ACTIVITE   
          WHERE   
          [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  ACTIVITE.COD_ACTIVITE in ('-10', '10-49', '50-299', 'VOL')   
          AND  NR152.ID_TYPE_FINANCEMENT IS NOT NULL  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
         	 (  
         	 -- Pour le Type de financement Volontaire et l'activit‚ Volontaire, tous les Sous Type de couts sont autorises sauf FFRECONV  
         	 NR152.ID_TYPE_FINANCEMENT IN (3)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('VOL')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
         	 )  
         	 OR  
         	 (  
         	 -- Pour le Type de financement Obligatoire, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         	 NR152.ID_TYPE_FINANCEMENT IN  (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('10-49', '50-299')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
         	 )  
         	 OR  
         	 (  
         	 -- Pour le Type de financement Obligatoire, seuls les sous-type de cout 'CP', 'INGE', 'ACTEVAL', 'FCT' sont autorises   
         	 NR152.ID_TYPE_FINANCEMENT IN  (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('-10')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'REM')  
         	 )  
          )   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  
          UNION  
          -- Plan financement enveloppes  
          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          INNER JOIN DISPOSITIF ON  TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE  [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND   
          (   
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('CPF')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('AF', 'FFRECONV', 'REMFORM')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('PPPRIO')  
          AND   
          NOT SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('FFRECONV')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('FORMTUT')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'REM', 'REPHEB', 'TRANSP', 'FCT', 'FFORM', 'REMFORM')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('FONCTUT')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('REM', 'TRANSP')   
          )  
          )  
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  
            
          -- Affecter … chaque op‚ration financiŠre un code identique … son ID.  
          -- -------------------------------------------------------------------------------------------------  
          UPDATE  
           OPERATION_FINANCIERE  
          SET  
           COD_OPERATION_FINANCIERE = ID_OPERATION_FINANCIERE  
          WHERE  
           COD_OPERATION_FINANCIERE = 'x'  
          
         
         END
         
GO

         
         -- =============================================
         -- Author:		SAFIYULLA
         -- Create date: 24-11-2008 
         -- Description:	LIST DES DOSSIERS FACTURE FOR 
         -- PEC AND PRO
         -- =============================================
         -- Author:		SAFIYULLA
         -- Create date: 10-12-2008 
         -- Description:	getting the information of coloumns on PRO 
         		--		with different condition for OF and ADHERENT
         -- =============================================
         -- Author:		SAFIYULLA
         -- Create date: 30-12-2008 
         -- Description:	Modification des colonnes pour arrondi
         -- =============================================
         -- Author:		AMA
         -- Modif date: 30-12-2008 
         -- Description:	
         -- Ajout du m‚canisme de recompile par DROP/CREATE
         -- =============================================
         -- Author:		ASD
         -- Modif date: 15-01-2009 
         -- Description:	Fiche d'‚volution 308
         -- =============================================
         -- Author:		DSZ
         -- Modif date: 26-03-2010 
         -- Description:	Anomalie 12333. Liste des dossiers factures ne fait pas apparaŒtre toutes les DR PEC associ‚es 
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_LST_DOSSIERS_FACTURE]
         	
         @LIST_ID_FACTURE  VARCHAR(MAX)
         
         AS
         BEGIN
         	
         -- SEPERATE THE ID_FACTURE FROM THE PARAMETER 
         DECLARE			@pos        int
         DECLARE         @nextpos    int
         DECLARE			@valuelen   int
         
         CREATE TABLE #LstFacture (ID int) -- NOT NULL)
         
         
            SET @pos = 0
            SET @nextpos = 1
         
            WHILE @nextpos > 0
            BEGIN
               SELECT @nextpos = charindex(',', @LIST_ID_FACTURE, @pos + 1)
               SELECT @valuelen = CASE WHEN @nextpos > 0
                                       THEN @nextpos
                                       ELSE len(@LIST_ID_FACTURE) + 1
                                  END - @pos - 1
               INSERT INTO #LstFacture (ID)
                  VALUES (convert(int, substring(@LIST_ID_FACTURE, @pos + 1, @valuelen)))
               SELECT @pos = @nextpos
            END
           -- RETURN
          -- END 
         
         --select id_facture from facture where id_facture in (select * from #LstFacture)
         
         ------ BEGIN PEC --------
         SELECT 
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PEC.COD_SESSION_PEC AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PEC.LIBL_MODULE_PEC AS LIBL_MODULE,	
         	--SESSION_PEC.DAT_DEBUT,
         	--SESSION_PEC.DAT_FIN,	
         	CONVERT(VARCHAR, SESSION_PEC.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PEC.DAT_FIN, 103) AS DAT_FIN,
         	SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT,	
         	ROUND(POSTE_COUT_REGLE.MNT_REGLE_HT,2) as MNT_ATTESTE_HT,
         	CONVERT(VARCHAR, POSTE_COUT_REGLE.DAT_BAP,103) AS DAT_BAP,
         	REGLEMENT.NUM_VIREMENT,
         	CONVERT(VARCHAR,REGLEMENT.DAT_VALID_REGLEMENT,103) AS DAT_VALID_REGLEMENT,
         
         	CASE WHEN (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		ROUND(POSTE_COUT_REGLE.MNT_REGLE_HT,2)
         	ELSE
         		0.00 
         	END
         	AS MNT_REGLE_HT,	
         
         
         	CASE WHEN (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		ROUND(POSTE_COUT_REGLE.MNT_REGLE_TTC,2)
         	ELSE
         		0.00 
         	END
         	AS MNT_REGLE_TTC,
         -- TRANSACTION	
         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF
         -- END TRANSACTION
         
         
         INTO #TMP_PEC
         FROM POSTE_COUT_REGLE		
         LEFT JOIN FACTURE				ON FACTURE.ID_FACTURE = POSTE_COUT_REGLE.ID_FACTURE
         LEFT JOIN SESSION_PEC			ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 
         LEFT JOIN MODULE_PEC			ON POSTE_COUT_REGLE.ID_MODULE_PEC =	MODULE_PEC.ID_MODULE_PEC
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN SOUS_TYPE_COUT		ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         LEFT JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 
         POSTE_COUT_REGLE.BLN_ACTIF = 1 AND
         -- POSTE_COUT_REGLE.ID_FACTURE = @ID_FACTURE
         POSTE_COUT_REGLE.ID_FACTURE  IN (SELECT ID FROM #LstFacture)
         ------- END PEC --------- 
         
         ---------------------------------------------------------------------------------------------------------------------
         ---------------------------------------------------------------------------------------------------------------------
         
         ------- PRO --------- 
         SELECT DISTINCT
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PRO.COD_SESSION_PRO AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PRO.LIBL_MODULE_PRO AS LIBL_MODULE,
         	--SESSION_PRO.DAT_DEBUT,
         	--SESSION_PRO.DAT_FIN,	
         	CONVERT(VARCHAR, SESSION_PRO.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PRO.DAT_FIN, 103) AS DAT_FIN,
         	'CPRO'	AS LIBL_SOUS_TYPE_COUT,
         --	SESSION_PRO.MNT_ATTESTE_HT as MNT_ATTESTE_HT,
         --MNT_ATTESTE_HT_OF/ADH
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         	THEN
         		ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         	ELSE
         		ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         	END
         	AS MNT_ATTESTE_HT,
         -- DAT_BAP
         	CASE WHEN (FACTURE.ID_FACTURE =SESSION_PRO.ID_FACTURE_OF) 
         	THEN	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_OF , 103)  -- SESSION_PRO.DAT_BAP_OF 
         	ELSE	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_ADH , 103)   -- SESSION_PRO.DAT_BAP_ADH
         	END		AS	DAT_BAP,
         
         -- NUM VIREMENT
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END		
         	AS 	NUM_VIREMENT,
         
         -- DAT VALID REGLEMENT
         	CONVERT(VARCHAR,
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT	REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END,103)
         	AS DAT_VALID_REGLEMENT,
         
         ----MNT_REGLE_HT
         --	(SESSION_PRO.MNT_ATTESTE_HT) AS MNT_ATTESTE_HT,
         
         
         
         --MNT_REGLE_HT_OF/ADH
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         		ELSE
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         		END
         	ELSE
         		0.00
         	END
         	AS MNT_REGLE_HT,
         
         --MNT_REGLE_TTC
         	ROUND(
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN					
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         /*
         			   (SELECT REGLEMENT_PRO.MNT_REGLE_HT * (1 + SP.TAU_TVA_OF)
         				FROM REGLEMENT_PRO RP, SESSION_PRO SP
         				WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         				SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)			
         			ELSE				
         			   (SELECT	REGLEMENT_PRO.MNT_REGLE_HT * (1 + SP.TAU_TVA_ADH)
         				FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         				WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         				SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)					
         		END
         */				
         
         		THEN
         --			ROUND((SESSION_PRO.MNT_VERSE_HT_OF * (1 + SESSION_PRO.TAU_TVA_OF)),2)
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF + SESSION_PRO.MNT_VERSE_TVA_OF ),2)
         		ELSE
         --			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH * (1 + SESSION_PRO.TAU_TVA_ADH)),2)
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH + SESSION_PRO.MNT_VERSE_TVA_ADH ),2)
         		END
         	ELSE
         		0.00
         	END,2)
         	AS MNT_REGLE_TTC,
         
         -- TRANSACTION	
         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF
         -- END TRANSACTION
         INTO #TMP_PRO
         FROM 	SESSION_PRO	
         INNER JOIN FACTURE				ON FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF --OR 
         								   --FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_ADHERENT 
         LEFT JOIN MODULE_PRO			ON SESSION_PRO.ID_MODULE_PRO =	MODULE_PRO.ID_MODULE_PRO
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN REGLEMENT_PRO			ON REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_OF --OR
         								   --REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_ADH 								   
         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 
         -- SESSION_PRO.ID_FACTURE_OF = @ID_FACTURE			OR 
         -- SESSION_PRO.ID_FACTURE_ADHERENT = @ID_FACTURE
         -- SESSION_PRO.ID_FACTURE_OF IN  (SELECT ID FROM #LstFacture)		OR
         -- SESSION_PRO.ID_FACTURE_ADHERENT IN (SELECT ID FROM #LstFacture)
         FACTURE.ID_FACTURE IN  ( SELECT ID FROM #LstFacture)
         
         UNION 
         ----------------------------------------------
         --------- ADH
         SELECT DISTINCT
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PRO.COD_SESSION_PRO AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PRO.LIBL_MODULE_PRO AS LIBL_MODULE,
         	--SESSION_PRO.DAT_DEBUT,
         	--SESSION_PRO.DAT_FIN,	
         	CONVERT(VARCHAR, SESSION_PRO.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PRO.DAT_FIN, 103) AS DAT_FIN,
         	'CPRO'	AS LIBL_SOUS_TYPE_COUT,
         --	SESSION_PRO.MNT_ATTESTE_HT as MNT_ATTESTE_HT,
         --MNT_ATTESTE_HT_OF/ADH
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         	THEN
         		ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         	ELSE
         		ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         	END
         	AS MNT_ATTESTE_HT,
         
         -- DAT_BAP
         	CASE WHEN (FACTURE.ID_FACTURE =SESSION_PRO.ID_FACTURE_OF) 
         	THEN	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_OF , 103)  -- SESSION_PRO.DAT_BAP_OF 
         	ELSE	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_ADH , 103)   -- SESSION_PRO.DAT_BAP_ADH
         	END		AS	DAT_BAP,
         
         -- NUM VIREMENT
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END		
         	AS 	NUM_VIREMENT,
         
         -- DAT VALID REGLEMENT
         	CONVERT(VARCHAR,
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT	REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END,103)
         	AS DAT_VALID_REGLEMENT,
         
         ----MNT_REGLE_HT
         --	(SESSION_PRO.MNT_ATTESTE_HT) AS MNT_ATTESTE_HT,
         /*
         --MNT_ATTESTE_HT
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		ROUND((SESSION_PRO.MNT_ATTESTE_HT),2)
         
         	ELSE
         		0.00
         	END
         	AS MNT_REGLE_HT,
         
         
         --MNT_REGLE_TTC
         	ROUND(
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN					
         			CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         				THEN
         				   (SELECT REGLEMENT_PRO.MNT_REGLE_HT * (1 + SP.TAU_TVA_OF)
         					FROM REGLEMENT_PRO RP, SESSION_PRO SP
         					WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)			
         				ELSE				
         				   (SELECT	REGLEMENT_PRO.MNT_REGLE_HT * (1 + SP.TAU_TVA_ADH)
         					FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         					WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)					
         				
         			END
         	ELSE
         		0.00
         	END,2)
         	AS MNT_REGLE_TTC,
         */
         --MNT_REGLE_HT_OF/ADH
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         		ELSE
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         		END
         	ELSE
         		ROUND(0.00,2)
         	END
         	AS MNT_REGLE_HT,
         
         --MNT_REGLE_TTC
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN					
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         
         		THEN
         --			ROUND((SESSION_PRO.MNT_VERSE_HT_OF * (1 + SESSION_PRO.TAU_TVA_OF)),2)
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF + SESSION_PRO.MNT_VERSE_TVA_OF ),2)
         		ELSE
         --			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH * (1 + SESSION_PRO.TAU_TVA_ADH)),2)
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH + SESSION_PRO.MNT_VERSE_TVA_ADH ),2)
         		END
         	ELSE
         		ROUND(0.00,2)
         	END
         	AS MNT_REGLE_TTC,
         
         
         -- TRANSACTION	
         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF
         -- END TRANSACTION
         --INTO #TMP_PRO
         FROM 	SESSION_PRO	
         INNER JOIN FACTURE				ON -- FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF OR 
         								   FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_ADHERENT 
         LEFT JOIN MODULE_PRO			ON SESSION_PRO.ID_MODULE_PRO =	MODULE_PRO.ID_MODULE_PRO
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN REGLEMENT_PRO			ON --REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_OF OR
         								   REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_ADH 								   
         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 
         -- SESSION_PRO.ID_FACTURE_OF = @ID_FACTURE			OR 
         -- SESSION_PRO.ID_FACTURE_ADHERENT = @ID_FACTURE
         -- SESSION_PRO.ID_FACTURE_OF IN  (SELECT ID FROM #LstFacture)		OR
         -- SESSION_PRO.ID_FACTURE_ADHERENT IN (SELECT ID FROM #LstFacture)
         FACTURE.ID_FACTURE IN  ( SELECT ID FROM #LstFacture)
         --------- ADH 
         ----------------------------------------------
         
         
         ------- END PEC --------- 
         
          --MERG PEC AND PRO
         SELECT #TMP_PEC.* 
         INTO #TMP_LSTDOSFACTURE
         FROM  #TMP_PEC
         --MODIF DSZ 26/03/2010 Mantis 12333: sans ALL "union" fait distinct
         UNION ALL
         -- <--fin modif DSZ 12333
         SELECT #TMP_PRO.* FROM  #TMP_PRO
         
          --END MERG
         
         DROP TABLE		#LstFacture
         
         --BENEFECIAIRE ADR et CODE_POSTAL
         	-- 1.Adherent
         -- SELECT #TMP_LSTDOSFACTURE.*,
         -- Selecting individual Coloumns
         SELECT
         #TMP_LSTDOSFACTURE.ID_FACTURE,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_TRANSACTION,
         #TMP_LSTDOSFACTURE.COD_SESSION,
         #TMP_LSTDOSFACTURE.LIB_RAISON_SOCIALE ,
         #TMP_LSTDOSFACTURE.LIBL_MODULE,
         #TMP_LSTDOSFACTURE.DAT_DEBUT,
         #TMP_LSTDOSFACTURE.DAT_FIN,
         #TMP_LSTDOSFACTURE.LIBL_SOUS_TYPE_COUT ,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_ATTESTE_HT, 1) AS MNT_ATTESTE_HT,
         #TMP_LSTDOSFACTURE.DAT_BAP,
         #TMP_LSTDOSFACTURE.NUM_VIREMENT,
         #TMP_LSTDOSFACTURE.DAT_VALID_REGLEMENT,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_REGLE_HT,1) AS MNT_REGLE_HT,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_REGLE_TTC,1) AS MNT_REGLE_TTC,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF,
         -- End Individual Coloumns
         
         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADH.LIB_RAISON_SOCIALE 
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA 
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT)				
         	ELSE
         	-- 2. TIERS
         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT TIE.LIB_NOM
         			 FROM TIERS TIE 
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF)
         	-- 3. OF
         		ELSE
         			(SELECT O_F.LIB_RAISON_SOCIALE
         			 FROM ORGANISME_FORMATION O_F,  ETABLISSEMENT_OF ETA_OF	 
         			 WHERE 
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF) 								
         		END
         	END
         	AS BENEFECIAIRE,
         -- END BENEFECIAIRE
         
         -- ADRESS
         	-- 1.Adherent
         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_ADR
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE
         	-- 2. TIERS
         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_ADR
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )
         	-- 3. OF
         		ELSE
         			(SELECT ADR.LIB_ADR
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR , ETABLISSEMENT_OF ETA_OF
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS LIB_ADR,
         -- END ADRESS
         -- CODE POSTAL
         	-- 1.Adherent
         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_CP_CEDEX
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE
         	-- 2. TIERS
         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_CP_CEDEX
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )
         	-- 3. OF
         		ELSE
         			(SELECT ADR.LIB_CP_CEDEX
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR, ETABLISSEMENT_OF ETA_OF
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS COD_POSTAL,
         -- END CODE POSTAL
         
         -- VILLE
         	-- 1.Adherent
         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_VIL_CEDEX
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE
         	-- 2. TIERS
         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_VIL_CEDEX
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )
         	-- 3. OF
         		ELSE
         			(SELECT ADR.LIB_VIL_CEDEX
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS LIB_VILLE,
         -- END VILLE
         
         -- END BENEFECIAIRE ADR et CODE_POSTAL
         
         	''''+ #TMP_LSTDOSFACTURE.COD_SESSION as COD_SESSION_EXPORT,
         	''''+ CAST(#TMP_LSTDOSFACTURE.NUM_FACTURE AS VARCHAR) AS NUM_FACTURE,	
         	CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_HT,1) AS MNT_HT,
         	CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_TTC,1) AS MNT_TTC,	
         	CONVERT(VARCHAR,#TMP_LSTDOSFACTURE.DAT_EMISSION,103) AS DAT_EMISSION,	
         	#TMP_LSTDOSFACTURE.COD_TYPE_FACTURE
         
         FROM #TMP_LSTDOSFACTURE
         ORDER BY #TMP_LSTDOSFACTURE.NUM_FACTURE 
         END
         
         
         
         
         --- History of Modifications 
         -- PRO --
         -- NUM VIREMENT
         --	CASE WHEN (SESSION_PRO.ID_FACTURE_ADHERENT IS NOT NULL) THEN
         --		(SELECT REGLEMENT_PRO.NUM_VIREMENT
