 CREATE PROCEDURE INIT_PARAMETRAGE_ANNUEL_2016
         -- =============================================
         -- Auteur       : MBL
         -- Date			: 09/12/2015
         -- Description  : Proc‚dure cr‚ant le param‚trage n‚cessaire pour le d‚marrage de l'exercice 2016
         -- =============================================
         AS
         BEGIN
         	-- begin tran
         	-- ann‚e de l'exercice … ouvrir
         
         	print '2016 - INIT - param‚trage annuel.sql'
         	declare @num_annee int, @id_periode int
         	set @num_annee = 2016
         
         	declare @num_annee_precedente int
         	set @num_annee_precedente = @num_annee-1
         
         	select @id_periode = id_periode from PERIODE where NUM_ANNEE = @num_annee and ID_TYPE_PERIODE  =1
         
         	-- PERIODE_BRANCHE
         	if not exists (select 1 from PERIODE_BRANCHE where id_periode = @id_periode)
         	BEGIN
         		insert into periode_branche
         		(ID_PERIODE, ID_BRANCHE, PRC_MUTUALISATION_VERSEMENT_RELIQUAT, PRC_MS_MIN_REMBOURSEMENT_FRAIS_GESTION, PRC_MS_MIN_DOTATION_ABONDEMENT_VO)
         		select	@id_periode, id_branche, PRC_MUTUALISATION_VERSEMENT_RELIQUAT, PRC_MS_MIN_REMBOURSEMENT_FRAIS_GESTION, PRC_MS_MIN_DOTATION_ABONDEMENT_VO
         		from	PERIODE_BRANCHE t1
         		join	PERIODE t2
         		on		t1.id_periode = t2.id_periode
         		where	t2.NUM_ANNEE = @num_annee_precedente
         	END
         
         	-- initialiser l'effectif de l'adh‚rent … blanc pour l'ann‚e en cours (R21)
         	EXEC MAJ_EFFECTIF_ANNEE @num_annee
         
         
         	-- Initialisation des enveloppes 2016 pour types d'enveloppe actifs
         	--EXEC MAJ_ENVELOPPES @num_annee
         	-- Effectue en 2016 par un batch specifique
         
         
         	-- mise … jour des op‚rations financiŠres (OPERATION_FINANCIERE)
         	-- Cette proc‚dure ne cr‚e pas les op‚rations financiŠres action co et triennal sauf MULTIBR
         	EXEC MAJ_OPERATIONS_FINANCIERES @num_annee
         
         
         	--**************************************************************
         	--* Initialisation des options groupes pour l'ann‚e en cours   *
         	--* Les options sont initialis‚es sur la valeur "Pas d'option" *
         	--**************************************************************
         
         	declare @id_option	int
         
         	-- r‚cup‚ration ann‚e en cours
         	select	@id_periode = id_periode
         	from	periode 
         	where	id_type_periode = 1
         	and		num_annee = @num_annee
         
         	-- r‚cup‚ration de l'option
         	select	@id_option = id_option
         	from	options
         	where	cod_option = 'NON'
         
         	insert into r20bis
         	(ID_GROUPE, ID_PERIODE, ID_OPTION, PRC_OPTION, PRC_FRAIS_GESTION)
         	select	distinct t1.id_groupe, @id_periode, @id_option, 0, 0
         	from	etablissement t1
         	join	groupe t2
         	on		t1.id_groupe = t2.id_groupe
         	where	t1.bln_actif = 1
         	and		t2.bln_actif = 1
         	and		not exists (select 1 from r20bis where id_groupe = t1.id_groupe and id_periode = @id_periode)
         
         
         
         	-- R‚cup‚ration des objets d‚pendants des tables impact‚es par les traitements annuels
         	-- Tables concern‚es: OPERATION_FINANCIERE, PARAMETRE_GLOBAL, PARAMETRE_APPEL, R20, ENVELOPPE
         	-- Recompilation de toutes les proc‚dures stock‚es autres que celles d'insertion et mise … jour, les vues, les fonctions
         	declare @objet varchar(100), @commande_sql varchar(2000), @res int
         
         	declare recompile_curseur cursor for
         	SELECT	distinct object_name(object_id)
         	FROM	sys.sql_dependencies 
         	WHERE	referenced_major_id in (OBJECT_ID('OPERATION_FINANCIERE'), OBJECT_ID('PARAMETRE_GLOBAL'), OBJECT_ID('PARAMETRE_APPEL'), OBJECT_ID('R20'), OBJECT_ID('ENVELOPPE'))
         	AND		object_name(object_id) not like 'INS%'
         	AND		object_name(object_id) not like 'UPD%'
         
         	open recompile_curseur
         	fetch next from recompile_curseur into @objet
         	while @@fetch_status = 0
         	BEGIN
         		set @commande_sql = 'sp_recompile ' + @objet
         		EXEC (@commande_sql)
         		if @res <> 0 print 'echec recompilation ' + @objet
         		fetch next from recompile_curseur into @objet
         	END
         
         	close recompile_curseur
         	deallocate recompile_curseur
         
         	--********************************************************************
         	--* MISE A JOUR DES EXERCICES MODULE								 *
         	--********************************************************************
         	-- A ADAPTER SELON LES BESOINS CHAQUE ANNEE EN FONCTION DU DELAI DE SAISIE
         	-- ATTENTTION, DATE_FIN n'est pas inclu dans l'intervalle des dates autoris‚es
         	TRUNCATE TABLE [PARAMETRE_EXERCICE_MODULE]
         	INSERT INTO [PARAMETRE_EXERCICE_MODULE]
         			   ([DAT_DEBUT]
         			   ,[DAT_FIN]
         			   ,[NUM_VALEUR])
         		 VALUES
         			   ('20160101'
         			   ,'20160131'				-- saisie modules PEC 2015 pour l'ann‚e 2016 jusqu'au 31 janvier 2016
         			   ,'-1')
         
         
         	-- mise … jour taux SMIC
         	declare @id_periode_smic int
         
         	update	PERIODE 
         	set		BLN_EN_COURS = 0,
         			DAT_FIN_PERIODE = CONVERT(datetime, '31-12-2015 23:59:59')
         	where	ID_TYPE_PERIODE = 4
         	and		NUM_ANNEE = 2015
         
         	if not exists (select * from periode where id_type_periode = 4 and NUM_ANNEE = 2016)
         	BEGIN
         		insert into periode
         		(ID_TYPE_PERIODE, COD_PERIODE, NUM_ANNEE, DAT_DEB_PERIODE, DAT_FIN_PERIODE, BLN_ACTIF, BLN_EN_COURS, DAT_CREATION, ID_UTILISATEUR, BLN_PRIORITAIRE)
         		SELECT
         		ID_TYPE_PERIODE		= 4, 
         		COD_PERIODE			= '2016', 
         		NUM_ANNEE			= 2016, 
         		DAT_DEB_PERIODE		= CONVERT(datetime, '01-01-2016 00:00:00'), 
         		DAT_FIN_PERIODE		= CONVERT(datetime, '31-12-9999 00:00:00'), 
         		BLN_ACTIF			= 1, 
         		BLN_EN_COURS		= 1, 
         		DAT_CREATION		= getdate(),
         		ID_UTILISATEUR		= 82,
         		BLN_PRIORITAIRE		= 1 
         
         
         	END
         	select	@id_periode_smic = id_periode
         	from	PERIODE
         	where	ID_TYPE_PERIODE = 4
         	and		NUM_ANNEE		= 2016
         	AND		BLN_EN_COURS	= 1
         	if not exists (select 1 from tau_smic where id_periode = @id_periode_smic)
         	BEGIN
         		insert into TAU_SMIC
         		(ID_PERIODE, MNT_SMIC_HORAIRE_BRUT)
         		values
         		(@id_periode_smic, 9.67)
         	END
         
         	-- mise … jour champ PERIODE.BLN_FINANCEMENT_DISPO pour l'ann‚e trait‚e (utilis‚ pour la redescente d'info dans D3R)
         	update	PERIODE
         	set		BLN_FINANCEMENT_DISPO = 1
         	where	ID_TYPE_PERIODE = 1
         	and		NUM_ANNEE = @num_annee
         
         	-- PARAMETRAGE du calendrier bancaire utilis‚ pour d‚terminer les dates d'ex‚cution des ordres SEPA.
         	EXEC MAJ_CALENDRIER 2016
         
         
         	-- mise … jour de la date de mutualisation au 01/07/N+1 pour les periodes 2014 et au-dela
         	update	PERIODE
         	set		DAT_CONSTITUTION_POT_MUT= CONVERT(DATETIME, '01/07/'+ CAST(NUM_ANNEE+1 AS VARCHAR), 103)
         	where	ID_TYPE_PERIODE = 1
         	and		NUM_ANNEE = 2016
         
         	--commit tran
         	-- rollback tran
         END
GO

         CREATE PROCEDURE [dbo].[UPD_LETTRE_PEC_ENGAGEMENT_OF]
         	@IDS_MODULE_PEC TEXT	-- List of COD_MODULE separated with ',' without spaces - i.e.: 1,2,3,4,5,6
         AS
         
         BEGIN
         
         	--AMA la d‚claration en int pause des problŠme … C2P
         	--DECLARE @Item int;
         	--FIN AMA 
         	DECLARE @Item varchar(50);
         	-- Create a temporary table which contains codes
         	CREATE TABLE #List(Item varchar(50) collate French_CI_AI)
         	
         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,1,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)-1))),
         			@IDS_MODULE_PEC=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)+1,DATALENGTH(@IDS_MODULE_PEC))))
         
         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END
         
         	IF DATALENGTH(@IDS_MODULE_PEC) > 0
         		INSERT INTO #List SELECT @IDS_MODULE_PEC -- Put the last item in
         
         	--Mise … jour des dates de rejet
         	UPDATE MODULE_PEC
         	SET DAT_LETTRE_PEC_ENGAGEMENT_OF = GETDATE()
         	WHERE COD_MODULE_PEC IN (SELECT Item FROM #List)
         END
         
         
         
         
         
         
         
GO

         -- =============================================
         -- Author		: MB
         -- Create date	: 05/05/2008
         -- Description	: Suivi comptable  des engagaments
         -- Ce batch est lance toutes les nuits
         -- ---------------------------------------------
         -- Author		: 
         
         -- Modified date: 
         -- comment		: 
         -- =============================================
         CREATE  PROCEDURE [dbo].[BATCH_INS_SUIVI_COMPTABLE_ENGAGEMENT]
         (@ID_MODULE_PRO integer  = NULL)
         AS 
         
         BEGIN
         DECLARE 
         	@ID_ENGAGEMENT_MODULE_CPTA_PRO	int,
         	@ID_TYPE_ENGAGEMENT_CPTA		int,
         	@DAT_BAE						datetime,
         	@NB_UNITE_TOTALE				float,
         	@NB_UNITE_EVALUATION			float,
         	@NB_UNITE_ACCOMPAGNEMENT		float,
         	@MNT_MODULE_HT					float,
         	@MNT_ATTESTE_HT					float,
         	@DAT_CLOTURE					datetime,
         	@BLN_ACTIF						tinyint,
         	@NUM_CAS						int
         
         CREATE TABLE #TMP01
         (
         	NUM_CAS				int,
         	ID_MODULE_PRO			int, 
         	ID_TYPE_ENGAGEMENT_CPTA	int, 
         	DAT_BAE					datetime, 
         	NB_UNITE_TOTALE			float, 
         	NB_UNITE_EVALUATION		float, 
         	NB_UNITE_ACCOMPAGNEMENT	float, 
         	MNT_MODULE_HT			float
         )
         
         
         /* Traitement de l'engagement comptable des engagements */
         INSERT INTO #TMP01
         SELECT	1, ID_MODULE_PRO, ID_TYPE_ENGAGEMENT_PRO, DAT_BAE, NB_UNITE_TOTALE, NB_UNITE_EVALUATION, NB_UNITE_ACCOMPAGNEMENT, MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (1, 2)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)
         
         /* Traitement de la desactivation d'un module engage */
         INSERT INTO #TMP01
         SELECT	2, ID_MODULE_PRO, 4 , GETDATE(), -NB_UNITE_TOTALE, -NB_UNITE_EVALUATION, -NB_UNITE_ACCOMPAGNEMENT, -MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		BLN_ACTIF = 0
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (4)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)
         
         
         /* Traitement de la cloture d'un module engage */
         INSERT INTO #TMP01
         SELECT	3, ID_MODULE_PRO, 3 , GETDATE(), NB_UNITE_TOTALE, NB_UNITE_EVALUATION, NB_UNITE_ACCOMPAGNEMENT, MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		DAT_CLOTURE IS NOT NULL
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (3)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)
         
         /* Traitement de la cloture d'un contrat */
         INSERT INTO #TMP01
         SELECT	4, MODULE_PRO.ID_MODULE_PRO, 5 , GETDATE(), MODULE_PRO.NB_UNITE_TOTALE, MODULE_PRO.NB_UNITE_EVALUATION, MODULE_PRO.NB_UNITE_ACCOMPAGNEMENT, MODULE_PRO.MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO, CONTRAT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		MODULE_PRO .ID_CONTRAT_PRO = CONTRAT_PRO .ID_CONTRAT_PRO 
         AND		MODULE_PRO.DAT_CLOTURE IS NULL
         AND		CONTRAT_PRO.DAT_CLOTURE IS NOT NULL
         AND		MODULE_PRO.BLN_ACTIF = 1
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (5)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)
         
         
         DECLARE cu_engagement_module CURSOR FOR
         SELECT	NUM_CAS,
         		ID_MODULE_PRO			, 
         		ID_TYPE_ENGAGEMENT_CPTA	, 
         		DAT_BAE					, 
         		NB_UNITE_TOTALE			, 
         		NB_UNITE_EVALUATION		, 
         		NB_UNITE_ACCOMPAGNEMENT	, 
         		MNT_MODULE_HT			
         FROM #TMP01
         ORDER BY NUM_CAS
         
         OPEN cu_engagement_module 
         
         FETCH cu_engagement_module 
         INTO @NUM_CAS, @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, @DAT_BAE, @NB_UNITE_TOTALE, @NB_UNITE_EVALUATION, @NB_UNITE_ACCOMPAGNEMENT, @MNT_MODULE_HT
         
         WHILE (@@fetch_status <> -1)
         BEGIN
         --SELECT @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, @DAT_BAE, @NB_UNITE_TOTALE, @NB_UNITE_EVALUATION, @NB_UNITE_ACCOMPAGNEMENT, @MNT_MODULE_HT
         
         
         	IF @NUM_CAS = 3
         	-- Cas de la cloture d'un module
         	BEGIN
         		-- Recherche de l'engagement initial
         		SELECT	
         		@NB_UNITE_TOTALE			= -(@NB_UNITE_TOTALE			- NB_UNITE_TOTALE			)	, 
         		@NB_UNITE_ACCOMPAGNEMENT	= -(@NB_UNITE_ACCOMPAGNEMENT	- NB_UNITE_ACCOMPAGNEMENT	)	, 
         		@NB_UNITE_EVALUATION		= -(@NB_UNITE_EVALUATION		- NB_UNITE_EVALUATION		)	, 
         		@MNT_MODULE_HT				= -(@MNT_MODULE_HT				- MONTANT_ENGAGE			)	
         		FROM	ENGAGEMENT_MODULE_CPTA_PRO
         		WHERE	ID_MODULE_PRO = @ID_MODULE_PRO
         		AND		ID_TYPE_ENGAGEMENT_CPTA IN (1, 2)
         
         	END
         
         	IF @NUM_CAS = 4
         	-- Cas de la cloture d'un contrat
         	BEGIN
         
         		-- Calcul du montant regle sur le module
         		SELECT	@MNT_ATTESTE_HT	= ISNULL(SUM(MNT_ATTESTE_HT), 0)
         		FROM	SESSION_PRO
         		WHERE	ID_MODULE_PRO	= @ID_MODULE_PRO
         
         		-- Recherche de l'engagement initial
         		SELECT	
         		@NB_UNITE_TOTALE			= 0	, 
         		@NB_UNITE_ACCOMPAGNEMENT	= 0	, 
         		@NB_UNITE_EVALUATION		= 0	, 
         		@MNT_MODULE_HT				= -(@MNT_MODULE_HT				- @MNT_ATTESTE_HT)	
         
         --		SELECT	'CAS4 CLOTURE CONTRAT ',	@NB_UNITE_TOTALE, @NB_UNITE_ACCOMPAGNEMENT	, @NB_UNITE_EVALUATION		, 		MNT_ATTESTE = @MNT_ATTESTE_HT, RELIQUAT = @MNT_MODULE_HT				
         
         	END
         
         	IF @NB_UNITE_TOTALE +@NB_UNITE_ACCOMPAGNEMENT+ @NB_UNITE_EVALUATION	+ @MNT_MODULE_HT <> 0
         	BEGIN
         
         		INSERT INTO ENGAGEMENT_MODULE_CPTA_PRO
         		(	
         			COD_ENGAGEMENT_MODULE_CPTA_PRO, ID_MODULE_PRO, ID_TYPE_ENGAGEMENT_CPTA,
         			NB_UNITE_TOTALE, NB_UNITE_ACCOMPAGNEMENT, NB_UNITE_EVALUATION, MONTANT_ENGAGE,
         			BLN_ACTIF, DAT_CREATION 
         		)
         		VALUES
         		(	
         			99 , @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, 
         			@NB_UNITE_TOTALE, @NB_UNITE_ACCOMPAGNEMENT, @NB_UNITE_EVALUATION, @MNT_MODULE_HT,
         			1, @DAT_BAE 
         		)
         		SET @ID_ENGAGEMENT_MODULE_CPTA_PRO = @@identity
         
         		UPDATE	ENGAGEMENT_MODULE_CPTA_PRO  
         		SET		COD_ENGAGEMENT_MODULE_CPTA_PRO = @ID_ENGAGEMENT_MODULE_CPTA_PRO 
         		WHERE	ID_ENGAGEMENT_MODULE_CPTA_PRO = @ID_ENGAGEMENT_MODULE_CPTA_PRO
         
         		EXEC BATCH_INS_SUIVI_COMPTABLE_ENGAGEMENT_PERIODE @ID_ENGAGEMENT_MODULE_CPTA_PRO 
         	END
         
         	FETCH cu_engagement_module 
         	INTO @NUM_CAS, @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, @DAT_BAE, @NB_UNITE_TOTALE, @NB_UNITE_EVALUATION, @NB_UNITE_ACCOMPAGNEMENT, @MNT_MODULE_HT
         
         END
         
         CLOSE cu_engagement_module 
         DEALLOCATE cu_engagement_module 
         
         
         END
GO
CREATE PROCEDURE [dbo].[MVT_BUDGETAIRE_COLLECTE_GENERATION]  
         /* *****************************************************************************************
         -- Auteur   : MBL
         -- Date Creation : 11/12/2014
         
         -- Role    : 
           Procedure generique de g‚n‚ration des mouvements budgetaires associes a un evenement de collecte
           Cette PS permet de declencher la generation des differents mouvements budgetaires associes a un type d'evenement
           pour les differents types de mouvement a generer.
         ***************************************************************************************** */
          @ID_EVENEMENT  INT
         AS
         DECLARE 
          @COD_TYPE_EVENEMENT varchar(8) ,
          @ID_TYPE_MOUVEMENT int   ,
          @P_E_R    varchar(1) ,
          @LIB_PB_EVENEMENT varchar(100)
         
         BEGIN
          
          IF EXISTS (SELECT 1 FROM MVT_BUDGETAIRE WHERE ID_EVENEMENT = @ID_EVENEMENT)
          BEGIN
           SELECT  'Pb : Mvt Budgetaires deja generes pour cet evenement ', *
           FROM EVENEMENT
           WHERE ID_EVENEMENT = @ID_EVENEMENT  
         
           SET @LIB_PB_EVENEMENT = 'D‚tection tentative de generation de Mvt Budgetaires deja generes pour cet versement'
         
           INSERT INTO PB_EVENEMENT_MVT_BUDGETAIRE_COLLECTE
           (
           ID_EVENEMENT   ,
           LIB_PB_EVENEMENT  , 
           LIBL_EVENEMENT   , 
           DAT_EVENEMENT   , 
           ID_TYPE_EVENEMENT  , 
           ID_VERSEMENT   ,
           COM_EVENEMENT   
           )
           SELECT
            ID_EVENEMENT   ,
            LIB_PB_EVENEMENT  = @LIB_PB_EVENEMENT,
            LIBL_EVENEMENT   , 
            DAT_EVENEMENT   , 
            ID_TYPE_EVENEMENT  , 
            ID_VERSEMENT   ,
            COM_EVENEMENT   = 'Batch Reg‚n‚ration MVT BUDGETAIRE (PS [MVT_BUDGETAIRE_COLLECTE_GENERATION]) : D‚tection tentative de g‚n‚ration de Mvt Budgetaires deja g‚n‚r‚s pour ce versement'
           FROM EVENEMENT
           WHERE ID_EVENEMENT = @ID_EVENEMENT 
           
          END
          ELSE
          BEGIN
          
          
           SELECT @COD_TYPE_EVENEMENT = TYPE_EVENEMENT .COD_TYPE_EVENEMENT 
           FROM EVENEMENT 
           INNER JOIN TYPE_EVENEMENT ON TYPE_EVENEMENT.ID_TYPE_EVENEMENT = EVENEMENT.ID_TYPE_EVENEMENT 
           WHERE ID_EVENEMENT = @ID_EVENEMENT
         
           --SELECT ' Traitement Evenement ', ID_EVENEMENT = @ID_EVENEMENT , COD_TYPE_EVENEMENT  = @COD_TYPE_EVENEMENT
         
           IF @COD_TYPE_EVENEMENT IN ( 'VERSEMEN', 'REGUL', 'REVERSE')
           BEGIN
            -- Generation des Mouvements Budgetaires d'alimentation de l'enveloppe de collecte
            EXEC MVT_BUDGETAIRE_COLLECTE_ALIM_ENVELOPPE_COLLECTE @ID_EVENEMENT
            
            -- Generation des Mouvements Budgetaires d'abondement du compte
            EXEC MVT_BUDGETAIRE_COLLECTE_ABONDEMENT_COMPTE @ID_EVENEMENT
           
           END
         
           IF @COD_TYPE_EVENEMENT IN ( 'IMPAYE')
           BEGIN
            -- Generation des Mouvements Budgetaires d'alimentation des Impayes
            EXEC MVT_BUDGETAIRE_COLLECTE_IMPAYE @ID_EVENEMENT
           END
         
          END
         END
GO

         CREATE PROCEDURE [dbo].[LEC_PRE_BON_A_PAYER]
         
         -- =============================================    
         -- Author   : XX    
         -- Modified date : XX XXXX 2007    
         -- Description  : Cr‚ation    
         -- =============================================    
         -- Author   : SV    
         -- Modified date : 28 ao–t 2007    
         -- Description  : Inversion des requˆtes qui mettent le champ ID_TYPE_VALIDATION … null et … 8    
         -- =============================================    
         -- Author   : KS    
         -- Modified date : 01 sept 2007    
         -- Description  : remise … jour des rŠgles de gestion    
         -- Modified date : 02 sept 2007    
         -- Description  : remise … jour des rŠgles de gestion : IBAN MaJ aprŠs correction de l'utilisateur    
         -- =============================================    
         -- Author   : KS    
         -- Modified date : 03 sept 2007    
         -- Description  : nouveaux dossier … contr“ler : filtrage ajouter sur POSTE_COUT_REGLE.ID_ETAT_PEC = 3    
         -- =============================================    
         -- Author   : SV    
         -- Modified date : 16 octobre 2007    
         -- Description  : Ajout d'un filtre sur l'‚tat des piŠces du module pour d‚finir si le P.C.R. est bapable ou non    
         -- =============================================    
         -- Author   : DCH    
         -- Modified date : 16 octobre 2007    
         -- Description  : R‚organisation des filtres    
         -- =============================================    
         -- Author   : KS    
         -- Modified date : 23 octobre 2007    
         -- Description  : nouvel OF : filtrage sur POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1    
         -- =============================================    
         -- Author   : DCH    
         -- Modified date : 23 octobre 2007    
         -- Description  : nouvel OF : filtrage sur POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL AND (POSTE_COUT_REGLE.ID_ETAT_PEC = 3 or POSTE_COUT_REGLE.ID_ETAT_PEC = 1)    
         --                    IBAN manquant : d‚placement du contr“le de l'IBAN manquant dans la clause WHERE    
         --                    rajout du contr“le IBAN diff‚rent de ''    
         -- =============================================    
         -- Author   : DCH    
         -- Modified date : 26 octobre 2007    
         -- Description  : Ajout d'un filtre sur les postes de cout r‚gl‚ dont le mnt est diff‚rent de la somme des mnt des plans de financement    
         -- =============================================    
         -- Author   : SV    
         -- Modified date : 29 octobre 2007    
         -- Description  : Modification du filtre sur la somme des plans de financement pour prendre en compte les valeurs nulles    
         -- =============================================    
         -- Author   : MB    
         -- Modified date : 30 octobre 2007    
         -- Description  : Modification du filtre sur la somme des plans de financement pour prendre en compte les valeurs nulles (requete modifiee)    
         -- Description  : Il faut filtrer sur l'agence et pas sur l'utilisateur connecte    
         -- =============================================    
         -- Author   : KS    
         -- Modified date : 06 novembre 2007    
         -- Description  : EVOLUTION >> ajout d'un nouvel ‚l‚ment de critŠre pour les nouveaux dossiers : BLN_OK_FINANCEMENT is null    
         -- =============================================    
         -- Author   : DCH    
         -- Modified date : 22 novembre 2007    
         -- Description  : EVOLUTION >> ajout d'un filtre sur les postes de cout r‚gl‚s dont l'‚tablissement destinataire (OF ou adh‚rent selon le cas) de la transaction associ‚e n'est pas celui qui est lui rattach‚    
         --                                 suppression du contr“le des valeurs 1 ou 3 pour l'‚tat    
         -- =============================================    
         -- Author   : DCH    
         -- Modified date : 30 novembre 2007    
         -- Description  : EVOLUTION >> ajout d'un filtre sur les transactions inactives    
         -- =============================================    
         -- Author   : MBE    
         -- Modified date : 29 MAI 2008    
         -- Description  : Il faut filtrer sur l'utilisateur et pas sur l'agence    
         -- =============================================    
         -- Author   : ASD    
         -- Modified date : 2009/02/25    
         -- Description  : Evol 353 :  en cas issu de la reprise, ne pas contr“ler que l'OF de la DR est identique     
         --         … l'OF de la transaction de la DR    
         -- =============================================    
         -- Author   : ASD    
         -- Modified date : 2009/03/19    
         -- Description  : Modification du critŠre id_utilisateur (old: ACTION_PEC, new: POSTE_COUT_REGLE)    
         -- =============================================    
         -- Author   : MB    
         -- Modified date : 2009/10/19    
         -- Description  : Les DR avec desynchronisation de TVA sont bloque au niveau des BAP    
         -- =============================================    
         -- Author   : MB    
         -- Modified date : 2010/05/21    
         -- Description  : Les DR dont le financement est "interdit" sont bloquees au niveau des BAP
         -- =============================================    
         -- Author   : DSZ   
         -- Modified date : 2011/01/14
         -- Description  : EVOL 12378 voir C2P_SFD_PEC_BAP_2.17 du 04/01/2011
         -- =============================================    
         -- Author   : DSZ   
         -- Modified date : 2011/09/05
         -- Description  : EVOL 12839 voir C2P_SFD_PEC_BAP_2.19 du 05/09/2011
         -- =============================================    
         -- DSZ 14/09/2012 13642
         -- ajout traitement des DR dont la facture n'a pas de type TVA (nouveau type etat pec TVAMQ)
         -- perf: suppression des inner joins inutiles, suppression  des tables temporaires
         -- =============================================    
         -- BBL 14/01/2013
         -- Accepte les etablissements Of de la table repise_NESSIE
         -- =============================================    
         -- ASD 18/01/2013 corrig‚ le 29/01/2013
         -- Accepte les factures d'etablissements Of du mˆme OF que l'‚tablissement OF du module
         -- Accepte les factures d'‚tablissement du mˆme adh‚rent que l'‚tablissement du PCR
         -- =============================================    
         -- ASD 05/06/2013
         -- 15274 Accepte les OF ou ADHs inactifs lorsque ce sont ceux du PCR.
         -- =============================================    
         -- SBR 11/12/13
         -- Correction apport‚e sur 15274 non conforme: permet de payer un OF inactif si ‚tablissement OF PCR = ‚tablissement OF module
         -- Demand‚: permettre de payer un OF inactif mˆme si ‚tablissement OF PCR <> ‚tablissement OF module
         -- =============================================  
         -- HBO - 241213 - #16641: SBR - SEPA ano contr“le BAP PEC
         -- =============================================    
         -- DSZ - 05/05/2014 ajout return sinon timeout dans le code C#
         -- =============================================
         -- LDE 30/05/2014 #351
         -- =============================================
         -- Author		: MB
         -- Modif. date  : 13/08/2015
         -- Description  : Remise en place de l'interdiction de BAPE une DR en attente de pieces
         -- =======================================================================================================================================
         -- Author		: MB
         -- Modif. date  : 30/12/2015
         -- Description  : Mise en place Interdiction de BAPer des DR associ‚es … des Sessions 2016 (et post‚rieures) mobilisant des heures de DIF
         -- =======================================================================================================================================
         
         @ID_UTILISATEUR  INT
         AS
         BEGIN
         	-- Ceux qui sont B…Pables, mais qui ne l'‚taient pas jusqu'alors ETAT_PEC = 1    
         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = NULL
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         		AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION = 8
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	-- Ceux qui sont B…Pables, mais qui ne l'‚taient pas jusqu'alors ETAT_PEC = 3    
         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION = 8
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	-- Les nouveaux dossiers    
         	-- Pour ceux dont la somme des plans de financement n'est pas ‚gale au poste de co–t r‚gl‚  ----------------------------------------------------------------------------------    
         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 4,
         		BLN_OK_FINANCEMENT = 0
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND (
         			 abs(round(POSTE_COUT_REGLE.MNT_REGLE_HT - (SELECT
         															isnull(sum (MNT_PLAN_FINANCEMENT_US), 0)
         														FROM PLAN_FINANCEMENT_US
         														WHERE ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE), 2))>= 0.01
         		OR BLN_OK_FINANCEMENT IS NULL
         		)
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 11,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND abs(round(POSTE_COUT_REGLE.MNT_REGLE_TVA - (SELECT
         														isnull(sum (MNT_PLAN_FINANCEMENT_US_TVA), 0)
         													FROM PLAN_FINANCEMENT_US
         													WHERE ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE), 2))>= 0.01
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	--ceux dont la facture n'a pas du type TVA (suite … l'‚vol prefacture)
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = (SELECT
         						   ID_ETAT_PEC
         					   FROM ETAT_PEC
         					   WHERE COD_ETAT_PEC ='TVAMQ'),
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN FACTURE F
         			ON F.ID_FACTURE = POSTE_COUT_REGLE.ID_FACTURE
         	WHERE
         		F.ID_TYPE_TVA IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 11,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND abs(round(POSTE_COUT_REGLE.MNT_REGLE_TTC - (POSTE_COUT_REGLE.MNT_REGLE_HT + POSTE_COUT_REGLE.MNT_REGLE_TVA), 2))>= 0.01
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 12,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN F_C2P_AUDIT_FINANCEMENTREGLEMENTNONAUTORISE() A ON A.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	-- Les nouveaux dossiers    
         	-- Pour ceux qui ne sont pas B…Pables  ----------------------------------------------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 2
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 4
         	  -- LDE 30/05/2014 #351
         	  /*OR POSTE_COUT_REGLE.BLN_OK_PIECE = 0
         	  OR MODULE_PEC.BLN_OK_PIECE = 0*/
         	  -- /LDE 30/05/2014 #351
         -- Author		: MB
         -- Modif. date  : 13/08/2015
         -- Description  : Remise en place de l'interdiction de BAPE une DR en attente de pieces	  
         -- Rajout des 2 ligne suivante supprimees lors de l'US 351
         	  OR POSTE_COUT_REGLE.BLN_OK_PIECE = 0
         	  OR MODULE_PEC.BLN_OK_PIECE = 0
         	  )
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	-- BaPable sans transaction ou sans IBAN ----------------------------------------------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.ID_TRANSACTION IS NULL
         	
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	FROM
         		POSTE_COUT_REGLE
         		INNER JOIN [TRANSACTION]
         			ON	[TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         				AND [TRANSACTION].BLN_ACTIF = 1 --ajout DSZ 12839
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		AND
         		(
         			ISNULL(NULLIF([TRANSACTION].NUM_IBAN, ''),null)IS NULL 
         			OR ISNULL(NULLIF([TRANSACTION].BIC, ''),null)IS NULL
         		)
         	
         	-- BaPable avec un ‚tablissement destinataire de la transaction diff‚rent de celui rattach‚ au poste de cout r‚gl‚----------------------------------------------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 10
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC  ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		 INNER JOIN ACTION_PEC  ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION -- 2013/01/14 BBL donn‚e de reprise
         		 LEFT  JOIN REPRISE_MODULE_NESSIE	ON
         												REPRISE_MODULE_NESSIE.ID_ETABLISSEMENT_OF = [TRANSACTION].ID_ETABLISSEMENT_OF_DEST
         											AND REPRISE_MODULE_NESSIE.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	-- 2013/01/14 BBL donn‚e de reprise
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 0
         	AND [TRANSACTION].ID_ETABLISSEMENT_DEST NOT IN (SELECT
         														A.ID_ETABLISSEMENT
         													FROM
         														ETABLISSEMENT A
         														INNER JOIN ETABLISSEMENT B ON B.ID_ADHERENT=A.ID_ADHERENT
         													WHERE
         														  B.ID_ETABLISSEMENT =POSTE_COUT_REGLE.ID_ETABLISSEMENT
         													  AND (
         														  A.BLN_ACTIF=1
         													   OR A.ID_ETABLISSEMENT =B.ID_ETABLISSEMENT) --15274
         		)
         	 OR
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND [TRANSACTION].ID_ETABLISSEMENT_OF_DEST NOT IN (SELECT
         														   AOF.ID_ETABLISSEMENT_OF
         													   FROM
         														   ETABLISSEMENT_OF AOF
         														   INNER JOIN ETABLISSEMENT_OF BOF ON BOF.ID_OF=AOF.ID_OF
         													   WHERE
         															 BOF.ID_ETABLISSEMENT_OF =MODULE_PEC.ID_ETABLISSEMENT_OF
         														 AND (
         															 AOF.BLN_ACTIF=1
         														  OR AOF.ID_ETABLISSEMENT_OF =BOF.ID_ETABLISSEMENT_OF) --15274
         		)
         	AND coalesce(ACTION_PEC.BLN_REPRISE_ADHOC, 0) = 0
         		-- 2013/01/14 BBL donn‚e de reprise
         	AND ( 
         		 ACTION_PEC.BLN_REPRISE_NESSIE = 1
         	 AND REPRISE_MODULE_NESSIE.ID_ACTION_PEC IS NULL
         	  OR ACTION_PEC.BLN_REPRISE_NESSIE = 0
         		)
         	-- BaPable avec une transaction inactive----------------------------------------------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 10
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC  ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND [TRANSACTION].BLN_ACTIF = 0
         	-- Pour ceux qui sont ® A contr“ler¯    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	 AND POSTE_COUT_REGLE.BLN_A_CONTROLER = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	-- s'il y a un changement de destinataire du rŠglement    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 7
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND [TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 0
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	
         	-- s'il y a eu un changement d'IBAN du destinataire    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND (
         		dateadd(MM, 3, [TRANSACTION].DAT_CREATION) >= getdate()
         	 OR dateadd(MM, 3, [TRANSACTION].DAT_MODIF) >= getdate() );
         	-- Si l'OF est nouveau    
         	WITH PCR_OF_NOUVEAU
         		AS (
         		SELECT
         			POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC=POSTE_COUT_REGLE.ID_MODULE_PEC
         			INNER JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF=MODULE_PEC.ID_ETABLISSEMENT_OF
         			INNER JOIN ORGANISME_FORMATION ON
         											  ORGANISME_FORMATION.ID_OF=ETABLISSEMENT_OF.ID_OF
         										  AND dateadd(MM, 3, ORGANISME_FORMATION.DAT_CREATION)>=getdate()
         		WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		UNION
         		SELECT
         			POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC=POSTE_COUT_REGLE.ID_MODULE_PEC
         			INNER JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF=MODULE_PEC.ID_ETABLISSEMENT_OF
         			INNER JOIN ORGANISME_FORMATION ON
         											  ORGANISME_FORMATION.ID_OF=ETABLISSEMENT_OF.ID_OF
         										  AND (
         			SELECT
         				count(DISTINCT PCR.ID_POSTE_COUT_REGLE)
         			FROM
         				POSTE_COUT_REGLE PCR
         				INNER JOIN MODULE_PEC MP ON MP.ID_MODULE_PEC=PCR.ID_MODULE_PEC
         				INNER JOIN ETABLISSEMENT_OF EOF ON EOF.ID_ETABLISSEMENT_OF=MP.ID_ETABLISSEMENT_OF
         				INNER JOIN ORGANISME_FORMATION ORF ON
         													  ORF.ID_OF=EOF.ID_OF
         												  AND ORF.ID_OF=ORGANISME_FORMATION.ID_OF
         				INNER JOIN REGLEMENT ON
         										PCR.ID_REGLEMENT IS NOT NULL
         									AND REGLEMENT.ID_REGLEMENT=PCR.ID_REGLEMENT
         									AND REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL)<10
         		WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		)
         		UPDATE     POSTE_COUT_REGLE
         		SET
         			ID_TYPE_VALIDATION = 4,
         			ID_ETAT_PEC = 9
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN PCR_OF_NOUVEAU
         				ON PCR_OF_NOUVEAU.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         	
         	-- Pour ceux qui ne sont pas B…Pables mais ayant un IBAN aprŠs correction  ----------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON
         									[TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         								AND [TRANSACTION].BLN_ACTIF = 1 --ajout DSZ 12839							
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND ID_TYPE_VALIDATION = 8
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND ISNULL(NULLIF([TRANSACTION].NUM_IBAN, ''),null)IS NOT NULL
         	AND ISNULL(NULLIF([TRANSACTION].BIC, ''),null)IS NOT NULL
         
         	--Pas B…Pables car avaient un ETAT_PEC … 13  
         	--et qui depuis ont vu leur module r‚engag‚ 
         	--(mˆme sous type de co–t et mˆme module) 
         	--et pour lesquelles la valeur de POSTE_COUT_REGLE. ID_TYPE_VALIDATION ‚tait donc 
         	--jusqu'… pr‚sent positionn‚e … 8 = ® Non B…Pable ¯, 
         	--que l'on positionnera alors … 4 pour les contr“ler 
         	--et on mettra leur ETAT_PEC … la valeur 1 (OK RŠglement).
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 1
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN DBO.POSTE_COUT_ENGAGE
         	ON
         	  POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
           AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	WHERE
         		ID_TYPE_VALIDATION = 8
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 13
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.DAT_BAP IS NULL
         	AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL
         	AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
         	
         	--Bapable (ID_ETAT_PEC = 1), on v‚rifie que le pce de mˆme module et sous type de co–t 
         	--est bien engag‚ (Attention ce n'est pas forc‚ment l'ID_POSTE_COUT_ENGAGE associ‚ au PCR). 
         	--Si ce n'est pas le cas, on positionne l'ETAT_PEC … la valeur 13  (Module d‚sengag‚) 
         	--et le type de validation … 8 (Non B…Pable). 
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 13
         	WHERE
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.DAT_BAP IS NULL
         	AND NOT EXISTS
         		(SELECT
         			 POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
         		 FROM POSTE_COUT_ENGAGE
         		 WHERE
         				POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
         			AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         			AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL
         			AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL)
         	-- end DSZ 12378
         
         
         	/* *******************************************************************************
         	MB Ajout du 30/12/2015 : Mise en place Interdiction de BAPer des DR associ‚es  :
         		- … des Sessions 2016 (et post‚rieures) 
         		- … des Sessions mobilisant des heures de DIF :  ('DIFPRIO', 'DIFPORT', 'PLPPDIF')
         	******************************************************************************* */
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION	= 8	,	-- Non B…Pable
         		ID_ETAT_PEC			= 12,	-- Financement interdit
         		BLN_OK_FINANCEMENT	= 0
         	FROM POSTE_COUT_REGLE
         	INNER JOIN SESSION_PEC		ON SESSION_PEC.ID_SESSION_PEC		= POSTE_COUT_REGLE.ID_SESSION_PEC
         	INNER JOIN STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_SESSION_PEC		= POSTE_COUT_REGLE.ID_SESSION_PEC
         	INNER JOIN UNITE_STAGIAIRE	ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC	= STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         	INNER JOIN DISPOSITIF		ON UNITE_STAGIAIRE .ID_DISPOSITIF	= DISPOSITIF.ID_DISPOSITIF 
         	WHERE 
         	(
         		-- Session PEC mobilisant des heures de DIF
         		COD_DISPOSITIF IN ('DIFPRIO', 'DIFPORT', 'PLPPDIF')
         		AND 
         		UNITE_STAGIAIRE .NB_HEURE_REGLE > 0
         	)
         	AND 
         	(	-- Sessions 2016 (et post‚rieures)
         		YEAR(SESSION_PEC.DAT_DEBUT) >= 2016  
         	)
         	AND POSTE_COUT_REGLE.DAT_BAP		IS NULL
         	AND POSTE_COUT_REGLE.ID_SESSION		IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         
         
         
         
         	-- Default value  --------------------------------------------------------------------------------------------------------    
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 1
         	FROM POSTE_COUT_REGLE
         	WHERE
         		ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	return 0
         END
         
         
GO
-- =============================================
         -- Author		: XXX
         -- Date			: 14/01/09
         -- Description	: This generates a random password, defaulting to 5 characters
         -- =============================================
         CREATE PROCEDURE dbo.GetPass
         	@passlen int = 5, 
         	@charset int = 2, -- 2 is alphanumeric + special characters, 1 is alphanumeric, 0 is alphabetical only
         	@password varchar(8000) output
         AS
         BEGIN
         	set nocount on
         	if (@passlen > 8000 or @passlen < 1)
         	 select @passlen = 10
         
         	declare @string varchar(256), @numbers varchar(10), @extra varchar(50),
         	 @stringlen int, @index int
         
         	-- no 1, l, I, 0, O which can cause confusion
         	select @string = 'ABCDEFGHJKLMNPQRSTUVWXYZ' -- same as @charset = 0
         	select @numbers = '23456789'
         	select @extra = '">_!@#$%&=?<>' -- add more special characters if you want
         
         
         	if @charset = 2
         	 select @string = @string + @numbers + @extra
         	else if @charset = 1
         	 select @string = @string + @numbers
         	-- else assume @extra is 0 and @string is just letters. Feel free to modify these criteria as you see fit
         
         	select @stringlen = len(@string)
         
         	select @password = ''
         
         	while (@passlen > 0)
         	begin
         	 -- For the random part here, use rand() or newid()
         	 select @index = (abs(checksum(newid())) % @stringlen) + 1
         	 select @password = @password + substring(@string, @index, 1)
         	 select @passlen = @passlen - 1
         	end
         
         END
GO
 CREATE PROCEDURE [dbo].[EDIT_ETAT_CONTROLE_DE_SAISIE_COLLECTE]
          @IDS_BORDEREAU VARCHAR(500) -- List of ID_BORDEREAU separated with ',' without spaces - i.e.: 1,2,3,4,5,6
          WITH RECOMPILE 
         AS
         --=============================================================
         -- DSZ 28/07/2011
         -- EVOL 10-50 12406
         -- ajout colonnes 10-49 et 50+ 14768
         --=============================================================
         -- EOU 30/01/2013
         -- ajout colonnes DSP 14768
         --=============================================================
         -- DSZ 22/11/2013 16393
         -- montants Plan dor‚navant issus d'une somme Plan + Conv
         --=============================================================
         -- DSZ 08/01/2015 US#614 Remplacement de plan 10+ par "Autre"
         --=============================================================
         BEGIN
          DECLARE
           @LIB_NOM   VARCHAR(35),
           @LIB_PNM   VARCHAR(35),
           @ID_BORDEREAU  INT,
           @COD_BORDEREAU  INT,
           @COD_ADHERENT  INT,
           @LIB_RAISON_SOCIALE VARCHAR(50),
           @ID_POSTE_VERSEMENT INT,
           @ID_VERSEMENT  INT,
           @LIB_BANQUE   VARCHAR(50),
           @NUM_CHEQUE   VARCHAR(10),
           @DAT_SAISIE   DATETIME,
           @ID_PERIODE   INT,
           @TOTAL_HT   FLOAT,
           @GRP_TYPE_VERSEMENT VARCHAR(2),
           @CHQ_CPT   INT,
           @OLD_COD_BORDEREAU INT,
           @OLD_ID_VERSEMENT INT
          
          SET @OLD_COD_BORDEREAU = 0
          SET @OLD_ID_VERSEMENT = 0
          SET @CHQ_CPT = 0
          
          CREATE TABLE #TMP_DATA
          (
           LIB_NOM    VARCHAR(35),
           LIB_PNM    VARCHAR(35),
           GRP_TYPE_VERSEMENT VARCHAR(2),
           ID_BORDEREAU  INT,
           COD_BORDEREAU  INT,
           COD_ADHERENT  INT,
           LIB_RAISON_SOCIALE VARCHAR(50),
           ID_POSTE_VERSEMENT INT,
           LIB_BANQUE   VARCHAR(50),
           NUM_CHEQUE   VARCHAR(10),
           DAT_SAISIE   DATETIME,
           ID_PERIODE   INT,
           TOTAL_HT   DECIMAL(18,2),
           NUM_CHEQ   INT
          )
          
          -- Create a temporary table which contains IDs
          SELECT
           [DATA] ITEM
          INTO
           #LIST
          FROM
           dbo.F_SPLIT(@IDS_BORDEREAU, ',')
          
          -- Start the selection
          DECLARE CURSOR_DATA CURSOR FOR
          SELECT
           U.LIB_NOM,
           U.LIB_PNM,
           TV.GRP_TYPE_VERSEMENT,
           B.ID_BORDEREAU,
           B.COD_BORDEREAU,
           ADH.COD_ADHERENT,
           ADH.LIB_RAISON_SOCIALE,
           PV.ID_POSTE_VERSEMENT,
           V.ID_VERSEMENT,
           V.LIB_BANQUE,
           V.NUM_CHEQUE,
           V.DAT_SAISIE,
           PV.ID_PERIODE,
           SUM(PIMP.MNT_HT) as TOTAL_HT
          FROM
           BORDEREAU B
           INNER JOIN UTILISATEUR U
            ON B.ID_UTILISATEUR = U.ID_UTILISATEUR
           INNER JOIN VERSEMENT V
            ON V.ID_BORDEREAU = B.ID_BORDEREAU
           INNER JOIN POSTE_VERSEMENT PV
            ON PV.ID_VERSEMENT = V.ID_VERSEMENT
           INNER JOIN TYPE_VERSEMENT TV
            ON PV.ID_TYPE_VERSEMENT = TV.ID_TYPE_VERSEMENT
           INNER JOIN ADHERENT ADH
            ON PV.ID_ADHERENT_BENEFICIAIRE = ADH.ID_ADHERENT
           INNER JOIN POSTE_IMPUTATION PIMP
            ON PIMP.ID_POSTE_VERSEMENT = PV.ID_POSTE_VERSEMENT
           INNER JOIN PERIODE P
            ON P.ID_PERIODE = PV.ID_PERIODE
           INNER JOIN #List
            ON B.ID_BORDEREAU = #List.Item 
          WHERE
           PV.BLN_ACTIF = 1
           AND V.BLN_ACTIF = 1
          GROUP BY
           U.LIB_NOM,
           U.LIB_PNM,
           B.ID_BORDEREAU,
           B.COD_BORDEREAU,
           TV.GRP_TYPE_VERSEMENT,
           ADH.COD_ADHERENT,
           ADH.LIB_RAISON_SOCIALE,
           V.ID_VERSEMENT,
           PV.ID_POSTE_VERSEMENT,
           V.LIB_BANQUE,
           V.NUM_CHEQUE,
           V.DAT_SAISIE,
           PV.ID_PERIODE
          ORDER BY
           V.ID_VERSEMENT,
           PV.ID_POSTE_VERSEMENT,
           ADH.COD_ADHERENT
         
          -- Parcours des activit‚s concern‚es pour trouver le montant d–
          OPEN CURSOR_DATA
          FETCH NEXT FROM CURSOR_DATA
          INTO
           @LIB_NOM,
           @LIB_PNM,
           @GRP_TYPE_VERSEMENT,
           @ID_BORDEREAU,
           @COD_BORDEREAU,
           @COD_ADHERENT,
           @LIB_RAISON_SOCIALE,
           @ID_POSTE_VERSEMENT,
           @ID_VERSEMENT,
           @LIB_BANQUE,
           @NUM_CHEQUE,
           @DAT_SAISIE,
           @ID_PERIODE,
           @TOTAL_HT
         
          WHILE @@FETCH_STATUS = 0
          BEGIN
           IF (@COD_BORDEREAU <> @OLD_COD_BORDEREAU)
           BEGIN
            SET @CHQ_CPT = 0
            SET @OLD_COD_BORDEREAU = @COD_BORDEREAU
           END
           
           IF (@ID_VERSEMENT <> @OLD_ID_VERSEMENT)
           BEGIN
            SET @CHQ_CPT = @CHQ_CPT + 1
           END
           
           INSERT INTO
            #TMP_DATA
           VALUES
           (
            @LIB_NOM,
            @LIB_PNM,
            @GRP_TYPE_VERSEMENT,
            @ID_BORDEREAU,
            @COD_BORDEREAU,
            @COD_ADHERENT,
            @LIB_RAISON_SOCIALE,
            @ID_POSTE_VERSEMENT, 
            @LIB_BANQUE,
            @NUM_CHEQUE,
            @DAT_SAISIE,
            @ID_PERIODE,
            @TOTAL_HT,  
            @CHQ_CPT
           )
           
           FETCH NEXT FROM CURSOR_DATA
           INTO
            @LIB_NOM,
            @LIB_PNM,
            @GRP_TYPE_VERSEMENT,
            @ID_BORDEREAU,
            @COD_BORDEREAU,
            @COD_ADHERENT,
            @LIB_RAISON_SOCIALE,
            @ID_POSTE_VERSEMENT,
            @ID_VERSEMENT,
            @LIB_BANQUE,
            @NUM_CHEQUE,
            @DAT_SAISIE,
            @ID_PERIODE,
            @TOTAL_HT
          END
          CLOSE CURSOR_DATA
          DEALLOCATE CURSOR_DATA
         
          SELECT
           B.ID_BORDEREAU,
           PV.ID_POSTE_VERSEMENT,
           PIMP.ID_POSTE_IMPUTATION, 
           TA.ID_TYPE_ACTIVITE, 
           A.COD_ACTIVITE,  
           TASS.ID_CHAMP_APPLICATION,
           PIMP.MNT_HT, 
           PIMP.MNT_TVA, 
           PIMP.MNT_TTC 
          INTO
           #TEMP
          FROM
           BORDEREAU B
           INNER JOIN #List
            ON B.ID_BORDEREAU = #List.Item
           INNER JOIN VERSEMENT V
            ON V.ID_BORDEREAU = B.ID_BORDEREAU
           INNER JOIN POSTE_VERSEMENT PV
            ON PV.ID_VERSEMENT = V.ID_VERSEMENT
           LEFT OUTER JOIN R20
            ON R20.ID_PERIODE = PV.ID_PERIODE
             AND R20.ID_ADHERENT = PV.ID_ADHERENT_BENEFICIAIRE
           LEFT OUTER JOIN TYPE_ASSUJETISSEMENT TASS
            ON R20.ID_TYPE_ASSUJETISSEMENT = TASS.ID_TYPE_ASSUJETISSEMENT
           INNER JOIN POSTE_IMPUTATION PIMP
            ON PIMP.ID_POSTE_VERSEMENT = PV.ID_POSTE_VERSEMENT
           INNER JOIN ACTIVITE A
            ON PIMP.ID_ACTIVITE = A.ID_ACTIVITE
           INNER JOIN TYPE_ACTIVITE TA
            ON A.ID_TYPE_ACTIVITE =  TA.ID_TYPE_ACTIVITE
          WHERE
           PV.BLN_ACTIF = 1
           AND V.BLN_ACTIF = 1
          ORDER BY
           B.ID_BORDEREAU,
           PV.ID_POSTE_VERSEMENT
          
          /* DSP */ 
          SELECT
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT,
           sum(#TEMP.MNT_HT) AS MNT_HT_DSP,
           sum(#TEMP.MNT_TVA) AS MNT_TVA_DSP,
           sum(#TEMP.MNT_TTC) AS MNT_TTC_DSP
          INTO
           #TEMP_DSP
          FROM
           #TEMP
          WHERE
           #TEMP.COD_ACTIVITE = 'DSP'
          GROUP BY
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT   
         
          /* PRO */
          SELECT
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT,
           sum(#TEMP.MNT_HT) AS MNT_HT_PRO,
           sum(#TEMP.MNT_TVA) AS MNT_TVA_PRO,
           sum(#TEMP.MNT_TTC) AS MNT_TTC_PRO
          INTO
           #TEMP_PRO
          FROM
           #TEMP
          WHERE
           #TEMP.COD_ACTIVITE = 'PRO'
          GROUP BY
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT
         
          /* Colonne - 10  Plan */
          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_MOINS_10_PLAN,
           sum(MNT_TVA) AS MNT_TVA_MOINS_10_PLAN,
           sum(MNT_TTC) AS MNT_TTC_MOINS_10_PLAN
          INTO
           #TEMP_MOINS_10_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE = '-10'
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT
         
          /* Colonne 10-49 PLAN  + Conventionnel */
          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_1049_PLAN,
           sum(MNT_TVA) AS MNT_TVA_1049_PLAN,
           sum(MNT_TTC) AS MNT_TTC_1049_PLAN
          INTO
           #TEMP_1049_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE IN ('10-49','C10-49')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT
          
          /* Colonne 50+ PLAN + Conventionnel*/
          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_50_PLUS_PLAN,
           sum(MNT_TVA) AS MNT_TVA_50_PLUS_PLAN,
           sum(MNT_TTC) AS MNT_TTC_50_PLUS_PLAN
          INTO
           #TEMP_50_PLUS_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE IN ('50+','C50+')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT
         
          /* Colonne AUTRE */ 
          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_AUTRE,
           sum(MNT_TVA) AS MNT_TVA_AUTRE,
           sum(MNT_TTC) AS MNT_TTC_AUTRE
          INTO
           #TEMP_AUTRE
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE NOT IN ('DSP', 'PRO','-10','10-49','C10-49','50+','C50+')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT
         
          /* FINAL */
          SELECT
           #TMP_DATA.LIB_NOM,
           #TMP_DATA.LIB_PNM,
           #TMP_DATA.GRP_TYPE_VERSEMENT,
           #TMP_DATA.ID_BORDEREAU,
           #TMP_DATA.COD_BORDEREAU,
           #TMP_DATA.COD_ADHERENT,
           #TMP_DATA.LIB_RAISON_SOCIALE,
           #TMP_DATA.ID_POSTE_VERSEMENT,
           #TMP_DATA.LIB_BANQUE,
           #TMP_DATA.NUM_CHEQUE,
           #TMP_DATA.DAT_SAISIE,
           #TMP_DATA.TOTAL_HT,
           #TMP_DATA.NUM_CHEQ,
           PERIODE.NUM_ANNEE NUM_ANNEE,
           #TEMP_PRO.MNT_HT_PRO,
           #TEMP_DSP.MNT_HT_DSP,
           #TEMP_MOINS_10_PLAN.MNT_HT_MOINS_10_PLAN,
           #TEMP_AUTRE.MNT_HT_AUTRE,
           #TEMP_1049_PLAN.MNT_HT_1049_PLAN,
           #TEMP_50_PLUS_PLAN.MNT_HT_50_PLUS_PLAN,
           (ISNULL(#TEMP_DSP.MNT_HT_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_HT_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_HT_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_HT_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_HT_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_HT_AUTRE,0)) MNT_HT,
           (ISNULL(#TEMP_DSP.MNT_TVA_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_TVA_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_TVA_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_TVA_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_TVA_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_TVA_AUTRE,0)) MNT_TVA,
           (ISNULL(#TEMP_DSP.MNT_TTC_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_TTC_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_TTC_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_TTC_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_TTC_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_TTC_AUTRE,0)) MNT_TTC
          FROM
           #TMP_DATA
           LEFT OUTER JOIN #TEMP_DSP
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_DSP.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_PRO
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_PRO.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_MOINS_10_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_MOINS_10_PLAN.ID_POSTE_VERSEMENT 
           LEFT OUTER JOIN #TEMP_1049_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_1049_PLAN.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_50_PLUS_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_50_PLUS_PLAN.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_AUTRE
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_AUTRE.ID_POSTE_VERSEMENT
           INNER JOIN PERIODE
            ON #TMP_DATA.ID_PERIODE = PERIODE.ID_PERIODE
          ORDER BY
           #TMP_DATA.ID_BORDEREAU,#TMP_DATA.ID_POSTE_VERSEMENT
         
          DROP TABLE #TEMP
         END
GO
-- =============================================
         -- Author:		MBL
         -- Create date: 27/06/2014
         -- Description:	Refonte du Batch de Lettrage des factures
         --    Ce batch se base d‚sormais sur la vue VUE_LETTRAGE_FACTURE
         --    permettant de r‚cup‚rer toutes les factures non encore lettr‚es et devraient ˆtre lettr‚es
         -- =============================================
         CREATE PROCEDURE [dbo].[BATCH_LETTRAGE_FACTURES]
         	@ID_FACTURE int
         AS
         BEGIN
         	IF EXISTS(SELECT * FROM tempdb..sysobjects WHERE id=OBJECT_ID('tempdb..#FACTURES_A_LETTRER'))
         	BEGIN
         		DROP TABLE #FACTURES_A_LETTRER  
         	END
         
         	SELECT
         		ID_FACTURE, COD_AVOIR
         	INTO
         		#FACTURES_A_LETTRER  
         	FROM
         		VUE_LETTRAGE_FACTURE
         	WHERE 
         	(
         		BLN_LETTRE = 0 
         		AND BLN_NON_LETTRE_A_TORT = 1
         		AND ID_FACTURE = ISNULL(@ID_FACTURE, ID_FACTURE)
         	)
         
         	-- Lettrage de la facture
         	UPDATE
         		FACTURE
         	SET
         		BLN_LETTRE = 1
         	FROM
         		FACTURE 
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE = #FACTURES_A_LETTRER.ID_FACTURE
         
         	---- Lettrage des avoirs associes a la facture
         	UPDATE
         		FACTURE
         	SET
         		BLN_LETTRE = 1
         	FROM
         		FACTURE 
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE_ASSOCIEE_AVOIR = #FACTURES_A_LETTRER.ID_FACTURE
          
         	INSERT INTO
         		COMMENTAIRES
         		(
         			[TYPE_OBJET],
         			[ID_OBJET],
         			[DATE],
         			[COMMENTAIRE],
         			[ID_UTILISATEUR]
         		)
              SELECT
         		7, --TYPE_OBJET = facture
         		ID_FACTURE_ASSOCIEE_AVOIR,
         		GetDate(),
         		'lettr‚ par enregistrement de l''AVOIR nø ' + COD_FACTURE,
         		82
         	FROM
         		FACTURE
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE_ASSOCIEE_AVOIR = #FACTURES_A_LETTRER.ID_FACTURE
         
         END
GO
 CREATE PROC SearchAllTables
          (
           @SearchStr nvarchar(100)
          )
          AS
          BEGIN
         
           -- Copyright ¸ 2002 Narayana Vyas Kondreddi. All rights reserved.
           -- Purpose: To search all columns of all tables for a given search string
           -- Written by: Narayana Vyas Kondreddi
           -- Site: http://vyaskn.tripod.com
           -- Tested on: SQL Server 7.0 and SQL Server 2000
           -- Date modified: 28th July 2002 22:50 GMT
         
         
           CREATE TABLE #Results (ColumnName nvarchar(370), ColumnValue nvarchar(3630))
         
           SET NOCOUNT ON
         
           DECLARE @TableName nvarchar(256), @ColumnName nvarchar(128), @SearchStr2 nvarchar(110)
           SET  @TableName = ''
           SET @SearchStr2 = QUOTENAME('%' + @SearchStr + '%','''')
         
           WHILE @TableName IS NOT NULL
           BEGIN
            SET @ColumnName = ''
            SET @TableName =
            (
             SELECT MIN(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME))
             FROM  INFORMATION_SCHEMA.TABLES
             WHERE   TABLE_TYPE = 'BASE TABLE'
              AND QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) > @TableName
              AND OBJECTPROPERTY(
                OBJECT_ID(
                 QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)
                  ), 'IsMSShipped'
                       ) = 0
            )
         
            WHILE (@TableName IS NOT NULL) AND (@ColumnName IS NOT NULL)
            BEGIN
             SET @ColumnName =
             (
              SELECT MIN(QUOTENAME(COLUMN_NAME))
              FROM  INFORMATION_SCHEMA.COLUMNS
              WHERE   TABLE_SCHEMA = PARSENAME(@TableName, 2)
               AND TABLE_NAME = PARSENAME(@TableName, 1)
               AND DATA_TYPE IN ('char', 'varchar', 'nchar', 'nvarchar')
               AND QUOTENAME(COLUMN_NAME) > @ColumnName
             )
           
             IF @ColumnName IS NOT NULL
             BEGIN
              INSERT INTO #Results
              EXEC
              (
               'SELECT ''' + @TableName + '.' + @ColumnName + ''', LEFT(' + @ColumnName + ', 3630)
               FROM ' + @TableName + ' (NOLOCK) ' +
               ' WHERE ' + @ColumnName + ' LIKE ' + @SearchStr2
              )
             END
            END 
           END
         
           SELECT ColumnName, ColumnValue FROM #Results ORDER BY ColumnValue
          END
GO

         -- =============================================
         -- Author:		DSZ
         -- Create date: 31/05/2011
         -- Description:	Detacher les reglements annules des sessions pro
         -- sauf la session qui ‚tait d‚j… modifi‚ en cours de UPD_ANNULATION_VIREMENT_PRO
         -- =============================================
         -- Author:		DSZ
         -- Modif date: 10/10/2011
         -- Description:	12769 :  ajout v‚rif si reglementn'est pas valid‚
         -- =============================================
         CREATE PROCEDURE [dbo].[DETACHER_REGLT_PRO_DE_SESSION] 
         	@ID_REGLEMENT_PRO INT,
         	@ID_SESSION_PRO INT
         AS
         BEGIN
         
         	-- DSZ 10/10/11 ajout verif si le reglement n'est pas valid‚, au cas o—
         	DECLARE @DAT_VALID_REGLEMENT datetime
         	SET @DAT_VALID_REGLEMENT = null
         	SELECT @DAT_VALID_REGLEMENT = DAT_VALID_REGLEMENT 
         	FROM REGLEMENT_PRO 
         	WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO
         
         	if (@DAT_VALID_REGLEMENT is null)
         	begin
         	-- nettoyer les anciennes appartenances au rŠglement qui doit ˆtre remplac‚ 
         		UPDATE SESSION_PRO 
         		SET
         							ID_REGLEMENT_PRO_ADH= NULL
         		WHERE ID_REGLEMENT_PRO_ADH = @ID_REGLEMENT_PRO
         			AND ID_SESSION_PRO <> @ID_SESSION_PRO
         
         		UPDATE SESSION_PRO
         		SET
         							ID_REGLEMENT_PRO_OF= NULL
         		WHERE ID_REGLEMENT_PRO_OF = @ID_REGLEMENT_PRO
         			AND ID_SESSION_PRO <> @ID_SESSION_PRO
         	end
         END
         
GO

         -- =============================================
         -- Author:		kwame woollams
         -- Create date: 27 novembre 2007
         -- Description:	recupere le pourcentage des virements pro
         -- annul‚es par rapport aux virements … valider
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_PRC_VIR_PRO_SELECTIONNEES_ANNULEES]
         AS
         BEGIN
         	DECLARE @PRC AS decimal(18,2)
         
         	DECLARE @NUMERATEUR AS decimal(18,2)
         	DECLARE @DENOMINATEUR AS decimal(18,2)
         	SET @NUMERATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT_PRO.ID_REGLEMENT_PRO)
         		FROM	REGLEMENT_PRO
         		WHERE	REGLEMENT_PRO.BLN_EN_COURS = 1 AND
         				REGLEMENT_PRO.BLN_CRITERE = 1 AND
         				REGLEMENT_PRO.BLN_ACTIF = 0
         	)
         
         	SET @DENOMINATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT_PRO.ID_REGLEMENT_PRO)
         		FROM	REGLEMENT_PRO
         		WHERE	REGLEMENT_PRO.BLN_EN_COURS = 1 AND
         				REGLEMENT_PRO.BLN_CRITERE = 1
         	)
         
         	IF @DENOMINATEUR = 0
         		SET @PRC = 0
         
         	IF @DENOMINATEUR != 0 
         		SET @PRC = @NUMERATEUR/@DENOMINATEUR
         	
         	SELECT 'Return Value' = COALESCE(ROUND(@PRC,2),0)
         END
         
GO

         
         -- =============================================
         -- Author:		KW
         -- Create date: 26 septembre 2007
         -- Description:	 Permet de r‚cuperer le nombre de poste cout avec engagement pour un module
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_NB_POSTE_COUT_AVEC_ENGAGEMENT]
         	@ID_MODULE_PEC int
         AS
         BEGIN
         
         	DECLARE @NB AS INT
         	SET @NB = 0
         
         	SELECT  @NB = COUNT(*)
         	FROM    MODULE_PEC 
         			INNER JOIN POSTE_COUT_ENGAGE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC 
         			INNER JOIN ENGAGEMENT ON POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT 
         			INNER JOIN TYPE_ENGAGEMENT ON ENGAGEMENT.ID_TYPE_ENGAGEMENT = TYPE_ENGAGEMENT.ID_TYPE_ENGAGEMENT
         	WHERE		ENGAGEMENT.DAT_BAE IS NOT NULL
         			AND TYPE_ENGAGEMENT.ID_TYPE_ENGAGEMENT IN ( 1,3)
         			AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
         			AND MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
         	
         	SELECT 'Return Value' = COALESCE(@NB,0)
         END
         
GO

