-- =============================================  
         -- Author:  DSZ  
         -- Create date: 27/11/2012  
         -- Description: 14176 a utiliser dans ins_versement_extranet, cas simple : creer une regul avec son pv et pi,  
         -- uniquement le mnt HT  
         -- =============================================  
         -- DSZ 22/03/2012 15054 ajout cr‚ation d'un evenement de r‚gul  
         -- =============================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT  
         -- =============================================  
         -- ASD 17/06/2013 : e-mail : ajout de ID_ETABLISSEMENT_EMETTEUR dans INSERT INTO VERSEMENT  
         -- =============================================  
         -- MBL 19/12/2013	: Modification du libelle de l'evenement associe a la regul automatique : 'Regularisation automatique'
         --					: Valorisation du commentaires du versement cree avec ce meme libelle
         -- =============================================  
         CREATE PROCEDURE dbo.CREER_REGULARISATION_PV_PI
         	@ID_ADHERENT_EMETTEUR INTEGER,    
         	@ID_TIERS_EMETTEUR INTEGER,    
         	@ID_ETABLISSEMENT_EMETTEUR INTEGER,  
         	@MNT_VERSEMENT DECIMAL(18,2),  
         	@ID_TYPE_VERSEMENT INT, --5 OU 7  
         	@ID_PERIODE INT,  
         	@ID_ACTIVITE INT,  
         	@DONT_FPSPP DECIMAL(18,2)  
         AS  
         BEGIN
         	INSERT INTO VERSEMENT
         	(
         		ID_ADHERENT_EMETTEUR,
         		ID_TIERS_EMETTEUR,
         		ID_ETABLISSEMENT_EMETTEUR,
         		ID_MODE_VERSEMENT,
         		COD_VERSEMENT,
         		DAT_CREATION,
         		MNT_VERSEMENT ,
         		BLN_PB_IMPUTATION ,
         		BLN_ACTIF ,
         		ID_UTILISATEUR ,
         		DAT_SAISIE ,
         		ID_STATUT_VERSEMENT ,
         		BLN_IMPAYE ,
         		BLN_ECHEANCIER ,
         		COM_VERSEMENT
         	)
         	VALUES
         	(
         		@ID_ADHERENT_EMETTEUR,
         		@ID_TIERS_EMETTEUR,
         		@ID_ETABLISSEMENT_EMETTEUR,
         		2,
         		0, --cod ver  
         		GETDATE(),
         		@MNT_VERSEMENT,
         		0 ,
         		1 ,
         		82 ,
         		getdate(),
         		1 ,
         		0 ,
         		0 ,
         		'R‚gularisation automatique'
         	)
         	
         	DECLARE
         		@ID_VERSEMENT INT
         	
         	SET @ID_VERSEMENT =  scope_identity()
         	
         	UPDATE
         		VERSEMENT
         	SET
         		COD_VERSEMENT = @ID_VERSEMENT
         	WHERE
         		ID_VERSEMENT = @ID_VERSEMENT
         	
         	DECLARE
         		@ID_POSTE_VERSEMENT INT
         	EXEC
         		@ID_POSTE_VERSEMENT = INS_POSTE_VERSEMENT
         		@ID_VERSEMENT = @ID_VERSEMENT, --  int  
         		@ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT_EMETTEUR, --  int  
         		@ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT, --  int  
         		@ID_PERIODE = @ID_PERIODE, --  int  
         		@LIBL_POSTE_VERSEMENT = NULL, --  varchar(50)  
         		@MNT_POSTE_VERSEMENT = @MNT_VERSEMENT, --  decimal(18,2)  
         		@BLN_PB_IMPUTATION = 0, --  tinyint  
         		@BLN_ACTIF = 1, --  tinyint  
         		@ID_ETABLISSEMENT_BENEFICIAIRE = @ID_ETABLISSEMENT_EMETTEUR --  int  
         
         	DECLARE
         		@ID_POSTE_IMPUTATION INT
         
         	EXEC
         		@ID_POSTE_IMPUTATION = INS_POSTE_IMPUTATION
         		@ID_ACTIVITE = @ID_ACTIVITE, --  int  
         		@ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT, --  int  
         		@ID_VIREMENT_INTERNE_COLLECTE = NULL, --  int  
         		@MNT_HT = @MNT_VERSEMENT, --  decimal(18,2)  
         		@MNT_TVA = 0, --  decimal(18,2)  
         		@MNT_TTC = @MNT_VERSEMENT, --  decimal(18,2)  
         		@DAT_MAJ_CPT_ADH = NULL, --  datetime  
         		@ID_VIREMENT_INTERNE_COLLECTE_IMPAYE = NULL, --  int  
         		@DONT_REGLE_FPSPP = @DONT_FPSPP --  decimal(18,2)  
         
         	INSERT INTO EVENEMENT
         	(
         		LIBL_EVENEMENT,
         		DAT_EVENEMENT,
         		ID_TYPE_EVENEMENT,
         		ID_VERSEMENT
         	)
         	VALUES
         	(
         		'R‚gularisation Automatique' ,
         		getdate(),
         		5,
         		@ID_VERSEMENT
         	)
         END
GO
-- =============================================
         -- Author			: xxx
         -- Create date		: xx xxxx 2007
         -- Description		: proc‚dure de lecture demandes de chiffrages pour les demandes de rŠglements
         -- =============================================
         -- Author			: SAY
         -- Modified date	: 03 juillet 2007
         -- comment			: # ajout de : "AND STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC"
         -- =============================================
         -- Author			: SV
         -- Modified date	: 27 ao–t 2007
         -- comment			: Ajout d'un filtre sur les unit‚s stagiaires qui ont un nombre d'heure > 0
         --						--> Gestion des dispositifs refus‚s
         -- =============================================
         -- Author			: SV
         -- Modified date	: 28 ao–t 2007
         -- comment			: Ajout d'un filtre sur les unit‚s stagiaires non refus‚es lors de la cr‚ation
         --						--> Gestion des dispositifs refus‚s quand il y a plusieurs stagiaire avec des refus diff‚rents
         -- =============================================
         -- Author			: DSZ
         -- Modified date	: 25/06/09 
         -- comment			: Mantis 12093. ajout filtre etablissement d'adherent
         -- =============================================
         -- Author			: SLAH
         -- Modified date	: 04/06/12 
         -- comment			: Mantis 13505. Heures r‚mun‚r‚es 2 : rŠglement 
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         
         CREATE PROCEDURE [dbo].[LEC_GRP_DEMANDES_CHIFFRAGE]
         	@ID_MODULE int,
         	@ID_POSTE_COUT_REGLE int,
         	@BLN_CREATION bit,
         	@ID_SESSION_PEC int,
         	@ID_ADHERENT int,
         	--ajout DSZ 25/06/09 Mantis 12093
         	@ID_ETABLISSEMENT int
         	--fin ajout DSZ
         AS
         BEGIN
         	IF @BLN_CREATION IS NULL
         	BEGIN
         		SET @BLN_CREATION = 0
         	END
         
         	IF @BLN_CREATION = 0
         	BEGIN
         		DECLARE @MNT_REGLE_HT decimal(18,2)
         		DECLARE @NUM_DUREE_HEURE int
         		DECLARE @NUM_STAGIAIRE int
         		DECLARE @SUM_HEURE_STAGIAIRE float
         		
         		--SV : Pas utile de le refaire ici
         		--IF (@BLN_CREATION IS NULL)
         		--BEGIN
         		--	SET @BLN_CREATION = 0
         		--END
         		
         		SELECT @NUM_DUREE_HEURE = NUM_DUREE_HEURE FROM
         		MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE
         		
         		IF (@NUM_DUREE_HEURE IS NULL)
         		BEGIN
         			SET @NUM_DUREE_HEURE = 1
         		END
         		
         		SELECT @MNT_REGLE_HT = MNT_REGLE_HT FROM
         		POSTE_COUT_REGLE WHERE ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         
         		SELECT @SUM_HEURE_STAGIAIRE = SUM(NB_HEURE_ENGAGE)
         		FROM STAGIAIRE_PEC
         		WHERE ID_MODULE_PEC = @ID_MODULE
         
         		IF (@MNT_REGLE_HT IS NULL)
         		BEGIN
         			SET @MNT_REGLE_HT = 0
         		END
         		
         		SELECT @NUM_STAGIAIRE = COUNT(*) FROM
         		STAGIAIRE_PEC WHERE ID_MODULE_PEC = @ID_MODULE
         		
         		IF (@NUM_STAGIAIRE IS NULL)
         		BEGIN
         			SET @NUM_STAGIAIRE = 0
         		END
         		
         		Select DISTINCT
         			UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE,
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         			ADHERENT.LIB_RAISON_SOCIALE AS ADHERENT,
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU AS STAGIAIRE,
         			DISPOSITIF.LIBL_DISPOSITIF AS DISPOSITIF,
         			UNITE_STAGIAIRE.NB_HEURE_ENGAGE AS NB_HEURE,
         			UNITE_STAGIAIRE.NB_HEURE_REGLE As NB_HEURE_REGLE,
         			case when (@SUM_HEURE_STAGIAIRE > 0)
         				then (@MNT_REGLE_HT * UNITE_STAGIAIRE.NB_HEURE_REGLE) / @SUM_HEURE_STAGIAIRE
         				else 0
         			end AS CALCULATE_TOTAL,
         			0 AS TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_ENGAGE As NB_HEURE_TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_REGLE As NB_HEURE_REGLE_TOTAL,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT,
         			ETABLISSEMENT.ID_ADHERENT,
         			DISPOSITIF.ID_DISPOSITIF,
         			ISNULL(@ID_POSTE_COUT_REGLE,0) AS ID_POSTE_COUT_REGLE,
         			ISNULL(UNITE_STAGIAIRE.NB_HEURE_REM,0) AS NB_HEURE_REM
         		FROM
         			UNITE_STAGIAIRE
         				--INNER JOIN PLAN_FINANCEMENT_US	ON PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         										--AND PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         				INNER JOIN STAGIAIRE_PEC		ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         				INNER JOIN DISPOSITIF			ON DISPOSITIF.ID_DISPOSITIF = UNITE_STAGIAIRE.ID_DISPOSITIF
         				INNER JOIN  INDIVIDU				ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				LEFT JOIN ETABLISSEMENT			ON ETABLISSEMENT.ID_ETABLISSEMENT = STAGIAIRE_PEC.ID_ETABLISSEMENT
         				LEFT JOIN ADHERENT				ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE
         			AND (@ID_SESSION_PEC is null OR STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)
         			AND (@ID_ADHERENT is null or ADHERENT.ID_ADHERENT = @ID_ADHERENT)
         			--ajout DSZ 25/06/09 Mantis 12093
         			AND (@ID_ETABLISSEMENT is null or ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
         			--fin ajout DSZ
         			AND UNITE_STAGIAIRE.NB_HEURE_REGLE > 0
         			AND UNITE_STAGIAIRE.BLN_REFUS = 0
         		ORDER BY
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU
         	END
         	ELSE
         	BEGIN
         		SELECT DISTINCT
         			UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE,
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         			ADHERENT.LIB_RAISON_SOCIALE AS ADHERENT,
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU AS STAGIAIRE,
         			DISPOSITIF.LIBL_DISPOSITIF AS DISPOSITIF,
         			UNITE_STAGIAIRE.NB_HEURE_ENGAGE AS NB_HEURE,
         			UNITE_STAGIAIRE.NB_HEURE_REGLE AS NB_HEURE_REGLE,
         			0 AS CALCULATE_TOTAL,
         			0 AS TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_ENGAGE AS NB_HEURE_TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_REGLE AS NB_HEURE_REGLE_TOTAL,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT,
         			ETABLISSEMENT.ID_ADHERENT,
         			DISPOSITIF.ID_DISPOSITIF,
         			0 AS ID_POSTE_COUT_REGLE,
         			ISNULL(UNITE_STAGIAIRE.NB_HEURE_REM,0) AS NB_HEURE_REM
         		FROM
         			UNITE_STAGIAIRE
         				INNER JOIN STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC
         				INNER JOIN DISPOSITIF		ON DISPOSITIF.ID_DISPOSITIF = UNITE_STAGIAIRE.ID_DISPOSITIF
         				INNER JOIN INDIVIDU			ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				INNER JOIN ETABLISSEMENT	ON ETABLISSEMENT.ID_ETABLISSEMENT = STAGIAIRE_PEC.ID_ETABLISSEMENT
         				INNER JOIN ADHERENT			ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE
         			AND UNITE_STAGIAIRE.NB_HEURE_REGLE > 0
         			AND UNITE_STAGIAIRE.BLN_REFUS = 0
         			AND	(@ID_SESSION_PEC is null OR STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)
         			AND (@ID_ADHERENT is null or ADHERENT.ID_ADHERENT =@ID_ADHERENT)
         			--ajout DSZ 25/06/09 Mantis 12093
         			AND (@ID_ETABLISSEMENT is null or ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
         			--fin ajout DSZ
         		ORDER BY
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU
         	END
         END   
         
         
         
         
         
         
         
         
         
GO

         
         -- =============================================
         -- Author:		KW
         -- Create date: 26 septembre 2007
         -- Description:	 Permet de r‚cuperer le nombre de poste cout regle avec reglement pour un module
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_NB_POSTE_COUT_AVEC_REGLEMENT]
         	@ID_MODULE_PEC int
         AS
         BEGIN
         
         	DECLARE @NB AS INT
         	SET @NB = 0
         
         	SELECT  @NB = COUNT(*)
         	FROM    MODULE_PEC 
         			INNER JOIN POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC 
         			
         	WHERE		POSTE_COUT_REGLE.DAT_BAP IS NOT NULL
         			AND MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
         	
         	SELECT 'Return Value' = COALESCE(@NB,0)
         END
         
GO
 CREATE PROCEDURE [dbo].[UPD_STAGIAIRE_MODULE_PEC]
         -- ============================================================================================
         -- Author: Dorota Szeliga
         -- Modif. date: 18/04/2008
         -- Description: Changement ID_BRANCHE si changement ETABLISSEMENT
         -- ============================================================================================
         -- Author: MB (pour le FAF Propret‚)
         -- Modif. date: 12/02/2008 !!!
         -- Description: - Modification pour empecher de supprimer les mouvements budgetaires associes aux reglements
         -- ============================================================================================
         -- Author: SAF & ASD
         -- Modif. date: 18/03/2009
         -- Description: - R‚cup‚ration des modifications pour C2P
         -- ============================================================================================
         -- Author: SAFI
         -- Modif. date: 05/01/2010
         -- Description: COMMENTER LES LIGNE DE SUPPRISSION DE EVE ET MVT
         -- ============================================================================================
         -- Author: MBT
         -- Modif. date: 19/02/2010
         -- Description: EVOL EDI salari‚s niveau formation 
         -- ============================================================================================
         -- Author: DSZ
         -- Modif. date: 19/03/2010
         -- Description: 12307: ne pas toucher a BLN_OK_FINANCEMENT des modules engages
         -- ============================================================================================
         -- Author: DSZ
         -- Modif. date: 29/11/2010
         -- Description: 12561: Sur modif ‚tab de rattachement d'un stagiaire dans module pec,
         --               remettre … z‚ro le plan financement us de ce stagiaire dans ce module.
         -- ============================================================================================
         -- Author: DSZ
         -- Modif. date: 07/12/2010
         -- Description: 12561: Sur modif ‚tab de rattachement d'un stagiaire ajouter les mouvements inverses P associ‚s.
         -- PLUS modif LEC_GRP_STAGIAIRE_MODULE_PEC_POSTE_COUT!!!!
         -- ============================================================================================
         -- Author: DSZ
         -- Modif. date: 17/02/2011
         -- Description: 12638: Si @DUREE_PREVUE = 0, supprimer les PFUS et annuler les mvt P
         -- ============================================================================================
         -- Author: DSZ
         -- Modif. date: 16/06/2011
         -- Description: Gestion null ref exception. si parametres = -1, mettre null
         -- datetime : 1900-01-01T00:00:00
         -- ============================================================================================
         -- 05/12/2011 DSZ
         -- 13040 : historisation ID_ACTIVITE : modif si etablissement modifi‚
         -- ============================================================================================
         -- 20/12 2011 DSZ
         -- 13040 : Passer ID_ACTIVITE en parametre
         -- ============================================================================================
         -- 18/05/12 SLAH
         -- 13485 : mise … jour du SALARIE sur enregistrement du STAGIAIRE_PEC 
         -- ============================================================================================
         -- 29/05/12 SLAH
         -- 13504 : mise … jour @NB_HEURE_REM
         -- ============================================================================================
         -- 30/05/12 LDE
         -- 13530: [#1089] Revue onglet Stagiaire de Module et Session PEC : compl‚ment
         -- Ajout de la conlonne FONCTION
         -- ============================================================================================
         -- Author:  EOU
         -- Modification date: 10 09 2012
         -- Description: 13746 
         -- ============================================================================================
         -- 07/02/13 LDE
         -- 14822: [AGPP] : 8 : AGPP fonctionnel en descente en compta, ETEBAC et virements internes (-> en prod le 28/2)
         -- Remplacement de != 3 pour d‚tecter le plan
         -- ============================================================================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- ============================================================================================ 
         -- Author:  <Page Olivier>
         -- Create date: <28/06/2013>
         -- Description: <15341: [Synchro] Nouveau type de stage : Fonction tutorale + synchro : 2- la synchro (2/2 : en v1.6.1)>
         -- ============================================================================================
         -- HBO - 20140903 #481
         -- ============================================================================================
         -- HBO - #578 - MAJ de PFUS possible que sur un PCE non engag‚
         -- ============================================================================================
         -- OPA 14/01/2013 #713 : enlever le paramŠtre par d‚faut 
         -- ============================================================================================
          @ID_MODULE_PEC     INT,
          @ID_INDIVIDU     INT,
          @ID_ETABLISSEMENT    INT,
          @TYPE_CONTACT     INT,
          @CATEGORIE_ACTION    INT,
          @CSP       INT,
          @CLASSIFICATION     INT,
          @ID_STATUT      INT,
          @HORARIE_MENSUEL    DECIMAL(18,2),
          @DUREE_PREVUE     DECIMAL(18,2),
          @DUREE_REALISEE     DECIMAL(18,2),
          @MATRICULE      VARCHAR(20),
          @AGENCE       VARCHAR(35),
          @DR        VARCHAR(35),
          @BRUT_CHARGE     DECIMAL(18,2),
          @FORMATEUR_INTERNE    INT,
          @NB_HEURES      DECIMAL(18,2),
          @COM_STAGIAIRE     VARCHAR(255),
          @BLN_TEMPS_PARTIEL    TINYINT,
          @CENTRE_COUT     VARCHAR(50),
          @ID_CODE_INSEE     INT,
          @ID_FAMILLE_PROFESSIONNELLE  INT,
          @SALAIRE_HORAIRE_NET   DECIMAL(18,2),
          @SALAIRE_HORAIRE_BRUT_CHARGE DECIMAL(18,2),
          @MONTANT_BRUT_CHARGE   DECIMAL(18,2),
          @DATE_EMBAUCHE     DATETIME,
          @ID_NIVEAU_AVENANT    INT,
          @ANALYTIQUE_STAGIAIRE   VARCHAR(20),
          @ID_STAGIAIRE_TUTEUR   INT,
          @TIME_STAMP      TIMESTAMP,
          @ID_STAGIAIRE     INT OUTPUT,
          @ID_SESSION      INT,
          @ID_BRANCHE      INT,
          @ID_GROUPE      INT,
          @ID_ACTIVITE     INT,
          @NB_HEURE_REM     DECIMAL(18,2),
          @FONCTION      VARCHAR(100),
          @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU INT,
          @ID_SUIVI_STAGIAIRE_IMMEDIAT INT,
          @ID_SUIVI_STAGIAIRE_TROIS_MOIS INT
         AS  
         BEGIN 
          IF (@ID_FAMILLE_PROFESSIONNELLE = -1)
          BEGIN
           SET @ID_FAMILLE_PROFESSIONNELLE = NULL
          END
          
          IF (@ID_CODE_INSEE = -1)
          BEGIN
           SET @ID_CODE_INSEE = NULL
          END
          
          IF (@TYPE_CONTACT = -1)
          BEGIN
           SET @TYPE_CONTACT = NULL
          END
          
          IF (@CLASSIFICATION = -1)
          BEGIN
           SET @CLASSIFICATION = NULL
          END
         
          IF (@ID_ACTIVITE < 0)
          BEGIN
           SET @ID_ACTIVITE = NULL
          END
         
          DECLARE
           @COUNT INT
         
          SELECT
           @COUNT = COUNT(*)
          FROM
           STAGIAIRE_PEC
          WHERE
           ID_STAGIAIRE_PEC = @ID_STAGIAIRE
           AND ID_MODULE_PEC = @ID_MODULE_PEC
         
          IF (@COUNT > 0)
          BEGIN
           DECLARE
            @ID_ETABLISSEMENT_OLD INT
         
           SELECT
            @ID_ETABLISSEMENT_OLD = ID_ETABLISSEMENT
           FROM
            STAGIAIRE_PEC
           WHERE
            ID_STAGIAIRE_PEC = @ID_STAGIAIRE
         
           UPDATE
            STAGIAIRE_PEC
           SET
            ID_INDIVIDU = @ID_INDIVIDU,
            ID_MODULE_PEC = @ID_MODULE_PEC,
            ID_TYPE_CONTRAT = @TYPE_CONTACT,
            ID_CATEGORIE_ACTION = @CATEGORIE_ACTION,
            ID_CLASSIFICATION = @CLASSIFICATION,
            ID_CSP    = @CSP,
            ID_STATUT   = @ID_STATUT ,
            ID_ETABLISSEMENT = @ID_ETABLISSEMENT,
            BLN_FORMATEUR_INTERNE = @FORMATEUR_INTERNE,
            NB_HEURES_HORS_TT  = @NB_HEURES,
            NUM_DUREE_MENSUELLE_TRAVAIL = @HORARIE_MENSUEL,
            NB_HEURE_ENGAGE  = @DUREE_PREVUE,
            NB_HEURE_REGLE  = @DUREE_REALISEE,
            MATRICULE_SALARIE = @MATRICULE,
            LIB_AGENCE   = @AGENCE,
            LIB_DR    = @DR,
            SALAIRE_HORAIRE_CHARGE = @BRUT_CHARGE,
            COM_STAGIAIRE_PEC = @COM_STAGIAIRE,
            BLN_TEMPS_PARTIEL = @BLN_TEMPS_PARTIEL,
            CENTRE_COUT = @CENTRE_COUT,
            ID_CODE_INSEE = @ID_CODE_INSEE,
            ID_FAMILLE_PROFESSIONNELLE = @ID_FAMILLE_PROFESSIONNELLE,
            SALAIRE_HORAIRE_NET = @SALAIRE_HORAIRE_NET,
            SALAIRE_HORAIRE_BRUT_CHARGE = @SALAIRE_HORAIRE_BRUT_CHARGE,
            MONTANT_BRUT_CHARGE = @MONTANT_BRUT_CHARGE,
            DATE_EMBAUCHE = @DATE_EMBAUCHE,
            ANALYTIQUE_STAGIAIRE = @ANALYTIQUE_STAGIAIRE,
            ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE_TUTEUR,
            ID_BRANCHE = @ID_BRANCHE,
            ID_GROUPE = @ID_GROUPE,
            ID_NIVEAU_AVENANT = @ID_NIVEAU_AVENANT,
            NB_HEURE_REM = @NB_HEURE_REM,
            FONCTION   = @FONCTION,
            ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU = @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
            ID_SUIVI_STAGIAIRE_IMMEDIAT = @ID_SUIVI_STAGIAIRE_IMMEDIAT,
            ID_SUIVI_STAGIAIRE_TROIS_MOIS = @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
           WHERE
            ID_STAGIAIRE_PEC = @ID_STAGIAIRE 
         
           PRINT @FORMATEUR_INTERNE
         
           IF ( @FORMATEUR_INTERNE > 0)
           BEGIN
            UPDATE
             SP
            SET
             SP.ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE
            FROM
             STAGIAIRE_PEC SP
             INNER JOIN MODULE_PEC MP
              ON MP.ID_MODULE_PEC = SP.ID_MODULE_PEC
            WHERE
             MP.ID_ACTION_PEC IN (SELECT ID_ACTION_PEC FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC)
             AND MP.ID_MODULE_PEC <> @ID_MODULE_PEC
           END 
             
           IF (@ID_NIVEAU_AVENANT = 0)
           BEGIN
            UPDATE
             STAGIAIRE_PEC
            SET
             ID_NIVEAU_AVENANT = NULL
            WHERE
             ID_STAGIAIRE_PEC = @ID_STAGIAIRE 
           END
           
           IF (@ID_SESSION IS NULL OR @ID_SESSION = 0)
           BEGIN
            UPDATE
             POSTE_COUT_ENGAGE
            SET
             BLN_OK_FINANCEMENT = 0
            WHERE
             ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 
           END
         
           IF ((@ID_ETABLISSEMENT_OLD <> @ID_ETABLISSEMENT) OR @DUREE_PREVUE = 0)
           BEGIN
            IF (@ID_ETABLISSEMENT_OLD <> @ID_ETABLISSEMENT)
            BEGIN
             --SI ON N'A PAS DETERMIN L'ID ACTIVIT DANS LE CODE
             IF (@ID_ACTIVITE IS NULL)
             BEGIN
              --*********** RECHERCHE DE L'ID ACTIVIT POUR L'HISTORISER
              --MODIF ID_ACTIVITE DSZ 05/12/2011
              --UNIFORMISATION DE L'ACTIVIT AU 1ER STAGIAIRE DE L'TABLISSEMENT
              SELECT
               @ID_ACTIVITE = ID_ACTIVITE
              FROM
               STAGIAIRE_PEC
              WHERE
               STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
               AND STAGIAIRE_PEC.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
               AND STAGIAIRE_PEC.ID_STAGIAIRE_PEC <> @ID_STAGIAIRE
               AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL
              ORDER BY
               ID_STAGIAIRE_PEC
         
              IF (@ID_ACTIVITE IS NULL)
               SELECT
                @ID_ACTIVITE = R19.ID_ACTIVITE 
               FROM
                MODULE_PEC 
                INNER JOIN ETABLISSEMENT
                 ON ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
                INNER JOIN R19
                 ON R19.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
                  AND R19.ID_PERIODE = MODULE_PEC.ID_PERIODE
                  AND R19.ID_ACTIVITE IN (SELECT ID_ACTIVITE FROM GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN')) -- LDE 07/02/2013 #14822
               WHERE
                MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC 
         
              -- si toujours null, on lŠve une exception
              IF (@ID_ACTIVITE IS NULL) 
              BEGIN
               RAISERROR(N'Impossible d''attacher un ou plusieurs stagiaires : leur adh‚rent n''a pas d''activit‚', 16, 1)
              END
         
               -- *** FIN RECHERCHE ACTIVIT, UPDATE
             END  -- IF @ID_ACTIVITE IS NULL 
         
             UPDATE
              STAGIAIRE_PEC
             SET
              ID_ACTIVITE = @ID_ACTIVITE
             WHERE
              ID_STAGIAIRE_PEC = @ID_STAGIAIRE
            END
         
            DECLARE
             @SUM_PFUS DECIMAL(18,2)
            
            SELECT
             @SUM_PFUS = -1 * SUM(MNT_PLAN_FINANCEMENT_US)
            FROM
             PLAN_FINANCEMENT_US
             INNER JOIN  UNITE_STAGIAIRE
              ON UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE
            WHERE
             UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = @ID_STAGIAIRE
             
            UPDATE
             PLAN_FINANCEMENT_US
            SET
             MNT_PLAN_FINANCEMENT_US = 0,
             MNT_PLAN_FINANCEMENT_US_TVA = 0,
             COM_PLAN_FINANCEMENT_US = 'REMIS · 0 PENDANT CHANGEMENT D''TABLISSEMENT'
            FROM
             PLAN_FINANCEMENT_US
             INNER JOIN  UNITE_STAGIAIRE
              ON UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE
             INNER JOIN POSTE_COUT_ENGAGE
              ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
            WHERE
             UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = @ID_STAGIAIRE
             AND
             (
              MNT_PLAN_FINANCEMENT_US <>0
              OR MNT_PLAN_FINANCEMENT_US_TVA <> 0
             )
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL
           END
          
           -- RECHERCHE DES STAGIAIRES SESSION CORRESPONDANT
           SELECT
            S.ID_STAGIAIRE_PEC
           INTO
            #SEARCH_SESSION
           FROM
            STAGIAIRE_PEC S
            INNER JOIN ETABLISSEMENT E1
             ON E1.ID_ETABLISSEMENT = S.ID_ETABLISSEMENT
            INNER JOIN STAGIAIRE_PEC S2
             ON S2.ID_MODULE_PEC = S.ID_MODULE_PEC
              AND S2.ID_INDIVIDU  = S.ID_INDIVIDU
              AND S2.ID_SESSION_PEC IS NULL
            INNER JOIN ETABLISSEMENT E2
             ON E2.ID_ETABLISSEMENT = S2.ID_ETABLISSEMENT
              AND E2.ID_ADHERENT = E1.ID_ADHERENT
           WHERE
            S2.ID_STAGIAIRE_PEC = @ID_STAGIAIRE AND 
            S.ID_SESSION_PEC IS NOT NULL
         
           IF (EXISTS (SELECT * FROM #SEARCH_SESSION))
           BEGIN
            UPDATE
             STAGIAIRE_PEC
            SET 
             ID_TYPE_CONTRAT  = @TYPE_CONTACT,
             ID_CATEGORIE_ACTION = @CATEGORIE_ACTION,
             ID_CLASSIFICATION = @CLASSIFICATION,
             ID_CSP    = @CSP,
             ID_STATUT   = @ID_STATUT ,
             ID_ETABLISSEMENT = @ID_ETABLISSEMENT,
             NUM_DUREE_MENSUELLE_TRAVAIL = @HORARIE_MENSUEL,
             SALAIRE_HORAIRE_CHARGE  = @BRUT_CHARGE,
             MATRICULE_SALARIE = @MATRICULE,
             LIB_AGENCE   = @AGENCE,
             LIB_DR    = @DR,
             NB_HEURE_REM  = @NB_HEURE_REM,
             FONCTION   = @FONCTION,
             ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU = @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
             ID_SUIVI_STAGIAIRE_IMMEDIAT = @ID_SUIVI_STAGIAIRE_IMMEDIAT,
             ID_SUIVI_STAGIAIRE_TROIS_MOIS = @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
            WHERE
             ID_STAGIAIRE_PEC IN (SELECT ID_STAGIAIRE_PEC FROM #SEARCH_SESSION)
           END
          END
          ELSE
          BEGIN
           EXEC INS_STAGIAIRE_MODULE_PEC
            @ID_MODULE_PEC,
            @ID_INDIVIDU,
            @ID_ETABLISSEMENT,
            @TYPE_CONTACT,
            @CATEGORIE_ACTION,
            @CSP,
            @CLASSIFICATION,
            @MATRICULE,
            @ID_STATUT,
            @AGENCE,
            @DR,
            @FORMATEUR_INTERNE,
            @HORARIE_MENSUEL,
            @DUREE_PREVUE,
            @DUREE_REALISEE,
            @NB_HEURES,
            @BRUT_CHARGE,
            @COM_STAGIAIRE,
            @BLN_TEMPS_PARTIEL,
            @CENTRE_COUT,
            @ID_CODE_INSEE,
            @ID_FAMILLE_PROFESSIONNELLE,
            @SALAIRE_HORAIRE_NET,    
            @SALAIRE_HORAIRE_BRUT_CHARGE,
            @MONTANT_BRUT_CHARGE,
            @DATE_EMBAUCHE,
            @ID_NIVEAU_AVENANT,    
            @ANALYTIQUE_STAGIAIRE,
            @ID_STAGIAIRE_TUTEUR,
            @ID_STAGIAIRE OUTPUT,
            @ID_SESSION,
            @ID_BRANCHE,
            @ID_GROUPE,   
            @ID_ACTIVITE,
            @NB_HEURE_REM,
            @FONCTION,
            @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
            @ID_SUIVI_STAGIAIRE_IMMEDIAT ,
            @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          END
         END

GO

--=======================================
-- DSZ 23/02/2011 12378
-- On v‚rifie que le PCE de mˆme module et sous type de co–t 
         -- est bien engag‚ (Attention ce n'est pas forc‚ment l'ID_POSTE_COUT_ENGAGE associ‚ au PCR). 
         -- Si ce n'est pas le cas, on positionne l'ETAT_PEC … la valeur 13  (Module d‚sengag‚) 
         -- et le type de validation … 8 (Non B…Pable). 
-----------------------------------------
-- DSZ 17/03/2011 12378
-- ne pas baper si le PCR en Etat-pec <> 1 (donc ca a change depuis lec_pre-bon_a_payer)
-- ne pas rebaper le PCR si deja bape
-----------------------------------------
-- DSZ 30/03/2011 12744
--  ajout faux update si pas de vrai
-- le dataset exige un update d'une ligne
-----------------------------------------
-- DSZ 29/04/2011 12768
-- modif la restriction trop stricte sur ETAT_PEC = 1 
-----------------------------------------
-- ASD-DSZ 05/07/2011 12823
-- Pb prod : restriction trop forte sur DAT_BAP is null : 
-- on peut avoir une DR bap‚e mais n'appartenant pas encore … un lot de bap (une SESSION)
-- parce qu'on n'a pas encore cl“tur‚ le lot.
--=======================================
CREATE PROCEDURE [dbo].[UPD_BON_A_PAYER]
	@BAP tinyint,
	@ID_POSTE_COUT_REGLE	int,
	@ID_SESSION				int,
	@DAT_BAP				datetime,
	@ID_TYPE_VALIDATION		int
AS  
         BEGIN
         
         --on selectionne PCE non desengag‚ de mˆme module et stc
         	declare @ID_PCE int
         	set @ID_PCE = null
         	select @ID_PCE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
	from POSTE_COUT_ENGAGE
		inner join POSTE_COUT_REGLE on 
			(POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT AND
			POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC)
	where	
		POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE AND
		POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL AND
		POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL

         
         -- si ID_PCE existe (est non null) on peut BAPer, si etat PEC le permet
         	if @ID_PCE is not null
         	begin
         		UPDATE POSTE_COUT_REGLE
         		SET	
         			ID_SESSION = @ID_SESSION,
         			--20110705 ASD-DSZ (en remplacement de DAT_BAP=@DAT_BAP)
         			DAT_BAP = case when (DAT_BAP is null) then @DAT_BAP else DAT_BAP end,
         			ID_TYPE_VALIDATION = @ID_TYPE_VALIDATION
         		WHERE 
         			ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         			--ajout DSZ 17/03/2011  --modif DSZ 29/04/2011 -- and ID_ETAT_PEC = 1
         			and ID_TYPE_VALIDATION <> 8
         			--20110705 ASD-DSZ
         			-- and DAT_BAP is null --: implicit ID_TYPE_VALIDATION <> 2
         
         		--faux update ajout‚ DSZ 12744
         		if (@@rowcount =0)
         			UPDATE POSTE_COUT_REGLE
         			SET	ID_SESSION = ID_SESSION
         			WHERE ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         	end
         
         --sinon l'ETAT_PEC … la valeur 13 et le type de validation … 8
         	else
         		UPDATE POSTE_COUT_REGLE    
		SET 
			ID_TYPE_VALIDATION = 8, 
			ID_ETAT_PEC = 13    
		WHERE 
         			ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         END
         
         
         
GO
 CREATE PROCEDURE [dbo].[INS_STAGIAIRE_MODULE_PEC]
          @ID_MODULE_PEC  int,
          @ID_INDIVIDU  int,
          @ID_ETABLISSEMENT int,
          @TYPE_CONTACT  int,
          @CATEGORIE_ACTION int,
          @CSP    int,
          @CLASSIFICATION  int,
          @MATRICULE   varchar(20),
          @ID_STATUT   int,
          @AGENCE    varchar(35),
          @DR     varchar(35),
          @FORMATEUR_INTERNE int,
          @HORARIE_MENSUEL decimal(18,2),
          @DUREE_PREVUE  decimal(18,2),
          @DUREE_REALISEE  decimal(18,2),
          @NB_HEURES   decimal(18,2),
          @BRUT_CHARGE  decimal(18,2),
          @COM_STAGIAIRE  varchar(255),
          @BLN_TEMPS_PARTIEL tinyint,
          @CENTRE_COUT  varchar(50),
          @ID_CODE_INSEE  int,
          @ID_FAMILLE_PROFESSIONNELLE int,
          @SALAIRE_HORAIRE_NET decimal(18,2),
          @SALAIRE_HORAIRE_BRUT_CHARGE decimal(18,2),
          @MONTANT_BRUT_CHARGE decimal(18,2),
          @DATE_EMBAUCHE  datetime,
          @ID_NIVEAU_AVENANT int,
          @ANALYTIQUE_STAGIAIRE varchar(20),
          @ID_STAGIAIRE_TUTEUR int,
          @ID_STAGIAIRE  int output,
          @ID_SESSION   int,
          @ID_BRANCHE   int,
          @ID_GROUPE   int,
          @ID_ACTIVITE  INT,
          @NB_HEURE_REM  decimal(18,2),
          @FONCTION   varchar(100),
          @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU INT,
          @ID_SUIVI_STAGIAIRE_IMMEDIAT INT,
          @ID_SUIVI_STAGIAIRE_TROIS_MOIS INT
         AS  
         -- ============================================================================================
         -- Author: Dorota Szeliga
         -- Modif. date: 18/04/2008
         -- Description: Sauvagarde de la branche d'etablissement dans la table stagiaire_pec afin
         --    de conserver la branche d'origine si l'etablissement en change
         -- ============================================================================================
         -- 21/10/2009 DSZ
         -- Mantis 12180 Evol 406 Historisation du groupe
         -- ============================================================================================
         -- 09/12/2009 SAFI
         -- Mantis 12256 : La branche et le groupe doit ˆtre historis‚e la mˆme 
             --pour toute la vie du dossier. 
         -- ============================================================================================
         -- 09/12/2009 SAFI
         -- Mantis 12180 : Added two parameters @ID_BRANCHE ET @ID_GROUPE 
         -- ============================================================================================
         -- 19/03/2010 DSZ
         -- 12307: ne pas toucher a BLN_OK_FINANCEMENT des modules engag‚s
         -- ============================================================================================
         -- 05/12/2011 DSZ
         -- 13040 : historisation ID_ACTIVITE
         -- ============================================================================================
         -- 20/12 2011 DSZ
         -- 13040 : Passer ID_ACTIVITE en parametre
         -- ============================================================================================
         -- ============================================================================================
         -- 18/05/12 SLAH
         -- 13485 : mise … jour du SALARIE sur enregistrement du STAGIAIRE_PEC 
         -- ============================================================================================
         
         -- ============================================================================================
         -- 29/05/12 SLAH
         -- 13504 : mise … jour @NB_HEURE_REM
         -- ============================================================================================
         -- 30/05/12 LDE
         -- 13530: [#1089] Revue onglet Stagiaire de Module et Session PEC : compl‚ment
         -- Ajout de la conlonne FONCTION
         -- ============================================================================================
         -- 01/06/12 EOU
         -- 13527: [#1089] Revue onglet Stagiaire de Module et Session PEC : compl‚ment
         -- Copier stagaiaire
         -- ============================================================================================
         -- Author:  EOU
         -- Modification date: 10 09 2012
         -- Description: 13746 
         ------------------------------------------------------------
         -- ASD 07/01/2013 14822 : remplacer la condition !=3 via type_activite 
         -- ============================================================================================
         -- OPA 14/01/2013 #713 : enlever le paramŠtre par d‚faut 
         -- ============================================================================================
         -- Author:  <Page Olivier>
         -- Create date: <28/06/2013>
         -- Description: <15341: [Synchro] Nouveau type de stage : Fonction tutorale + synchro : 2- la synchro (2/2 : en v1.6.1)>
         -- ============================================================================================
         
         BEGIN
         --@ID_ACTIVITE recupere dans le code, mais sinon :
         
          IF (@ID_ACTIVITE < 0)
          BEGIN
           SET @ID_ACTIVITE = NULL
          END
         
         --*** recherche de l'activit‚e de l'‚tablissement
          --Uniformisation de l'activit‚e au 1er stagiaire de l'‚tablissement
          if (@ID_ACTIVITE IS NULL)
           select @ID_ACTIVITE = ID_ACTIVITE
           from stagiaire_pec
           where stagiaire_pec.id_module_pec = @ID_MODULE_PEC
           and stagiaire_pec.id_etablissement = @ID_ETABLISSEMENT
           and stagiaire_pec.id_session_pec is null
           order by id_stagiaire_pec
         
          --si on est au premier stagiaire de l'‚tablissement on cherche l'activit‚e de l'adh‚rent
          -- au p‚riode du module
          if (@ID_ACTIVITE IS NULL) 
           select @ID_ACTIVITE = R19.ID_ACTIVITE 
           from MODULE_PEC 
            inner join ETABLISSEMENT on (ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
            inner join R19 on ( R19.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT AND 
                 R19.ID_PERIODE = MODULE_PEC.ID_PERIODE and 
                 R19.ID_ACTIVITE  in (select id_activite from GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN')) -- 14822
                 )
           where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC 
         
          -- si toujours null, on lŠve une exception
          IF (@ID_ACTIVITE IS NULL) 
          BEGIN
           RAISERROR(N'Impossible d''attacher un ou plusieurs stagiaires : leur adh‚rent n''a pas d''activit‚', 16, 1)
          END
         
         --******** fin de recherche d'activit‚e
         
         INSERT INTO STAGIAIRE_PEC with (rowlock)
          (
           COD_STAGIAIRE_PEC,
           ID_INDIVIDU,
           ID_MODULE_PEC,
           ID_TYPE_CONTRAT,
           ID_CATEGORIE_ACTION,
           ID_CLASSIFICATION,
           ID_CSP,
           ID_STATUT,
           ID_ETABLISSEMENT,
           BLN_FORMATEUR_INTERNE,
           NB_HEURES_HORS_TT,
           NUM_DUREE_MENSUELLE_TRAVAIL,
           NB_HEURE_ENGAGE,
           NB_HEURE_REGLE,
           MATRICULE_SALARIE,
           LIB_AGENCE,
           LIB_DR,
           SALAIRE_HORAIRE_CHARGE,
           COM_STAGIAIRE_PEC,
           BLN_TEMPS_PARTIEL,
           CENTRE_COUT,
           ID_CODE_INSEE,
           ID_FAMILLE_PROFESSIONNELLE,
           SALAIRE_HORAIRE_NET,
           SALAIRE_HORAIRE_BRUT_CHARGE,
           MONTANT_BRUT_CHARGE,
           DATE_EMBAUCHE,
           ID_NIVEAU_AVENANT,
           ANALYTIQUE_STAGIAIRE,
           ID_STAGIAIRE_TUTEUR,
           ID_SESSION_PEC,
           ID_BRANCHE,
           ID_GROUPE,
           ID_ACTIVITE,
           NB_HEURE_REM,
           FONCTION,
           ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
           ID_SUIVI_STAGIAIRE_IMMEDIAT,
           ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          )  
         VALUES  
          (
           0,
           @ID_INDIVIDU,
           @ID_MODULE_PEC,
           @TYPE_CONTACT,
           @CATEGORIE_ACTION,
           @CLASSIFICATION,
           @CSP,
           @ID_STATUT,
           @ID_ETABLISSEMENT,
           @FORMATEUR_INTERNE,
           @NB_HEURES,
           @HORARIE_MENSUEL,
           @DUREE_PREVUE,
           @DUREE_REALISEE,
           @MATRICULE ,
           @AGENCE ,
           @DR, 
           @BRUT_CHARGE,
           @COM_STAGIAIRE,
           @BLN_TEMPS_PARTIEL,
           @CENTRE_COUT,
           @ID_CODE_INSEE,
           @ID_FAMILLE_PROFESSIONNELLE,
           @SALAIRE_HORAIRE_NET,
           @SALAIRE_HORAIRE_BRUT_CHARGE,
           @MONTANT_BRUT_CHARGE,
           @DATE_EMBAUCHE,
           @ID_NIVEAU_AVENANT,
           @ANALYTIQUE_STAGIAIRE,
           @ID_STAGIAIRE_TUTEUR,
           @ID_SESSION,
           @ID_BRANCHE,
           @ID_GROUPE,
           @ID_ACTIVITE,
           @NB_HEURE_REM,
           @FONCTION,
           @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
           @ID_SUIVI_STAGIAIRE_IMMEDIAT ,
           @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          )
         
         DECLARE @ID_STAGIAIRE_PEC INT
         SET @ID_STAGIAIRE_PEC = @@IDENTITY
         UPDATE STAGIAIRE_PEC
         SET  COD_STAGIAIRE_PEC = @ID_STAGIAIRE_PEC
         WHERE ID_STAGIAIRE_PEC = @ID_STAGIAIRE_PEC
         
         IF (@ID_SESSION is null or @ID_SESSION = 0)
         BEGIN
          UPDATE POSTE_COUT_ENGAGE SET BLN_OK_FINANCEMENT = 0
           WHERE ID_MODULE_PEC = @ID_MODULE_PEC
            AND DAT_DESENGAGEMENT IS NULL
            AND ID_ENGAGEMENT IS NULL 
          
         END
         SET @ID_STAGIAIRE = @ID_STAGIAIRE_PEC
         
         -- <OPA 28/06/2013>
         PRINT @FORMATEUR_INTERNE
         
         IF ( @FORMATEUR_INTERNE > 0)
         BEGIN
          UPDATE sp
          SET sp.ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE
          FROM STAGIAIRE_PEC sp
          INNER JOIN MODULE_PEC mp on mp.ID_MODULE_PEC = sp.ID_MODULE_PEC
          WHERE mp.ID_ACTION_PEC in (SELECT ID_ACTION_PEC FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC)
          AND mp.ID_MODULE_PEC <> @ID_MODULE_PEC
         END 
         -- </END OPA>
         
         SELECT @ID_STAGIAIRE AS ID
         
         END
GO

         -- ==============================================================
         -- Author:		Kwame Woollams
         -- Create date: 15 janvier 2008
         -- Description:	Insertion d'un type evenement admin
         -- ==============================================================
         CREATE PROCEDURE [dbo].[INS_TYPE_EVENEMENT_ADMIN]
         			@COD_TYPE_EVENEMENT_ADMIN	VARCHAR(20),
         			@LIBC_TYPE_EVENEMENT_ADMIN	VARCHAR(20), 
         			@LIBL_TYPE_EVENEMENT_ADMIN	VARCHAR(50), 
         			@BLN_PRIO					TINYINT, 
         			@BLN_ACTIF					TINYINT, 
         			@COM_TYPE_EVENEMENT_ADMIN	VARCHAR(255), 
         			@NUM_ORDRE					INT, 
         			@ID_UTILISATEUR				INT	
         AS 
         BEGIN
         	INSERT INTO TYPE_EVENEMENT_ADMIN
         			(
         				COD_TYPE_EVENEMENT_ADMIN, 
         				LIBC_TYPE_EVENEMENT_ADMIN, 
         				LIBL_TYPE_EVENEMENT_ADMIN, 
         				BLN_PRIO, 
         				BLN_ACTIF, 
         				DAT_MODIF, 
         				COM_TYPE_EVENEMENT_ADMIN, 
         				NUM_ORDRE, 
         				ID_UTILISATEUR, 
         				DAT_CREATION
         			)
         	VALUES
         			(
         				@COD_TYPE_EVENEMENT_ADMIN, 
         				@LIBC_TYPE_EVENEMENT_ADMIN, 
         				@LIBL_TYPE_EVENEMENT_ADMIN, 
         				@BLN_PRIO, 
         				@BLN_ACTIF, 
         				GETDATE(), 
         				@COM_TYPE_EVENEMENT_ADMIN, 
         				@NUM_ORDRE, 
         				@ID_UTILISATEUR, 
         				GETDATE()	
         			)
         
         
         	return @@IDENTITY
         END
