          @LIBL_IDCC VARCHAR(50),
         
         -- MBL Modif du 08/02/2016 : Rajout de toutes les colonnes de la table HISTO_CONTRAT_DGEFP non renvoy‚es en sortie de la PS 
          @NUM_DUREE_CONTRAT_PRO_MOIS     tinyint,
