         -- Author:		XXX
         -- Create date: XX XXXX 2007
         -- Description:	Obtention des donn‚es qui seront utilis‚es pour visualiser une action pec
         -- =============================================
         -- Author:		Say
         -- Modified:	05 oct. 2007
         -- Description: MANTIS 0006408 >> Mise … jour action : interdire la MAJ de l'action de cycle court vers long si elle a un PCR 
         -- =============================================
         -- Author:		Dorota Szeliga
         -- Modif. date: 11/03/2008
         -- Description:	C2P: Ajout DAT_RECU, ID_DECISION_ACTION_PEC,AXE,	DOMAINE, CODE_ACTION
         -- =============================================
         -- Author:		GLEG
         -- Modif. date: 11/04/2008
         -- Description: Ajout UCREATEUR.COD_UTIL AS CREATEUR
         -- =============================================
         -- 22/04/2008 MBE Ajout ID_CHARGEE_MISSION
         -- =============================================
         -- 18/07/2008 DSZE Ajout BLN_REPRISE_ADHOC
         -- =============================================
         -- 13/04/2011 Safi Ajout TOTAL_DUREE_UTILISE
         -- =============================================
         -- 10/05/2011 MAB Correction sur TOTAL_DUREE_UTILISE 12584
         -- =============================================
         -- 12/01/2012 APA Ajout Next Module Number = prochain nøordre de module
         -- =============================================
         -- 18/04/2012 RVI Ajout ID_AGENCE_CLOTURE et NUM_ARCHIVE
         -- =============================================
         -- 24/05/2012 APA Ajout arrondis
         -- =============================================
         -- 06/08/2012 DSZ 13800 Ajout bln_reprise_nessie
         -- =============================================
         CREATE PROCEDURE [dbo].[LEC_DET_ACTION_PRISES_SESSION]
         	@ID_ACTION int
         AS
         BEGIN
         
         	DECLARE @IS_ENGAGE	INT
         	DECLARE @IS_PAS_ENTIEREMENT_ENGAGEE BIT
         	DECLARE @NB_PCR		INT
         	DECLARE @NB_PCE		INT
         
         	SELECT @IS_ENGAGE = COUNT(*)
         	FROM ENGAGEMENT
         	WHERE ID_ACTION_PEC = @ID_ACTION
         
         
         	SET @IS_PAS_ENTIEREMENT_ENGAGEE=0
         
               IF (dbo.SiActionPecPasEntierementEngagee(@ID_ACTION)>0)
         	BEGIN
         		SET @IS_PAS_ENTIEREMENT_ENGAGEE=1
         	END
         	
         	select @NB_PCR = count(*) from POSTE_COUT_REGLE
         		INNER JOIN SESSION_PEC		on	SESSION_PEC.ID_SESSION_PEC	= POSTE_COUT_REGLE.ID_SESSION_PEC
         		INNER JOIN MODULE_PEC		on	MODULE_PEC.ID_MODULE_PEC	= SESSION_PEC.ID_MODULE_PEC
         	where id_action_pec = @ID_ACTION
         
         
         	SELECT  @NB_PCE = COUNT(*)
         	FROM	POSTE_COUT_ENGAGE
         			INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC
         			INNER JOIN  ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION
         
         	select 
         		ACTION_PEC.ID_ACTION_PEC,
         		ACTION_PEC.COD_ACTION_PEC AS NUM_ACTION, 
         		ACTION_PEC.LIBL_ACTION_PEC AS LIBL_ACTION, 
         		ACTION_PEC.ID_THEME,
         		ACTION_PEC.ID_NIVEAU,
         		ACTION_PEC.ID_SANCTION,
         		ACTION_PEC.DAT_DEB_ACTION_PEC AS DATE_DEBUT, 
         		ACTION_PEC.DAT_FIN_ACTION_PEC AS DATE_FIN,
         		ACTION_PEC.NUM_DUREE_JOUR, 
         		ACTION_PEC.NUM_DUREE_HEURE,
         		ACTION_PEC.ID_OPERATION_FINANCIERE as ID_OPERATION,	
         		ACTION_PEC.ID_AGENCE,
         		ACTION_PEC.CIBLE_ACTION AS CIBLE_ACTION, 
         		ACTION_PEC.DAT_CREATION, 
         		ACTION_PEC.DAT_MODIF, 
         		ACTION_PEC.ID_UTILISATEUR,
         		UTILISATEUR.COD_UTIL AS PAR,
         		UCREATEUR.COD_UTIL as CREATEUR,
         		ACTION_PEC.BLN_ACTIF AS ACTIF,
         		ROUND (ACTION_PEC.NUM_DUREE_JOUR - 
         			isnull((Select SUM(MODULE_PEC .NUM_DUREE_JOUR)
         				from MODULE_PEC
         				WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         					AND MODULE_PEC.BLN_ACTIF = 1
         				GROUP BY MODULE_PEC .ID_ACTION_PEC),0), 2)
         			as MAX_DUREE_JOUR,
         		ROUND (ACTION_PEC.NUM_DUREE_HEURE -
         			ISNULL((SELECT SUM(MODULE_PEC.NUM_DUREE_HEURE)
         					FROM MODULE_PEC
         					WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         						AND MODULE_PEC.BLN_ACTIF = 1
         					GROUP BY MODULE_PEC.ID_ACTION_PEC),0), 2)
         			AS MAX_DUREE_HEURE,
         		ACTION_PEC.BLN_CYCLE_COURT,
         		ISNULL((SELECT SUM(MODULE_PEC.NUM_DUREE_HEURE)
         					FROM MODULE_PEC
         					WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         						AND MODULE_PEC.BLN_ACTIF = 1
         					GROUP BY MODULE_PEC.ID_ACTION_PEC),0)
         		AS TOTAL_DUREE_UTILISE,
         		ACTION_PEC.COM_ACTION_PEC,
         		(SELECT TOP 1 NUM_DUREE_JOUR_ACTION_MAX
         			FROM PARAMETRES) AS NUM_DUREE_JOUR_ACTION_MAX,
         		(SELECT TOP 1 NUM_DUREE_HEURE_ACTION_MAX
         			FROM PARAMETRES) AS NUM_DUREE_HUERE_ACTION_MAX,
         		ACTION_PEC.ID_FORMACODE,
         		CASE 
         			WHEN @IS_ENGAGE > 0 THEN 1
         			ELSE 0 
         		END			AS ENGAGE,
         		ACTION_PEC.TIME_STAMP,
         		ACTION_PEC.DAT_CLOTURE,
                 @IS_PAS_ENTIEREMENT_ENGAGEE AS IS_PAS_ENTIEREMENT_ENGAGEE,
         		@NB_PCR AS NB_PCR,
         		@NB_PCE AS NB_PCE,
         		ACTION_PEC.ANNEE_ACTION_PEC,
         		ACTION_PEC.DAT_RECU,
         		ACTION_PEC.ID_DECISION_ACTION_PEC,
         		ACTION_PEC.AXE,
         		ACTION_PEC.DOMAINE,
         		dbo.GetActionPECCode(ACTION_PEC.COD_ACTION_PEC,ACTION_PEC.ANNEE_ACTION_PEC) AS CODE_ACTION,
         		ACTION_PEC.ID_CHARGEE_MISSION,
         		isnull(ACTION_PEC.BLN_REPRISE_ADHOC,0) AS BLN_REPRISE_ADHOC,
         		(SELECT  COUNT(*) + 1
         		FROM MODULE_PEC
         		WHERE ID_ACTION_PEC=@ID_ACTION) AS NEXT_MODULE_NUMBER,
         		ACTION_PEC.ID_AGENCE_CLOTURE,
         		ACTION_PEC.NUM_ARCHIVE,
         		ACTION_PEC.BLN_REPRISE_NESSIE 
         	from ACTION_PEC 
         			INNER JOIN UTILISATEUR ON UTILISATEUR.ID_UTILISATEUR = ACTION_PEC.ID_UTILISATEUR
         			INNER JOIN UTILISATEUR UCREATEUR ON UCREATEUR.ID_UTILISATEUR = ACTION_PEC.ID_UTILISATEUR_CREATEUR
         
         	WHERE ACTION_PEC.ID_ACTION_PEC = @ID_ACTION
         	
         END
         
         
GO

         -- =============================================
         -- Author		: XXX
         -- Create date	: XX XXX XXX
         -- comment		: # lecture groupe pour les sous type de cout
         -- ---------------------------------------------
         -- Author		: Say
         -- Modified date: 30 juillet 2007
         -- comment		: # ajout du montant "MNT chiffr‚ "
         -- ---------------------------------------------
         -- Author		: Say
         -- Modified date: 06 ao–t 2007
         -- comment		: # montant "MNT chiffr‚ " devient "MNT reste … engager"
         -- ---------------------------------------------
         -- Author		: Say
         -- Modified date: 08 ao–t 2007
         -- comment		: # montant "MNT reste … engager" redevient "MNT chiffr‚" et les regles sont all‚ges
         -- ---------------------------------------------
         -- Author		: SVA
         -- Modified date: 05 septembre 2007
         -- comment		: Ajout de la valeur @BLN_CREATION dans la sortie pour que l'information puisse ˆtre r‚percut‚e dans la proc‚dure UPD_SOUS_TYPE_COUT_MODULE_PEC plus tard
         -- ---------------------------------------------
         -- Author		: SVA
         -- Modified date: 04 octobre 2007
         -- comment		: Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚
         -- ---------------------------------------------
         -- Author		: SVA
         -- Modified date: 05 octobre 2007
         -- comment		: Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚ calcul‚ pour la colonne r‚gl‚ (r‚el)
         -- ---------------------------------------------
         -- Author		: MBL
         -- Modified date: 19 octobre 2007
         -- comment		: Modification pour prise en compte des postes de cout engage … 0
         -- ---------------------------------------------
         -- Author		: kw
         -- Modified date: 5 decembre 2007
         -- comment		:Prise en compte unique des engagements avec id_type_engagement a null
         -- soit id_type_engagement = 1 (ce qui evite l'affichage des poste cout engag‚s qui ont ‚t‚ desengag‚s)
         -- ---------------------------------------------
         -- Author		: DSZ
         -- Modified date: 18/04/2008
         -- comment		:Modifie calcul MNT_CHIFFRE pour prendre en compte PLAN_FNANCEMENT_US
         -- ============================================= 
         -- Author		: SAFI
         -- Modified date: 18/04/2008
         -- comment		: Re SUM(MNT_ACCORDE) according to ID_SOUS_TYPE_COUT from #TEMPLIST
         -- ============================================= 
         -- Author		: SAFI
         -- Modified date: 11/02/2009
         -- comment		: Add the SOUS_TYPE_COUT.BLN_ACTIF in the selection 
         --				  and remove the condition by SOUS_TYPE_COUT.BLN_ACTIF = 1
         -- ============================================= 
         -- Author		: MBE(de SIRUS)/SAFI/ASD
         -- Modified date: 15 Sep 2008
         -- comment		: AJOUT D'UN FILTRE TYPE_ENGAGEMENT SUR LES PCE 
         -- 				  ENGAGEMENT.ID_TYPE_ENGAGEMENT = 3
         -- ---------------------------------------------
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         ----------------------------------------------  
         
         CREATE PROCEDURE [dbo].[LEC_GRP_SOUS_TYPE_COUT_MODULE_PEC]
            @ID_MODULE int,
            @BLN_CREATION int
         AS
         BEGIN
         	CREATE TABLE #TEMPLIST
         	(
         		ID_SOUS_TYPE_COUT INT,
         		MNT_ACCORDE DECIMAL(18,2)
         	)
         
         /*	
         COMMENTED BY SAFI
         	INSERT INTO #TEMPLIST (ID_SOUS_TYPE_COUT, MNT_ACCORDE)
         	SELECT 
         		SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
         		SUM (isnull(POSTE_COUT_REGLE.MNT_REGLE_HT,0))
         	FROM SOUS_TYPE_COUT
         		LEFT JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         		AND POSTE_COUT_REGLE.ID_MODULE_PEC = @ID_MODULE
         		LEFT JOIN REGLEMENT ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
         	GROUP BY SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT, DAT_VALID_REGLEMENT
         
         END COMMENT
         */
         
         
         	SELECT 
         		SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
         		SUM (isnull(POSTE_COUT_REGLE.MNT_REGLE_HT,0)) AS MNT_ACCORDE
         	INTO #LISTPREMIER
         	FROM SOUS_TYPE_COUT
         		LEFT JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         		AND POSTE_COUT_REGLE.ID_MODULE_PEC = @ID_MODULE
         		LEFT JOIN REGLEMENT ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
         	GROUP BY SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT, DAT_VALID_REGLEMENT
         
         
         -- Make a sum according to the Sous type Cout
          INSERT INTO #TEMPLIST (ID_SOUS_TYPE_COUT, MNT_ACCORDE)	
          SELECT ID_SOUS_TYPE_COUT, SUM(MNT_ACCORDE) FROM #LISTPREMIER GROUP BY ID_SOUS_TYPE_COUT
         
         
         
         	select 
         		isnull(sum(isnull(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0)),0) AS MNT_CHIFFRE,
         		PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         	into #TEMP_MNT_CHIFFRE
         	from PLAN_FINANCEMENT_US
         	left join POSTE_COUT_ENGAGE on POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         	where POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE
         	group by PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         
         
         	Select
         		DISTINCT(SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT)	AS ID_SOUS_TYPE_COUT,
         		SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT			AS SOUS_TYPE_COUT,
         		POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE		AS ID_POSTE_COUT_ENGAGE,
         		POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT		AS MNT_PREVISIONNEL,
         		CASE 
         			WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL OR
         				@BLN_CREATION = 1 
         			THEN 1 
         			ELSE 0 
         		END AS MODIFIABLE_MNT,
         		
         		CASE
         			WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
         				CASE
         					WHEN (DAT_DESENGAGEMENT	is NULL		AND (ID_TYPE_ENGAGEMENT	is null OR ID_TYPE_ENGAGEMENT	<> 2)	AND 
         							ENGAGEMENT.DAT_BAE	is NOT NULL) THEN POSTE_COUT_ENGAGE.MNT_ENGAGE_HT
         					ELSE 0
         				END
         			ELSE #TEMPLIST.MNT_ACCORDE
         		END											AS MNT_ENGAGE,
         
         --		CASE
         --			WHEN (DAT_DESENGAGEMENT	is NULL		AND (ID_TYPE_ENGAGEMENT	is null OR ID_TYPE_ENGAGEMENT	<> 2))/*	AND 
         --					(ENGAGEMENT.DAT_BAE is NULL OR POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL)) */
         --													THEN POSTE_COUT_ENGAGE.MNT_ENGAGE_HT
         --			ELSE 0
         --		END										AS MNT_CHIFFRE,
         		#TEMP_MNT_CHIFFRE.MNT_CHIFFRE			AS MNT_CHIFFRE,
         		#TEMPLIST.MNT_ACCORDE					AS MNT_ACCORDE,
         		@ID_MODULE								AS ID_MODULE,
         		POSTE_COUT_ENGAGE.ID_ENGAGEMENT,
         		@BLN_CREATION							AS MODE_CREATION,
         		SOUS_TYPE_COUT.BLN_ACTIF
         	FROM  SOUS_TYPE_COUT
         		LEFT JOIN POSTE_COUT_ENGAGE ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT
         			AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE
         			AND (
         				(@BLN_CREATION = 0) 
         				--AND (POSTE_COUT_ENGAGE.MNT_ENGAGE_HT >= 0)
         				)
         		LEFT JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         		LEFT JOIN MODULE_PEC ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         		LEFT JOIN #TEMPLIST ON #TEMPLIST.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         		LEFT JOIN #TEMP_MNT_CHIFFRE ON #TEMP_MNT_CHIFFRE.ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
         	WHERE
         		--SOUS_TYPE_COUT.BLN_ACTIF = 1 AND
         		POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL	AND 
         		(POSTE_COUT_ENGAGE.MNT_ENGAGE_HT>=0 OR POSTE_COUT_ENGAGE.MNT_ENGAGE_HT IS NULL)
         		AND (ENGAGEMENT.ID_TYPE_ENGAGEMENT IS NULL OR ENGAGEMENT.ID_TYPE_ENGAGEMENT = 1 OR ENGAGEMENT.ID_TYPE_ENGAGEMENT = 3)
         	ORDER BY SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         END   
         
         -- SAFI
         --select * from #TEMPLIST
         -- EN SAFI
         
GO

         
         -- =============================================
         -- Author			: MB
         -- Create date		: 05/04/2008 
         -- Description		: Lecture des taches … effectuer en agence
         -- =============================================
         
           
         CREATE PROCEDURE [dbo].[LEC_TACHE_AGENCE]
         /* Lecture des taches … effectuer */  
         @ID_UTIL int ,
         @MIN_AFF int
         AS   
         BEGIN
         	DECLARE 
         		@ID_AGENCE int,  
         		@NBR int	  
         
         	create table #TEMPO1  
         	 (APPLI VARCHAR (3),
         	  LIB CHAR(50) null,  
         	  NBR INTEGER null)  
         	  
         	  
         	select @ID_AGENCE=ID_AGENCE  
         	FROM UTILISATEUR  
         	WHERE ID_UTILISATEUR=@ID_UTIL  
         	  
         
         	/* Liste des taches de la PEC */
         	SET @NBR =0
         	EXECUTE LEC_GRP_ETABLISSEMENT_PEC_ENGAGEMENT_ADH @ID_AGENCE, @NBR OUTPUT  
         	  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Lettre d''engagement Adh',  
         	 NBR = @NBR  
         	END  
         
         
         
         	SET @NBR =0
         	EXEC EDT_LISTE_BAP_SESSION 1, NULL, NULL, @ID_UTIL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,@NBR	
         	  
         	IF @NBR>=@MIN_AFF 
