         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Liste BAP',  
         	 NBR = @NBR  
         	END  
         
         
         	SET @NBR =0
         	EXECUTE LEC_GRP_ETABLISSEMENT_RELANCE_ENGAGEMENT_ADH @ID_AGENCE, @NBR OUTPUT  
         	  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
