         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Rejet Adh',  
         	 NBR = @NBR  
         	END  
         
         
         	SET @NBR =0
         	EXECUTE LEC_GRP_ACTION_ENGAGER @ID_AGENCE, @NBR OUTPUT  
         	  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Bons A Engager',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
