         	END  
         
         
         	/* Liste des taches du contrat de pro */
         	SET @NBR =0
         	EXEC EDT_LISTE_BAP_SESSION_PRO 1, NULL, NULL, @ID_UTIL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,@NBR	
         
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Liste BAP',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre engagement pro Adh',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre engagement pro OF',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_RELANCE_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance engagement pro Adh',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_RELANCE_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance engagement pro OF',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_RELANCE_REGLEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance rŠglement pro Adh',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_RELANCE_REGLEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance rŠglement pro OF',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_ADH null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement Adh',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_ADH_TUTORAL null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement tut.',  
         	 NBR = @NBR  
         	END  
         
         
         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_OF null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement OF',  
         	 NBR = @NBR  
         	END  
         
         	SET @NBR =0
         	EXEC LEC_GRP_CONTRAT_PRO_A_ENGAGER @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'BAE',  
         	 NBR = @NBR  
         	END  
         
         
         	SET @NBR =0
         	EXEC LEC_GRP_BON_A_PAYER_PRO @ID_AGENCE, @NBR OUTPUT  
