         	 LIB = 'BAP',  
         	 NBR = @NBR  
         	END  
         
         
         	select * from #TEMPO1  
         
         
         
         END
GO
 CREATE PROCEDURE [dbo].[UPD_PLAN_FINANCEMENT_US]
         -- =============================================
         -- Author: MB (pour le FAF Propret‚)
         -- Modif. date: 12/02/2008
         -- Description: - Modification pour empecher de supprimer les mouvements budgetaires associes aux reglements
         -- =============================================
         -- Author: SAF & ASD
         -- Modif. date: 18/03/2009
         -- Description: - R‚cup‚ration de la version pour C2P
         -- =============================================
         -- DSZ 17/04/2013 15133
         -- on ne supprime plus les mvts budgetaires, on les annule si le montant du pce est 0
         -- =============================================
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         -- =============================================
         -- HBO - OPA - 20140801 #148D
         -- =============================================
         -- HBO - #578 - On ne supprime pas les PFUS
         -- =============================================
          @ID_UNITE_STAGIAIRE  INT,
          @ID_POSTE_COUT_ENGAGE INT,
          @ID_DISPOSITIF   INT,
          @ID_MODULE    INT,
          @BLN_PLUS10    BIT,
          @HOURS_ALL    DECIMAL(18,2),
          @HOURS_STAGIAIRE  DECIMAL(18,2),
          @MNT_POSTE_COUT_ENGAGE DECIMAL(18,2)
         AS
         BEGIN
          IF (@MNT_POSTE_COUT_ENGAGE <> 0)
          BEGIN
           DECLARE
            @MNT_PLAN_FINANCEMENT_US DECIMAL(18,2)
         
           -- CALCULATES MNT_PLAN_FINANCEMENT_US
           SET @MNT_PLAN_FINANCEMENT_US = (@MNT_POSTE_COUT_ENGAGE * @HOURS_STAGIAIRE) / @HOURS_ALL
         
           UPDATE
            PLAN_FINANCEMENT_US
           SET
            MNT_PLAN_FINANCEMENT_US = @MNT_PLAN_FINANCEMENT_US
           WHERE 
            ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
            AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE
          END
         END
GO

         CREATE PROCEDURE [dbo].[UPD_ADHERENT]
         	@ID_ADHERENT int,
         	@ID_AGENCE int,
         	@ID_ADRESSE_PRINCIPALE int,
         	@ID_MODE_PAIEMENT int,
         	@ID_BRANCHE int,
         	@ID_GROUPE int,
         	@ID_IDCC int,
         	@ID_MODE_VERSEMENT int,
         	@ID_NAF int,
         	@ID_ETABLISSEMENT_PRINCIPAL int,
         	@ID_SITUATION_FAF int,
         	@NUM_SIREN varchar(9),
         	@LIB_RAISON_SOCIALE varchar(50),
         	@LIB_SIGLE_ADHERENT varchar(15),
         	@BLN_ACTIF tinyint,
         	@BLN_ASSUJETTI_TA tinyint,
         	@BLN_GESTION_GROUPE tinyint,
         	@COM_ADHERENT varchar(255),
         	@BLN_HABILIT_ALTERNANCE tinyint,
         	@ID_UTILISATEUR int,
         	@LIB_MOT_PASSE varchar(30),
         	@EMAIL varchar(100),
         	@DAT_DEBUT_GROUPE datetime,
         	@LIB_ENSEIGNE varchar(35),
         	@BLN_MOINS_10 tinyint,
         	@ANNEE_MOINS_10 varchar(4),
         	@BLN_10_19 tinyint,
         	@ANNEE_10_19 varchar(4),
         	@BLN_20_PLUS tinyint,
         	@ANNEE_20_PLUS varchar(4),
         	@ID_TIERS_MANDATAIRE int,
         	@ID_ADHERENT_REPRENEUR int,
         	@ID_SITUATION_ECONOMIQUE int,
         	@ID_TYPE_TVA int,
         	@BLN_SERVICE_PERSONNE tinyint,
         	@TIME_STAMP timestamp,
         	@ID_CHARGEE_MISSION int,
         	@ID_CHARGEE_RELATION int,
         	@ID_TIERS_CABINET_COMPTABLE int,
         	@ID_SYNDICAT int,
         	@ID_FEDERATION int,
         	@SITE_WEB_ADHERENT varchar(100),
         	@ID_GROUPE_STATISTIQUE int,
         	@DAT_SITUATION_ECONOMIQUE datetime,
         	@LIB_TIERS_MANDATAIRE varchar(50)
         
         	
         AS
         
         /* MAJ MB du 18/07/2007 : 
         	Renseignement du sigle de l'adherent avec la raison sociale lorsque le sigle est null 
         */
         	if @LIB_SIGLE_ADHERENT is null
         	BEGIN
         		SET @LIB_SIGLE_ADHERENT  = SUBSTRING(@LIB_RAISON_SOCIALE, 1, 15)
         	END
             DECLARE @ID_PERIODE_ENCOURS INT
             
             select top 1 @ID_PERIODE_ENCOURS = ID_PERIODE
             from PERIODE
             where BLN_EN_COURS = 1 and BLN_ACTIF = 1 
             
         	DECLARE @ANNEE_10_19_OLD varchar(4)
         	DECLARE @ANNEE_20_PLUS_OLD varchar(4)
         	
         	select 
         			@ANNEE_10_19_OLD = ANNEE_10_19,
         			@ANNEE_20_PLUS_OLD = ANNEE_20_PLUS
         	from ADHERENT
         	where
         			ID_ADHERENT = @ID_ADHERENT
         		and	TIME_STAMP = @TIME_STAMP
         		
         	update ADHERENT set
         			ID_AGENCE = @ID_AGENCE,
         			ID_ADRESSE_PRINCIPALE = @ID_ADRESSE_PRINCIPALE,
         			ID_MODE_PAIEMENT = @ID_MODE_PAIEMENT,
         			ID_BRANCHE = @ID_BRANCHE,
         			ID_GROUPE = @ID_GROUPE,
         			ID_IDCC = @ID_IDCC,
         			ID_MODE_VERSEMENT = @ID_MODE_VERSEMENT,
         			ID_NAF = @ID_NAF,
         			ID_ETABLISSEMENT_PRINCIPAL = @ID_ETABLISSEMENT_PRINCIPAL,
         			ID_SITUATION_FAF = @ID_SITUATION_FAF,
         			NUM_SIREN = @NUM_SIREN,
         			LIB_RAISON_SOCIALE = @LIB_RAISON_SOCIALE,
         			LIB_SIGLE_ADHERENT = @LIB_SIGLE_ADHERENT,
         			BLN_ACTIF = @BLN_ACTIF,
         			BLN_ASSUJETTI_TA = @BLN_ASSUJETTI_TA,
         			BLN_GESTION_GROUPE = 1, --@BLN_GESTION_GROUPE, --D‚sormais Gestion de groupe tjours … TRUE
         			COM_ADHERENT = @COM_ADHERENT,
         			BLN_HABILIT_ALTERNANCE = @BLN_HABILIT_ALTERNANCE,
         			ID_UTILISATEUR = @ID_UTILISATEUR,
         			LIB_MOT_PASSE = @LIB_MOT_PASSE,
         			EMAIL = @EMAIL,
         			DAT_DEBUT_GROUPE = @DAT_DEBUT_GROUPE,
         			LIB_ENSEIGNE = @LIB_ENSEIGNE,
         			BLN_MOINS_10 = @BLN_MOINS_10,
         			ANNEE_MOINS_10 = @ANNEE_MOINS_10,
         			BLN_10_19 = @BLN_10_19,
         			ANNEE_10_19 = @ANNEE_10_19,
         			BLN_20_PLUS = @BLN_20_PLUS,
         			ANNEE_20_PLUS = @ANNEE_20_PLUS,
         			ID_TIERS_MANDATAIRE = @ID_TIERS_MANDATAIRE,
         			ID_ADHERENT_REPRENEUR = @ID_ADHERENT_REPRENEUR,
         			ID_SITUATION_ECONOMIQUE = @ID_SITUATION_ECONOMIQUE,
         			DAT_MODIF = getDate(),
         			ID_TYPE_TVA = @ID_TYPE_TVA,
         			BLN_SERVICE_PERSONNE = @BLN_SERVICE_PERSONNE,
         			ID_CHARGEE_MISSION = @ID_CHARGEE_MISSION,
         			ID_CHARGEE_RELATION = @ID_CHARGEE_RELATION,
         			ID_TIERS_CABINET_COMPTABLE = @ID_TIERS_CABINET_COMPTABLE,
         			ID_SYNDICAT = @ID_SYNDICAT,
         			ID_FEDERATION = @ID_FEDERATION,
         			SITE_WEB_ADHERENT = @SITE_WEB_ADHERENT,
         			ID_GROUPE_STATISTIQUE = @ID_GROUPE_STATISTIQUE,
         			DAT_SITUATION_ECONOMIQUE = @DAT_SITUATION_ECONOMIQUE,
         			LIB_TIERS_MANDATAIRE = @LIB_TIERS_MANDATAIRE
         
         	where	ID_ADHERENT = @ID_ADHERENT
         		and	TIME_STAMP = @TIME_STAMP
         
         		IF @@ROWCOUNT = 0   
         		BEGIN  
         		   IF EXISTS(SELECT * FROM ADHERENT WHERE ID_ADHERENT  = @ID_ADHERENT)      
         		   BEGIN  
         		      /* Probl?me de Concurrence d'acc?s */  
         		      RAISERROR(50001, 16, 1)  
         		   END  
         		   ELSE  
         		   BEGIN  
         		      /* L'enregistrement a ?t? d?truit */  
         		      RAISERROR(50002, 16, 1)  
         		   END  
         		END 
         		ELSE
         		BEGIN
         		IF(@ANNEE_10_19_OLD <> @ANNEE_10_19 or @ANNEE_20_PLUS_OLD <> @ANNEE_20_PLUS)
         		UPDATE VERSEMENT 
         		SET 
         		SYNC_BLN_SYNCHRO_SSIS = 1,
         		SYNC_DAT_SYNCHRO_SSIS = GETDATE()
         		FROM POSTE_VERSEMENT 
         		where POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT and
         		POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT and 
         		POSTE_VERSEMENT.ID_PERIODE = @ID_PERIODE_ENCOURS
         		END
         
GO
CREATE PROCEDURE [dbo].[UPD_SOUS_TYPE_COUT_MODULE_PEC]
         -- =============================================
         -- Author:  xxx
         -- Create date: xx xxx 2007
         -- Description: insert / Maj des sous type de cout et autres 
         -- ---------------------------------------------
         -- Author:  SAY
         -- Modif. date: 08 aout 2007
         -- Description: changement du para en mnt chiffre
         -- ---------------------------------------------
         -- Author:  SVA
         -- Modif. date: 05 septembre 2007
         -- Description: Ajout du paramŠtre @MODE_CREATION pour d‚finir la valeur du champ BLN_OK_FINANCEMENT lors de la cr‚ation d'un P.C.E.
         -- ---------------------------------------------
         -- Author:  ED
         -- Modif. date: 14 Janvier 2008
         -- Description: Ajout DATE_CREATION, DATE_MODIF dans le PCE
         -- ---------------------------------------------
         -- 28/04/08 DSZE
         -- pendant creation BLN_OK_FINANCEMENT doit etre mis a 0
         -- il va etre change uniquement apres Approuver sur l'ecran de chiffrage
         -- ---------------------------------------------
         -- 03/06/09 ASD
         -- Modif gestion @MNT_CHIFFRE si param = NULL
         -- Report modif FAF/MBL pour ne pas suppr de mvt_budg de reglement
         -- ---------------------------------------------
         -- 12/06/09 DSZ + ASD
         -- EVOL 400 (Mantis 12078)
         -- si mnt_previsionnel = 0 mettre 0 dans plan_financement_us
         -- bonus + : ne pas supprimer l'historique des PCE, EVNT, MVT_BUDG, PFU
         -- ---------------------------------------------
         -- 24/06/09 ASD
         -- EVOL 400 (Mantis 12078)
         -- correction pb acces concurrentiel li‚ au codage du bonus
         -- bonus + : ne pas supprimer l'historique des PCE, EVNT, MVT_BUDG, PFU
         -- ---------------------------------------------
         -- 26/06/09 ASD
         -- Modification du contenu de l'EVOL 400 (Mantis 12078)
         -- R‚alis‚ et annul‚, remplac‚ cause impact mvt_budg de P, 
         -- par l'affichage dans l'‚cran de chiffrage des lignes avec mnt_dem=0 si mnt_chiff<>0
         -- ---------------------------------------------
         -- 01/07/09 ASD
         -- Modification du contenu de l'EVOL 400 (Mantis 12078)
         -- Mise … jour des lignes avec mnt_dem=0 et mnt_chiff=0
         -- ---------------------------------------------
         -- 07/07/09 ASD
         -- Update PCE meme si mnt_demande=0 (ici mnt_prev=mnt_demande)
         -- ---------------------------------------------
         -- 21/08/09 DSZ Mantis 12201
         -- Faut pas changer le mnt_engage de poste cout qui sont desengages
         -- ---------------------------------------------
         -- 24/11/09 SAFI Mantis 12249
         -- Problem on updating, as the update fails it raises an exception,
         -- added a dummy update for dataset to continue without any error.
         -- ---------------------------------------------
         -- 09/12/09 DSZ Mantis 12290
         -- ne pas toucher si on ne change pas le montant previsionnel ->ne pas change bln_ok_financement
         -- si montant previsionnel =0 on laisse bln_ok_financement a 1. sinon il bloque engagement
         -- ---------------------------------------------
         -- 16/02/10 DSZ Mantis 12307 
         -- la logique ‚tait bonne sauf que select @x = ... ne remplit pas @x avec null si pas de r‚sultats!
         -- il garde l'ancien valeur. contrairement … ce qu'on attend
         -- ---------------------------------------------
         -- 05/01/11 DSZ Mantis 12599
         -- Si le mnt_previsionnel … 0 et modif de PCE 
         --  => modifier aussi les PFUS et anuller les mvts budgetaires P
         -- ---------------------------------------------
         -- 05/04/2011 DSZ ASD Mantis 12736
         -- ajout ‚clatement mvt budgetaire par compte et etablissement
         -- l'‚tablissement vient du PFUS et le compte du MVT budgetaire.
         --- ---------------------------------------------
         -- 24/05/2011 DSZ suite … la note dans 12599 : ajout close et deallocate cu_mvt
         -- ---------------------------------------------
         -- 04/11/2011 DSZ 12840 modif calcul du mvt budg de l'annulation si mnt previsionnel … 0
         -- prendre en compte le  sous-type_cout
         -- aussi: ne pas annuler a cause de remise … 0 si module inactif (annulation fait d‚j…)
         -- ---------------------------------------------
         -- 13/02/2102 DSZ 13245
         -- remise du code d'annulation dans la PS ANNULER_MVTS_PREV_POUR_PCE 
         -- Attention : suppression du parametre @MODE_CREATION 
         -- ============================================= 
         -- HBO - OPA - 20140801 #148D
         -- =============================================
         -- DSZ - 2014/09/04 #484
         -- Toute modification d'un module PEC devra d‚sormais entraŒner la d‚sapprobation (POSTE_COUT_ENGAGE.BLN_OK_FINANCEMENT = 0) 
         -- de tous les postes de co–t d'engagement non encore engag‚s (et non d‚sengag‚s) associ‚s au module modifi‚.
         --===============================================
         -- HBO - #578
         -- =============================================
          @ID_SOUS_TYPE_COUT  INT,
          @ID_MODULE_PEC   INT,
          @MNT_PREVISIONNEL  DECIMAL(18,2),  
          @MNT_CHIFFRE   DECIMAL(18,2),
          @ID_POSTE_COUT_ENGAGE INT OUTPUT
         AS
         BEGIN
          DECLARE
           @NUMREG int
         
          SELECT
           @NUMREG = COUNT(*)
          FROM
           POSTE_COUT_ENGAGE 
          WHERE
           ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT
           AND ID_MODULE_PEC = @ID_MODULE_PEC
           AND DAT_DESENGAGEMENT IS NULL
         
          IF (@MNT_PREVISIONNEL IS NULL)
          BEGIN
           SET @MNT_PREVISIONNEL = 0
          END
         
          IF (@MNT_CHIFFRE IS NULL)
          BEGIN
           SET @MNT_CHIFFRE = 0
          END
         
          IF (@MNT_PREVISIONNEL <> 0) 
          BEGIN
           IF (@NUMREG = 0)  --creation de pce
           BEGIN
            INSERT INTO POSTE_COUT_ENGAGE
            (
             COD_POSTE_COUT_ENGAGE,
             ID_MODULE_PEC,
             ID_SOUS_TYPE_COUT,
             MNT_PREVISIONNEL_HT,
             MNT_ENGAGE_HT,
             BLN_OK_FINANCEMENT,
             DAT_CREATION
            )
            VALUES
            (
             0,
             @ID_MODULE_PEC,
             @ID_SOUS_TYPE_COUT,
             @MNT_PREVISIONNEL,
             @MNT_CHIFFRE,
             0,
             getdate()
            )
         
            UPDATE
             POSTE_COUT_ENGAGE
            SET
             COD_POSTE_COUT_ENGAGE = @@IDENTITY
            WHERE
             ID_POSTE_COUT_ENGAGE = @@IDENTITY
         
            SET @ID_POSTE_COUT_ENGAGE = @@IDENTITY
           END
           ELSE   ----modif de pce
           BEGIN
            --VERIF: SI ON NE CHANGE PAS LE MONTANT PREVISIONNEL, ON NE FAIT RIEN
            DECLARE
             @OLD_MNT_PREV DECIMAL (18,2),
             @ID_PCE_NONENGAGE INT
            
            SET @ID_PCE_NONENGAGE = NULL
         
            SELECT
             @ID_PCE_NONENGAGE = ID_POSTE_COUT_ENGAGE ,
             @OLD_MNT_PREV = MNT_PREVISIONNEL_HT
            FROM
             POSTE_COUT_ENGAGE 
            WHERE
             ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT 
             AND ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 
         
            IF (@OLD_MNT_PREV = @MNT_PREVISIONNEL)
            BEGIN
             RETURN
            END
            
            IF (@ID_PCE_NONENGAGE IS NOT NULL)
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              MNT_PREVISIONNEL_HT  = @MNT_PREVISIONNEL,-- =0
              MNT_ENGAGE_HT = @MNT_PREVISIONNEL,-- =0
              BLN_OK_FINANCEMENT = 0,
              DAT_MODIF = Getdate()
             WHERE 
              ID_POSTE_COUT_ENGAGE  = @ID_PCE_NONENGAGE
              AND ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT
            END
            ELSE
            BEGIN
             -- dummy update pour que rowcount <>0
             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              DAT_MODIF = DAT_MODIF
             WHERE 
              ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT  
              AND ID_MODULE_PEC = @ID_MODULE_PEC
            END    
           END --modif de PCE existant
         
           IF @@ROWCOUNT = 0   
           BEGIN  
            IF EXISTS(
             SELECT * FROM POSTE_COUT_ENGAGE 
             WHERE ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT 
              AND ID_MODULE_PEC = @ID_MODULE_PEC
             )  
            BEGIN
             RAISERROR(50001, 16, 2)  
            END
            ELSE
            BEGIN
             RAISERROR(50002, 16, 2)  
            END
           END       
          END
          ELSE --mnt_previsionnel = 0
          BEGIN
           IF (@NUMREG <> 0) --PCE existent
           BEGIN
            DECLARE
             @ID_PCE INT
         
            SET @ID_PCE = NULL
            
            SELECT
             @ID_PCE = ID_POSTE_COUT_ENGAGE 
            FROM
             POSTE_COUT_ENGAGE 
            WHERE
             ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT  
             AND ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 
            
            IF (@ID_PCE IS NOT NULL)
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              MNT_PREVISIONNEL_HT  = @MNT_PREVISIONNEL,-- =0
              MNT_ENGAGE_HT = @MNT_PREVISIONNEL,-- =0
              DAT_MODIF = Getdate()
             WHERE 
              ID_POSTE_COUT_ENGAGE  = @ID_PCE  
         
             UPDATE
              PLAN_FINANCEMENT_US
             SET 
              MNT_PLAN_FINANCEMENT_US = 0,
              MNT_PLAN_FINANCEMENT_US_TVA = 0
             FROM
              PLAN_FINANCEMENT_US PFUS
             WHERE
              PFUS.ID_POSTE_COUT_ENGAGE = @ID_PCE
              AND PFUS.ID_POSTE_COUT_REGLE IS NULL
            END
            ELSE --@ID_PCE is null
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE 
             SET
              DAT_MODIF  = DAT_MODIF
             WHERE 
              ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT  
              AND ID_MODULE_PEC = @ID_MODULE_PEC       
            END 
           END
          END
         END
GO

