         CREATE PROCEDURE [dbo].[INS_OR_UPD_PARAM_GLOBAL] 
         	-- Add the parameters for the stored procedure here
         	@ID_PARAM_GLO int,
         	@ID_TYPE_ASSUJETISSEMENT int,
         	@ID_ACTIVITE int,
         	@COD_PARAM_GLO int,
         	@TAU_GLO_APPEL decimal(10,5),
         	@TAU_MIN tinyint,
         	@MNT_MIN int,
         	@BLN_ACTIF tinyint,
         	@COM_PARAM_GLO varchar(255),
         	@ID_PERIODE int,
         	@ID_REGIME int
         AS
         BEGIN
         	SET NOCOUNT ON;
         
         	if exists (select 1 from PARAMETRE_GLOBAL where ID_PARAM_GLO = @ID_PARAM_GLO)
         		UPDATE PARAMETRE_GLOBAL SET
         			ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT,
         			ID_ACTIVITE =	@ID_ACTIVITE,
         			COD_PARAM_GLO = @COD_PARAM_GLO,
         			TAU_GLO_APPEL = @TAU_GLO_APPEL,
         			TAU_MIN =		@TAU_MIN,
         			MNT_MIN =		@MNT_MIN,
         			BLN_ACTIF =		@BLN_ACTIF,
         			COM_PARAM_GLO = @COM_PARAM_GLO ,
         			ID_PERIODE =	@ID_PERIODE,
         			ID_REGIME =		@ID_REGIME 
         		WHERE ID_PARAM_GLO = @ID_PARAM_GLO
         	else
         		INSERT INTO [PARAMETRE_GLOBAL] ([ID_PARAM_GLO],[ID_TYPE_ASSUJETISSEMENT],[ID_ACTIVITE],[COD_PARAM_GLO],[TAU_GLO_APPEL],[TAU_MIN],[MNT_MIN],[BLN_ACTIF],[COM_PARAM_GLO],[ID_PERIODE],[ID_REGIME])
         		VALUES(@ID_PARAM_GLO,@ID_TYPE_ASSUJETISSEMENT,@ID_ACTIVITE,@COD_PARAM_GLO,@TAU_GLO_APPEL,@TAU_MIN,@MNT_MIN,@BLN_ACTIF,@COM_PARAM_GLO,@ID_PERIODE,@ID_REGIME)
         END
         
GO

