         -- Author:		Kwame Woollams
         -- Create date: 15 janvier 2008
         -- Description:	Insertion d'un evenement admin
         -- ==============================================================
         CREATE PROCEDURE [dbo].[INS_EVENEMENT_ADMIN] 
         				@LIBL_EVENEMENT_ADMIN		VARCHAR(100), 
         				@ID_UTILISATEUR				INT, 
         				@ID_TYPE_EVENEMENT_ADMIN	INT, 
         				@ID_CONTRAT_PRO				INT, 
         				@BLN_ACTIF					TINYINT, 
         				@DAT_EVENEMENT_ADMIN		DATETIME				
         AS 
         BEGIN
         	INSERT INTO EVENEMENT_ADMIN
         			(
         				COD_EVENEMENT_ADMIN, 
         				LIBL_EVENEMENT_ADMIN, 
         				ID_UTILISATEUR, 
         				ID_TYPE_EVENEMENT_ADMIN, 
         				ID_CONTRAT_PRO, 
         				BLN_ACTIF, 
         				DAT_EVENEMENT_ADMIN
         			)
         	VALUES
         			(
         				'0', 
         				@LIBL_EVENEMENT_ADMIN, 
         				@ID_UTILISATEUR, 
         				@ID_TYPE_EVENEMENT_ADMIN, 
         				@ID_CONTRAT_PRO, 
         				@BLN_ACTIF, 
         				@DAT_EVENEMENT_ADMIN
         			)
         
         	UPDATE	EVENEMENT_ADMIN 
         	SET		COD_EVENEMENT_ADMIN = @@IDENTITY 
         	WHERE	ID_EVENEMENT_ADMIN = @@IDENTITY
         
         	return @@IDENTITY
         END
GO
CREATE PROCEDURE [dbo].[UPD_INS_R20_R19_EXTRANET]
          @ID_ADHERENT INT,
          @ANNEE INT,
          @ID_TYPE_ASSUJETISSEMENT INT,
          @NUM_EFFECTIF_MOYEN INT,
          @COMM VARCHAR(255) OUTPUT -- LDE 13/01/2014 #16805
         AS
         -- ================================================================================================= 
         -- Author   : DSZ
         -- Creation date : 13/12/2013
         -- 13190   : [#36] 
         -- Description  : Proc‚dure d'insertion / maj du type assuj et 
         -- de l'activite pour la synchro exranet
         -- ================================================================================================= 
         -- AAM 07/02/2013 14902
         -- Assujetissement 20/49 et plus de 50
         -- ================================================================================================= 
         -- AAM 07/02/2013 14907
         -- Ajout Activit‚s
         -- =================================================================================================
         -- DSZ 27/11/2013 16434
         -- Ajout du commentaire d'adh‚rent si type d'assuj a chang‚
         -- =================================================================================================
         -- DSZ 13/01/14 - #16803: NLE - cr‚ation activit‚ conventionnel lors d'un franchissement de seuil
         -- =================================================================================================
         -- LDE 13/01/2014 #16805: NLE - commentaires changement assuj
         -- =================================================================================================
         -- OPA - #659 : Utilisation de INS_R19 (remplac‚e par INS_R19_SIMPLE (futur INS_R19) )
         -- =================================================================================================
         -- BBL 22/01/2015 -  : Le split ne doit s'effectuer que lorsque l'assujetissement est 20+ 49 pas sur les autres 
         -- =================================================================================================
         -- BBL 22/01/2015 -  : Les activit‚s ne doivent etre recherch‚es que sur la branche de l'adh‚rent
         -- =================================================================================================
         -- DSZ 30/11/2015 #1184 : ne pas recalculer type assujettissement
         -- =================================================================================================
         BEGIN
          DECLARE
           @ID_PERIODE INT
         
          SELECT
           @ID_PERIODE = ID_PERIODE
          FROM
           PERIODE
          WHERE
           COD_PERIODE = @ANNEE
           AND ID_TYPE_PERIODE = 1
         
          DECLARE
           @ID_TA_ANCIEN INT = NULL,
           @Existe_nouveau_TA bit = 0
           
           select @Existe_nouveau_TA = 1 from TYPE_ASSUJETISSEMENT where ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT 
          
          SELECT
           @ID_TA_ANCIEN = ID_TYPE_ASSUJETISSEMENT
          FROM
           R20
          WHERE
           ID_ADHERENT = @ID_ADHERENT
           AND ID_PERIODE = @ID_PERIODE
          
          if (@Existe_nouveau_TA = 1)   
          begin 
          IF (@ID_TA_ANCIEN IS NOT NULL)
           BEGIN
            UPDATE
             R20 
            SET
             ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT
            WHERE
             ID_ADHERENT = @ID_ADHERENT
             AND ID_PERIODE = @ID_PERIODE
           END
           ELSE
           BEGIN
            INSERT INTO R20
            (
             ID_ADHERENT,
             ID_PERIODE,
             ID_TYPE_ASSUJETISSEMENT
            )
            VALUES
            (
             @ID_ADHERENT,
             @ID_PERIODE,
             @ID_TYPE_ASSUJETISSEMENT
            )
           END
           
           --gestion de commentaire si le type d'assuj a chang‚
           IF ((@ID_TA_ANCIEN IS NULL) OR (@ID_TA_ANCIEN <> @ID_TYPE_ASSUJETISSEMENT))
           BEGIN
            SET
             @COMM = 'Attention : changement d''assujettissement : Ancien assujettissement : ' -- LDE 13/01/2014 #16805
         
            IF (@ID_TA_ANCIEN IS NULL)
            BEGIN
             SELECT
           @COMM = @COMM+'{absent}'
            END
            ELSE
            BEGIN
             SELECT
           @COMM = @COMM+LIBL_TYPE_ASSUJETISSEMENT
             FROM
           TYPE_ASSUJETISSEMENT
             WHERE
           ID_TYPE_ASSUJETISSEMENT = @ID_TA_ANCIEN
            END
            
            SELECT
             @COMM = @COMM+' Assujettissement Extranet : ' + LIBL_TYPE_ASSUJETISSEMENT
            FROM
             TYPE_ASSUJETISSEMENT
            WHERE
             ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT
           END
          end
          else -- le Type Assuj pass‚ n'existe pas
          begin 
             SET
             @COMM = 'Attention : le type d''assujettissement venant d''Extranet n''existe pas dans Optiform. Son id est '+ cast(@ID_TYPE_ASSUJETISSEMENT  as varchar(4))
          end
         
          DECLARE
           @ID_ACTIVITE INT
         
          DECLARE CURSEUR_ACTIVITE 
          CURSOR FOR 
          SELECT DISTINCT
           ID_ACTIVITE 
          FROM
           PARAM_ACTIVITE_BRANCHE
          WHERE
           ID_PERIODE = @ID_PERIODE 
           AND ID_CHAMP_APPLICATION = (SELECT TOP 1 ID_CHAMP_APPLICATION  FROM  TYPE_ASSUJETISSEMENT WHERE ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT)
           AND BLN_ACTIF = 1
           AND ID_BRANCHE = (select ID_BRANCHE FROM ADHERENT where ID_ADHERENT = @ID_ADHERENT )
         
          OPEN CURSEUR_ACTIVITE
          FETCH CURSEUR_ACTIVITE INTO @ID_ACTIVITE
         
          DELETE FROM R19 WHERE ID_ADHERENT = @ID_ADHERENT AND ID_PERIODE = @ID_PERIODE
         
          WHILE (@@FETCH_STATUS = 0)
          BEGIN  
           EXEC [dbo].[INS_R19] @ID_ADHERENT, @ID_ACTIVITE, @ID_PERIODE
           FETCH CURSEUR_ACTIVITE INTO @ID_ACTIVITE
          END
         
          CLOSE CURSEUR_ACTIVITE
          DEALLOCATE CURSEUR_ACTIVITE
         END
GO

         CREATE PROCEDURE [dbo].[UPD_MOTIF_REFUS_STAGIAIRE]
         	@ID_MOTIF_REFUS int,
         	@ID_STAGIAIRE int,
         	@ID_DISPOSITIF int,
         	--@ID_UNITE_STAGIAIRE int,
         	@BLN_ACTIF bit
         AS  
         
         BEGIN
         	DECLARE @ID_UNITE_STAGIAIRE int
         	
         	SELECT @ID_UNITE_STAGIAIRE = ID_UNITE_STAGIAIRE
         	FROM UNITE_STAGIAIRE
         	WHERE ID_DISPOSITIF = @ID_DISPOSITIF
         		AND ID_STAGIAIRE_PEC = @ID_STAGIAIRE
         
         	DECLARE @CONT int
         	SELECT @CONT = COUNT(*)
         	FROM NR215
         	WHERE NR215.ID_MOTIF_REFUS = @ID_MOTIF_REFUS
         		AND NR215.ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
         
         	IF @BLN_ACTIF = 1
         		BEGIN
         			IF @CONT = 0
         				BEGIN
         					INSERT INTO NR215
         						(ID_MOTIF_REFUS, ID_UNITE_STAGIAIRE)
         					VALUES
         						(@ID_MOTIF_REFUS, @ID_UNITE_STAGIAIRE)
         				END
         		END
         	ELSE
         		BEGIN
         			IF @CONT > 0
         				BEGIN
         					DELETE NR215
         					WHERE ID_MOTIF_REFUS = @ID_MOTIF_REFUS
         						AND ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
         				END
         		END
         END
         
GO

         CREATE PROCEDURE [BATCH_TRANSFERT_DOTATION_ALIM_CPT_DEFI_SELECTION_10_300]
         /*
         =============================================  
         Author  : MBL
         Create date : 03/03/2015
         Description : Proc‚dure permettant de lancer des tranferts des dotations 
         pour les adherents 10 … 300 (Champs applications 10-49 ET 50-299)
         sur le compte Selection DEFI	(@COD_TYPE_EVENEMENT_DOTATION_MOINS300 = 'DOTDS_M3')
         
         Le traitement fait appel a la fonction de table F_TRANSFERT_DOTATION_ALIM_CPT_DEFI_SELECTION_10_300 constituant un outil d'aide … la d‚cision 
         afin de g‚n‚rer ces transferts.
         
         -- CONDITION DE LANCEMENT
         Parametre : la valorisation du parametre @ID_ADHERENT_TRAITE est optionnelle. 
         			S'il est valorise, le traitement n'est declenche que pour l'adherent de mˆme ID
         			S'il n'est pas valorise, le traitement est declenche pour tous les adherents
         =============================================  
         -- Author		: MBL
         -- Modif date	: 21/04/2015
         -- Description	: Alimentation de l'‚tablissement lors de la cr‚ation transfert (colonne TRANSFERT.ID_ETABLISSEMENT)
         -- =============================================
         -- Author		: MBL
         -- Modif date	: 11/03/2016
         -- Description	: Adaptations 2015
         -- =============================================
         */
         @COD_TYPE_EVENEMENT_DOTATION_MOINS300	varchar(8),
         @ID_ADHERENT_TRAITE						int
         AS
         BEGIN
         
         	IF OBJECT_ID('tempdb..#TMP_TRANSFERT', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_TRANSFERT
         	END
         
         
         	DECLARE 
         	@DAT							DATETIME,
         	@ID_TYPE_EVENEMENT_TRANSFERT	INTEGER,
         	@ID_GROUPE						INTEGER,
         	@ID_ADHERENT					INTEGER,
         	@ID_ETABLISSEMENT				INTEGER,
         	@NUM_ANNEE_N					INTEGER, 
         	@MNT_TRANSFERT					DECIMAL(15, 2),
         	@ID_BRANCHE						INT,
         	@ID_PERIODE_N					INTEGER, 
         	@ID_PERIODE_N_PLUS1				INTEGER, 
         	@LIBL_MVT						VARCHAR(60),
         	@LIBL_EVENEMENT					VARCHAR(50),
         	@ID_ENVELOPPE					INTEGER,
         	@LIBL_ENVELOPPE					VARCHAR(50),
         	@ID_ACTIVITE					INTEGER,
         	@BLN_COMPTE_VERS_ENVELOPPE		TINYINT,
         	@ID_TRANSFERT					INT,
         	@ID_TYPE_FINANCEMENT			INT
         
         	SELECT @NUM_ANNEE_N = 2015
         
         	select @ID_TYPE_EVENEMENT_TRANSFERT = ID_TYPE_EVENEMENT FROM TYPE_EVENEMENT where COD_TYPE_EVENEMENT = @COD_TYPE_EVENEMENT_DOTATION_MOINS300	
         	
         	IF @ID_TYPE_EVENEMENT_TRANSFERT IS NULL 
         	BEGIN
         		SELECT 'Le type d''evenement associe au code evenement passe en parametre : ' + @COD_TYPE_EVENEMENT_DOTATION_MOINS300 + ' n''existe pas'
         	END
         	ELSE
         	BEGIN
         	
         		IF @COD_TYPE_EVENEMENT_DOTATION_MOINS300 = 'DOTDS_M3'
         		BEGIN
         			SELECT @ID_TYPE_FINANCEMENT = 5 -- Compte selection DEFI
         		END		
         		
         		SELECT t.*, ADHERENT.ID_ETABLISSEMENT_PRINCIPAL
         		INTO #TMP_TRANSFERT 
         		FROM F_TRANSFERT_DOTATION_ALIM_CPT_DEFI_SELECTION_10_300(@NUM_ANNEE_N, @ID_ADHERENT_TRAITE, @COD_TYPE_EVENEMENT_DOTATION_MOINS300) t
         		INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT = t.ID_ADHERENT
         		INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL
         
         --SELECT * FROM #TMP_TRANSFERT
         
         		SELECT @DAT = GETDATE()
         
         		SELECT	@ID_PERIODE_N		= ID_PERIODE   
         		from	PERIODE     
         		where	NUM_ANNEE		= @NUM_ANNEE_N 
         		AND		ID_TYPE_PERIODE = 1   
         
         		SELECT	@ID_PERIODE_N_PLUS1		= ID_PERIODE
         		from	PERIODE     
         		where	NUM_ANNEE				= @NUM_ANNEE_N + 1
         		AND		ID_TYPE_PERIODE			= 1   
         
         		SET @LIBL_EVENEMENT		= 'Transfert Dotation Cpt Defi Selection des 10-299 '	+ CAST(@NUM_ANNEE_N + 1 AS VARCHAR(4)) 
         		SET @LIBL_MVT			= 'Attribution enveloppe annuelle forfaitaire '		+ CAST(@NUM_ANNEE_N + 1 AS VARCHAR(4)) 
         
         
         		DECLARE cu_transfert CURSOR FOR
         		SELECT ID_ADHERENT, ID_GROUPE = ID_GROUPE_DOTATION, ID_BRANCHE, [ID_ACTIVITE_PLAN_N+1], MNT_TRANSFERT, ID_ETABLISSEMENT_PRINCIPAL
         		FROM #TMP_TRANSFERT
         		WHERE ABS(MNT_TRANSFERT) > 0
         
         		OPEN cu_transfert
         
         		FETCH cu_transfert INTO
         		@ID_ADHERENT, @ID_GROUPE, @ID_BRANCHE, @ID_ACTIVITE, @MNT_TRANSFERT, @ID_ETABLISSEMENT
         
         
         		WHILE (@@FETCH_STATUS <> -1)
         		BEGIN	
         			-- Recherche de l'enveloppe de collecte PIVOT
         			SELECT		@ID_ENVELOPPE = ID_ENVELOPPE , @LIBL_ENVELOPPE = LIBL_ENVELOPPE 
         			FROM		TYPE_ENVELOPPE 
         			INNER JOIN	ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         			WHERE		TYPE_ENVELOPPE.BLN_COLLECTE = 1 
         			AND			TYPE_ENVELOPPE.ID_ACTIVITE	= @ID_ACTIVITE 
         			AND			ENVELOPPE.ID_PERIODE		= @ID_PERIODE_N
         			AND			TYPE_ENVELOPPE.ID_BRANCHE	= @ID_BRANCHE
         
         			--SELECT LIBL_ENVELOPPE = @LIBL_ENVELOPPE 
         			IF @MNT_TRANSFERT >0
         			BEGIN
         				SET @BLN_COMPTE_VERS_ENVELOPPE  = 0
         			END
         			ELSE
         			BEGIN
         				SET @MNT_TRANSFERT = - @MNT_TRANSFERT
         				SET @BLN_COMPTE_VERS_ENVELOPPE  = 1
         			END
         
         			--SELECT '@ID_TRANSFERT = INS_TRANSFERT ',
         			--	LIBL_TRANSFERT				= @LIBL_EVENEMENT,
         			--	BLN_COMPTE_VERS_ENVELOPPE	= @BLN_COMPTE_VERS_ENVELOPPE,  
         			--	ID_GROUPE					= @ID_GROUPE,
         			--	ID_ENVELOPPE				= @ID_ENVELOPPE,
         			--	DAT_TRANSFERT				= @DAT,
         			--	MNT_TRANSFERT				= @MNT_TRANSFERT, 
         			--	ID_TYPE_FINANCEMENT			= @ID_TYPE_FINANCEMENT,   -- Type de financement sur Compte Historique
         			--	ID_UTILISATEUR				= 82, 
         			--	ID_PERIODE					= @ID_PERIODE_N_PLUS1,
         			--	COM_TRANSFERT				= @LIBL_MVT, 
         			--	LIBL_MVT_BUDGETAIRE			= @LIBL_MVT,
         			--	ID_TYPE_EVENEMENT			= @ID_TYPE_EVENEMENT_TRANSFERT
         					
         			exec @ID_TRANSFERT = INS_TRANSFERT 
         				@LIBL_TRANSFERT				= @LIBL_EVENEMENT,
         				@BLN_COMPTE_VERS_ENVELOPPE	= @BLN_COMPTE_VERS_ENVELOPPE,  
         				@ID_GROUPE					= @ID_GROUPE,
         				@ID_ENVELOPPE				= @ID_ENVELOPPE,
         				@DAT_TRANSFERT				= @DAT,
         				@MNT_TRANSFERT				= @MNT_TRANSFERT, 
         				@ID_TYPE_FINANCEMENT		= @ID_TYPE_FINANCEMENT,   -- Type de financement sur Compte Historique
         				@ID_UTILISATEUR				= 82, 
         				@ID_PERIODE					= @ID_PERIODE_N_PLUS1,
         				@COM_TRANSFERT				= @LIBL_MVT, 
         				@LIBL_MVT_BUDGETAIRE		= @LIBL_MVT,
         				@ID_TYPE_EVENEMENT			= @ID_TYPE_EVENEMENT_TRANSFERT,
         				@ID_ETABLISSEMENT			= @ID_ETABLISSEMENT
         
         			FETCH cu_transfert INTO
         			@ID_ADHERENT, @ID_GROUPE, @ID_BRANCHE, @ID_ACTIVITE, @MNT_TRANSFERT, @ID_ETABLISSEMENT
         
         
         		END
         
         		CLOSE cu_transfert
         		DEALLOCATE cu_transfert
         	END
         	
         	IF OBJECT_ID('tempdb..#TMP_TRANSFERT', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_TRANSFERT
         	END
         
         END		
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_MODULE_PEC_MBL]
         -- =======================================================================================================================================
         -- Author:		xxx
         -- Create date: xx xxx 2007
         -- Description:	lecture des MODULES PEC
         -- =======================================================================================================================================
         -- Author:		SAY
         -- Modif. date: 04 juillet 2007
         -- Description:	ajout d'engag‚
         -- =======================================================================================================================================
         -- Author:		SAY
         -- Modif. date: 30 juillet 2007
         -- Description:	ajout du montant chiffr‚ et
         --				optimisation
         -- =======================================================================================================================================
         -- Author		: Say
         -- Modified date: 06 ao–t 2007
         -- comment		: # montant "MNT chiffr‚ " devient "MNT reste … engager"
         -- =======================================================================================================================================
         -- Author		: Say
         -- Modified date: 08 ao–t 2007
         -- comment		: # montant "MNT reste … engager" redevient "MNT chiffr‚ "
         -- =======================================================================================================================================
         -- Author		: Say
         -- Modified date: 16 ao–t 2007
         -- comment		: # restructuration de la proc‚dure car les calculs de montants n'‚taient pas toujours prises en compte
         -- =======================================================================================================================================
         -- Author		: Say
         -- Modified date: 20 ao–t 2007
         -- comment		: # table temporaire pour calculer en distinct le MNT_REGLE_HT
         -- =======================================================================================================================================
         -- Author		: SVA
         -- Modified date: 04 octobre 2007
         -- comment		: Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚
         -- =======================================================================================================================================
         -- Author		: SVA
         -- Modified date: 05 octobre 2007
         -- comment		: Pour une action en cycle court, le montant engag‚ est ‚gale au montant r‚gl‚ calcul‚ pour la colonne r‚gl‚ (r‚el)
         -- =======================================================================================================================================
         -- Author		: MBL
         -- Modified date: 16 octobre 2007
         -- comment		: Correction des conditions portant sur les actions actives et imputables
         --					Suppression du code inutile (alimentation table #TABLE_OF et #TABLE_ADH_ETAB)
         -- =======================================================================================================================================
         -- Author		: MBL
         -- Modified date: 19 octobre 2007
         -- comment		: Modification du calcul du montant engag‚
         -- =======================================================================================================================================
         -- Author		: SV
         -- Modified date: 29 octobre 2007
         -- comment		: Modification de la valeur renvoy‚e pour la la raison sociale de l'adh‚rent
         -- =======================================================================================================================================
         -- 24/04/08 Dorota 
         -- Remplacement calcul MNT_CHIFFRE pour prendre en compte PLAN_FINANCEMENT_US
         -- =======================================================================================================================================
         -- 30/06/08 RMA 
         -- Parameter @ANNEE_ACTION added
         -- =======================================================================================================================================
         -- 18/07/08 DSZE Mantis 9419 --corrige 23/07/2008 pour prendre en compte ID_ENGAGEMENT
         -- IS_ENGAGE etait calcule pour l'action et non pas pour le module, a tort
         -- =======================================================================================================================================
         -- 24/04/08 SAFI
         -- AJOUTER UN COLOUMN DANS LA SELECT MODULE_PEC.BLN_IMPUTABLE
         -- =======================================================================================================================================
         -- 16/09/08 SAFI
         -- FILTRER LES ELEMENTS POSTE_COUT_ENGAGE QUI MATCHENT AVEC #TRI_ (#TRI_ c'est la table de selection)
         -- =======================================================================================================================================
         -- 22/09/08 AMA
         -- Modification du calcul du MNT_REEL: l'utilisation de la clause distincte sur les postes
         -- de cout induit que les op‚rations de versement d'encaissement pris en compte apr‚s des d‚caissements
         -- ne sont pas pris en compte par l'appli
         -- exemple: MODULE|POSTE_COUT
         -- =======================================================================================================================================
         --			100	  | 500
         --          100   |-500
         --          100   | 500 =>Element filtr‚ par la clause DISTINCT
         --						=>SOMME FAUSE (0 au lieu de 500)
         -- =======================================================================================================================================
         -- 15/10/08 AMA
         -- Prise en compte des modules inactifs (MANTIS 0010836)
         -- =======================================================================================================================================
         -- 15/10/08 AMA
         -- Annulation de la correction pr‚c‚dente
         -- =======================================================================================================================================
         -- 24/10/08 ASD
         -- Correction sur critŠre NUM_FACTURE (longueur … 50 du varchar)
         -- =======================================================================================================================================
         -- 29/12/08 AMA
         -- Correction d'un problŠme sur le calcul du nombre d'heures engag‚es (MANTIS 0011299)
         -- Ajout du nouveau systŠme de livraison (if exits .. DROP... create)
         -- =======================================================================================================================================
         -- 07/01/09 ASD
         -- valeur de la colonne "engagement possible" : on ne verifiait pas que les postes de cout 
         -- qui n'avaient jamais encore ‚t‚ engag‚s avaient recu l'approbation du chiffrage
         -- =======================================================================================================================================
         -- 08/01/09 ASD
         -- correction r‚gression sur montant engag‚ apparue sur PCE non encore engag‚s (Mantis 11367)
         -- =======================================================================================================================================
         -- 14/01/09 ASD
         -- correction s‚lection des modules n'ayant jamais ‚t‚ engag‚s (Mantis 11367)
         -- Cette correction doit ˆtre ‚valu‚e avec la plus grande prudence.
         -- =======================================================================================================================================
         -- 14/01/09 AMA
         -- Correction s‚lection des modules ayant ‚t‚ engag‚s (MANTIS 11367)
         -- Cette correction doit ˆtre ‚valu‚e avec la plus grande prudence.
         -- =======================================================================================================================================
         -- 29/01/09 AMA
         -- Les deux corrections pr‚c‚dentes (MANTIS 11367) ont entrain‚
         -- une regression (MANTIS 0011473) car le critŠre d'engagement/d‚sengagement
         -- ‚tait mal pris en compte (pour les actions courtes et les bases de reprise)
         -- =======================================================================================================================================
         -- 29/01/05 ASD
         -- Correction de constraint dans la colonne BLN_OK_FINANCEMENT
         -- =======================================================================================================================================
         -- 24/02/09 SAFI
         -- CORRECTION DE COLOUMN COD_ADHERENT FOR DISPLAY AIC/AC or COD_ADHERENT
         -- =======================================================================================================================================
         -- 14/04/2009 SAFI
         -- CHANGER LES CALCUL POUR NB HEUR ENGAGE 
         -- STAGIAIRE_PEC.ID_SESSION_PEC IS NOT NULL 
         -- =======================================================================================================================================
         -- 14/05/2009 ASD SAF
         -- revision de la correction AMA du 29/12 pour NB_H_ENGAGEES 
         -- STAGIAIRE_PEC.ID_SESSION_PEC IS NULL AND ACTION IS ENGAGED
         -- =======================================================================================================================================
         -- 18/05/2009 SAFI
         -- Correction dans la calcul de mnt regle!
         -- =======================================================================================================================================
         -- 04/06/2009 DSZ
         -- changement float->decimal dans la requete finale Mantis 12060
         -- =======================================================================================================================================
         -- 12/06/2009 DSZ
         -- Mantis 12077 mauvais calcul de "chiffrage inacheve". faut prendre min au lieu de sum
         -- =======================================================================================================================================
         -- 26/06/2009 ASD
         -- Correction calcul de MNT_DEMANDE (MNT_PREVISIONNEL) : ne pas prendre en compte les anciens postes de cout
         -- am‚lioration CAST en decimal (18,2)
         -- =======================================================================================================================================
         -- 08/12/2009 SAFI ano id 12251
         -- Correction calcul de MNT_CHIFFRE, Filtre sur PCE non d‚sengag‚ 
         -- Correction trasmis par SBR
         -- =======================================================================================================================================
         -- SAFI AJOUTER ano 12345 05/05/2010 ajout colonne ACTION_PEC_CLOTURE
         -- =======================================================================================================================================
         -- Author		: ASD DSZ
         -- Modified date: 13/10/2010
         -- comment		: 12423 Perf.  + indexes associ‚s
         -- =======================================================================================================================================
         -- Author		: DSZ ASD
         -- Modified date: 25/10/2010
         -- comment		: correction ano rapporte par mail 25/10/2010 ID_MODULE_PEC -> ID_MODULE
         --				  + correction premier select #tri : manque clauses sur bln_actif et imputable
         -- =======================================================================================================================================
         -- Author		: DSZ
         -- Modified date: 15/11/2010 - 18/11/2010
         -- comment		: 12544 perf
         -- =======================================================================================================================================
         -- Author		: DSZ
         -- Modified date: 30/09/2011
         -- comment		: 12570 Ne pas prendre en compte les US refus‚s pour calculer le mnt chiffr‚
         -- =======================================================================================================================================
         -- Author		: DSZ
         -- Modified date: 10/11/2011
         -- comment		: 12940 Ne pas prendre en compte les PCE … 0 pour determiner si ok financement
         -- =======================================================================================================================================
         -- Author		: DSZ
         -- Modified date: 17/02/2012
         -- comment		: 13261 Ajout de BLN_MODULE_CLOTURE
         -- Modification de methode de calcul de IS_ENGAGE : reprise de la logique de ACTION_ENGAGED
         -- =======================================================================================================================================
         -- Author		: DSZ
         -- Modified date: 14/05/2012
         -- comment		: 13462 reprise de 12940  : on ne prend pas en compte les PCE … 0 pour ok financement,
         -- mais on les prend en compte pour is_engage. sinon on ne peut pas desengager le module engag‚ mais … 0.
         -- =======================================================================================================================================
         -- DSZ 15/06/2012 13601 RAISON_SOCIALE_OF varchar(50) -> varchar(64)
         -- =======================================================================================================================================
         -- ASD/DSZ 30/07/2102 13766 la correction 13462 ne pas valable pour les modules pas engag‚s
         -- =======================================================================================================================================
         -- OPA #219	En tant qu'utilisateur habilit‚ Optiform, lorsque je consulte la liste des dossiers PEC engageables, je veux que seuls les 
         -- modules ayant des piŠces Bloquant l'engagement absentes ou non conformes soient r‚pertori‚s en "PiŠce manquante"
         -- =======================================================================================================================================
         -- Author		: MB
         -- Modif. date  : 13/08/2015
         -- Description  : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
         --                Correction adapation faite sur US # 219 mal g‚r‚e
         --                Un module dont une (ou +sieurs) piŠce active est absente doit positionner le module en PiŠce manquante et bloquer son engagement 
         --                ce qui n'est plus le cas … ce jour
         -- =======================================================================================================================================
         -- Author		: MBL 
         -- Modif. date	: 21/10/2015
         -- Description  : Refonte complŠte de la PS suite … pr‚conisation DBA
         --=======================================================
         
         	@COD_ACTION					INT,
         	@ANNEE_ACTION				INT,
         	@LIBL_ACTION_PEC			VARCHAR(100),
         	@ID_ETABLISSEMENT_OF		INT,
         	@ID_THEME					INT,
         	@ID_STAGE					INT,
         	@ID_FORMACODE				INT,
         	@ID_INDIVIDU				INT,
         	@ID_ADHERENT				INT,
         	@ID_ETABLISSEMENT			INT,
         	@NUM_ANNEE 					INT,
         	@DEPARTMENT 				INT,
         	@DATE_DEBUT_ENTRE_LE		DATETIME,	
         	@DATE_DEBUT_ET_LE 			DATETIME,	
         	@DATE_FIN_ENTRE_LE 			DATETIME,	
         	@DATE_FIN_ET_LE 			DATETIME,	
         	@BLN_NON_IMPUTABLES			INT,
         	@BLN_INACTIVES				INT,
         	@NUM_FACTURE 				VARCHAR(50),
         	@MONTANT_FACTUE 			DECIMAL(18,2),
         	@ID_CODE_OF 				INT,
         	@NUM_INTERNE 				VARCHAR(50)
         
         
         AS
         BEGIN
         
         
         	CREATE TABLE #TMP01
         	(
         		ID_MODULE					INT,
         		ID_ACTION_PEC				INT,
         		NUM_MODULE					VARCHAR(14),
         		LIBELLE_MODULE				VARCHAR(100),
         		DATE_DEBUT					DATETIME,
         		DATE_FIN					DATETIME,
         		RAISON_SOCIALE_OF			VARCHAR(64),
         		COD_ADHERENT				VARCHAR(10),	
         		ADHERENT_RAISON_SOCIALE		VARCHAR(50),
         		BLN_CYCLE_COURT				TINYINT, 		
         		BLN_ACTIF					TINYINT,
         		BLN_IMPUTABLE				TINYINT,
         		BLN_OK_PIECE				TINYINT,
         		BLN_OK_ENGAGEMENT			TINYINT default 1,
         		LIB_BLN_DELEGATION_PAIEMENT VARCHAR(1),
         		ACTION_PEC_CLOTURE			TINYINT,
         		BLN_MODULE_CLOTURE			TINYINT,
         		MNT_CHIFFRE					DECIMAL(18,2) default 0.0,
         		MNT_PREVISIONNEL			DECIMAL(18,2) default 0.0,
         		MNT_ENGAGE					DECIMAL(18,2) default 0.0,
         		MNT_REEL					DECIMAL(18,2) default 0.0,
         		IS_ENGAGE					INTEGER,
         		NB_STAGIAIRES				INTEGER default 0,
         		NB_H_ENGAGEES				FLOAT	default 0.0,
         		NB_H_REALISEES				FLOAT	default 0.0,
         		ENGAGEMENT_POSSIBLE			VARCHAR(18),
         		
         		-- ELEMENT AJOUTES
         		CIBLE_ACTION				INT,
         		BLN_OK_FINANCEMENT			INT
         		
         	)
         
         	DECLARE @NB_STAGIAIRES INT
         	DECLARE @NB_H_ENGAGEES INT
         	DECLARE @NB_H_REALISEES INT
         
         	DECLARE @SQLQuery AS NVARCHAR(4000)
         	DECLARE @ParameterDefinition AS NVARCHAR(2500) 
         
         	IF (@BLN_NON_IMPUTABLES IS NULL)
         	BEGIN
         		SET @BLN_NON_IMPUTABLES = 0
         	END	
         
         	IF (@BLN_INACTIVES IS NULL)
         	BEGIN
         		SET @BLN_INACTIVES = 0
         	END
         
         
         	SET @SQLQuery = ''
         
         	SET @SQLQuery += ' INSERT INTO #TMP01'
         	SET @SQLQuery += ' (ID_MODULE,'
         	SET @SQLQuery += ' ID_ACTION_PEC,'
         	SET @SQLQuery += ' NUM_MODULE,'
         	SET @SQLQuery += ' LIBELLE_MODULE,'
         	SET @SQLQuery += ' DATE_DEBUT,'
         	SET @SQLQuery += ' DATE_FIN,'
         	SET @SQLQuery += ' RAISON_SOCIALE_OF,'
         	SET @SQLQuery += ' BLN_CYCLE_COURT,'		
         	SET @SQLQuery += ' BLN_ACTIF,'
         	SET @SQLQuery += ' BLN_IMPUTABLE,'
         	SET @SQLQuery += ' BLN_OK_PIECE,'
         	SET @SQLQuery += ' LIB_BLN_DELEGATION_PAIEMENT,'
         	SET @SQLQuery += ' ACTION_PEC_CLOTURE,'
         	SET @SQLQuery += ' BLN_MODULE_CLOTURE,'
         	SET @SQLQuery += ' 	CIBLE_ACTION'
         	SET @SQLQuery += ' )'
         	SET @SQLQuery += ' SELECT  TOP 301'
         	SET @SQLQuery += ' ID_MODULE =MODULE_PEC.ID_MODULE_PEC,'
         	SET @SQLQuery += ' ACTION_PEC.ID_ACTION_PEC,'
         	SET @SQLQuery += ' NUM_MODULE = MODULE_PEC.COD_MODULE_PEC,'
         	SET @SQLQuery += ' LIBELLE_MODULE = MODULE_PEC.LIBL_MODULE_PEC,'
         	SET @SQLQuery += ' DATE_DEBUT = MODULE_PEC.DAT_DEBUT,'
         	SET @SQLQuery += ' DATE_FIN = MODULE_PEC.DAT_FIN,'
         	SET @SQLQuery += ' RAISON_SOCIALE_OF = ORGANISME_FORMATION.LIB_RAISON_SOCIALE,'
         	SET @SQLQuery += ' ACTION_PEC.BLN_CYCLE_COURT,										'	
         	SET @SQLQuery += ' MODULE_PEC.BLN_ACTIF,											'			
         	SET @SQLQuery += ' MODULE_PEC.BLN_IMPUTABLE,										'
         	SET @SQLQuery += ' MODULE_PEC.BLN_OK_PIECE,										'
         	SET @SQLQuery += ' LIB_BLN_DELEGATION_PAIEMENT = CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN		'
         	SET @SQLQuery +=																						'''X'''
         	SET @SQLQuery +=																					' ELSE '
         	SET @SQLQuery +=																						''''''
         	SET @SQLQuery +=																					'END,'
         	SET @SQLQuery += ' ACTION_PEC_CLOTURE = (CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END),'
         	SET @SQLQuery += ' BLN_MODULE_CLOTURE =	(CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END),'
         	SET @SQLQuery += ' CIBLE_ACTION = ACTION_PEC.CIBLE_ACTION'
         	SET @SQLQuery += ' FROM		MODULE_PEC'
         	SET @SQLQuery += ' INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC	= ACTION_PEC.ID_ACTION_PEC'
         	SET @SQLQuery += ' INNER JOIN PERIODE ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE								'
         	SET @SQLQuery += ' LEFT JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF	= MODULE_PEC.ID_ETABLISSEMENT_OF	'
         	SET @SQLQuery += ' LEFT JOIN ORGANISME_FORMATION ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF						'
         	SET @SQLQuery += ' LEFT JOIN ADRESSE ON ADRESSE.ID_ADRESSE = ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE '
         	
         	SET @SQLQuery += ' WHERE MODULE_PEC.BLN_IMPUTABLE >= @BLN_NON_IMPUTABLES '
         	SET @SQLQuery += ' AND  ACTION_PEC.BLN_ACTIF >= @BLN_INACTIVES'
         
         	IF @COD_ACTION		IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND ACTION_PEC.COD_ACTION_PEC = @COD_ACTION '
         	END
         	
         	IF @ANNEE_ACTION		IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION'
         	END
         	IF @LIBL_ACTION_PEC		IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND ACTION_PEC.LIBL_ACTION_PEC LIKE  RTRIM(@LIBL_ACTION_PEC)'
         	END
         	
         	IF 	@ID_CODE_OF	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND ORGANISME_FORMATION.ID_OF = @ID_CODE_OF'
         	END		
         
         	IF 	@ID_THEME	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_THEME = @ID_THEME'
         	END		
         
         	IF 	@ID_STAGE	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_STAGE = @ID_STAGE'
         	END		
         
         	IF 	@ID_FORMACODE	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_FORMACODE = @ID_FORMACODE'
         	END		
         
         	IF 	@NUM_ANNEE	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND PERIODE.NUM_ANNEE = @NUM_ANNEE'
         	END		
         
         	IF 	@DEPARTMENT	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND LEFT(ADRESSE.LIB_CP_CEDEX, 2) = RIGHT(''0''+CAST(@DEPARTMENT AS VARCHAR), 2)'
         	END		
         
         	IF @DATE_DEBUT_ENTRE_LE	IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND MODULE_PEC.DAT_DEBUT >= @DATE_DEBUT_ENTRE_LE'
         	END
         
         	IF @DATE_DEBUT_ET_LE	IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND MODULE_PEC.DAT_DEBUT <= @DATE_DEBUT_ET_LE'
         	END
         
         	IF @DATE_FIN_ENTRE_LE	IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND MODULE_PEC.DAT_FIN >= @DATE_FIN_ENTRE_LE'
         	END
         
         	IF @DATE_FIN_ENTRE_LE	IS NOT NULL
         	BEGIN
         		SET @SQLQuery += ' AND MODULE_PEC.DAT_FIN <= @DATE_FIN_ENTRE_LE'
         	END
         
         	IF 	@NUM_INTERNE	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.NUM_INTERNE = @NUM_INTERNE'
         	END		
         
         	IF 	@ID_ETABLISSEMENT_OF	IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF'
         	END		
         
         	IF 	@ID_ADHERENT IS NOT NULL OR @ID_ETABLISSEMENT IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND ACTION_PEC.ID_ACTION_PEC IN '
         		SET @SQLQuery +=								' ('
         		SET @SQLQuery +=								' SELECT ID_ACTION_PEC '
         		SET @SQLQuery += 								' FROM NR140 '
         		SET @SQLQuery += 								' INNER JOIN ETABLISSEMENT ON NR140 .ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT '
         		IF 	@ID_ADHERENT IS NOT NULL
         		BEGIN
         			SET @SQLQuery += 							' WHERE ETABLISSEMENT .ID_ADHERENT = @ID_ADHERENT'
         		END
         		IF 	@ID_ETABLISSEMENT IS NOT NULL
         		BEGIN
         			SET @SQLQuery += 							' AND ETABLISSEMENT .ID_ETABLISSEMENT = @ID_ETABLISSEMENT'
         		END
         		SET @SQLQuery +=								' )'
         	END		
         
         
         	IF 	@ID_INDIVIDU IS NOT NULL
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_MODULE_PEC IN '
         		SET @SQLQuery +=					' ('
         		SET @SQLQuery +=					' SELECT ID_MODULE_PEC'
         		SET @SQLQuery += 					' FROM STAGIAIRE_PEC '
         		SET @SQLQuery += 					' WHERE ID_INDIVIDU = @ID_INDIVIDU'
         		SET @SQLQuery +=					' )'
         	END		
         
         	IF 	@NUM_FACTURE IS NOT NULL OR @MONTANT_FACTUE IS NOT NULL 
         	BEGIN 
         		SET @SQLQuery += ' AND MODULE_PEC.ID_MODULE_PEC IN '
         		SET @SQLQuery +=								' ('
         		SET @SQLQuery +=								' SELECT ID_MODULE_PEC '
         		SET @SQLQuery += 								' FROM POSTE_COUT_REGLE '
         		IF 	@NUM_FACTURE IS NOT NULL
         		BEGIN
         			SET @SQLQuery += 							' WHERE POSTE_COUT_REGLE .NUM_FACTURE = @NUM_FACTURE'
         		END
         		IF 	@MONTANT_FACTUE IS NOT NULL
         		BEGIN
         			SET @SQLQuery += 							' AND POSTE_COUT_REGLE.MNT_REGLE_TTC = @MONTANT_FACTUE '
         			SET @SQLQuery += 							' AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1'
         		END
         		SET @SQLQuery +=								' )'
         	END		
         
         	SET @SQLQuery += ' ORDER BY MODULE_PEC.ID_MODULE_PEC'
         
         --SELECT @SQLQuery
         
         	SET @ParameterDefinition = '@COD_ACTION INT,@ANNEE_ACTION INT,@LIBL_ACTION_PEC VARCHAR(100), @ID_ETABLISSEMENT_OF INT, @ID_THEME int, @ID_STAGE int, @ID_FORMACODE int, @ID_INDIVIDU INT, @ID_ADHERENT INT, @ID_ETABLISSEMENT INT, @NUM_ANNEE int, @DEPARTMENT int , @DATE_DEBUT_ENTRE_LE DATETIME, @DATE_DEBUT_ET_LE DATETIME, @DATE_FIN_ENTRE_LE DATETIME, @DATE_FIN_ET_LE DATETIME, @BLN_NON_IMPUTABLES INT, @BLN_INACTIVES INT, @NUM_FACTURE VARCHAR(50),	@MONTANT_FACTUE DECIMAL(18,2), @ID_CODE_OF INT, @NUM_INTERNE VARCHAR(50)'
         
         
         	EXECUTE sp_executesql @SQLQuery, @ParameterDefinition, @COD_ACTION, @ANNEE_ACTION, @LIBL_ACTION_PEC, @ID_ETABLISSEMENT_OF, @ID_THEME, 
         	@ID_STAGE , @ID_FORMACODE, @ID_INDIVIDU, @ID_ADHERENT, @ID_ETABLISSEMENT, @NUM_ANNEE, @DEPARTMENT, 
         	@DATE_DEBUT_ENTRE_LE, @DATE_DEBUT_ET_LE, @DATE_FIN_ENTRE_LE, @DATE_FIN_ET_LE, @BLN_NON_IMPUTABLES, @BLN_INACTIVES, 
         	@NUM_FACTURE, @MONTANT_FACTUE, @ID_CODE_OF, @NUM_INTERNE
         
         
         	UPDATE #TMP01
         	SET COD_ADHERENT = ADH_ACTION.COD_ADHERENT, ADHERENT_RAISON_SOCIALE = ADH_ACTION.ADHERENT_RAISON_SOCIALE
         	FROM #TMP01 T
         	INNER JOIN
         		(SELECT ID_ACTION_PEC, COD_ADHERENT  = MAX(COD_ADHERENT), ADHERENT_RAISON_SOCIALE = MAX(LIB_RAISON_SOCIALE)
         		FROM NR140
         		INNER JOIN ETABLISSEMENT ON NR140.ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT 
         		INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT= ETABLISSEMENT .ID_ADHERENT
         		GROUP BY ID_ACTION_PEC
         		) 
         		ADH_ACTION	ON T.ID_ACTION_PEC = ADH_ACTION.ID_ACTION_PEC
         	WHERE T.CIBLE_ACTION = 1
         
         	UPDATE #TMP01 
         	SET 	COD_ADHERENT = 'AIC', ADHERENT_RAISON_SOCIALE ='AIC'
         	FROM #TMP01 T
         	WHERE T.CIBLE_ACTION = 2
         
         	UPDATE #TMP01 
         	SET 	COD_ADHERENT = 'AC', ADHERENT_RAISON_SOCIALE ='AC'
         	FROM #TMP01 T
         	WHERE T.CIBLE_ACTION = 3
         
         
         	-- Recherche si des pieces bloquant l'engagement sont absentes ou non conformes
         	UPDATE #TMP01
         	SET BLN_OK_ENGAGEMENT = KO_PIECE_ENGAGEMENT.BLN_OK_ENGAGEMENT
         	FROM #TMP01 T
         	INNER JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
         					0 AS BLN_OK_ENGAGEMENT
         					FROM ARRIVEE_PIECE_PEC 
         					INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
         					INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC			
         					AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
         					AND
         					(
         						ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
         						OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         					)
         					AND PIECE_PEC.BLN_ACTIF = 1
         					GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         				) 
         	KO_PIECE_ENGAGEMENT	ON KO_PIECE_ENGAGEMENT.ID_MODULE_PEC = T.ID_MODULE
         	
         		
         	-- Calcul des montants r‚gl‚s
         	UPDATE #TMP01
         	SET MNT_REEL = ISNULL(REGLE.MNT_REGLE_HT, 0)
         	FROM #TMP01 T
         	INNER JOIN
         		(
         			SELECT	ID_MODULE_PEC,
         					MNT_REGLE_HT = SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) 
         			FROM POSTE_COUT_REGLE			
         			INNER JOIN REGLEMENT			ON REGLEMENT.ID_REGLEMENT			= POSTE_COUT_REGLE.ID_REGLEMENT 
         											AND (REGLEMENT.DAT_VALID_REGLEMENT	IS NOT NULL)
         			GROUP BY ID_MODULE_PEC
         		)
         	REGLE ON REGLE.ID_MODULE_PEC = T.ID_MODULE
         
         
         
         	-- Calcul des montants demandes (previsionnels)
         	UPDATE #TMP01
         	SET MNT_PREVISIONNEL	= ISNULL(DEMANDE.MNT_PREVISIONNEL_HT, 0),
         		BLN_OK_FINANCEMENT	= ISNULL(DEMANDE.BLN_OK_FINANCEMENT, 0)
         	FROM #TMP01 T
         	INNER JOIN
         		(
         			SELECT 
         				ID_MODULE_PEC, 
         				MNT_PREVISIONNEL_HT = SUM(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT) ,
         				BLN_OK_FINANCEMENT  = MIN(POSTE_COUT_ENGAGE.BLN_OK_FINANCEMENT) 
         			FROM POSTE_COUT_ENGAGE
         			WHERE POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         			GROUP BY POSTE_COUT_ENGAGE.ID_MODULE_PEC
         		)
         	DEMANDE ON DEMANDE.ID_MODULE_PEC =  T.ID_MODULE
         
         
         	-- Calcul des montants chiffr‚s
         	UPDATE #TMP01
         	SET MNT_CHIFFRE	= ISNULL(CHIFFRE.MNT_CHIFFRE, 0),
         		MNT_ENGAGE	= ISNULL(CHIFFRE.MNT_ENGAGE, 0) ,
         		IS_ENGAGE	= ISNULL(CHIFFRE.IS_ENGAGE, 0) 		
         	FROM #TMP01 T
         	INNER JOIN
         		(
         			SELECT 
         				ID_MODULE_PEC, 
         				MNT_CHIFFRE = SUM(ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US, 0)) ,
         				MNT_ENGAGE =  SUM(CASE WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL THEN 0 ELSE ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US, 0) END) ,
         				IS_ENGAGE =  MAX(CASE WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL THEN 0 ELSE 1 END) 
         			FROM POSTE_COUT_ENGAGE
         			INNER JOIN PLAN_FINANCEMENT_US	ON	POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US .ID_POSTE_COUT_ENGAGE
         											AND PLAN_FINANCEMENT_US .ID_POSTE_COUT_REGLE IS NULL
         			WHERE POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         			GROUP BY POSTE_COUT_ENGAGE.ID_MODULE_PEC
         		)
         	CHIFFRE ON CHIFFRE.ID_MODULE_PEC = T.ID_MODULE
         
         
         	-- Calcul du NB de stagiaire et du NB d'heures engag‚es
         	UPDATE #TMP01
         	SET NB_STAGIAIRES= ISNULL(NB_STAGIAIRES_ENG.NB_STAGIAIRE, 0), 
         		NB_H_ENGAGEES= ISNULL(NB_STAGIAIRES_ENG.NB_HEURE_ENGAGE, 0) 
         	FROM #TMP01 T
         	INNER JOIN
         		(
         			SELECT	ID_MODULE_PEC,
         					NB_STAGIAIRE= COUNT(STAGIAIRE_PEC.ID_STAGIAIRE_PEC) ,
         					NB_HEURE_ENGAGE = SUM(STAGIAIRE_PEC.NB_HEURE_ENGAGE)
         					
         			FROM STAGIAIRE_PEC
         			WHERE	ID_SESSION_PEC IS NULL
         			GROUP BY ID_MODULE_PEC
         		)
         	NB_STAGIAIRES_ENG ON NB_STAGIAIRES_ENG.ID_MODULE_PEC = T.ID_MODULE
         	UPDATE #TMP01
         	SET NB_H_ENGAGEES = NB_H_ENGAGEES * IS_ENGAGE
         	
         
         	-- Calcul du NB d'heures r‚alis‚es (Session actives du module)
         	UPDATE #TMP01
         	SET NB_H_REALISEES= ISNULL(NB_STAGIAIRES_REGLE.NB_HEURE_REGLE, 0)
         	FROM #TMP01 T
         	INNER JOIN
         		(
         			SELECT	STAGIAIRE_PEC.ID_MODULE_PEC,
         					NB_HEURE_REGLE = SUM(STAGIAIRE_PEC.NB_HEURE_REGLE)
         			FROM STAGIAIRE_PEC
         			INNER JOIN SESSION_PEC ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         			WHERE SESSION_PEC.BLN_ACTIF = 1
         			GROUP BY STAGIAIRE_PEC.ID_MODULE_PEC
         			
         		)
         	NB_STAGIAIRES_REGLE ON NB_STAGIAIRES_REGLE.ID_MODULE_PEC = T.ID_MODULE
         
         	UPDATE #TMP01
         	SET ENGAGEMENT_POSSIBLE = 'PiŠce Manquante'
         	WHERE BLN_OK_ENGAGEMENT = 0
         	
         	UPDATE #TMP01
         	SET ENGAGEMENT_POSSIBLE = 'Chiffrage inachev‚'	
         	WHERE BLN_OK_FINANCEMENT = 0
         
         	UPDATE #TMP01
         	SET ENGAGEMENT_POSSIBLE = 'Possible'	
         	WHERE ENGAGEMENT_POSSIBLE IS NULL
         
         
         	
         	SELECT 
         		ID_MODULE					,
         		ID_ACTION_PEC				,
         		NUM_MODULE					,
         		LIBELLE_MODULE				,
         		DATE_DEBUT					,
         		DATE_FIN					,
         		RAISON_SOCIALE_OF			,
         		COD_ADHERENT				,	
         		ADHERENT_RAISON_SOCIALE		,
         		BLN_CYCLE_COURT				, 		
         		BLN_ACTIF					,
         		BLN_IMPUTABLE				,
         		BLN_OK_PIECE				,
         		BLN_OK_ENGAGEMENT			,
         		LIB_BLN_DELEGATION_PAIEMENT ,
         		ACTION_PEC_CLOTURE			,
         		BLN_MODULE_CLOTURE			,
         		MNT_CHIFFRE					,
         		MNT_PREVISIONNEL			,
         		MNT_ENGAGE					,
         		MNT_REEL					,
         		IS_ENGAGE					,
         		NB_STAGIAIRES				,
         		NB_H_ENGAGEES				,
         		NB_H_REALISEES				,
         		ENGAGEMENT_POSSIBLE			
          FROM #TMP01
         
         /*
         Code Supprime Suite A Refonte
         -----------------------------
         -- MBL du 21/10/2015
         -- Description  : Refonte complŠte de la PS suite … pr‚conisation DBA
         
         CREATE TABLE #TRI_ (
         		ID_MODULE INT,
         		ID_ACTION_PEC INT,
         		NUM_MODULE  VARCHAR(14),
         		LIBELLE_MODULE VARCHAR(100),
         		DATE_DEBUT DATETIME,
         		DATE_FIN DATETIME,
         		RAISON_SOCIALE_OF VARCHAR(64),
         		COD_ADHERENT VARCHAR(10),	
         		ADHERENT_RAISON_SOCIALE VARCHAR(50),
         		BLN_CYCLE_COURT TINYINT, 		
         		BLN_ACTIF TINYINT,
         		BLN_IMPUTABLE TINYINT,
         		BLN_OK_PIECE TINYINT,
         		BLN_OK_ENGAGEMENT TINYINT,
         		LIB_BLN_DELEGATION_PAIEMENT VARCHAR(1),
         		ACTION_PEC_CLOTURE TINYINT,
         		BLN_MODULE_CLOTURE TINYINT
         )
         
         IF(	@COD_ACTION					IS NOT NULL AND 
         	@LIBL_ACTION_PEC			IS NULL AND 
         	@ID_ETABLISSEMENT_OF		IS NULL AND 
         	@ID_THEME					IS NULL AND 
         	@ID_STAGE					IS NULL AND 
         	@ID_FORMACODE				IS NULL AND 
         	@ID_INDIVIDU				IS NULL AND
         	@ID_ADHERENT				IS NULL AND 
         	@ID_ETABLISSEMENT			IS NULL AND 
         	@DEPARTMENT 				IS NULL AND 
         	@DATE_DEBUT_ENTRE_LE		IS NULL AND 	
         	@DATE_DEBUT_ET_LE 			IS NULL AND 	
         	@DATE_FIN_ENTRE_LE 			IS NULL AND 	
         	@DATE_FIN_ET_LE 			IS NULL AND 	
         	@NUM_FACTURE 				IS NULL AND 
         	@MONTANT_FACTUE 			IS NULL AND 
         	@ID_CODE_OF 				IS NULL AND 
         	@NUM_INTERNE 				IS NULL 
         )
         BEGIN
         
         
         
         	-- Lecture des donnees ---------------------------------------------------------------------------------------------------------------
         	INSERT INTO #TRI_
         	SELECT DISTINCT TOP 301 
         		MODULE_PEC.ID_MODULE_PEC	AS ID_MODULE,
         		ACTION_PEC.ID_ACTION_PEC,
         		MODULE_PEC.COD_MODULE_PEC			AS NUM_MODULE,
         		MODULE_PEC.LIBL_MODULE_PEC			AS LIBELLE_MODULE,
         		--MODULE_PEC.ID_REGLE_CHIFFRAGE       AS ID_REGLE_CHIFFRAGE,
         		MODULE_PEC.DAT_DEBUT				AS DATE_DEBUT,
         		MODULE_PEC.DAT_FIN					AS DATE_FIN,
         		ORGANISME_FORMATION.LIB_RAISON_SOCIALE			AS RAISON_SOCIALE_OF,
         		CASE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN  CAST(ADHERENT.COD_ADHERENT AS VARCHAR(10))
         			WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
         			ELSE 'AC'
         		END									AS COD_ADHERENT,	
         		CASE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN ADHERENT.LIB_RAISON_SOCIALE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
         			ELSE 'AC'
         		END									AS ADHERENT_RAISON_SOCIALE,
         		ACTION_PEC.BLN_CYCLE_COURT,		
         		MODULE_PEC.BLN_ACTIF,
         		MODULE_PEC.BLN_IMPUTABLE,
         		MODULE_PEC.BLN_OK_PIECE,
         		COALESCE(PIECEMODULEPEC.BLN_OK_ENGAGEMENT, 1) AS BLN_OK_ENGAGEMENT,
         		CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN 	'X'  ELSE '' END			
         		AS  LIB_BLN_DELEGATION_PAIEMENT,
         		(CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS ACTION_PEC_CLOTURE,
         		(CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS BLN_MODULE_CLOTURE
         		
         	FROM  MODULE_PEC
         		INNER JOIN ACTION_PEC			ON MODULE_PEC.ID_ACTION_PEC	= ACTION_PEC.ID_ACTION_PEC
         		LEFT JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
         						0 AS BLN_OK_ENGAGEMENT
         					FROM ARRIVEE_PIECE_PEC 
         					INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
         					INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC			
         					AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
         					AND
         					(
         						ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
         						OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         					)
         					-- Modif MB . du 13/08/2015 : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
         					--WHERE ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
         					AND PIECE_PEC.BLN_ACTIF = 1
         					GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC) PIECEMODULEPEC ON PIECEMODULEPEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN ETABLISSEMENT_OF		ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF	= MODULE_PEC.ID_ETABLISSEMENT_OF
         		LEFT JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         		INNER JOIN NR140				ON NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         		inner join ETABLISSEMENT		ON NR140.ID_ETABLISSEMENT IS NOT NULL AND NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
         		LEFT JOIN ADHERENT				ON ETABLISSEMENT.ID_ADHERENT IS NOT NULL AND ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         		INNER JOIN PERIODE				ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         	WHERE
         			((@COD_ACTION IS NULL) OR (ACTION_PEC.COD_ACTION_PEC = @COD_ACTION))  
         		AND ((@ANNEE_ACTION	IS NULL) OR (ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION))  		
         		AND ((@NUM_ANNEE IS NULL) OR (PERIODE.NUM_ANNEE IS NOT NULL AND PERIODE.NUM_ANNEE= @NUM_ANNEE))
         		AND (MODULE_PEC.BLN_IMPUTABLE >= CASE @BLN_NON_IMPUTABLES WHEN 0 THEN 1 ELSE 0 END)
         		AND (ACTION_PEC.BLN_ACTIF >= CASE @BLN_INACTIVES WHEN 0 THEN 1 ELSE 0 END)
         	ORDER BY MODULE_PEC.ID_MODULE_PEC
         	OPTION(RECOMPILE)
         END
         ELSE
         BEGIN
         	INSERT INTO #TRI_
         	SELECT DISTINCT TOP 301 
         		MODULE_PEC.ID_MODULE_PEC				AS ID_MODULE,
         		ACTION_PEC.ID_ACTION_PEC,
         		MODULE_PEC.COD_MODULE_PEC				AS NUM_MODULE,
         		MODULE_PEC.LIBL_MODULE_PEC				AS LIBELLE_MODULE,
         		--MODULE_PEC.ID_REGLE_CHIFFRAGE			As ID_REGLE_CHIFFRAGE,
         		MODULE_PEC.DAT_DEBUT					AS DATE_DEBUT,
         		MODULE_PEC.DAT_FIN						AS DATE_FIN,
         		ORGANISME_FORMATION.LIB_RAISON_SOCIALE	AS RAISON_SOCIALE_OF,
         		CASE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN  cast(ADHERENT.COD_ADHERENT as varchar(10))	 
         			WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
         			ELSE 'AC'
         		END										AS COD_ADHERENT,	
         		CASE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 1 THEN ADHERENT.LIB_RAISON_SOCIALE 
         			WHEN ACTION_PEC.CIBLE_ACTION = 2 THEN 'AIC' 
         			ELSE 'AC'
         		END										AS ADHERENT_RAISON_SOCIALE,
         		ACTION_PEC.BLN_CYCLE_COURT,		
         		MODULE_PEC.BLN_ACTIF,
         		MODULE_PEC.BLN_IMPUTABLE,
         		MODULE_PEC.BLN_OK_PIECE,
         		COALESCE(PIECEMODULEPEC.BLN_OK_ENGAGEMENT, 1) AS BLN_OK_ENGAGEMENT,
         		CASE WHEN (MODULE_PEC.BLN_DELEGATION_PAIEMENT = 1)THEN
         			'X' 
         		ELSE
         			''
         		END			
         		AS  LIB_BLN_DELEGATION_PAIEMENT,
         		(CASE WHEN ACTION_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS ACTION_PEC_CLOTURE,
         		(CASE WHEN MODULE_PEC.DAT_CLOTURE IS NULL THEN 0 ELSE 1 END) AS BLN_MODULE_CLOTURE
         		
         	FROM  MODULE_PEC
         		INNER JOIN ACTION_PEC			ON MODULE_PEC.ID_ACTION_PEC	= ACTION_PEC.ID_ACTION_PEC
         		LEFT JOIN (SELECT ARRIVEE_PIECE_PEC.ID_MODULE_PEC, 
         						0 AS BLN_OK_ENGAGEMENT
         					FROM ARRIVEE_PIECE_PEC 
         					INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC AND BLN_OK_PIECE = 0
         					INNER JOIN PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC			
         					AND PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
         					AND
         					(
         						ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
         						OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         					)
         					-- Modif MB . du 13/08/2015 : Correction gestion des piŠces absentes ou non conformes bloquant l'engagement 
         					--WHERE ARRIVEE_PIECE_PEC.BLN_ACTIF = 1
         					AND PIECE_PEC.BLN_ACTIF = 1
         					GROUP BY ARRIVEE_PIECE_PEC.ID_MODULE_PEC) PIECEMODULEPEC ON PIECEMODULEPEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN ETABLISSEMENT_OF		ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF	= MODULE_PEC.ID_ETABLISSEMENT_OF
         		LEFT JOIN ADRESSE				ON ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE IS NOT NULL AND ADRESSE.ID_ADRESSE = ETABLISSEMENT_OF.ID_ADRESSE_PRINCIPALE
         		LEFT JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         		INNER JOIN NR140				ON NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         		INNER JOIN ETABLISSEMENT		ON NR140.ID_ETABLISSEMENT IS NOT NULL AND NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
         		LEFT JOIN ADHERENT				ON ETABLISSEMENT.ID_ADHERENT IS NOT NULL AND ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         		INNER JOIN PERIODE				ON PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         		LEFT JOIN POSTE_COUT_REGLE		ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN STAGIAIRE_PEC			ON STAGIAIRE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         	WHERE
         			((@COD_ACTION			IS NULL) OR (ACTION_PEC.COD_ACTION_PEC IS NOT NULL AND ACTION_PEC.COD_ACTION_PEC = @COD_ACTION))  
         		AND ((@ANNEE_ACTION			IS NULL) OR (ACTION_PEC.ANNEE_ACTION_PEC IS NOT NULL AND ACTION_PEC.ANNEE_ACTION_PEC = @ANNEE_ACTION))  		
         		AND ((@LIBL_ACTION_PEC		IS NULL) OR (ACTION_PEC.LIBL_ACTION_PEC IS NOT NULL AND ACTION_PEC.LIBL_ACTION_PEC LIKE  RTRIM(@LIBL_ACTION_PEC)))  
         		AND  ((@ID_CODE_OF			IS NULL) OR (ORGANISME_FORMATION.ID_OF = @ID_CODE_OF))
         	    AND ((@ID_THEME				IS NULL) OR (MODULE_PEC.ID_THEME = @ID_THEME))
         		AND  ((@ID_STAGE			IS NULL) OR (MODULE_PEC.ID_STAGE IS NOT NULL AND MODULE_PEC.ID_STAGE = @ID_STAGE))
         		AND  ((@ID_FORMACODE		IS NULL) OR (MODULE_PEC.ID_FORMACODE = @ID_FORMACODE))
         		AND  ((@DATE_DEBUT_ENTRE_LE	IS NULL) OR (MODULE_PEC.DAT_DEBUT >= @DATE_DEBUT_ENTRE_LE))
         		AND  ((@DATE_DEBUT_ET_LE	IS NULL) OR (MODULE_PEC.DAT_DEBUT IS NOT NULL AND MODULE_PEC.DAT_DEBUT <= @DATE_DEBUT_ET_LE))
         		AND  ((@DATE_FIN_ENTRE_LE	IS NULL) OR (MODULE_PEC.DAT_FIN >= @DATE_FIN_ENTRE_LE))
         		AND  ((@DATE_FIN_ET_LE		IS NULL) OR (MODULE_PEC.DAT_FIN <= @DATE_FIN_ET_LE))
         		AND  ((@NUM_INTERNE			IS NULL) OR (MODULE_PEC.NUM_INTERNE IS NOT NULL AND MODULE_PEC.NUM_INTERNE = RTRIM(@NUM_INTERNE)))	
         	    AND ((@ID_ETABLISSEMENT_OF	IS NULL) OR (MODULE_PEC.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF))  
         		AND  ((@DEPARTMENT			IS NULL) OR (ADRESSE.LIB_CP_CEDEX IS NOT NULL AND 
         									SUBSTRING(ADRESSE.LIB_CP_CEDEX,0,3) = (CASE WHEN @DEPARTMENT < 10 THEN '0' ELSE '' END) + CONVERT(VARCHAR(3),@DEPARTMENT)))
         		AND  ((@ID_INDIVIDU			IS NULL) OR (STAGIAIRE_PEC.ID_INDIVIDU = @ID_INDIVIDU AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL))
         		AND  ((@ID_ADHERENT			IS NULL) OR (ADHERENT.ID_ADHERENT =  @ID_ADHERENT))
         		AND  ((@ID_ETABLISSEMENT	IS NULL) OR (NR140.ID_ETABLISSEMENT = @ID_ETABLISSEMENT))
         		AND  ((@NUM_ANNEE			IS NULL) OR (PERIODE.NUM_ANNEE= @NUM_ANNEE))
         		AND  (MODULE_PEC.BLN_IMPUTABLE >= CASE @BLN_NON_IMPUTABLES WHEN 0 THEN 1 ELSE 0 END)
         		AND  (ACTION_PEC.BLN_ACTIF >= CASE @BLN_INACTIVES WHEN 0 THEN 1 ELSE 0 END)
         		AND  ((@MONTANT_FACTUE		IS NULL) OR (POSTE_COUT_REGLE.MNT_REGLE_TTC = @MONTANT_FACTUE AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1))
         		AND  ((@NUM_FACTURE			IS NULL) OR (POSTE_COUT_REGLE.NUM_FACTURE like CAST(RTRIM(@NUM_FACTURE) AS VARCHAR(50))))
         	ORDER BY MODULE_PEC.ID_MODULE_PEC
         	OPTION(RECOMPILE)
         END
         
         
         	--AMA 22/09/2008 Pour ‚viter d'utiliser la requˆte avec le DISTINCT, 
         	-- on r‚cupŠre d'abord la liste des modules concern‚s par les versements
         SELECT
         		#TRI_.ID_MODULE,
         		SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MNT_REEL
         	INTO #TEMPLISTMODULE
         	FROM 
         		#TRI_	
         		INNER JOIN POSTE_COUT_REGLE		ON POSTE_COUT_REGLE.ID_MODULE_PEC	= #TRI_.ID_MODULE
         		INNER JOIN REGLEMENT			ON REGLEMENT.ID_REGLEMENT			= POSTE_COUT_REGLE.ID_REGLEMENT 
         										AND (REGLEMENT.DAT_VALID_REGLEMENT	IS NOT NULL)
         	GROUP BY #TRI_.ID_MODULE
         
         	-- 1- pour les postes de cout engag‚s et non (d‚sengag‚s ou de d‚sengagement)
         		SELECT 
         			#TRI_.ID_MODULE, 
         			ISNULL(MIN(CASE POSTE_COUT_ENGAGE.MNT_ENGAGE_HT WHEN 0 THEN 1 ELSE BLN_OK_FINANCEMENT END),0) AS MIN_BLN_OK_FINANCEMENT, 
         			CASE WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
         					ISNULL(SUM(ISNULL(POSTE_COUT_ENGAGE.MNT_ENGAGE_HT,		0)),0)
         				ELSE
         					(SELECT MNT_REEL FROM #TEMPLISTMODULE WHERE #TEMPLISTMODULE.ID_MODULE = #TRI_.ID_MODULE)
         			END	AS MNT_ENGAGE,
         			COUNT(POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE) AS ENGAGE_CNT
         		INTO #TEMPLISTENGAGE_1EREETAPE
         		FROM POSTE_COUT_ENGAGE
         			INNER JOIN #TRI_		ON #TRI_.ID_MODULE			= POSTE_COUT_ENGAGE.ID_MODULE_PEC
         			INNER JOIN ACTION_PEC	ON ACTION_PEC.ID_ACTION_PEC = #TRI_.ID_ACTION_PEC
         			INNER JOIN ENGAGEMENT	ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         							AND ENGAGEMENT.DAT_BAE IS NOT NULL
         		WHERE
         			DAT_DESENGAGEMENT	IS NULL		AND 
         			ID_TYPE_ENGAGEMENT	IS NOT NULL AND 
         			ID_TYPE_ENGAGEMENT	<> 2
         			
         		GROUP BY #TRI_.ID_MODULE, action_pec.bln_cycle_court
         	UNION
         	-- 2- pour les modules n'ayant pas encore ‚t‚ engag‚s
         	SELECT 
         		#TRI_.ID_MODULE, 
         		ISNULL(MIN(BLN_OK_FINANCEMENT),0) AS MIN_BLN_OK_FINANCEMENT, 
         		CASE WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
         				0
         			ELSE
         				(SELECT MNT_REEL FROM #TEMPLISTMODULE WHERE #TEMPLISTMODULE.ID_MODULE = #TRI_.ID_MODULE)
         		END	AS MNT_ENGAGE,
         		0 AS ENGAGE_CNT
         	FROM POSTE_COUT_ENGAGE
         		INNER JOIN #TRI_		ON #TRI_.ID_MODULE			= POSTE_COUT_ENGAGE.ID_MODULE_PEC
         		INNER JOIN ACTION_PEC	ON ACTION_PEC.ID_ACTION_PEC = #TRI_.ID_ACTION_PEC 
         		LEFT JOIN ENGAGEMENT	ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         									AND ENGAGEMENT.DAT_BAE IS NULL
         	WHERE
         		POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL
         	GROUP BY #TRI_.ID_MODULE, ACTION_PEC.BLN_CYCLE_COURT
         
         	SELECT 
         			ID_MODULE,
         			ISNULL(MIN(MIN_BLN_OK_FINANCEMENT),0) AS MIN_BLN_OK_FINANCEMENT,
         			ISNULL(SUM(MNT_ENGAGE),0)AS MNT_ENGAGE,
         			ISNULL(SUM(ENGAGE_CNT),0) AS IS_ENGAGE
         	INTO 	#TEMPLISTENGAGE
         	FROM 	#TEMPLISTENGAGE_1EREETAPE
         	GROUP BY ID_MODULE
         
         	SELECT 
         		#TRI_.ID_MODULE, 
         		SUM(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT) AS MNT_PREVISIONNEL
         	INTO #TEMPLISTENGAGE2
         	FROM POSTE_COUT_ENGAGE
         		INNER JOIN #TRI_		ON #TRI_.ID_MODULE	= POSTE_COUT_ENGAGE.ID_MODULE_PEC
         	WHERE 		POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL 
         	GROUP BY #TRI_.ID_MODULE
         
         	SELECT 
         		#TRI_.ID_MODULE,
         		ISNULL(SUM(ISNULL(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0)),0) AS MNT_CHIFFRE
         	INTO #TEMPLISTENGAGE3
         	FROM #TRI_
         	INNER JOIN POSTE_COUT_ENGAGE ON #TRI_.ID_MODULE=POSTE_COUT_ENGAGE.ID_MODULE_PEC
         	INNER JOIN  PLAN_FINANCEMENT_US ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         										AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
         	-- AJOUT DSZ 30/09/2011 12570
         	INNER JOIN UNITE_STAGIAIRE ON (PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
         									AND UNITE_STAGIAIRE.BLN_REFUS = 0)
         	-- << --
         	GROUP BY #TRI_.ID_MODULE
         
         
         	SELECT  ISNULL(SUM(NB_HOURS), 0) AS NB_H_E, ID_MODULE
         	INTO #TEMP_NB_H_E
         	FROM         (SELECT DISTINCT 
         	dbo.STAGIAIRE_PEC.ID_STAGIAIRE_PEC, dbo.STAGIAIRE_PEC.NB_HEURE_ENGAGE AS NB_HOURS, 
         	#TRI_.ID_MODULE
         	FROM          dbo.STAGIAIRE_PEC
         	inner join #TRI_ ON STAGIAIRE_PEC.ID_MODULE_PEC	= #TRI_.ID_MODULE
         	 INNER JOIN dbo.MODULE_PEC ON dbo.MODULE_PEC.ID_MODULE_PEC = dbo.STAGIAIRE_PEC.ID_MODULE_PEC
         	 INNER JOIN dbo.POSTE_COUT_ENGAGE ON dbo.POSTE_COUT_ENGAGE.ID_MODULE_PEC = dbo.MODULE_PEC.ID_MODULE_PEC
         
         	WHERE      (dbo.STAGIAIRE_PEC.ID_SESSION_PEC IS NULL) AND (dbo.MODULE_PEC.BLN_ACTIF = 1) AND (dbo.MODULE_PEC.BLN_IMPUTABLE = 1) 
         	AND (dbo.POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL) AND (dbo.POSTE_COUT_ENGAGE.ID_ENGAGEMENT > 0) AND 
         	(dbo.POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL)) AS derivedtbl_1
         	GROUP BY ID_MODULE
         
         	SELECT     SUM(dbo.UNITE_STAGIAIRE.NB_HEURE_REGLE) AS NB_H_R, #TRI_.ID_MODULE
         	INTO #TEMP_NB_H_R
         	FROM  #TRI_ 
         	inner join dbo.STAGIAIRE_PEC ON STAGIAIRE_PEC.ID_MODULE_PEC	= #TRI_.ID_MODULE
         	INNER JOIN dbo.UNITE_STAGIAIRE       ON dbo.STAGIAIRE_PEC.ID_STAGIAIRE_PEC = dbo.UNITE_STAGIAIRE.ID_STAGIAIRE_PEC
         	WHERE     (dbo.STAGIAIRE_PEC.ID_SESSION_PEC IS NOT NULL)
         	GROUP BY #TRI_.ID_MODULE
         
         	-- Lecture final ------------------------------------------------------------------------------------------------------------------
         	SELECT 
         		#TRI_.*,
         		CAST(ISNULL(#TEMPLISTENGAGE3.MNT_CHIFFRE,0) AS DECIMAL(18,2)) AS MNT_CHIFFRE, 
         		ISNULL(#TEMPLISTENGAGE2.MNT_PREVISIONNEL,	0)	AS MNT_PREVISIONNEL,
         		ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,			0)	AS MNT_ENGAGE,
         		ISNULL(#TEMPLISTMODULE.MNT_REEL,				0)	AS MNT_REEL,
         		CASE WHEN #TEMPLISTENGAGE.IS_ENGAGE > 0 THEN 1 ELSE 0 END
         								AS IS_ENGAGE,
         -- 1. NB_STAGIAIRE
         		ISNULL((SELECT COUNT(STAGIAIRE_PEC.ID_STAGIAIRE_PEC)
         		FROM STAGIAIRE_PEC	WHERE 
         		STAGIAIRE_PEC.ID_MODULE_PEC =  #TRI_.ID_MODULE AND
         		STAGIAIRE_PEC.ID_SESSION_PEC IS NULL),0) AS NB_STAGIAIRES,
         --2. NB_H_ENGAGEES
         	ISNULL(#TEMP_NB_H_E.NB_H_E,0) AS NB_H_ENGAGEES,
         --3. NB_H_REALISEES
         			ISNULL(#TEMP_NB_H_R.NB_H_R,0) AS NB_H_REALISEES,
         --4.ENGAGEMENT POSSIBLE
         		CASE WHEN (#TRI_.BLN_ACTIF = 1 AND #TRI_.BLN_IMPUTABLE = 1) THEN
         			CASE WHEN(#TRI_.BLN_OK_ENGAGEMENT = 0 ) THEN
         				'PiŠce Manquante'
         			ELSE
         				CASE WHEN (#TEMPLISTENGAGE.MIN_BLN_OK_FINANCEMENT = 0) THEN
         					'Chiffrage inachev‚'	
         				ELSE
         					'Possible'
         				END
         			END
         		ELSE
         			'' -- Return Empty
         		END AS ENGAGEMENT_POSSIBLE
         	FROM  #TRI_
         		LEFT JOIN #TEMPLISTENGAGE	ON #TEMPLISTENGAGE.ID_MODULE	= #TRI_.ID_MODULE
         		LEFT JOIN #TEMPLISTENGAGE2	ON #TEMPLISTENGAGE2.ID_MODULE	= #TRI_.ID_MODULE
         		LEFT JOIN #TEMPLISTENGAGE3	ON #TEMPLISTENGAGE3.ID_MODULE	= #TRI_.ID_MODULE
         		LEFT JOIN #TEMPLISTMODULE	ON #TEMPLISTMODULE.ID_MODULE	= #TRI_.ID_MODULE
         		LEFT JOIN #TEMP_NB_H_R 
         									ON #TEMP_NB_H_R.ID_MODULE	= #TRI_.ID_MODULE
         		LEFT JOIN #TEMP_NB_H_E 
         									ON #TEMP_NB_H_E.ID_MODULE	= #TRI_.ID_MODULE
         
         
         */
         END
GO
 -- ============================================= 
         -- Author		: KSA
         -- Create date	: 14 janv. 2008
         -- Description	: Cr‚ation de la proc‚dure d'insertion d'un salari‚ pro
         -- ============================================= 
         -- Author		: EOU
         -- Modif. date	: Ajout param @ID_TYPE_MIN_SOCIAL
         -- Description	: 15378
         -- ============================================= 
         -- Author		: HBO
         -- Modif. date	: 20130702
         -- Description	: M15385 : Ajout param @ID_DIPLOME_VISE
         -- ============================================= 
         -- TLE - 20/12/2013 - modification de taille (100 vers 120 pour tout ce qui fonction)
         -- =============================================
         CREATE PROCEDURE dbo.INS_SALARIE_PRO
         	@ID_SALARIE_PRO				int OUTPUT, 
         	@COD_SALARIE_PRO			varchar(10) OUTPUT,
         	@BLN_ACTIF					tinyint = 1, 
         	@COM_SALARIE_PRO			varchar(255),
         	@ID_UTILISATEUR				int, 
         	@LIB_DR						varchar(50), 
         	@LIB_AGENCE					varchar(50), 
         	@MATRICULE_SALARIE			varchar(20), 
         	@BLN_TRAVAILLEUR_HANDICAPE	tinyint = 0, 
         	@NUM_DUREE_SITUATION		int, 
         	@LIB_DERNIERE_CERTIF_PROF	varchar(100), 
         	@LIB_DERNIER_EMPLOI_OCCUPE	varchar(120), 
         	@ID_INDIVIDU				int, 
         	@ID_TRANCHE_AGE				int, 
         	@ID_DIPLOME					int, 
         	@ID_NATIONALITE				int, 
         	@ID_SITUATION_SALARIE		int, 
         	@ID_CSP						int, 
         	@ID_NIVEAU					int, 
         	@NUM_MOBILE					varchar(10), 
         	@COD_IDE					varchar(8), 
         	@BLN_EQUIVALENT_BAC_PRO		tinyint = 0,
         	@ID_ADRESSE					int,
         	@ID_BRANCHE					INT,
         	@ID_TYPE_MIN_SOCIAL 		INT,
         	@ID_DIPLOME_VISE			INT
         AS
         BEGIN
         	INSERT INTO SALARIE_PRO
         		(
         			COD_SALARIE_PRO, 
         			BLN_ACTIF, 
         			DAT_MODIF,			DAT_CREATION, 
         			COM_SALARIE_PRO,	ID_UTILISATEUR, 
         			LIB_DR,				LIB_AGENCE, 
         			MATRICULE_SALARIE,	BLN_TRAVAILLEUR_HANDICAPE, 
         			NUM_DUREE_SITUATION, LIB_DERNIERE_CERTIF_PROF, 
         			LIB_DERNIER_EMPLOI_OCCUPE, 
         			ID_INDIVIDU,		ID_TRANCHE_AGE, 
         			ID_DIPLOME,			ID_NATIONALITE, 
         			ID_SITUATION_SALARIE, ID_CSP, 
         			ID_NIVEAU,			NUM_MOBILE, 
         			COD_IDE,			BLN_EQUIVALENT_BAC_PRO, 
         			ID_ADRESSE,			ID_BRANCHE,
         			ID_TYPE_MIN_SOCIAL, ID_DIPLOME_VISE
         		)
         	VALUES 
         		(
         			'0', 
         			@BLN_ACTIF, 
         			getdate(),			getdate(), 
         			@COM_SALARIE_PRO,	@ID_UTILISATEUR, 
         			@LIB_DR,			@LIB_AGENCE, 
         			@MATRICULE_SALARIE,	@BLN_TRAVAILLEUR_HANDICAPE, 
         			@NUM_DUREE_SITUATION, @LIB_DERNIERE_CERTIF_PROF, 
         			@LIB_DERNIER_EMPLOI_OCCUPE, 
         			@ID_INDIVIDU,		@ID_TRANCHE_AGE, 
         			@ID_DIPLOME,		@ID_NATIONALITE, 
         			@ID_SITUATION_SALARIE, @ID_CSP, 
         			@ID_NIVEAU,			@NUM_MOBILE, 
         			@COD_IDE,			@BLN_EQUIVALENT_BAC_PRO, 
         			@ID_ADRESSE,		@ID_BRANCHE,
         			@ID_TYPE_MIN_SOCIAL,@ID_DIPLOME_VISE
         		)
         	SET @ID_SALARIE_PRO		 = @@IDENTITY
         
         	UPDATE SALARIE_PRO SET COD_SALARIE_PRO = @ID_SALARIE_PRO WHERE ID_SALARIE_PRO = @ID_SALARIE_PRO
         
         	return @@IDENTITY
         END
GO

         CREATE PROCEDURE [BATCH_TRANSFERT_DOTATION_ALIM_CPT_MOINS10]
         /*
         =============================================  
         Author  : MBL
         Create date : 03/03/2015
         Description : Proc‚dure permettant de lancer des tranferts des dotations sur les comptes -10
         - sur le compte Selection DEFI					(@COD_TYPE_EVENEMENT_DOTATION_MOINS10 = 'DOTDSM10')
         - sur le compte Compte Versement Obligatoire	(@COD_TYPE_EVENEMENT_DOTATION_MOINS10 = 'DOTVOM10')
         
         
         Le traitement fait appel a la fonction de table F_TRANSFERT_DOTATION_ALIM_CPT_MOINS10 constituant un outil d'aide … la d‚cision 
         afin de g‚n‚rer ces transferts.
         
         -- CONDITION DE LANCEMENT
         Parametre : la valorisation du parametre @ID_ADHERENT_TRAITE est optionnelle. 
         			S'il est valorise, le traitement n'est declenche que pour l'adherent de mˆme ID
         			S'il n'est pas valorise, le traitement est declenche pour tous les adherents
         =============================================  
         -- Author		: MBL
         -- Create date	: 21/04/2015
         -- Description	: Alimentation de l'‚tablissement lors de la cr‚ation transfert (colonne TRANSFERT.ID_ETABLISSEMENT)
         -- =============================================
         -- Author		: MBL
         -- Modif date	: 11/03/2016
         -- Description	: Adaptations 2015
         -- =============================================
         */
         @COD_TYPE_EVENEMENT_DOTATION_MOINS10	varchar(8),
         @ID_ADHERENT_TRAITE						int
         AS
         BEGIN
         
         	IF OBJECT_ID('tempdb..#TMP_TRANSFERT', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_TRANSFERT
         	END
         
         
         	DECLARE 
         	@DAT							DATETIME,
         	@ID_TYPE_EVENEMENT_TRANSFERT	INTEGER,
         	@ID_GROUPE						INTEGER,
         	@ID_ADHERENT					INTEGER,
         	@ID_ETABLISSEMENT				INTEGER,
         	@NUM_ANNEE_N					INTEGER, 
         	@MNT_TRANSFERT					DECIMAL(15, 2),
         	@ID_BRANCHE						INT,
         	@ID_PERIODE_N					INTEGER, 
         	@ID_PERIODE_N_PLUS1				INTEGER, 
         	@LIBL_MVT						VARCHAR(60),
         	@LIBL_EVENEMENT					VARCHAR(50),
         	@ID_ENVELOPPE					INTEGER,
         	@LIBL_ENVELOPPE					VARCHAR(50),
         	@ID_ACTIVITE					INTEGER,
         	@BLN_COMPTE_VERS_ENVELOPPE		TINYINT,
         	@ID_TRANSFERT					INT,
         	@ID_TYPE_FINANCEMENT			INT
         
         	SELECT @NUM_ANNEE_N = 2015
         
         	select @ID_TYPE_EVENEMENT_TRANSFERT = ID_TYPE_EVENEMENT FROM TYPE_EVENEMENT where COD_TYPE_EVENEMENT = @COD_TYPE_EVENEMENT_DOTATION_MOINS10	
         	
         	IF @ID_TYPE_EVENEMENT_TRANSFERT IS NULL 
         	BEGIN
         		SELECT 'Le type d''evenement associe au code evenement passe en parametre : ' + @COD_TYPE_EVENEMENT_DOTATION_MOINS10 + ' n''existe pas'
         	END
         	ELSE
         	BEGIN
         	
         		IF @COD_TYPE_EVENEMENT_DOTATION_MOINS10 = 'DOTDSM10'
         		BEGIN
         			SET @LIBL_EVENEMENT		= 'Transfert Dotation Cpt Defi Selection des -10 '	+ CAST(@NUM_ANNEE_N + 1 AS VARCHAR(4)) 
         			SET @ID_TYPE_FINANCEMENT = 5 -- Compte selection DEFI
         		END
         		IF @COD_TYPE_EVENEMENT_DOTATION_MOINS10 = 'DOTVOM10'
         		BEGIN
         			SET @LIBL_EVENEMENT		= 'Transfert Dotation Cpt Plan Obligatoire -10 '	+ CAST(@NUM_ANNEE_N + 1 AS VARCHAR(4)) 
         			SET @ID_TYPE_FINANCEMENT = 4 -- Compte Versement Obligatoire
         		END
         		
         		
         		SELECT t.*, ETABLISSEMENT.ID_BRANCHE, ADHERENT.ID_ETABLISSEMENT_PRINCIPAL
         		INTO #TMP_TRANSFERT 
         		FROM F_TRANSFERT_DOTATION_ALIM_CPT_MOINS10(@NUM_ANNEE_N, @ID_ADHERENT_TRAITE, @COD_TYPE_EVENEMENT_DOTATION_MOINS10) t
         		INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT = t.ID_ADHERENT
         		INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL
         
         		--SELECT * FROM #TMP_TRANSFERT
         
         		SELECT @DAT = GETDATE()
         
         		SELECT	@ID_PERIODE_N		= ID_PERIODE   
         		from	PERIODE     
         		where	NUM_ANNEE		= @NUM_ANNEE_N 
         		AND		ID_TYPE_PERIODE = 1   
         
         		SELECT	@ID_PERIODE_N_PLUS1		= ID_PERIODE
         		from	PERIODE     
         		where	NUM_ANNEE				= @NUM_ANNEE_N + 1
         		AND		ID_TYPE_PERIODE			= 1   
         
         
         		SET @LIBL_MVT			= 'Attribution enveloppe annuelle forfaitaire '		+ CAST(@NUM_ANNEE_N + 1 AS VARCHAR(4)) 
         
         		SELECT @ID_ACTIVITE = ID_ACTIVITE 
         		FROM ACTIVITE			
         		WHERE COD_ACTIVITE = '-10'
         
         
         		DECLARE cu_transfert CURSOR FOR
         		SELECT ID_ADHERENT, ID_GROUPE = ID_GROUPE_DOTATION, ID_BRANCHE, MNT_TRANSFERT, ID_ETABLISSEMENT_PRINCIPAL
         		FROM #TMP_TRANSFERT
         		WHERE ABS(MNT_TRANSFERT) > 0
         
         		OPEN cu_transfert
         
         		FETCH cu_transfert INTO
         		@ID_ADHERENT, @ID_GROUPE, @ID_BRANCHE, @MNT_TRANSFERT, @ID_ETABLISSEMENT
         
         
         		WHILE (@@FETCH_STATUS <> -1)
         		BEGIN	
         			-- Recherche de l'enveloppe de collecte PIVOT
         			SELECT		@ID_ENVELOPPE = ID_ENVELOPPE , @LIBL_ENVELOPPE = LIBL_ENVELOPPE 
         			FROM		TYPE_ENVELOPPE 
         			INNER JOIN	ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         			WHERE		TYPE_ENVELOPPE.BLN_COLLECTE = 1 
         			AND			TYPE_ENVELOPPE.ID_ACTIVITE	= @ID_ACTIVITE 
         			AND			ENVELOPPE.ID_PERIODE		= @ID_PERIODE_N
         			AND			TYPE_ENVELOPPE.ID_BRANCHE	= @ID_BRANCHE
         
         			IF @MNT_TRANSFERT >0
         			BEGIN
         				SET @BLN_COMPTE_VERS_ENVELOPPE  = 0
         			END
         			ELSE
         			BEGIN
         				SET @MNT_TRANSFERT = - @MNT_TRANSFERT
         				SET @BLN_COMPTE_VERS_ENVELOPPE  = 1
         			END
         			--SELECT '@ID_TRANSFERT = INS_TRANSFERT', 
         			--	LIBL_TRANSFERT				= @LIBL_EVENEMENT,
         			--	BLN_COMPTE_VERS_ENVELOPPE	= @BLN_COMPTE_VERS_ENVELOPPE,  
         			--	ID_GROUPE					= @ID_GROUPE,
         			--	ID_ENVELOPPE				= @ID_ENVELOPPE,
         			--	DAT_TRANSFERT				= @DAT,
         			--	MNT_TRANSFERT				= @MNT_TRANSFERT, 
         			--	ID_TYPE_FINANCEMENT			= @ID_TYPE_FINANCEMENT,   -- Type de financement sur Compte Historique
         			--	ID_UTILISATEUR				= 82, 
         			--	ID_PERIODE					= @ID_PERIODE_N_PLUS1,
         			--	COM_TRANSFERT				= @LIBL_MVT, 
         			--	LIBL_MVT_BUDGETAIRE			= @LIBL_MVT,
         			--	ID_TYPE_EVENEMENT			= @ID_TYPE_EVENEMENT_TRANSFERT,
         			--	ID_ETABLISSEMENT			= @ID_ETABLISSEMENT
         					
         			EXEC @ID_TRANSFERT = INS_TRANSFERT 
         				@LIBL_TRANSFERT				= @LIBL_EVENEMENT,
         				@BLN_COMPTE_VERS_ENVELOPPE	= @BLN_COMPTE_VERS_ENVELOPPE,  
         				@ID_GROUPE					= @ID_GROUPE,
         				@ID_ENVELOPPE				= @ID_ENVELOPPE,
         				@DAT_TRANSFERT				= @DAT,
         				@MNT_TRANSFERT				= @MNT_TRANSFERT, 
         				@ID_TYPE_FINANCEMENT		= @ID_TYPE_FINANCEMENT,   -- Type de financement sur Compte Historique
         				@ID_UTILISATEUR				= 82, 
         				@ID_PERIODE					= @ID_PERIODE_N_PLUS1,
         				@COM_TRANSFERT				= @LIBL_MVT, 
         				@LIBL_MVT_BUDGETAIRE		= @LIBL_MVT,
         				@ID_TYPE_EVENEMENT			= @ID_TYPE_EVENEMENT_TRANSFERT,
         				@ID_ETABLISSEMENT			= @ID_ETABLISSEMENT
         
         			FETCH cu_transfert INTO
         			@ID_ADHERENT, @ID_GROUPE, @ID_BRANCHE, @MNT_TRANSFERT, @ID_ETABLISSEMENT
         
         		END
         
         		CLOSE cu_transfert
         		DEALLOCATE cu_transfert
         	END
         	
         	IF OBJECT_ID('tempdb..#TMP_TRANSFERT', 'U') IS NOT NULL 
         	BEGIN
         		drop table #TMP_TRANSFERT
         	END
         
         END		
GO
CREATE PROCEDURE [dbo].[UPD_INS_MASSE_SALARIALE_EXTRANET] 
          @ID_ADHERENT int, 
          @MASSE_SALARIALE int,
          @MASSE_SALARIALE_CDD int,
          @ANNEE int,
          @NUM_EFFECTIF int,
          @ID_ETABLISSEMENT int --‚tablissement verseur
         AS
         -- ============================================= 
         -- Author:  DSZ
         -- Create date: 27/11/2012
         -- Description: UPDATE or insert la masse salariale de l'adherent
         -- ============================================= 
         -- DSZ 01/02/2013 14852
         -- la synchronisation de la MS doit, dans tous les cas, alimenter :
         -- MSE (‚tablissement verseur) <- MS
         -- MSE (autres ‚tablissements) <- 0
         -- MSAdherent <- MS
         -- ============================================= 
         -- AME / OPA : 28/10/2015 / #1158 ajout masse salariale
         -- ============================================= 
         BEGIN
          DECLARE @id_periode int
          SELECT @id_periode = ID_PERIODE from PERIODE where cod_periode = @ANNEE and id_type_periode = 1
          
          if (@id_periode is not null)
          begin
           --MSAdherent <- MS
           if exists (SELECT 1 from R21 where ID_ADHERENT = @ID_ADHERENT and 
            ID_PERIODE = @id_periode)
            UPDATE R21
            set 
             MASSE_SALARIALE_REELLE = @MASSE_SALARIALE,
             MASSE_SALARIALE_CDD = @MASSE_SALARIALE_CDD,
             NUM_EFFECTIF = ISNULL(@NUM_EFFECTIF, NUM_EFFECTIF)
            where 
             ID_ADHERENT = @ID_ADHERENT and 
             ID_PERIODE = @id_periode 
           ELSE
            insert into R21(ID_ADHERENT, ID_PERIODE, MASSE_SALARIALE_REELLE, MASSE_SALARIALE_CDD, NUM_EFFECTIF)
            values (@ID_ADHERENT, @id_periode, @MASSE_SALARIALE, @MASSE_SALARIALE_CDD, @NUM_EFFECTIF)
           
           
           -- MSE (autres ‚tablissements) <- 0
           UPDATE R21_BIS 
           set MASSE_SALARIALE_REELLE = 0,
           MASSE_SALARIALE_CDD = 0
           from R21_BIS 
            inner join ETABLISSEMENT on (ETABLISSEMENT.ID_ETABLISSEMENT = R21_BIS.ID_ETABLISSEMENT)
           where ETABLISSEMENT.ID_ADHERENT = @ID_ADHERENT
           and R21_BIS.ID_PERIODE = @id_periode 
           and ETABLISSEMENT.ID_ETABLISSEMENT <> @ID_ETABLISSEMENT 
           
           --MSE (‚tablissement verseur) <- MS
           if exists (SELECT 1 from R21_BIS where ID_ETABLISSEMENT = @ID_ETABLISSEMENT and ID_PERIODE = @id_periode )
            UPDATE R21_BIS 
            set MASSE_SALARIALE_REELLE = @MASSE_SALARIALE,
             MASSE_SALARIALE_CDD = @MASSE_SALARIALE_CDD
            where 
             ID_ETABLISSEMENT = @ID_ETABLISSEMENT 
             and ID_PERIODE = @id_periode 
           ELSE
            insert into R21_BIS (ID_ETABLISSEMENT, ID_PERIODE, MASSE_SALARIALE_REELLE, MASSE_SALARIALE_CDD)
            values (@ID_ETABLISSEMENT, @id_periode , @MASSE_SALARIALE, @MASSE_SALARIALE_CDD)  
          end
         END
GO


         CREATE PROCEDURE [dbo].[INS_NR67]

         	@ID_ADHERENT int,

         	@ID_DOCUMENT int

         AS

         BEGIN

         	/* si il n'y a pas d'adherent on ajoute le document a tous les adherents */

         	IF (@ID_ADHERENT IS NULL)

         		BEGIN

         			insert into NR67

         				(ID_ADHERENT, ID_DOCUMENT)

         			select 

         				distinct

         				ADHERENT.ID_ADHERENT as ID_ADHERENT, @ID_DOCUMENT as ID_DOCUMENT

         			from

         				ADHERENT

         				LEFT OUTER JOIN NR67 on NR67.ID_ADHERENT = ADHERENT.ID_ADHERENT  and NR67.ID_DOCUMENT = @ID_DOCUMENT

         			where NR67.ID_ADHERENT is null

         			order by ADHERENT.ID_ADHERENT

         		END

         	/* ajout d'un document associ‚ … un adherent */

         	ELSE

         		BEGIN

         			insert into NR67

         				(ID_ADHERENT, ID_DOCUMENT)

         			values

         				(@ID_ADHERENT, @ID_DOCUMENT)

         		END

         END

GO

         CREATE PROCEDURE [dbo].[BATCH__RESULTAT_COMPTA_PRO]
         -- =============================================  
         -- Create date	: XXX
         -- Author		:  XXX
         -- Description	: Generation des ecritures comptables associees au contrat PRO
         -- =============================================
         -- Modif. date	: 06/01/2015
         -- Author		: MBL
         -- Description	: Reforme 2015 : Les comptes comptables passent a 12 caracteres
         -- =============================================
         AS
         BEGIN
         	DECLARE	@ID_REGLEMENT_PRO			int, 
         			@NUM_VIREMENT				int	, 
         			@NUM_ANNEE					int, 
         			@ID_DISPOSITIF				int, 
         			@MNT_TOTAL_HT				float,
         			@MNT_TOTAL_TVA				float,
         			@MNT_TOTAL_TTC				float,
         			@MNT_HT						float,
         			@MNT_TVA					float,
         			@MNT_TTC					float,
         			@ID_ACTIVITE				int	,
         			@ID_TRANSACTION				int,
         			@ID_ETABLISSEMENT_ADH		int ,
         			@ID_ETABLISSEMENT_OF		int	,
         			@ID_DEST					int	,
         			-- MB Modif du 06/01/2015 Les comptes comptables passent a 12 caracteres
         			--@NUM_CPT					varchar(8)
         			@NUM_CPT					varchar(13)
         
         	DECLARE @COD_TRAITEMENT				varchar(3), 
         			@REF_ECRITURE				varchar(13), 
         			@LIBELLE_ECRITURE			varchar(25), 
         			@LIB_NOM_JNL_BANQUE			varchar(3), 
         			@NUM_CPT_COMPTA_BANCAIRE	varchar(13),
         			-- MB Modif du 06/01/2015 Les comptes comptables passent a 12 caracteres
         			--@NUM_CPT_TVA_DEDUCTIBLE		varchar(8),
         			@NUM_CPT_TVA_DEDUCTIBLE		varchar(13),
         			@DATE_PIECE					datetime
         
         	SET @COD_TRAITEMENT = 'CP'		-- Traitement de comptabilite des contrats de PRO
         	SET @ID_ACTIVITE	= 3			-- Activite unique associee au contrat de pro
         
         	SELECT	@LIB_NOM_JNL_BANQUE			= LIB_NOM_JNL_BANQUE,
         			@NUM_CPT_TVA_DEDUCTIBLE		= NUM_CPT_TVA_DEDUCTIBLE,
         			@NUM_CPT_COMPTA_BANCAIRE	= NUM_CPT_COMPTA_BANCAIRE
         	FROM	ACTIVITE
         	WHERE	ID_ACTIVITE = @ID_ACTIVITE
         
         
         	/* Generation d'une ecriture TTC de credit pour tous les reglements PRO valides et non remis en compta
         		regroupes par leur date de validation de reglement */
         	DECLARE  cu_compta_pro_reg CURSOR FOR
         	SELECT DATE_PIECE = CONVERT(DATETIME, DAT_VALID_REGLEMENT, 103), MNT_TOTAL_HT = ROUND(SUM(MNT_REGLE_HT),2), MNT_TOTAL_TTC = ROUND(SUM(MNT_REGLE_TTC),2)
         	FROM REGLEMENT_PRO
         	WHERE DAT_VALID_REGLEMENT IS NOT NULL AND REGLEMENT_PRO.DAT_COMPTA_REGLEMENT IS NULL
         	GROUP BY CONVERT(DATETIME, DAT_VALID_REGLEMENT, 103)
         
         	OPEN cu_compta_pro_reg 
         	FETCH cu_compta_pro_reg INTO 
         		@DATE_PIECE , @MNT_TOTAL_HT , @MNT_TOTAL_TTC 
         
         
         	WHILE (@@fetch_status <> -1)
         	BEGIN
         
         		SET @MNT_TOTAL_TVA = ROUND(@MNT_TOTAL_TTC - @MNT_TOTAL_HT,2)
         		--SELECT 'DEBIT TTC ' , TOTAL_TTC = @MNT_TOTAL_TTC,  TOTAL_HT = @MNT_TOTAL_HT, TOTAL_TVA = @MNT_TOTAL_TVA
         
         
         		SET @LIBELLE_ECRITURE	= 'TTC Vir du ' + CONVERT(VARCHAR(10), @DATE_PIECE, 03)
         		SET @REF_ECRITURE		= 'Vir ' + CONVERT(VARCHAR(10), @DATE_PIECE, 03)
         
         		INSERT INTO ECRITURE_COMPTABLE
         		(
         		COD_TRAITEMENT,
         		DATE_PIECE,
         		REF_ECRITURE,
         		LIBELLE_ECRITURE,
         		LIB_NOM_JNL_BANQUE,
         		NUM_CPT_COMPTA_BANCAIRE,
         		MNT,
         		SENS, 
         		TYPE_COMPTE, 
         		NUM_CPT_AUXILIAIRE)
         		VALUES
         		(
         		@COD_TRAITEMENT, 
         		@DATE_PIECE, 
         		@REF_ECRITURE, 
         		@LIBELLE_ECRITURE, 
         		@LIB_NOM_JNL_BANQUE, 
         		@NUM_CPT_COMPTA_BANCAIRE, 
         		@MNT_TOTAL_TTC, 
         		'C',
         		'',
         		''
         		)
         
         		FETCH cu_compta_pro_reg INTO 
         			@DATE_PIECE , @MNT_TOTAL_HT , @MNT_TOTAL_TTC 
         	END
         	CLOSE cu_compta_pro_reg 
         	DEALLOCATE cu_compta_pro_reg 
         
         	SELECT	@MNT_TOTAL_HT		= 0,
         			@MNT_TOTAL_TVA		= 0,
         			@MNT_TOTAL_TTC		= 0
         
         
         	/* Generation d'une ecriture HT et TVA de debit pour tous les reglements PRO valides et non remis en compta
         		regroupes par periode et dispositif */
         	DECLARE cu_compta_pro CURSOR FOR
         	SELECT	REGLEMENT_PRO.ID_REGLEMENT_PRO, 
         			REGLEMENT_PRO.NUM_VIREMENT, 
         			PERIODE.NUM_ANNEE, 
         			TYPE_FORMATION.ID_DISPOSITIF, 
         			MNT_HT =
         			ROUND(SUM(MNT_VERSE_HT_OF			*  CASE SESSION_PRO.ID_REGLEMENT_PRO_OF WHEN REGLEMENT_PRO .ID_REGLEMENT_PRO THEN 1 ELSE 0 END ) 
         			+	SUM(MNT_VERSE_HT_ADH	* CASE SESSION_PRO.ID_REGLEMENT_PRO_ADH WHEN REGLEMENT_PRO .ID_REGLEMENT_PRO THEN 1 ELSE 0 END ) ,2) ,
         			MNT_TVA =
         			ROUND(SUM(MNT_VERSE_TVA_OF		*  CASE SESSION_PRO.ID_REGLEMENT_PRO_OF WHEN REGLEMENT_PRO .ID_REGLEMENT_PRO THEN 1 ELSE 0 END ) 
         			+	SUM(MNT_VERSE_TVA_ADH		* CASE SESSION_PRO.ID_REGLEMENT_PRO_ADH WHEN REGLEMENT_PRO .ID_REGLEMENT_PRO THEN 1 ELSE 0 END ) ,2)
         
         	FROM REGLEMENT_PRO, SESSION_PRO, MODULE_PRO, PERIODE, TYPE_FORMATION
         	WHERE DAT_VALID_REGLEMENT IS NOT NULL AND REGLEMENT_PRO.DAT_COMPTA_REGLEMENT IS NULL
         	AND (REGLEMENT_PRO .ID_REGLEMENT_PRO = SESSION_PRO.ID_REGLEMENT_PRO_ADH OR REGLEMENT_PRO .ID_REGLEMENT_PRO = SESSION_PRO.ID_REGLEMENT_PRO_OF )
         	AND SESSION_PRO.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO 
         	AND MODULE_PRO.ID_PERIODE =  PERIODE.ID_PERIODE
         	AND MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION 
         	GROUP BY REGLEMENT_PRO.ID_REGLEMENT_PRO, 
         			REGLEMENT_PRO.NUM_VIREMENT, 
         			PERIODE.NUM_ANNEE, 
         			TYPE_FORMATION.ID_DISPOSITIF
         
         	OPEN cu_compta_pro 
         	FETCH cu_compta_pro INTO
         			@ID_REGLEMENT_PRO	, 
         			@NUM_VIREMENT		, 
         			@NUM_ANNEE			, 
         			@ID_DISPOSITIF		, 
         			@MNT_HT				,
         			@MNT_TVA				
         
         	WHILE (@@fetch_status <> -1)
         	BEGIN
         		
         		--SELECT 		'HT' , CASE @ID_DISPOSITIF WHEN 7 THEN 'FT' ELSE 'CPOR' END, @NUM_VIREMENT		, 	@NUM_ANNEE			, 		@ID_DISPOSITIF		, 		@MNT_HT				
         		--SELECT 		'TVA' , CASE @ID_DISPOSITIF WHEN 7 THEN 'FT' ELSE 'CPOR' END, @NUM_VIREMENT		, 	@NUM_ANNEE			, 		@ID_DISPOSITIF		, 		@MNT_TVA				
         
         
         		SELECT @NUM_VIREMENT = NUM_VIREMENT, @ID_TRANSACTION = ID_TRANSACTION, @DATE_PIECE = CONVERT(DATETIME, DAT_VALID_REGLEMENT, 103)
         		FROM REGLEMENT_PRO
         		WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO
         
         		SET @REF_ECRITURE		= 'Vir ' + CAST(@NUM_VIREMENT AS VARCHAR)
         		--SET @REF_ECRITURE		= 'Vir ' + CONVERT(VARCHAR(10), @DATE_PIECE, 03)
         
         		SELECT	@ID_ETABLISSEMENT_ADH = ID_ETABLISSEMENT_DEST, @ID_ETABLISSEMENT_OF = ID_ETABLISSEMENT_OF_DEST
         		FROM	[TRANSACTION]
         		WHERE	ID_TRANSACTION = @ID_TRANSACTION 
         
         
         		IF @ID_ETABLISSEMENT_ADH IS NOT NULL
         		BEGIN
         			SELECT	@ID_DEST = ID_ADHERENT
         			FROM	ETABLISSEMENT
         			WHERE	ID_ETABLISSEMENT = @ID_ETABLISSEMENT_ADH
         		END
         		ELSE
         		BEGIN
         			SELECT	@ID_DEST = ID_OF
         			FROM	ETABLISSEMENT_OF
         			WHERE	ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF
         		END
         		SET @LIBELLE_ECRITURE	= 'HT Vir ' + CAST(@NUM_VIREMENT AS VARCHAR) +  ' ' + CASE @ID_DISPOSITIF WHEN 7 THEN 'FT' ELSE 'CPRO' END
         		SET @LIBELLE_ECRITURE	= @LIBELLE_ECRITURE	 + ' ' + CAST(@ID_DEST AS VARCHAR)
         		
         		SET @NUM_CPT = 'XXXXXX'
         		SELECT @NUM_CPT = NUM_CPT_COMPTA
         		FROM PARAM_COMPTA_PRO
         		WHERE	ID_DISPOSITIF = @ID_DISPOSITIF 
         
         		--SET @NUM_CPT = @NUM_CPT + RIGHT(@NUM_ANNEE, 2)   -- Changement SPEC demande par ED le 04/04/2008
         		SET @NUM_CPT = @NUM_CPT + '00'
         
         		-- Ecriture HT
         		INSERT INTO ECRITURE_COMPTABLE
         		(
         		COD_TRAITEMENT,
         		DATE_PIECE,
         		REF_ECRITURE,
         		LIBELLE_ECRITURE,
         		LIB_NOM_JNL_BANQUE,
         		NUM_CPT_COMPTA_BANCAIRE,
         		MNT,
         		SENS, 
         		TYPE_COMPTE, 
         		NUM_CPT_AUXILIAIRE)
         		VALUES
         		(
         		@COD_TRAITEMENT, 
         		@DATE_PIECE, 
         		@REF_ECRITURE, 
         		@LIBELLE_ECRITURE, 
         		@LIB_NOM_JNL_BANQUE, 
         		@NUM_CPT, 
         		@MNT_HT, 
         		'D',
         		'',
         		''
         		)
         
         		IF @MNT_TVA > 0
         		BEGIN
         			-- Ecriture TVA
         			SET @LIBELLE_ECRITURE	= 'TVA Vir ' + CAST(@NUM_VIREMENT AS VARCHAR) +  ' ' + CASE @ID_DISPOSITIF WHEN 7 THEN 'FT' ELSE 'CPRO' END
         			SET @LIBELLE_ECRITURE	= @LIBELLE_ECRITURE	 + ' ' + CAST(@ID_DEST AS VARCHAR)
         			--SET @NUM_CPT = LEFT(@NUM_CPT_TVA_DEDUCTIBLE, 6) + RIGHT(@NUM_ANNEE, 2) -- Changement SPEC demande par ED le 04/04/2008
         			-- MB Modif du 06/01/2015 Les comptes comptables passent a 12 caracteres
         			--SET @NUM_CPT = LEFT(@NUM_CPT_TVA_DEDUCTIBLE, 6) + '00'
         			SET @NUM_CPT = @NUM_CPT_TVA_DEDUCTIBLE 
         			
         			
         			INSERT INTO ECRITURE_COMPTABLE
         			(
         			COD_TRAITEMENT,
         			DATE_PIECE,
         			REF_ECRITURE,
         			LIBELLE_ECRITURE,
         			LIB_NOM_JNL_BANQUE,
         			NUM_CPT_COMPTA_BANCAIRE,
         			MNT,
         			SENS, 
         			TYPE_COMPTE, 
         			NUM_CPT_AUXILIAIRE)
         			VALUES
         			(
         			@COD_TRAITEMENT, 
         			@DATE_PIECE, 
         			@REF_ECRITURE, 
         			@LIBELLE_ECRITURE, 
         			@LIB_NOM_JNL_BANQUE, 
         			@NUM_CPT , 
         			@MNT_TVA, 
         			'D',
         			'',
         			''
         			)
         
         		END
         
         		SET @MNT_TOTAL_HT = @MNT_TOTAL_HT + @MNT_HT
         		SET @MNT_TOTAL_TVA = @MNT_TOTAL_TVA + @MNT_TVA
         
         		FETCH cu_compta_pro INTO
         			@ID_REGLEMENT_PRO	, 
         			@NUM_VIREMENT		, 
         			@NUM_ANNEE			, 
         			@ID_DISPOSITIF		, 
         			@MNT_HT				,
         			@MNT_TVA				
         
         	END
         
         	--SELECT TOTAL_HT = @MNT_TOTAL_HT , TOTAL_TVA = @MNT_TOTAL_TVA, TOTAL_TTC = @MNT_TOTAL_HT + @MNT_TOTAL_TVA
         
         	CLOSE cu_compta_pro 
         	DEALLOCATE cu_compta_pro 
         
         
         	-- Mise a jour des reglements pour mettre a jour la adte de passage en compta des reglements
         	UPDATE REGLEMENT_PRO
         	SET REGLEMENT_PRO.DAT_COMPTA_REGLEMENT = GETDATE()
         	WHERE DAT_VALID_REGLEMENT IS NOT NULL AND REGLEMENT_PRO.DAT_COMPTA_REGLEMENT IS NULL
         END
GO
 CREATE PROCEDURE [dbo].[UPD_INS_MASSE_SALARIALE_ETABLISSEMENT_EXTRANET] 
          @ID_ETABLISSEMENT int, 
          @MASSE_SALARIALE int,
          @MASSE_SALARIALE_CDD int,
          @ANNEE int
         AS
         -- ===========================================
         -- LDE 03/01/2013 #16701 : NLE - masses salariales ‚tablissement
         -- =============================================
         BEGIN
          DECLARE @ID_PERIODE int
          SELECT @ID_PERIODE = ID_PERIODE FROM PERIODE WHERE cod_periode = @ANNEE AND ID_TYPE_PERIODE = 1
          
          IF (@ID_PERIODE IS NOT NULL)
          BEGIN 
           IF EXISTS (SELECT 1 FROM R21_BIS WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT AND ID_PERIODE = @ID_PERIODE )
            UPDATE R21_BIS 
            SET MASSE_SALARIALE_REELLE = @MASSE_SALARIALE,
             MASSE_SALARIALE_CDD = @MASSE_SALARIALE_CDD
            WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT AND ID_PERIODE = @ID_PERIODE 
           ELSE
            INSERT INTO R21_BIS 
             (ID_ETABLISSEMENT, ID_PERIODE, MASSE_SALARIALE_REELLE, MASSE_SALARIALE_CDD) 
            VALUES 
             (@ID_ETABLISSEMENT, @ID_PERIODE , @MASSE_SALARIALE, @MASSE_SALARIALE_CDD)
          END
         END
GO
CREATE PROCEDURE [dbo].[INS_MOTIF_RELANCE]
          @COD_MOTIF_RELANCE VARCHAR(8),  
          @LIBC_MOTIF_RELANCE VARCHAR(20),  
          @LIBL_MOTIF_RELANCE VARCHAR(50),  
          @BLN_PRIO TINYINT,  
          @BLN_ACTIF TINYINT,  
          @NUM_ORDRE INTEGER,
          @ID_UTILISATEUR INTEGER,
          @COM_MOTIF_RELANCE VARCHAR(255)  
         AS
         BEGIN
          INSERT INTO MOTIF_RELANCE
          (
           COD_MOTIF_RELANCE,
           LIBC_MOTIF_RELANCE,
           LIBL_MOTIF_RELANCE,
           BLN_ACTIF,
           DAT_CREATION,
           DAT_MODIF,
           NUM_ORDRE,
           ID_UTILISATEUR
          )
          VALUES  
          (
           @COD_MOTIF_RELANCE,
           @LIBC_MOTIF_RELANCE,
           @LIBL_MOTIF_RELANCE,
           @BLN_ACTIF,
           GETDATE(),
           GETDATE(),
           @NUM_ORDRE,
           @ID_UTILISATEUR
          )  
         
          SELECT @@IDENTITY AS ID
         
         END
GO

         ----------------------------------------------  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT
         ----------------------------------------------  
         
         CREATE PROCEDURE [dbo].[REPRISE_HISTO_DGEFP]
         	@ID_CONTRAT_PRO			AS INT
         AS
         BEGIN
         	
         	DECLARE @NB_UNITE_FORMATION_TOT AS decimal(18,2)
         	DECLARE @NB_UNITE_TOTAL_TOT AS decimal(18,2)
         	DECLARE @NB_ORGANISMES_INTERVENANTS AS INT
         	DECLARE @NUM_SIRET_ORGANISME_PRINCIPAL AS VARCHAR(14)
         	DECLARE @BLN_EXTERNE tinyint
         
         	SELECT	@NB_UNITE_FORMATION_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_FORMATION),0), 
         			@NB_UNITE_TOTAL_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_TOTALE),0) 
         	FROM	CONTRAT_PRO 
         			INNER JOIN MODULE_PRO ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         			INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
         			AND	MODULE_PRO.BLN_ACTIF = 1			
         			AND TYPE_FORMATION.COD_TYPE_FORMATION != 'FTUT'
         
         	SELECT   @NB_ORGANISMES_INTERVENANTS = COUNT(DISTINCT ETABLISSEMENT_OF.ID_OF)
         	FROM	 MODULE_PRO 
         			 INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE		MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_ACTIF = 1
         
         	SET		@NUM_SIRET_ORGANISME_PRINCIPAL = NULL
         	SET		@BLN_EXTERNE = 1
         	SELECT  @NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT_OF.NUM_SIRET,
         			@BLN_EXTERNE					= MODULE_PRO .BLN_EXTERNE 
         	FROM    MODULE_PRO 
         			LEFT JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE	MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_PRINCIPAL = 1
         
         	IF @NUM_SIRET_ORGANISME_PRINCIPAL IS NULL AND @BLN_EXTERNE = 0
         	BEGIN
         		SELECT	@NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT.NUM_SIRET
         		FROM	CONTRAT_PRO
         				INNER JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT 
         		WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         	END
         
         
         	SELECT  TOP 1 CONTRAT_PRO.*,
         			@NB_UNITE_FORMATION_TOT			AS NB_UNITE_FORMATION,
         			@NB_UNITE_TOTAL_TOT				AS NB_UNITE_TOTALE,
         			CLASSIFICATION.COD_CLASSIFICATION, 
         			TYPE_CONTRAT_PRO.COD_TYPE_CONTRAT_PRO,
         			ADHERENT.LIB_RAISON_SOCIALE					AS LIB_RAISON_SOCIALE_ADH,
         			ETABLISSEMENT.NUM_SIRET						AS NUM_SIRET_ADH,
         			ADRESSE.LIB_ADR								AS LIB_ADR1_ADH,
         			ADRESSE.LIB_COMP_VOIE						AS LIB_ADR2_ADH,
         			ADRESSE.LIB_CP_CEDEX						AS LIB_CP_CEDEX_ADH,
         			ADRESSE.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_ADH,
         			ETABLISSEMENT_OF.NUM_SIRET					AS NUM_SIRET_OF,
         			TUTEUR.NOM_INDIVIDU							AS NOM_INDIVIDU_TUTEUR,
         			TUTEUR.PRENOM_INDIVIDU						AS PRENOM_INDIVIDU_TUTEUR,
         			TUTEUR.BLN_MASCULIN							AS BLN_MASCULIN_TUTEUR,
         			SALARIE_PRO.COD_IDE,
         			SALARIE_PRO.ID_TRANCHE_AGE, 
         			SALARIE_PRO.ID_NATIONALITE, 
         			SALARIE_PRO.BLN_TRAVAILLEUR_HANDICAPE,
         			SALARIE_PRO.LIB_DERNIERE_CERTIF_PROF,
         			SALARIE_PRO.LIB_DERNIER_EMPLOI_OCCUPE,
         			SALARIE_PRO.NUM_DUREE_SITUATION,
         
         			ADRESSE_SALARIE_PRO.NUM_TEL								AS NUM_TEL_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_FAX								AS NUM_FAX_SALARIE_PRO,
         			SALARIE_PRO.NUM_MOBILE									AS NUM_MOBILE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_VOIE							AS NUM_VOIE_SALARIE_PRO,
         			COMP_NUM_ADR_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO,
         			TYPE_VOIE_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE_SALARIE_PRO,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE_SALARIE_PRO.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE_SALARIE_PRO.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         																	AS LIB_MENTION_PARTICULIERE_SALARIE_PRO,
         			HEXAPOSTE_SALARIE_PRO.COD_INSEE_COMMUNE					AS COD_INSEE_COMMUNE_SALARIE_PRO,
         			PAYS_SALARIE_PRO.COD_DDTEFP								AS COD_PAYS_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_COMP_VOIE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_ADR								AS LIB_ADR1_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_ADR2_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_CP_CEDEX						AS LIB_CP_CEDEX_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_SALARIE_PRO,
         
         			INDIVIDU.BLN_MASCULIN,
         			INDIVIDU.NOM_INDIVIDU,
         			INDIVIDU.PRENOM_INDIVIDU,
         			INDIVIDU.NOM_JEUNE_FILLE,
         			INDIVIDU.DAT_NAISSANCE,
         			NATIONALITE.COD_DDTEFP						AS COD_DDTEFP_NATIONALITE,
         			ADRESSE.NUM_TEL,
         			ADRESSE.NUM_FAX,
         			SALARIE_PRO.NUM_MOBILE,
         			ADRESSE.NUM_VOIE,
         			COMP_NUM_ADR.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE,
         			TYPE_VOIE.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         			AS LIB_MENTION_PARTICULIERE,
         			HEXAPOSTE.COD_INSEE_COMMUNE,
         			PAYS.COD_DDTEFP							AS COD_PAYS,
         			ADRESSE.LIB_COMP_VOIE,
         			TIERS.NUM_SIRET							AS NUM_SIRET_TIERS,
         			TIERS.COD_TIERS							AS COD_TIERS,
         			IDCC.COD_IDCC, 
         			IDCC.LIBL_IDCC,
         			NIVEAU.COD_DDTEFP						AS COD_DDTEFP_NIVEAU,
         			DIPLOME.COD_DDTEFP						AS COD_DDTEFP_DIPLOME, 
         			SITUATION_SALARIE.COD_DDTEFP			AS COD_DDTEFP_SITUATION_SALARIE,
         			SANCTION.COD_DDTEFP						AS COD_DDTEFP_SANCTION,
         			MOTIF_CLOTURE_PRO.COD_DDTEFP			AS COD_DDTEFP_MOTIF_CLOTURE_PRO,
         			MOTIF_CLOTURE_PRO.BLN_RUPTURE			AS BLN_RUPTURE,
         			TYPE_ISSUE_PRO.COD_TYPE_ISSUE_PRO		AS COD_DDTEFP_TYPE_ISSUE_PRO,
         			TYPE_CONTRAT.COD_DDTEFP					AS COD_DDTEFP_TYPE_CONTRAT,
         			SPECIALITE.COD_DDTEFP					AS COD_DDTEFP_SPECIALITE,
         			@NB_ORGANISMES_INTERVENANTS				AS NB_ORGANISMES_INTERVENANTS,
         			@NUM_SIRET_ORGANISME_PRINCIPAL			AS NUM_SIRET_ORGANISME_PRINCIPAL
         	INTO	#TEMP_CONTRAT
         	FROM	CONTRAT_PRO
         			LEFT  JOIN ETABLISSEMENT		ON ETABLISSEMENT.ID_ETABLISSEMENT	= CONTRAT_PRO.ID_ETABLISSEMENT
         			INNER JOIN ADRESSE				ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE 
         												AND ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         			LEFT JOIN	HEXAPOSTE			ON HEXAPOSTE.ID_HEXAPOSTE = ADRESSE.ID_HEXAPOSTE
         			LEFT JOIN	PAYS				ON PAYS.ID_PAYS = ADRESSE.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR			ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE				ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE
         
         			LEFT JOIN  ADHERENT				ON ADHERENT.ID_ADHERENT				= ETABLISSEMENT.ID_ADHERENT
         			LEFT JOIN CLASSIFICATION		ON CONTRAT_PRO.ID_CLASSIFICATION	= CLASSIFICATION.ID_CLASSIFICATION
         			LEFT JOIN TYPE_CONTRAT_PRO		ON CONTRAT_PRO.ID_TYPE_CONTRAT_PRO = TYPE_CONTRAT_PRO.ID_TYPE_CONTRAT_PRO
         			LEFT JOIN MODULE_PRO			ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         												AND  MODULE_PRO.BLN_PRINCIPAL = 1
         			LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         			LEFT JOIN INDIVIDU	TUTEUR		ON CONTRAT_PRO.ID_TUTEUR = TUTEUR.ID_INDIVIDU
         			INNER JOIN SALARIE_PRO			ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO
         
         			INNER JOIN ADRESSE		AS ADRESSE_SALARIE_PRO		ON ADRESSE_SALARIE_PRO.ID_ADRESSE = SALARIE_PRO.ID_ADRESSE 
         			LEFT JOIN	HEXAPOSTE	AS HEXAPOSTE_SALARIE_PRO	ON HEXAPOSTE_SALARIE_PRO.ID_HEXAPOSTE = ADRESSE_SALARIE_PRO.ID_HEXAPOSTE
         			LEFT JOIN	PAYS		AS PAYS_SALARIE_PRO 		ON PAYS_SALARIE_PRO.ID_PAYS = ADRESSE_SALARIE_PRO.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR	AS COMP_NUM_ADR_SALARIE_PRO	ON ADRESSE_SALARIE_PRO.ID_COMP_NUM_ADR = COMP_NUM_ADR_SALARIE_PRO.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE		AS TYPE_VOIE_SALARIE_PRO	ON TYPE_VOIE_SALARIE_PRO.ID_TYPE_VOIE = ADRESSE_SALARIE_PRO.ID_TYPE_VOIE
         			
         			INNER JOIN INDIVIDU				ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			LEFT JOIN NATIONALITE			ON INDIVIDU.ID_NATIONALITE = NATIONALITE.ID_NATIONALITE
         			LEFT JOIN TIERS					ON CONTRAT_PRO.ID_TIERS_DDTE = TIERS.ID_TIERS
         			LEFT JOIN IDCC					ON CONTRAT_PRO.ID_IDCC = IDCC.ID_IDCC
         			LEFT JOIN NIVEAU				ON SALARIE_PRO.ID_NIVEAU = NIVEAU.ID_NIVEAU
         			LEFT JOIN DIPLOME				ON SALARIE_PRO.ID_DIPLOME = DIPLOME.ID_DIPLOME 
         			LEFT JOIN SITUATION_SALARIE		ON SALARIE_PRO.ID_SITUATION_SALARIE = SITUATION_SALARIE.ID_SITUATION_SALARIE
         			LEFT JOIN SANCTION				ON CONTRAT_PRO.ID_SANCTION = SANCTION.ID_SANCTION
         			LEFT JOIN MOTIF_CLOTURE_PRO		ON CONTRAT_PRO.ID_MOTIF_CLOTURE_PRO = MOTIF_CLOTURE_PRO.ID_MOTIF_CLOTURE_PRO
         			LEFT JOIN TYPE_ISSUE_PRO		ON CONTRAT_PRO.ID_TYPE_ISSUE_PRO = TYPE_ISSUE_PRO.ID_TYPE_ISSUE_PRO
         			LEFT JOIN TYPE_CONTRAT			ON CONTRAT_PRO.ID_TYPE_CONTRAT = TYPE_CONTRAT.ID_TYPE_CONTRAT
         			--LEFT JOIN SPECIALITE			ON CONTRAT_PRO.ID_SPECIALITE = SPECIALITE.ID_SPECIALITE
         			INNER JOIN THEME				ON CONTRAT_PRO.ID_THEME = THEME.ID_THEME 
         			INNER JOIN SPECIALITE			ON THEME.ID_SPECIALITE = SPECIALITE.ID_SPECIALITE
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         	SELECT  UTILISATEUR.LIB_NOM				AS LIB_NOM_UTILISATEUR, 
         			UTILISATEUR.LIB_PNM				AS LIB_PNM_UTILISATEUR,	
         			UTILISATEUR.NUM_TEL				AS NUM_TEL_UTILISATEUR, 
         			UTILISATEUR.EMAIL				AS EMAIL_UTILISATEUR, 
         			AGENCE.NUM_FAX					AS NUM_FAX_AGENCE,
         			AGENCE.NUM_TEL					AS NUM_TEL_AGENCE, 
         			AGENCE.COD_POSTAL				AS COD_POSTAL_AGENCE,
         			AGENCE.LIB_VILLE				AS LIB_VILLE_AGENCE, 
         			AGENCE.LIB_ADR1					AS LIB_ADR1_AGENCE, 
         			HEXAPOSTE.COD_INSEE_COMMUNE		AS COD_INSEE_COMMUNE_AGENCE, 
         			AGENCE.LIB_NOM_CONSEILLER		AS LIB_NOM_CONSEILLER, 
                     AGENCE.LIB_PNM_CONSEILLER		AS LIB_PNM_CONSEILLER
         	INTO	#TEMP_OPERATEUR
         	FROM    CONTRAT_PRO 
         			INNER JOIN UTILISATEUR ON CONTRAT_PRO.ID_UTILISATEUR = UTILISATEUR.ID_UTILISATEUR 
         			INNER JOIN AGENCE ON UTILISATEUR.ID_AGENCE = AGENCE.ID_AGENCE 
         			INNER JOIN HEXAPOSTE ON AGENCE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         
         
         	SELECT	ADHERENT.DAT_CREATION				AS DAT_CREATION_ADHERENT,
         			NAF.COD_NAF							AS COD_NAF, 
         			ADRESSE.NUM_TEL						AS NUM_TEL_ENTREPRENEUR,	
         			ADRESSE.NUM_FAX						AS NUM_FAX_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_ENTREPRENEUR,
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_ENTREPRENEUR,
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_ENTREPRENEUR,
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_ENTREPRENEUR, 
         			ADRESSE.LIB_ADR						AS LIB_ADR_ENTREPRENEUR,  
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_ENTREPRENEUR,
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR
         	INTO	#TEMP_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN NR31 ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT
         								AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 
              -- AND   ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL modif 07/03/2007 ED
         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF 
         			LEFT JOIN  ADRESSE ON ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         									AND ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         			LEFT JOIN TYPE_VOIE ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS ON ADRESSE.ID_PAYS = PAYS.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         			
         
         
         
         	SELECT  CONTACT.LIB_NOM_CONTACT				AS LIB_NOM_CONTACT_ENTREPRENEUR, 
         			CONTACT.LIB_PNM_CONTACT				AS LIB_PNM_CONTACT_ENTREPRENEUR, 
         			CIVILITE.COD_DDTEFP					AS COD_DDTEFP_CIVILITE_CONTACT_ENTREPRENEUR, 
         			NAF.COD_NAF							AS COD_NAF_CONTACT_ENTREPRENEUR,
         			NR31.NUM_TEL						AS NUM_TEL_CONTACT_ENTREPRENEUR, 
         			NR31.NUM_FAX						AS NUM_FAX_CONTACT_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_CONTACT_ENTREPRENEUR, 
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_CONTACT_ENTREPRENEUR, 
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_CONTACT_ENTREPRENEUR, 
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEF_TYPE_VOIE_CONTACT_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_CONTACT_ENTREPRENEUR, 
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_CONTACT_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_CONTACT_ENTREPRENEUR,
         			ADRESSE.LIB_ADR						AS LIB_ADR_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_CONTACT_ENTREPRENEUR
         	INTO	#TEMP_CONTACT_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 
         			--AND ETABLISSEMENT.ID_ETABLISSEMENT = ADHERENT.ID_ETABLISSEMENT_PRINCIPAL modif 07/03/2007 ED
         			LEFT JOIN NR31  ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT 
         						AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADRESSE ON NR31.ID_ADRESSE = ADRESSE.ID_ADRESSE 
         			LEFT JOIN CONTACT ON NR31.ID_CONTACT = CONTACT.ID_CONTACT
         			LEFT JOIN CIVILITE ON CONTACT.ID_CIVILITE = CIVILITE.ID_CIVILITE 
         			LEFT JOIN TYPE_VOIE ON ADRESSE.ID_TYPE_VOIE = TYPE_VOIE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS  ON PAYS.ID_PAYS = ADRESSE.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR 
         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         
         
         
         	--SELECT * FROM #TEMP_CONTRAT
         	--SELECT * FROM #TEMP_OPERATEUR
         	--SELECT * FROM #TEMP_ENTREPRENEUR
         	--SELECT * FROM #TEMP_CONTACT_ENTREPRENEUR
         
         	SELECT	* INTO #TMP_HISTO
         	FROM	#TEMP_CONTRAT
         			FULL OUTER JOIN #TEMP_OPERATEUR	ON 1=1
         			FULL OUTER JOIN #TEMP_ENTREPRENEUR ON 1=1
         			FULL OUTER JOIN #TEMP_CONTACT_ENTREPRENEUR ON 1=1
         
         	INSERT INTO HISTO_CONTRAT_DGEFP
         	(
         	ID_CONTRAT_PRO	,
         	NUM_AVENANT	,
         	DAT_CREATION	,
         	DAT_ENVOI_DGEFP	,
         	BLN_EXONERATION_CHARGES	,
         	NUM_ENREGISTREMENT_DDTE	,
         	DAT_DEPOT_DDTE	,
         	DAT_ENREGISTREMENT_DDTE	,
         	BLN_INITIAL	,
         	BLN_MODIFICATION	,
         	BLN_AVENANT	,
         	DAT_DEB_CONTRAT	,
         	DAT_FIN_CONTRAT	,
         	NUM_DUREE_HEBDO_TRAVAIL	,
         	NUM_DUREE_PERIODE_ESSAI	,
         	NUM_DUREE_CONTRAT	,
         	NB_UNITE_FORMATION	,
         	COD_CLASSIFICATION	,
         	COEF_CLASSIFICATION	,
         	MNT_SALAIRE_BRUT_MENSUEL	,
         	COD_TYPE_CONTRAT	,
         	DAT_SIGNATURE_CONTRAT	,
         	LIB_RAISON_SOCIALE_ADH	,
         	NUM_SIRET_ADH	,
         	LIB_ADR1_ADH	,
         	LIB_ADR2_ADH	,
         	LIB_CP_CEDEX_ADH	,
         	LIB_VIL_CEDEX_ADH	,
         	NUM_SIRET_OF	,
         	NOM_INDIVIDU_TUTEUR	,
         	PRENOM_INDIVIDU_TUTEUR	,
         	LIB_QUALIF_TUTEUR	,
         	NOM_FICHIER_XML	,
         	STATUT_HISTO	,
         	MOTIF_CONTROL_CONFORMITE	,
         	COMMENTAIRE_COMMANDITAIRE	,
         	ETAT_TRAITEMENT_HISTO	,
         	NUM_DEPOT_DDTE	,
         	LIB_LIEU_FORMATION	,
         	DAT_EXAMEN	,
         	LIBL_QUALIFICATION_VISEE	,
         	NB_ORGANISMES_INTERVENANTS	,
         	NUM_SIRET_ORGANISME_PRINCIPAL	,
         	EMAIL_PRO_ENTREPRENEUR	,
         	COD_NAF	,
         	COD_DDTEFP_COMP_NUM_ADR_ENTREPRENEUR	,
         	NUM_VOIE_ENTREPRENEUR	,
         	LIB_ADR_ENTREPRENEUR	,
         	LIB_COMP_VOIE_ENTREPRENEUR	,
         	LIB_CP_CEDEX_ENTREPRENEUR	,
         	LIB_VIL_CEDEX_ENTREPRENEUR	,
         	LIB_MENTION_PARTICULIERE_ENTREPRENEUR	,
         	COD_INSEE_COMMUNE_ENTREPRENEUR	,
         	COD_PAYS_ENTREPRENEUR	,
         	COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR	,
         	LIB_CAISSE_RETRAITE	,
         	NUM_FAX_ENTREPRENEUR	,
         	NUM_TEL_ENTREPRENEUR	,
         	LIB_ORGANISME_PREVOYANCE	,
         	NUM_NB_SALARIE_ETABLISSEMENT	,
         	DAT_CLOTURE	,
         	BLN_PARTICIPATION_FINANCIERE	,
         	COD_DDTEFP_DIPLOME	,
         	COD_DDTEFP_NIVEAU	,
         	COD_DDTEFP_NATIONALITE	,
         	COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO	,
         	BLN_MASCULIN	,
         	DAT_NAISSANCE	,
         	LIB_ADR1_SALARIE_PRO	,
         	LIB_ADR2_SALARIE_PRO	,
         	LIB_MENTION_PARTICULIERE_SALARIE_PRO	,
         	LIB_VIL_CEDEX_SALARIE_PRO	,
         	LIB_CP_CEDEX_SALARIE_PRO	,
         	COD_INSEE_COMMUNE_SALARIE_PRO	,
         	NUM_VOIE_SALARIE_PRO	,
         	COD_PAYS_SALARIE_PRO	,
         	LIB_DERNIERE_CERTIF_PROF	,
         	LIB_DERNIER_EMPLOI_OCCUPE	,
         	COD_IDE	,
         	PRENOM_INDIVIDU	,
         	NOM_INDIVIDU	,
         	NUM_DUREE_SITUATION	,
         	COD_DDTEFP_SITUATION_SALARIE	,
         	BLN_TRAVAILLEUR_HANDICAPE	,
         	OBTENTION_QUALIFICATION	,
         	COD_DDTEFP_MOTIF_CLOTURE_PRO	,
         	COD_DDTEFP_TYPE_VOIE_SALARIE_PRO	,
         	COD_DDTEFP_TYPE_ISSUE_PRO	,
         	COD_DDTEFP_SANCTION	,
         	LIB_EMPLOI_OCCUPE	,
         	NB_UNITE_TOTALE	,
         	COD_DDTEFP_SPECIALITE	,
         	COD_IDCC	,
         	LIBL_IDCC	)
         
         SELECT
         ID_CONTRAT_PRO	,
         NUM_DERNIER_AVENANT	,
         DAT_CREATION	,
         DAT_CREATION	,
         BLN_EXONERATION_CHARGES	,
         NUM_ENREGISTREMENT_DDTE	,
         DAT_DEPOT_DDTE	,
         DAT_ENREGISTREMENT_DDTE	,
         BLN_INITIAL=	CASE NUM_DERNIER_AVENANT WHEN NULL THEN 1 ELSE NULL END,
         BLN_MODIFICATION = NULL,	
         BLN_AVENANT =CASE NUM_DERNIER_AVENANT WHEN NULL THEN NULL ELSE 1 END,
         DAT_DEB_CONTRAT	,
         DAT_FIN_CONTRAT	,
         NUM_DUREE_HEBDO_TRAVAIL	,
         NUM_DUREE_PERIODE_ESSAI	,
         NUM_DUREE_CONTRAT	,
         NB_UNITE_FORMATION	,
         COD_CLASSIFICATION	,
         COEF_CLASSIFICATION	,
         MNT_SALAIRE_BRUT_MENSUEL	,
         COD_TYPE_CONTRAT_PRO	,
         DAT_SIGNATURE_CONTRAT	,
         LIB_RAISON_SOCIALE_ADH	,
         NUM_SIRET_ADH	,
         LIB_ADR1_ADH	,
         LIB_ADR2_ADH	,
         LIB_CP_CEDEX_ADH	,
         LIB_VIL_CEDEX_ADH	,
         ISNULL(NUM_SIRET_OF, '')	,
         NOM_INDIVIDU_TUTEUR	,
         PRENOM_INDIVIDU_TUTEUR	,
         LIB_QUALIF_TUTEUR	,
         'XML.XML'	,
         30	,
         NULL	,
         NULL	,
         1	,
         NUM_ENREGISTREMENT_DDTE	,
         LIB_LIEU_FORMATION	,
         DAT_EXAMEN	,
         LIBL_QUALIFICATION_VISEE	,
         NB_ORGANISMES_INTERVENANTS	,
         NUM_SIRET_ORGANISME_PRINCIPAL	,
         EMAIL_PRO_ENTREPRENEUR	,
         COD_NAF	,
         COD_DDTEFP_COMP_NUM_VOIE	,
         NUM_VOIE_ENTREPRENEUR	,
         LIB_ADR_ENTREPRENEUR	,
         LIB_COMP_VOIE_ENTREPRENEUR	,
         LIB_CP_CEDEX_ENTREPRENEUR	,
         LIB_VIL_CEDEX_ENTREPRENEUR	,
         LIB_MENTION_PARTICULIERE_ENTREPRENEUR	,
         COD_INSEE_COMMUNE_ENTREPRENEUR	,
         COD_PAYS_ENTREPRENEUR	,
         COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR	,
         LIB_CAISSE_RETRAITE	,
         NUM_FAX_ENTREPRENEUR	,
         NUM_TEL_ENTREPRENEUR	,
         LIB_ORGANISME_PREVOYANCE	,
         NUM_NB_SALARIE_ETABLISSEMENT	,
         DAT_CLOTURE	,
         BLN_PARTICIPATION_FINANCIERE	,
         COD_DDTEFP_DIPLOME	,
         COD_DDTEFP_NIVEAU	,
         COD_DDTEFP_NATIONALITE	,
         COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO	,
         BLN_MASCULIN	,
         DAT_NAISSANCE	,
         LIB_ADR1_SALARIE_PRO	,
         LIB_ADR2_SALARIE_PRO	,
         LIB_MENTION_PARTICULIERE_SALARIE_PRO	,
         LIB_VIL_CEDEX_SALARIE_PRO	,
         LIB_CP_CEDEX_SALARIE_PRO	,
         COD_INSEE_COMMUNE_SALARIE_PRO	,
         NUM_VOIE_SALARIE_PRO	,
         COD_PAYS_SALARIE_PRO	,
         LIB_DERNIERE_CERTIF_PROF	,
         LIB_DERNIER_EMPLOI_OCCUPE	,
         COD_IDE	,
         PRENOM_INDIVIDU	,
         NOM_INDIVIDU	,
         NUM_DUREE_SITUATION	,
         COD_DDTEFP_SITUATION_SALARIE	,
         BLN_TRAVAILLEUR_HANDICAPE	,
         BLN_DIPLOME_OBTENU	,
         COD_DDTEFP_MOTIF_CLOTURE_PRO	,
         COD_DDTEFP_TYPE_VOIE_SALARIE_PRO	,
         COD_DDTEFP_TYPE_ISSUE_PRO	,
         COD_DDTEFP_SANCTION	,
         LIB_EMPLOI_OCCUPE	,
         NB_UNITE_TOTALE	,
         COD_DDTEFP_SPECIALITE	,
         COD_IDCC	,
         LIBL_IDCC	
         FROM #TMP_HISTO
         
         END
         
GO

         
         CREATE PROCEDURE [dbo].[UPD_PIECES_STAGIAIRE_NON_CONFORM]  
         	@ID_MOTIF int,
         	@ID_ARRIVEE_PIECE int,
         	@BLN_ACTIF int
         AS  
         
         BEGIN
         	DECLARE @EXIST int
         
         	SELECT @EXIST = COUNT (*)
         	FROM NR210
         	WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         	AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE
         
         	IF @EXIST <> 0
         	BEGIN
         		IF @BLN_ACTIF = 0
         		BEGIN
         			DELETE NR210
         			WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         				AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE
         		END
         	END
         	ELSE
         	BEGIN
         		IF @BLN_ACTIF = 1 AND @ID_ARRIVEE_PIECE IS NOT NULL			
         			INSERT INTO NR210
         				(ID_MOTIF_NON_CONFORM_PIECE, ID_ARRIVEE_PIECE_PEC)
         			VALUES
         				(@ID_MOTIF, @ID_ARRIVEE_PIECE)
         	END
         
         END
         
GO
CREATE PROCEDURE [dbo].[BATCH_INS_MVT_BUDGETAIRE_CONTRAT_PRO] 
          @ID_EVENEMENT int = NULL
         AS 
         
         
         
         -- =============================================
         -- Author  : MB
         -- Create date : 12/03/2008
         -- Description : insertion des mouvements budgetaires associes aux evenements budgetaires des contrats de professionnalisation
         -- Ce batch est lance toutes les nuits
         -- ---------------------------------------------
         -- Author  : ASD-SBR
         -- Modified date: 23/10/2008
         -- Description : gestion du paramŠtre @ID_EVENEMENT=NULL si pas fourni dans le scheduler
         -- ---------------------------------------------
         -- Author  : RMA
         -- Modified date: 24/10/2008
         -- Description : Ajout ID_GROUPE
         -- ---------------------------------------------
         -- Author  : DCL
         -- Modified date: 27/04/2009
         -- Description : reglement PRO : separation ADH / OF (ano 11843)
         -- RAF : desengagement ? evenemnt REGLTPRO ou REGLADH. reprise donn‚es...
         -- ---------------------------------------------
         -- Author  : DSZ
         -- Modified date: 05/03/2010
         -- Description : Ano 12261. Pour les cpro repris le mvt de cloture doit ˆtre du type E
         -- ---------------------------------------------
         -- Author  : MBT : Mohamed BENSLIMANE
         -- Modified date: 12/03/2010
         -- Description : EVOL 12271. Ajout de la partie cl“ture d'un module pro
         -- ---------------------------------------------
         -- Author  : ASD
         -- Modified date: 03/11/2010
         -- Description : ANO 12386. ne pas forcer le P_E_R a E en cloture de module
         -- Description  : ne pas cloturer tous les modules en mˆme temps, mais uniquement ceux nouvellement clotur‚s !
         -- ---------------------------------------------
         -- Author  : ASD
         -- Modified date: 09/06/2011
         -- Description : ANO 12730. PERF : ajout de "top 1" dans les exists et not exists
         --         et remplace AND ID_EVENEMENT = ISNULL(@ID_EVENEMENT, ID_EVENEMENT)
         --           par  AND (@ID_EVENEMENT is null OR @ID_EVENEMENT = ID_EVENEMENT)
         -- ---------------------------------------------
         -- Author  : DSZ
         -- Modified date: 28/09/2011
         -- Description : 12881. Remplacement Adherent.Id_BRANCHE par salarie_pro.id_branche
         -- (branche historis‚e dans le salari‚)
         -- ---------------------------------------------
         -- DSZ/LDE 02/04/2015 #808 Les mouvements budg‚taires de type D‚sengagement cr‚‚s … la suite d'un ‚vŠnement de cl“ture d'un module pro 
         -- doivent comporter l'id_groupe. 
         -- =============================================
         
          BEGIN
          DECLARE 
           @ID_TYPE_EVENEMENT    int,
           @DAT_EVENEMENT     datetime,
           @ID_CONTRAT_PRO     int,
           @ID_MODULE_PRO     int,
           @COD_TYPE_EVENEMENT    varchar(8),
           @COD_CONTRAT_PRO    varchar(10),
           @COD_MODULE_PRO     varchar(12),
           @ID_TYPE_MOUVEMENT    int,
           @P_E_R       varchar(1),
           @LIBL_MVT_BUDGETAIRE   varchar(50),
           @ID_ETABLISSEMENT    int, 
           @ID_ADHERENT     int,
           @ID_ENVELOPPE     int,
           @ID_BRANCHE      int,
           @ID_PERIODE      int,
           @ID_DISPOSITIF     int,
           @DAT_DEB_CONTRAT    datetime,
           @DAT_MODIF      datetime,
           @DAT_CLOTURE     datetime,
           @ID_AGENCE      int,
           @ID_ACTIVITE     int,
           @ID_ENGAGEMENT_PRO    int,
           @ID_SESSION_PRO     int,
           @BLN_OK       tinyint,
           @MNT_MODULE_HT     float,
           @MNT_ATTESTE_HT     float,
           @MNT_MVT_BUDGETAIRE    float,
           @ID_MVT_BUDGETAIRE    int,
           @BLN_ACTIF      tinyint,
           @ID_TYPE_FORMATION    int,
           @DAT_MVT      datetime,
           @ID_REGLEMENT_PRO    int,
           @ID_GROUPE      int
           --DCL 27/04/2009
           , @ID_REGLEMENT_PRO_ADH    int,
           @ID_REGLEMENT_PRO_OF    int,
           @MNT_VERSE_HT_ADH     float, -- au lieu de montant attest‚
           @MNT_VERSE_HT_OF     float
         
          SET @ID_ACTIVITE = 3 -- Professionnalisation
         
          -- Selection des evenements associes au contrat de professionnalisation
          -- pour lesquels aucun mouvement budgetaire n'a ete genere
          DECLARE cu_evenement_contrat_pro SCROLL CURSOR FOR
          SELECT ID_EVENEMENT, ID_TYPE_EVENEMENT, DAT_EVENEMENT, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_ENGAGEMENT_PRO, ID_SESSION_PRO
          FROM EVENEMENT
          WHERE (ID_CONTRAT_PRO IS NOT NULL OR ID_MODULE_PRO IS NOT NULL)
           --20110609 ajout ici de top 1 
           AND NOT EXISTS (SELECT top 1 1 FROM MVT_BUDGETAIRE WHERE MVT_BUDGETAIRE.ID_EVENEMENT = EVENEMENT.ID_EVENEMENT )
           --20110609 remplac‚ car trop trop long  : AND ID_EVENEMENT = ISNULL(@ID_EVENEMENT, ID_EVENEMENT)
           AND (@ID_EVENEMENT is null OR @ID_EVENEMENT = ID_EVENEMENT)
          UNION
          --Selection des evenements de chiffrage associes a des modules dont les mouvements budgetaires previsionnels n'ont pas ete generes
          SELECT DISTINCT ID_EVENEMENT, ID_TYPE_EVENEMENT, DAT_EVENEMENT, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_ENGAGEMENT_PRO, ID_SESSION_PRO
          FROM EVENEMENT
          WHERE (ID_CONTRAT_PRO IS NOT NULL)--  20110609 inutile, la premiere clause suffit : OR ID_MODULE_PRO IS NOT NULL)
           AND EXISTS (
             --20110609 ajout ici de top 1 
             SELECT top 1 ID_MODULE_PRO = ID_MODULE_PRO 
             FROM MODULE_PRO 
             WHERE EVENEMENT.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
             AND MODULE_PRO.BLN_ACTIF = 1 AND MODULE_PRO.ID_ENGAGEMENT_PRO is null
             --20110609 ajout ici de top 1 
             AND NOT EXISTS (SELECT top 1 1 FROM MVT_BUDGETAIRE WHERE MVT_BUDGETAIRE.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO AND P_E_R = 'P')
             )
           AND EVENEMENT.ID_TYPE_EVENEMENT = 18 -- Chiffrage contrat PRO
           --20110609 remplac‚ car trop trop long  : AND ID_EVENEMENT = ISNULL(@ID_EVENEMENT, ID_EVENEMENT)
           AND (@ID_EVENEMENT is null OR @ID_EVENEMENT = ID_EVENEMENT)
          ORDER BY ID_EVENEMENT 
         
         
         
          OPEN cu_evenement_contrat_pro
          FETCH cu_evenement_contrat_pro INTO @ID_EVENEMENT, @ID_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_ENGAGEMENT_PRO, @ID_SESSION_PRO
         
         
          WHILE (@@fetch_status <> -1)
          BEGIN
         
           SELECT @COD_TYPE_EVENEMENT = COD_TYPE_EVENEMENT
           FROM TYPE_EVENEMENT
           WHERE ID_TYPE_EVENEMENT = @ID_TYPE_EVENEMENT 
         
           SELECT @COD_CONTRAT_PRO = COD_CONTRAT_PRO    , 
             @ID_ETABLISSEMENT = CONTRAT_PRO.ID_ETABLISSEMENT , 
             @ID_GROUPE   = ETABLISSEMENT.ID_GROUPE  ,
             @ID_ADHERENT  = ADHERENT.ID_ADHERENT   ,
             @ID_AGENCE   = CONTRAT_PRO.ID_AGENCE   ,
             @ID_BRANCHE   = SALARIE_PRO.ID_BRANCHE  ,
             @DAT_DEB_CONTRAT = CONTRAT_PRO.DAT_DEB_CONTRAT ,
             @DAT_MODIF   = CONTRAT_PRO.DAT_MODIF   ,
             @DAT_CLOTURE  = CONTRAT_PRO.DAT_CLOTURE
           FROM   CONTRAT_PRO
            INNER JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
            INNER JOIN ADHERENT  ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
            INNER JOIN  SALARIE_PRO  ON SALARIE_PRO.ID_SALARIE_PRO = CONTRAT_PRO.ID_SALARIE_PRO
           WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO
           
           IF @ID_MODULE_PRO IS NOT NULL 
           BEGIN
            SELECT @COD_MODULE_PRO = COD_MODULE_PRO
            FROM MODULE_PRO
            WHERE ID_MODULE_PRO = @ID_MODULE_PRO
           END
         
          /* ********************************************************** 
          -- Chiffrage d'un contrat de professionnalisation
          TYPE_EVENEMENT = 'CHIF_PRO'
           ********************************************************** */
           IF  @COD_TYPE_EVENEMENT = 'CHIF_PRO'   -- Chiffrage d'un contrat de professionnalisation
           BEGIN
            /*
             Un mouvement pr‚visionnel est cr‚‚ pour tous les modules actifs associes au module 
            */
             
            SELECT @ID_TYPE_MOUVEMENT = 18 --Mouvement Pr‚vision
            SELECT @P_E_R = 'P'     -- Pr‚vision
            SELECT @LIBL_MVT_BUDGETAIRE = 'Chiffrage Contrat PRO ' + CAST(@COD_CONTRAT_PRO AS VARCHAR)
           
            DECLARE cu_module_previsionnel SCROLL CURSOR FOR
            SELECT MODULE_PRO.ID_CONTRAT_PRO, MODULE_PRO.ID_MODULE_PRO, MODULE_PRO.ID_PERIODE,  MODULE_PRO.MNT_MODULE_HT, MODULE_PRO.BLN_ACTIF, MODULE_PRO.ID_ENGAGEMENT_PRO, MODULE_PRO.ID_TYPE_FORMATION, TYPE_FORMATION.ID_DISPOSITIF
            FROM    MODULE_PRO
              INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
            WHERE   ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
            --AND  MODULE_PRO.ID_ENGAGEMENT_PRO IS NULL
            AND  MODULE_PRO.BLN_ACTIF = 1
         
         
            
            OPEN cu_module_previsionnel
            FETCH cu_module_previsionnel INTO
            @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_PERIODE, @MNT_MODULE_HT, @BLN_ACTIF, @ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION, @ID_DISPOSITIF
            WHILE (@@fetch_status <> -1)
            BEGIN
         
             -- Determination de l'enveloppe a associe au module :
             SELECT @ID_ENVELOPPE = ID_ENVELOPPE
             FROM ENVELOPPE
               INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
             WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
             AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
             AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
             AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
         
             
             -- Recherche du mouvement budgetaire previsionnel associe aux modules 
             set @ID_MVT_BUDGETAIRE = null
             SELECT @ID_MVT_BUDGETAIRE = ID_MVT_BUDGETAIRE, @MNT_MVT_BUDGETAIRE = MNT_MVT_BUDGETAIRE
             FROM MVT_BUDGETAIRE
             WHERE ID_EVENEMENT = @ID_EVENEMENT 
             AND  ID_MODULE_PRO = @ID_MODULE_PRO
             AND  P_E_R   = 'P'
             
             
             IF @ID_MVT_BUDGETAIRE is null
             BEGIN
               INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
              ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = @MNT_MODULE_HT, ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_EVENEMENT,
              ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END
             ELSE
             BEGIN
              UPDATE MVT_BUDGETAIRE 
              SET  MNT_MVT_BUDGETAIRE = @MNT_MODULE_HT
              WHERE ID_MVT_BUDGETAIRE = @ID_MVT_BUDGETAIRE
             END
         
             FETCH cu_module_previsionnel INTO
             @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_PERIODE, @MNT_MODULE_HT, @BLN_ACTIF, @ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION, @ID_DISPOSITIF
            END
            CLOSE cu_module_previsionnel
            DEALLOCATE cu_module_previsionnel     
           END
         
         
          /* ********************************************************** 
          -- Annulation d'un contrat de professionnalisation non encore engage 
          TYPE_EVENEMENT = 'ANNCOPRO'
           ********************************************************** */
           IF  @COD_TYPE_EVENEMENT = 'ANNCOPRO'   
           BEGIN
            -- Suppression de tous les mouvements budgetaires previsionnles associes au contrat
            DELETE FROM MVT_BUDGETAIRE 
            WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO
            AND P_E_R = 'P'
           END
         
         
          /* ********************************************************** 
          -- Engagement d'un contrat de professionnalisation
          TYPE_EVENEMENT = 'ENGAGPRO'
           ********************************************************** */
           IF  @COD_TYPE_EVENEMENT = 'ENGAGPRO'   
           BEGIN
         
            DECLARE cu_module_a_engager SCROLL CURSOR FOR
            SELECT MODULE_PRO.ID_CONTRAT_PRO, MODULE_PRO.ID_MODULE_PRO, MODULE_PRO.ID_PERIODE,  MODULE_PRO.MNT_MODULE_HT, MODULE_PRO.BLN_ACTIF, MODULE_PRO.ID_ENGAGEMENT_PRO, MODULE_PRO.ID_TYPE_FORMATION, TYPE_FORMATION.ID_DISPOSITIF
            FROM    MODULE_PRO
              INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
            WHERE   MODULE_PRO.ID_ENGAGEMENT_PRO = @ID_ENGAGEMENT_PRO
            AND  MODULE_PRO.BLN_ACTIF = 1
         
         
            OPEN cu_module_a_engager
            FETCH cu_module_a_engager INTO
            @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_PERIODE, @MNT_MODULE_HT, @BLN_ACTIF, @ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION, @ID_DISPOSITIF
            WHILE (@@fetch_status <> -1)
            BEGIN
         
             -- Determination de l'enveloppe a associer au module :
             SELECT @ID_ENVELOPPE = ID_ENVELOPPE
             FROM ENVELOPPE
               INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
             WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
             AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
             AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
             AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
         
             
             -- Recherche du mouvement budgetaire previsionnel associe aux modules a engager
             SET @ID_MVT_BUDGETAIRE = null
             SELECT @ID_MVT_BUDGETAIRE = ID_MVT_BUDGETAIRE, @MNT_MVT_BUDGETAIRE = MNT_MVT_BUDGETAIRE
             FROM MVT_BUDGETAIRE
             WHERE ID_MODULE_PRO = @ID_MODULE_PRO
             AND  P_E_R   = 'P'
             
             
             IF @ID_MVT_BUDGETAIRE is not null
             BEGIN
              SELECT @ID_TYPE_MOUVEMENT = 19 --Mouvement Annulation Pr‚vision
              SELECT @P_E_R = 'P'     -- Pr‚vision
              SELECT @LIBL_MVT_BUDGETAIRE = 'Annulation prevision Contrat PRO ' + CAST(@COD_CONTRAT_PRO AS VARCHAR)
         
               INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
              ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_EVENEMENT,
              ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END
         
             -- On engage les montants des modules pour lesquels le BAE a ete accorde
             SELECT @ID_TYPE_MOUVEMENT = 20 --Mouvement d'Engagement
             SELECT @P_E_R = 'E'     -- Engagement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Engagement Contrat PRO ' + CAST(@COD_CONTRAT_PRO AS VARCHAR)
         
             INSERT INTO MVT_BUDGETAIRE 
             ( 
             ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
             ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, N_R, ID_ACTIVITE)
             SELECT 
             ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = @MNT_MODULE_HT, ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_EVENEMENT,
             ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
         
             FETCH cu_module_a_engager INTO
             @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_PERIODE, @MNT_MODULE_HT, @BLN_ACTIF, @ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION, @ID_DISPOSITIF
            END
            CLOSE cu_module_a_engager
            DEALLOCATE cu_module_a_engager
               
           END
         
          /* ********************************************************** 
          -- Annulation d'un module engage associe a un contrat de professionnalisation engage 
          TYPE_EVENEMENT = 'DESMOPRO'
          ********************************************************** */
          IF  @COD_TYPE_EVENEMENT = 'DESMOPRO'   -- Annulation d'un module engage associe a un contrat de professionnalisation engage 
           BEGIN
         
            SELECT @ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO, @ID_PERIODE = MODULE_PRO.ID_PERIODE,  @MNT_MODULE_HT = MODULE_PRO.MNT_MODULE_HT, 
              @BLN_ACTIF = MODULE_PRO.BLN_ACTIF, @ID_ENGAGEMENT_PRO = MODULE_PRO.ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION = MODULE_PRO.ID_TYPE_FORMATION, 
              @ID_DISPOSITIF = TYPE_FORMATION.ID_DISPOSITIF
            FROM    MODULE_PRO
              INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
            WHERE   MODULE_PRO.ID_MODULE_PRO = @ID_MODULE_PRO 
         
            -- Determination de l'enveloppe a associer au module :
            SELECT @ID_ENVELOPPE = ID_ENVELOPPE
            FROM ENVELOPPE
              INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
            WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
            AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
            AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
            AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
            
            -- Recherche du mouvement budgetaire previsionnel associe au module a desengager
            SET @MNT_MVT_BUDGETAIRE = 0
            SELECT @MNT_MVT_BUDGETAIRE = ISNULL(MNT_MVT_BUDGETAIRE, 0)
            FROM MVT_BUDGETAIRE
            WHERE ID_MODULE_PRO = @ID_MODULE_PRO
            AND  P_E_R   = 'E'
            
            
            IF @MNT_MVT_BUDGETAIRE > 0
            BEGIN
             -- Diminution de l'engagement a hauteur du montant du module desengage
             SELECT @P_E_R = 'E'     -- Pr‚vision
             SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation ENgagement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Desactivation module pro ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
             INSERT INTO MVT_BUDGETAIRE 
             ( 
             ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
             ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, N_R, ID_ACTIVITE)
             SELECT 
             ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE, ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_EVENEMENT,
             ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
            END     
           END
         
          /* ********************************************************** 
          -- Validation du reglement d'un contrat professionnalisation
          -- TYPE_EVENEMENT = 'REGLTPRO'
         
          -- DCL Comment : a supprimer … J+1 de la livraison du trigger reglement_pro__validation
          ********************************************************** */
           IF @COD_TYPE_EVENEMENT = 'REGLTPRO'   -- Validation du reglement d'un contrat professionnalisation
           BEGIN
             SELECT  @ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO, @ID_PERIODE = MODULE_PRO.ID_PERIODE,  @MNT_ATTESTE_HT = SESSION_PRO.MNT_ATTESTE_HT, 
               @ID_ENGAGEMENT_PRO = MODULE_PRO.ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION = MODULE_PRO.ID_TYPE_FORMATION, 
               @ID_DISPOSITIF = TYPE_FORMATION.ID_DISPOSITIF, @ID_REGLEMENT_PRO = ISNULL(SESSION_PRO.ID_REGLEMENT_PRO_OF, SESSION_PRO.ID_REGLEMENT_PRO_ADH)
             FROM    SESSION_PRO
               INNER JOIN MODULE_PRO  ON MODULE_PRO.ID_MODULE_PRO = SESSION_PRO.ID_MODULE_PRO 
               INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
             WHERE   SESSION_PRO.ID_SESSION_PRO = @ID_SESSION_PRO
         
             -- Determination de l'enveloppe a associer au module :
             SELECT @ID_ENVELOPPE = ID_ENVELOPPE
             FROM ENVELOPPE
               INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
             WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
             AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
             AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
             AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
         
             -- Recherche de la date de reglement
             SELECT @DAT_MVT = DAT_VALID_REGLEMENT
             FROM REGLEMENT_PRO
             WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO 
                
             -- Recherche du mouvement budgetaire d'engagement associe au module a regler
             SET @MNT_MVT_BUDGETAIRE = 0
             SELECT @MNT_MVT_BUDGETAIRE = ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)
             FROM MVT_BUDGETAIRE
             WHERE ID_MODULE_PRO = @ID_MODULE_PRO
             AND  ID_ENVELOPPE = @ID_ENVELOPPE
             AND  P_E_R   = 'E'
             
             
             IF @MNT_MVT_BUDGETAIRE > 0
             BEGIN
              -- Diminution de l'engagement a hauteur du montant du module regle dans la limite de l'engagement initial
         
              IF @MNT_ATTESTE_HT < @MNT_MVT_BUDGETAIRE
              BEGIN
               SET @MNT_MVT_BUDGETAIRE = @MNT_ATTESTE_HT 
              END
              
              SELECT @P_E_R = 'E'     -- Pr‚vision
              SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation Pr‚vision
              SELECT @LIBL_MVT_BUDGETAIRE = 'Annul. engagement suite regl module pro ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
               INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
              ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
              ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
              ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
              @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END     
         
             -- On regle les montants attestes des differentes sessions reglees
             SELECT @ID_TYPE_MOUVEMENT = 22 --Mouvement de Reglement
             SELECT @P_E_R = 'R'     -- Reglement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Reglement Module PRO ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
             INSERT INTO MVT_BUDGETAIRE 
             ( 
             ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
             ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
             ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
             ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
             SELECT 
             ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = @MNT_ATTESTE_HT, 
             ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
             ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
             @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
            
           END
          /* separation ADH / OF : ne devrait plus rester beaucoup de cas REGLTPRO*/ 
           IF @COD_TYPE_EVENEMENT = 'REGLT_AD' -- Validation du reglement ADH d'un contrat professionnalisation
           BEGIN
             SELECT  @ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO, @ID_PERIODE = MODULE_PRO.ID_PERIODE,  
               @MNT_VERSE_HT_ADH = SESSION_PRO.mnt_verse_ht_adh,
               @ID_ENGAGEMENT_PRO = MODULE_PRO.ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION = MODULE_PRO.ID_TYPE_FORMATION, 
               @ID_DISPOSITIF = TYPE_FORMATION.ID_DISPOSITIF, @ID_REGLEMENT_PRO_ADH = SESSION_PRO.ID_REGLEMENT_PRO_ADH
             FROM SESSION_PRO
               INNER JOIN MODULE_PRO  ON MODULE_PRO.ID_MODULE_PRO = SESSION_PRO.ID_MODULE_PRO 
               INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
             WHERE   SESSION_PRO.ID_SESSION_PRO = @ID_SESSION_PRO
         
             -- Determination de l'enveloppe a associer au module :
             SELECT @ID_ENVELOPPE = ID_ENVELOPPE
             FROM ENVELOPPE
               INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
             WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
             AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
             AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
             AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
         
             -- Recherche de la date de reglement
             SELECT @DAT_MVT = DAT_VALID_REGLEMENT
             FROM REGLEMENT_PRO
             WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO_ADH 
                
             -- Recherche du mouvement budgetaire d'engagement associe au module a regler
             SET @MNT_MVT_BUDGETAIRE = 0
             SELECT @MNT_MVT_BUDGETAIRE = ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)
             FROM MVT_BUDGETAIRE
             WHERE ID_MODULE_PRO = @ID_MODULE_PRO
             AND  ID_ENVELOPPE = @ID_ENVELOPPE
             AND  P_E_R   = 'E'
             
          -- mvt_budgetaire OF+ADH?!   
             IF @MNT_MVT_BUDGETAIRE > 0
             BEGIN
              -- Diminution de l'engagement a hauteur du montant du module regle dans la limite de l'engagement initial
              IF @MNT_VERSE_HT_ADH  < @MNT_MVT_BUDGETAIRE
              BEGIN
               SET @MNT_MVT_BUDGETAIRE = @MNT_VERSE_HT_ADH 
              END
              
              SELECT @P_E_R = 'E'     -- Pr‚vision
              SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation Pr‚vision
              SELECT @LIBL_MVT_BUDGETAIRE = 'Annul. engag. suite regl module pro ADH ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
               INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
              ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
              ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, 
              MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
              ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
              @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END     
         
             -- On regle les montants attestes des differentes sessions reglees
             SELECT @ID_TYPE_MOUVEMENT = 22 --Mouvement de Reglement
             SELECT @P_E_R = 'R'     -- Reglement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Reglement Module PRO ADH ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
             INSERT INTO MVT_BUDGETAIRE 
             ( 
             ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
             ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
             ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
             ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
             SELECT 
             ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, 
             MNT_MVT_BUDGETAIRE = @MNT_VERSE_HT_ADH, 
             ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
             ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
             @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
            
           END
          -- OF
           IF @COD_TYPE_EVENEMENT = 'REGLT_OF'   -- Validation du reglement d'un contrat professionnalisation
           BEGIN
             SELECT  @ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO, @ID_PERIODE = MODULE_PRO.ID_PERIODE,  
               @MNT_VERSE_HT_OF = SESSION_PRO.MNT_verse_HT_OF, 
               @ID_ENGAGEMENT_PRO = MODULE_PRO.ID_ENGAGEMENT_PRO, @ID_TYPE_FORMATION = MODULE_PRO.ID_TYPE_FORMATION, 
               @ID_DISPOSITIF = TYPE_FORMATION.ID_DISPOSITIF, @ID_REGLEMENT_PRO_OF = SESSION_PRO.ID_REGLEMENT_PRO_OF
             FROM SESSION_PRO
               INNER JOIN MODULE_PRO  ON MODULE_PRO.ID_MODULE_PRO = SESSION_PRO.ID_MODULE_PRO 
               INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
             WHERE   SESSION_PRO.ID_SESSION_PRO = @ID_SESSION_PRO
         
             -- Determination de l'enveloppe a associer au module :
             SELECT @ID_ENVELOPPE = ID_ENVELOPPE
             FROM ENVELOPPE
               INNER JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE  = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
             WHERE TYPE_ENVELOPPE.ID_DISPOSITIF = @ID_DISPOSITIF
             AND  TYPE_ENVELOPPE.ID_AGENCE  = @ID_AGENCE
             AND  TYPE_ENVELOPPE.ID_BRANCHE  = @ID_BRANCHE
             AND  ENVELOPPE.ID_PERIODE   = @ID_PERIODE
         
             -- Recherche de la date de reglement
             SELECT @DAT_MVT = DAT_VALID_REGLEMENT
             FROM REGLEMENT_PRO
             WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO_OF
                
             -- Recherche du mouvement budgetaire d'engagement associe au module a regler
             SET @MNT_MVT_BUDGETAIRE = 0
             SELECT @MNT_MVT_BUDGETAIRE = ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)
             FROM MVT_BUDGETAIRE
             WHERE ID_MODULE_PRO = @ID_MODULE_PRO
             AND  ID_ENVELOPPE = @ID_ENVELOPPE
             AND  P_E_R   = 'E'
             
             
             IF @MNT_MVT_BUDGETAIRE > 0
             BEGIN
              -- Diminution de l'engagement a hauteur du montant du module regle dans la limite de l'engagement initial
         
              If @MNT_VERSE_HT_OF < @MNT_MVT_BUDGETAIRE
              BEGIN
               SET @MNT_MVT_BUDGETAIRE = @MNT_VERSE_HT_OF 
              END
              
              SELECT @P_E_R = 'E'     -- Pr‚vision
              SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation Pr‚vision
              SELECT @LIBL_MVT_BUDGETAIRE = 'Annul. engag. suite regl module pro OF ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
               INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
              ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
              ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R,
              MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE,
              ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
              ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
              @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END     
         
             -- On regle les montants attestes des differentes sessions reglees
             SELECT @ID_TYPE_MOUVEMENT = 22 --Mouvement de Reglement
             SELECT @P_E_R = 'R'     -- Reglement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Reglement Module PRO OF ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
             INSERT INTO MVT_BUDGETAIRE 
             ( 
             ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
             ID_PERIODE_FISC, ID_PERIODE_CPT, DAT_MVT_BUDGETAIRE,
             ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE, 
             ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, ID_SESSION_PRO, N_R, ID_ACTIVITE)
             SELECT 
             ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, 
             MNT_MVT_BUDGETAIRE =@MNT_VERSE_HT_OF,
             ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, DAT_MVT_BUDGETAIRE = @DAT_MVT,
             ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, 
             @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, ID_SESSION_PRO = @ID_SESSION_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
            END
         
          /* ********************************************************** 
          -- Cloture d'un contrat de pro
          -- TYPE_EVENEMENT = 'CLOT_PRO'
          ********************************************************** */
           IF  @COD_TYPE_EVENEMENT = 'CLOT_PRO'   -- Cloture d'un contrat de pro
           BEGIN
            
            -- Recherche des reliquats de previsionnel et d'engagement sur le contrat a cloturer
            DECLARE cu_contrat_a_cloturer  CURSOR FOR
            SELECT ID_ENVELOPPE, ID_MODULE_PRO, ID_DISPOSITIF, ID_PERIODE_FISC, P_E_R, ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)
            FROM MVT_BUDGETAIRE
            WHERE P_E_R != 'R'
            AND  ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
            GROUP BY ID_ENVELOPPE, ID_MODULE_PRO, ID_DISPOSITIF, ID_PERIODE_FISC, P_E_R
            HAVING ABS(ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)) > 0.01
            
            declare @BLN_REPRISE_ADHOC tinyint
            select @BLN_REPRISE_ADHOC= BLN_REPRISE_ADHOC 
            from CONTRAT_PRO  
            where ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
            OPEN cu_contrat_a_cloturer
            FETCH cu_contrat_a_cloturer INTO 
             @ID_ENVELOPPE, @ID_MODULE_PRO, @ID_DISPOSITIF, @ID_PERIODE, @P_E_R, @MNT_MVT_BUDGETAIRE
         
            WHILE (@@fetch_status <> -1)
            BEGIN
             
              if @BLN_REPRISE_ADHOC = 1
              set @P_E_R = 'E'
             IF @P_E_R = 'P'
             BEGIN
              SELECT @ID_TYPE_MOUVEMENT = 19 --Mouvement Annulation Pr‚vision
              SELECT @LIBL_MVT_BUDGETAIRE = 'Cloture Contrat PRO ' + CAST(@COD_CONTRAT_PRO AS VARCHAR)
             END
             IF @P_E_R = 'E'
             BEGIN
              SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation Engagement
              SELECT @LIBL_MVT_BUDGETAIRE = 'Cloture Contrat PRO ' + CAST(@COD_CONTRAT_PRO AS VARCHAR)
             END
         
             IF @ID_TYPE_MOUVEMENT IS NOT NULL
             BEGIN
              INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC, ID_PERIODE_CPT, 
              DAT_MVT_BUDGETAIRE,ID_ADHERENT, ID_ETABLISSEMENT, ID_GROUPE, ID_DISPOSITIF, 
              LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, ID_MODULE_PRO, N_R, ID_ACTIVITE)
              SELECT 
              ID_TYPE_MOUVEMENT = @ID_TYPE_MOUVEMENT, ID_EVENEMENT = @ID_EVENEMENT, P_E_R = @P_E_R, MNT_MVT_BUDGETAIRE = -@MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC = @ID_PERIODE, ID_PERIODE_CPT = @ID_PERIODE, 
              DAT_MVT_BUDGETAIRE = @DAT_CLOTURE, ID_ADHERENT = @ID_ADHERENT, ID_ETABLISSEMENT = @ID_ETABLISSEMENT, ID_GROUPE = @ID_GROUPE, ID_DISPOSITIF = @ID_DISPOSITIF, 
              LIBL_MVT_BUDGETAIRE = @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, ID_CONTRAT_PRO = @ID_CONTRAT_PRO, ID_MODULE_PRO = @ID_MODULE_PRO, N_R = 'N', ID_ACTIVITE = @ID_ACTIVITE
             END
         
             FETCH cu_contrat_a_cloturer INTO 
             @ID_ENVELOPPE, @ID_MODULE_PRO, @ID_DISPOSITIF, @ID_PERIODE, @P_E_R, @MNT_MVT_BUDGETAIRE
            END
         
         
            CLOSE cu_contrat_a_cloturer
            DEALLOCATE cu_contrat_a_cloturer
         
         
           END
         
          /* ********************************************************** 
          -- MBT le 12/03/2010 EVOL 12271
          -- Cloture d'un module pro
          -- TYPE_EVENEMENT = 'CLOMOPRO'
          ********************************************************** */
           IF  @COD_TYPE_EVENEMENT = 'CLOMOPRO'   -- Cloture d'un module pro
           BEGIN
            
            DECLARE @DAT_CLOTURE_MODULE DATETIME
         
            SELECT @DAT_CLOTURE_MODULE = DAT_CLOTURE FROM MODULE_PRO
            WHERE ID_MODULE_PRO = @ID_MODULE_PRO
         
            -- Recherche des reliquats de previsionnel et d'engagement sur le module … cl“turer
            DECLARE cu_module_a_cloturer  CURSOR FOR
            SELECT ID_ENVELOPPE, ID_MODULE_PRO, ID_DISPOSITIF, ID_PERIODE_FISC, P_E_R, ISNULL(SUM(MNT_MVT_BUDGETAIRE), 0)
            FROM MVT_BUDGETAIRE
            WHERE P_E_R != 'R'
            AND  ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
            -- 20101103 ajout ASD : restriction au module_pro
            AND  ID_MODULE_PRO = @ID_MODULE_PRO 
            GROUP BY ID_ENVELOPPE, ID_MODULE_PRO, ID_DISPOSITIF, ID_PERIODE_FISC, P_E_R
         
            OPEN cu_module_a_cloturer
            FETCH cu_module_a_cloturer INTO 
             @ID_ENVELOPPE, @ID_MODULE_PRO, @ID_DISPOSITIF, @ID_PERIODE, @P_E_R, @MNT_MVT_BUDGETAIRE
         
            WHILE (@@fetch_status <> -1)
            BEGIN
             
             
             SELECT @ID_TYPE_MOUVEMENT = 21 --Mouvement Annulation Engagement
             SELECT @LIBL_MVT_BUDGETAIRE = 'Cl“ture Module PRO ' + CAST(@COD_MODULE_PRO AS VARCHAR)
         
              INSERT INTO MVT_BUDGETAIRE 
              ( 
              ID_TYPE_MOUVEMENT, ID_EVENEMENT, P_E_R, MNT_MVT_BUDGETAIRE, 
              ID_PERIODE_FISC, DAT_MVT_BUDGETAIRE, ID_PERIODE_CPT, 
              ID_ADHERENT, ID_ETABLISSEMENT, ID_DISPOSITIF, 
              LIBL_MVT_BUDGETAIRE, ID_ENVELOPPE, ID_CONTRAT_PRO, 
              ID_MODULE_PRO, ID_SESSION_PRO, ID_GROUPE)
              VALUES
              (
              @ID_TYPE_MOUVEMENT, @ID_EVENEMENT, @P_E_R, -@MNT_MVT_BUDGETAIRE, 
              @ID_PERIODE, @DAT_CLOTURE_MODULE, @ID_PERIODE, 
              @ID_ADHERENT, @ID_ETABLISSEMENT, @ID_DISPOSITIF, 
              @LIBL_MVT_BUDGETAIRE, @ID_ENVELOPPE, @ID_CONTRAT_PRO, 
              @ID_MODULE_PRO, @ID_SESSION_PRO, @ID_GROUPE) 
         
             FETCH cu_module_a_cloturer INTO 
             @ID_ENVELOPPE, @ID_MODULE_PRO, @ID_DISPOSITIF, @ID_PERIODE, @P_E_R, @MNT_MVT_BUDGETAIRE
            END
            CLOSE cu_module_a_cloturer
            DEALLOCATE cu_module_a_cloturer
           END
           FETCH cu_evenement_contrat_pro INTO @ID_EVENEMENT, @ID_TYPE_EVENEMENT, @DAT_EVENEMENT, @ID_CONTRAT_PRO, @ID_MODULE_PRO, @ID_ENGAGEMENT_PRO, @ID_SESSION_PRO
          END
         
          CLOSE cu_evenement_contrat_pro
          DEALLOCATE cu_evenement_contrat_pro
         
         
          END
GO
 -- =============================================
         -- Author		:	SAFIYULLA
         -- Create date	:	03/02/2011
         -- Description	:	Selects the Motif Refus pour les Pieces de 
         --					(Adherents, Module, et Stagiaires)
         -- =============================================
         CREATE PROCEDURE [LEC_GRP_MOTIF_NON_CONFORM_MODULE_PEC]	
         	@ID_PIECE_PEC INT,
         	@ID_ARRIVEE_PIECE_PEC INT,
         	@ID_MODULE_PEC INT,
         	@ID_ADHERENT INT,
         	@ID_STAGIAIRE_PEC INT,	
         	@ID_SESSION_PEC INT
         
         AS
         BEGIN	
         
         SET @ID_ARRIVEE_PIECE_PEC = (CASE WHEN @ID_ARRIVEE_PIECE_PEC = -1 THEN NULL ELSE @ID_ARRIVEE_PIECE_PEC END)
         SET @ID_ADHERENT = (CASE WHEN @ID_ADHERENT = -1 THEN NULL ELSE @ID_ADHERENT END)
         SET @ID_MODULE_PEC = (CASE WHEN @ID_MODULE_PEC = -1 THEN NULL ELSE @ID_MODULE_PEC END)
         SET @ID_STAGIAIRE_PEC = (CASE WHEN @ID_STAGIAIRE_PEC = -1 THEN NULL ELSE @ID_STAGIAIRE_PEC END)
         SET @ID_SESSION_PEC = (CASE WHEN @ID_SESSION_PEC = -1 THEN NULL ELSE @ID_SESSION_PEC END)
         
         IF(@ID_PIECE_PEC IS NOT NULL)
         	BEGIN
         		SELECT	
         				(SELECT COUNT(*) FROM NR210
				WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
				AND ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE) AS SELECTION,
         				@ID_ARRIVEE_PIECE_PEC									AS ID_ARRIVEE_PIECE_PEC,				
         				MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE		AS ID,
         				MOTIF_NON_CONFORM_PIECE.COD_MOTIF_NON_CONFORM_PIECE		AS COD,
         				MOTIF_NON_CONFORM_PIECE.LIBL_MOTIF_NON_CONFORM_PIECE	AS LIBELLE,
         				MOTIF_PIECE.ID_PIECE_PEC,
         				@ID_ADHERENT											AS ID_ADHERENT,
         				@ID_STAGIAIRE_PEC										AS ID_STAGIAIRE_PEC,
         				ARRIVEE_PIECE_PEC.ID_MODULE_PEC,
         				ARRIVEE_PIECE_PEC.ID_SESSION_PEC				
         		FROM	MOTIF_NON_CONFORM_PIECE
         		INNER	JOIN	MOTIF_PIECE			ON	MOTIF_PIECE.ID_PIECE_PEC = @ID_PIECE_PEC
         		LEFT	JOIN	ARRIVEE_PIECE_PEC	ON	(ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC) AND
         												(ARRIVEE_PIECE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC) AND
         												(ARRIVEE_PIECE_PEC.ID_ADHERENT = @ID_ADHERENT) AND
         												(ARRIVEE_PIECE_PEC.ID_STAGIAIRE_PEC = @ID_STAGIAIRE_PEC) AND
         												(ARRIVEE_PIECE_PEC.ID_SESSION_PEC  = @ID_SESSION_PEC)
         											
         		WHERE	MOTIF_PIECE.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE
         	END
         	
         END
         
GO
 -- =============================================
         -- HBO - 221113 - M16379: LOT 1 - FICHIERS · GNRER SEPA
         -- =============================================
         CREATE PROCEDURE dbo.SEPA_DATA
         	@CAS_A_FAIRE	TINYINT
         AS
         BEGIN
         	DECLARE
         		@ID_ACTIVITE	INT = 0
         	
         	IF @CAS_A_FAIRE = 0 --'PCOL'
         	BEGIN
         	
         		-- Pr‚lŠvement Collecte
         		SELECT DISTINCT
         			'PRAC'					AS	OPERATION,
         			ID_PRELEVEMENT_COLLECTE	AS	NUM_VIR,
         			AP.NUM_IBAN				AS	DbtrAcctIBAN,
         			AP.NUM_BIC				AS	DbtrAgtBIC,
         			TS.NUM_IBAN_TRANSIT		AS	CdtrAcctIBAN,
         			TS.BIC_TRANSIT			AS	CdtrAgtBIC,
         			ID_PRELEVEMENT_COLLECTE	AS	ID,
         			A.ID_ACTIVITE			AS	ID_ACTIVITE,
         			NULL					AS	ID_SUBVENTION,
         			NULL					AS	ID_TRANSACTION,
         
         			A.NUM_IBAN_ACTIVITE		AS	IBAN_ACTIVITE,
         			NULL					AS	IBAN_SUBVENTION,
         			NULL					AS	IBAN_TRANSACTION,
         			TS.NUM_IBAN_TRANSIT		AS	IBAN_TRANSIT,
         			TS.NUM_IBAN_TRANSIT_DECAISSEMENT	AS	IBAN_TRANSIT_DECAISSEMENT,
         
         			A.BIC_ACTIVITE			AS	BIC_ACTIVITE,
         			NULL					AS	BIC_SUBVENTION,
         			NULL					AS	BIC_TRANSACTION,
         			TS.BIC_TRANSIT			AS	BIC_TRANSIT,
         			TS.BIC_TRANSIT_DECAISSEMENT	AS	BIC_TRANSIT_DECAISSEMENT,
         
         			MNT_PRELEVEMENT			AS	MNT,
         
         			P.FAF_NAME				AS	NOM_CREDITEUR,
         			'OPCA DEFI PCOL ' + ISNULL(CONVERT(VARCHAR(50),ID_PRELEVEMENT_COLLECTE),'')	AS EndToEndId,
         			NULL					AS	REF_FACT,
         			master.dbo.fn_cdc_hexstrtobin('0000')		AS	TIME_STAMP
         		FROM
         			PRELEVEMENT_COLLECTE					PC
         			LEFT  JOIN	ACTIVITE					A	ON	A.ID_ACTIVITE = PC.ID_ACTIVITE
         			INNER JOIN	AUTORISATION_PRELEVEMENT	AP	ON	AP.ID_AUTORISATION_PRELEVEMENT =  PC.ID_AUTORISATION_PRELEVEMENT
         			INNER JOIN	ETABLISSEMENT				E	ON	E.ID_ETABLISSEMENT = AP.ID_ETABLISSEMENT
         			INNER JOIN	ADHERENT					ADH	ON	ADH.ID_ADHERENT = E.ID_ADHERENT
         			CROSS JOIN	TRANSIT						TS,
         			PARAMETRES					P
         		WHERE
         			DAT_GENERATION_SEPA	IS NULL
         			AND MNT_PRELEVEMENT			<>	0
         			AND PC.ID_ACTIVITE IS NOT NULL
         		ORDER BY
         			NUM_VIR
         	END
         	ELSE IF @CAS_A_FAIRE = 1 --'VCOL'
         	BEGIN
         		-- Collecte Interne
         		SELECT DISTINCT
         			'OVIC'				AS OPERATION,
         			ID_VIREMENT_INTERNE_COLLECTE	AS	NUM_VIR,
         			CASE
         				WHEN	MNT_VIREMENT_INTERNE_COLLECTE > 0
         					THEN	TS.NUM_IBAN_TRANSIT
         				ELSE		A.NUM_IBAN_ACTIVITE
         			END					AS	DbtrAcctIBAN,
         			CASE
         				WHEN	MNT_VIREMENT_INTERNE_COLLECTE > 0
         					THEN	TS.BIC_TRANSIT
         				ELSE		A.BIC_ACTIVITE
         			END					AS	DbtrAgtBIC,
         			CASE
         				WHEN	MNT_VIREMENT_INTERNE_COLLECTE > 0
         					THEN	A.NUM_IBAN_ACTIVITE
         				ELSE		TS.NUM_IBAN_TRANSIT
         			END					AS	CdtrAcctIBAN,
         			CASE
         				WHEN	MNT_VIREMENT_INTERNE_COLLECTE > 0
         					THEN	A.BIC_ACTIVITE
         				ELSE		TS.BIC_TRANSIT
         			END					AS	CdtrAgtBIC,
         			ID_VIREMENT_INTERNE_COLLECTE	AS	ID,
         			A.ID_ACTIVITE		AS	ID_ACTIVITE,
         			NULL				AS	ID_SUBVENTION,
         			NULL				AS	ID_TRANSACTION,
         
         			A.NUM_IBAN_ACTIVITE	AS	IBAN_ACTIVITE,
         			NULL				AS	IBAN_SUBVENTION,
         			NULL				AS	IBAN_TRANSACTION,
         			TS.NUM_IBAN_TRANSIT	AS	IBAN_TRANSIT,
         			TS.NUM_IBAN_TRANSIT_DECAISSEMENT	AS	IBAN_TRANSIT_DECAISSEMENT,
         
         			A.BIC_ACTIVITE		AS	BIC_ACTIVITE,
         			NULL				AS	BIC_SUBVENTION,
         			NULL				AS	BIC_TRANSACTION,
         			TS.BIC_TRANSIT		AS	BIC_TRANSIT,
         			TS.BIC_TRANSIT_DECAISSEMENT	AS	BIC_TRANSIT_DECAISSEMENT,
         
         			MNT_VIREMENT_INTERNE_COLLECTE	AS	MNT,
         
         			P.FAF_NAME						AS	NOM_CREDITEUR,
         			'OPCA DEFI VIRT COL ' + ISNULL(CONVERT(VARCHAR(50),ID_VIREMENT_INTERNE_COLLECTE),'')	AS EndToEndId,
         			NULL							AS	REF_FACT,
         			VIC.TIME_STAMP					AS	TIME_STAMP
         		FROM
         			VIREMENT_INTERNE_COLLECTE	VIC
         			LEFT  JOIN	ACTIVITE		A	ON	A.ID_ACTIVITE = VIC.ID_ACTIVITE
         			CROSS JOIN	TRANSIT			TS,
         			PARAMETRES					P
         		WHERE
         			DAT_GENERATION_SEPA	IS NULL
         			AND MNT_VIREMENT_INTERNE_COLLECTE			<>	0
         			AND 
         			(
         				MNT_VIREMENT_INTERNE_COLLECTE<0
         				AND VIC.ID_ACTIVITE IS NOT NULL
         				
         				OR MNT_VIREMENT_INTERNE_COLLECTE>0
         			)
         	END
         	ELSE IF @CAS_A_FAIRE = 2 --'PEC'
         	BEGIN
         		-- PEC Externe
         		SELECT DISTINCT
         			'REGL'				AS OPERATION,
         			NUM_VIREMENT		AS	NUM_VIR,
         			TS.NUM_IBAN_TRANSIT_DECAISSEMENT	AS	DbtrAcctIBAN,
         			TS.BIC_TRANSIT_DECAISSEMENT		AS	DbtrAgtBIC,
         			ID_REGLEMENT		AS	ID,
         			NULL				AS	ID_ACTIVITE,
         			NULL				AS	ID_SUBVENTION,
         			T.ID_TRANSACTION	AS	ID_TRANSACTION,
         
         			NULL				AS	IBAN_ACTIVITE,
         			NULL				AS	IBAN_SUBVENTION,
         			T.NUM_IBAN			AS	IBAN_TRANSACTION,
         			TS.NUM_IBAN_TRANSIT	AS	IBAN_TRANSIT,
         			TS.NUM_IBAN_TRANSIT_DECAISSEMENT	AS	IBAN_TRANSIT_DECAISSEMENT,
         
         			NULL				AS	BIC_ACTIVITE,
         			NULL				AS	BIC_SUBVENTION,
         		    T.BIC				AS	BIC_TRANSACTION,
         			TS.BIC_TRANSIT		AS	BIC_TRANSIT,
         			TS.BIC_TRANSIT_DECAISSEMENT	AS	BIC_TRANSIT_DECAISSEMENT,
         
         			MNT_REGLE_TTC		AS	MNT,
         
         			CASE
         				WHEN	ID_ETABLISSEMENT_BENEF IS NOT NULL
         					THEN	isnull(ADH.LIB_RAISON_SOCIALE, '')
         				WHEN	ID_ETABLISSEMENT_OF_BENEF IS NOT NULL
         					THEN	isnull(OFO.LIB_RAISON_SOCIALE, '')
         				WHEN	ID_TIERS_BENEF IS NOT NULL
         					THEN	isnull(TR.LIB_NOM, '')
         				ELSE		''
         			END					AS	NOM_CREDITEUR,
         			'OPCA DEFI VIRT PEC ' + ISNULL(CONVERT(VARCHAR(50),R.NUM_VIREMENT),'')	AS EndToEndId,
         			'Vos ref fact ' + (SELECT
         				LEFT(
         					REPLACE(
         						REPLACE(
         							REPLACE(
         										(
         											SELECT
         												REPLACE(F.NUM_FACTURE,' ','') AS NF
         											FROM
         												FACTURE F
         												INNER JOIN POSTE_COUT_REGLE PCR
         													ON PCR.ID_FACTURE = F.ID_FACTURE
         													AND R.ID_REGLEMENT = PCR.ID_REGLEMENT
         											GROUP BY
         												F.NUM_FACTURE
         											FOR XML PATH('')
         										),
         									'</NF><NF>','|'),
         								'<NF>',''),
         							'</NF>',''),
         					127)
         			)									AS	REF_FACT,
         			R.TIME_STAMP					AS	TIME_STAMP
         		FROM
         			REGLEMENT						R
         			INNER JOIN	[TRANSACTION]		T		ON	T.ID_TRANSACTION			= R.ID_TRANSACTION
         			LEFT  JOIN	ETABLISSEMENT_OF	E_OF	ON	E_OF.ID_ETABLISSEMENT_OF	= T.ID_ETABLISSEMENT_OF_BENEF
         			LEFT  JOIN	ORGANISME_FORMATION	OFO		ON	OFO.ID_OF			= E_OF.ID_OF
         			LEFT  JOIN	ETABLISSEMENT		E		ON	E.ID_ETABLISSEMENT		= T.ID_ETABLISSEMENT_BENEF
         			LEFT  JOIN	ADHERENT			ADH		ON	ADH.ID_ADHERENT = E.ID_ADHERENT
         			LEFT  JOIN	TIERS				TR		ON	TR.ID_TIERS = T.ID_TIERS_BENEF
         			CROSS JOIN	TRANSIT				TS
         		WHERE
         			DAT_GENERATION_SEPA	IS NULL
         			AND MNT_REGLE_TTC			<> 0
         			AND R.BLN_ACTIF		= 1
         			AND DAT_VALID_REGLEMENT		IS NOT NULL
         		
         		UNION ALL
         		
         		-- PEC Interne
         		SELECT DISTINCT
         			'OVIP'				AS OPERATION,
         			ID_VIREMENT_INTERNE_PEC	AS	NUM_VIR,
         			CASE
         				WHEN	VIP.ID_ACTIVITE IS NOT NULL
         					THEN	A.NUM_IBAN_ACTIVITE
         				WHEN	VIP.ID_SUBVENTION IS NOT NULL
         					THEN	S.NUM_IBAN_SUBVENTION
         				ELSE		''
         			END					AS	DbtrAcctIBAN,
         			CASE
         				WHEN	VIP.ID_ACTIVITE IS NOT NULL
         					THEN	A.BIC_ACTIVITE
         				WHEN	VIP.ID_SUBVENTION IS NOT NULL
         					THEN	S.BIC_SUBVENTION
         				ELSE		''
         			END					AS	DbtrAgtBIC,
         			ID_VIREMENT_INTERNE_PEC	AS	ID,
         			A.ID_ACTIVITE		AS	ID_ACTIVITE,
         			S.ID_SUBVENTION		AS	ID_SUBVENTION,
         			NULL				AS	ID_TRANSACTION,
         
         			A.NUM_IBAN_ACTIVITE	AS	IBAN_ACTIVITE,
         			S.NUM_IBAN_SUBVENTION	AS	IBAN_SUBVENTION,
         			NULL				AS	IBAN_TRANSACTION,
         			TS.NUM_IBAN_TRANSIT	AS	IBAN_TRANSIT,
         			TS.NUM_IBAN_TRANSIT_DECAISSEMENT	AS	IBAN_TRANSIT_DECAISSEMENT,
         
         			A.BIC_ACTIVITE		AS	BIC_ACTIVITE,
         			S.BIC_SUBVENTION	AS	BIC_SUBVENTION,
         			NULL				AS	BIC_TRANSACTION,
         			TS.BIC_TRANSIT		AS	BIC_TRANSIT,
         			TS.BIC_TRANSIT_DECAISSEMENT	AS	BIC_TRANSIT_DECAISSEMENT,
         
         			MNT_VIREMENT_INTERNE_PEC	AS	MNT,
         
         			P.FAF_NAME				AS	NOM_CREDITEUR,
         			'OPCA DEFI OVI PEC ' + ISNULL(CONVERT(VARCHAR(50),ID_VIREMENT_INTERNE_PEC),'')	AS EndToEndId,
         			NULL					AS	REF_FACT,
         			VIP.TIME_STAMP					AS	TIME_STAMP
         		FROM
         			VIREMENT_INTERNE_PEC	VIP
         			LEFT  JOIN	ACTIVITE	A	ON A.ID_ACTIVITE		= VIP.ID_ACTIVITE
         			LEFT  JOIN	SUBVENTION	S	ON S.ID_SUBVENTION	= VIP.ID_SUBVENTION
         			CROSS JOIN	TRANSIT		TS,
         			PARAMETRES				P
         		WHERE
         			DAT_GENERATION_SEPA	IS NULL
         			AND MNT_VIREMENT_INTERNE_PEC <>	0
         			AND
         			(
         				VIP.ID_ACTIVITE IS NOT NULL
         				OR VIP.ID_SUBVENTION IS NOT NULL
         			)
         		ORDER BY
         			NUM_VIR
         	END
         	ELSE IF @CAS_A_FAIRE = 3 --'PRO'
         	BEGIN
         		SET @ID_ACTIVITE = 3
         
         		SELECT DISTINCT
         			'REGP'				AS	OPERATION,
         			NUM_VIREMENT		AS	NUM_VIR,
         			A.NUM_IBAN_ACTIVITE	AS	DbtrAcctIBAN,
         			A.BIC_ACTIVITE		AS	DbtrAgtBIC,
         			T.NUM_IBAN			AS	CdtrAcctIBAN,
         			T.BIC				AS	CdtrAgtBIC,
         			
         			ID_REGLEMENT_PRO	AS	ID,
         			A.ID_ACTIVITE		AS	ID_ACTIVITE,
         			NULL				AS	ID_SUBVENTION,
         			T.ID_TRANSACTION	AS	ID_TRANSACTION,
         
         			A.NUM_IBAN_ACTIVITE	AS	IBAN_ACTIVITE,
         			NULL				AS	IBAN_SUBVENTION,
         			T.NUM_IBAN			AS	IBAN_TRANSACTION,
         			NULL				AS	IBAN_TRANSIT,
         			NULL				AS	IBAN_TRANSIT_DECAISSEMENT,
         
         			A.BIC_ACTIVITE		AS	BIC_ACTIVITE,
         			NULL				AS	BIC_SUBVENTION,
         			T.BIC				AS	BIC_TRANSACTION,
         			NULL				AS	BIC_TRANSIT,
         			NULL				AS	BIC_TRANSIT_DECAISSEMENT,
         
         			MNT_REGLE_TTC		AS	MNT,
         
         			CASE
         				WHEN	ID_ETABLISSEMENT_OF_BENEF IS NOT NULL
         					THEN	isnull(OFO.LIB_RAISON_SOCIALE, '')
         				WHEN	ID_ETABLISSEMENT_BENEF IS NOT NULL
         					THEN	isnull(ADH.LIB_RAISON_SOCIALE, '')
         				WHEN	ID_TIERS_BENEF IS NOT NULL
         					THEN	isnull(TR.LIB_NOM, '')
         				ELSE		''
         			END					AS	NOM_CREDITEUR,
         			'OPCA DEFI VIRT PRO ' + ISNULL(CONVERT(VARCHAR(50),RP.NUM_VIREMENT),'')		AS EndToEndId,
         			'Vos ref fact ' + (SELECT
         				LEFT(
         					REPLACE(
         						REPLACE(
         							REPLACE(
         										(
         											SELECT
         												REPLACE(F.NUM_FACTURE,' ','') AS NF
         											FROM
         												FACTURE F
         												INNER JOIN SESSION_PRO SP
         													ON
         													(
         														SP.ID_FACTURE_ADHERENT = F.ID_FACTURE
         														OR SP.ID_FACTURE_OF = F.ID_FACTURE
         													)
         													AND
         													(
         														SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO
         														OR SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO
         													)
         											GROUP BY
         												F.NUM_FACTURE
         											FOR XML PATH('')
         										),
         									'</NF><NF>','|'),
         								'<NF>',''),
         							'</NF>',''),
         					127)
         			)								AS	REF_FACT,
         			RP.TIME_STAMP					AS	TIME_STAMP
         		FROM
         			REGLEMENT_PRO					RP
         			INNER JOIN	[TRANSACTION]		T		ON T.ID_TRANSACTION = RP.ID_TRANSACTION
         			LEFT  JOIN	ETABLISSEMENT_OF	E_OF	ON E_OF.ID_ETABLISSEMENT_OF = T.ID_ETABLISSEMENT_OF_BENEF
         			LEFT  JOIN	ORGANISME_FORMATION	OFO		ON OFO.ID_OF = E_OF.ID_OF
         			LEFT  JOIN	ETABLISSEMENT		E		ON E.ID_ETABLISSEMENT = T.ID_ETABLISSEMENT_BENEF
         			LEFT  JOIN	ADHERENT			ADH		ON ADH.ID_ADHERENT = E.ID_ADHERENT
         			LEFT  JOIN	TIERS				TR		ON TR.ID_TIERS = T.ID_TIERS_BENEF
         			CROSS JOIN	ACTIVITE			A
         		WHERE
         			DAT_GENERATION_SEPA IS NULL
         			AND MNT_REGLE_TTC <> 0
         			AND RP.BLN_ACTIF = 1
         			AND DAT_VALID_REGLEMENT IS NOT NULL
         			AND A.ID_ACTIVITE = @ID_ACTIVITE
         		ORDER BY
         			NUM_VIR
         	END	
         END
GO
 -- =============================================
         -- Author		:	SAFIYULLA
         -- Create date	:	03/02/2011
         -- Description	:	Updating Motif Refus pour les Pieces de 
         --					(Adherents, Module, et Stagiaires)
         -- =============================================
         -- LDE 13/05/2013 15026: DNE - Relance instruction propos‚e plusieurs fois
         -- =============================================
         -- OPA 24/05/2013 15232: 15232: UPD_MOTIF_NON_CONFORME... : doublonnage de code
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_MOTIF_NON_CONFORM_MODULE_PEC]	
         	@ID_PIECE_PEC	int,
         	@ID_ADHERENT	int,
         	@ID_MODULE_PEC	int,
         	@ID_MOTIF		int,
         	@BLN_ACTIF		int,
         	@ID_SESSION_PEC	int
         AS  
         
         BEGIN
         	IF @ID_ADHERENT = -1
         	BEGIN
         		SET @ID_ADHERENT = NULL
         	END
         
         	DECLARE @ID_ARRIVEE_PIECE_PEC INT
         	DECLARE @DAT_ARRIVEE DATETIME
         	DECLARE @NUMREG INT
         
         	SELECT 
         		@ID_ARRIVEE_PIECE_PEC	= ID_ARRIVEE_PIECE_PEC, 
         		@DAT_ARRIVEE			= DAT_ARRIVEE_PIECE_PEC
         	FROM ARRIVEE_PIECE_PEC
         	WHERE 
         		ID_PIECE_PEC	= @ID_PIECE_PEC AND
         		ID_MODULE_PEC	= @ID_MODULE_PEC AND
         		(
         			(@ID_SESSION_PEC is null		AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC is null) OR 
         			(@ID_SESSION_PEC is not null	AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)
         		)								AND 
         		(ID_ADHERENT	= @ID_ADHERENT OR @ID_ADHERENT IS NULL)
         	
         	IF @BLN_ACTIF IS NULL
         	BEGIN
         		SET @BLN_ACTIF = 0
         	END
         
         	SELECT @NUMREG = COUNT(*) 
         	FROM NR210
         	WHERE 
         		ID_MOTIF_NON_CONFORM_PIECE	= @ID_MOTIF AND 
         		ID_ARRIVEE_PIECE_PEC		= @ID_ARRIVEE_PIECE_PEC
         
         	IF @NUMREG = 0
         	BEGIN
         		IF (@BLN_ACTIF = 1) AND (@ID_ARRIVEE_PIECE_PEC IS NOT NULL)
         		BEGIN			
         			INSERT INTO NR210 
         				(ID_MOTIF_NON_CONFORM_PIECE, ID_ARRIVEE_PIECE_PEC)
         			VALUES 
         				(@ID_MOTIF, @ID_ARRIVEE_PIECE_PEC)
         
         			-- LDE 13/05/2013 15026
         			UPDATE ARRIVEE_PIECE_PEC 
         				SET DAT_RELANCE_ENGAGE_1 = NULL, DAT_RELANCE_ENGAGE_2 = NULL, DAT_RELANCE_ENGAGE_3 = NULL
         				WHERE ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC
         			-- /LDE 13/05/2013 15026
         		END		
         	END
         	ELSE
         	BEGIN
         		IF @BLN_ACTIF = 0
         		BEGIN
         			DELETE FROM NR210 
         			WHERE 
         				ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC AND 
         				ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         		END
         		
         		IF (@DAT_ARRIVEE IS NULL)
         		BEGIN
         			DELETE FROM NR210 
         			WHERE 
         				ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC AND 
         				ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         		END
         	END	
         END
GO
 --=========================================
         -- CREATED BY EOU 13550 24/07/2012
         --=========================================
         -- HBO - 141113 - M16371: Lot 1 - Modification structure de donn‚es / proc‚dures stock‚es
         -- =============================================
         CREATE PROCEDURE INS_PRELEVEMENT_COLLECTE
         	@ID_VERSEMENT INT,
         	@DAT_GENERATION_SEPA DATETIME,
         	@ID_ACTIVITE INT,
         	@MNT_PRELEVEMENT DECIMAL(9,2),
         	@ID_AUTORISATION_PRELEVEMENT INT,
         	@REFERENCE_EXTRANET VARCHAR(20) 
         AS
         	BEGIN
         		INSERT INTO PRELEVEMENT_COLLECTE
                 (  
         			ID_VERSEMENT  ,
         			DAT_GENERATION_SEPA  ,
         			ID_ACTIVITE  ,
         			MNT_PRELEVEMENT  ,
         			ID_AUTORISATION_PRELEVEMENT  ,
         			REFERENCE_EXTRANET
         		)
         		 VALUES
         		( 
         			@ID_VERSEMENT  ,
         			@DAT_GENERATION_SEPA  ,
         			@ID_ACTIVITE  ,
         			@MNT_PRELEVEMENT  ,
         			@ID_AUTORISATION_PRELEVEMENT  ,
         			@REFERENCE_EXTRANET  
         		)
         
         		RETURN @@IDENTITY
         	END
GO

         
CREATE PROCEDURE [dbo].[UPD_MOTIF_NON_IMPUTABLE]  
	@ID_MODULE int,
         	@ID_MOTIF int,
         	@BLN_SELECTION int
         AS  
         
         	DECLARE @NUMREG INT
         
         	SELECT @NUMREG = COUNT(*) FROM NR204
         	WHERE ID_MOTIF_NON_IMPUTABILITE = @ID_MOTIF
         	AND ID_MODULE_PEC = @ID_MODULE	
         
         	IF (@BLN_SELECTION = 0 OR @BLN_SELECTION IS NULL)
         	BEGIN
         		IF (@NUMREG > 0)
         		BEGIN 
         			DELETE FROM NR204 WHERE ID_MOTIF_NON_IMPUTABILITE = @ID_MOTIF
         			AND ID_MODULE_PEC = @ID_MODULE
         		END
         	END
         	ELSE
         	BEGIN
         		IF (@NUMREG = 0)
         		BEGIN
         			INSERT INTO NR204 (ID_MOTIF_NON_IMPUTABILITE, ID_MODULE_PEC)
         			VALUES (@ID_MOTIF, @ID_MODULE)
         		END
         	END
         
GO
CREATE PROCEDURE [dbo].[INS_EVENEMENT_PEC]
	@LIBL_EVENEMENT VARCHAR(50),  
	@DAT_EVENEMENT DATETIME,
	@ID_TYPE_EVENEMENT INT,
	@ID_NEW INT
	
AS

DECLARE @ID_EVENEMENT INTEGER


IF (@ID_TYPE_EVENEMENT = 2)
BEGIN
 -- DOTATION
 
 INSERT INTO EVENEMENT 
	(
		 LIBL_EVENEMENT,
		 DAT_EVENEMENT,
		 ID_TYPE_EVENEMENT,
		 ID_DOTATION
	 )
	 VALUES
	 (
		@LIBL_EVENEMENT,
		@DAT_EVENEMENT,
		@ID_TYPE_EVENEMENT,
		@ID_NEW
	 )
	 
	 SELECT  @ID_EVENEMENT = @@IDENTITY
	 
 END

IF (@ID_TYPE_EVENEMENT = 3)
BEGIN
 -- VIREMENTS
 
 INSERT INTO EVENEMENT 
	(
		 LIBL_EVENEMENT,
		 DAT_EVENEMENT,
		 ID_TYPE_EVENEMENT,
		 ID_VIREMENT_ENVELOPPE
	 )
	 VALUES
	 (
		@LIBL_EVENEMENT,
		@DAT_EVENEMENT,
		@ID_TYPE_EVENEMENT,
		@ID_NEW
	 )
	 
	 SELECT  @ID_EVENEMENT = @@IDENTITY
	 
 END


IF (@ID_TYPE_EVENEMENT = 4)
BEGIN
 -- TRANSFERTS
 
 INSERT INTO EVENEMENT 
	(
		 LIBL_EVENEMENT,
		 DAT_EVENEMENT,
		 ID_TYPE_EVENEMENT,
		 ID_TRANSFERT
	 )
	 VALUES
	 (
		@LIBL_EVENEMENT,
		@DAT_EVENEMENT,
		@ID_TYPE_EVENEMENT,
		@ID_NEW
	 )
	 	 
	 SELECT  @ID_EVENEMENT = @@IDENTITY
	 
 END



RETURN @ID_EVENEMENT
GO
