         -- =================================================================================
         -- Author:		DSZ
         -- Date modification: 13/03/2012
         -- Description:	Augmentation de la taille du parametre @COMMENTAIRE 13144
         -- =================================================================================
         CREATE PROCEDURE [dbo].[INS_COMMENTAIRES] 
         	@TYPE_OBJET int,	
         	@ID_OBJET int,
         	@COMMENTAIRE varchar(7600) , --EOU 13144
         	@ID_UTILISATEUR int
         AS
         BEGIN
         	SET NOCOUNT ON;
         
         	INSERT INTO COMMENTAIRES
                    ([TYPE_OBJET]
                    ,[ID_OBJET]
                    ,[DATE]
                    ,[COMMENTAIRE]
                    ,[ID_UTILISATEUR])
              VALUES
                    (@TYPE_OBJET
                    ,@ID_OBJET
                    ,GetDate()
                    ,@COMMENTAIRE
                    ,@ID_UTILISATEUR)
         END
