         -- =======================================================================================================================================
         -- Author:		DSZ
         -- Create date: 14/08/2012
         -- Description:	13716 : xml pour la prefacture
         -- =======================================================================================================================================
         -- DSZ 14246 06/11/2012
         -- ajout distinction de salari‚s par id_stagiaire (nom prenom NIR pas suffisant)
         -- limiter les salari‚s dans l'allocation formation aux salari‚s de l'adherent de l'‚tablissement
         -- =======================================================================================================================================
         -- DSZ 15110 13/05/2013
         -- lignes d'allocation formation aparaissent uniquement si un sous-type de co–t allocation formation est pr‚vu dans le module.
         -- =======================================================================================================================================
         -- DSZ 15212 14/05/2013
         -- pour le bloc Allocation formation: ne pas alimenter les heures d'allocation de formation ni la colonne montant. On les laisse vides.
         -- =======================================================================================================================================
         -- ASD 15229 21/05/2013
         -- Ajout de qq critŠres type BLN_ACTIF
         -- =======================================================================================================================================
         -- LDE/OPA 23/05/2014 : #213 En tant qu'utilisateur OPTIFORM, 
         -- lorsque j'‚dite un courrier (PEC, PRO) … destination d'un Adh‚rent ou d'un OF, je veux que, 
         -- l'adresse … afficher dans la zone "correspondance" soit l'adresse TSA propre … ce type de courrier 
         -- si le mode "TSA" s'applique sinon qu'elle soit l'adresse actuelle
         -- =======================================================================================================================================
         
         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_PREFACTURE] 
         	@ID_ETABLISSEMENT INT, --on prendra tous les etablissements de l'adh‚rent, id_etab sert uniquement … r‚cuperer l'adresse
         	@ID_BENEFICIAIRE INT,
         	@TYPE_BENEFICIAIRE INT,
         	@ID_ADRESSE INT,
         	@ID_CONTACT INT,
         	@ID_MODULE_PEC INT,
         	@_COD_FACTURE VARCHAR(50)
         AS
         
         BEGIN
         
         	DECLARE	@ID_UTILISATEUR INT  --createur de la prefacture
         	DECLARE @ID_FACTURE	VARCHAR(50)
         
         	SELECT 
         		@ID_FACTURE = ID_FACTURE,
         		@ID_UTILISATEUR = ID_UTILISATEUR
         	FROM FACTURE 
         	WHERE COD_FACTURE = @_COD_FACTURE
         	AND FACTURE.BLN_ACTIF=1
         
         	
         	--identifier les sessions du module pour cette prefacture
         	SELECT DISTINCT
         		SESSION_PEC.DAT_DEBUT, 
         		SESSION_PEC.DAT_FIN, 
         		SESSION_PEC.ID_SESSION_PEC
         	INTO #SESSIONS
         	FROM POSTE_COUT_REGLE
         	INNER JOIN SESSION_PEC ON (POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         								AND SESSION_PEC.ID_MODULE_PEC = @ID_MODULE_PEC) 
         	WHERE 
         		POSTE_COUT_REGLE.ID_FACTURE = @ID_FACTURE
         		AND POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = 5
         		AND POSTE_COUT_REGLE.BLN_ACTIF=1
         		AND SESSION_PEC.BLN_ACTIF=1
         	 
         
         	-- Modification de la session pec pour indiquer que la lettre de remboursement de salaire est ‚dit‚e
         	--Nota ASD : ne devrait intervenir que lorsque la pr‚facture est r‚ellement envoy‚e
         	UPDATE
         		SESSION_PEC
         	SET
         		DAT_LETTRE_REMBOURSEMENT_SALAIRE = CONVERT(DATETIME, '31/12/9999', 103)
         	FROM SESSION_PEC
         	INNER JOIN #SESSIONS ON (#SESSIONS.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC)
         	
         	;
         	--remboursement des salaires
         	--pfus
         	
         	WITH SALAIRES
         	AS 
         	(
         		SELECT 
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US + MNT_PLAN_FINANCEMENT_US_TVA) AS TOTAL_SALAIRES  ,
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC, 
         			STAGIAIRE_PEC.ID_INDIVIDU,
         			SUBSTRING(ETABLISSEMENT.NUM_SIRET,10,6) AS NIC
         		FROM #SESSIONS
         		INNER JOIN POSTE_COUT_REGLE ON (POSTE_COUT_REGLE.ID_FACTURE = @ID_FACTURE
         										AND POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = 5 
         										AND POSTE_COUT_REGLE.ID_SESSION_PEC = #SESSIONS.ID_SESSION_PEC --inutile car la jointure sur la facture est suffisant, mais laiss‚ pour coh‚rence
         										AND BLN_ACTIF=1)
         		INNER JOIN STAGIAIRE_PEC ON (STAGIAIRE_PEC.ID_SESSION_PEC = #SESSIONS.ID_SESSION_PEC
         									AND STAGIAIRE_PEC.ID_ETABLISSEMENT IN (--tous les ‚tablissements de l'adh‚rent de la pr‚facture
         																			SELECT ID_ETABLISSEMENT
         																			FROM POSTE_COUT_REGLE 
         																			WHERE POSTE_COUT_REGLE.ID_FACTURE = @ID_FACTURE))
         		INNER JOIN UNITE_STAGIAIRE ON (UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC )
         		INNER JOIN PLAN_FINANCEMENT_US ON (PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         										AND PLAN_FINANCEMENT_US.BLN_ACTIF = 1
         										AND PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE)
         		INNER JOIN ETABLISSEMENT ON (STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT)
         		GROUP BY
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC, 
         			 STAGIAIRE_PEC.ID_INDIVIDU,
         			 ETABLISSEMENT.NUM_SIRET 
         	)
         	--liste des stagiaires, toutes sessions confondues, et la somme des heures rem
         	SELECT 
         		SALAIRES.NIC,
         		CASE INDIVIDU.BLN_MASCULIN WHEN 1 THEN 'M' ELSE 'Mme' END AS CIVILITE,
         		INDIVIDU.PRENOM_INDIVIDU, 
         		INDIVIDU.NOM_INDIVIDU,
         		SUM(UNITE_STAGIAIRE.NB_HEURE_REM) AS NB_HEURES, --TOTAL DES HEURES REM 
         		SALAIRES.TOTAL_SALAIRES
         	INTO #REMBOURSEMENT_SALAIRES	
         	FROM SALAIRES
         	INNER JOIN INDIVIDU ON SALAIRES.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU 
         	INNER JOIN UNITE_STAGIAIRE ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = SALAIRES.ID_STAGIAIRE_PEC 
         	GROUP BY 
         		INDIVIDU.BLN_MASCULIN,
         		INDIVIDU.PRENOM_INDIVIDU,
         		INDIVIDU.NOM_INDIVIDU,
         		SALAIRES.TOTAL_SALAIRES,
         		SALAIRES.NIC,
         		SALAIRES.ID_STAGIAIRE_PEC
         	
         	-----------------------
         	--- Allocation formation : les heures HTT des stagiaires, pour toutes les sessions du module
         	--uniquement si existe un PCE d'allocation de formation
         	
         	SELECT 
         		CASE INDIVIDU.BLN_MASCULIN WHEN 1 THEN 'M' ELSE 'Mme' END AS CIVILITE,
         		INDIVIDU.PRENOM_INDIVIDU, 
         		INDIVIDU.NOM_INDIVIDU,
         		SUM(UNITE_STAGIAIRE.NB_HEURE_HTT) AS HEURES_HTT,
         		ROUND(STAGIAIRE_PEC.SALAIRE_HORAIRE_NET/2 ,2) AS TAUX_HORAIRE,
         		SUBSTRING(ETABLISSEMENT.NUM_SIRET,10,6) AS NIC 
         	INTO #REMBOURSEMENT_ALLOCATION
         	FROM UNITE_STAGIAIRE 
         		INNER JOIN STAGIAIRE_PEC ON ( STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC)
         		INNER JOIN INDIVIDU ON STAGIAIRE_PEC.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU 
         		INNER JOIN ETABLISSEMENT ON (STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT)
         	WHERE 
         		STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
         		AND STAGIAIRE_PEC.ID_SESSION_PEC IS NOT NULL
         		AND ETABLISSEMENT.ID_ADHERENT = (SELECT ID_ADHERENT FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT )
         		AND EXISTS (
         			SELECT 1 FROM POSTE_COUT_ENGAGE 
         				INNER JOIN SOUS_TYPE_COUT ON (SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT) 
         			WHERE ID_MODULE_PEC = @ID_MODULE_PEC
         			AND COD_SOUS_TYPE_COUT = 'AF'
         			AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL)
         	GROUP BY 
         		STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         		STAGIAIRE_PEC.SALAIRE_HORAIRE_NET,
         		INDIVIDU.BLN_MASCULIN,
         		INDIVIDU.PRENOM_INDIVIDU,
         		INDIVIDU.NOM_INDIVIDU,
         		ETABLISSEMENT.NUM_SIRET
         	HAVING SUM(UNITE_STAGIAIRE.NB_HEURE_HTT) > 0
         
         	--l'entete pour le tableau remboursement allocation formation
         	SELECT 
         		'Remboursement des allocations formation' AS TITRE_REMBOURSEMENT,
         		'Taux horaire allocation formation *' AS TITRE_TAUX,
         		'Nb heures' AS TITRE_NB_H,
         		'Total Allocation formation' AS TITRE_TOTAL,
         		'*Allocation formation = ‚gale … 50 % de sa r‚mun‚ration nette de r‚f‚rence' AS LEGENDE,
         		'Total des salaires' AS LIBL_TOTAL,
         		ROUND(SUM(HEURES_HTT*TAUX_HORAIRE),2) AS TOTAL_MNT,
         		'Total de l''allocation formation … reporter' AS DERNIERE_LIGNE_TOTAL,
         		'A' AS DERNIERE_LIGNE_A,
         		',' AS DERNIERE_LIGNE_VIRGULE
         	INTO #REMBOURS_ALLO_ENTETE
         	FROM #REMBOURSEMENT_ALLOCATION 
         	
         	IF NOT EXISTS (SELECT 1 FROM #REMBOURSEMENT_ALLOCATION)
         		DELETE FROM #REMBOURS_ALLO_ENTETE
         	
         	/*ENTETE */
         	SELECT	ETABLISSEMENT.ID_ETABLISSEMENT,
         			ADHERENT.ID_ADHERENT,
         			ADHERENT.COD_ADHERENT,
         			ETABLISSEMENT.NUM_SIRET,
         			ADRESSE.LIB_CP_CEDEX,
         			RTRIM(CASE WHEN PATINDEX('%CEDEX%', ADRESSE.LIB_VIL_CEDEX) <> 0 THEN LEFT(ADRESSE.LIB_VIL_CEDEX, PATINDEX('%CEDEX%', ADRESSE.LIB_VIL_CEDEX)-1) ELSE ADRESSE.LIB_VIL_CEDEX END) AS LIB_VIL_CEDEX, -- RETRAITEMENT DE LA VILLE AU CAS Oë DE LA FORME COMMUNE CEDEX 999
         			COALESCE(DBO.IS_EMPTY(ETABLISSEMENT.LIB_ENSEIGNE), ADHERENT.LIB_RAISON_SOCIALE) AS NOM_ADH,
         			CR.ID_UTILISATEUR	AS ID_UTIL,
         			CR.LIB_PNM			AS LIB_PRENOM_CHARGE_RELATION,
         			CR.LIB_NOM			AS LIB_NOM_CHARGE_RELATION,
         			CR.LIB_VILLE,
         			CR.EMAIL			AS EMAIL_CHARGE_RELATION,
         			MODULE_PEC.LIBL_MODULE_PEC,
         			DBO.GETSHORTDATE(MODULE_PEC.DAT_DEBUT) AS DAT_DEBUT,
         			DBO.GETSHORTDATE(MODULE_PEC.DAT_FIN) AS DAT_FIN,
         			ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         			MODULE_PEC.COD_MODULE_PEC
         	INTO	#TMP_GENERAL
         	FROM	ADHERENT
         	JOIN	ETABLISSEMENT 
         	ON		ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	AND		ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         	JOIN	ADRESSE
         	ON		ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         	JOIN	MODULE_PEC ON ID_MODULE_PEC = @ID_MODULE_PEC
         	JOIN	ACTION_PEC
         	ON		MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC 
         	JOIN	NR140
         	ON		ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         	AND		ACTION_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         	LEFT JOIN
         			UTILISATEUR CR -- charg‚ de relation ou responsable des actions collectives
         	ON		CASE WHEN (ACTION_PEC.CIBLE_ACTION = 1 OR ACTION_PEC.BLN_REPRISE_ADHOC = 1)
         				 THEN ETABLISSEMENT.ID_CHARGEE_RELATION
         				 ELSE ACTION_PEC.ID_CHARGEE_MISSION 
         			END = CR.ID_UTILISATEUR
         	LEFT JOIN ETABLISSEMENT_OF ON (ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF)
         	LEFT JOIN ORGANISME_FORMATION ON (ORGANISME_FORMATION.ID_OF	= ETABLISSEMENT_OF.ID_OF)
         				
         				;
         				
         	/*****  Creation du flux XML *******************************************************************************/
         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_PEC_PREFACTURE'
         	)
         	/************************************************************************************************************/
         
         
         	SELECT
         		-- R‚cup‚ration des informations sur le contact et le b‚n‚ficiaire
         		dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
         
         		/**********************************************************************************************/
         		/*****************	ENTETE DE LA LETTRE *******************************************************/
         		/**********************************************************************************************/
         		(
         			SELECT	              	
         				/******************* Recuperation des informations de l'entete ****************************/
         				ISNULL(COD_ADHERENT, '')				AS COD_ADHERENT,
         
         				-- R‚cup‚ration des informations sur l'‚metteur
         				dbo.GetXmlAdrUtilNomEmail(@ID_UTILISATEUR, (SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE), 1),		
         							
         				RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, -- retraitement de la ville au cas o— de la forme COMMUNE CEDEX 999
         				dbo.GetFullDate(GETDATE()) AS DATE,		
         					
         				COD_MODULE_PEC AS REFERENCE,		
         				(
         					SELECT top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         					FROM CIVILITE
         					FOR XML PATH('POLITESSE_HAUT'), TYPE
         				),
         				(
         					SELECT top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         					FROM CIVILITE
         					FOR XML PATH('POLITESSE_BAS'), TYPE
         				)
         			FROM #TMP_GENERAL AS ENTETE     
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         
         
         		/**********************************************************************************************/
         		/*****************	SIGNATURE DE LA LETTRE ****************************************************/
         		/**********************************************************************************************/
         		(
         			SELECT	ISNULL(UTILISATEUR.LIB_PNM , '') AS LIB_PNM_CONSEILLER,
         					ISNULL(UTILISATEUR.LIB_NOM, '') AS LIB_NOM_CONSEILLER
         			FROM	UTILISATEUR 
         			WHERE	ID_UTILISATEUR = @ID_UTILISATEUR 
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         
         		/**********************************************************************************************/
         		/*****************	SUPPLEMENT DE LA LETTRE = PREFACTURE ****************************************************/
         		/**********************************************************************************************/
         		dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS FACTURE_EMISE_PAR,
         		dbo.GetXmlAdrUtilAvecTel(@ID_UTILISATEUR, 0, 0)													AS DESTINATAIRE_FACTURE,		
         		COD_MODULE_PEC																				AS NUMERO_MODULE,
         		ISNULL(LETTRE.COD_ADHERENT, '')																AS CODE_ADH,
         		LETTRE.LIBL_MODULE_PEC																		AS INTITULE_MODULE,
         		LETTRE.DAT_DEBUT,				
         		LETTRE.DAT_FIN,
         		LETTRE.LIB_RAISON_SOCIALE																	AS ENSEIGNE_OF,
         		@_COD_FACTURE																				AS NUM_PREFACTURE,
         		(
         			SELECT 
         				dbo.GetShortDate(MIN(SESSIONS_PEC.DAT_DEBUT))	AS DAT_DEBUT_SESSION,
         				dbo.GetShortDate(MAX(SESSIONS_PEC.DAT_FIN))		AS DAT_FIN_SESSION
         			FROM #SESSIONS AS SESSIONS_PEC
         			FOR XML AUTO, ELEMENTS, TYPE	
         		),
         		/*remboursement salaires*/
         		(
         			SELECT 
         				NIC,
         				CIVILITE,
         				NOM_INDIVIDU,
         				PRENOM_INDIVIDU, 
         				dbo.GetFrenchCurrencyFormat(ROUND(TOTAL_SALAIRES/NB_HEURES, 2)) AS TAUX_HORAIRE,
         				dbo.GetFrenchCurrencyFormat(NB_HEURES) AS NB_HEURES, 
         				dbo.GetFrenchCurrencyFormat(TOTAL_SALAIRES) AS TOTAL_SALAIRES
         			FROM #remboursement_salaires AS REMBOURS_SALAIRES
         			WHERE NB_HEURES > 0
         			ORDER BY NOM_INDIVIDU
         			FOR XML AUTO, ELEMENTS, TYPE	
         		),
         		/*montant total tableau salaires*/
         		(
         			SELECT 
         				dbo.GetFrenchCurrencyFormat(sum(TOTAL_SALAIRES)) AS MONTANT_TOTAL
         			FROM #remboursement_salaires AS REMBOURS_SALAIRES_TOTAL 
         			WHERE NB_HEURES > 0
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         		/*remboursement allocation formation - entete*/
         		(
         			SELECT 
         				TITRE_REMBOURSEMENT,
         				TITRE_TAUX,
         				TITRE_NB_H,
         				TITRE_TOTAL
         			FROM #REMBOURS_ALLO_ENTETE AS ENTETE_TABLEAU
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         		/*remboursement allocation formation - corps*/
         		(
         			SELECT
         				NIC,
         				CIVILITE,
         				NOM_INDIVIDU,
         				PRENOM_INDIVIDU, 
         				dbo.GetFrenchCurrencyFormat(TAUX_HORAIRE) as TAUX_HORAIRE, 
         				/*comment‚ en 15212*/
         				--dbo.GetFrenchCurrencyFormat(HEURES_HTT) as HEURES_HTT,
         				--dbo.GetFrenchCurrencyFormat(round(HEURES_HTT * TAUX_HORAIRE, 2)) as TOTAL_STAG	
         				'' AS HEURES_HTT,
         				'' AS TOTAL_STAG			
         			FROM #remboursement_allocation AS REMBOURS_ALLOCATION_FORMATION
         			ORDER BY NOM_INDIVIDU
         			FOR XML AUTO, ELEMENTS, TYPE
         		),
         		/*remboursement allocation formation - pied*/
         		(
         			SELECT
         				LEGENDE,
         				LIBL_TOTAL,
         				dbo.GetFrenchCurrencyFormat(TOTAL_MNT),
         				DERNIERE_LIGNE_TOTAL,
         				DERNIERE_LIGNE_A,
         				DERNIERE_LIGNE_VIRGULE
         			FROM #rembours_allo_entete AS PIED_TABLEAU
         			FOR XML AUTO, ELEMENTS, TYPE
         		)
         		
         		
         	FROM	#TMP_GENERAL AS LETTRE
         	FOR XML AUTO, ELEMENTS	
         	
         END
GO
 CREATE PROCEDURE [dbo].[LEC_GRP_FINANCEMENT_ADHERENT]      
          @ID_POSTE_COUT_REGLE int      
         WITH RECOMPILE    
         AS      
         -- =============================================      
         -- Author  : MBL      
         -- Modified date: 25 juin 2008      
         -- comment  : Refonte complete de la procedure    
         --    Modification du calcul du disponible :    
         -- Dans la version anterieure, Disponible = Solde d'Engagement - Montant imput‚ sur la source de financement sur la DR    
         -- Dans la version actuelle, Disponible = Solde Reel - Somme des Montants imput‚s sur la source de financement et dont le reglement n'est pas valide.    
         -- =============================================      
         -- Author  : kw      
         -- Modified date: 18 juillet 2008      
         -- comment  : Ne comptabiliser que les DR qui sont     
         --en accord decouvert ou en ok financement pour calculer le solde disponible    
         -- =============================================      
         -- Author  : MBL    
         -- Modified date: 26/08/2008      
         -- comment  : Correction pb sur solde adherent/groupe    
         -- comment  : On comptabilise egalement la DR courante dans le calcul du disponible, meme si elle n'est pas OK financement     
         -- =============================================      
         -- Author  : ASD      
         -- Modified date: 19/02/2009    
         -- comment  : Adaptation … C2P    
         -- =============================================      
         -- DSZ 18/12/09    
         -- Mantis 12265  (suite … l'evol 406 historisation du groupe)    
         -- prendre le groupe historis‚ dans le stagiaire    
         -- =============================================      
         -- ASD SAF 14/10/2010     
         -- Perf    
         -- =============================================      
         -- ASD DSZ 25/10/2010     
         -- Suppression d'un des deux curseurs    
         -- with recompile    
         -- =============================================      
         -- SBR 24/04/2013  
         -- En cas d'affichage d'une DR d‚j… r‚gl‚e, le montant imput‚e de la DR continuait … ˆtre retir‚ du solde disponible (donc d‚duit 2 fois)  
         -- =============================================      
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT  
         -- =============================================  
         -- LDE 24/11/2014 #661: Suppression de ID_PUBLIC_FAF et remplacement par ID_TYPE_FINANCEMENT  
         -- =============================================  
         -- DSZ 04/12/2014 #656 : ajout des libell‚s des types financement; nettoyage  
         -- =============================================  
         -- MBL 02/03/2015 : Mise en place de la possibilit‚ d'effectuer un d‚couvert sur le compte Versement volontaire
         -- =============================================  
         -- OPA 21/03/16 1357 
         -- En tant qu'utilisateur Optiform, dans la chaŒne d'engagement ou de rŠglement PEC, 
         -- je ne souhaite pas qu'il y ai de cr‚ation de mouvements budg‚taires sur le type de financement 
         -- Compte Historique si aucun type de financement n'est reconnu.
         -- =============================================
           
         BEGIN      
             
         DECLARE @ID_GROUPE int      
         DECLARE  @MNT_ATTENTE_REGLEMENT decimal(18,2)    
         DECLARE     
           @P_E_R   VARCHAR(1) ,    
           @ID_TYPE_FINANCEMENT int   ,     
           @RELIQUAT  decimal(18,2)      
             
             
          -- Calcul du montant impute sur l'adherent/groupe par source de financement  
          SELECT   
          STAGIAIRE_PEC.ID_GROUPE,   
          PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT,   
          cast(ISNULL(SUM(MNT_PLAN_FINANCEMENT_US), 0) as decimal(18,2)) as MONTANT_IMPUTE,   
          CAST(0 as decimal(18,2)) as RELIQUAT_REEL ,    
          CAST(0 as decimal(18,2)) as RELIQUAT_ENGAGEMENT ,    
          CAST(0 as decimal(18,2)) as RELIQUAT_PREVISIONNEL ,    
          CAST(0 as decimal(18,2))as MNT_ATTENTE_REGLEMENT  
          INTO #TMP01    
          FROM PLAN_FINANCEMENT_US    
            INNER JOIN UNITE_STAGIAIRE  ON UNITE_STAGIAIRE .ID_UNITE_STAGIAIRE  = PLAN_FINANCEMENT_US .ID_UNITE_STAGIAIRE    
            INNER JOIN STAGIAIRE_PEC  ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC   = UNITE_STAGIAIRE . ID_STAGIAIRE_PEC  
          WHERE PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT       IS NOT NULL    
            AND PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE     
          GROUP BY PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT, ID_GROUPE  
          HAVING ABS(ISNULL(SUM(MNT_PLAN_FINANCEMENT_US), 0)) > 0.01    
             
             
          DECLARE cu_solde CURSOR FOR    
           SELECT P_E_R, ID_TYPE_FINANCEMENT = COMPTE.ID_TYPE_FINANCEMENT,     
            SOLDE = ISNULL(SUM (CASE SENS WHEN 'C' THEN 1 ELSE -1 END *  MNT_MVT_BUDGETAIRE)  , 0),    
            #TMP01.ID_GROUPE    
           FROM MVT_BUDGETAIRE       
            INNER JOIN COMPTE     ON MVT_BUDGETAIRE.ID_COMPTE   = COMPTE.ID_COMPTE      
            INNER JOIN PARAMETRAGE_BUDGETAIRE ON COMPTE.ID_TYPE_COMPTE    = PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE       
            AND MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT      
            INNER JOIN #TMP01   ON #TMP01.ID_TYPE_FINANCEMENT   = MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT    
            AND MVT_BUDGETAIRE.ID_GROUPE = #TMP01.ID_GROUPE    
           GROUP BY P_E_R, COMPTE.ID_TYPE_FINANCEMENT , #TMP01.ID_GROUPE    
             
          OPEN cu_solde    
          FETCH cu_solde INTO @P_E_R, @ID_TYPE_FINANCEMENT, @RELIQUAT, @ID_GROUPE    
             
             
          WHILE (@@fetch_status <> -1)    
          BEGIN    
          -- Calcul des montants non regles pour diminuer le disponible    
           SELECT @MNT_ATTENTE_REGLEMENT = ISNULL(SUM(MNT_PLAN_FINANCEMENT_US), 0)    
           FROM PLAN_FINANCEMENT_US    
          INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE .ID_POSTE_COUT_REGLE = PLAN_FINANCEMENT_US .ID_POSTE_COUT_REGLE    
          INNER JOIN UNITE_STAGIAIRE  ON UNITE_STAGIAIRE .ID_UNITE_STAGIAIRE  = PLAN_FINANCEMENT_US .ID_UNITE_STAGIAIRE    
          INNER JOIN STAGIAIRE_PEC  ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC   = UNITE_STAGIAIRE . ID_STAGIAIRE_PEC    
          LEFT JOIN REGLEMENT    ON  REGLEMENT.ID_REGLEMENT =POSTE_COUT_REGLE.ID_REGLEMENT     
           WHERE  ID_TYPE_FINANCEMENT       = @ID_TYPE_FINANCEMENT   
          and STAGIAIRE_PEC.ID_GROUPE=@ID_GROUPE    
          AND POSTE_COUT_REGLE.BLN_ACTIF    = 1    
          AND PLAN_FINANCEMENT_US.BLN_ACTIF = 1    
          AND (    
            (POSTE_COUT_REGLE.DAT_BAP IS NOT NULL AND REGLEMENT.DAT_VALID_REGLEMENT IS NULL)    
            OR     
            (POSTE_COUT_REGLE.DAT_BAP IS NULL AND  (POSTE_COUT_REGLE.ID_ETAT_PEC = 1 OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3) AND (POSTE_COUT_REGLE.BLN_OK_FINANCEMENT = 1) )    
            OR    
            (POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE AND REGLEMENT.DAT_VALID_REGLEMENT IS NULL)  -- SBR le 24/04/13  
           )    
           BEGIN    
            UPDATE #TMP01     
            SET RELIQUAT_REEL   = CASE @P_E_R WHEN 'R' THEN @RELIQUAT ELSE RELIQUAT_REEL   END,    
          RELIQUAT_ENGAGEMENT  = CASE @P_E_R WHEN 'E' THEN @RELIQUAT ELSE RELIQUAT_ENGAGEMENT  END,    
          RELIQUAT_PREVISIONNEL = CASE @P_E_R WHEN 'P' THEN @RELIQUAT ELSE RELIQUAT_PREVISIONNEL END,    
          MNT_ATTENTE_REGLEMENT = @MNT_ATTENTE_REGLEMENT    
            WHERE ID_TYPE_FINANCEMENT = @ID_TYPE_FINANCEMENT     
            AND  ISNULL(ID_GROUPE, -1)  =  ISNULL(@ID_GROUPE, -1)    
           END    
            
           FETCH cu_solde INTO @P_E_R, @ID_TYPE_FINANCEMENT, @RELIQUAT, @ID_GROUPE    
             
          END    
             
          CLOSE cu_solde    
          DEALLOCATE cu_solde    
             
             
         SELECT   
          GROUPE.LIB_GROUPE AS LIBELLE,  
          TYPE_FINANCEMENT.LIBL_TYPE_FINANCEMENT AS LIBL_TYPE_FINANCEMENT,    
           MONTANT_IMPUTE,       
           ROUND(RELIQUAT_REEL, 2) AS MNT_REEL,    
           ROUND(RELIQUAT_REEL  + RELIQUAT_ENGAGEMENT,2)  AS  MNT_ENGAGEMENT,    
           ROUND(RELIQUAT_REEL  + RELIQUAT_ENGAGEMENT + RELIQUAT_PREVISIONNEL, 2) AS MNT_PREVISIONNEL,    
           ROUND(ROUND(RELIQUAT_REEL,2) - MNT_ATTENTE_REGLEMENT, 2) AS SOLDE_DISPONIBLE,    
           CASE --sur SOLDE_DISPONIBLE    
            WHEN ROUND(ROUND(RELIQUAT_REEL,2) - MNT_ATTENTE_REGLEMENT, 2) >=0 THEN NULL    --
            ELSE
            CASE WHEN TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN ('3')  -- Le decouvert est possible que pour les Versement volontaire
            THEN 'A autoriser'    
            ELSE 'Interdit'    
            END
            
         --  AND TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT = '1' ) THEN 'A autoriser'    
         --   WHEN (ROUND(ROUND(RELIQUAT_REEL,2) - MNT_ATTENTE_REGLEMENT, 2) <0 AND TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT <> '1') THEN 'Interdit'    
           END AS DECOUVERT    
          FROM #TMP01    
           INNER JOIN GROUPE    ON GROUPE.ID_GROUPE = #TMP01.ID_GROUPE    
           INNER JOIN TYPE_FINANCEMENT ON TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT = #TMP01.ID_TYPE_FINANCEMENT    
         END
GO
 -- =============================================
         -- Author			: SLA
         -- Creation date	: 10/10/2012
         -- 13190			: [13985]  
         -- Description		: Proc‚dure d'insertion d'un autorisation du pr‚lŠvement venant de
         -- l'Extranet avec ses champs supl‚mentaires.
         -- Est bas‚ sur INS_AUTORISATION_PRELEVEMENT
         -- =============================================
         CREATE PROCEDURE [dbo].[INS_AUTORISATION_PRELEVEMENT]
         		@ID_ETABLISSEMENT INT,
         		@LIBL_ETABLISSEMENT_BANCAIRE varchar(100),
         		@LIBL_ADRESSE_BANQUE_1 varchar(255),
         		@LIBL_ADRESSE_BANQUE_2 varchar(255),
         		@LIBL_ADRESSE_BANQUE_3 varchar(255),
         		@LIBL_CODE_POSTAL_BANQUE VARCHAR(10),
         		@LIBL_VILLE_BANQUE VARCHAR(100),
         		@COD_RUM VARCHAR(35),
         		@NUM_IBAN varchar(34),
         		@NUM_BIC varchar(11),
         		@REF_EXTRANET uniqueidentifier,
         		@ID_OPTIFORM INT,
         		@DAT_SIGNATURE datetime  -- WKH, 17/12/2013, #16609, rajout de la colonne DAT_SIGNATURE
         AS  
         
         DECLARE @DAT_CREATION DATETIME = GETDATE();
                
         IF(@ID_OPTIFORM is null)
         	BEGIN
         		INSERT INTO AUTORISATION_PRELEVEMENT
         				   (ID_ETABLISSEMENT
         				   ,LIBL_ETABLISSEMENT_BANCAIRE
         				   ,LIBL_ADRESSE_BANQUE_1
         				   ,LIBL_ADRESSE_BANQUE_2
         				   ,LIBL_ADRESSE_BANQUE_3
         				   ,LIBL_CODE_POSTAL_BANQUE
         				   ,LIBL_VILLE_BANQUE
         				   ,COD_RUM
         				   ,DAT_CREATION
         				   ,ID_UTILISATEUR
         				   ,NUM_IBAN
         				   ,NUM_BIC
         				   ,ID_ETAT
         				   ,REF_EXTRANET,
         				   DAT_SIGNATURE)
         			 VALUES
         				   (@ID_ETABLISSEMENT
         				   ,@LIBL_ETABLISSEMENT_BANCAIRE
         				   ,@LIBL_ADRESSE_BANQUE_1
         				   ,@LIBL_ADRESSE_BANQUE_2
         				   ,@LIBL_ADRESSE_BANQUE_3
         				   ,@LIBL_CODE_POSTAL_BANQUE
         				   ,@LIBL_VILLE_BANQUE
         				   ,@COD_RUM
         				   ,@DAT_CREATION 
         				   ,82
         				   ,@NUM_IBAN
         				   ,@NUM_BIC
         				   ,1
         				   ,@REF_EXTRANET,
         				   @DAT_SIGNATURE)
         END
         ELSE
         BEGIN 
         	UPDATE AUTORISATION_PRELEVEMENT
         	SET REF_EXTRANET = @REF_EXTRANET
         	WHERE ID_AUTORISATION_PRELEVEMENT = @ID_OPTIFORM
         END
         
GO
 CREATE PROCEDURE [dbo].[MB_INS_CHIFFRAGE]
         	@ID_MODULE_PEC INT  
         AS  
         BEGIN  
          -- VAR DECLARATION  
          DECLARE @CURRENT_DATE DATETIME
          DECLARE @LIBL_EVENEMENT VARCHAR(50)
          DECLARE @ID_TYPE_EVENEMENT INT
          DECLARE @ID_EVENEMENT INT
          DECLARE @ID_POSTE_COUT_ENGAGE INT
          DECLARE @DAT_DESENGAGEMENT DATETIME
          DECLARE @ID_ACTION_PEC INT
          SELECT	@ID_ACTION_PEC = ID_ACTION_PEC FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC
            
          -- VAR INITIALIZATION  
          SET @CURRENT_DATE = GETDATE()  
          SET @ID_TYPE_EVENEMENT = 11 -- CHIFFRAGE PEC  
          SELECT @LIBL_EVENEMENT = LIBL_TYPE_EVENEMENT FROM TYPE_EVENEMENT  
           WHERE ID_TYPE_EVENEMENT = @ID_TYPE_EVENEMENT  
         
          DECLARE CURSOR_POSTE_COUT_ENGAGE  
           CURSOR FOR  
            SELECT	ID_POSTE_COUT_ENGAGE, DAT_DESENGAGEMENT  
            FROM		POSTE_COUT_ENGAGE  
            WHERE	POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE_PEC  
            AND		POSTE_COUT_ENGAGE.MNT_ENGAGE_HT > 0  
         -- DIFFERE DE INS_CHIFFRAGE SUR LA LIGNE SUPPRIMEE INDIQUEE
             --and POSTE_COUT_ENGAGE.ID_ENGAGEMENT is null  
            
          OPEN CURSOR_POSTE_COUT_ENGAGE  
          FETCH NEXT FROM CURSOR_POSTE_COUT_ENGAGE INTO  
           @ID_POSTE_COUT_ENGAGE,  
           @DAT_DESENGAGEMENT  
             
          WHILE (@@Fetch_Status <> -1)  
          BEGIN --FOREACH POSTE_COUT_ENGAGE IN THE MODULE  
           IF (@@Fetch_Status <> -2)   
           BEGIN -- (@@Fetch_Status <> -2)   
            IF (@DAT_DESENGAGEMENT IS NULL) -- IF THE POSTE_COUT_ENGAGE IS NOT DESENGAGED  
              
            BEGIN --(@DAT_DESENGAGEMENT IS NULL)       
            IF EXISTS (SELECT ID_EVENEMENT FROM EVENEMENT WHERE ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE AND ID_TYPE_EVENEMENT = 11)  
             BEGIN      
             SELECT @ID_EVENEMENT = ID_EVENEMENT FROM EVENEMENT WHERE ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE AND ID_TYPE_EVENEMENT = 11
             END  
            ELSE  
             BEGIN      
               -- CREATE THE NEW EVENEMENT  
               INSERT INTO EVENEMENT (LIBL_EVENEMENT, DAT_EVENEMENT, ID_TYPE_EVENEMENT, ID_POSTE_COUT_ENGAGE)
                VALUES (@LIBL_EVENEMENT, @CURRENT_DATE ,@ID_TYPE_EVENEMENT ,@ID_POSTE_COUT_ENGAGE)
               SET @ID_EVENEMENT = @@IDENTITY  
             END  
            -- CREATE THE NEW NEEDED MVT BUDGE  
            
            EXEC MB_INS_MVT_BUDGETAIRE_CHIFFRAGE @ID_POSTE_COUT_ENGAGE, @ID_EVENEMENT, @CURRENT_DATE  
              
            END --(@DAT_DESENGAGEMENT IS NULL)   
             
           END -- (@@Fetch_Status <> -2)   
           FETCH NEXT FROM CURSOR_POSTE_COUT_ENGAGE INTO  
            @ID_POSTE_COUT_ENGAGE,  
            @DAT_DESENGAGEMENT  
          END --FOREACH POSTE_COUT_ENGAGE IN THE MODULE  
           
          CLOSE CURSOR_POSTE_COUT_ENGAGE  
          DEALLOCATE CURSOR_POSTE_COUT_ENGAGE  
         END     
         
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_ARRIVEE_PIECES_PRO]
         -- =============================================
         -- Author		: KWO
         -- Create date	: XX XXXX 2007
         -- Description	: Cr‚ation de la proc‚dure de lecture arr. pieces pro
         -- ---------------------------------------------
         -- Author		: KSA
         -- Modif. date	: 16 et 18 et 22 janvier 2008
         -- Description	: Alt‚ration pour la lecture avec ID, afin d'avoir uniquement ceux du CONTRAT/MODULE/SESSION PRO
         -- ---------------------------------------------
         -- Modif. date	: 1er avril 2008
         -- Description	: Ajout BLN_BLOQUANT_ENGAGEMENT, BLN_BLOQUANT_REGLEMENT
         -- ---------------------------------------------
         -- Author		: DSZ
         -- Modif. date	: 26/09/2011
         -- Description	: 12820; Dedoublage de facture en Of et ADH
         -- ajout order by, ajout cod_piece_pro
         -- cosmetique code
         -- ---------------------------------------------
         -- Author		: APA
         -- Modif. date	: 22/12/2011
         -- Description	: Ajout R‚pertoire, nom fichier, Type piŠce et Information + non exclusif Contrat / Module / Session
         --				  NON INCLUSIF Means: BLN Contrat, module and session can be all true
         --                SI blnContrat = 1 --> l'ID est celui du contrat (inclut si tous les 3 sont … 1.
         --                SI blnContrat = 0 et blnModule = 1 --> l'ID est celui du module
         --                SI blnContrat = 0 et blnModule = 0 et blnSession = 1 --> l'ID est celui de la session
         -- ---------------------------------------------
         -- LDE 19/06/2013 #15282: Gestion des piŠces Autres
         -- ============================================================================
         -- DSZ 26/06/2013 : 15338: ajout ID_UTILISATEUR
         -- ============================================================================
         -- DSZ 12/11/2013 : 16337 ajout NOM_FICHIER
         -- ============================================================================
         -- OPA 04/11/2013 : 16517: BBL : LEC_GRP_ARRIVEE_PIECES_PRO_MBL : nb de colonnes
         -- ============================================================================
         -- DSZ 11/07/2014 US#399 refection bln_autres
         -- ============================================================================
         -- Author		: MBL 
         -- Modif. date	: 21/10/2015
         -- description  : Refonte complŠte PS suite … pr‚conisation DBA
         -- ============================================================================
         
         	@ID int,			  --Identifiant de l'‚l‚ment manipul‚ (Contrat, Module ou Session PRO)
         	@BLN_ACTIF TINYINT,   --Les pieces actives
         	@BLN_CONTRAT TINYINT, --Les pieces li‚es aux contrats
         	@BLN_MODULE TINYINT,  --Les pieces li‚es aux modules
         	@BLN_SESSION TINYINT  --Les pieces li‚es aux sessions
         AS 
         
         DECLARE @ID_CONTRAT_PRO			INT
         DECLARE @ID_MODULE_PRO			INT
         DECLARE @ID_SESSION_PRO			INT
         DECLARE @COD_CONTRAT_PRO		VARCHAR(10)
         DECLARE @COD_SESSION_PRO		VARCHAR(12)
         DECLARE @DAT_CREATION_CONTRAT	DATETIME		
         
         BEGIN
         
         	DECLARE
         	@arrivee_piece TABLE 
         	(
         		ID_PIECE_PRO			int,
         		ID_ARRIVEE_PIECE_PRO	int
         	)
         		
         	IF @ID IS NULL 
         	BEGIN
         	
         		-- Renvoie la liste des pieces PRO, independamment d'un element specifique associees a 
         		 -- un contrat pro	si @BLN_CONTRAT = 1
         		 -- un module pro	si @BLN_MODULE = 1
         		 -- une session PRO si @BLN_SESSION = 1
         		SELECT 		PIECE_PRO.ID_PIECE_PRO,
         					PIECE_PRO.LIBL_PIECE_PRO,
         					-1*ROW_NUMBER() OVER(ORDER BY ID_PIECE_PRO) as ID_ARRIVEE_PIECE_PRO,
         					NULL AS COD_ARRIVEE_PIECE_PRO,
         					NULL AS DAT_ARRIVEE_PIECE_PRO,
         					1 AS BLN_ACTIF,
         					1 AS BLN_CONFORME,
         					NULL AS COM_ARRIVEE_PIECE_PRO,
         					NULL AS ID_CONTRAT_PRO,
         					NULL AS ID_MODULE_PRO,
         					NULL AS ID_SESSION_PRO,
         					NULL AS DAT_RELANCE_ENGAGE_1,
         					NULL AS DAT_RELANCE_ENGAGE_2,
         					NULL AS DAT_RELANCE_ENGAGE_3,
         					NULL AS DAT_RELANCE_REGLE_1,
         					NULL AS DAT_RELANCE_REGLE_2,
         					NULL AS DAT_RELANCE_REGLE_3,
         					NULL AS LIB_RELANCE_ENGAGE,
         					NULL AS LIB_RELANCE_REGLE,
         					BLN_BLOQUANT_ENGAGEMENT,
         					BLN_BLOQUANT_REGLEMENT,
         					cast (null as TIMESTAMP) as TIME_STAMP,
         					COD_PIECE_PRO,
         					REPERTOIRE,
         					CAST(NULL AS VARCHAR(50)) AS INFORMATION,
         					CASE 
         						WHEN BLN_SESSION	= 1 THEN 'Session'
         						WHEN BLN_MODULE		= 1  THEN 'Module'
         						WHEN BLN_CONTRAT	= 1 THEN 'Contrat'
         					ELSE NULL
         					END as TYPE_PIECE,						
         					NULL AS COD_CONTRAT_PRO,
         					NULL AS COD_MODULE_PRO,
         					NULL AS COD_SESSION_PRO,
         					NULL AS DAT_CREATION,
         					BLN_AUTRE as BLN_AUTRES,
         					NUM_FILE= CAST(0 AS INT),
         					ID_UTILISATEUR = CAST(NULL AS INT),
         					NOM_FICHIER = CAST( NULL AS VARCHAR(100))
         
         		FROM        PIECE_PRO 
         		WHERE		(PIECE_PRO.BLN_ACTIF = @BLN_ACTIF)
         					AND	(
         							   ((PIECE_PRO.BLN_SESSION = @BLN_SESSION) AND  (@BLN_SESSION = 1))
         							OR ((PIECE_PRO.BLN_MODULE  = @BLN_MODULE)  AND  (@BLN_MODULE  = 1))
         							OR ((PIECE_PRO.BLN_CONTRAT = @BLN_CONTRAT) AND  (@BLN_CONTRAT = 1))
         						)
         		ORDER BY TYPE_PIECE, INFORMATION
         	END --@ID is null
         	
         	
         	ELSE -- @ID is not null
         	BEGIN
         
         		SET @ID_MODULE_PRO =
         		(CASE
         			WHEN @BLN_CONTRAT = 1 AND @BLN_MODULE = 0 THEN NULL
         			WHEN @BLN_MODULE = 1 AND @BLN_CONTRAT = 0 THEN @ID
         			WHEN @BLN_SESSION = 1 THEN (SELECT TOP(1) ID_MODULE_PRO FROM SESSION_PRO WHERE ID_SESSION_PRO = @ID)
         		END)
         			
         		SET @ID_CONTRAT_PRO = 
         		(CASE 
         			WHEN @BLN_CONTRAT = 1 THEN @ID
         			WHEN @BLN_CONTRAT = 0 AND (@BLN_MODULE = 1 OR @BLN_SESSION = 1) THEN (SELECT TOP(1) ID_CONTRAT_PRO FROM MODULE_PRO WHERE ID_MODULE_PRO = @ID_MODULE_PRO)
         		END)
         			
         		-- Determination de la session PRO associee au contexte
         		SET @ID_SESSION_PRO =
         		(CASE WHEN @BLN_SESSION = 1 THEN @ID
         		END)
         				
         
         		IF @ID_CONTRAT_PRO IS NOT NULL
         		BEGIN
         			SELECT @COD_CONTRAT_PRO = COD_CONTRAT_PRO, @DAT_CREATION_CONTRAT = DAT_CREATION
         			FROM CONTRAT_PRO
         			WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
         		END
         
         		IF @ID_SESSION_PRO IS NOT NULL
         		BEGIN
         			SELECT @COD_SESSION_PRO = COD_SESSION_PRO
         			FROM SESSION_PRO
         			WHERE ID_SESSION_PRO = @ID_SESSION_PRO
         		END
         
         		IF @BLN_CONTRAT = 1 
         		-- Les pieces de type contrat (BLN_CONTRAT = 1) associees au contrat sont ramenees
         		BEGIN
         			INSERT INTO @arrivee_piece
         			SELECT
         			PIECE_PRO.ID_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         			FROM		PIECE_PRO
         			LEFT JOIN	ARRIVEE_PIECE_PRO			ON	ARRIVEE_PIECE_PRO.ID_PIECE_PRO		= PIECE_PRO.ID_PIECE_PRO		
         													AND	ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         			WHERE	PIECE_PRO.BLN_CONTRAT		= 1
         			AND		PIECE_PRO.BLN_ACTIF			= @BLN_ACTIF
         		END
         		
         		IF @BLN_MODULE = 1 AND @ID_MODULE_PRO IS NULL
         		-- Les pieces de type module (BLN_MODULE = 1) associees aux modules du contrat sont ramenees
         		BEGIN
         			INSERT INTO @arrivee_piece
         			SELECT
         			PIECE_PRO.ID_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         			FROM		PIECE_PRO
         			LEFT JOIN	ARRIVEE_PIECE_PRO			ON	ARRIVEE_PIECE_PRO.ID_PIECE_PRO		= PIECE_PRO.ID_PIECE_PRO		
         													AND	ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         			WHERE	PIECE_PRO.BLN_MODULE			= 1
         			AND		PIECE_PRO.BLN_ACTIF				= @BLN_ACTIF
         		END
         		
         		IF @BLN_MODULE = 1 AND @ID_MODULE_PRO IS NOT NULL
         		-- Les pieces de type module (BLN_MODULE = 1) associees au module du contrat sont ramenees
         		BEGIN
         			INSERT INTO @arrivee_piece
         			SELECT
         			PIECE_PRO.ID_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         			FROM		PIECE_PRO
         			LEFT JOIN	ARRIVEE_PIECE_PRO		ON	ARRIVEE_PIECE_PRO.ID_PIECE_PRO		= PIECE_PRO.ID_PIECE_PRO		
         												AND	ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO
         			WHERE	PIECE_PRO.BLN_MODULE			= 1
         			AND		PIECE_PRO.BLN_ACTIF				= @BLN_ACTIF
         		END	
         		
         		IF @BLN_SESSION	= 1
         		-- Les pieces de type session (BLN_MODULE = 1) associees … la session sont ramenees
         		BEGIN
         			INSERT INTO @arrivee_piece
         			SELECT
         			PIECE_PRO.ID_PIECE_PRO,
         			ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         			FROM		PIECE_PRO			
         			LEFT JOIN	ARRIVEE_PIECE_PRO		ON		ARRIVEE_PIECE_PRO.ID_PIECE_PRO		= PIECE_PRO.ID_PIECE_PRO		
         												AND		ARRIVEE_PIECE_PRO.ID_SESSION_PRO	= @ID_SESSION_PRO
         			WHERE	PIECE_PRO.BLN_SESSION				= 1
         			AND		PIECE_PRO.BLN_ACTIF					= @BLN_ACTIF
         		END		
         
         --SELECT * FROM @arrivee_piece
         		SELECT
         		PIECE_PRO.ID_PIECE_PRO,
         		PIECE_PRO.LIBL_PIECE_PRO,
         		CASE 
         			WHEN (ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO is null 
         					OR ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO < 1) 
         					THEN -1*ROW_NUMBER() OVER(ORDER BY ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO) 
         			ELSE ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         		END											AS ID_ARRIVEE_PIECE_PRO,
         		ARRIVEE_PIECE_PRO.COD_ARRIVEE_PIECE_PRO,
         		ARRIVEE_PIECE_PRO.DAT_ARRIVEE_PIECE_PRO,
         		ISNULL(ARRIVEE_PIECE_PRO.BLN_ACTIF, 1)		AS BLN_ACTIF,
         		ISNULL(ARRIVEE_PIECE_PRO.BLN_CONFORME, 1)	AS BLN_CONFORME,
         		ARRIVEE_PIECE_PRO.COM_ARRIVEE_PIECE_PRO,
         		ID_CONTRAT_PRO = @ID_CONTRAT_PRO,
         		ID_MODULE_PRO =  MODULE_PRO.ID_MODULE_PRO, 
         		ID_SESSION_PRO = @ID_SESSION_PRO,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         		ARRIVEE_PIECE_PRO.TIME_STAMP,
         		CASE 
         			WHEN	(ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) 
         			THEN			NULL
         			
         			WHEN	(ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NOT NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) 
         			THEN			'Relance Nø 1 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,103)	
         			
         			WHEN	(ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NOT NULL) 
         					AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) 
         			THEN			'Relance Nø 2 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,103)
         			
         			WHEN	(ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NOT NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NOT NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NOT NULL) 
         			THEN			'Relance Nø 3 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3,103)
         			
         		END											AS LIB_RELANCE_ENGAGE,
         
         		CASE	
         			WHEN	 
         					(ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) 
         			THEN			NULL
         			
         			WHEN	(ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NOT NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) 
         			THEN			'Relance Nø 1 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,103)
         			
         			WHEN    (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NOT NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) 
         			THEN			'Relance Nø 2 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,103)
         			
         			WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NOT NULL)
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NOT NULL) 
         				AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NOT NULL) 
         			THEN			'Relance Nø 3 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,103)
         		END											AS LIB_RELANCE_REGLE,		
         		PIECE_PRO.COD_PIECE_PRO,
         		PIECE_PRO.BLN_BLOQUANT_ENGAGEMENT,
         		PIECE_PRO.BLN_BLOQUANT_REGLEMENT,
         		PIECE_PRO.REPERTOIRE,
         		INFORMATION = CASE 
         			WHEN MODULE_PRO.ID_MODULE_PRO IS NOT NULL AND  PIECE_PRO.BLN_MODULE = 1 THEN 
         			MODULE_PRO.COD_MODULE_PRO + ' - ' + TYPE_FORMATION.LIBC_TYPE_FORMATION
         			WHEN SESSION_PRO.ID_SESSION_PRO IS NOT NULL AND  PIECE_PRO.BLN_SESSION = 1 THEN 
         			SESSION_PRO.COD_SESSION_PRO + ' - ' + TYPE_FORMATION.LIBC_TYPE_FORMATION
         			ELSE null 
         		END ,			
         		TYPE_PIECE =	CASE 
         							WHEN PIECE_PRO.BLN_SESSION = 1	THEN 'Session'
         							WHEN PIECE_PRO.BLN_MODULE = 1	THEN 'Module'
         							WHEN PIECE_PRO.BLN_CONTRAT = 1	THEN 'Contrat'
         							ELSE NULL
         						END ,		
         		COD_CONTRAT_PRO = @COD_CONTRAT_PRO			,
         		COD_MODULE_PRO	= MODULE_PRO.COD_MODULE_PRO	, 
         		COD_SESSION_PRO = @COD_SESSION_PRO			,
         		DAT_CREATION	= @DAT_CREATION_CONTRAT,
         		PIECE_PRO.BLN_AUTRE							AS BLN_AUTRES,
         		coalesce(ARRIVEE_PIECE_PRO.NUM_FILE,0)		AS NUM_FILE,
         		-- /LDE 19/06/2013 #15282
         		ARRIVEE_PIECE_PRO.ID_UTILISATEUR,
         		ARRIVEE_PIECE_PRO.NOM_FICHIER 
         		FROM PIECE_PRO			
         		INNER JOIN @arrivee_piece		AP		ON PIECE_PRO.ID_PIECE_PRO			=	AP.ID_PIECE_PRO 
         		LEFT JOIN ARRIVEE_PIECE_PRO				ON AP.ID_ARRIVEE_PIECE_PRO			=	ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO	
         		LEFT JOIN MODULE_PRO					ON ARRIVEE_PIECE_PRO.ID_MODULE_PRO	=	MODULE_PRO	.ID_MODULE_PRO	
         		LEFT JOIN SESSION_PRO					ON ARRIVEE_PIECE_PRO.ID_SESSION_PRO	=	SESSION_PRO	.ID_SESSION_PRO
         		LEFT JOIN TYPE_FORMATION				ON TYPE_FORMATION.ID_TYPE_FORMATION	=	MODULE_PRO	.ID_TYPE_FORMATION
         		WHERE PIECE_PRO.BLN_ACTIF			= @BLN_ACTIF
         				
         		ORDER BY ID_MODULE_PRO, TYPE_PIECE, LIBL_PIECE_PRO
         
         
         	END  -- @id is not null
         	
         	
         	/* Code desactive Suite Refonte
         		IF @ID IS NULL 
         		BEGIN
         			with temp
         			as
         			(
         			SELECT DISTINCT	PIECE_PRO.ID_PIECE_PRO,
         						PIECE_PRO.LIBL_PIECE_PRO,
         						NULL AS ID_ARRIVEE_PIECE_PRO,
         						NULL AS COD_ARRIVEE_PIECE_PRO,
         						NULL AS DAT_ARRIVEE_PIECE_PRO,
         						1 AS BLN_ACTIF,
         						1 AS BLN_CONFORME,
         						NULL AS COM_ARRIVEE_PIECE_PRO,
         						NULL AS ID_CONTRAT_PRO,
         						NULL AS ID_MODULE_PRO,
         						NULL AS ID_SESSION_PRO,
         						NULL AS DAT_RELANCE_ENGAGE_1,
         						NULL AS DAT_RELANCE_ENGAGE_2,
         						NULL AS DAT_RELANCE_ENGAGE_3,
         						NULL AS DAT_RELANCE_REGLE_1,
         						NULL AS DAT_RELANCE_REGLE_2,
         						NULL AS DAT_RELANCE_REGLE_3,
         						NULL AS LIB_RELANCE_ENGAGE,
         						NULL AS LIB_RELANCE_REGLE,
         						BLN_BLOQUANT_ENGAGEMENT,
         						BLN_BLOQUANT_REGLEMENT,
         						COD_PIECE_PRO,
         						REPERTOIRE,
         						BLN_SESSION,
         						BLN_MODULE, 
         						BLN_CONTRAT,
         						NULL AS COD_CONTRAT_PRO,
         						NULL AS COD_MODULE_PRO,
         						NULL AS COD_SESSION_PRO,
         						NULL AS DAT_CREATION,
         						BLN_AUTRE as BLN_AUTRES
         			FROM        PIECE_PRO 
         						LEFT JOIN ARRIVEE_PIECE_PRO ON PIECE_PRO.ID_PIECE_PRO = ARRIVEE_PIECE_PRO.ID_PIECE_PRO
         			WHERE		(PIECE_PRO.BLN_ACTIF = @BLN_ACTIF)
         						AND	(
         								   ((PIECE_PRO.BLN_SESSION = @BLN_SESSION) AND  (@BLN_SESSION = 1))
         								OR ((PIECE_PRO.BLN_MODULE  = @BLN_MODULE)  AND  (@BLN_MODULE  = 1))
         								OR ((PIECE_PRO.BLN_CONTRAT = @BLN_CONTRAT) AND  (@BLN_CONTRAT = 1))
         							)
         			)
         			SELECT	temp.ID_PIECE_PRO,
         					temp.LIBL_PIECE_PRO,
         					-1*ROW_NUMBER() OVER(ORDER BY temp.ID_ARRIVEE_PIECE_PRO) as ID_ARRIVEE_PIECE_PRO,
         					temp.COD_ARRIVEE_PIECE_PRO,
         					temp.DAT_ARRIVEE_PIECE_PRO,
         					temp.BLN_ACTIF,
         					temp.BLN_CONFORME,
         					temp.COM_ARRIVEE_PIECE_PRO,
         					temp.ID_CONTRAT_PRO,
         					temp.ID_MODULE_PRO,
         					temp.ID_SESSION_PRO,
         					temp.DAT_RELANCE_ENGAGE_1,
         					temp.DAT_RELANCE_ENGAGE_2,
         					temp.DAT_RELANCE_ENGAGE_3,
         					temp.DAT_RELANCE_REGLE_1,
         					temp.DAT_RELANCE_REGLE_2,
         					temp.DAT_RELANCE_REGLE_3,
         					temp.LIB_RELANCE_ENGAGE,
         					temp.LIB_RELANCE_REGLE,
         					temp.BLN_BLOQUANT_ENGAGEMENT,
         					temp.BLN_BLOQUANT_REGLEMENT,
         					cast (null as TIMESTAMP) as TIME_STAMP,
         					temp.COD_PIECE_PRO,
         					temp.REPERTOIRE,
         					
         					CASE 
         						WHEN temp.ID_MODULE_PRO IS NOT NULL AND temp.ID_SESSION_PRO IS NULL THEN 
         							 (SELECT COD_MODULE_PRO + ' - ' + TYPE_FORMATION.LIBC_TYPE_FORMATION
         							 FROM MODULE_PRO
         								LEFT JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
         							 WHERE temp.ID_MODULE_PRO = ID_MODULE_PRO)
         						ELSE null
         					END as INFORMATION,
         					CASE 
         						WHEN temp.BLN_SESSION = 1 THEN 'Session'
         						WHEN temp.BLN_MODULE = 1  THEN 'Module'
         						WHEN temp.BLN_CONTRAT = 1 THEN 'Contrat'
         					ELSE NULL
         					END as TYPE_PIECE,
         					temp.COD_CONTRAT_PRO,
         					temp.COD_MODULE_PRO,
         					temp.COD_SESSION_PRO,
         					temp.DAT_CREATION,
         					-- LDE 19/06/2013 #15282
         					temp.BLN_AUTRES ,
         					coalesce(ARRIVEE_PIECE_PRO.NUM_FILE,0) as NUM_FILE,
         					-- /LDE 19/06/2013 #15282
         					ARRIVEE_PIECE_PRO.ID_UTILISATEUR,
         					ARRIVEE_PIECE_PRO.NOM_FICHIER
         
         			FROM	temp
         					LEFT JOIN ARRIVEE_PIECE_PRO ON temp.ID_ARRIVEE_PIECE_PRO = ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO 
         			ORDER BY TYPE_PIECE, INFORMATION
         
         		END --@ID is null
         	
         	ELSE -- @ID is not null
         BEGIN
         
         	DECLARE @ID_MODULE_PRO INT
         	SET @ID_MODULE_PRO =
         	(CASE
         		WHEN @BLN_CONTRAT = 1 AND @BLN_MODULE = 0 THEN NULL
         		WHEN @BLN_MODULE = 1 AND @BLN_CONTRAT = 0 THEN @ID
         		WHEN @BLN_SESSION = 1 THEN (SELECT TOP(1) ID_MODULE_PRO FROM SESSION_PRO WHERE ID_SESSION_PRO = @ID)
         	END)
         		
         	DECLARE @ID_CONTRAT_PRO INT
         	SET @ID_CONTRAT_PRO = 
         	(CASE 
         		WHEN @BLN_CONTRAT = 1 THEN @ID
         		WHEN @BLN_MODULE = 1 AND @BLN_CONTRAT = 0 OR @BLN_SESSION = 1 THEN (SELECT TOP(1) ID_CONTRAT_PRO FROM MODULE_PRO WHERE ID_MODULE_PRO = @ID_MODULE_PRO)
         	END)
         			
         	SELECT
         		PIECE_PRO.ID_PIECE_PRO,
         		LIBL_PIECE_PRO,
         		CASE 
         			WHEN (ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO is null OR ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO < 1) THEN -1*ROW_NUMBER() OVER(ORDER BY ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO) 
         			ELSE ARRIVEE_PIECE_PRO.ID_ARRIVEE_PIECE_PRO
         		END AS ID_ARRIVEE_PIECE_PRO,
         		ARRIVEE_PIECE_PRO.COD_ARRIVEE_PIECE_PRO,
         		ARRIVEE_PIECE_PRO.DAT_ARRIVEE_PIECE_PRO,
         		ISNULL(ARRIVEE_PIECE_PRO.BLN_ACTIF, 1) AS BLN_ACTIF,
         		ISNULL(ARRIVEE_PIECE_PRO.BLN_CONFORME, 1) AS BLN_CONFORME,
         		ARRIVEE_PIECE_PRO.COM_ARRIVEE_PIECE_PRO,
         		@ID_CONTRAT_PRO AS ID_CONTRAT_PRO,
         		MODULE_PRO.ID_MODULE_PRO,
         		CASE
         			WHEN @BLN_SESSION = 1 THEN @ID
         			ELSE NULL
         		END AS ID_SESSION_PRO,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,
         		ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,
         		ARRIVEE_PIECE_PRO.TIME_STAMP,
         		CASE WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) THEN
         			NULL
         		WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NOT NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) THEN
         			'Relance Nø 1 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1,103)	
         		WHEN    (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NOT NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NULL) THEN
         			'Relance Nø 2 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2,103)
         		WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_1 IS NOT NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_2 IS NOT NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3 IS NOT NULL) THEN
         			'Relance Nø 3 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_ENGAGE_3,103)
         		END AS LIB_RELANCE_ENGAGE,
         
         		CASE WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) THEN
         			NULL
         		WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NOT NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) THEN
         			'Relance Nø 1 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1,103)
         		WHEN    (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NOT NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NULL) THEN
         			'Relance Nø 2 du '+ CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2,103)
         		WHEN	 (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_1 IS NOT NULL)
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_2 IS NOT NULL) 
         		AND (ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3 IS NOT NULL) THEN
         			'Relance Nø 3 du ' + CONVERT(VARCHAR(10),ARRIVEE_PIECE_PRO.DAT_RELANCE_REGLE_3,103)
         		END AS LIB_RELANCE_REGLE,
         		COD_PIECE_PRO,
         		BLN_BLOQUANT_ENGAGEMENT,
         		BLN_BLOQUANT_REGLEMENT,
         		REPERTOIRE,
         		CASE 
         			WHEN MODULE_PRO.ID_MODULE_PRO IS NOT NULL AND @BLN_SESSION = 0 THEN 
         			(SELECT MODPRO2.COD_MODULE_PRO + ' - ' + TYPE_FORMATION.LIBC_TYPE_FORMATION
         				 FROM MODULE_PRO AS MODPRO2
         					LEFT JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
         				 WHERE ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO)
         			ELSE null
         		END as INFORMATION,
         		CASE 
         			WHEN PIECE_PRO.BLN_SESSION = 1 THEN 'Session'
         			WHEN PIECE_PRO.BLN_MODULE = 1 THEN 'Module'
         			WHEN PIECE_PRO.BLN_CONTRAT = 1 THEN 'Contrat'
         		ELSE NULL
         		END as TYPE_PIECE,
         		(SELECT COD_CONTRAT_PRO FROM CONTRAT_PRO WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO) AS COD_CONTRAT_PRO,
         		MODULE_PRO.COD_MODULE_PRO,
         		SESSION_PRO.COD_SESSION_PRO,
         		(SELECT DAT_CREATION FROM CONTRAT_PRO WHERE ID_CONTRAT_PRO = @ID_CONTRAT_PRO) AS DAT_CREATION,
         		
         		PIECE_PRO.BLN_AUTRE AS BLN_AUTRES,
         		coalesce(ARRIVEE_PIECE_PRO.NUM_FILE,0) as NUM_FILE,
         		-- /LDE 19/06/2013 #15282
         		ARRIVEE_PIECE_PRO.ID_UTILISATEUR,
         		ARRIVEE_PIECE_PRO.NOM_FICHIER 
         		INTO #TEMP_ARRIVEE_PIECES_PRO
         	 FROM PIECE_PRO
         
         	 LEFT JOIN SESSION_PRO ON 
         	 @BLN_SESSION = 1
         	 AND SESSION_PRO.ID_SESSION_PRO =	CASE
         											WHEN @BLN_SESSION = 1 THEN @ID
         											ELSE NULL
         										END
         	 AND PIECE_PRO.BLN_SESSION = @BLN_SESSION
         
         	 LEFT JOIN MODULE_PRO ON 
         	 (@BLN_MODULE = 1 AND @BLN_CONTRAT = 1 AND MODULE_PRO.ID_MODULE_PRO IN (SELECT ID_MODULE_PRO FROM MODULE_PRO WHERE (ID_CONTRAT_PRO = @ID AND @BLN_CONTRAT = 1))
         	 OR @BLN_MODULE = 1 AND @BLN_CONTRAT = 0 AND MODULE_PRO.ID_MODULE_PRO = @ID
         	 OR @BLN_SESSION = 1 AND MODULE_PRO.ID_MODULE_PRO = SESSION_PRO.ID_MODULE_PRO)
         	 AND PIECE_PRO.BLN_MODULE = @BLN_MODULE
         
         	 LEFT JOIN CONTRAT_PRO ON 
         	 CONTRAT_PRO.ID_CONTRAT_PRO = 
          		CASE
          			WHEN PIECE_PRO.BLN_CONTRAT = 1 THEN @ID
          			WHEN PIECE_PRO.BLN_MODULE = 1 OR PIECE_PRO.BLN_SESSION = 1 THEN MODULE_PRO.ID_CONTRAT_PRO
          		END
         	 AND PIECE_PRO.BLN_CONTRAT = @BLN_CONTRAT
         	 LEFT JOIN ARRIVEE_PIECE_PRO ON ARRIVEE_PIECE_PRO.ID_PIECE_PRO = PIECE_PRO.ID_PIECE_PRO 
         	 AND (ARRIVEE_PIECE_PRO.ID_CONTRAT_PRO = CONTRAT_PRO.ID_CONTRAT_PRO AND @BLN_CONTRAT = 1
         		OR ARRIVEE_PIECE_PRO.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO AND @BLN_MODULE = 1
         		OR ARRIVEE_PIECE_PRO.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND @BLN_SESSION = 1)
         
         	WHERE (@BLN_MODULE = 1 AND PIECE_PRO.BLN_MODULE = @BLN_MODULE
         		OR @BLN_SESSION = 1 AND PIECE_PRO.BLN_SESSION = @BLN_SESSION
         		OR @BLN_CONTRAT = 1 AND PIECE_PRO.BLN_CONTRAT = @BLN_CONTRAT)
         		AND PIECE_PRO.BLN_ACTIF = @BLN_ACTIF
         
         	ORDER BY ID_MODULE_PRO, TYPE_PIECE, LIBL_PIECE_PRO
         
         	SELECT *
         	FROM #TEMP_ARRIVEE_PIECES_PRO	
         
         	END  -- @id is not null
         
         	*/
         
         END
         
GO

         CREATE PROCEDURE [dbo].[DEL_REGLEMENT_PRO_ANNULATION]
         
         AS
         BEGIN
         SET NOCOUNT ON
         
         	SELECT ID_REGLEMENT_PRO INTO #REGLEMENT_PRO FROM REGLEMENT_PRO WHERE BLN_ACTIF = 2
         
         	UPDATE SESSION_PRO
         	SET ID_REGLEMENT_PRO_ADH = NULL,
         		ID_REGLEMENT_PRO_OF = NULL
         	WHERE 
         			(ID_REGLEMENT_PRO_ADH IN (SELECT ID_REGLEMENT_PRO FROM REGLEMENT_PRO WHERE BLN_ACTIF = 2))
         		AND (ID_REGLEMENT_PRO_OF IN (SELECT ID_REGLEMENT_PRO FROM REGLEMENT_PRO WHERE BLN_ACTIF = 2))
         	DELETE FROM REGLEMENT_PRO 
         	WHERE 
         		BLN_ACTIF > 1  
         END
         
GO

         -- ============================================= 
         -- Author:		MBL
         -- Create date: 20/12/2013
         -- Description:	
         --  1 - Affectation des Actions importees via EDI a une agence, un conseiller et un AGF
         --		REGLES D''AFFECTATION :
         --  2 - Envoi a chaque AGF concern‚, la liste des modules importes
         -- ============================================= 

         CREATE PROCEDURE [dbo].[EDI_PEC_AFFECTION_ACTION]
         	@ID_LOT_IMPORT			INT,
         	@ID_EDI_GROUPE_EDI_PEC	INT	
         AS
         BEGIN
         
         	SET NOCOUNT ON
         
         	SELECT 	ID_LOT_IMPORT			 = @ID_LOT_IMPORT			,	ID_EDI_GROUPE_EDI_PEC	 = @ID_EDI_GROUPE_EDI_PEC	
         
         	if exists (select 1 from sys.objects where type = 'U' and name = 'TMP01_EDI')
         	BEGIN
         		DROP TABLE TMP01_EDI
         	END
         
         	CREATE TABLE TMP01_EDI
         	(
         		ID_ACTION_PEC		int, 
         		COD_ACTION_PEC		int,
         		ID_MODULE_PEC		int,
         		ID_AGENCE			int,
         		ID_CONSEILLER		int,
         		ID_AGF				int
         	)
         
         
         	DECLARE @ID_ACTION_PEC			int, 
         			@ID_MODULE_PEC			int, 
         			@COD_ACTION_PEC			int, 
         			@ID_ETABLISSEMENT		int, 
         			@NB_INDIVIDU			int,		
         			@ID_AGENCE				int,
         			@ID_CONSEILLER			int, 
         			@ID_AGF					int, 
         			@AXE_MODULE				varchar(30),
         			@DOMAINE_MODULE			varchar(30),
         			@BLN_MODULE_MUTUALISE	tinyint
         			
         
         	/* VALORISATION DE L'AGENCE ET DU CONSEILLER ET DETERMINATION DE L'AGF ASSOCIE AU MODULE IMPORTE */
         	DECLARE cu_action_pec_edi CURSOR FOR
         	SELECT DISTINCT ID_ACTION_PEC, ID_MODULE_PEC
         	FROM EDI_PEC_ST
         	WHERE ID_LOT_IMPORT = @ID_LOT_IMPORT
         	AND BLN_REJET = 0
         	ORDER BY 1 , 2
         
         
         	OPEN cu_action_pec_edi 
         	FETCH cu_action_pec_edi INTO @ID_ACTION_PEC, @ID_MODULE_PEC
         
         	WHILE (@@FETCH_STATUS <> -1)
         	BEGIN
         		
         		
         		SELECT 	@ID_AGENCE				= NULL,
         				@ID_CONSEILLER			= NULL, 
         				@ID_AGF					= NULL,
         				@BLN_MODULE_MUTUALISE	= 0
         		
         		SELECT	@AXE_MODULE		= ISNULL(AXE_MODULE, ''), 
         				@DOMAINE_MODULE = ISNULL(DOMAINE_MODULE, '')
         		FROM MODULE_PEC 
         		WHERE ID_MODULE_PEC		= @ID_MODULE_PEC
         
         
         		IF LEN(@AXE_MODULE) > 0 OR LEN(@DOMAINE_MODULE) > 0
         		BEGIN
         			SELECT 	@ID_AGENCE			= ID_AGENCE,
         					@ID_CONSEILLER		= ID_CONSEILLER, 
         					@ID_AGF				= ID_AGF,
         					@BLN_MODULE_MUTUALISE = 1
         			FROM [EDI_GROUPE_EDI_PEC_PARAM_AFFECTATION]
         			WHERE	ID_EDI_GROUPE_EDI_PEC	= @ID_EDI_GROUPE_EDI_PEC
         			AND		AXE_MODULE				= @AXE_MODULE
         			AND		DOMAINE_MODULE			= @DOMAINE_MODULE
         						
         		END
         		
         		IF @BLN_MODULE_MUTUALISE = 0
         		BEGIN 
         			SELECT TOP 1 @ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT, @NB_INDIVIDU = COUNT(DISTINCT STAGIAIRE_PEC .ID_INDIVIDU)
         			FROM action_pec 
         			INNER JOIN MODULE_PEC		ON action_pec .ID_ACTION_PEC = MODULE_PEC .id_action_pec
         			INNER JOIN NR140			ON action_pec .ID_ACTION_PEC = NR140 .id_action_pec
         			INNER JOIN STAGIAIRE_PEC	ON STAGIAIRE_PEC .ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         													AND STAGIAIRE_PEC .ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			WHERE ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC 
         			GROUP BY ACTION_PEC.ID_ACTION_PEC, NR140.ID_ETABLISSEMENT
         			ORDER BY 2 DESC, 1
         			
         
         			SELECT
         					@ID_AGF			= ID_CHARGEE_RELATION, 
         					@ID_CONSEILLER	= ID_CHARGEE_MISSION, 
         					@ID_AGENCE		= ID_AGENCE
         			FROM	ETABLISSEMENT		
         			WHERE	ID_ETABLISSEMENT = @ID_ETABLISSEMENT 
         			
         			
         		END
         				
         		SELECT TOP 1 @COD_ACTION_PEC = COD_ACTION_PEC
         		FROM action_pec 
         		WHERE ID_ACTION_PEC = @ID_ACTION_PEC
         				
         		
         		INSERT INTO TMP01_EDI		(	ID_ACTION_PEC,	COD_ACTION_PEC,		ID_MODULE_PEC,	ID_AGF,		ID_CONSEILLER,	ID_AGENCE )
         		SELECT							@ID_ACTION_PEC, @COD_ACTION_PEC,	@ID_MODULE_PEC, @ID_AGF,	@ID_CONSEILLER, @ID_AGENCE
         
         
         		UPDATE ACTION_PEC 
         		SET ID_CHARGEE_MISSION	= @ID_CONSEILLER	,
         			ID_AGENCE			= @ID_AGENCE
         		FROM ACTION_PEC 
         		WHERE ID_ACTION_PEC = @ID_ACTION_PEC
         
         		
         		FETCH cu_action_pec_edi INTO @ID_ACTION_PEC, @ID_MODULE_PEC
         	END
         
         	CLOSE cu_action_pec_edi 
         	DEALLOCATE cu_action_pec_edi 
         	/* FIN VALORISATION DE L'AGENCE ET DU CONSEILLER ET DETERMINATION DE L'AGF ASSOCIE AU MODULE IMPORTE */
         
         
         	SELECT	ID_ACTION_PEC,  
         			COD_ACTION_PEC,
         			ID_MODULE_PEC,  
         			ID_AGF			= AGF.ID_UTILISATEUR, 
         			NOM_AGF			= AGF.LIB_NOM, 
         			ID_CONSEILLER	= CONS.ID_UTILISATEUR, 
         			NOM_CONSEILLER	= CONS.LIB_NOM, 
         			NOM_AGENCE		= AGENCE.LIBL_AGENCE,
         			ID_AGENCE		= AGENCE.ID_AGENCE
         	FROM TMP01_EDI
         	INNER JOIN UTILISATEUR AGF		ON AGF.ID_UTILISATEUR	= TMP01_EDI.ID_AGF
         	INNER JOIN UTILISATEUR CONS		ON CONS.ID_UTILISATEUR	= TMP01_EDI.ID_CONSEILLER
         	INNER JOIN AGENCE				ON AGENCE.ID_AGENCE		= TMP01_EDI.ID_AGENCE
         	ORDER BY AGF.ID_UTILISATEUR
         
         
         
         
         /* ENVOI MAIL A CHAQUE AGF associe aux MODULES IMPORTES */
         
         	DECLARE @Actif					TINYINT,
         			@Id_Profil				INT,
         			@Recipients				VARCHAR(1000),
         			@NewCopyRecipients		VARCHAR(1000),
         			@Recipients_Agence		VARCHAR(1000),
         			@Copy_Recipients_Dest	VARCHAR(1000),
         			@CopyActif				TINYINT,
         			@CopyId_Profil			INT,
         			@Id_Copy_Utilisateur	INT,
         			@COD_MODULE_PEC			VARCHAR(20),
         			@Comp_Agence			VARCHAR(100),
         			@LIBL_MODULE_PEC		VARCHAR(100),
         			@NUM_INTERNE_MODULE_PEC	VARCHAR(50),
         			@DAT_DEBUT				VARCHAR(10),
         			@DAT_FIN				VARCHAR(10),
         			@MNT_DEMANDE			DECIMAL(15,2),
         			@NB_STAGIAIRE			INTEGER,
         			@NB_ETABLISSEMENT		INTEGER,
         			@LIB_ADH				VARCHAR(500)
         
         	DECLARE	@Subject				VARCHAR(255),
         			@Body					VARCHAR(MAX),
         			@Body_Deb				VARCHAR(MAX),
         			@Body_Action			VARCHAR(MAX),
         			@Body_Fin				VARCHAR(MAX),
         			@Bln_Debug				TINYINT
         
         	DECLARE @nom_agf varchar(35), @prenom_agf varchar(35), @mail_agf VARCHAR(1000)
         	DECLARE @nom_CONSEILLER varchar(35), @prenom_CONSEILLER varchar(35), @mail_CONSEILLER VARCHAR(1000)
         
         
         	SET @Bln_Debug = 1
         											
         
         	DECLARE cu_agf_edi SCROLL CURSOR FOR
         	SELECT DISTINCT ID_AGF, ID_CONSEILLER
         	FROM TMP01_EDI
         	OPEN cu_agf_edi 
         	FETCH cu_agf_edi INTO @ID_AGF, @ID_CONSEILLER
         	
         	WHILE @@FETCH_STATUS <> -1 
         	BEGIN
         		SET @Body_Action			=''
         
         		SELECT	@mail_agf = UTILISATEUR.EMAIL, 
         				@nom_agf = COALESCE(UTILISATEUR.LIB_NOM, ''''), 
         				@prenom_agf = COALESCE(UTILISATEUR.LIB_PNM, '''') 
         				--,	@Actif = UTILISATEUR.BLN_ACTIF, 
         				--@Id_Profil = UTILISATEUR.ID_PROFIL, 
         				--@Id_Agence = UTILISATEUR.ID_AGENCE, 
         				--@Recipients_Agence = AGENCE.EMAIL
         		FROM	UTILISATEUR 
         		WHERE	UTILISATEUR.ID_UTILISATEUR = @ID_AGF
         
         
         		SELECT	@mail_CONSEILLER	= UTILISATEUR.EMAIL, 
         				@nom_CONSEILLER		= COALESCE(UTILISATEUR.LIB_NOM, ''''), 
         				@prenom_CONSEILLER  = COALESCE(UTILISATEUR.LIB_PNM, '''') 
         		FROM	UTILISATEUR 
         		WHERE	UTILISATEUR.ID_UTILISATEUR = @ID_CONSEILLER
         
         		SELECT @Recipients = @mail_agf
         		SELECT @Copy_Recipients_Dest = @mail_CONSEILLER + ';admin_defi@opcadefi.fr;'
         
         
         		SELECT @Subject = 'DPC EDI '
         		SELECT @Body_Deb = '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN">'
         		+'<html><head><meta http-equiv = "content-type" content = "text/html; charset = utf-8">'
         		+ '<title>email</title>'
         		+'</head><body>'			
         			+ '<table width= "100%" cellpadding = "0" cellspacing = "0">'
         				+'<tr>'
         					+ '<td valign = "top">'
         						+'<table width= "100%" bgcolor = "#0070c0">'
         							+'<tr> '
         								+'<td align = "left"> <font face = "arial" size = "3" color = "white">'
         									+'<b>NOUVELLES DPC EDI</b></font>'
         								+'</td>'
         							+'</tr>'
         						+'</table>'
         					+'</td>'
         				+'</tr>'
         				+'<tr height = "15">'
         					+'<td>'
         					+'</td>'
         				+'</tr>'
         				+ '<tr>'
         					+'<td>' 
         						+ 'AGF : ' + @nom_agf + ' ' + @prenom_agf  + ' (' + @Recipients  + ')'
         					+'</td>'
         				+'</tr>'
         				+ '<tr>'
         					+'<td>' 
         						+ 'CONSEILLER : ' +  @nom_CONSEILLER + ' ' + @prenom_CONSEILLER  + ' (' + @Copy_Recipients_Dest  + ')'
         					+'</td>'
         				+'</tr>'
         				+'<tr height = "50">'
         					+'<td>'
         					+'</td>'
         				+'</tr>'
         				+ '<tr>'
         					+'<td>' 
         						+ 'Des nouvelles demandes de prise en charge viennent d''etre creees dans OPTIFORM suite a un import EDI concernant les modules PEC suivants : '
         					+'</td>'
         				+'</tr>'
         				+'<tr height = "15">'
         					+'<td>'
         					+'</td>'
         				+'</tr>'
         				+'<tr>'
         					+'<td valign = "top">'
         						+'<table width= "100%" cellpadding = "0" cellspacing = "0">'
         							+'<tr> '
         							+	'<td align = "left" bgcolor = "#f2f2f2">'
         									+'<table cellpadding = "8" cellspacing = "0" width= "100%" border="2" bordercolor="blue" >'
         										+ '<font face = "arial" size = "1" color = "black" >'									
         											+ '<tr>'
         												+'<td width = 100><b>Code Module</b></td>'
         												+'<td width = 300><b>Libelle Module</b></td>'
         												+'<td width = 100><b>Dates Module</b></td>'
         												+'<td width = 200><b>Adh‚rent</b></td>'
         												+'<td width = 100><b>Montants Pr‚visionnels</b></td>'
         												+'<td width = 100><b>Nombre Stagiaires</b></td>'
         												--+'<td width = 100><b>Nø interne module</b></td>'
         											+'</tr>'
         
         
         		SELECT 	@Body_Fin =										
         										'</font>'
         									+'</table>'
         								+'</td>'
         							+'</tr>'
         						+'</table>'
         					+'</td>'
         				+'</tr>'
         			+'</table>'
         		+ '</body></html>' ;			
         		
         		DECLARE cu_module_utilisateur SCROLL CURSOR FOR
         		SELECT	DISTINCT ID_MODULE_PEC
         		FROM	TMP01_EDI
         		WHERE	ID_AGF = @ID_AGF
         		OPEN cu_module_utilisateur 	
         		
         		FETCH cu_module_utilisateur INTO @Id_Module_PEC		
         		WHILE @@FETCH_STATUS <> -1 
         		BEGIN
         			SELECT		@COD_MODULE_PEC			= MODULE_PEC.COD_MODULE_PEC,
         						@LIBL_MODULE_PEC		= MODULE_PEC.LIBL_MODULE_PEC,
         						@NUM_INTERNE_MODULE_PEC = MODULE_PEC.NUM_INTERNE,
         						@DAT_DEBUT				= CONVERT(VARCHAR(10), MODULE_PEC.DAT_DEBUT, 103),
         						@DAT_FIN				= CONVERT(VARCHAR(10), MODULE_PEC.DAT_FIN, 103)
         			FROM		MODULE_PEC
         			INNER JOIN	ACTION_PEC				ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         			WHERE		ID_MODULE_PEC = @Id_Module_PEC
         			
         			
         			SELECT	@MNT_DEMANDE = SUM(POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT)
         			FROM	POSTE_COUT_ENGAGE
         			WHERE	ID_MODULE_PEC = @Id_Module_PEC
         			
         			SELECT @MNT_DEMANDE = ISNULL(@MNT_DEMANDE ,0)
         
         			SELECT @NB_STAGIAIRE  = COUNT(DISTINCT ID_STAGIAIRE_PEC)
         			FROM	STAGIAIRE_PEC
         			WHERE	ID_MODULE_PEC = @Id_Module_PEC
         			AND		ID_SESSION_PEC IS NULL
         			
         			SELECT @NB_STAGIAIRE  = ISNULL(@NB_STAGIAIRE, 0)
         			
         			SELECT @NB_ETABLISSEMENT = COUNT (DISTINCT ID_ETABLISSEMENT), @ID_ETABLISSEMENT = MAX(ID_ETABLISSEMENT)
         			FROM		NR140
         			INNER JOIN	ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			INNER JOIN	MODULE_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         			WHERE MODULE_PEC .ID_MODULE_PEC = @Id_Module_PEC
         			
         			IF @NB_ETABLISSEMENT  = 1
         			BEGIN
         				SELECT @LIB_ADH =	'SIRET '  + ETABLISSEMENT.NUM_SIRET 
         									+ '<br/>Adh‚rent ' +  CAST (ADHERENT.ID_ADHERENT AS VARCHAR) + ' '+ ADHERENT.LIB_RAISON_SOCIALE
         				FROM		ETABLISSEMENT
         				INNER JOIN	ADHERENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         				WHERE ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         				
         			END
         			ELSE
         			BEGIN
         				SET @LIB_ADH = 'Action Collective'
         			END
         			SELECT 	@Body_Action =	@Body_Action +									
         											 '<tr>'
         												+'<td>' + '<b>'+ @COD_MODULE_PEC +'</b>' +'</td>'
         												+'<td>' + REPLACE(@LIBL_MODULE_PEC, '''', '''''') +'</td>'
         												+'<td>' + 'du '+@DAT_DEBUT+' au ' + @DAT_FIN +'</td>'
         												+'<td width>'+@LIB_ADH+'</td>'
         												+'<td align ="right">' +CAST(@MNT_DEMANDE AS VARCHAR) + ' ?'+'</td>'
         												+'<td align ="right">' +CAST(@NB_STAGIAIRE AS VARCHAR)+'</td>'
         												--+'<td>' +@NUM_INTERNE_MODULE_PEC+'</td>'
         											+'</tr>'
         											
         			FETCH cu_module_utilisateur INTO @Id_Module_PEC
         		END
         
         		SET @Body	= @Body_Deb	 +@Body_Action +  @Body_Fin
         		
         		IF ( @Bln_Debug = 1 )
         		BEGIN
         			-- Test en recette
         			SELECT @Recipients = 'miguel.blanco@sisyphe-tech.com'
         			SELECT @Copy_Recipients_Dest = 'miguel.blanco@sisyphe-tech.com'
         		END
         					
         		EXEC msdb.dbo.sp_send_dbmail	@profile_name	 = 'Administrateur',
         										@recipients		 = @Recipients,--'b.blanchard@opcadefi.fr', --@Recipients, -- a changer avec recipients
         										@Copy_Recipients = @Copy_Recipients_Dest,					--@Copy_Recipients_Dest,	-- a changer avec @Copy_Recipients_Dest
         										@subject		 = @subject,
         										@Body			 = @Body,
         										@Body_format	 = 'HTML'		
         												
         		CLOSE cu_module_utilisateur 
         		DEALLOCATE cu_module_utilisateur 		
         			
         		FETCH cu_agf_edi INTO @ID_AGF, @ID_CONSEILLER
         	END
         	
         	CLOSE cu_agf_edi 
         	DEALLOCATE cu_agf_edi 
         
         END
GO

