         CREATE PROCEDURE [dbo].[UPD_MODULE_DATE_REJET_LETTRE_OF]
         	@IDS_MODULE_PEC varchar(500)	-- List of ID_MODULE separated with ',' without spaces - i.e.: 1,2,3,4,5,6
         AS
         
         BEGIN
         
         	DECLARE @Item int;
         	-- Create a temporary table which contains IDs
         	CREATE TABLE #List(Item int)
         	
         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,1,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)-1))),
         			@IDS_MODULE_PEC=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)+1,LEN(@IDS_MODULE_PEC))))
         
         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END
         
         	IF LEN(@IDS_MODULE_PEC) > 0
         		INSERT INTO #List SELECT @IDS_MODULE_PEC -- Put the last item in
         
         
         	--Mise … jour des dates de rejet
         	UPDATE MODULE_PEC
         	SET DAT_LETTRE_REJET_OF = GETDATE()
         	WHERE ID_MODULE_PEC IN (SELECT Item FROM #List)
         
         END
         
GO
-- =============================================
         -- Author				: KW
         -- Create date			: 28 septembre 2007
         -- Description			: Gestion des transactions pour un ‚tablissement of
         -- =============================================
         -- MAJ MB du 30/10/2007 : Refonte complŠte de la proc‚dure stock‚e
         -- Modification des regles de gestion non repecteees !!
         -- =============================================
         -- Author				: RMA & ASD
         -- Create date			: 05/02/2009
         -- Description			: 0011521: MHBM DA : OF extension d'IBan mˆme si pas cocher (vu en recette et en prod) 
         -- =============================================
         -- DSZ 17/04/2012 
         -- dans 13265 EOU a ajout‚ des parametres … INS_TRANSACTION
         -- =============================================
         -- SLAH 06/06/2012 
         -- dans 13531 Script transactions Toutes Toutes 
         -- =============================================
         -- DSZ 05/07/2012 13658 id_mode_envoi_doc ne peut pas etre 0
         -- =============================================
         -- DSZ 02/08/2012 13803 il faut fixer le type de transaction … null. 
         -- =============================================
         -- DSZ 07/09/2012 13824 cr‚ation de la transaction toutes/toutes supprim‚. toutes/reglement laiss‚
         -- =============================================
         -- TLE 13/07/2013 : 15143 : Modification taille NUM_IBAN (de 27 … 34)
         -- ====================================================
         -- HBO - 141113 - M16371: Lot 1 - Modification structure de donn‚es / proc‚dures stock‚es
         -- =============================================
         CREATE PROCEDURE UPD_GESTION_TRANSACTION_ETABLISSEMENT_OF
         				@ID_OF INT,
         				@ID_ETABLISSEMENT_OF INT,
         				@ID_ADRESSE INT,
         				@ID_UTILISATEUR INT,
         				@BLN_PRINCIPAL TINYINT,
         				@NUM_IBAN VARCHAR(34),
         				@BIC VARCHAR(11)
         AS
         
         	DECLARE @ID_TYPE_TRANSACTION INT
         	DECLARE @ID_SOUS_TYPE_TRANSACTION INT,
         			@ID_ETABLISSEMENT_OF_BENEF INT,
         			@ID_ADRESSE_BENEF INT,
         			@ID_CONTACT_BENEF INT,
         			@NUM_IBAN_BENEF VARCHAR(34)
         
         
         	--R‚cup‚ration de l'identifiant du sous type transaction RŠglement
         	SELECT @ID_SOUS_TYPE_TRANSACTION = SOUS_TYPE_TRANSACTION.ID_SOUS_TYPE_TRANSACTION
         	FROM   SOUS_TYPE_TRANSACTION
         	WHERE  SOUS_TYPE_TRANSACTION.COD_SOUS_TYPE_TRANSACTION = 'REGLEMT'
         	
         -- Creation de la transaction Toutes, RŠglement , Toutes si elle n'existe pas
         	IF NOT EXISTS ( select * from  [TRANSACTION] 
         				where		 [TRANSACTION].ID_ETABLISSEMENT_OF_DEST = @ID_ETABLISSEMENT_OF 
         						AND  [TRANSACTION].ID_TYPE_TRANSACTION IS NULL
         						AND  [TRANSACTION].ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION
         						AND  [TRANSACTION].ID_ACTIVITE IS NULL
         						AND [TRANSACTION].BLN_ACTIF = 1
         						AND [TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 1) 
         	BEGIN
         
         
         
         		--R‚cup‚ration des infos de l'‚tablissement
         		SELECT 
         			@ID_ETABLISSEMENT_OF_BENEF =ID_ETABLISSEMENT_OF,
         			@ID_ADRESSE_BENEF =ID_ADRESSE_PRINCIPALE, 
         			@ID_CONTACT_BENEF = NULL,
         			@NUM_IBAN_BENEF =NUM_IBAN
         		FROM ETABLISSEMENT_OF
         		WHERE ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF
         
         
         		IF LTRIM(@NUM_IBAN_BENEF) = '' SET @NUM_IBAN_BENEF = NULL
         		DECLARE @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE TINYINT
         		SET @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = 0
         		IF(@ID_ETABLISSEMENT_OF=@ID_ETABLISSEMENT_OF_BENEF)
         		BEGIN
         			SET @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = 1
         		END
         		
         			EXEC INS_TRANSACTION
         				@ID_ETABLISSEMENT_DEST = NULL, --  int
         				@ID_ETABLISSEMENT_OF_DEST = @ID_ETABLISSEMENT_OF, --  int
         				@ID_ETABLISSEMENT_BENEF = NULL, --  int
         				@ID_ETABLISSEMENT_OF_BENEF = @ID_ETABLISSEMENT_OF_BENEF, --  int
         				@ID_TIERS_BENEF = NULL, --  int
         				@ID_ADRESSE = @ID_ADRESSE_BENEF, --  int
         				@ID_CONTACT = @ID_CONTACT_BENEF, --  int
         				@ID_TYPE_TRANSACTION = null,
         				@ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION, --  int
         				@ID_ACTIVITE = NULL, --  int
         				@BLN_ACTIF = 1, --  tinyint
         				@ID_MODE_ENVOI_DOC = 1, --  int
         				@NUM_IBAN = @NUM_IBAN_BENEF, --  varchar(34)
         				@ID_UTILISATEUR = @ID_UTILISATEUR, --  int
         				@BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 1, --  tinyint
         				@BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE, --  tinyint
         				@LIBL_TRANSACTION = 'Cr‚‚e avec l''OF',
         				@BIC = @BIC
         
         		UPDATE ETABLISSEMENT_OF 
         		SET NUM_IBAN = @NUM_IBAN_BENEF
         		WHERE ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF
         		
         	END
         
         
         SELECT * FROM TYPE_TRANSACTION
GO

CREATE PROCEDURE [dbo].[UPD_PIECES_REGLEMENT_NON_CONFORM]  
	@ID_MOTIF int,
	@ID_ARRIVEE_PIECE int,
	@BLN_ACTIF int
AS  

BEGIN
	DECLARE @EXIST int
         
         	SELECT @EXIST = COUNT (*)
         	FROM NR210
         	WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         	AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE
         
         	IF @EXIST <> 0
         	BEGIN
         		IF @BLN_ACTIF = 0
         		BEGIN
         			DELETE NR210
         			WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         				AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE
         		END
         	END
         	ELSE
         	BEGIN
         		IF @BLN_ACTIF = 1
         			INSERT INTO NR210
         				(ID_MOTIF_NON_CONFORM_PIECE, ID_ARRIVEE_PIECE_PEC)
         			VALUES
         				(@ID_MOTIF, @ID_ARRIVEE_PIECE)
         	END
         
         END
GO
 CREATE PROCEDURE [dbo].[LEC_GRP_IMPUTATION_PAR_ACTIVITE_EDITION]  
          @ID_ADHERENT    AS INT,  
          @ID_PERIODE     AS INT,  
          @ID_POSTE_VERSEMENT   AS INT,  
          @ID_TYPE_VERSEMENT   AS INT,  
          @ID_TYPE_ASSUJETISSEMENT AS INT,  
          @MASSE_SALARIALE   AS DECIMAL(18,2) = 0,  
          @MASSE_SALARIALE_CDD   AS DECIMAL(18,2) = 0, 
          @DATE      as datetime,  
          @ID_GROUPE_DE_ETABLISSEMENT as INT,  
          @ID_ETABLISSEMENT_VERSEUR AS INT    
         AS  
         -- modification pr‚cdente : 20 f‚vrier 2007 SAY --  
         -- modification : 16 mars 2007 SAY -- tri : plan puis les autres  
         -- MODIFICATION : 11/09/2009 SAFI  Evol 399  
         -- Modification : Ajouter une Parameter IDGroupe de l'Etablissement 12/10/2009 Anno ID 121799  
         -- Modification : Get the periode of the versement not the year civil, 15/10/2009 Anno ID 121799  
         -- =========================================================================  
         -- Modification : SAFI 20/01/2010 MODIFIER  
         -- 12285: Reforme professionnelle : FPSPP  
          -- R‚forme professionnelle : Ajouter 2 colonnes suivent   
          -- Dont d‚j… r‚gl‚ FPSPP (entre la colonne D‚j… r‚gl‚ et D‚duction)  
          -- Dont r‚gl‚ FPSPP (entre la colonne R‚gl‚ et TVA)  
         -- =========================================================================  
         -- Modification : SAFI 01/04/2010 MODIFIER  
         -- 12337: - La branche utilis‚e pour le calcul du FPSPP n'est pas correcte  
          -- La branche utilis‚e pour le calcul du FPSPP doit etre celle de l'etablissement et pas celle de l'adherent   
          -- Ajouter @ID_ETABLISSEMENT_VERSEUR  
         -- =========================================================================  
         -- Modification : SAFI 05/05/2010 MODIFIER  
         -- 0012343: There is a problem in getting the details of Imputation When the type_versement   
         -- passed on parameter other than 3 or 4, because of the table PARAMETRE_APPEL dont have any other type versement then 3 or 4.  
         -- Correction: if the type versement passed other than 3 or 4,   
         -- then the type versement is got from GRP_TYPE_VERSEMENT from table TYPE_VERSEMENT.  
         -- =========================================================================  
         -- Modification : SAFI 08/06/2010 MODIFIER : 12401  
         -- Modification on existing control :  
         -- Control Actual : Non lignes created if the Groupe of the Etab.   
         --     dont have any options or the option 'PAS DE OPTION',   
         --     So, if the accuranecs are found those lignes   
         --     where deleted from the actual select.  
         -- Correction   : Inorder to display the other type of Versements like   
         --     Versement Regul and Reversement, the contidion is altered.  
         --     So, if the passed parameter @ID_TYPE_VERSEMENT has BLN_VERSEMENT_INITIAL <> 1 then   
         --     those lignes were not deleted.  
         -- =========================================================================  
         -- Modification : DSZ 17/10/2011 EVOL 10-50 12911  
         -- =========================================================================  
         -- Modification : DSZ 10/11/11 12979   
         -- modif selon la SFD vu avec ASD. Supprime la modif precedente !  
         -- "On ne cr‚e pas les occurrences dans la table POSTE_IMPUTATION pour les activit‚s autres que   
         -- ID_ ACTIVITE = 3 ou 2 " (Avant: que 3)  
         -- =========================================================================  
         -- Modification : DSZ 03/01/2012 13104  
         -- L'adh‚rent ne doit r‚gler le FPSPP qu'une seule fois ind‚pendamment de l'activit‚ plan.  
         -- =========================================================================  
         -- Modification : DSZ 04/01/2012 13103   
         -- si  @ID_POSTE_VERSEMENT not null, on affiche les donnees existantes; on ne se base pas sur R19 pour l'activite  
         -- ATTENTION : REFECTION TOTALE !!!!!  
         -- =========================================================================  
         -- Modification : ASD 30/01/2013 14767  
         -- Gestion AGPP via l'ajout de la table TYPE_ACTIVITE  
         -- =========================================================================  
         -- Modification : LDE 31/01/2013 #14767  
         -- Gestion de la modification de NUM_ORDRE dans la table ACTIVITE  
         -- et du poste imputation AGPP uniquement en VO (comment‚ pour le moment)  
         -- =========================================================================  
         -- Modification : ASD 01/02/2013 14767  
         -- =========================================================================  
         -- DSZ 18/03/2013 15029 : permettre l'affichage de la ligne plan de formation mˆme si elle porte sur un agr‚ment diff‚rent de celui de l'adh‚rent pour la p‚riode consid‚r‚e.  
         -- =========================================================================  
         -- LDE 25/03/2013 15030 : SBR - suppression du type FLOAT et REAL dans le SQL : 1- REAL  
         -- =========================================================================  
         -- DSZ 27/03/2103 15029 : ajustement de la logique, ajout de la colonne BLN_ACTIVITE_PLAN_DIFFERENT  
         -- =========================================================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT  
         -- =========================================================================  
         -- DSZ 02/07/2013 15368 : afficher la ligne plan mˆme si pas d'option, si on est en modif et la ligne plan existe  
         -- =========================================================================  
         -- DSZ 25/07/2013 16177 : tau_tva a besoin de 5 chiffres decimals  
         -- =========================================================================  
         -- MBL 30/09/2014 : Adaptation PS suite a Reforme et introduction nouvelles activites
         -- =========================================================================    
         -- DSZ 03/11/2014 : #617 nettoyage et simplification
         -- =========================================================================    
         -- DSZ 04/11/2015 : #1190 dynamisation de la masse salariale
         -- =========================================================================    
         -- DSZ 24/11/2015 : #1230 le code a ‚t‚ sorti dans GET_ACTIVITES_ADHERENT
         -- =========================================================================    
         -- DSZ 08/12/2015 : #1243 ajout ActivityType
         -- =========================================================================    
         -- OPA/AME 22/12/2015 : 1262 
         -- =========================================================================
         BEGIN  
          -- Force le type de versement … ˆtre de type initial (VOLON. ou OBLIG.)   
          -- s'il ne l'est pas … l'origine, mais de mˆme groupe de type (Oblig ou volont)  
          -- Ecrase donc la valeur @ID_TYPE_VERSEMENT pass‚e en paramŠtres dans ce cas.  
          -- On est oblig‚ … faire comme ‡a car ID_TYPE_VERSEMENT (initial) est utilis‚ pour param_appel
         
          SELECT @ID_TYPE_VERSEMENT = INI.ID_TYPE_VERSEMENT   
           FROM TYPE_VERSEMENT 
           inner join TYPE_VERSEMENT INI on 
          (INI.GRP_TYPE_VERSEMENT = TYPE_VERSEMENT.GRP_TYPE_VERSEMENT AND ini.BLN_VERSEMENT_INITIAL=1 )
           WHERE TYPE_VERSEMENT.ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT 
           
          
          -- R‚cup‚ration du Taux de TVA applicable … l'adh‚rent dans les conditions du poste_versement  
          DECLARE @TAU_TVA  as decimal(10,5)  
          SELECT @TAU_TVA = R26.TAU_TVA   
          FROM R26   
           INNER JOIN ADHERENT ON (R26.ID_TYPE_TVA  = ADHERENT.ID_TYPE_TVA)  
           INNER JOIN PERIODE P2 ON datediff(day, isnull(@DATE, getdate()), P2.DAT_DEB_PERIODE) <= 0 AND   
                  datediff(day, isnull(@DATE, getdate()), P2.DAT_FIN_PERIODE) >= 0 AND   
                  P2.ID_TYPE_PERIODE = 2 AND   
                  R26.ID_PERIODE  = P2.ID_PERIODE  
          WHERE ADHERENT.ID_ADHERENT = @ID_ADHERENT  
          SET @TAU_TVA = isnull(@TAU_TVA, 0)   
           
          
           -- On r‚cupŠre l'option du groupe
          declare @ID_OPTION int  
          set @ID_OPTION = null  
          select @ID_OPTION = R20BIS.ID_OPTION  
          from R20BIS    
          where R20BIS.ID_GROUPE = @ID_GROUPE_DE_ETABLISSEMENT   
            AND R20BIS.ID_PERIODE = @ID_PERIODE 
          
          
         select   
           @ID_ADHERENT    as ID_ADHERENT,  
           @ID_PERIODE     as ID_PERIODE,  
           @ID_OPTION     as ID_OPTION,  
           imputation.COD_PERIODE,  
           imputation.NUM_ANNEE,  
           imputation.ID_ACTIVITE,  
           ACTIVITE.NUM_ORDRE,  
           ACTIVITE.LIBL_ACTIVITE,  
           imputation.MASSE_SALARIALE,  
           imputation.TAU_GLO_APPEL,  
           imputation.PRC_APPELE,  
           100 as PRC_OPTION,  --comme ‡a (100 en dur) avant #1230 le 24/11/2015; impossible … savoir ce que ‡a veut dire
           imputation.PRC_FPSPP,  
           isnull(DEDUCTION.MNT_HT, 0)   as DEDUCTION_EN_COURS_MNT_HT,  
           (isnull(imputation.VERSE_HT, 0)-isnull(POSTE_IMPUTATION.MNT_HT, 0))   
                    as VERSE_HT,  
           POSTE_IMPUTATION.ID_POSTE_IMPUTATION,  
           POSTE_IMPUTATION.ID_POSTE_VERSEMENT,  
           POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE,  
           POSTE_IMPUTATION.DAT_MAJ_CPT_ADH,  
           isnull(POSTE_IMPUTATION.MNT_HT, 0) as IMPUTATION_MNT_HT,  
           isnull(POSTE_IMPUTATION.MNT_TVA, 0) as IMPUTATION_MNT_TVA,  
           isnull(POSTE_IMPUTATION.MNT_TTC, 0) as IMPUTATION_MNT_TTC,  
           imputation.ID_TYPE_TVA,  
           case when (ACTIVITE.COD_ACTIVITE not like 'DSP')  
           then @TAU_TVA   
           else 0 -- collecte AGPP sans TVA  
           end as TAU_TVA,  
           POSTE_VERSEMENT.TIME_STAMP   as POSTE_VERSEMENT_TIME_STAMP,  
           POSTE_IMPUTATION.TIME_STAMP   as POSTE_IMPUTATION_TIME_STAMP,  
           DEDUCTION.TIME_STAMP    as DEDUCTION_TIME_STAMP,  
           ( CASE WHEN @ID_POSTE_VERSEMENT > 0  --- Modification OU Visualisation   
              THEN ISNULL(imputation.DONT_DEJA_REGLE_FPSPP,0) - ISNULL(POSTE_IMPUTATION.DONT_REGLE_FPSPP,0) -- Montant de versement Actual FPSPP   
             ELSE        --- Creation  
              ISNULL(imputation.DONT_DEJA_REGLE_FPSPP,0)  
           END)        AS DONT_DEJA_REGLE_FPSPP,  
           ISNULL(POSTE_IMPUTATION.DONT_REGLE_FPSPP,0)     
                    AS DONT_REGLE_FPSPP,  
           imputation.PRC_FPSPP,  
           imputation.BLN_IMPUTABLE,
           TYPE_ACTIVITE.COD_TYPE_ACTIVITE ActivityType  
           
         from  dbo.GET_ACTIVITES_ADHERENT( @ID_ADHERENT,
                    @ID_PERIODE,
                    @ID_POSTE_VERSEMENT,
                    @ID_TYPE_VERSEMENT,  
                    @ID_TYPE_ASSUJETISSEMENT,  
                    --@MASSE_SALARIALE , 
                    --@MASSE_SALARIALE_CDD,
                    @ID_ETABLISSEMENT_VERSEUR) imputation
           
           LEFT JOIN POSTE_IMPUTATION ON  POSTE_IMPUTATION.ID_ACTIVITE    = imputation.ID_ACTIVITE AND  
                   POSTE_IMPUTATION.ID_POSTE_VERSEMENT   = @ID_POSTE_VERSEMENT  
           LEFT JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT   = POSTE_VERSEMENT.ID_POSTE_VERSEMENT AND   
                   POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT AND   
                   POSTE_VERSEMENT.ID_PERIODE     = @ID_PERIODE  AND   
                   POSTE_VERSEMENT.BLN_ACTIF     = 1   
           LEFT JOIN ADHERENT   ON  ADHERENT.ID_ADHERENT      = POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE  
           LEFT JOIN DEDUCTION   ON DEDUCTION.ID_ADHERENT      = @ID_ADHERENT AND   
                   DEDUCTION.ID_PERIODE      = @ID_PERIODE AND  
                   DEDUCTION.ID_ACTIVITE      = imputation.ID_ACTIVITE  
           INNER JOIN ACTIVITE   ON ACTIVITE.ID_ACTIVITE = imputation.ID_ACTIVITE  
           INNER JOIN TYPE_ACTIVITE ON TYPE_ACTIVITE.ID_TYPE_ACTIVITE = ACTIVITE.ID_TYPE_ACTIVITE   
          ORDER by ACTIVITE.NUM_ORDRE  
           
         END
GO
-- =====================================================================================
         -- Author		: KW
         -- Create date	: 27 novembre 2007
         -- Description	: Mise … jour de bln_en_cours, dat_valid_reglement du reglement pro et
         -- de dat_paiement de la session bap pro reli‚e aux session pro
         -- ---------------------------------------------
         -- Author		: RMA 
         -- Modified date: 10/12/2008
         -- comment		: # Evol.1 210 
         --				  [DAT_BAP] => [DAT_BAP_OF - DAT_BAP_ADH]
         --				  [ID_SESSION_BAP_PRO] => [ID_SESSION_BAP_PRO_OF - ID_SESSION_BAP_PRO_ADH]
         -- ---------------------------------------------
         -- Author		: ASD 
         -- Modified date: 23/04/2009
         -- comment		: # Ano 11932
         --				  Am‚lioration d'une clause OR sur le join de Session_bap_pro 
         --					en marquant de prŠs le critŠre "rŠglement validable"
         --				Afin de ne pas marquer Pay‚e la deuxiŠme Session_bap_pro non concern‚e.
         -- ---------------------------------------------
         -- 22/12/09 par SBR - Optimisation de la proc‚dure: la jointure sur SESSION_BAP_PRO avec clause OR est supprim‚e
         --					  Alimentation de la table #TEMP en 2 requˆtes distinctes et filtre sur les SESSION_BAP_PRO.ID_SESSION_BAP_PRO renseign‚s
         --					  Le temps d'alimentation de #TEMP passe de 30s … <1s
         -- =============================================
         CREATE PROCEDURE [dbo].[UPDATE_REGLEMENT_PRO_VALIDABLE]
         AS
         BEGIN
         
         	CREATE TABLE #TEMP (ID_SESSION_PRO int, ID_SESSION_BAP_PRO int)
         
         	INSERT INTO #TEMP
         	SELECT DISTINCT SESSION_PRO.ID_SESSION_PRO AS ID_SESSION_PRO,
         					SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         	FROM			SESSION_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_ADH ON SESSION_PRO.ID_REGLEMENT_PRO_ADH = REGLEMENT_PRO_ADH.ID_REGLEMENT_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_OF ON SESSION_PRO.ID_REGLEMENT_PRO_OF = REGLEMENT_PRO_OF.ID_REGLEMENT_PRO
         					LEFT JOIN  SESSION_BAP_PRO ON 
         												(
         												SESSION_PRO.ID_SESSION_BAP_PRO_OF = SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         												AND	REGLEMENT_PRO_OF.DAT_VALID_REGLEMENT IS NULL 
         												AND	REGLEMENT_PRO_OF.BLN_EN_COURS = 1 
         												AND	REGLEMENT_PRO_OF.BLN_ACTIF = 1 
         												AND	REGLEMENT_PRO_OF.DAT_EDITION IS NOT NULL
         												)
         	WHERE			SESSION_BAP_PRO.ID_SESSION_BAP_PRO IS NOT NULL
         
         
         	INSERT INTO #TEMP
         	SELECT DISTINCT SESSION_PRO.ID_SESSION_PRO AS ID_SESSION_PRO,
         					SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         	FROM			SESSION_PRO 
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_ADH ON SESSION_PRO.ID_REGLEMENT_PRO_ADH = REGLEMENT_PRO_ADH.ID_REGLEMENT_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_OF ON SESSION_PRO.ID_REGLEMENT_PRO_OF = REGLEMENT_PRO_OF.ID_REGLEMENT_PRO
         					LEFT JOIN  SESSION_BAP_PRO ON
         												(
         												SESSION_PRO.ID_SESSION_BAP_PRO_ADH = SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         											    AND REGLEMENT_PRO_ADH.DAT_VALID_REGLEMENT IS NULL 
         											    AND REGLEMENT_PRO_ADH.BLN_EN_COURS = 1 
         											    AND REGLEMENT_PRO_ADH.BLN_ACTIF = 1 
         											    AND REGLEMENT_PRO_ADH.DAT_EDITION IS NOT NULL
         												)
         	WHERE			SESSION_BAP_PRO.ID_SESSION_BAP_PRO IS NOT NULL
         	AND				NOT EXISTS (SELECT 1 FROM #TEMP WHERE #TEMP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND #TEMP.ID_SESSION_BAP_PRO = SESSION_BAP_PRO.ID_SESSION_BAP_PRO)
         
         
         	UPDATE	REGLEMENT_PRO 
         	SET		REGLEMENT_PRO.DAT_VALID_REGLEMENT = GETDATE(),
         			REGLEMENT_PRO.BLN_EN_COURS = 0
         	WHERE		REGLEMENT_PRO.DAT_VALID_REGLEMENT IS NULL 
         						AND	REGLEMENT_PRO.BLN_EN_COURS = 1 
         						AND	REGLEMENT_PRO.BLN_ACTIF = 1 
         						AND	REGLEMENT_PRO.DAT_EDITION IS NOT NULL
         
         	UPDATE	SESSION_BAP_PRO
         	SET		SESSION_BAP_PRO.DAT_PAIEMENT  = GETDATE()
         	WHERE	SESSION_BAP_PRO.ID_SESSION_BAP_PRO  IN (SELECT DISTINCT ID_SESSION_BAP_PRO FROM #TEMP)
         
         
         	UPDATE REGLEMENT_PRO
         	SET	   REGLEMENT_PRO.BLN_EN_COURS = 0
         	WHERE  REGLEMENT_PRO.ID_REGLEMENT_PRO IN (
         				SELECT DISTINCT REGLEMENT_PRO.ID_REGLEMENT_PRO
         				FROM			REGLEMENT_PRO
         				WHERE		REGLEMENT_PRO.DAT_VALID_REGLEMENT IS NULL 
         						AND	REGLEMENT_PRO.BLN_EN_COURS = 1 
         						AND	REGLEMENT_PRO.BLN_ACTIF = 0
         						AND	REGLEMENT_PRO.DAT_EDITION IS NOT NULL 
         	)
         
         END
         
GO

         
         
         

