 -- =============================================  
         -- Author    : EOU  
         -- Modification date : 14 09 2012  
         -- Description   : 13909  
         -- =============================================  
         -- DSZ 12/10/2012   
         -- Gestion de prelevement collecte deplac‚ ici de INS_LOT_REMISE_BANCAIRE  
         -- =============================================  
         -- EOU 12/10/2012   
         -- 14085  
         -- =============================================  
         -- DSZ 13/10/2012  
         -- 14108 :  montant FMS calcul‚ sur versements plan VO et VV   
         -- =============================================  
         -- DSZ 07/11/2012  
         -- 14256 : le prelevement collecte ne doit pas ˆtre cr‚e qu'au moment de la remise bancaire  
         -- =============================================  
         -- DSZ 22/11/2012  
         -- 14041 : ajout des transferts conventionnels, pour la remise bancaire  
         -- =============================================  
         -- 07/02/13 LDE  
         -- 14822: [AGPP] : 8 : AGPP fonctionnel en descente en compta, ETEBAC et virements internes (-> en prod le 28/2)  
         -- Remplacement de != 3 pour d‚tecter le plan  
         -- =============================================  
         -- DSZ 10/04/2013  
         -- 15120 calcul de montant de versement ne prend pas en compte les FPSPP  
         -- =============================================  
         -- OPA 31/05/2013 : 15031 : SBR - suppression du type FLOAT et REAL dans le SQL : 2- FLOAT  
         -- =============================================  
         -- MBL 12/11/2013 : Les versements inactifs associes au bordereau ne doivent pas etre pris en compte
         -- =============================================   
         -- DSZ 12/12/2013 : 16551: R‚server aux p‚riodes 2012 et ant‚rieures les transferts conventionnels
         -- =============================================   
         -- MBL 17/12/2013 : Suppression Appel a la creation des transferts FMS et des transferts conventionnels
         -- =============================================   
         CREATE PROCEDURE dbo.UPD_BORDEREAU  
         	@ID_BORDEREAU			INT,
         	@ID_LOT_REMISE_BANCAIRE INT,
         	@COD_BORDEREAU			INT,
         	@DAT_EDIT_BORDEREAU		DATETIME,
         	@DAT_COMPTA_BORDEREAU	DATETIME,
         	@BLN_VALIDATION			TINYINT,
         	@TIME_STAMP				TIMESTAMP,
         	@ID_UTILISATEUR			INT
         AS
         BEGIN
         	UPDATE
         		BORDEREAU
         	SET
         		ID_LOT_REMISE_BANCAIRE = @ID_LOT_REMISE_BANCAIRE,
         		COD_BORDEREAU   = @COD_BORDEREAU,
         		DAT_EDIT_BORDEREAU  = @DAT_EDIT_BORDEREAU,
         		DAT_COMPTA_BORDEREAU = @DAT_COMPTA_BORDEREAU,
         		BLN_VALIDATION   = @BLN_VALIDATION,
         		ID_UTILISATEUR   = @ID_UTILISATEUR
         	FROM
         		BORDEREAU
         	WHERE
         		ID_BORDEREAU  = @ID_BORDEREAU
         		AND TIME_STAMP = @TIME_STAMP
         	
         	IF @@ROWCOUNT = 0
         		BEGIN
         			IF EXISTS(SELECT * FROM BORDEREAU WHERE ID_BORDEREAU  = @ID_BORDEREAU)
         				BEGIN
         					/*===============================
         					 ProblŠme de Concurrence d'accŠs 
         					===============================*/
         					RAISERROR(50001, 16, 1)
         				END
         			ELSE
         				BEGIN
         					/*==============================
         					 L'enregistrement a ‚t‚ d‚truit 
         					==============================*/
         					RAISERROR(50002, 16, 1)
         				END
         		END
         
         	--Si c'est la remise en banque  
         	IF @ID_LOT_REMISE_BANCAIRE IS NOT NULL
         		BEGIN
         			--transfert FMS pour les groupes des versements tous types concern‚s par le bordereau   
         			DECLARE
         				@ID_GROUPE INT,
         				@ID_PERIODE INT,
         				@ID_AUTORISATION_PRELEVEMENT INT,
         				@ID_ACTIVITE INT,
         				@MNT_PRELEVEMENT DECIMAL(9, 2),
         				@REF_EXTRANET VARCHAR(20),
         				@ID_VERSEMENT INT,
         				@N INT
         
         			-- MBL 17/12/2013 : Suppression Appel a la creation des transferts FMS 
         			--  DECLARE curs_groupes CURSOR FOR  
         			--  SELECT distinct   
         			--   etablissement.id_groupe,   
         			--   POSTE_VERSEMENT.id_periode  
         			--  from versement  
         			--  INNER JOIN POSTE_VERSEMENT ON POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT   
         			--  inner join etablissement on (etablissement.id_etablissement = POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE)  
         			--  where VERSEMENT.ID_BORDEREAU   = @ID_BORDEREAU  
         			---- MBL 12/11/2013 : Les versements inactifs associes au bordereau ne doivent pas etre pris en compte
         			--  and VERSEMENT.BLN_ACTIF = 1
         			--  OPEN curs_groupes  
         			--  FETCH NEXT FROM curs_groupes  
         			--  INTO @id_groupe, @id_periode  
         			--  WHILE @@FETCH_STATUS = 0  
         			--  BEGIN  
         			--   exec INS_TRANSFERT_FMS @id_groupe, @id_periode, @ID_UTILISATEUR  
         			--   FETCH NEXT FROM curs_groupes INTO @id_groupe, @id_periode  
         			--  END  
         			--  CLOSE curs_groupes  
         			--  DEALLOCATE curs_groupes  
         			--fin FMS   
         			-- MBL 17/12/2013 : Suppression Appel a la creation des transferts FMS et des transferts conventionnels
         			--transfert conventionnel pour les etablissements beneficiaires des versements volontaires plan concern‚s par le bordereau   
         			--declare @id_etab int  
         			--declare @mnt decimal(18,2)  
         			--DECLARE curs_etabs_vv CURSOR FOR  
         			--SELECT    
         			-- POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,   
         			-- POSTE_VERSEMENT.ID_PERIODE,   
         			-- sum(POSTE_IMPUTATION.MNT_HT - POSTE_IMPUTATION.DONT_REGLE_FPSPP)  
         			--from VERSEMENT  
         			--INNER JOIN POSTE_VERSEMENT ON POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT   
         			--inner join POSTE_IMPUTATION on (poste_imputation.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT  
         			--        and id_activite in (SELECT ID_ACTIVITE FROM GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN'))) -- LDE 07/02/2013 #14822  
         			--where VERSEMENT.ID_BORDEREAU   = @ID_BORDEREAU  
         			--group by   
         			-- POSTE_IMPUTATION.ID_ACTIVITE,  
         			-- POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,  
         			-- POSTE_VERSEMENT.ID_PERIODE  
         			--OPEN curs_etabs_vv  
         			--FETCH NEXT FROM curs_etabs_vv  
         			--INTO @id_etab, @id_periode, @mnt  
         			--WHILE @@FETCH_STATUS = 0  
         			--BEGIN  
         			-- exec CREER_TRANSFERT_CONVENTIONNEL @id_etab, @mnt, @id_periode,  @ID_UTILISATEUR  
         			-- FETCH NEXT FROM curs_etabs_vv INTO @id_etab, @id_periode, @mnt  
         			--END  
         			--CLOSE curs_etabs_vv  
         			--DEALLOCATE curs_etabs_vv  
         			----fin FMS  
         			--gestion de prelevement collecte  
         			
         			DECLARE DB_CURSOR CURSOR
         				FOR
         					SELECT
         						ID_ACTIVITE,
         						sum(MNT_TTC),
         						VERSEMENT.REF_EXTRANET,
         						ID_AUTORISATION_PRELEVEMENT,
         						VERSEMENT.ID_VERSEMENT
         					FROM
         						POSTE_IMPUTATION
         						INNER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         						INNER JOIN VERSEMENT ON POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         						INNER JOIN AUTORISATION_PRELEVEMENT ON VERSEMENT.ID_ETABLISSEMENT_EMETTEUR = AUTORISATION_PRELEVEMENT.ID_ETABLISSEMENT
         					WHERE
         						VERSEMENT.ID_BORDEREAU = @ID_BORDEREAU
         						AND POSTE_IMPUTATION.MNT_TTC > 0
         						AND AUTORISATION_PRELEVEMENT.DAT_VALIDATION IS NOT NULL
         						AND AUTORISATION_PRELEVEMENT.DAT_ANNULATION IS  NULL
         						AND ID_MODE_VERSEMENT = 4
         						-- MBL 12/11/2013 : Les versements inactifs associes au bordereau ne doivent pas etre pris en compte
         						AND VERSEMENT.BLN_ACTIF = 1
         					GROUP BY
         						ID_ACTIVITE,
         						VERSEMENT.REF_EXTRANET,
         						ID_AUTORISATION_PRELEVEMENT,
         						VERSEMENT.ID_VERSEMENT
         			OPEN DB_CURSOR
         			FETCH NEXT FROM DB_CURSOR 
         			INTO
         				@ID_ACTIVITE,
         				@MNT_PRELEVEMENT,
         				@REF_EXTRANET,
         				@ID_AUTORISATION_PRELEVEMENT,
         				@ID_VERSEMENT
         			
         			WHILE @@FETCH_STATUS = 0
         				BEGIN
         					SET @N = charindex('_', @REF_EXTRANET)
         					IF @N > 1
         						BEGIN
         							SET @REF_EXTRANET = left (@REF_EXTRANET, @N-1)
         						END
         					EXEC dbo.INS_PRELEVEMENT_COLLECTE @ID_VERSEMENT, NULL, @ID_ACTIVITE, @MNT_PRELEVEMENT, @ID_AUTORISATION_PRELEVEMENT, @REF_EXTRANET
         					FETCH NEXT FROM DB_CURSOR INTO @ID_ACTIVITE, @MNT_PRELEVEMENT, @REF_EXTRANET, @ID_AUTORISATION_PRELEVEMENT, @ID_VERSEMENT
         				END
         				
         			CLOSE DB_CURSOR
         			DEALLOCATE  DB_CURSOR
         		END --fin de la remise en banque (/if @ID_LOT_REMISE_BANCAIRE is not null)
         END
GO
 -- =============================================
         -- Author:		xxx
         -- Create date: xx xxx 2007
         -- Description:	update/insert des motifs non conf. piŠce pour un module ou une session
         -- ---------------------------------------------
         -- Author:		SAY
         -- Modif. date: 20 juin 2007
         -- Description:	ajout pr la prise en charge de la session
         -- =============================================
         CREATE PROCEDURE [dbo].[UPD_MOTIF_NON_CONFORM_PIECE]  
         	@ID_PIECE_PEC	int,
         	@ID_ADHERENT	int,
         	@ID_MODULE		int,
         	@ID_MOTIF		int,
         	@BLN_ACTIF		int,
         	@ID_SESSION		int
         AS  
         
         	IF @ID_ADHERENT = -1
         	BEGIN
         		SET @ID_ADHERENT = NULL
         	END
         
         	DECLARE @ID_ARRIVEE_PIECE_PEC INT
         	DECLARE @DAT_ARRIVEE DATETIME
         	DECLARE @NUMREG INT
         
         	SELECT 
         		@ID_ARRIVEE_PIECE_PEC	= ID_ARRIVEE_PIECE_PEC, 
         		@DAT_ARRIVEE			= DAT_ARRIVEE_PIECE_PEC
         	FROM ARRIVEE_PIECE_PEC
         	WHERE 
         		ID_PIECE_PEC	= @ID_PIECE_PEC AND
         		ID_MODULE_PEC	= @ID_MODULE	AND
         		(
         			(@ID_SESSION is null		AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC is null) OR 
         			(@ID_SESSION is not null	AND ARRIVEE_PIECE_PEC.ID_SESSION_PEC = @ID_SESSION)
         		)								AND 
         		(ID_ADHERENT	= @ID_ADHERENT OR @ID_ADHERENT IS NULL)
         	
         	IF @BLN_ACTIF IS NULL
         	BEGIN
         		SET @BLN_ACTIF = 0
         	END
         
         	SELECT @NUMREG = COUNT(*) 
         		FROM NR210
         		WHERE 
         			ID_MOTIF_NON_CONFORM_PIECE	= @ID_MOTIF AND 
         			ID_ARRIVEE_PIECE_PEC		= @ID_ARRIVEE_PIECE_PEC
         
         	IF @NUMREG = 0
         	BEGIN
         		IF @BLN_ACTIF = 1
         		BEGIN
         			INSERT INTO NR210 
         				(ID_MOTIF_NON_CONFORM_PIECE, ID_ARRIVEE_PIECE_PEC)
         			VALUES 
         				(@ID_MOTIF, @ID_ARRIVEE_PIECE_PEC)
         		END
         	END
         	ELSE
         	BEGIN
         		IF @BLN_ACTIF = 0
         		BEGIN
         			DELETE FROM NR210 
         			WHERE 
         				ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC AND 
         				ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         		END
         
         		IF (@DAT_ARRIVEE IS NULL)
         		BEGIN
         			DELETE FROM NR210 
         			WHERE 
         				ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE_PEC AND 
         				ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         		END
         	END
         
         
GO
