-- Auteur		: SBR
-- Date			: 05/07/2012
-- Description	: Traitement d'un fichier EDI
--				  Le fichier a ‚t‚ pr‚alablement charg‚ dans la table EDI_TAMPON
-- ParamŠtres	: @nom_fichier_chemin = nom du fichier avec chemin complet
--				  Le nom du fichier doit respecter la nomenclature: COD_TABLE-SIRET.ext o— COD_TABLE est la valeur du champ EDI_IMPORT_TABLE.COD_TABLE
----------------------------------------------
-- Auteur		: EOU
-- Date			: 25/02/2013
--              : Le nom du fichier doit respecter la nomenclature: COD_TABLE-SIRET.ext o— COD_TABLE est la valeur du champ EDI_IMPORT_TABLE.COD_TABLE
-- Description	: 14671
----------------------------------------------
-- EOU 06/06/2013 : 15275 : changement ID_UTILISATEUR ADMIN par celui de EDI
         ---------------------------------------------- 
CREATE PROCEDURE [dbo].[EDI_TRAITE_FICHIER]
		@nom_fichier_chemin varchar(200)
AS

SET NOCOUNT ON

-- variables
         declare @cod_table varchar(10),
         		@nom_fichier varchar(100),
         		@num_ligne int,
         		@data varchar(8000),
         		@ID_ADHERENT int, 
         		@ID_TABLE int,
         		@BLN_FORMAT_FIXE int, 
         		@COD_ASCII_SEPARATEUR int,
         		@SEPARATEUR char(1), 
         		@COD_TABLE_TAMPON varchar(50), 
         		@NOM_PROC_STOCKEE varchar(50),
         		@NB_CHAMPS smallint,
         		@NB_OCCUR smallint,
         		@ID_LOT_IMPORT int,
         		@res tinyint,
         		@cmd varchar(2000)
         
         select	@nom_fichier = REVERSE(dbo.GetDelimData(REVERSE(@nom_fichier_chemin), 1, '\', 'N'))
         select	@cod_table = dbo.GetDelimData(@nom_fichier, 1, '-', 'N')
         
         -- Activer pour initialisation en masse
         --if @nom_fichier not like 'EDI_SAL_ST%'
         --begin
         --	set @cod_table = 'EDI_SAL_ST'
         --	set @nom_fichier = (select top 1 'EDI_SAL_ST-' + dbo.GetDelimData(data, 12, ';', 'N')+dbo.GetDelimData(data, 13, ';', 'N') +'.csv' from EDI_TAMPON)
         --end
         
         select	@ID_TABLE = ID_TABLE,
         		@BLN_FORMAT_FIXE = BLN_FORMAT_FIXE,
         		@COD_ASCII_SEPARATEUR = COD_ASCII_SEPARATEUR,
         		@SEPARATEUR = CHAR(COD_ASCII_SEPARATEUR), 
         		@COD_TABLE_TAMPON =COD_TABLE_TAMPON, 
         		@NOM_PROC_STOCKEE = NOM_PROC_STOCKEE
         from	EDI_IMPORT_TABLE
         where	COD_TABLE = @cod_table
         
         if @@ROWCOUNT = 0 GOTO ERR_COD_TABLE
         
         -- Le format du fichier est-il correcte (bon nombre de champ si format variable ou bonne longueur si format fixe)?
         if @BLN_FORMAT_FIXE = 0
         begin
         	select	@NB_CHAMPS = COUNT(*)
         	from	EDI_IMPORT_COLONNE
         	where	ID_TABLE = @ID_TABLE
         
         	select	@NB_OCCUR = dbo.GetNbOccur(data, @SEPARATEUR)
         	from	EDI_TAMPON
         	
         	if @NB_OCCUR <> @NB_CHAMPS-1 GOTO ERR_FORMAT
         end
         
         -- r‚cup‚ration de l'adh‚rent concern‚
         select	@ID_ADHERENT = ID_ADHERENT
         from	ADHERENT
         where	NUM_SIREN =	left(dbo.GetDelimData(@nom_fichier, 2, '-', 'N'), 9)
         
         if @ID_ADHERENT IS NULL GOTO ERR_ADH
         
         
         -- Cr‚ation d'un lot EDI
         exec @ID_LOT_IMPORT = INS_EDI_LOT_IMPORT @ID_ADHERENT,NULL,@ID_TABLE,@BLN_FORMAT_FIXE,@COD_ASCII_SEPARATEUR,@COD_TABLE_TAMPON,@nom_fichier_chemin,80 --utilisateur EDI
         
         -- Parcours du fichier et alimentation de la table tampon EDI_SAL_ST
         declare lecture_fichier cursor for
         select	data
         from	edi_tampon
         
         open lecture_fichier
         fetch next from lecture_fichier into @data
         
         set @num_ligne = 0
         
         while @@FETCH_STATUS = 0
         BEGIN
         	set @num_ligne = @num_ligne + 1
         	set @data = REPLACE(@data, '''', '''''') -- gestion des ‚ventuels simples quotes dans la chaine
         
         	-- trace pour debug
         	-- select 'EDI_TRAITE_LIGNE '+cast(@ID_LOT_IMPORT as varchar)+', '+cast(@num_ligne as varchar)+', '+@data
         	-- traitement de la ligne: validit‚ de la ligne et alimentation de la table de travail
         	exec @res = EDI_TRAITE_LIGNE @ID_LOT_IMPORT, @num_ligne, @data
         	
         	fetch next from lecture_fichier into @data
         END
         
         close lecture_fichier
         deallocate lecture_fichier
         
         -- trace pour debug
         -- select 'EXEC ' + @NOM_PROC_STOCKEE + ' ' + CAST(@ID_LOT_IMPORT as varchar) + ', null, null'
         
         -- execution de la proc‚dure stock‚ de traitement des lignes valides (… partir de la table de travail aliment‚e dans la proc‚dure EDI_TRAITE_LIGNE)
         -- format NOM_PROC_STOCKEE @ID_LOT_IMPORT, @NUM_LIGNE_DEBUT, @NUM_LIGNE_FIN
         set @cmd = 'EXEC ' + @NOM_PROC_STOCKEE + ' ' + CAST(@ID_LOT_IMPORT as varchar) + ', null, null'
         EXEC (@cmd)
         
         
         -- Retour pour g‚n‚ration du fichier de log
         declare @nb_enr_file int, 
         		@nb_enr_ok int, 
         		@nb_enr_ko int
         
         -- nombre d'enregistrements dans le fichier
         select	@nb_enr_file = COUNT(*) 
         from	dbo.EDI_TAMPON
         
         -- nombre d'enregistrements trait‚s avec succ‚s
         if(@cod_table = 'EDI_SAL_ST')
         BEGIN
         select	@nb_enr_ok = COUNT(*) 
         from	dbo.EDI_SAL_ST
         where	ID_LOT_IMPORT = @id_lot_import
         and		BLN_REJET = 0
         END
         ELSE IF(@cod_table = 'EDI_PAR_ST')
         BEGIN
         select	@nb_enr_ok = COUNT(*) 
         from	dbo.EDI_PAR_ST
         where	ID_LOT_IMPORT = @id_lot_import
         and		BLN_REJET = 0
         END
         -- nombre d'enregistrements rejet‚s
         select	@nb_enr_ko =  COUNT(distinct NUM_LIGNE )
         from	dbo.EDI_LOG
         where	ID_LOT_IMPORT = @id_lot_import
         
         if(@nb_enr_ok <> @nb_enr_file - @nb_enr_ko and @cod_table = 'EDI_PAR_ST')
         BEGIN
         	set @nb_enr_ok = @nb_enr_file - @nb_enr_ko
         END
         -- lignes du fichier de log
         select	T.LIB
         from	(
         		select	0 as NUM_LIGNE, convert(varchar, getdate(), 103) + ' - Traitement du fichier ' + @nom_fichier_chemin + CHAR(13) + CHAR(10) +
         				cast(@nb_enr_file as varchar) + ' lignes d‚tect‚es dans le fichier' + CHAR(13) + CHAR(10) +
         				cast(@nb_enr_ok as varchar)  + ' lignes trait‚es avec succ‚s' + CHAR(13) + CHAR(10) +
         				cast(@nb_enr_ko as varchar) + ' lignes rejet‚es' + CHAR(13) + CHAR(10) as LIB
         
         		UNION
         
         		select	t1.NUM_LIGNE, ('Ligne '+cast(t1.NUM_LIGNE as varchar) + ' - ' + t1.LIB_PROBLEME) AS LIB
         		from	dbo.EDI_LOG t1
         		join	dbo.EDI_LOT_IMPORT t2
         		on		t1.ID_LOT_IMPORT = t2.ID_LOT_IMPORT
         		where	t2.NOM_FICHIER = @nom_fichier_chemin
         		and		t2.ID_LOT_IMPORT = @id_lot_import
         		) T
         
         order by T.NUM_LIGNE
         
         -- suppression des donn‚es de la table de travail
         set @cmd = 'DELETE ' + @COD_TABLE_TAMPON + ' WHERE ID_LOT_IMPORT = ' + CAST(@ID_LOT_IMPORT as varchar)
         EXEC (@cmd)
         
         
         RETURN 0
         
         ERR_COD_TABLE:
         /* Nom fichier non valide */
         select @nom_fichier + ': Nom de fichier non reconnu.'
         RETURN -1
         
         ERR_FORMAT:
         /* Format fichier non valide */
         select @nom_fichier + ': Format de fichier non valide. Le fichier doit comporter '+ CAST(@NB_CHAMPS as varchar) + ' champs et utiliser comme s‚parateur le ' + @SEPARATEUR
         RETURN -1
         
         ERR_ADH:
         /* adh‚rent inconnu */
         select @nom_fichier + ': Adh‚rent non trouv‚ pour le SIREN '+ left(dbo.GetDelimData(@nom_fichier, 2, '-', 'N'), 9)
         RETURN -1
         
GO
 CREATE PROCEDURE [dbo].[GetActiviteAdherent] 
         
         	@ID_ADHERENT int, 
         	@ID_PERIODE int,
         	@ID_ACTIVITE int output 
         AS
         -- =============================================
         -- Author:		DSZ
         -- Create date: 20/12/2011
         -- Description:	13040 : Get Activite Plan de Adherent, pour la creation du stagiaire
         -- par d‚faut 10-49 : 4
         ------------------------------------------------------------
         -- ASD 07/01/2013 14822 : remplacer la condition !=3 par cod_type_activite = plan 
         -- =============================================
         -- EOU Ajout OutPut Parametre ID_ACTIVITE
         -- =============================================
         BEGIN
         	SET NOCOUNT ON;
         	declare @ID_ACTIVITE_LOCAL int
             select @ID_ACTIVITE_LOCAL = R19.ID_ACTIVITE
         	from R19 
         	where
         	R19.ID_ACTIVITE in (select id_activite from GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN'))
         	AND R19.ID_ADHERENT = @ID_ADHERENT AND 
         		R19.ID_PERIODE = @ID_PERIODE  
         	set @ID_ACTIVITE = @ID_ACTIVITE_LOCAL
         	return isnull(@ID_ACTIVITE_LOCAL,4)
         END
GO

         
         
         CREATE PROCEDURE [dbo].[UPD_DATE_LETTRE_RELANCE_REGLEMENT_ADH]
         	@CODS_SESSION_PEC TEXT	-- List of ID_MODULE separated with ',' without spaces - i.e.: 1,2,3,4,5,6
         AS
         
         BEGIN
         
         	DECLARE @Item VARCHAR(17);
         	-- Create a temporary table which contains IDs
         	CREATE TABLE #List(Item VARCHAR(17)  collate French_CI_AI)
         	
         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@CODS_SESSION_PEC,1,CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0)-1))),
         			@CODS_SESSION_PEC=RTRIM(LTRIM(SUBSTRING(@CODS_SESSION_PEC,CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0)+1,DATALENGTH(@CODS_SESSION_PEC))))
         
         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END
         
         	IF DATALENGTH(@CODS_SESSION_PEC) > 0
         		INSERT INTO #List SELECT @CODS_SESSION_PEC
         
         	
         SELECT  DISTINCT MODULE_PEC.ID_MODULE_PEC,
         				 SESSION_PEC.ID_SESSION_PEC,
         				 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         				 POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE,
         				 STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         				 ETABLISSEMENT.ID_ETABLISSEMENT,
         				 ADHERENT.ID_ADHERENT 
         
         INTO	#TEMP_SESSIONS
         
         FROM	MODULE_PEC
         		INNER JOIN SESSION_PEC ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC 
         		INNER JOIN POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		INNER JOIN STAGIAIRE_PEC ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         		INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         		INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         
         WHERE		(MODULE_PEC.BLN_ACTIF = 1)
         		AND (SESSION_PEC.BLN_ACTIF = 1)
         		AND (POSTE_COUT_REGLE.BLN_ACTIF = 1)
         		AND ((MODULE_PEC.BLN_OK_PIECE = 0) OR (POSTE_COUT_REGLE.BLN_OK_PIECE = 0))
         		AND (SESSION_PEC.COD_SESSION_PEC   in (SELECT Item FROM #List))
         
         
         --Selection des pieces a mettre … jour apres la premiere relance----------------------------------------
         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	INTO	#TEMP_RELANCE_1					 
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC										
         			INNER JOIN ADHERENT ON #TEMP_SESSIONS.ID_ADHERENT = ADHERENT.ID_ADHERENT
         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 0)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION 
         
         
         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC					 
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			--INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC										
         			INNER JOIN ADHERENT ON #TEMP_SESSIONS.ID_ADHERENT = ADHERENT.ID_ADHERENT
         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (PIECE_PEC.BLN_SESSION = 1)
